insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('763ecd4e-c440-5076-904b-71dc0d2d3f74', 'Cross Dress', NULL, NULL, 'Hiromi lernt Louis während des städtischen Karnevalsumzugs kennen und ist gleich Feuer und Flamme für den stattlichen "Vampir". Louis scheint auch ganz entzückt von der kleinen Japanerin im Kimono zu sein. Was er nicht ahnt: Hiromi heißt mit zweiten Namen Paul.', NULL, NULL, ARRAY['Deutsch']::text[], 75, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hiromi','Louis']::text[], ARRAY['Queer']::text[], '{}', '317ad5ef-a56b-5880-8009-11a174dee181', '1', '{}', 'sheet', :'owner') on conflict do nothing;
