insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('484b69a7-aa13-5622-a02c-1ecde1e8a1e1', 'Cross Dress 2', NULL, NULL, 'Hiromi und Louis sind bereits zwei Jahre zusammen und haben immer noch nicht die Herausforderungen ihres ungewöhnlichen Beziehungstarts ganz gemeistert. Hiromi ist verzweifelt, denn er hat das Gefühl zu stagnieren und immer ist es Louis, der sie in ihrer Entwicklung bremst. Doch Hiromi will mehr.', NULL, NULL, ARRAY['Deutsch']::text[], 71, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hiromi','Louis']::text[], ARRAY['Queer']::text[], '{}', '317ad5ef-a56b-5880-8009-11a174dee181', '2', '{}', 'sheet', :'owner') on conflict do nothing;
