insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3ab3cfc4-b735-5f39-a70f-b98ce9f9d8c1', 'Shanghai Immortal', NULL, '9781399720854', 'Pawned by her mother to the King of Hell as a child, Lady Jing is half-vampire, half-hulijing fox-spirit and all sasshole. As the King''s ward, she has spent the past ninety years running errands, dodging the taunts of the spiteful hulijing courtiers, and trying to control her explosive temper - with varying levels of success. So when Jing overhears the courtiers plotting to steal a priceless dragon pearl from the King, she seizes her chance to expose them, once and for all. With the help of a gentle mortal tasked with setting up the Central Bank of Hell, Jing embarks on a wild chase for intel, first through Hell and then mortal Shanghai. But when her hijinks put the mortal in danger, she must decide which is more important: avenging her loss of face, or letting go of her half-empty approach to life for a chance to experience tenderness - and maybe even love.', '01.06.2023', 'Fairyloot', ARRAY['Englisch']::text[], 346, 31, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, NULL, 'Shanghai', '{}', ARRAY['Jing']::text[], ARRAY['Asia Mythology']::text[], '{}', '9f96ba41-c582-5a19-87c8-485dfb0505b4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
