insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5e296488-3bce-5e06-aa80-35f6a25185bd', 'Follow Me Back', NULL, '9783736309975', 'Tessa Hart fürchtet sich davor, ihr Zimmer zu verlassen. Ihr einziger Kontakt zur Außenwelt ist ihr Twitter-Account @TessaHeartsEric, auf dem sie sich mit anderen Fans über ihre Liebe zu dem Popstar Eric Thorn austauscht. Was sie nicht ahnt: Der Sänger ist eine der Personen, mit denen sie sich regelmäßig Privatnachrichten schreibt! Eric weiß, dass er Tessa die Wahrheit sagen muss, zumal die junge Frau mit jedem Tag tiefere Gefühle in ihm weckt. Doch als die beiden sich für ihr erstes Treffen verabreden, nimmt plötzlich alles eine gefährliche Wendung ...', '30.09.2019', 'LYX', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Romantic Suspense']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa Hart','Eric Thorn']::text[], ARRAY['Famous Person','Mental Issues','Secred Identity']::text[], '{}', '7d0df2d6-e39c-51d9-b80b-1326ecfc9a7e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
