insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cd32bb28-feeb-54d6-adcf-514738c77d1f', 'Tell Me No Lies', NULL, '9783736310469', 'Wo ist Eric Thorn? Ist er am Leben? Tessa Hart ist die Einzige, die die Wahrheit kennt. Aber sie hat beschlossen, ihre Eric-Thorn-Fangirl-Zeiten ein für alle Mal hinter sich zu lassen - und nie wieder in die Nähe einer Twitter-App zu kommen. Denn auch wenn sie sich inzwischen traut, ihr Zimmer zu verlassen, so fürchtet sie sich noch immer vor der Vergangenheit. Doch genau dieser muss sich Tessa früher stellen als gedacht ...', '27.11.2019', 'LYX', ARRAY['Deutsch']::text[], 333, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Romantic Suspense']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa Hart','Eric Thorn']::text[], ARRAY['Famous Person','Mental Issues','Secred Identity']::text[], '{}', '7d0df2d6-e39c-51d9-b80b-1326ecfc9a7e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
