insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57aeb026-8a24-5df3-9f55-d5409227ad79', 'Rush of Love - Verführt', 'Fallen too far', '9783492964012', 'Nach dem Tod der Mutter verlässt Blaire ihr Zuhause, um bei ihrem Vater und dessen neuer Familie in einem luxuriösen Strandhaus zu leben. Vor allem ihr attraktiver Stiefbruder Rush lässt sie jedoch immer wieder spüren, dass sie nicht willkommen ist. Er ist so abweisend wie anziehend, so verletzend wie faszinierend, er ist verwirrend und unwiderstehlich – und er kennt ein Geheimnis, das Blaires Herz mit einem Schlag für immer brechen könnte.', '14.05.2013', 'Piper', ARRAY['Deutsch']::text[], 240, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Blair','Rush Finlay']::text[], ARRAY['Found Family','Step Brother','Bad Boy X Good Girl','Rich vs. Poor','Forbidden Love']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '1', '{}', 'sheet', :'owner') on conflict do nothing;
