insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f52bb493-c858-569c-9b7d-213fe11e21e0', 'Rush of Love - Erlöst', 'Never too far', '9783492964029', 'Blaires Welt bricht mit einem Schlag zusammen. Alles, was sie für wahr hielt, ist nichts als Lüge. Sie weiß, dass sie niemals aufhören wird, Rush zu lieben – sie weiß aber auch, dass sie ihm niemals verzeihen kann. Sie versucht, ihr Leben wieder in den Griff zu bekommen. Ohne ihn. Bis ihre Welt erneut erschüttert wird. Doch was tun, wenn der Mensch, der einen am tiefsten verletzt hat, der Einzige ist, dem man noch vertrauen kann?', '25.06.2013', 'Piper', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Blair','Rush Finlay']::text[], ARRAY['Found Family','Step Brother','Bad Boy X Good Girl','Rich vs. Poor','Forbidden Love']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '2', '{}', 'sheet', :'owner') on conflict do nothing;
