insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4ff99b69-ef34-5918-ac2a-a9b16108600c', 'Rush of Love - Vereint', 'Forever too far', '9783492964616', 'Alles scheint endlich perfekt: Blaire ist mit ihrer großen Liebe Rush verlobt und trägt sein Kind unter ihrem Herzen. Sie hat in Rosemary Beach echte Freunde gefunden und sogar damit begonnen, die verkorkste Beziehung zu ihrem Vater zu kitten. Doch ein erster Schatten fällt auf das Glück der beiden Liebenden, als Rushs Vater auftaucht, um ihn um Hilfe zu bitten, und schon bald ziehen noch dunklere Gewitterwolken auf …', '23.04.2013', 'Piper', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Blair','Rush Finlay']::text[], ARRAY['Found Family','Step Brother','Bad Boy X Good Girl','Rich vs. Poor','Forbidden Love']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '3', '{}', 'sheet', :'owner') on conflict do nothing;
