insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ac4915ed-4843-5588-b67d-89e3e6d3ae06', 'Rush too Far - Erhofft', 'Rush too far', '9783492968058', 'Rush Finlay weiß, dass er in der Hölle landen wird, als er Blaire zum ersten Mal sieht. Sie ist jung, unschuldig und seine Stiefschwester. Doch für den stadtbekannten Bad Boy ist sie vor allem eines: verboten verführerisch. Da sie Hilfe braucht und ihr Vater gerade mit Rushs Mutter in Paris ist, nimmt Rush sie widerstrebend bei sich auf – und versucht, ihr aus dem Weg zu gehen. Doch sein Widerstand droht mit jedem Tag, den Blaire unter seinem Dach wohnt, zu schwinden ...', '15.09.2014', 'Piper', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Blair','Rush Finlay']::text[], ARRAY['Found Family','Step Brother','Bad Boy X Good Girl','Rich vs. Poor','Forbidden Love']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '4', ARRAY['Interquel']::text[], 'sheet', :'owner') on conflict do nothing;
