insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ca564e60-c468-58c7-9f28-7dbfb2870c83', 'Twisted Perfection - Ersehnt', 'Twisted Perfection', '9783492966641', 'Della ist endlich frei. Als sie ins Auto steigt und einfach losfährt, lässt sie nicht nur ihr Elternhaus, sondern auch ihre Vergangenheit hinter sich. Sie will unbeschwert leben und die Welt entdecken. Bei einem Zwischenstopp im sonnigen Rosemary Beach lernt sie an einer Tankstelle den unverschämt charmanten Woods kennen. Doch was für Della als heißer One-Night-Stand beginnt, wird ihr Leben für immer verändern …', '20.01.2014', 'Piper', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Woods','Della Sloane']::text[], ARRAY['Rich vs. Poor','Family Drama']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
