insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c1dce45b-6187-5ce3-8186-d7df44cc22ca', 'Simple Perfection - Erfüllt', 'Simple Perfection', '9783492966658', 'Della will stark für Woods sein, auch wenn sich ihr Leben vor ihren Augen in nichts auflöst. Egal, wie weit sie von zu Hause flieht, die Schatten ihrer Vergangenheit lassen sie nicht los. Sie versucht, ihre tiefen Ängste und wahren Gefühle vor Woods zu verbergen, um ihn zu schützen, denn sie weiß, dass sie ihn sonst mit sich in die dunklen Tiefen reißen wird. Aber ist sie stark genug, den einzigen Menschen loszulassen, der ihr noch Halt gibt?', '17.02.2014', 'Piper', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Woods','Della Sloane']::text[], ARRAY['Found Family','Rich vs. Poor','Family Drama']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '6', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
