insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b43dd1e9-025c-5c06-a3d2-ad798f33cce5', '17ef8b95-6e32-5de1-8769-ec8d1a455947', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c865e30f-9fb7-5a55-a1c6-de64779f6ece', 'Take a Chance - Begehrt', 'Take a Chance', '9783492968379', 'Als Harlow von ihrem Vater nach Rosemary Beach geschickt wird, um bei ihrer Halbschwester Nan zu wohnen, gibt es da gleich zwei Probleme: Zum einen kann Nan sie auf den Tod nicht ausstehen, weshalb Harlow versucht, möglichst keine Aufmerksamkeit auf sich zu ziehen. Zum anderen kommt eines Morgens Grant Carter aus Nans Zimmer. Harlow weiß, dass sie mit diesem verboten attraktiven Playboy nichts zu tun haben will, der sich von ihrer fiesen Halbschwester um den Finger wickeln lässt … allerdings sollte sie dann auch aufhören, ihn so anzustarren.', '10.06.2014', 'Piper', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Grant','Harlow']::text[], ARRAY['Bad Boy X Good Girl','Family Drama','Found Family']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '7', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
