insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57e748d1-bea8-596c-bec2-bbfc93e6b8b1', 'One more Chance - Befreit', 'One more Chance', '9783492968386', 'Grant hat um Harlows Herz gekämpft, und er hat ihr bewiesen, dass sie ihm vertrauen kann. Da er längst nicht mehr der Playboy ist, für den alle ihn halten, hat Harlow sich schließlich auf ihn eingelassen. Sie hat all die neuen Gefühle und Wünschen zugelassen, die er ihn ihr weckt. Beinahe scheint es so, als könnten sie zusammen glücklich werden. Doch obwohl sie Grant vertraut, hat Harlow ein Geheimnis für sich behalten. Ein Geheimnis, das alles für immer verändern könnte und eines Tages alles zerstören wird ...', '11.08.2014', 'Piper', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Grant','Harlow']::text[], ARRAY['Second Chance','Pregnancy','Found Family','Rich vs. Poor']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '8', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
