insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ac2e1ab1-c97a-5a73-87de-87c7a9f3ace2', 'You were Mine - Unvergessen', 'You were Mine', '9783492968232', 'Tripp ist genau dort, wo er nie sein wollte: zurück in Rosemary Beach. Zu viel erinnert ihn hier an seine Vergangenheit, die er hinter sich lassen wollte. Deshalb hat er allem vor langer Zeit den Rücken gekehrt. Aber jetzt ist er zurück, und viel zu oft läuft er Bethy über den Weg, die er ebenfalls nie wieder sehen wollte. Doch mit jedem Tag, den er in Rosemary Beach verbringt, spürt er, dass es ihm schwerer fällt, diesen Ort erneut zu verlassen – ebenso wie Bethy.', '08.12.2014', 'Piper', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Tripp','Bethy']::text[], ARRAY['Second Chance','Tragic Backstory','Redemption']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '9', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
