insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('05d7bb81-e774-5eb5-9a79-6b671acd7d9f', 'When I’m Gone - Verloren', 'When I’m Gone', '9783492969499', 'Mase Colt-Manning ist ein waschechter Cowboy aus Texas. Als er nach Florida aufbricht, um seine Halbschwester Harlow im sonnigen Rosemary Beach zu besuchen, verliert er dabei sein Herz – ausgerechnet an die Frau, vor der ihn alle von Anfang an gewarnt haben.', '08.06.2015', 'Piper', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Reese','Mase Colt-Manning']::text[], ARRAY['Opposites Attract','Found Family','Tragic Backstory']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '11', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
