insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('42f3cb62-1dfc-5c70-be76-c664d943f010', 'When You’re Back - Gefunden', 'When You’re Back', '9783492969505', 'Die Zukunft erscheint rosig für Reese. Sie hat in Mase ihren absoluten Traummann gefunden, und sie freut sich, endlich ihren leiblichen Vater kennenzulernen. Alles wird gut. Doch während sie ihre neue Familie in Chicago besucht, verbringt Mase viel Zeit mit Aida. Als Reese zurückkommt, muss sie bald erkennen, dass Aida mehr für Mase empfindet und um ihn kämpfen wird – und sie hat nicht vor, sich an die Spielregeln zu halten …', '10.08.2015', 'Piper', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Reese','Mase Colt-Manning']::text[], ARRAY['Found Family','Miscommunication']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '12', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
