insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6f4739f9-2475-5a27-bf77-f60ed17203be', 'The Best Goodbye - Ganz nah', 'The Best Goodbye', '9783492971218', 'Die Adoptiveltern von River »Captain« Kipling haben ihn stets spüren lassen, dass sie lieber eine Tochter gehabt hätten und dass er nur die zweite Wahl war. Als eines Tages Addison bei ihnen einzog, war das Familienglück perfekt. Oder zumindest hätte es das sein sollen. Denn schon bald war das junge Mädchen nicht mehr die langersehnte Tochter, sondern nur mehr eine weitere Last für die Eltern. Von diesem Tag an setzte Captain alles daran, Addison zu beschützen. Trotzdem lief sie von zu Hause weg, und nur Captain wusste, warum. Er hat sie danach nicht mehr gesehen. Bis heute.', '01.03.2016', 'Piper', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['River Kipling','Addison']::text[], ARRAY['Opposites Attract','Bad Boy X Good Girl','Found Family','Miscommunication']::text[], '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '13', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
