insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7997bba8-5607-54aa-966c-42b3daa1d660', 'Up in Flames - Entbrannt', 'Up in Flames', '9783492973151', 'Wer liebt, wird verletzt. Immer. Das musste Nan schon früh auf schmerzhafte Weise lernen. Nach außen hin hat sie sich deshalb längst eine harte Schale zugelegt: Sie ist kalt und berechnend, sie provoziert, intrigiert und macht ihren Mitmenschen das Leben zur Hölle. Innerlich ist sie jedoch zerrissen, gebrochen, zutiefst unglücklich. Vor allem aber hat sie es sich verboten, jemals wieder Gefühle für einen anderen Menschen zuzulassen. Doch dann empfindet sie plötzlich trotzdem etwas – und zwar ausgerechnet für den Mann, bei dem sie es am wenigsten erwartet hat.', '01.08.2016', 'Piper', ARRAY['Deutsch']::text[], 282, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Rosemary Beach', '{}', ARRAY['Nan']::text[], '{}', '{}', '06be9cd1-0de8-58d6-9001-efbb5f0059bd', '14', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
