insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d0956324-a263-587a-9d34-becf2237a76d', 'Die Walkinder (Vol.1)', 'Kujira no Kora wa Sajō ni Utau', '9783551711410', 'Eine Welt aus Sand – Die Bewohner des Schlammwals, einer riesigen Schiffsinsel, die über ein endlos weites Sandmeer treibt, können »Saimia« einsetzen. Das sind übernatürliche Fähigkeiten, die sich aus ihren Gefühlen nähren. Der Preis dafür: Die Leben dieser Menschen sind kurz. »Unser kurzes Leben müssen wir auf dem Schlammwal verbringen, einer von der Außenwelt gänzlich abgeschotteten Insel…« Der Junge Chakuro nimmt dieses Schicksal an, bis er eines Tages auf einer angeschwemmten Schiffsruine einem Mädchen begegnet…', '20.03.2018', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, 'Schlammwal', ARRAY['3P Objective']::text[], ARRAY['Chakuro']::text[], ARRAY['Coming-of-Age','Magical Creatures','Epic Quest','Hidden Powers']::text[], '{}', '54e2ecd9-8fc5-55d2-a1ef-c23197db91c6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
