insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17e52b94-53cf-544b-8c5c-9f465eb50bd1', 'Belladonna', NULL, '9781529367263', 'Orphaned as a child, Signa Farrow has been raised by a string of guardians, each more interested in her wealth than her well-being - and each has met an untimely end. Her only remaining relatives are the elusive Hawthornes, an eccentric family living at Thorn Grove, an estate both glittering and gloomy. When a restless spirit appears claiming she was poisoned, Signa realizes the Hawthornes could be in grave danger, and enlists the help of a surly stable boy to hunt down the killer. But Signa''s best chance of uncovering the murderer is an alliance with Death himself. And as the mystery unfurls, Signa realizes their growing connection may be more irresistible than she dared imagine . . .', '22.06.2023', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Academia']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Thorn Grove', '{}', ARRAY['Signa Farrow']::text[], ARRAY['Enemies to Lovers','Forbidden Love']::text[], '{}', '11760bad-b2a4-5416-a2db-33435c06497d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
