insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f5a8b9b0-b915-58b3-a756-0cc71ee3c7c6', 'a480a44c-86a7-5771-83df-5359de49b130', :'owner', 1, '2024-06-18', '2024-06-25', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6ee6770-34f8-5eea-a053-44de4179057f', 'Foxglove', NULL, '9781399705165', 'A duke has been murdered. The lord of Thorn Grove has been framed. And Fate, the elusive brother of Death, has taken up residence in a sumptuous estate nearby. He''s hellbent on revenge after Death took the life of the woman he loved many years ago . . . and now he''s determined to have Signa for himself, no matter the cost. Signa and her cousin Blythe are certain that Fate can save Elijah Hawthorne from prison if they will entertain his presence. But the more time the girls spend with Fate, the more frightening their reality becomes as Signa exhibits dramatic new powers that link her to Fate''s past. With mysteries and danger around every corner, the cousins must decide if they can trust one another as they navigate their futures in high society, unravel the murders that haunt their family, and play Fate''s unexpected games-all with their destinies hanging in the balance.', '25.07.2024', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Academia']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Thorn Grove', '{}', ARRAY['Signa Farrow','Blythe Hawthorn']::text[], ARRAY['Forbidden Love','Love Triangle']::text[], '{}', '11760bad-b2a4-5416-a2db-33435c06497d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
