insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c04c41bc-0360-5a96-b304-bf6d64cce1ff', 'fe2f05bd-57ff-5a4b-a2b9-44ebd6af036f', :'owner', 1, '2024-06-25', '2024-06-29', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('703e601f-96d2-568a-a122-a5844b90b4f9', 'Wisteria', NULL, '9781399726108', 'Blythe Hawthorn has never let anyone tell her what to do . . . and she''s not about to start now. Headstrong and passionate, she won''t be ruled by society, or by her overprotective father, and certainly not by the man she''s bound herself to, no matter how insufferable he is. She''s determined to be a thorn in his side for the rest of her days, even as he ensues that her life in his palace is anything but the decadent fairytale she imagined. But as Blythe discovers a new side of herself linked to his past, she''ll have to decide if she''s willing to let an unexpected spark ignite . . . and discover the real truth about who she is inside.', '12.06.2025', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 419, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Academia']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Thorn Grove', ARRAY['Double POV','2P']::text[], ARRAY['Signa Farrow','Blythe Hawthorn']::text[], ARRAY['End of World','Soul Mates','Fake Marriage']::text[], '{}', '11760bad-b2a4-5416-a2db-33435c06497d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('2b232805-e0f4-5ed9-82ff-7b36939f3bee', :'owner', '703e601f-96d2-568a-a122-a5844b90b4f9', 'gelesen'::reading_status, true, true, ARRAY['Print','Audiobook']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 999, false, false, ARRAY['Audible']::text[], ARRAY['Kristin Atherton']::text[], 715, '👌🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 1, 'slow'::burn_kind, 'Ich hab dieses Buch ewig vor mir weggeschoben, weil mir die ersten beiden Bände schon nicht so gut gefallen haben und leider hat mich dieser Teil auch nicht wirklich überzeugt. Irgendwie ist das alles nichts ganzes und nichts halbes. Ich hab irgendwie das Gefühl, dass nichts erklärt oder abgeschlossen wurde, obwohl die Reihe hiermit beendet ist.') on conflict do nothing;
