insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('41b97f45-2e0a-56c5-a26e-54a13008d4a6', 'Bait', NULL, NULL, 'Alma Corvado has spent all her twenty-nine years believing there was no world beyond the bunker she’d always called home. Bound by duty and the fickle whims of the council she has only ever indulged in one simple rebellion.When her act of defiance finds her being pushed out into the dangers of the outside, she discovers that the world never ended. When she’s rescued from the clutches of dangerous raiders by the two people she thought were lost to her forever, Alma must confront the truth. Everything she thought she knew about the end of the world was a lie.', '07.10.2025', NULL, ARRAY['Englisch']::text[], 142, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Alma Corvado']::text[], ARRAY['End of World','Queer','Second Chance','Brother''s Best Friend']::text[], '{}', '1e483446-8299-5f6e-b954-d90d07cd9b01', '2', '{}', 'sheet', :'owner') on conflict do nothing;
