insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7e325a7-4175-5a86-838f-cafc99b6f4ca', 'Mein heißer Mitbewohner', 'Micchaku Room Share', '9782889211791', 'Keiichis neuer Mitbewohner Takumi ist wortkarg, abweisend und ständig am Pennen. Während Keiichi sich mit Freunden trifft und pflichtbewusst zur Uni geht, verschanzt sich Takumi den lieben langen Tag im Wohnheim. Was stimmt denn nicht mit dem Kerl? Schließlich reißt Keiichi der Geduldsfaden. Der wird doch wohl mal den Arsch hochkriegen! Doch wer andere aus dem Bett zerren will, fällt selbst hinein …', '04.04.2019', 'Kaze Manga', ARRAY['Deutsch']::text[], 170, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Keiichi','Takumi']::text[], ARRAY['Queer','Roomates','Opposites Attract','Friends to Lovers']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
