insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1756efa8-96e1-54a3-9152-c16b7a0a5322', 'Sternensturm', NULL, '9783401806792', 'Wie lange hat Liliana auf diesen Moment gewartet? Doch als sie endlich zur Magierin ernannt wird, stellt man ihr ausgerechnet Chris als Energiequelle zur Seite. Mit ihm muss sie sich verbinden, um ihre Macht entfesseln zu können. Aber in Chris’ Augen tobt der Hass auf alle Magier und er widersetzt sich seiner Bestimmung. So schnell wie möglich muss Liliana sein Vertrauen gewinnen, denn in den Tiefen unter Neuseeland braut sich eine schreckliche Katastrophe zusammen und nur Liliana kann sie aufhalten.', '05.01.2015', 'Arena', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Liliana','Chris']::text[], ARRAY['The Chosen One','Magical School','Enemies to Lovers','Hidden Powers','Prophezeiung']::text[], '{}', 'd308f315-ba96-598d-ae63-1d4cf6199e39', '1', '{}', 'sheet', :'owner') on conflict do nothing;
