insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('df6011fc-545f-51ed-958d-2cdc9320f360', 'Die Überlebenden', 'The Darkest Minds', '9783641123215', 'Ruby hat überlebt. Sie hat das schreckliche Virus überstanden, das die meisten Kinder und Jugendlichen in Amerika getötet hat. Doch der Preis dafür ist hoch. Sie hat alles verloren: Freunde, Familie, ihr ganzes Leben. Weil sie nun eine Fähigkeit besitzt, die sie zur Bedrohung werden lässt, zu einer Gefahr für die Menschheit. Denn sie kann die Gedanken anderer beeinflussen. Deshalb wurde sie in ein Lager gebracht mit vielen anderen Überlebenden. Deshalb soll sie getötet werden. Aber Ruby will nicht sterben. Ihr gelingt die Flucht, und sie beschließt zu kämpfen, schließlich hat sie nichts zu verlieren. Bis sie Liam trifft ...', '18.08.2014', 'Goldmann', ARRAY['Deutsch','Englisch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Ruby','Liam']::text[], '{}', '{}', '7380c8ac-2116-5928-9a9a-c213ac13de40', '1', '{}', 'sheet', :'owner') on conflict do nothing;
