insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('23759dbc-ac95-5dbc-ab1c-f8e3c4df8ae9', 'Die Überlebenden - Furchtlose Liebe', 'Never Fade', '9783641144487', 'Ruby ist eine der wenigen, die das Virus überlebt haben. Dafür ist ihr eine Gabe geblieben, die sie verflucht: Sie kann Gedanken lesen und manipulieren. Das macht sie für viele sehr wertvoll. Die berüchtigte Children’s League will sie im Kampf gegen die Regierung einsetzen. Als Ruby entdeckt, dass ihr Freund Liam erneut in großer Gefahr ist, begibt sie sich auf eine gefährliche Mission, die auch der Children’s League nicht gefallen wird. Denn niemals könnte sie ertragen, dass sie den einzigen Menschen, den sie liebt, verlieren könnte ...', '16.02.2015', 'Goldmann', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Ruby','Liam']::text[], '{}', '{}', '7380c8ac-2116-5928-9a9a-c213ac13de40', '2', '{}', 'sheet', :'owner') on conflict do nothing;
