insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8e775050-fdc9-5c73-aba1-e2c0221a0d14', 'In the Afterlight', NULL, '9781786540218', 'One of the few survivors of a disease which killed most of America''s children, Ruby has emerged as Leader of the rebel group determined to bring the government down. Torn apart by the unbearable loss of Liam, she forms an unlikely alliance with his brother, Cole. But whatever their differences, Ruby and Cole are united by a clear mission: there are thousands like them still suffering in ''rehabilitation camps''. It''s up to Ruby to set them free ...', '17.11.2014', 'Disney-Hyperion', ARRAY['Englisch']::text[], 621, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Ruby','Liam']::text[], '{}', '{}', '7380c8ac-2116-5928-9a9a-c213ac13de40', '3', '{}', 'sheet', :'owner') on conflict do nothing;
