insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d225fa6f-55e1-5aca-aef2-68861b185728', 'The Darkest Legacy', NULL, '9781786540621', 'Five years after the destruction of the so-called rehabilitation camps that imprisoned her and countless other Psi kids, seventeen-year-old Suzume “Zu” Kimura has assumed the role of spokesperson for the interim government, fighting for the rights of Psi kids against a growing tide of misinformation and prejudice. But when she is accused of committing a horrifying act, she is forced to go on the run once more in order to stay alive.', '02.08.2018', 'Disney-Hyperion', ARRAY['Englisch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Ruby','Liam']::text[], '{}', '{}', '7380c8ac-2116-5928-9a9a-c213ac13de40', '4', '{}', 'sheet', :'owner') on conflict do nothing;
