insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('53ae9886-2315-59bb-8976-39fb67e54110', 'Elian & Lira - Das wilde Herz der See', 'To Kill a Kingdom', '9783423762205', 'Lira ist die Tochter der Meereskönigin und dazu verdammt, einmal im Jahr einem Prinzen das Herz zu rauben. Als Lira einen Fehler begeht, verwandelt ihre Mutter sie zur Strafe in die Kreatur, die sie am meisten verabscheut – einen Menschen. Und sie stellt ihr ein Ultimatum: Bring mir das Herz von Prinz Elian oder bleib für immer ein Mensch. Elian ist der Thronerbe eines mächtigen Königreichs und das Meer ist der einzige Ort, an dem er sich wirklich zu Hause fühlt. Er jagt Sirenen, vor allem die eine, die bereits so vielen Prinzen das Leben genommen hat. Als er eine junge Frau aus dem Ozean fischt, ahnt er nicht, wen er da an Bord geholt hat. Das Unerwartete geschieht: die beiden verlieben sich ineinander – doch hat ihre Liebe eine Zukunft?', '20.07.2020', 'dtv', ARRAY['Deutsch']::text[], 348, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Elian','Lira']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
