insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c9d6c1c6-07db-59c7-91bf-eaa80094eebf', 'Blight', NULL, '9780062397010', 'When an agribusiness facility producing genetically engineered food releases a deadly toxin into the environment, seventeen-year-old Tempest Torres races to deliver the cure before time runs out. Seventeen-year-old Tempest Torres has lived on the AgraStar farm north of Atlanta, Georgia, since she was found outside its gates at the age of five. Now she’s part of the security force guarding the fence and watching for scavengers—people who would rather steal genetically engineered food from the Company than work for it. When a group of such rebels accidentally sets off an explosion in the research compound, it releases into the air a blight that kills every living thing in its path—including humans. With blight-resistant seeds in her pocket, Tempest teams up with a scavenger boy named Alder and runs for help. But when they finally arrive at AgraStar headquarters, they discover that there’s an even bigger plot behind the blight—and it’s up to them to stop it from happening again.', '01.04.2015', 'Greenwillow Books', ARRAY['Englisch']::text[], 345, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'AgraStar', '{}', ARRAY['Tempest Torres']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
