insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bb288f75-cad5-5a6d-a439-d3ae5317ae29', 'Sound', NULL, '9780062220172', 'As a child, Ava’s adopted sister Miyole watched her mother take to the stars, piloting her own ship from Earth to space making deliveries. Now a teen herself, Miyole is finally living her dream as a research assistant on her very first space voyage. If she plays her cards right, she could even be given permission to conduct her own research and experiments in her own habitat lab on the flight home. But when her ship saves a rover that has been viciously attacked by looters and kidnappers, Miyole–along with a rescued rover girl named Cassia–embarks on a mission to rescue Cassia’s abducted brother, and that changes the course of Miyole’s life forever.', '22.09.2015', 'Greenwillow Books', ARRAY['Englisch']::text[], 492, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Miyole']::text[], '{}', '{}', '61ae0734-be83-5f25-b046-3b85d39a2666', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
