insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5b7c33d9-f36b-5004-b77e-8f523706193b', 'Boyfriend Material', NULL, '9783736317529', 'Mit einem berühmten Vater, der mit seinen Eskapaden immer wieder für Schlagzeilen sorgt, steht auch Luc O’Donnell im Licht der Öffentlichkeit. Als die Klatschpresse wieder mal negativ über ihn berichtet, droht er seinen Job bei einer Wohltätigkeitsorganisation zu verlieren. Um sein Image aufzupolieren, macht Luc sich auf die Suche nach einem respektablen Fake-Freund und findet schnell die ideale Besetzung für die Rolle: Oliver Blackwood - Anwalt, Vegetarier und so skandalfrei, wie es nur geht. Die beiden beschließen, der Welt das perfekte Paar vorzuspielen, und obwohl sie nicht unterschiedlicher sein könnten, merken sie bald, dass nicht alles bloß vorgetäuscht ist ...', '29.07.2022', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Luc O''Donnell','Oliver Blackwood']::text[], ARRAY['Fake Dating','Opposites Attract']::text[], '{}', '5e1151ce-c5bb-5c35-a2d6-9da46e79f580', '1', '{}', 'sheet', :'owner') on conflict do nothing;
