insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('22c371a3-96e4-589e-bf19-d66a6a6e6df2', 'Forever Material', 'Husband Material', '9783736317963', 'Aus ihrer Fake-Beziehung ist längst etwas Echtes geworden. Luc und Oliver sind verliebt und könnten eigentlich nicht glücklicher sein. Doch dann bricht auf einmal der Heiratswahn aus, und alle um sie herum geben sich das Jawort. Von den ganzen Zukunftsplänen in seinem Bekanntenkreis unter Druck gesetzt, beginnt Luc sich zu fragen, ob Oliver und er auch den nächsten Schritt wagen sollten. Aber beide merken schnell, dass es für ein Happy End mehr braucht als bloß einen Heiratsantrag ...', '27.01.2023', 'LYX', ARRAY['Deutsch']::text[], 501, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Luc O''Donnell','Oliver Blackwood']::text[], ARRAY['Fake Dating','He falls first']::text[], '{}', '5e1151ce-c5bb-5c35-a2d6-9da46e79f580', '2', '{}', 'sheet', :'owner') on conflict do nothing;
