insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4e768b6d-fe77-5d0e-be9d-5442b74b28df', 'The Lost Memory Project', '10 Things That Never Happened', '9783736320659', 'Am liebsten würde Sam Becker das Meeting mit seinem Boss absagen, weiß er doch, dass der mit ihm über mögliche Entlassungen in seinem Team sprechen will. Jonathan Forest ist attraktiv - keine Frage -, aber leider auch ein bisschen einschüchternd. Und als Sam sich während des Termins den Kopf stößt, nutzt er die Gelegenheit und tut das einzig "Logische": Er gibt vor, sein Gedächtnis verloren zu haben und sich deshalb auch nicht an ihr Gespräch erinnern zu können. Was zuerst wie eine gute Idee aussieht, entwickelt sich schnell zu einem Desaster, denn bei ihrer zweiten Chance, sich wirklich kennenzulernen, entdeckt Sam ganz neue Seiten an seinem verschlossenen Boss und beginnt, ungeahnte Gefühle für ihn zu entwickeln ...', '22.12.2023', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Sam Becker','Jonathan Forest']::text[], ARRAY['Enemies to Lovers','Grumpy x Sunshine','Work Adversaries']::text[], '{}', '5e1151ce-c5bb-5c35-a2d6-9da46e79f580', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
