insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9b46c031-948a-561d-8c84-e014f94307eb', 'First', NULL, NULL, 'A general plans to use a nobleman’s bride to teach him a lesson. After meeting her, he decides to keep her for himself.', '2025', NULL, ARRAY['Englisch']::text[], 136, 23, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['Double POV','1P']::text[], ARRAY['Sofia','Gabriel']::text[], ARRAY['Forced Proximity','Omegaverse']::text[], ARRAY['Dub-Con/Non-Con','Physische Gewalt','Tod von Familienangehörigen','Toxische Beziehungsdynamiken']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c8eddef1-fec7-5a33-8b7e-aed65dcd784c', :'owner', '9b46c031-948a-561d-8c84-e014f94307eb', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'untertroffen'::expectation_kind, 3, 'slow'::burn_kind, 'Also wie immer: Ich mag Alis Schreibstil einfach und ich mag ihren Humor. ABER die Story war schon....wild. Ich hab einfach eine Hassliebe für Kurzgeschichten. Auf der einen Seite macht es Spaß zu lesen, auf der anderen Seite nervt es mich oft wie Kontextlos und viel zu schnell die meisten Dinge zwangsläufig passieren. Und ich mag es auch irgendiwie nicht, wenn sexual consent irgendwie fragwürdig ist.') on conflict do nothing;
