insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('68837b1f-a452-5849-990b-118ca4c88a8b', 'd74715f0-668f-5b0d-a231-b2a8b7afdb05', :'owner', 1, '2025-05-14', '2025-05-20', NULL, NULL, 7, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4223e687-a914-50a9-ad02-818d55f678e9', 'Bride', NULL, '9780593550403', 'Misery Lark, the only daughter of the most powerful Vampyre councilman of the Southwest, is an outcast - again. Her days of living in anonymity among the Humans are over: she has been called upon to uphold an historic peacekeeping alliance between the Vampyres and their mortal enemies, the Weres, and sees little choice but to surrender herself in the exchange - again . . . Weres are ruthless and unpredictable, and their Alpha, Lowe Moreland, is no exception. He rules his pack with absolute authority, but not without justice. And, unlike the Vampyre Council, not without feeling. It''s clear from the way he tracks Misery''s every movement that he doesn''t trust her. If only he knew how right he was . . . Because Misery has her own reasons to agree to this marriage of convenience, reasons that have nothing to do with politics or alliances, and everything to do with the only thing she''s ever cared about. And she is willing to do whatever it takes to get back what''s hers, even if it means a life alone in Were territory . . . alone with the wolf.', '06.02.2024', 'Penguin LLC US', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Misery Lark','Lowe Moreland']::text[], ARRAY['Found Family','Omegaverse','Political Intrigue','Unlikely Allies','Enemies to Lovers']::text[], '{}', 'd6dfe9bd-04ca-5f16-af69-00c823d03e78', '1', '{}', 'sheet', :'owner') on conflict do nothing;
