insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('40369537-490b-5f98-a01b-a4834078c4da', :'owner', '64d6f214-b568-5c04-897d-c5309c1f6d17', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['Taschenbuch','eBook']::text[], 'Normal', '{}', 798, NULL, NULL, '{}', '{}', NULL, NULL, true, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'erfuellt'::expectation_kind, NULL, 'slow'::burn_kind, 'Ich mochte beide Charaktere an sich super gerne (ok ich liebe Adam) aber ihre Entscheidungen waren wirklich oft so doof und unüberlegt. Wenn alle einfach mal ehrlich miteinander gewesen wären, hätte es all diese Probleme nicht gebraucht. Trotzdem eine super süße Story und ich liebe den Humor von Ali Hazelwood.') on conflict do nothing;
