insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('70304d6d-2e73-5a10-8309-97c0221ae79a', 'Mate', NULL, '9780593952580', 'Serena Paris is orphaned, pack-less, and one of a kind. Coming forward as the first Human-Were hybrid was supposed to heal a centuries-long rift between species. Instead, it made her a target, prey for the ruthless political machinations between Weres, Vampyres, and Humans. With her enemies closing in on her, she has only one option left—if he’ll have her. As Alpha of the Northwest pack, Koen Alexander commands obedience. His authority is so absolute, only a fool would threaten his mate. It doesn’t matter if Serena doesn’t reciprocate his feelings, nothing will stop him from keeping her safe. But power-hungry Vampyres and Weres are not the only threats chasing Serena. Sooner or later, her past is bound to catch up with her—and Koen might be the only thing standing between her and total annihilation…', '07.10.2025', 'Penguin LLC US', ARRAY['Englisch']::text[], 464, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, 'Northwest Territory', ARRAY['Single POV','1P']::text[], ARRAY['Serena Paris','Koen Alexander']::text[], ARRAY['Soul Mates','Omegaverse','Forbidden Love','Health Problems']::text[], '{}', 'd6dfe9bd-04ca-5f16-af69-00c823d03e78', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('9b8d16d3-9e14-58e3-b324-ad26797df9b2', :'owner', '70304d6d-2e73-5a10-8309-97c0221ae79a', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1199, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 5, 'slow'::burn_kind, 'Ich liebe Ali Hazelwoods Humor und das hat sich auch in diesem Buch mal wieder gezeigt. Serena und Koean sind einfach funny! Aber die kleinen Einblicke in Koens Gedankenwelt haben mich jedes mal zum schmunzeln gebracht. Ein wirklich gutes Buch! Das einzige was ich ein wenig kritisieren würde wäre, dass die Probleme immer zu schnell und zu einfach gelöst werden konnten. Aber es muss ja auch nicht immer alles super dramatisch sein.') on conflict do nothing;
