insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3512c39f-f29d-5f6a-812b-07bead62ec43', 'Problematic Summer Romance', NULL, '9781408729885', 'Maya Killgore is twenty-three and still in the process of figuring out her life. Conor Harkness is thirty-eight, and Maya cannot stop thinking about him. It''s such a cliché, it almost makes her heart implode: older man and younger woman; successful biotech guy and struggling grad student; brother''s best friend and the girl he never even knew existed. As Conor loves to remind her, the power dynamic is too imbalanced. Any relationship between them would be problematic in too many ways to count, and Maya should just get over him. After all, he has made it clear that he wants her gone from his life. But not everything is as it seems - and clichés sometimes become plot twists. When Maya''s brother decides to get married in Taormina, she and Conor end up stuck together in a romantic Sicilian villa for over a week. There, on the beautiful Ionian coast, between ancient ruins, delicious foods, and natural caves, Maya realizes that Conor might be hiding something from her. And as the destination wedding begins to erupt out of control, she decides that a summer fling might be just what she needs - even if it''s a problematic one.', '27.05.2025', 'Little, Brown Books', ARRAY['Englisch']::text[], 416, 43, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Taormina', ARRAY['Single POV','1P']::text[], ARRAY['Maya Killgore','Conor Harkness']::text[], ARRAY['Brother''s Best Friend','Age Gap','Forced Proximity']::text[], ARRAY['Tod von Familienangehörigen']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('43328e33-a224-55a3-918f-2b1d3d8aea04', :'owner', '3512c39f-f29d-5f6a-812b-07bead62ec43', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1039, NULL, NULL, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 4, 'slow'::burn_kind, 'Ich glaube ich würde jedes Buch von Ali lieben, einfach weil ihr Humor zu 100% kompatibel ist mit meinem. Hank ging mir zwar zwischendurch etwas auf die nerven, aber das war ja der Sinn des ganzen.') on conflict do nothing;
