insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3b0a4c2b-fbb8-5792-ad91-929f3936b6e7', 'Scared Sexy - Die ungeheuerliche Unzähmbarkeit der Liebe', 'Scared Sexy Collection', '9783987511042', 'Nachts erwachen alle Monster. Und sie haben es auf dein Herz abgesehen. Sobald die Nächte länger werden, wird es spicy: Enzo, der Vampirjäger und Jahrhunderterzfeind von Vampirin Ethel hat alles vergessen – sogar, dass er sie töten will. Der Untersterbliche Brigan trifft derweil auf Cat, die erste Frau in 900 Jahren, die seiner magischen Anziehungskraft widerstehen kann. Journalistin Petra hingegen glaubt nicht an Magie – bis sie Dax mit seinen lebendigen Tattoos trifft. Auf einer Raumstation kommen sich Dana, die Gefangene eines Aliens, und der genetisch veränderte Vampir Vlad kommen näher; während in einer anderen Dimension Schlafparalyse-Dämonin Gemma zu fasziniert von ihrem Opfer ist, um zuzuschlagen. Und als Lucy eine Münze in einen Brunnen wirft, buhlen plötzlich mehrere übernatürlich schöne Männer um ihr Herz. Doch jedes Happy End hat seinen Preis ...', '16.09.2026', 'more', ARRAY['Deutsch']::text[], 492, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['Multiple POV']::text[], '{}', ARRAY['Holiday']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
