insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('95623dd0-25f5-5d79-8c34-7e337d505825', 'Under the Mistletoe - Die zwangsläufige Zeit der Liebe', NULL, '9783352010231', 'Sinken die Temperaturen, müssen erst die Funken fliegen, damit uns – endlich – warm wird: So steckt die Kinderärztin Jamie bei Ali Hazelwood mit ihrem Ex-Sandkastenfeind Marc in einem tosenden Wintersturm fest. Und der ist inzwischen hot as hell geworden ... Bei Tessa Bailey sucht eine alleinerziehende Mutter auf keinen Fall mehr als einen Friend-with-Benefits – und bekommt mit dem Farmer Luke ganz das Gegenteil. Wildes Schneetreiben macht es bei Olivia Dade möglich, dass Collegedozentin Nina endlich ihrem Crush William nahekommt. Bei Alexandria Bellefleur wird Everleigh von einem heißen Feuerwehrmann aus der Feiertagskrise gerettet. Und Alexis Daria lässt die unanständigen Fantasien, die Evie für ihren Nachbarn hegt, zauberhafte Wirklichkeit werden.', '17.09.2025', 'rütten & loening', ARRAY['Deutsch']::text[], 365, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['Multiple POV']::text[], '{}', ARRAY['Holiday','Friends to Lovers','Brother''s Best Friend','Single Parent']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
