insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3534565a-052c-50b4-bb3a-1270d020fd35', 'Die Frau des Serienkillers', 'The Serial Killer''s Wife', '9783757700966', 'Beth und Tom Hardcastle leben in dem kleinen, idyllischen Ort Lower Tew und werden von allen beneidet. Sie führen die perfekte Ehe, haben das perfekte Haus, die perfekte Tochter, kurzum: Sie sind die perfekte Familie ... zumindest bis zu dem Tag, an dem die Polizei auftaucht und Tom wegen Mordes in Haft nimmt. So beginnt auch für Beth eine tägliche Tortur, denn die Nachbarn können nicht glauben, dass sie nichts von Toms Taten gewusst hat. Zunächst verteidigt Beth ihren Mann noch und beteuert seine Unschuld. Mit der Zeit wird jedoch klar, dass auch sie ihre Geheimnisse hat, die ihre Freunde und Nachbarn nicht erfahren sollen, ganz zu schweigen von der Polizei.', '29.11.2024', 'Lübbe', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Beth Hardcastle']::text[], ARRAY['Small Town','Unreliable Narrator']::text[], '{}', '80cc3a05-b2a5-5ae1-a60d-ae0f89fe4466', '1', '{}', 'sheet', :'owner') on conflict do nothing;
