insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('343ab040-d8ea-53c8-a3eb-3820c2ddea90', 'Wedding People', 'The Wedding People', '9783757701291', 'Als Phoebe Stone in einem grünen Seidenkleid und goldenen High Heels im prächtigen »Cornwall Inn« ankommt, wird sie von allen für einen Hochzeitsgast gehalten. Doch sie ist die Einzige, die nicht zum Feiern angereist ist. Seit Jahren hat sie davon geträumt, mit ihrem Mann hierherzukommen. Nun ist sie ohne ihn hier, am Tiefpunkt ihres Lebens, fest entschlossen, sich ein letztes Mal etwas zu gönnen, bevor sie mit allem Schluss macht. Dumm nur, dass sie ausgerechnet der Braut in die Quere kommt. Die hat jedes Detail und jede denkbare Katastrophe sorgfältig einkalkuliert - mit einer Ausnahme: Phoebe und deren Vorhaben. Als sich ihre Wege kreuzen, gerät alles aus dem Takt, und es setzt etwas in Gang, das keine von ihnen erwartet hat.', '28.07.2025', 'Lübbe', ARRAY['Deutsch']::text[], 477, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['RomCom']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Cornwall Inn', '{}', ARRAY['Phoebe Stone']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
