insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f81a1dd0-a6cd-597a-8815-5de3ffe136dd', 'ab49cbaa-2934-5f75-8642-32badceb89de', :'owner', 2, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('547c43bc-ca87-562f-95df-02a2a0ac5bf9', 'A Fragile Enchantment', NULL, '9781510112117', 'All Niamh has longed for is to be remembered: to create something that will last far longer than she will. For her, that means becoming a renowned dressmaker, using the magic in her blood that lets her stitch emotions and memories into fabric - the same magic that will eventually kill her. When Niamh is commissioned to design the prince''s wardrobe for a royal wedding in Avaland, she knows she finally has her chance to leave her legacy. But Avaland is far from the fairytale that she imagined. While nobles and the elite attend extravagant balls and candlelit garden parties, unrest brews amid the working class. Niamh finds herself drawn to Kit, the prince whom she must dress for his wedding, despite his cold, prickly demeanour. And soon, a gossip column reports on their undeniable chemistry between them, threatening scandal. Niamh must decide if reputation should come above all else, whether her magic curse will allow her to experience love, and what cost she is willing to pay for a future she never thought possible...', '04.01.2024', 'Orion', ARRAY['Englisch']::text[], 373, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Niamh Ó Conchobhair','Kit Carmine']::text[], ARRAY['Enemies to Lovers','Forbidden Love']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
