insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('726fccc3-f858-50fa-95fa-0625bb84ecd0', 'Die Flucht', 'Crossed', '9783104019857', 'Wenn das System dich zwingt zu fliehen, kann deine Liebe überleben? Stell dir vor, du lebst in einer Welt, in der alles in deinem Leben geregelt wird – sogar, wen du lieben musst. Aber du liebst den Falschen: Jemanden, den das System töten will. Wie weit würdest du gehen, um sein Leben zu retten? Würdest du für deine Liebe sterben? Wie durch ein Wunder gelingt Cassia die Flucht in die Äußeren Provinzen. Sie will nach Ky suchen, ihrer großen Liebe. Ky kämpft dort als Soldat für die Gesellschaft und ist ununterbrochen brutalen Angriffen ausgesetzt. Als Cassia endlich auf eine Spur von Ky stößt, ist er bereits entkommen und auf dem Weg in die wilden Canyons in den Grenzgebieten. Verzweifelt macht sich Cassia auf den lebensgefährlichen Weg. Was wird sie am Ende der ihr bekannten Welt finden? Zwischen steinigen Schluchten und staubigen Pfaden sucht Cassia nicht nur nach Ky – sondern auch nach sich selbst.', '20.01.2012', 'Fischer', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Cassia','Ky']::text[], '{}', '{}', 'a6888ddb-38fb-5dfa-9a35-71d944fd59cb', '2', '{}', 'sheet', :'owner') on conflict do nothing;
