insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('19ca3e52-33c6-55b2-b2dc-5acdef4db5a7', '1d3d2692-39e5-50fa-84db-b2652247e60b', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f8f99bcb-4c20-585f-9909-72b2650c04f0', 'Die Ankunft', 'Reached', '9783104023236', 'WENN JEMAND STIRBT, DEN DU LIEBST – WÜRDEST DU DEN RETTEN, DER IHN GETÖTET HAT? Das fulminante Finale über die Liebesgeschichte von Cassia & Ky beschert den Leserinnen ein unvergessliches Leseerlebnis. Stell dir vor, du konntest fliehen – vor dem System, das dir befohlen hat, wie du leben und wen du lieben sollst. Unter Lebensgefahr hast du deine Liebe wiedergefunden – eine Liebe, die das System töten wollte. Jetzt willst du das System besiegen, doch dafür musst du zurück. Zurück in dein altes Leben. Zurück zu einem Geheimnis, das tief in dir verborgen ist. Es wird alles verändern. Dein Leben. Deine Liebe. In den zerklüfteten Schluchten der Canyons hat Cassia nicht nur ihre große Liebe Ky wiedergefunden– sondern auch die Erhebung, eine Untergrundbewegung, die das System stürzen will. Als sich beide der Erhebung anschließen, müssen sie sich jedoch trennen. Ky wird auf einem Stützpunkt in einer Äußeren Provinz zum Piloten ausgebildet und Cassia in die Hauptstadt beordert. Dort trifft sie auf Xander, der als Funktionär für die Gesellschaft arbeitet. Kann sie sich ihm anvertrauen? Als eine tödliche Seuche ausbricht und die gesamte Bevölkerung zu vernichten droht, muss Cassia eine Entscheidung treffen …', '08.01.2013', 'Fischer', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Cassia','Ky']::text[], '{}', '{}', 'a6888ddb-38fb-5dfa-9a35-71d944fd59cb', '3', '{}', 'sheet', :'owner') on conflict do nothing;
