insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('322f4e40-f4bc-541e-b9bd-7baf50695755', '7b3056b7-e568-5dde-b386-d6490549032d', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ae8b9df7-d22a-588e-9326-98c4d3003d6b', 'Die Auswahl', 'Matched', '9783104007502', 'Das System sagt, wen du lieben sollst – aber was sagt dein Herz? Für die 17-jährige Cassia ist es der wichtigste Tag ihres Lebens: Heute erfährt sie, wen sie mit 21 heiraten wird – wen das System für sie ausgewählt hat. Es könnte jeder Junge aus Oria sein, doch zur großen Überraschung aller wird ihr bester Freund Xander als ihr Partner bekanntgegeben. Als Cassia sich später auf dem feierlich überreichten Mikrochip Informationen über Xander ansehen will, passiert etwas schier Unmögliches: Es erscheint das Gesicht eines anderen Jungen – das von Ky. Cassia ist schockiert und verängstigt. Das System macht keine Fehler! Und tatsächlich wird ihr von offizieller Seite versichert, dass es sich um ein einmaliges Versehen handelt. Aber Cassia geht Kys Anblick nicht mehr aus dem Kopf. Gibt es doch die Möglichkeit zu wählen?', '28.01.2011', 'Fischer', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Cassia','Ky']::text[], '{}', '{}', 'a6888ddb-38fb-5dfa-9a35-71d944fd59cb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
