insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('ac672de2-bf97-58e9-8e57-d062722bae57', 'f09a5194-6a43-50fd-8c52-324ff1a95021', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('231cecc8-d069-5ae5-942b-819949808931', 'The Deep', NULL, '9780857504289', 'Deaths and disappearances have plagued the vast liner from the moment she began her maiden voyage on 10 April 1912. Four days later, caught in what feels like an eerie, unsettling twilight zone, some passengers - including millionaire Madeleine Astor and maid Annie Hebbley - are convinced that something sinister is afoot. And then disaster strikes. Four years later and the world is at war. Having survived that fateful night, Annie is now a nurse on board the Titanic''s sister ship, the Britannic, refitted as a hospital ship. And she is about to realise that those demons from her past and the terrors of that doomed voyage have not finished with her yet . . . Bringing together Faustian pacts, the occult, tales of sirens and selkies, guilt and revenge, desire and destiny, The Deep offers a thrilling, tantalizing twist on one of the world''s most famous tragedies.', '11.03.2021', 'Bantam Press', ARRAY['Englisch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Paranormal']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Annie Hebbley']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
