insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('879a5195-7765-5d2c-9435-3441e82fb76f', 'Soul Seeker - Vom Schicksal bestimmt', 'Soul Seeker - Fated', NULL, 'Plötzlich ist im Leben der 16-jährigen Daire Santos nichts mehr so, wie es war. Von einem Tag auf den anderen hat sie schreckliche Visionen, Krähen und Geister verfolgen sie, während die Zeit still zu stehen scheint. Und dann wird sie in ihren Träumen auch noch heimgesucht von einem unbekannten Jungen mit wunderschönen blauen Augen. Daire glaubt, den Verstand zu verlieren. Erst als sie zum ersten Mal Kontakt zu ihrer Großmutter aufnimmt, scheint sich alles zu klären. Denn von ihr erfährt sie, dass sie ein Soul Seeker ist. Nur sie hat die Fähigkeit, zwischen den Welten der Lebenden und der Toten zu wandeln. Doch dann begegnet sie Dace, dem Jungen mit den schönen blauen Augen in der Wirklichkeit, und von dem Augenblick an ringt ihre Großmutter mit dem Tod. Kann es sein, dass dieser charmante Junge nicht der ist, der er vorgibt zu sein und eine dunkle Gefahr von ihm ausgeht?', '10.09.2012', 'Goldmann', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Daire Santos']::text[], '{}', '{}', 'ff12b84d-ca44-5123-a455-9d1dcdfa2c36', '1', '{}', 'sheet', :'owner') on conflict do nothing;
