insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('859e2932-6eb0-5c9f-bf8e-b0a921178a6d', 'Riley - Im Schein der Finsternis', 'The Riley Series', NULL, 'Riley ist tot, und das genießt sie ausgiebig, denn schließlich hat sie eine mehr als spannende Aufgabe: Seelen einzufangen, die auf ihrem Weg ins Jenseits verlorengegangen sind. Dabei sind es die schweren Fälle, derer sie sich mit Vorliebe annimmt. Allerdings fragt sie sich inzwischen, warum sie ausgerechnet diesem Geistermädchen Rebecca helfen wollte? Sie ist voller Hass und will nur Rache für ihren Tod: In einem gefährlich dunkel-glitzernden Nebel aus Zorn hält sie unzählige Seelen gefangen, um sie zu quälen. Riley ist verzweifelt – wie kann sie diesem Grauen ein Ende setzen? Wie kann sie der Finsternis gegenübertreten, ohne sich selbst darin zu verlieren?', '15.07.2011', 'Page Turner', ARRAY['Deutsch']::text[], 220, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Riley']::text[], '{}', '{}', '88b92dea-23fe-5133-a50f-13251422f7a8', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
