insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b6a5e5cd-46e9-597b-b81e-06f7daa30fde', 'Soul Seeker - Das Echo des Bösen', 'Soul Seeker - Echo', '9783641089184', 'Daire Santos hat ihr Schicksal als Soul Seeker angenommen und damit nicht nur das Leben ihrer Großmutter gerettet, sondern auch deren Seele. Aber der Preis dafür war hoch: Die Erzfeinde der Soul Seeker haben sich nämlich einen Zugang zur Unterwelt verschaffen können. Es ist eine mächtige Familie, deren Mitglieder allesamt magische Kräfte besitzen. Ihr größtes Ziel ist es, die verlorenen Seelen ihrer furchterregendsten Vorfahren zurückzubringen, um ihren Einfluss zu vergrößern. Daire und ihr Freund Dace müssen alles tun, um sie aufzuhalten, damit das Gleichgewicht zwischen Gut und Böse nicht zerstört wird. Diesmal steht allerdings noch mehr auf dem Spiel als nur eine Seele. Denn es geht nicht nur um ihre kleine Stadt Enchantment in New Mexiko, diesmal könnte die ganze Welt von den dunklen Mächten überschattet werden …', '22.07.2013', 'Goldmann', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Daire Santos']::text[], '{}', '{}', 'ff12b84d-ca44-5123-a455-9d1dcdfa2c36', '2', '{}', 'sheet', :'owner') on conflict do nothing;
