insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e29b27a5-496a-583d-af61-08ae316e6e4a', 'Riley - Die Geisterjägerin', 'The Riley Series', NULL, 'Riley Bloom hat sich im Jenseits inzwischen einigermaßen eingelebt. Aber den Kontakt zu Ever vermisst sie immer noch sehr. Ihre geliebte Schwester muss auf der Erde als Unsterbliche ihre eigenen Probleme lösen. Als Riley erfährt, dass es einen Ort gibt, an dem man Träume erzeugen und an Menschen auf der Erde schicken kann, macht sie sich gleich auf den Weg. Ein Traum ist die einzige Möglichkeit, Ever eine Botschaft zu schicken und ihr zu zeigen, dass es ihr gut geht. Doch als sie am Ort der Träume ankommt, hat sich dort bereits ein Geisterjunge niedergelassen, der seit einiger Zeit Albträume auf die Erde schickt. Riley weiß, er ist gefährlich, und es erfordert all ihren Mut, sich ihm in den Weg zu stellen ...', '23.01.2012', 'Page Turner', ARRAY['Deutsch']::text[], 218, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Riley']::text[], '{}', '{}', '88b92dea-23fe-5133-a50f-13251422f7a8', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
