insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ad109cfc-f744-54d1-b19b-9e68e5e4076c', 'Soul Seeker - Im Namen des Sehers', 'Soul Seeker - Mystic', NULL, 'Nachdem Daire Santos plötzlich mysteriöse Visionen hatte, ist sie zu ihrer Großmutter Paloma in die kleine Stadt Enchantment in New Mexico gezogen. Dort erfährt sie, dass sie eine Seelensucherin ist, die zwischen den Welten der Lebenden und der Toten wandeln kann. Mit Palomas Hilfe hat sie gerade noch rechtzeitig gelernt, mit ihren Kräften umzugehen. Denn eine mächtige Familie hat es darauf abgesehen, die Unter-, Mittel- und Oberwelt zu stürmen. Daire ist der einzige Mensch, der sie stoppen kann, aber es gibt ein Problem: Sie liebt Dace, dessen Zwillingsbruder Cade es auf Daires Kräfte abgesehen hat. Beide Brüder gehören der mächtigen Familie an. Wird Daire es schaffen können, ihre Bestimmung zu erfüllen, ohne ihre wahre Liebe dabei zu zerstören?', '17.11.2014', 'Goldmann', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Daire Santos']::text[], '{}', '{}', 'ff12b84d-ca44-5123-a455-9d1dcdfa2c36', '3', '{}', 'sheet', :'owner') on conflict do nothing;
