insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bc168084-dc05-5086-903a-27b90264bae7', 'Riley - Der erste Kuss', 'The Riley Series', NULL, 'Riley steht vor ihrer bisher größten Herausforderung als Geisterjägerin, und daran ist sie selbst nicht ganz unschuldig. Schließlich wollte sie auf einen Geist angesetzt werden, der es ihr besonders schwer machen würde. Also wird die zierliche Zwölfjährige zu einem echten römischen Gladiator geschickt, der auf der Erde sein Unwesen treibt. Und plötzlich steckt Riley in den größten Schwierigkeiten. Doch dann trifft sie die schöne Messalina, die ihr einen Rat gibt: Nur wenn sie Teil seiner Welt wird, wird sie es schaffen können, seine Seele endlich ins Jenseits zu befördern. Mit ihrer Hilfe durchläuft sie also ein komplettes Umstyling und wird zum schönen Teenager. Und ist so nicht nur bestens für ihre Aufgabe gerüstet, sondern auch bereit für ihren ersten Kuss ...', '21.05.2012', 'Page Turner', ARRAY['Deutsch']::text[], 224, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Riley']::text[], '{}', '{}', '88b92dea-23fe-5133-a50f-13251422f7a8', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
