insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9204035a-6920-5908-a6bc-4e14b357a716', 'Soul Seeker - Licht am Horizont', 'Soul Seeker - Horizon', '9783641095864', 'Als Seelensucherin ist Daire Santos inzwischen eine Meisterin. Sie hat gelernt, mit ihrer Gabe umzugehen und ihre Fähigkeiten voll auszuschöpfen. Um ihre Aufgabe erfüllen zu können, ist das auch dringend nötig, denn nur sie allein kann das Gleichgewicht zwischen den Welten der Lebenden und der Toten aufrechterhalten. Aber als wäre das noch nicht genug, hat sich auch noch ein Prophet in den Kampf um Gut und Böse eingemischt. Er will den Erzfeinden der Soulseeker helfen, die Welt in Dunkelheit versinken zu lassen. Und das Schlimmste ist: Seine Tochter ist die Exfreundin von Daires geliebtem Dace. Werden ihre Kräfte dieser Übermacht an mächtigen Gegnern standhalten? Und wird ihre Liebe zu Dace allen Gefahren trotzen können?', '14.07.2014', 'Goldmann', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Daire Santos']::text[], '{}', '{}', 'ff12b84d-ca44-5123-a455-9d1dcdfa2c36', '4', '{}', 'sheet', :'owner') on conflict do nothing;
