insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bd9f1f76-ac15-5d71-a68a-5e9d4382419e', 'Evermore - Für immer und ewig', 'Evermore', NULL, 'So viel schon hat Ever riskiert und verloren, um endlich mit Damen glücklich zu sein. Doch noch immer ist der Fluch, der auf ihrer Liebe lastet, nicht besiegt. Und solange der Fluch noch existiert, gibt es keine glückliche Zukunft für die beiden. Noch dazu geschehen merkwürdige Dinge im Sommerland, der Ort, wo sich Ever immer geborgen gefühlt hat. Wird es Ever schaffen, endlich den Fluch zu brechen? Und kann sie das Sommerland retten?', '15.08.2011', 'Page Turner', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '6', '{}', 'sheet', :'owner') on conflict do nothing;
