insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('970f66ee-d266-50f8-9d01-b25afdc142ec', 'Evermore - Das Schattenland', 'Evermore', '9783442203772', 'Ever ist verzweifelt. Unter keinen Umständen darf sie ihrer großen Liebe Damen zu nahe kommen, sonst wird er für immer im Schattenland gefangen sein. Um einen Ausweg zu finden, wendet sie sich der Magie zu und trifft dabei auf Jude. Sofort ist eine Vertrautheit zwischen ihnen. Alles fühlt sich mit Jude plötzlich so leicht an, während es mit Damen immer komplizierter wird. Und langsam kommen Gedanken in Ever auf, ob Damen und sie wirklich füreinander bestimmt sind.', '16.08.2010', 'Page Turner', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '3', '{}', 'sheet', :'owner') on conflict do nothing;
