insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6ff2b09b-c956-5f28-af69-0393f09975f9', 'Evermore - Das dunkle Feuer', 'Evermore', '9783442203789', 'Endlich weiß Ever, was sie tun muss, um mit ihrer großen Liebe Damen zusammen sein zu können: Sie muss die Kontrolle über ihren Erzfeind Roman erlangen. Und ihn dazu bringen, den Fluch, den er über ihre Liebe zu Damen verhangen hat, außer Kraft zu setzen. Doch für dieses Ritual ist schwarze Magie nötig. Und das bedeutet, dass Ever nicht nur sich selbst, sondern auch Damen in größte Gefahr bringt.', '15.11.2010', 'Page Turner', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '4', '{}', 'sheet', :'owner') on conflict do nothing;
