insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0be66c84-8218-5584-93f7-329475e709bf', 'Evermore - Die Unsterblichen', 'Evermore', '9783442203604', 'Seit dem tragischen Autounfall, bei dem ihre gesamte Familie ums Leben kam und sie als Einzige überlebte, ist die sechzehnjährige Ever in sich gekehrt und lässt niemanden an sich heran. Doch seit diesem traumatischen Ereignis, hat sie eine Gabe: Sie hört die Gedanken der Menschen in ihrer Nähe und kann ihre Aura sehen...', '02.11.2009', 'Page Turner', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '1', '{}', 'sheet', :'owner') on conflict do nothing;
