insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5b8922e9-fc81-599e-ad61-b2cef42a45ff', 'Riley - Das Mädchen im Licht', 'The Riley Series', '9783442203833', 'Riley Bloom hat einen ganz neuen Lebensabschnitt vor sich - den Tod. Durch einen Autounfall wurde sie aus dem Leben gerissen und von ihrer Schwester Ever getrennt. Ein Abschied, der ihr so schwerfiel, dass sie noch eine Weile als Geist auf der Erde blieb. Aber da auch das schönste Geisterleben einmal ein Ende haben muss, überquerte Riley schließlich die Brücke ins Jenseits. Nur kann sie dort leider auch keine Ruhe finden, denn vom großen Rat wird ihr eine besondere Aufgabe zugeteilt: Sie soll auf der Erde verlorene Seelen einfangen. Und ausgerechnet der langweiligste Junge, dem sie je begegnet ist, wird ihr dabei zur Seite stehen. Riley hat sich das irgendwie anders vorgestellt. Zum Glück hält der Tod noch so einiges für sie bereit ...', '08.02.2011', 'Page Turner', ARRAY['Deutsch']::text[], 189, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Riley']::text[], '{}', '{}', '88b92dea-23fe-5133-a50f-13251422f7a8', '1', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
