insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eaf85ce5-be72-5713-a1bf-ffd21bc7ba03', 'Evermore - Der blaue Mond', 'Evermore', '9783442203611', 'Lange war Ever nicht mehr so glücklich. In Damen hat sie ihre große Liebe gefunden. Eine Liebe, die niemand mehr zerstören kann. Doch dann wird das Glück der beiden auf eine harte Probe gestellt. Damen wird von einer Krankheit befallen, die seine Kräfte schwinden lässt und scheinbar einen anderen Menschen aus ihm macht. Immer mehr wendet er sich von Ever ab. Sie bricht auf in das geheimnisvolle Sommerland, um eine Möglichkeit zu finden, Damen und ihre Liebe zu retten.', '08.03.2010', 'Page Turner', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '2', '{}', 'sheet', :'owner') on conflict do nothing;
