insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ef5a72db-6fd9-5e4d-ab66-faf2459b9ba2', 'Evermore - Der Stern der Nacht', 'Evermore', '9783442203796', 'Ever weiß keinen Ausweg mehr: Das Mittel gegen den Fluch, der auf der Liebe von Damen und ihr lastet, ist zerstört worden. Noch dazu gibt ihre beste Freundin Haven, Ever die Schuld an dem Tod ihrer großen Liebe Roman. Haven ist auf Rache aus. Und Ever sieht sich gezwungen, einen weiteren geliebten Menschen zu verlieren.', '25.04.2011', 'Page Turner', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ever','Damen']::text[], '{}', '{}', '0e26f6df-b95d-5aba-9542-569ddb675650', '5', '{}', 'sheet', :'owner') on conflict do nothing;
