insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b4a514fd-e37e-52fc-b3c9-aecddea04239', 'Seven Deadly Thorns', NULL, '9781526680297', 'Viola Sinclair has hidden her shadow magic her whole life. Discovery means certain death, for in the Kingdom of Aragoa dark magic is forbidden. When the Queen finds out Viola''s secret, she sends her royal assassin to kill her. He is given a cursed tattoo: seven thorns on his arm for the seven days he has to complete his deadly task. If he fails, he will be the one to die. The assassin is Roze Roquelart--entitled prince, arrogant fellow student at Vandenberghe Academy, and Viola''s mortal enemy. The chance to strike Viola down is at Roze''s fingertips. But he needs something from Viola. And he''s willing to spare her life to get it. Forced to work together, Viola and Roze uncover terrible secrets, sinister threats . . . and an irresistible attraction. Can they learn to trust each other in time to save themselves--and bring the light back to Aragoa?', '28.10.2025', 'Bloomsbury', ARRAY['Englisch']::text[], 373, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Academia']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Kingdom of Aragoa', ARRAY['Single POV','1P']::text[], ARRAY['Viola Sinclair','Roze Roquelart']::text[], ARRAY['Enemies to Lovers','Fake Dating','Fairytale Retelling']::text[], ARRAY['Gore','Tod von Familienangehörigen','Tod']::text[], '4a93afad-0971-5bdc-b666-bf90bb6cf71e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('34929291-7756-5d02-89e5-9e5ac5a7f8da', :'owner', 'b4a514fd-e37e-52fc-b3c9-aecddea04239', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['Taschenbuch','eBook']::text[], 'Normal', ARRAY['Pronounciation Guide']::text[], 899, false, false, '{}', '{}', NULL, NULL, false, 'group'::company_kind, 'middle'::verdict_kind, 2.5, 'untertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Hm, leider fand ich Viola sehr nervig. Ständig hat sie sich ohne Ahnung und Plan in Gefahren gestürzt und nichts hinbekommen. Letztendlich klappt alles nur aus Glück und Zufall. Roze mochte ich jedoch sehr gerne. Aber ja, leider war mir alles zu "dramatisch" und zu wenig dahinter.') on conflict do nothing;
