insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9b2e0706-5c13-55c9-b3e5-9c6347d0e9a1', 'Meridian - Dunkle Umarmung', 'Meridian', '9783426283011', 'Mein Name ist Meridian. Ich gehöre leider nicht zu den Mädchen, die man gerne zu Geburtstagsfeiern einlädt – denn obwohl ich es ganz sicher nicht will, muss ich mein Leben mit dem Tod teilen. Ich bin eine Fenestra: Durch mich gelangen die Seelen der Verstorbenen in den Himmel. Aber davon wusste ich nichts, bis ich sechzehn Jahre alt wurde – und plötzlich in großer Gefahr schwebte …', '05.10.2009', 'Pan', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Meridian']::text[], '{}', '{}', '44f1b2d8-31d1-5180-87e6-8aeb1c85a28a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
