insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9dda2865-1aab-57aa-adfe-beba89c9a7aa', 'Meridian - Flüsternde Seelen', 'Meridian - Wildcat Fireflies', '9783426283653', 'Das Mädchen Meridian schwebt in größter Gefahr: Als Fenestra ist es ihre Aufgabe, den Seelen der Verstorbenen den Weg in dem Himmel zu weisen – doch sie hat dunkle Gegenspieler, die dies verhindern wollen. Auf der Flucht vor den Aternocti gelangt Meridian in eine friedlich wirkende Kleinstadt, in der sie die Gegenwart einer anderen Fenestra spürt. Kann sie diese finden, bevor die Aternocti es tun?', '01.12.2011', 'Pan', ARRAY['Deutsch']::text[], 425, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Meridian']::text[], '{}', '{}', '44f1b2d8-31d1-5180-87e6-8aeb1c85a28a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
