insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c6b5eeaa-958d-5eaf-8d50-75555eee2b6c', 'The Book of Azrael', NULL, '9781035414505', 'Many centuries ago, desperate to save her dying sister, Dianna made a deal with Kaden, a monster far worse than any nightmare. Locked in servitude to him, she is forced to hunt down an ancient relic held by her most dangerous enemies: an army led by Samkiel, the World Ender. After the Gods War, Samkiel hid from everything, denying his crown and deserting his people. Now, an attack on those he loves sends him back to the realm he never wished to return to, and into the sights of an enemy he had hoped to forget. With every world at stake, Dianna and Samkiel are forced to set aside their animosity and work together, before all is lost . . .', '08.01.2024', 'Headline Eternal', ARRAY['Englisch']::text[], 577, 51, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Dianna','Liam']::text[], '{}', '{}', 'ad7b51c1-fa39-5beb-b3bd-37c6bf9beca7', '1', '{}', 'sheet', :'owner') on conflict do nothing;
