insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('65ee7876-13a1-593e-adcf-31432d9c0ea0', 'The Throne of Broken Gods', NULL, '9798986305042', 'When I burn this world to embers, and you paint me as the villain, remember, I really did try to be good . . . once. Dianna is hellbent on revenge. As the last shred of her humanity is ripped from her, she decides to embrace her monstrous side and set the worlds alight. Samkiel alone refuses to believe that she has become the monster that everyone else sees, and he''ll do anything in his power to save her from herself, even if it means losing her.', '18.01.2024', 'Rose & Star', ARRAY['Englisch']::text[], 616, 93, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Dianna','Liam']::text[], '{}', '{}', 'ad7b51c1-fa39-5beb-b3bd-37c6bf9beca7', '2', '{}', 'sheet', :'owner') on conflict do nothing;
