insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e17e1194-4567-5cde-864f-e77a75b3c5e2', 'The Dawn of the Cursed Queen', NULL, '9781962599955', 'Ask her what she ripped from the very heavens. And then ask her if she cares. Betrayed and bloodied, The Hand has failed. After a desperate battle, Nismera, the Goddess of War, now rules the realms as the last remnants of Samkiel''s power spill across the sky. Desperate to keep Samkiel safe after almost losing him, Dianna is willing to give up everything to protect him, even if that means sacrificing their relationship itself. But that''s not a risk Samkiel is willing to take, even as the stakes grow ever higher. The one true king is poised to return, but when the dust settles, who will truly rule?', '28.05.2024', 'Rose & Star', ARRAY['Englisch']::text[], 578, 106, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Dianna','Liam']::text[], '{}', '{}', 'ad7b51c1-fa39-5beb-b3bd-37c6bf9beca7', '3', '{}', 'sheet', :'owner') on conflict do nothing;
