insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cbf1719e-fc59-56c3-93e4-cc931be7f61b', 'Haus von Stein', 'The House of the Stone', NULL, 'Als Raven bei der Auktion ersteigert wird, weiß sie sofort, dass es nicht gutgehen wird. Und als sie im Palast der Gräfin ankommt, findet Raven bald heraus, dass die Gräfin weniger an einem Baby interessiert ist, als daran, mit Ravens Körper und Verstand zu experimentieren. Raven kann nur auf eine Fluchtmöglichkeit hoffen – und darauf, Violet wiederzusehen. Während all dessen, was sie durchleiden muss, erinnert sie sich selbst stets daran, dass sie Raven Stirling ist und niemandem gehört.', '25.08.2016', 'Fischer', ARRAY['Deutsch']::text[], 67, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Raven']::text[], '{}', '{}', '046f4e19-af66-50eb-8913-848fa5334a8e', '2.5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
