insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ab4f4483-7a02-5062-bc0f-f6ae2697978f', 'Das Juwel - Der Schwarze Schlüssel', 'The black Key', '9783841440198', 'Violet und der Geheimbund Der Schwarze Schlüssel bereiten einen Angriff auf den Adel vor, und Violet soll eine zentrale Rolle dabei spielen. Sie muss die jungen Frauen anführen, die die Auktion manipulieren und die Mauern der Einzigen Stadt zum Einstürzen bringen sollen. Doch Violet ist hin- und hergerissen. Ihre Schwester Hazel ist im Palast der Herzogin vom See gefangen. Um ihre Schwester zu retten, muss sie ihre Freunde und die gute Sache im Stich lassen und in das Juwel zurückkehren.', '27.04.2017', 'Fischer', ARRAY['Deutsch']::text[], 394, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Violet Lasting']::text[], '{}', '{}', '046f4e19-af66-50eb-8913-848fa5334a8e', '3', '{}', 'sheet', :'owner') on conflict do nothing;
