insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9f9f5a40-de45-5d64-8f56-c8410e726278', 'Das Juwel - Die Gabe', 'The Jewel', '9783841421043', 'Violet lebt in Armut, aber sie hat eine besondere Gabe. Eine Gabe, die ihre Chance und ihr Fluch zugleich ist … Violet Lasting ist etwas Besonderes. Sie kann durch bloße Vorstellungskraft Dinge verändern und wachsen lassen. Deshalb wird sie auserwählt, ein Leben im Juwel zu führen. Sie entkommt bitterer Armut und wird auf einer großen Auktion an die Herzogin vom See verkauft, um bei ihr zu wohnen. Eine faszinierende, prunkvolle Welt erwartet sie. Doch das neue Leben fordert ein großes Opfer von ihr: gegen ihren Willen und unter Einsatz all ihrer Kraft soll sie der Herzogin ein Kind schenken. Wie soll Violet in dieser Welt voller Gefahren und Palastintrigen bestehen? Als sie sich verliebt, setzt sie nicht nur ihre eigene Freiheit aufs Spiel.', '20.08.2015', 'Fischer', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Violet Lasting']::text[], '{}', '{}', '046f4e19-af66-50eb-8913-848fa5334a8e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
