insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e97c21f1-f8dd-54a3-9a97-e51c4bf7ca4e', 'Von der Nacht verzaubert', 'Die for Me', '9783732000906', 'Als Kate Merciers Eltern bei einem tragischen Unfall sterben, zieht sie zusammen mit ihrer Schwester Georgia zu den Großeltern nach Paris. Jede versucht auf ihre eigene Weise, ihr altes Leben und ihre schmerzvollen Erinnerungen hinter sich zu lassen. Während Georgia sich in das Nachtleben stürzt, sucht Kate Zuflucht in ihren Büchern - bis sie eines Tages Vincent trifft, der es schafft, ihren Schutzpanzer zu durchbrechen. Bei Spaziergängen entlang der Seine und durch die spätsommerlichen Gassen von Paris beginnt Kate, sich in ihn zu verlieben - nur um kurze Zeit später zu erfahren, dass Vincent ein Revenant ist. Die Liebe der beiden steht unter einem schlechten Stern: Vincent und seine Freunde sind in einen jahrhundertealten Kampf gegen eine Gruppe rachsüchtiger Revenants verstrickt. Schnell begreift Kate, dass ihr Leben niemals wieder sicher sein wird, wenn sie ihrem Herzen folgt.', '27.01.2014', 'Loewe', ARRAY['Deutsch']::text[], 370, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Paris', '{}', ARRAY['Kate Merciers']::text[], '{}', ARRAY['Tod von Familienangehörigen']::text[], '60cf5d5c-2ad3-5bd4-a253-84f624c8d818', '1', '{}', 'sheet', :'owner') on conflict do nothing;
