insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f6a61391-9ebe-5b7c-a6b6-35487d177c67', 'If We Ever Meet Again', NULL, NULL, '19-year-old Farrah Lin is going to fall in love for the first time during her year abroad in Shanghai. She''s sure of it. The only problem? Her would-be leading man is her new friend’s boyfriend. There’s nothing worse than being in love with someone you can’t have...or at least, she thinks it’s love. But if that’s true, why can’t she stop fantasizing about someone else, specifically the cocky blond athlete with the world’s biggest ego (and greatest dimples)?', '30.06.2023', 'Little, Brown Books', ARRAY['Englisch']::text[], 289, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Farrah Lin','Blake Ryan']::text[], ARRAY['Sport','Friends to Lovers']::text[], '{}', 'b0259a60-ee05-5503-a2ac-110a8693b163', '1', '{}', 'sheet', :'owner') on conflict do nothing;
