insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2be213f9-dd4c-50a7-b2c3-a4750177c084', 'The Striker', NULL, '9783736323278', 'Asher Donovan ist eine Legende - der Liebling der Premier League und der beste Fußballer der Welt. Doch die Teilnahme an illegalen Autorennen und der kürzliche Wechsel mitten in der Saison haben seinen Ruf angekratzt. Und als seine Rivalität mit einem Mannschaftskameraden dazu führt, dass sein neues Team die Meisterschaft verliert, werden er und sein Kontrahent zu einem gemeinsamen Training während der Sommerpause verdonnert. Das Problem? Bei der Trainerin handelt es sich nicht nur um die Frau, die er kurz zuvor in seinem Lieblingspub kennengelernt und die ihn auf den ersten Blick fasziniert hat, sondern Scarlett DuBois ist auch die Schwester seines Rivalen - und damit absolut tabu.', '16.12.2024', 'LYX', ARRAY['Deutsch']::text[], 717, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Asher Donovan','Scarlett DuBois']::text[], ARRAY['Sport','Forbidden Love','Rivals to Lovers']::text[], ARRAY['Krankheit','Tod','Tod von Familienangehörigen']::text[], '8ecde590-6011-5bd2-bc97-81a83f65faab', '1', '{}', 'sheet', :'owner') on conflict do nothing;
