insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('82b06a8a-d468-59b3-ac1b-bb9981a0f5ef', 'Twisted Games', NULL, '9783736319158', 'Gefangen von den Fesseln der Pflicht hat Bridget von Ascheberg, Prinzessin von Eldorra, nur drei Wünsche: Liebe, Leidenschaft und ihre eigenen Entscheidungen treffen zu dürfen. Doch als ihr Bruder seinen Anspruch auf den Thron aufgibt, findet sie sich auf einmal als zukünftige Königin wieder. Ein Titel, den sie nie wollte. An ihrer Seite der Mann, dem ihr Herz gehört, aber den sie nicht lieben darf: Rhys Larsen, ihr Bodyguard, ihr Beschützer, ihr Ruin. Ihre verbotenen Gefühle könnten sie beide in den Untergang treiben - und ihr Königreich zerstören.', '28.04.2023', 'LYX', ARRAY['Deutsch']::text[], 648, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Bridget von Ascheberg','Rhys Larsen']::text[], ARRAY['Forbidden Love','Royalty']::text[], ARRAY['Kindesmishandlung','Tod','Drogenmissbrauch']::text[], 'dd6a8e65-e476-5151-955d-8b6f9b01cc80', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
