insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5a2bdcf2-7379-54ca-a35e-0d242770eddf', 'Twisted Dreams', 'Twisted Love', '9783736319127', 'Als der beste Freund ihres Bruders in ihr Nachbarhaus zieht, ändert sich Ava Chens Leben von Grund auf. Alex Volkov sieht aus wie die Sünde und ist kalt wie Eis. Aber Ava schafft es, seine Mauern Stein um Stein einzureißen, und je besser sie den Multimillionär kennenlernt, desto weniger kann sie sich seiner Anziehungskraft entziehen. Schon bald kann auch Alex die ungewohnten Gefühle nicht länger leugnen. Doch er hat eine dunkle Vergangenheit, der er nicht entfliehen kann und die eine Liebe zwischen ihnen unmöglich macht ...', '23.12.2022', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ava Chens','Alex Volkov']::text[], ARRAY['Enemies to Lovers','Brother''s Best Friend','Forbidden Love']::text[], ARRAY['Mord','Physische Gewalt']::text[], 'dd6a8e65-e476-5151-955d-8b6f9b01cc80', '1', '{}', 'sheet', :'owner') on conflict do nothing;
