insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('27d7e870-4b50-5db3-ab47-3236b4037c5c', 'Twisted Lies', NULL, '9783736320727', 'Stella Alonso ist trotz ihrer Bekanntheit in den sozialen Medien eine schüchterne, introvertierte junge Frau. Neben ihren zwei Jobs hat sie weder die Zeit noch die Kapazitäten für die Liebe oder eine Beziehung. Doch eine Bedrohung aus ihrer Vergangenheit treibt sie direkt in die Arme - und das Penthouse - von Christian Harper, der seit ihrer ersten Begegnung von Stella fasziniert ist. Unter den perfekt sitzenden Anzügen verbirgt der CEO von Harper Security seine dunkelsten Seiten, aber Stella ist die eine Schwäche, die er sich erlaubt. Allerdings könnten die Geheimnisse, die er ihr verschweigt, alles zwischen ihnen zerstören ...', '25.08.2023', 'LYX', ARRAY['Deutsch']::text[], 662, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Stella Alonso','Christian Harper']::text[], ARRAY['Fake Dating']::text[], ARRAY['Krankheit','Suizidalität','Psychische Erkrankung/Belastung','Tod']::text[], 'dd6a8e65-e476-5151-955d-8b6f9b01cc80', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
