insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('42756df6-9edc-5df3-991a-3344c791f9d8', 'Novel Haven - Levels of Love', NULL, '9783736323285', 'Sie dürfen nicht verlieren - schon gar nicht ihr Herz. Zwei Konkurrenten. Lara vs. Luca. Unsicher vs. Selbstsicher. Cosy Game gegen Horror Game. Sie könnten nicht unterschiedlicher sein und verarbeiten doch beide ihre ganz eigenen Ängste in ihren Spielen. Ein Wettbewerb. Die GameChanger-Convention ist ihre Chance auf Anerkennung, Sichtbarkeit - und das dringend benötigte Preisgeld. Unzählige Gefühle. Hinter der Fassade aus Ehrgeiz und Konkurrenz sehnen sich Lara und Luca nach jemandem, der sie auch abseits der Bildschirme versteht. Sie könnten perfekt füreinander sein - doch am Ende kann nur einer gewinnen und seinen Traum verwirklichen ...', '27.05.2025', 'LYX', ARRAY['Deutsch']::text[], 445, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lara','Luca']::text[], ARRAY['Rivals to Lovers','Forced Proximity']::text[], ARRAY['Depiction of Trauma','Belästigung']::text[], '379fb017-66d5-57b3-9bc9-bb6626f259a4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
