insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b82deab-8382-5266-b51e-1ea05ed1247c', 'Dreams of Sapphire Seas', NULL, '9783736320468', 'Für Serena geht ein Traum in Erfüllung, als sie dank eines Stipendiums ihr Kunststudium im irischen Cork fortsetzen kann. In der Obdachlosenhilfe vor Ort findet sie zudem ein neues Herzensprojekt, dem sie sich mit Feuereifer verschreibt. Nur die Wohnungssuche erweist sich als schwierig. Mit viel Glück ergattert sie ein Zimmer in einer turbulenten Männer-WG. Es gibt nur eine Regel: Sie darf mit keinem der Jungs etwas anfangen. So weit, so gut, wäre da nicht ihr neuer Mitbewohner Aedan, der ihr Herz mit seinen zahlreichen Tattoos und dem warmen Lächeln gewaltig zum Rasen bringt. Was sie nicht ahnt: Die WG-Regel bleibt nicht das Einzige, was zwischen ihnen steht ...', '28.03.2024', 'LYX', ARRAY['Deutsch']::text[], 431, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Irland, Cork', '{}', ARRAY['Serena','Aedan']::text[], ARRAY['Forbidden Love','Grumpy x Sunshine','Universicy/College']::text[], '{}', '8c5f6b53-aaf0-508d-a189-b5bb46b21a62', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
