insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8a6494ba-dbb0-51c5-9cc5-9aeee36b6e75', 'Novel Haven - Match of Fate', NULL, '9783736325241', 'Sonst spielt er E-Sport -- jetzt ihren Freund. Ihr Plan. Fake Dating mit dem Feind. Dylan, ein berühmter E-Sportler, ruiniert Natalys ersten Livestream von Novel Haven und sorgt für einen viralen Shitstorm. Um die Wogen zu glätten, scheint Fake Dating die beste Lösung. Sein Plan. Die E-Sport-Championships gewinnen. Dank des Skandals mit Nataly sind Dylans Sponsoren verärgert, und um seinen Ruf zu retten, lässt er sich auf Natalys Idee einer Scheinbeziehung ein. Nicht Teil des Plan. Sich verlieben!', '31.10.2025', 'LYX', ARRAY['Englisch']::text[], 489, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dylan','Nataly']::text[], ARRAY['Fake Dating','Enemies to Lovers','Forced Proximity']::text[], ARRAY['Toxische Beziehungsdynamiken','Drogenmissbrauch']::text[], '379fb017-66d5-57b3-9bc9-bb6626f259a4', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
