insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('43665b17-59f9-5d45-ac38-ed143dc53526', 'Songs of Emerald Hills', NULL, '9783736320703', 'Eine Weile Abstand von allem - insbesondere den schmerzhaften Erinnerungen an ihre beste Freundin -, das erhofft Caroline sich von ihrem Aufenthalt in Irland. Idealerweise findet sie auf der grünen Insel endlich heraus, was sie eigentlich will vom Leben. Wen sie will, merkt sie früher, als ihr lieb ist: Conor, der Nachbar ihrer etwas schrulligen Gastgeberin, verdreht ihr nämlich vom ersten Tag an den Kopf. Als sie zusammen ein Gälisch- Festival auf die Beine stellen, um Conors Sprachschule zu retten, kann auch dieser nicht länger leugnen, dass er sich zu Caro hingezogen fühlt. Doch sie wird bald nach Deutschland zurückkehren, und so wehrt er sich mit aller Macht gegen die aufkommenden Gefühle, denn Verluste hatte er in seinem Leben bereits genug ...', '27.10.2023', 'LYX', ARRAY['Deutsch']::text[], 428, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Irland', '{}', ARRAY['Caroline','Conor']::text[], ARRAY['Forced Proximity','Small Town']::text[], '{}', '8c5f6b53-aaf0-508d-a189-b5bb46b21a62', '1', '{}', 'sheet', :'owner') on conflict do nothing;
