insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('01b19094-3bf7-596b-87ee-d4728efd062f', 'Kyria & Reb - Bis ans Ende der Welt', NULL, NULL, 'Kyria hat im Überwachungsstaat New Europe eine vielversprechende Zukunft vor sich. Doch als sie erfährt, dass die tödliche Krankheit, die schon seit ihrer Kindheit in ihr schlummert, auszubrechen droht, hat sie nur noch einen Wunsch: die ihr verbleibende Zeit in Freiheit zu verbringen. Gemeinsam mit dem Draufgänger Reb flieht sie in die unabhängigen Reservate, aber das System ist ihnen dicht auf den Fersen. Wird es Kyria und Reb dennoch gelingen, ihren Traum zu verwirklichen?', '09.02.2012', 'Ink', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Kyria','Reb']::text[], '{}', '{}', '23cfcfba-301c-5866-80a8-ffc9ba6d58e4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
