insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('469758d7-0bbb-5a12-ad30-56d619d23952', 'Kyria & Reb - Die Rückkehr', NULL, NULL, 'Nach ihrer Flucht aus dem Überwachungsstaat New Europe leben Kyria und Reb das erste Mal in Freiheit. Doch als Kyria erfährt, dass ihr Vater nicht seiner tödlichen Krankheit erlag, sondern einem Mordanschlag zum Opfer fiel, trennt sie sich schweren Herzens von ihrer großen Liebe. Sie kehrt zurück in ihre Heimatstadt, um die Mörder zu finden. Dabei beginnt sie allmählich, das Netz der dunklen Machenschaften von New Europe zu durchschauen, und gerät selbst in große Gefahr - doch da taucht Reb wieder auf. Wird es ihnen zusammen gelingen, dem mörderischen Komplott zu entfliehen?', '10.01.2013', 'Ink', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Kyria','Reb']::text[], '{}', '{}', '23cfcfba-301c-5866-80a8-ffc9ba6d58e4', '2', '{}', 'sheet', :'owner') on conflict do nothing;
