insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d8ccee93-ce54-5557-b5d9-1ae0ccc2ce45', 'The Bone Shard Daughter', NULL, '9780356514949', 'The Emperor''s reign has lasted for decades, his mastery of bone shard magic powering the animal-like constructs that maintain law and order. But now his rule is failing, and revolution is sweeping across the Empire''s many islands. Lin is the Emperor''s daughter and she spends her days trapped in a palace of locked doors and dark secrets. When her father refuses to recognise her as heir to the throne, she vows to prove her worth by mastering the forbidden art of bone shard magic. Yet such power carries a great cost, and when the revolution reaches the gates of the palace, Lin must decide how far she is willing to go to claim her birthright - and save her people.', '10.09.2020', 'Orbit', ARRAY['Englisch']::text[], 435, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Lin']::text[], '{}', '{}', '19b76ce5-c30d-59b7-9b83-9b6b602781a4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
