insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4d51d292-fd3a-580d-8bb2-97bdb73a5eae', 'Der schlauste Mann der Welt', NULL, '9783404193141', 'Jens Leunich besitzt nur so viel, wie in zwei Koffer passt - und außerdem genug Millionen auf dem Konto, um sein ganzes Leben in den Luxushotels der Welt zu verbringen. Abgesehen davon tut er - nichts. Gar nichts. Denn nichts zu tun, hat er erkannt, ist der beste Weg, die Welt zu retten. Bloß ist nichts zu tun nicht so einfach, wie die meisten denken. Diese und andere schlaue Einsichten will er nun niederschreiben - doch ganz gegen seine Gewohnheiten muss er sich damit beeilen, denn er hat nur noch zehn Tage zu leben ...', '30.08.2024', 'Lübbe', ARRAY['Deutsch']::text[], 222, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Jens Leunich']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
