insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('33ba732b-e69b-5e0a-b391-0b6694517b5b', 'Die Abschaffung des Todes', NULL, '9783757700515', 'Drei hochkarätige Unternehmer aus dem Silicon Valley wollen ein zweites »Manhattan Projekt« ins Leben rufen. Nur ist das Ziel noch ehrgeiziger als damals die Entwicklung der Atombombe: Sie wollen den Tod selbst abschaffen. Der Journalist James Windover entdeckt jedoch, dass die Unternehmer, während sie von Investoren Milliarden sammeln, insgeheim versuchen, einen Schriftsteller zum Schweigen zu bringen - weil sie eine Story fürchten, die er geschrieben hat. Was steht darin, das das Projekt gefährden könnte? James begibt sich auf die Suche nach dem Mann und gerät rasch selbst in tödliche Gefahr... Wenn Künstliche Intelligenz erst der Anfang ist. Ein atemberaubender Thriller um die Frage: Welche Gefahren - und Möglichkeiten - birgt das Künstliche Bewusstsein?', '30.08.2024', 'Lübbe', ARRAY['Deutsch']::text[], 654, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, 'Silicon Valley', '{}', ARRAY['James Windover']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
