insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ccb7d62-2d27-5bb8-8932-d99f0618b778', 'The Egg', NULL, NULL, 'short story about the universe and your place in it. “You were on your way home when you died. It was a car accident. Nothing particularly remarkable, but fatal nonetheless. You left behind a wife and two children. It was a painless death. … And that’s when you met me.” The Egg is a short story written by Andy Weir, his most popular, and follows a nameless 48-year-old man who discovers the “meaning of life” after he dies. The story is about “you” (in the second person), and God, who is “me” (in the first person). God says that you have been reincarnated many times before, and that you are soon to be reincarnated once more, leading to quite a few existential questions.', '14.08.2009', NULL, ARRAY['Englisch']::text[], 3, 1, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Philosophie', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Afterlife', ARRAY['Single POV','1P']::text[], ARRAY['God']::text[], '{}', ARRAY['Tod']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
