insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0f98ea5b-f25f-5285-aa19-de78e87d13fc', 'Der Untergang der Hexenjäger', NULL, '9783743116207', 'Ganz Caldon ächzt unter dem Joch der Hexenjäger, die gnadenlos Dunkelvölker, unkontrollierte Magie und Freidenker verfolgen. Nur wenige wagen, etwas dagegen zu unternehmen. Eine von ihnen ist Kenzie, deren Aktivitäten im Widerstand deutlich komplizierter werden, als ausgerechnet ihr bester Freund den Hexenjägern beitritt.', '20.06.2023', NULL, ARRAY['Deutsch']::text[], 440, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, NULL, 'Caldon', '{}', ARRAY['Kenzie']::text[], '{}', '{}', 'aaae072c-d571-5d81-bc40-57a1d5f378df', '1', '{}', 'sheet', :'owner') on conflict do nothing;
