insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('49524ac4-b330-506b-8ff5-65a143b0bfc2', 'Nachhilfe in Erster Liebe', NULL, '9783570400654', 'Katja ist total verknallt. Kein Wunder, denn Jan ist ein echter Traumtyp: sportlich, gut aussehend und ... einfach perfekt! Weshalb Katja nie den leisesten Hauch einer Chance bei ihm haben wird – findet sie. Und offensichtlich auch Jan, denn warum sonst will er unbedingt verheimlichen, dass Katja ihm Nachhilfe gibt? Dabei sind ihre Treffen doch viel mehr als nur trockene Vokabel-Paukerei. Oder doch nicht ...? Katja hält schweren Herzens dicht, auch wenn sie das gegenüber ihren Freundinnen in immer brenzligere Situationen bringt. Aber dann platzt die Bombe trotzdem und Jan ist stinksauer – doch der Grund dafür lässt Katjas Herz höher schlagen ...', '09.01.2012', 'cbj', ARRAY['Deutsch']::text[], 224, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Katja','Jan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
