insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3271d918-051e-517a-948f-3bcf27e984ec', 'A Sicilian Romance', NULL, '9781518328374', 'Set on the northern shores of Sicily, related by a tourist visiting the ruins of the family’s formerly grand castle, the novel recounts the history of the Mazzini family. Julia, daughter of the Marquis, falls for count Hippolitus, but when promised by her father to another, she attempts to elope with her lover. A thrilling literary classic, and an unmissable read.', '1790', NULL, ARRAY['Englisch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', ARRAY['Gothic']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Sizilien', '{}', ARRAY['Ferdinand Mazzini']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
