insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2d093d2e-c142-50f6-ba6f-bc15c78e1a3e', 'Blue Secrets - Der Kuss des Meeres', 'Of Poseidon', '9783641107161', 'Als Emma den süßen Galen zum ersten Mal sieht, fallen ihr sofort seine violetten Augen auf – denn ihre haben dieselbe Farbe. Und tatsächlich bergen sie ein Geheimnis: Galen ist nämlich ein Syrena, Prinz der Meere, und er spürt eine heftige Anziehung zu diesem Menschenmädchen, das mit den Fischen reden kann! Das kann nur eines bedeuten: Auch in ihren Adern fließt das Blut der Syrena. Doch falls sein Verdacht sich bestätigt, ist Emma eine Erbin Poseidons – und damit für einen anderen bestimmt …', '09.09.2013', 'cbt', ARRAY['Deutsch','Englisch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Emma','Galen']::text[], '{}', '{}', 'd2721034-d339-579a-9725-27a7678d9385', '1', '{}', 'sheet', :'owner') on conflict do nothing;
