insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a2580a54-6c04-5c3a-a6bd-ab21665fa7ae', 'Blue Secrets - Das Flüstern der Wellen', 'Of Triton', '9783641128760', 'Emmas Leben droht sich buchstäblich in den Wellen des Meeres zu verlieren. Denn ihre Mutter entpuppt sich als verloren geglaubte Königstochter der Syrena, was zugleich bedeutet, dass Emma ein Halbblut ist! Nach den Gesetzen der Ozeane ist sie damit dem Tode geweiht. Während die Rückkehr ihrer Mutter die Zwietracht zwischen den Meeresvölkern wieder aufflammen lässt, versucht Emmas große Liebe, Prinz Galen, sie um jeden Preis zu schützen und ihr Geheimnis zu hüten. Doch Emma weiß, dass sie das Volk der Syrena retten kann – nur dazu muss sie ihr wahres Wesen enthüllen ...', '14.04.2014', 'cbt', ARRAY['Deutsch','Englisch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Emma','Galen']::text[], '{}', '{}', 'd2721034-d339-579a-9725-27a7678d9385', '2', '{}', 'sheet', :'owner') on conflict do nothing;
