insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eacf7dfc-8866-5929-9d34-6fccc9fd51a4', 'Blue Secrets - Der Ruf des Ozeans', 'Of Neptune', '9783641150082', 'Emma und Galen brauchen etwas Zeit für sich. Allein. Weit weg von den Königreichen Triton und Poseidon. Emmas Großvater, der König von Poseidon, schlägt den beiden vor, eine kleine Stadt namens Neptun zu besuchen. Neptun ist die Heimat von Syrena und Halbblütern, die sich alles andere als wohlgesonnen sind. Emma und Galen geraten zwischen die Fronten. Sie treffen auf das Halbblut Reed, der seine Gefühle für Emma nicht lange verbergen kann. Plötzlich befinden sich Emma und Galen mitten in einem Machtkampf, der nicht nur ihre Liebe bedroht sondern auch ihre Königreiche.', '14.04.2015', 'cbt', ARRAY['Deutsch','Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Emma','Galen']::text[], '{}', '{}', 'd2721034-d339-579a-9725-27a7678d9385', '3', '{}', 'sheet', :'owner') on conflict do nothing;
