insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('870449db-390b-552a-911f-e409132a93d9', 'Legacy Lost', NULL, '9781466820098', 'He is a mer-prince, she is the mermaid princess that his family orders him to marry so that their kingdoms unite. Grom dreads this arrangement, until he meets Nalia – both beautiful and smart, she''s everything he ever wanted. But just when their connection grows deeper, tragedy strikes.', '22.05.2012', 'Tor Books', ARRAY['Englisch']::text[], 48, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Nalia','Grom']::text[], '{}', '{}', 'b82de9c2-2e3f-5a9f-9444-886657590afe', '4', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
