insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2065ef60-ffef-5ccc-b64a-e1e1713b49d4', 'Das Licht von Aurora', 'Tandem', '9783732002474', 'Ich hatte nicht das Gefühl, als würde er nach Aurora gehören. Ich hatte eher das Gefühl, als würde er zu mir gehören, egal wo ich war. Aber das lag ja nicht in meiner Hand und in seiner auch nicht. Schon immer wollte die 16-jährige Sasha in die Rolle ihrer liebsten Romanheldinnen schlüpfen und Abenteuer in fernen Welten erleben. Nicht ahnend, dass die Geschichten ihres Großvaters über Parallelwelten tatsächlich wahr sind, landet sie plötzlich unfreiwillig in Aurora - einer modernen Monarchie. Neben einem Leben am Hofe erwartet Sasha hier auch die ganz große Liebe. Doch Palastintrigen und Verrat drohen ihre Träume zu zerstören... Einmal Prinzessin sein! Der erste Roman in Anna Jarzabs spannender Jugendbuch-Reihe entführt Leser in eine Parallelwelt, in der eine Monarchie herrscht. Eine Geschichte voller Fantasy, Romantik, Geheimnisse und Verrat - für alle Fans der Bestseller-Trilogie Selection.', '22.06.2015', 'Loewe', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'YA'::audience_kind, NULL, 'Aurora', '{}', ARRAY['Sasha']::text[], '{}', '{}', '31e49f98-3601-50dc-9357-5598b06c34da', '1', '{}', 'sheet', :'owner') on conflict do nothing;
