insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7fbc6cb-b36f-531e-a946-0091756dedf5', 'Das Licht von Aurora - Im Schatten der Welten', 'Tether', '9783732004911', 'Einmal Prinzessin und zurück! Die spannende Fortsetzung von Anna Jarzabs Jugendbuch-Reihe Das Licht von Aurora überzeugt durch märchenhafte Parallelwelten, politische Machtkämpfe und eine weltenübergreifenden Liebesgeschichte. Romantische Mädchenfantasy, die nicht nur Fans von Selection und Die rote Königin lieben werden! Verzweifelt versucht Sasha zurück nach Aurora und zu ihrer großen Liebe zu gelangen. Aber in der Parallelwelt wartet nicht nur Thomas sehnsüchtig auf sie, sondern auch Selene, die dringend Sashas Unterstützung benötigt. Doch um Selene zu helfen, müsste Sasha das Königreich erneut verlassen. Soll sie ihrem Schicksal folgen, auch wenn sie das ihre große Liebe kosten könnte?', '15.02.2016', 'Loewe', ARRAY['Deutsch']::text[], 360, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'YA'::audience_kind, NULL, 'Aurora', '{}', ARRAY['Sasha']::text[], '{}', '{}', '31e49f98-3601-50dc-9357-5598b06c34da', '2', '{}', 'sheet', :'owner') on conflict do nothing;
