insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8d647bb5-448d-54cf-8298-92c5ad10c066', 'Lichterzauber in Schweden', NULL, '9783453426757', 'Lilje wird nach Jokkmokk in den hohen Norden Schwedens geschickt, um für das Online-Magazin eines Tourismusunternehmens über den traditionellen Wintermarkt der Sámi zu berichten. Dort angekommen gibt es jedoch eine böse Überraschung: Das Hotel ist überbucht, und Lilje muss sich ein Zimmer mit Juha teilen. Juha ist als Sohn eines Rentierzüchters aufgewachsen, und lebt als Wissenschaftler in Stockholm. Während er Lilje die atemberaubende Schönheit des verschneiten Lapplands zeigt, kommen sich die beiden näher. Doch dann erfährt Lilje, dass Juha ihr etwas verschwiegen hat. Kann der Zauber der Polarnacht die beiden doch noch zusammenführen?', '13.09.2023', 'Heyne', ARRAY['Deutsch']::text[], 413, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Jokkmokk', '{}', ARRAY['Lilje','Juha']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
