insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('250787c1-9273-5c63-8aaf-55e43a2a71f0', 'Hold Me', NULL, '9783736317239', 'Als Zoe die Zusage für die renommierte New England School of Ballet erhält, erfüllt sich ihr größter Traum - auch wenn das bedeutet, dass sie dort Jase wiedersieht. Den Jungen, dem all ihre Wahrheiten gehören. Alle außer einer: warum sie vor einem Jahr den Kontakt zu ihm abbrach. Deswegen ist Jase auch überhaupt nicht begeistert, ihr plötzlich jeden Tag an der Schule zu begegnen. Denn neben seinen Eltern, die seinen Traum vom Tanzen nicht akzeptieren, braucht er nicht auch noch Zoe, die ihn an alles erinnert, was er verloren hat. Doch als Zoe Jase als Tanzpartnerin zugeteilt wird, kommen sie sich unweigerlich näher - genauso wie ihrer gemeinsamen Vergangenheit, die sie beide bis heute nicht vergessen konnten ...', '24.02.2023', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New England School of Ballet', '{}', ARRAY['Zoe','Jase']::text[], ARRAY['Rivals to Lovers','Forced Proximity','Second Chance','Academy','Universicy/College','Sport']::text[], ARRAY['Rape','Psychische Erkrankung/Belastung','Tod']::text[], 'e103726b-acca-54b0-b4b8-3604ebcbb21a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
