insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f3a55add-0fbf-5a9c-8513-60d34c2d02e3', 'Beyond Shattered Moons', NULL, '9783736321632', 'DANACH bin ich nach Hause gekommen. DANACH setzen wir die Scherben unserer Herzen wieder zusammen. DANACH finden wir, was ich verloren glaubte. DANACH ist sie meine Madelyn.', '27.05.2025', 'LYX', ARRAY['Deutsch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Madelyn Prince']::text[], ARRAY['Friends to Lovers','Second Chance']::text[], ARRAY['Unfall','Krankheit','Tod von Familienangehörigen']::text[], '823ca4df-6253-5e73-8ea6-7deb13886c2a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
