insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e4acb58-3097-57a1-96e1-dc55d2c38b3d', 'Between Fading Stars', NULL, '9783736321649', 'DAMALS habe ich ihn verlassen, um mich selbst zu retten JETZT muss ich ehrlich sein, um uns zu retten. DAMALS habe ich sie nicht aufgehalten, als sie gegangen ist. JETZT muss ich sie festhalten, wenn ich sie nicht wieder verlieren will. JETZT können wir wieder wir sein, wenn wir mutig genug sind.', '09.12.2025', 'LYX', ARRAY['Deutsch']::text[], 524, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Madelyn Prince']::text[], ARRAY['Second Chance','He falls first','Friends to Lovers']::text[], ARRAY['Psychische Erkrankung/Belastung','Physische Gewalt','Tod von Familienangehörigen']::text[], '823ca4df-6253-5e73-8ea6-7deb13886c2a', '3', '{}', 'sheet', :'owner') on conflict do nothing;
