insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('753af93f-bcd9-59fe-905a-1c9410e1c3aa', 'Beneath Broken Skies', NULL, '9783736322356', 'Für Madelyn Prince ist nichts wichtiger als ihre Arbeit im Unternehmen ihrer Familie. Doch als der renommierte Verlag plötzlich verkauft wird, stellt sie dies vor ungeahnte Herausforderungen: denn der junge Erbe des Konkurrenzverlags - und Maddies neuer Boss - ist niemand anders als Wesley Knight. Ausgerechnet Wes, in den sie in der Schule schon verliebt war, der sie aber nie wirklich beachtet hat. Wes, der trotz aller Mauern um ihr Herz tief in ihre Seele schaut. Doch je mehr Zeit die beiden miteinander verbringen, desto stärker sind die Gefühle zwischen ihnen mit einem Mal - bis ein Moment alles verändert ...', '10.02.2025', 'LYX', ARRAY['Deutsch']::text[], 512, 55, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Madelyn Prince']::text[], ARRAY['Friends to Lovers','Work Adversaries','Second Chance']::text[], ARRAY['Tod von Familienangehörigen','Unfall']::text[], '823ca4df-6253-5e73-8ea6-7deb13886c2a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
