insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('32fbdfa7-0fb2-5342-834b-a6cb3ba4856f', 'Move On', NULL, '9783736319288', 'Als die Dreharbeiten zu einer Dokumentation über die New England School of Ballet beginnen, traut Skye ihren Augen nicht! Nie im Leben hätte sie gedacht, ausgerechnet Gabriel am Set plötzlich wieder gegenüberzustehen - dem Jungen, in den sie sich Hals über Kopf verliebt hat und der ihr vor drei Jahren auf schmerzhafteste Weise das Herz gebrochen hat. Sofort werden längst vergessene Erinnerungen wach. Und so sehr Skye versucht, Gabriel aus dem Weg zu gehen, kann ihr verräterisches Herz doch nicht leugnen, dass da immer noch viel zu viele Gefühle zwischen ihnen existieren - bis ein Kuss alles ins Wanken bringt ...', '29.02.2024', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New England School of Ballet', '{}', ARRAY['Skye','Gabriel']::text[], ARRAY['Second Chance','Academy','Universicy/College','Sport']::text[], ARRAY['Drogenmissbrauch']::text[], 'e103726b-acca-54b0-b4b8-3604ebcbb21a', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
