insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e68badb5-62a4-5211-8811-95f06ad00298', 'Shine Bright', NULL, '9783736319271', 'Das Leben von Lia Winslow scheint perfekt zu sein: Sie kommt aus einer angesehenen Bostoner Familie und ist die talentierteste Tänzerin der New England School of Ballet. Doch niemand ahnt, dass sie ihre wahren Träume hinter einer Fassade aus Perfektionismus verborgen hält und das Tanzen nahezu das Einzige ist, was sie noch kontrollieren kann. Das dachte sie zumindest, bis ihr am ersten Tag ihres Abschlussjahres plötzlich Phoenix gegenübersteht. Ihn als Lehrer an ihrer Ballettschule wiederzusehen, nachdem sie vor einigen Wochen eine unvergessliche Nacht miteinander verbracht haben, ist das Letzte, was sie erwartet hat! Das zwischen ihnen darf niemals ans Licht kommen und sich auf keinen Fall wiederholen, egal wie sehr Phoenix ihr unter die Haut geht - denn auch für ihn steht weit mehr auf dem Spiel als nur sein Job ...', '27.10.2023', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New England School of Ballet', '{}', ARRAY['Lia Winslow','Phoenix']::text[], ARRAY['Secred Identity','Academy','Universicy/College','Sport']::text[], ARRAY['Tod','Unfall','Essstörung']::text[], 'e103726b-acca-54b0-b4b8-3604ebcbb21a', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
