insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('386fcac1-87c1-541a-bef4-2750e07b2c70', 'After Truth', NULL, '9783453491175', 'Zutiefst verletzt hat Tessa ihre stürmische Beziehung zu Hardin beendet. Seit sie die Wahrheit über ihn erfahren hat, fühlt sie sich verraten und gedemütigt. Sie will ihr Leben zurück – ihr Leben vor Hardin. Doch da ist die Erinnerung an seine leidenschaftliche Liebe, seine Berührungen, die hungrigen Küsse. Ihr Verlangen nach dem unberechenbaren Mann mit den grünen Augen ist immer noch zu stark. Und sie weiß, dass er sie nicht einfach aufgeben wird. Aber kann er sich ändern? Können sie einander retten, oder wird der Sturm sie in die Tiefe reißen?', '14.04.2015', 'Heyne', ARRAY['Deutsch']::text[], 764, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa Young','Hardin Scott']::text[], ARRAY['Enemies to Lovers','Miscommunication','Bad Boy X Good Girl','Second Chance']::text[], '{}', '25c51d90-1793-59b4-a995-94b9f60380d4', '2', '{}', 'sheet', :'owner') on conflict do nothing;
