insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('120b5c45-9719-580f-8277-16309a6b2413', 'After Love', NULL, '9783453491182', 'Gerade als Tessa die wichtigste Entscheidung ihres Lebens getroffen hat, ändert sich alles. Die Geheimnisse in ihrer Familie und der Streit darüber, wie ihre Zukunft mit Hardin aussehen soll, bringen alles ins Wanken. Zudem schlägt Hardin immer noch um sich, anstatt Tessa zu vertrauen, und der Kreislauf aus Eifersucht, Zorn und Verschmelzung wird immer zerstörerischer. Noch nie hatte Tessa so intensive Gefühle, war so berauscht von einem Menschen. Aber reicht die Liebe allein?', '15.06.2015', 'Heyne', ARRAY['Deutsch']::text[], 938, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Washington Central University', '{}', ARRAY['Tessa Young','Hardin Scott']::text[], ARRAY['Enemies to Lovers','Miscommunication','Bad Boy X Good Girl','Second Chance']::text[], '{}', '25c51d90-1793-59b4-a995-94b9f60380d4', '3', '{}', 'sheet', :'owner') on conflict do nothing;
