insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c45eb733-683d-5e3a-8d84-0946845fe2b0', 'After Forever', NULL, '9783453418837', 'Die Verbindung zwischen Tessa und Hardin ist so stark wie nie zuvor. Tessa ist längst nicht mehr das süße Good Girl, das sie einmal war. Und Hardin nicht mehr der unberechenbare Bad Guy, in den sie sich leidenschaftlich verliebt hat. Tessa versteht seine gequälte Seele und weiß, dass nur sie ihn beruhigen kann, wenn er ausrastet. Er braucht sie. Doch als die Vergangenheit sie wieder einholt, wird Tessa klar, dass sie ihn nicht retten kann. Zumindest nicht, ohne sich selbst zu opfern …', '10.08.2015', 'Heyne', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa Young','Hardin Scott']::text[], ARRAY['Enemies to Lovers','Miscommunication','Bad Boy X Good Girl','Second Chance']::text[], '{}', '25c51d90-1793-59b4-a995-94b9f60380d4', '4', '{}', 'sheet', :'owner') on conflict do nothing;
