insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('93487b33-bda0-5df9-81df-0fb332de511d', 'After Passion', NULL, '9783453491168', 'Tessa Young ist attraktiv und klug. Und sie ist ein Good Girl. An ihrem ersten Tag an der Washington Central University trifft sie Hardin Scott. Er ist unverschämt und unberechenbar. Er ist ein Bad Guy. Er ist genau das Gegenteil von dem, was Tessa sich für ihr Leben wünscht. Und er ist sexy, gutaussehend und zieht Tessa magisch an. Sie kann nicht anders. Sie muss ihn einfach lieben. Und sie wird nie wieder die sein, die sie einmal war. Mit exklusivem Zusatzmaterial! Dieser Band enthält einen Brief der Autorin an ihre Fans und ein bisher unveröffentlichtes Kapitel aus Hardins Sicht.', '09.02.2015', 'Heyne', ARRAY['Deutsch']::text[], 720, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa Young','Hardin Scott']::text[], ARRAY['Enemies to Lovers','Miscommunication','Bad Boy X Good Girl','Second Chance']::text[], '{}', '25c51d90-1793-59b4-a995-94b9f60380d4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
