insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a7f01b69-7b89-5fa5-8788-4ff1179bcec3', 'Mein bester letzter Sommer', NULL, '9783641164522', 'Tessa hat immer gewartet – auf den perfekten Moment, den perfekten Jungen, den perfekten Kuss. Weil sie dachte, dass sie noch Zeit hat. Doch dann erfährt das 17-jährige Mädchen, dass es bald sterben muss. Tessa ist fassungslos, wütend, verzweifelt – bis sie Oskar trifft. Einen Jungen, der hinter ihre Fassade zu blicken vermag, der keine Angst vor ihrem Geheimnis hat, der ihr immer zur Seite steht. Er überrascht sie mit einem großartigen Plan. Und schafft es so, Tessa einen perfekten Sommer zu schenken. Einen Sommer, in dem Zeit keine Rolle spielt und Gefühle alles sind …', '08.03.2016', 'Heyne', ARRAY['Deutsch']::text[], 369, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Coming of Age']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tessa','Oskar']::text[], ARRAY['Health Problems']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a71ed689-3197-51a8-936b-d47af0bc001b', :'owner', 'a7f01b69-7b89-5fa5-8788-4ff1179bcec3', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1199, NULL, NULL, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 0, 'no'::burn_kind, 'Eine Geschichte, die mir für immer in Erinnerung bleiben wird weil sie so emotional war. Ich konnte so oft nicht weiterlesen, weil ich wegen meiner Tränen nichts mehr gesehen habe. Tolle Geschichte! Ich liebe ja meine Happy Ends, aber manchmal tut es gut, zu sehen, dass nunmal nicht immer alles ein Happy End haben kann und trotzdem gut sein kann.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('1173df19-507d-5603-97e0-c9e5460341a5', 'a71ed689-3197-51a8-936b-d47af0bc001b', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9ee4742e-1eb4-5fe1-853c-d24afde2999a', 'A Night of Promises and Blood', NULL, '9783736317550', 'Als Winnie mit ihrer Schwester Sasha nach New York zog, hatte sie nur ein Ziel: ihren Vater zu finden und zu erfahren, warum er vor vierzehn Jahren plötzlich aus ihrem Leben verschwand. Doch den Mut aufzubringen, sich der eigenen Vergangenheit zu stellen, ist leichter gesagt als getan, zumal Winnie mehr denn je das Gefühl hat, ein Auge auf ihre jüngere Schwester haben zu müssen. Diese hat sich nämlich mit Jo angefreundet, einer jungen Frau, die vor Kurzem in die Wohnung nebenan eingezogen ist und die Winnie nicht nur wegen ihrer mysteriösen Ausstrahlung, sondern auch mit der Art, wie sie ihr Herz schneller schlagen lässt, gehörig verwirrt. Dabei ahnt Winnie nicht, dass Jo ein Geheimnis hat. Ein Geheimnis, das so unglaublich wie gefährlich ist - und das Winnie alles nehmen könnte, was ihr lieb ist ...', '25.01.2023', 'LYX', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Winnie']::text[], ARRAY['Bad Boy X Good Girl','Forbidden Love','Secred Identity']::text[], '{}', '2eb69c70-ea4c-57cb-9989-22ea424612e2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
