insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f15aea8b-b97f-5877-8545-26a871ce067f', 'When We Dream', NULL, '9783736313040', 'Die 19-jährige Ella lebt seit dem Tod ihrer Eltern bei ihrer älteren Schwester in Chicago. Die Stadt ist ihr zu groß, zu laut, zu voll, und am liebsten würde sich Ella mit ihren Büchern und ihrem Zeichenblock in ihr Zimmer zurückziehen und die Außenwelt, so oft es geht, vergessen. Doch dann lernt sie Jae-yong kennen. Dass er ein Mitglied der bekanntesten K-Pop-Gruppe der Welt ist, weiß sie nicht. Was sie weiß, ist, dass der junge Mann mit den tiefbraunen Augen ihre Welt von einem Moment auf den anderen aus den Angeln hebt ...', '30.04.2020', 'LYX', ARRAY['Deutsch']::text[], 408, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ella','Jae-Young']::text[], ARRAY['Famous Person','Forbidden Love']::text[], '{}', '1aa7c392-b4d5-53f1-a9cf-7d0972ee7af0', '1', '{}', 'sheet', :'owner') on conflict do nothing;
