insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('82f67873-bf59-5aa5-b3ce-c623c942f35e', 'When We Fall', NULL, '9783736313057', 'Nachdem ein Foto von ihnen im Internet aufgetaucht ist, müssen Ella und Jae-yong einsehen, dass sie nicht zusammen sein können - egal, wie sehr sie es sich auch wünschen. Ella ist eine normale Studentin aus Chicago. Jae-yong ein K-Pop-Star, der Millionen von Fans hat und dessen Management es ihm verbietet, eine Beziehung zu führen. Tief in ihrem Herzen weiß Ella, dass es richtig war, Jae-yong gehen zu lassen. Schließlich hätte sie niemals gewollt, dass er für sie seine Musikkarriere aufgibt. Und doch kann sie ihn einfach nicht vergessen ...', '28.08.2020', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ella','Jae-Young']::text[], ARRAY['Famous Person','Forbidden Love']::text[], '{}', '1aa7c392-b4d5-53f1-a9cf-7d0972ee7af0', '2', '{}', 'sheet', :'owner') on conflict do nothing;
