insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a7330d64-d814-5f89-bd01-3fbd7b914fa5', 'A Night of Shadows and Betrayals', NULL, '9783736319714', 'Selbst wenn ich es gewollt hätte - ich hätte keine Ahnung gehabt, wie ich es ihr hätte näher bringen sollen: dass ich in ihrer Gegenwart nicht das Gefühl hatte, im Schatten zu verschwinden. Dass genau das es so schmerzhaft machte, sie anzusehen und nur denken zu können: Was, wenn sie nie in mein Leben getreten wäre?', '27.10.2023', 'LYX', ARRAY['Deutsch']::text[], 251, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Winnie']::text[], ARRAY['He falls first']::text[], '{}', '2eb69c70-ea4c-57cb-9989-22ea424612e2', '2', '{}', 'sheet', :'owner') on conflict do nothing;
