insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1157af5a-a411-5796-b943-5c2e93e96f5a', 'When We Hope', NULL, '9783736313378', 'Jae-yong ist ein Mitglied der erfolgreichsten K-Pop-Gruppe der Welt, Ella eine ganz normale Studentin aus Chicago. Eigentlich hätte den beiden klar sein müssen, dass eine Beziehung zwischen ihnen unmöglich ist. Nicht nur trennen sie Tausende von Kilometern und mehrere Zeitzonen, auch die Welten, in denen sie leben, sind grundverschieden. Und egal, wie nahe sich Ella und Jae-yong in den letzten Monaten gekommen sind - sie müssen sich nun fragen, ob ihre Liebe stark genug ist, allen Widerständen zu trotzen ...', '21.12.2020', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ella','Jae-Young']::text[], ARRAY['Famous Person','Forbidden Love']::text[], '{}', '1aa7c392-b4d5-53f1-a9cf-7d0972ee7af0', '3', '{}', 'sheet', :'owner') on conflict do nothing;
