insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b503f71-98df-5fc5-9d51-ab81a85cab5b', 'When We Begin', NULL, '9783736316218', 'Ella und Liv reisen nach Seoul, machen Sightseeing und besuchen Jae-yong. Special Guests: Min-ho und der Rest von NXT, Erin, die Ella nach wie vor die besten Ratschläge gibt, Mel, die im Mutter-Modus ist, weil ihre zwei Küken allein im Ausland sind, und Jae-yongs Bücherregal in der NXT-Wohnung. Falls es euch auch schwergefallen ist, Ella und Jae-yong nach dem Ende WHEN WE HOPE gehen zu lassen, dann ist diese Novella genau der richtige Lesenachschub für euch.', '01.05.2021', 'LYX', ARRAY['Deutsch']::text[], 80, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ella','Jae-Young']::text[], ARRAY['Famous Person','Forbidden Love']::text[], '{}', '1aa7c392-b4d5-53f1-a9cf-7d0972ee7af0', '4', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
