insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1b2c4f0f-a875-5f54-a9a4-52626b0a97a2', 'Der Märchenerzähler', NULL, '9783789142895', 'Abel Tannatek ist ein Außenseiter, ein Schulschwänzer und Drogendealer. Wider besseren Wissens verliebt Anna sich rettungslos in ihn. Denn es gibt noch einen anderen Abel: den sanften, traurigen Jungen, der für seine Schwester sorgt und der ein Märchen erzählt, das Anna tief berührt. Doch die Grenzen zwischen Realität und Fantasie verschwimmen. Was, wenn das Märchen gar kein Märchen ist, sondern grausame Wirklichkeit? Was, wenn Annas schlimmste Befürchtungen wahr werden?', '01.02.2011', 'Oetinger', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Drama']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Abel Tannatek','Anna']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
