insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ad759f56-3a45-5537-ba40-d1e755f55811', 'Regenglanz', NULL, '9783499006548', 'Verletzlich, aber stark. Kunststudentin Alissa arbeitet neben der Uni als Tätowiererin. Sie ist gut in ihrem Job, ausgesprochen gut. Nur scheint das ihren neuesten Kunden nicht zu interessieren, der sich offenbar kein Tattoo von einer Frau stechen lassen will. Sexistischer Mistkerl. Entschlossen, aber sanft. Als Sportstudent Simon Alissa das erste Mal sieht, rauben ihm ihre tiefblauen Augen fast den Atem. Er fühlt sich sofort von ihr angezogen – und will ihr auf keinen Fall das extrem peinliche Tattoo zeigen, das eigentlich überstochen werden soll. Aber nun hält sie ihn für ein Arschloch. Und das ist noch schlimmer. Zusammen, aber verloren. Alissa und Simon. Während der Sitzungen lernen sich die beiden kennen – und mit jedem Treffen knistert es mehr. Doch keiner von ihnen ahnt zu diesem Zeitpunkt, dass sie mit ihrer beginnenden Beziehung gerade ein Tabu brechen…', '19.10.2021', 'Kyss', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Alissa','Simon']::text[], '{}', '{}', 'ecfbcb5e-2e39-56b6-98bc-e289919999e7', '1', '{}', 'sheet', :'owner') on conflict do nothing;
