insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('08fade81-e1bd-56a4-a81d-0895af93959e', 'b77facac-e8af-5f3e-b826-35d25d35f992', :'owner', 1, '2022-03-08', '2022-03-21', NULL, NULL, 14, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c6177b13-c0b2-5767-a628-07ba85c51d77', 'Proof of Faith', NULL, '9783736316737', 'In der Treuetestagentur PROOF OF LOVE gilt eine eiserne Regel: Verlieben verboten! Und als Sierra Madigan merkt, dass Caleb Barnes, ihre neue Zielperson, ihr nicht mehr aus dem Kopf gehen will, übergibt sie die Beweise seiner Treue sofort an ihre Chefin und versucht, ihn zu vergessen. Doch Sierra staunt nicht schlecht, als der attraktive Kinderarzt ein paar Monate später in die Wohnung neben ihr einzieht: noch genauso charmant, aber offenbar inzwischen single! Da sie einen gemeinsamen Balkon teilen, kommen sie sich schnell näher. Einziges Problem: Caleb weiß nicht, dass Sierra in der Agentur arbeitet, der er die Schuld am Scheitern seiner Beziehung gibt!', '31.03.2023', 'LYX', ARRAY['Deutsch']::text[], 380, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sierra Madigan','Caleb Barnes']::text[], ARRAY['Secred Identity','Forbidden Love']::text[], '{}', '67e9b4fc-d977-5d1c-80f3-8e6dbb3406c9', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
