insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a444605d-a317-596e-881e-1a2b2c6c4029', 'Proof of Love', NULL, '9783736316744', 'Als Chelsea Madigan ihren Verlobten in flagranti mit einer anderen Frau erwischt, zerbricht ihre Welt in Tausende Scherben. Sie gründet daraufhin Proof of Love und sagt mit ihrer Treuetestagentur der Untreue in New York den Kampf an. Der Erfolg lässt Chelsea aufblühen, doch ihr gebrochenes Herz kann sie auch damit nicht kitten. Als sie das Angebot bekommt, eine TV-Show als Expertin für Treuetests zu beraten, steht sie plötzlich Nathaniel Stan gegenüber - dem Produzenten der Show und Cousin ihres Ex-Verlobten. Und sosehr Chelsea auch mit ihrer Vergangenheit abschließen will, knistert es gewaltig zwischen ihnen. Doch kann sie ihr Herz jemals wieder in die Hände eines anderen legen?', '25.08.2023', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Chelsea Madigan','Nathaniel Stan']::text[], ARRAY['Second Chance','Enemies to Lovers','Work Adversaries']::text[], '{}', '67e9b4fc-d977-5d1c-80f3-8e6dbb3406c9', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
