insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('60070045-b108-5bfb-a7b0-360dd16109e6', 'Dare to Trust', NULL, '9783736314351', 'Als der New Yorker Geschäftsmann Hayden Millard nach Jahren seiner ehemaligen Mitschülerin Tori Lancaster gegenübersteht, gerät seine Welt augenblicklich ins Wanken. Schließlich war sie es, die ihm das Leben in der Highschool zur Hölle gemacht hat - auch wenn sie ihn anscheinend nicht wiedererkennt! Als Hayden herausfindet, dass Tori dringend einen Job braucht, bietet er ihr eine Stelle als Assistentin bei seinem Plattenlabel Ever Records an - um ihr endlich heimzuzahlen, was sie ihm einst angetan hat! Doch der in sich gekehrte CEO merkt schon bald, dass sein Herz ganz andere Pläne als Rache hat ...', '19.01.2021', 'LYX', ARRAY['Deutsch']::text[], 419, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hayden Millard','Tori Lancaster']::text[], ARRAY['Enemies to Lovers','Work Adversaries','Second Chance']::text[], '{}', '143976ba-24ef-5b68-902c-6e3f9718f59d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
