insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('caf0e43d-cbe6-5673-b2d6-efa3d39758dc', 'Proof of Hope', NULL, '9783736318663', 'Aurora Madigan glaubt einfach nicht an die Liebe. Nicht nur, dass sie immer wieder an den Falschen gerät, auch der Erfolg von PROOF OF LOVE, der Treuetest-Agentur, die sie mit ihren Schwestern gegründet hat, beweist ihr jeden Tag, dass sie ihr Herz beschützen muss. Finanzmogul Elijah James würde lieber heute als morgen in das Start-up investieren, doch das erste Treffen geht gewaltig schief, und Rory wird darauf angesetzt, den Deal zu retten. Dass der attraktive New Yorker allerdings ihr Herz zum Rasen bringt wie niemand zuvor, war nicht Teil des Plans, denn Privates mit Beruflichem zu vermischen, ist absolut tabu!', '18.10.2022', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Aurora Madigan','Elijah James']::text[], ARRAY['Enemies to Lovers','Work Adversaries','Forbidden Love']::text[], ARRAY['Kindstod/Fehlgeburten']::text[], '67e9b4fc-d977-5d1c-80f3-8e6dbb3406c9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
