insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('df2415a9-219b-5588-a928-b81905885e4e', 'Starting Something New', NULL, '9783736322370', 'An Daphne Valentis erstem Arbeitstag als Juristin bei START Entertainment geht alles schief. Statt Fälle zu bearbeiten, soll sie die Babysitterin von Aspen Knox spielen! Der attraktive Schauspieler will einen Neuanfang und nicht länger als The Hot Villain bekannt sein. Daphne soll ihn für seine kommende Hauptrolle als Anwalt in einem Liebesfilm beraten - und vor allem dafür sorgen, dass Aspen in keinen weiteren Skandal verwickelt wird. Vom ersten Augenblick an geraten sie immer wieder aneinander, wobei Aspens türkisgrüne Augen ein seltsam vertrautes Gefühl in Daphne auslösen. Und als ein Geheimnis aus der Vergangenheit ans Licht kommt, ändert sich alles ...', '26.04.2024', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['Double POV','1P']::text[], ARRAY['Daphne Valentis','Aspen Knox']::text[], ARRAY['Work Adversaries','Secred Identity','Enemies to Lovers']::text[], ARRAY['Tod von Familienangehörigen']::text[], 'a0fc6537-dae8-5d22-8dcc-68f4ba16da06', '1', '{}', 'sheet', :'owner') on conflict do nothing;
