insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f53e0e87-c17a-5279-bb1c-1be879a3ccf0', 'Up All Night', NULL, '9783736309678', 'Als Taylor Jensen an ein und demselben Tag nicht nur ihren Job an einen Kollegen verliert, sondern auch ihren Freund beim Fremdgehen erwischt, hat sie von Männern erst einmal genug. Völlig verzweifelt läuft sie Daniel Grant in die Arme, der ihr ein Zimmer in seiner WG anbietet. Einst waren sie beste Freunde, aber ein männlicher Mitbewohner mit sexy Tattoos und einem unwiderstehlichen Lächeln ist das Letzte, was Tae jetzt gebrauchen kann. Doch Dan steht schon lange auf Männer, weshalb das heiße Prickeln zwischen ihnen nichts zu bedeuten hat - oder etwa doch?', '29.04.2019', 'LYX', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Taylor Jensen','Daniel Grant']::text[], ARRAY['Friends to Lovers','Queer','Second Chance']::text[], '{}', '27f3b03d-721b-5adc-a835-ebb6b6ad9292', '1', '{}', 'sheet', :'owner') on conflict do nothing;
