insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('0fcc54a6-10d5-5e3a-92fd-fff9791415fe', '1d5d7c8a-60de-55b8-a39b-a1e0835da53e', :'owner', 1, '2021-02-09', '2021-02-11', NULL, NULL, 3, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f74da763-7ef5-56b0-9da3-c7a04915cb2d', 'Dare to Dream', NULL, '9783736314948', 'Quinn Millard kann es kaum erwarten, ihrem Verlobten Troy - dem erfolgreichsten Baumagnaten New Yorks - in wenigen Wochen das Jawort zu geben. Doch dieser Plan gerät gehörig ins Wanken, als sie im Urlaub auf Hawaii plötzlich dem Besitzer ihres Luxushotels begegnet: Jackson Orwood, ihrer ersten großen Liebe! Sie wollte ihn nie wiedersehen, und doch knistert es gewaltig zwischen ihnen. Und auf einmal steht Quinn vor der Entscheidung ihres Lebens: Heiratet sie ihren Traumprinzen oder riskiert sie alles für ihre Jugendliebe, die sie nie vergessen konnte?', '30.07.2021', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Quinn Millard','Jackson Orwood']::text[], ARRAY['Second Chance','Love Triangle']::text[], '{}', '143976ba-24ef-5b68-902c-6e3f9718f59d', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
