insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('0a2b5cfc-24e6-5012-864f-ec6c138eb6a3', '204bfb59-6ac7-5da0-82b0-b7df1424171a', :'owner', 1, '2021-08-30', '2021-09-12', NULL, NULL, 14, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('12395f81-255f-543c-90bb-0496636953f3', 'Next To You', NULL, '9783736310674', 'Addison Grant sagt immer, was sie denkt - vor allem zu ihrem arroganten Nachbarn Drake O''Hara. Als Drake ihr jedoch den Job als seine persönliche Assistentin anbietet, ist Addy das erste Mal in ihrem Leben sprachlos. Denn trotz ihrer Wortgefechte knistert es gewaltig zwischen ihr und dem erfolgreichen (und zugegebenermaßen ziemlich heißen) CEO. So stark die Anziehungskraft zwischen ihnen auch ist, die Regeln ihrer Geschäftsbeziehung sind klar: Drake ist ihr Boss, nichts weiter - bis es bei einem Firmenevent zu einem Kuss kommt, der alles verändert ...', '31.10.2019', 'LYX', ARRAY['Deutsch']::text[], 361, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Addison Grant','Drake O''Hara']::text[], ARRAY['Enemies to Lovers','Work Adversaries','Forced Proximity']::text[], '{}', '27f3b03d-721b-5adc-a835-ebb6b6ad9292', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
