insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e4e1caf4-26d7-5829-9309-bbdb58d01fa8', 'Dare to Stay', NULL, '9783736314955', 'Verwüstete Hotelzimmer, Frauen und Partys sind das Leben von Rockstar Ian Millard - bis seine Band ihm ein Ultimatum stellt: Entweder er bekommt sein Leben in den Griff oder er fliegt aus der Band! Doch erst als seine Nachbarin Brooke ihn eines Abends betrunken im Treppenhaus findet und bei sich aufnimmt, ändert sich sein Leben schlagartig. Die alleinerziehende Mutter hat eigentlich ganz andere Sorgen als den schlafenden Rockstar in ihrem Bett. Aber mit ihrer liebevollen Art weckt Brooke Gefühle in Ian, die er noch nie zuvor gespürt hat. Und plötzlich sehnt er sich nach mehr als nur einem Kuss oder einer kurzen Affäre, doch eine Frau an seiner Seite ist das Letzte, was Ians Fans jetzt von ihm wollen ...', '28.01.2022', 'LYX', ARRAY['Deutsch']::text[], 390, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ian Millard','Brooke']::text[], ARRAY['Single Parent','Famous Person','He falls first']::text[], '{}', '143976ba-24ef-5b68-902c-6e3f9718f59d', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
