insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d675b73e-f8f4-560a-87b9-dc74cfaac1a7', 'More Than This', NULL, '9783736312920', 'Landschaftsarchitektin Grace hatte noch nie wirklich Glück in der Liebe. Und dass alle in ihr und ihrem besten Freund Zayn das perfekte Paar sehen, macht die Sache nicht besser. Denn so nahe sie sich auch stehen, der Draufgänger und die schüchterne Romantikerin könnten unterschiedlicher nicht sein. Dennoch fällt es Grace zunehmend schwerer, das prickelnde Knistern zwischen ihnen zu ignorieren. Aber kann sie es wirklich wagen, Zayn ihre Gefühle zu gestehen, wenn es sie ihre Freundschaft kosten könnte?', '30.04.2020', 'LYX', ARRAY['Deutsch']::text[], 375, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Grace','Zayn']::text[], ARRAY['Friends to Lovers','Opposites Attract']::text[], '{}', '27f3b03d-721b-5adc-a835-ebb6b6ad9292', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
