insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('89c83219-a608-5c96-ae34-d2a184ba4f77', 'Selling Dreams', NULL, '9783736325753', 'Marissa Gallagher ist Immobilienmaklerin und lässt sich von niemandem unterkriegen. Auch nicht von Calder Bevyn, ihrem größten Konkurrenten. Calder leitet gemeinsam mit seinen Brüdern die Bevyn Estates und ist der Prince Charming von New York. Doch dann schnappt Marissa ihm einen Deal vor der Nase weg und wird prompt vom CEO und Bruder von Calder eingestellt. Als Rivalen im selben Unternehmen kämpfen sie darum, die Nummer eins im Verkauf zu werden - bis echte Gefühle ins Spiel kommen und sich Marissa und Calder nicht mehr sicher sind, ob sie noch gewinnen wollen oder längst dabei sind, ihre Herzen zu verlieren ...', '02.02.2026', 'LYX', ARRAY['Deutsch']::text[], 477, 44, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Marissa Gallagher','Calder Bevyn']::text[], ARRAY['Rivals to Lovers','Work Adversaries','Enemies to Lovers']::text[], ARRAY['Mobbing','Depiction of Trauma','Physische Gewalt']::text[], '29dc934d-e777-55a4-97f3-857fa88140a8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
