insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ce896e69-d939-50d8-a235-6febe7b1bc8b', 'Starting Something Great', NULL, '9783736322714', 'Jasmina Delic hat Glück im Unglück. Gerade als die Studiengebühren ihrer kleinen Schwester unbezahlbar scheinen, erhält sie die Chance, als Make-up-Artistin bei START Entertainment anzufangen. Sie sagt sofort zu - ohne zu wissen, dass sie die weltberühmte Band Saving Winter auf ihrer Tournee begleiten muss. Der Schock sitzt tief, denn Leadsänger Julian Vaughn ist der Mann, mit dem Mina vor zwei Jahren den schönsten Sommer ihres Lebens verbracht hat. Eine Zeit, die auch Julian nie vergessen konnte, obwohl sie in einer schmerzhaften Trennung endete. Schnell flammen alte Gefühle auf, die nicht sein dürfen. Hat ihre Liebe noch eine Chance, oder wird sie für immer eine Erinnerung bleiben?', '28.02.2025', 'LYX', ARRAY['Deutsch']::text[], 416, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['Double POV','1P']::text[], ARRAY['Jasmina Delic','Julian Vaughn']::text[], ARRAY['Second Chance','Famous Person','Forbidden Love']::text[], ARRAY['Häusliche Gewalt','Abtreibung']::text[], 'a0fc6537-dae8-5d22-8dcc-68f4ba16da06', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('5ceea340-7efe-5eb4-8518-146cb0abb1fe', :'owner', 'ce896e69-d939-50d8-a235-6febe7b1bc8b', 'gelesen'::reading_status, true, false, ARRAY['Digital','Print']::text[], ARRAY['eBook','Paperback']::text[], 'Normal', ARRAY['Playlist']::text[], 1490, true, true, ARRAY['Spotify']::text[], ARRAY['Franziska Grün','David M. Schulze']::text[], 693, NULL, false, 'solo'::company_kind, 'dislike'::verdict_kind, 1.0, 'untertroffen'::expectation_kind, 1, 'slow'::burn_kind, 'Ich musste mehrfach die Augenverdrehen beim lesen, weil ich die Handluch einfach nur dämlich und clichehaft fand. Auf der einen Seite wird Mina als wilder Freigeist beschrieben, doch sie ist ein engstirniger Kontrollfreak, der zu viel Angst hat, um auch nur eine Sinnvolle Entscheidung zum richtigen Zeitpunkt zu treffen. Passt leider gar nicht zusammen. Dieses Buch wahr mehr nervig als alles andere. Ich finde die Entscheidungen der Charaktere waren oft total blöd, ich fand auch das alles gleichzeitig viel zu schnell ging, während es sich ewig gezogen hat.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3bcb1022-9720-5613-a93e-dade66ff0741', '5ceea340-7efe-5eb4-8518-146cb0abb1fe', :'owner', 1, '2026-02-03', '2026-02-09', NULL, NULL, 7, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('01ff3bc5-ecf6-5c05-a53f-7308159cb319', 'Starting Something Real', NULL, '9783736322592', 'Novalee Wells ist ein Superstar. Doch das Leben im Rampenlicht hat auch seine Schattenseiten, und als ein Dating-Gerücht dafür sorgt, dass Nova von Paparazzi verfolgt wird und in einen Autounfall gerät, braucht die Sängerin eine Auszeit. Ausgerechnet ihr sonst so verschlossener Bodyguard Thorne McKinley bietet ihr an, auf der abgelegenen Ranch seiner Eltern unterzutauchen. Weit weg vom Trubel ihres Ruhms beginnt Nova tatsächlich zu heilen und lernt ganz neue Seiten an Thorne kennen, die ihr Herz höherschlagen lassen. Aber kann ihre Liebe überleben, wenn Nova wieder in ihr altes Leben im erbarmungslosen Scheinwerferlicht zurückkehren muss?', '27.09.2024', 'LYX', ARRAY['Deutsch']::text[], 391, 38, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Washington Depot', ARRAY['Double POV','1P']::text[], ARRAY['Novalee Wells','Thorne McKinley']::text[], ARRAY['Famous Person','Forced Proximity']::text[], ARRAY['Unfall','Belästigung','Essstörung','Psychische Erkrankung/Belastung']::text[], 'a0fc6537-dae8-5d22-8dcc-68f4ba16da06', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('06d28e98-2421-5c98-9a4c-ac6c46cd543c', :'owner', '01ff3bc5-ecf6-5c05-a53f-7308159cb319', 'gelesen'::reading_status, true, false, ARRAY['Print','Digital','Audiobook']::text[], ARRAY['eBook','Paperback']::text[], 'Normal', ARRAY['Playlist']::text[], 1199, true, true, ARRAY['Spotify']::text[], ARRAY['Lisa Cardinale','Bastian Korff']::text[], 656, '👌🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 2.5, 'erfuellt'::expectation_kind, 1, 'slow'::burn_kind, 'Ich mochte die Charaktere. Ich hätte mir jedoch ein wenig mehr Einblick in Thornes Gedanken gewünscht manchmal. Und zwar Gedanken, die isch nicht nur darum drehen, wie sehr er Nova anhimmelt. Leider hat mir dieses Buch genau das gegeben was ich von einem LYX New Adult Buch erwatet habe: Langeweile. Die Bücher sind einfach zu hervorsehbar und das Drama ist unnötig und die Story dadurch flach.') on conflict do nothing;
