insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ec383bb2-8dfd-5eb6-996c-ea00bb8915ee', 'Elfenkuss', 'Wings', '9783570138847', 'Durchscheinend blau und weiß sind sie und erschreckend schön, die flügelartigen Blütenblätter, die der 15-jährigen Laurel eines Morgens aus dem Rücken wachsen. Gemeinsam mit ihrem neuen Freund David versucht sie, herauszufinden, was mit ihr geschieht. Doch erst als sie in dem verwunschenen Wald hinter ihrem Elternhaus auf den faszinierenden Tamani trifft, erfährt sie die unglaubliche Wahrheit: Laurel ist eine Elfe, die als kleines Kind zu den Menschen gesandt wurde, um das Tor nach Avalon zu beschützen. Sie weiß, am Ende wird sie sich entscheiden müssen: zwischen ihrem Leben als College-Mädchen und ihrer Bestimmung, vor allem aber zwischen dem attraktiven David und dem Frühlingselfen Tamani, dessen grüne Augen sie nicht mehr loslassen …', '22.03.2010', 'cbj', ARRAY['Deutsch']::text[], 347, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Avalon', '{}', ARRAY['Laurel','David','Tamani']::text[], ARRAY['Different Worlds']::text[], '{}', '96b1bc30-892d-5e97-979b-a49ffe62ee4d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
