insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('d54937a9-e5e9-51da-8898-4830830adbaa', '03a1977d-2566-5bc4-8277-7ec75d5d99b3', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b6d72bc3-d94b-5cf9-9b94-182d579fc493', 'Elfenliebe', 'Spells', '9783570138854', 'Als Laurel den Sommer in Avalon verbringt, wo sie die Lebensweise der Elfen kennenlernen soll, rückt die Menschenwelt für sie in weite Ferne. Dabei konnte Laurel sich die Zeit ohne ihren Freund David erst gar nicht vorstellen. Aber jetzt, in der Elfenwelt, ist alles neu, alles so wundersam – und da ist der attraktive, geheimnisvolle Frühlingself Tamani, der ihr zur Seite steht und der sie liebt, wie noch nie ein Mensch sie geliebt hat ... nach ihrer Rückkehr merkt Laurel, wie sehr ihr der Alltag in der Menschenwelt und vor allem David gefehlt haben. Sie spürt: Schon bald wird sie eine schwere Entscheidung treffen müssen ...', '21.03.2011', 'cbj', ARRAY['Deutsch']::text[], 396, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Avalon', '{}', ARRAY['Laurel','David','Tamani']::text[], ARRAY['Different Worlds']::text[], '{}', '96b1bc30-892d-5e97-979b-a49ffe62ee4d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
