insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('afa42b0e-7845-549a-a7aa-bf56aa23e756', 'Elfenbann', 'Illusions', '9783570138861', 'Laurel ist mehr als überrascht, als am ersten Tag des neuen Schuljahrs kein anderer als ihr Elfenfreund Tamani auftaucht – und zwar mit dem Auftrag, Laurel zu beschützen! Es dauert nicht lange, da merkt Laurel, wie all ihre verschütteten Gefühle für Tamani wieder aufleben und ihr innerer Konflikt – liebt sie den Menschen David oder den Elf Tamani? – erneut aufbricht. Damit nicht genug: Beunruhigt ist sie auch durch ihre mysteriöse neue Mitschülerin Yuki. Zusammen mit David und Tamani gelingt es Laurel, trotz aller Gefühlswirrungen, die Fremde zu entlarven. Ihre wichtigste Entscheidung hat sie aber immer noch nicht getroffen …', '17.04.2012', 'cbj', ARRAY['Deutsch']::text[], 407, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Avalon', '{}', ARRAY['Laurel','David','Tamani']::text[], ARRAY['Different Worlds']::text[], '{}', '96b1bc30-892d-5e97-979b-a49ffe62ee4d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
