insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('12bd3f56-52b0-5152-a7d0-16fd7500249e', 'Elfenglanz', 'Destined', '9783570138878', 'Laurel und Tamani sehen sich einem Feind gegenüber, der mächtiger ist als alle, denen sie bisher begegnet sind. Als sogar David und Chelsea ihnen nach Avalon folgen dürfen, wissen die Freunde, dass es schlechter um die Heimat der Elfen steht als gedacht. Doch dann entpuppt sich David als Nachfahre des legendären König Artus, er ist der Einzige, der das sagenumwobene Schwert Exalibur führen kann. Gemeinsam ziehen die Elfen und Menschen in die allerletzte Schlacht um Avalon – und nicht alle werden überleben. Das atemberaubende Finale der Elfen-Serie mit einem überraschenden Ende, denn Laurel muss sich endgültig entscheiden ...', '22.04.2013', 'cbj', ARRAY['Deutsch']::text[], 346, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Avalon', '{}', ARRAY['Laurel','David','Tamani']::text[], ARRAY['Different Worlds']::text[], '{}', '96b1bc30-892d-5e97-979b-a49ffe62ee4d', '4', '{}', 'sheet', :'owner') on conflict do nothing;
