insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6362606b-9734-5795-a12f-bc0d05d51655', 'Fair Blue', NULL, '9783770499816', 'Kann aus einer katastrophalen ersten Begegnung noch die große Liebe werden? Tomoyas Zwillingsbruder ist ein berühmter Schauspieler – verständlich, dass er deswegen Komplexe hat! Als er von einem Verehrer mit seinem Bruder verwechselt wird, gibt Tomoya ihm wütend einen Korb. Doch der Abgewiesene bleibt hartnäckig...', '10.01.2019', 'Egmont Manga', ARRAY['Deutsch']::text[], 181, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Tomoya']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
