insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('19937b57-b02f-54a7-9c7e-f946e0786bf2', 'Soul Eater (Vol.1)', 'Sōru ītā', '9783551792112', 'Einmal Seele zum Mitnehmen, bitte! Maka ist eine Waffenschmiedin in spezieller Ausbildung. Ihre Sense namens "Soul Eater" hat ein Eigenleben und nimmt außerhalb des Kampfes die Gestalt eines ultracoolen Jungen an. Um eine "Waffe des Todesgottes" zu erschaffen, muss sich Soul Eater exakt 99 böse Seelen und eine Hexenseele einverleiben, nur so kann Maka ihre Ausbildung abschließen. Die nötigen Seelen wurden nach einigem Aufwand "zubereitet" und verschlungen, doch an der Seele einer Hexe beißen sich die beiden die Zähne aus. Müssen sie nun vielleichtsogar wieder ganz von vorne beginnen...?', '22.10.2009', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōnen']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Maka']::text[], '{}', '{}', 'a5d8f761-1fdc-58cc-b6e2-49fc33fa3df4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
