insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4ce5fd2f-6b34-5245-8599-aacd69a0984d', 'Calendar Girl - Verführt', NULL, '9783548288840', 'Mia Saunders braucht Geld. Viel Geld. Eine Million Dollar, um ihren Vater zu retten. Er liegt im Krankenhaus, weil er seine Spielschulden nicht begleichen konnte. Um die Summe aufzutreiben, heuert Mia bei einer Agentur an und lässt sich als Begleitung buchen. Ihre Gesellschaft kostet 100.000 Dollar pro Monat. Sex ist ausdrücklich nicht Teil des Deals – leicht verdientes Geld! Und der Liebe hat Mia sowieso abgeschworen. Als sie ihrem ersten Kunden, dem Hollywood-Autor Wes Channing, gegenübersteht, ist schnell klar: Zwischen den beiden knistert es gewaltig. Vor ihnen liegt ein Monat voll heißer Leidenschaft. Doch Mia darf sich nicht verlieben. Denn Wes ist nur Mr Januar...', '27.06.2016', 'Ullstein', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mia Saunders','Wes Channing']::text[], '{}', '{}', 'b31dd112-0675-52e9-a453-37f7d7799acf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
