insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('87d2d3d3-4541-565b-a5f0-c79aa012d517', 'Trinity - Verzehrende Liebe', 'Body - The Trinity Series', '9783548289342', 'Ich liebe dich. Ich will dich. Ich werde dich nie verlassen. Beim Gedanken an diese Worte bekommt Gillian Callahan Panik. Jahrelang wurde sie von ihrem gewalttätigen Ex-Freund misshandelt. Jetzt ist sie frei und arbeitet für Safe Haven, die Hilfsorganisation, der sie ihre Rettung verdankt. Das Thema Männer hat sie abgehakt. Bis sie bei einer Konferenz den Vorsitzenden von Safe Haven, Chase Davis, kennenlernt. Der attraktive Milliardär ist so sexy, dass Gillian schwindelig wird. Außerdem bekommt er immer, was er will – und er will Gillian. In ihr kämpfen Lust und Angst gegeneinander. Wird sie Chase vertrauen können? Ist sie bei ihm wirklich sicher? Und wie gefährlich ist ihre dunkle Vergangenheit?', '02.01.2017', 'Ullstein', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Gillian Callahan','Chase Davis']::text[], '{}', '{}', '6b5ba9df-d633-5c14-a18b-3b785343a87c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
