insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('db605fe6-70e2-5f3b-b519-85ecca85aefc', 'Die Heinzelmännchen von Köln', NULL, '9783949276095', 'Wie schön wäre es, wenn unsere Arbeit sich von alleine erledigen würde? Vor langer Zeit lebte in Köln ein kleines Volk, die Heinzelmännchen. Diese kleinen Geister schlichen sich des Nachts in die Häuser der Menschen und verrichteten heimlich deren Arbeit. Als jedoch die Frau des Schneiders ihnen einen hinterlistigen Streich spielte, um sie zu Gesicht zu bekommen, verschwanden sie für immer.', '21.09.2022', 'Kindermann', ARRAY['Deutsch']::text[], 40, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Vergangenheit'::time_period, 'Köln', ARRAY['3P Objective']::text[], ARRAY['Heinzelmännchen']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
