insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bba8d8c4-42dc-545c-9d9c-03c49bc59fb9', 'For Good - Über die Liebe und das Leben', NULL, '9783959919623', 'Was würdest Du tun, wenn Du das verlierst, was Deinem Leben einen Sinn gab? Das, was Du mehr als alles andere auf dieser Welt geliebt hast. Würdest Du aufgeben? Nach dem Tod ihrer großen Liebe Ben, beginnt Charlie in Trauer zu versinken. Immer wieder erinnert sie sich an die vergangenen Zeiten, in denen sie ihn kennen- und lieben lernte. Doch der Verlust droht sie zu ersticken und blind zu machen für das, was das Leben ausmacht. Charlie zieht sich völlig zurück und beginnt zu verstehen, dass nichts je wieder so sein wird wie es einmal war.', '27.06.2016', 'Drachenmond', ARRAY['Deutsch']::text[], 195, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Charlie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
