insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('07e13d17-6fe6-5f26-98a6-e4bf0fde4de5', 'Mondprinzessin', NULL, '9783959913171', 'Lynn bemerkt an ihrem Geburtstag, wie sich auf der Haut ihres Unterarms ein Sternenbild abzeichnet. Die einzelnen Punkte leuchten und Lynn versucht verzweifelt, sie zu verstecken. Als nicht nur die Sterne auf ihrem Arm, sondern auch sie selbst zu leuchten beginnt, ist nichts mehr, wie es war. Dunkle Schatten jagen sie – die Wächter des Mondes. Und sie begegnet Juri, der ihr erzählt, sie sei eine Prinzessin – kein Waisenkind. Trotz Lynns Unglauben folgt sie dem Mondkrieger und stellt sich ihren Verfolgern. Juri verliebt sich in Lynn, doch sie ist einem Prinzen bestimmt und nicht ihm…', '01.10.2016', 'Drachenmond', ARRAY['Deutsch']::text[], 252, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Lynn']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
