insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8791cfa0-0740-5ec6-8528-227c4f8f4ce3', 'Wir fliegen, wenn wir fallen', NULL, '9783764191573', 'Eine Nacht unter den Sternen schlafen. Einen Spaziergang im Regenwald machen. Die Nordlichter beobachten ... So beginnt eine Liste mit zehn Wünschen, die Phil nach seinem Tod hinterlässt, gewidmet seinem Enkel Noel und der siebzehnjährigen Yara. Phils letztem Willen zufolge sollen sich die beiden an seiner statt die Wünsche erfüllen. Gemeinsam. Yara und Noel, die sich vom ersten Moment an nicht ausstehen können, willigen nur Phil zuliebe ein. Doch ohne es zu wissen, begeben sich die beiden auf eine Reise, die nicht nur ihr Leben grundlegend verändern wird, sondern an deren Ende beiden klar ist: Das Glück, das Leben und die Liebe fangen gerade erst an.', '01.10.2018', 'Oetinger', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Yara','Noel']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
