insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eae44e4b-0495-50a3-902c-530fa72544d1', 'Die Stille meiner Worte', NULL, '9783764192143', 'Hannah hat ihre Worte verloren. In der Nacht, als ihre Zwillingsschwester Izzy ums Leben kam. Wer soll nun ihre Gedanken weiterdenken, ihre Sätze beenden und ihr Lachen vervollständigen? Niemand kann das. Egal, was Hannahs Eltern versuchen, sie schweigt. Um Izzy nicht loslassen zu müssen, schreibt sie ihr Briefe. Schreibt und verbrennt sie. Immer wieder. Hannah kann der Stille ihrer Worte nicht entkommen. Bis sie Levi trifft, der mit aller Macht versucht herauszufinden, wer sie wirklich ist …', '21.10.2019', 'Oetinger', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hannah']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
