insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c8cf2a68-2cb6-584d-8421-dd1c9e2d7853', 'Spiegelsplitter', NULL, '9783551300447', 'Caitlin weiß nicht, was es bedeutet, sich in einem Spiegel zu sehen, denn sie erblickt nichts darin. Doch er zieht sie an, ruft sie zu sich, wo auch immer sie ist. Eines Tages steht sie dem geheimnisvollen Finn gegenüber, der eine Sehnsucht in ihr weckt, der sie nicht entkommen kann. Immer wieder begegnen sich die beiden, ohne zu wissen, was sie in Wirklichkeit verbindet. Bis Caitlins Erbe zu erwachen beginnt und sie erkennt, dass es mehr auf dieser Welt gibt, als sie ahnt...', '22.10.2015', 'im.press', ARRAY['Deutsch']::text[], 358, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Caitlin']::text[], '{}', '{}', '572712fe-0041-525e-8646-ccb4f12d349e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
