insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0bc7f171-f100-548d-9ec6-5fdf1c8aabb1', 'Spiegelstaub', NULL, '9783551300508', 'Lange schon dauert der Kampf gegen die Wesen der Fantasie. Und noch immer muss Caitlin lernen, ihre Fähigkeiten zu beherrschen. Obwohl jegliche Verbindung zur Spiegelwelt zerstört wurde, ist sie noch nicht in Sicherheit. Denn Finn, der Spiegel ihrer Seele und Caitlins wahre Liebe, hat ihr verschwiegen, dass der Magier Seth möglicherweise aus Scáthán entkommen konnte. Ihrer Bestimmung folgend, macht sie sich gemeinsam mit ihm und ihren Freunden auf den Weg in die Heimat ihrer Mutter. An den Ort, an dem das Leben begonnen hat. Doch alles was lebt, kann auch sterben…', '29.04.2016', 'im.press', ARRAY['Deutsch']::text[], 240, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Caitlin']::text[], '{}', '{}', '572712fe-0041-525e-8646-ccb4f12d349e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
