insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('51143fe6-6d35-5662-9b4a-daa75c3ebf35', 'Study in Drowning', NULL, '9781529195699', 'Effy Sayre has always believed in fairy tales. She’s had no choice. Since childhood, she’s been haunted by visions of the Fairy King. She’s found solace only in the pages of Angharad—author Emrys Myrddin’s beloved epic about a mortal girl who falls in love with the Fairy King and then destroys him. Effy’s tattered, dog-eared copy is all that’s keeping her afloat at Llyr’s prestigious architecture college. So when Myrddin’s family announces a contest to redesign the late author’s estate, Effy feels certain this is her destiny. But Hiraeth Manor is an impossible task: a musty, decrepit house on the brink of crumbling into a hungry sea. And when Effy arrives, someone else has already made a temporary home there. Preston Héloury, a stodgy young literature scholar, is studying Myrddin’s papers and is determined to prove her favorite author is a fraud. As the two rivals piece together clues about the reclusive author’s legacy, dark forces, both mortal and magical, conspire against them—and the truth may bring them both to ruin.', '19.09.2023', 'DelRey', ARRAY['Englisch']::text[], 376, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Academia']::text[], 'Adult'::audience_kind, NULL, 'Llyr', '{}', ARRAY['Effys']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
