insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1a5f2bce-9320-5c8d-a714-7c0d1ccd8a9f', 'Lovelight Farms', NULL, '9781035028856', 'In an effort to save the Christmas tree farm she’s loved since she was a child, Stella enters a contest with insta-famous influencer Evelyn St. James. With the added publicity and the huge cash prize, she might just be able to save the farm from its financial woes. There’s just one problem. To make the farm seem like a romantic destination for the holidays, she lied on the application and said that she owns Lovelight Farms with her boyfriend. Only . . . there is no boyfriend. Enter best friend Luka Peters. He just came home for some hot chocolate, and somehow got a farm and a serious relationship in the process. Will their fake love affair save Lovelight Farms in time for Christmas?', '08.06.2023', 'Pan MacMillan', ARRAY['Englisch']::text[], 321, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Lovelight Farm', '{}', ARRAY['Stella','Luka Peters']::text[], '{}', '{}', '4ac18f2b-8bd8-5d29-8c1b-b906881d66f9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
