insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d6927c83-2292-5596-b1e5-d17aefbcf7c3', 'Collide', NULL, '9783736323780', 'Als Summer Preston erfährt, dass sie ihre Forschungsarbeit für die Aufnahme ins renommierte Masterprogramm der Dalton University über Eishockey schreiben soll, kann das nur ein schlechter Scherz sein - ausgerechnet über den Sport, den sie abgrundtief hasst! Doch wenn sie ihren Traum, Sportpsychologin zu werden, nicht augenblicklich an den Nagel hängen will, hat sie keine andere Wahl. Dass dann auch noch Aiden Crawford von seinem Coach dazu verdonnert wird, sie bei ihrem Projekt zu unterstützen, macht die Sache nicht besser: Der selbstbewusste und viel zu attraktive Captain des Eishockeyteams und die Perfektionistin geraten bei jeder Begegnung aneinander! Aber schon bald fühlt es sich so gar nicht mehr nach einer Strafe an, Zeit mit Aiden zu verbringen ...', '29.11.2024', 'LYX', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Dalton University', ARRAY['Double POV','1P']::text[], ARRAY['Summer Preston','Aiden Crawford']::text[], ARRAY['Sport','Enemies to Lovers','Universicy/College']::text[], '{}', '813cb833-5607-5082-b9f9-bf796b6722c5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
