insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2d99d187-6b6d-5b63-b408-a19ac11cd34c', 'Spiral', NULL, '9783736324497', 'Ballerina Sage Beaumont bringt alles mit, was sie zur Hauptrolle in Schwanensee und für einen Platz am Nova Ballet Theater braucht - nur nicht die nötige Social-Media-Reichweite. Etwas, woran es Eishockeyspieler Eli Westbrook so gar nicht mangelt. Vor Kurzem völlig überraschend in die NHL gedraftet tut sich der skandalumwitterte Playboy schwer im Rampenlicht. Eine Fake-Beziehung scheint die Lösung für ihre Probleme: Die mediale Aufmerksamkeit sorgt dafür, das Sages Followeranzahl steigt, während Eli eine feste Freundin präsentieren und den Gerüchten endlich ein Ende setzen kann. Doch was als Fake-Dating beginnt, wird schon bald so viel mehr ...', '27.06.2025', 'LYX', ARRAY['Deutsch']::text[], 448, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Dalton University', ARRAY['Double POV','1P']::text[], ARRAY['Sage Beaumont','Eli Westbrook']::text[], ARRAY['Sport','Fake Dating','Universicy/College']::text[], ARRAY['Essstörung']::text[], '813cb833-5607-5082-b9f9-bf796b6722c5', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
