insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('61533423-335d-596e-a014-e26fe7e43858', 'Revolve', NULL, '9783736325692', 'Der Traum von Eiskunstläuferin Sierra Romanova ist geplatzt. Nach einem schweren Unfall kann sie nicht bei den Olympischen Spielen antreten und hat Angst, aufs Eis zurückzukehren. Ausgerechnet Dylan Donovan, der wegen seines rücksichtslosen Verhaltens und der wilden Partyexzesse vom Eishockeyteam suspendiert wurde, stellt ihr Leben komplett auf den Kopf. Seine provokanten Worte treiben sie zurück aufs Eis - und schon bald kann sie auch außerhalb des Trainings nicht aufhören, an ihn zu denken. Als Sierra für ihr Comeback einen Partner braucht, ist Dylan ihre beste Chance. Und was für die beiden als absolute Notlösung beginnt, lässt schnell Gefühle aufkommen, die sie nicht mehr ignorieren können ...', '02.03.2026', 'LYX', ARRAY['Deutsch']::text[], 505, 50, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Dalton University', ARRAY['Double POV','1P']::text[], ARRAY['Sierra Romanova','Dylan Donovan']::text[], ARRAY['Sport','Enemies to Lovers','Universicy/College']::text[], ARRAY['Psychische Erkrankung/Belastung','Toxische Beziehungsdynamiken']::text[], '813cb833-5607-5082-b9f9-bf796b6722c5', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
