insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a5cb03d4-a6a0-51e3-adac-c997cca9710d', 'Kirschblüten nach dem Winter (Vol.1)', '겨울 지나 벚꽃', '9783910530201', 'Nach dem Tod seiner Eltern wird der siebenjährige Haebom von der Familie seines besten Freundes Taeseong aufgenommen. Doch obwohl sich Taeseong liebevoll um Haebom kümmert, hat dieser Angst, seiner neuen Familie zur Last zu fallen, und beginnt sich zu distanzieren. Obwohl sie unter einem Dach leben, haben die beiden Freunde so jahrelang kaum etwas miteinander zu tun. Als Haebom und Taeseong in dieselbe Klasse in der Highschool kommen, ändert sich plötzlich alles. Dadurch, dass sie von nun an 24 Stunden am Tag gemeinsam verbringen, entwickeln sich zwischen ihnen Gefühle, die sie nie für möglich gehalten hätten …', '17.04.2023', 'Papertoons', ARRAY['Deutsch']::text[], 304, 21, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Highschool', ARRAY['3P Objective']::text[], ARRAY['Haebom','Tawesong']::text[], ARRAY['Queer','High School','Friends to Lovers']::text[], ARRAY['Tod von Familienangehörigen']::text[], 'ccee25fc-b304-5401-8c43-7dfd8a6ce1a9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
