insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('65cb67ee-be31-5246-9107-7bdccb7783fa', 'Das Labyrinth von London', 'Fated', '9783734161650', 'Willkommen in London! Wenn Sie diese großartige Stadt bereisen, versäumen Sie auf keinen Fall einen Besuch im Emporium Arcana. Hier verkauft der Besitzer Alex Verus keine raffinierten Zaubertricks, sondern echte Magie. Doch bleiben Sie wachsam. Diese Welt ist ebenso wunderbar wie gefährlich. Alex zum Beispiel ist kürzlich ins Visier mächtiger Magier geraten und muss sich alles abverlangen, um die Angelegenheit zu überleben. Also halten Sie sich bedeckt, sehen Sie für die nächsten Wochen von einem Besuch im Britischen Museum ab und vergessen Sie niemals: Einhörner sind nicht nett!', '16.07.2018', 'blanvalet', ARRAY['Deutsch']::text[], 412, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, NULL, 'London', '{}', ARRAY['Alex Verus']::text[], '{}', '{}', 'a6c3d578-48c1-5ba2-a63a-62c227b9f0ad', '1', '{}', 'sheet', :'owner') on conflict do nothing;
