insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2728c573-9274-529e-a096-3c8eaff4209f', 'The Kissing Booth', NULL, '9783641243791', 'Als die hübsche und beliebte Elle beschließt, für den Schulfasching eine „Kissing Booth“ einzurichten, denkt sie nicht im Traum daran, selbst einmal darin zu sitzen – und noch viel weniger, dass sie bald ihren ersten Kuss von Bad Boy Noah bekommt, dem großen Bruder ihres besten Freundes. Von da an steht ihr Leben Kopf. Denn Noah ist tabu, so hat sie es mit Lee vereinbart. Nicht so leicht durchzuhalten bei dem Jungen, auf den die ganze Schule steht. Aber kann das ein Happy End geben?', '01.02.2019', 'cbt', ARRAY['Englisch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Elle Evans','Noah Flynn']::text[], '{}', '{}', 'c60f6cc8-ffac-5b07-b5a8-22af0738c321', '1', '{}', 'sheet', :'owner') on conflict do nothing;
