insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3797e400-8b36-533b-b48d-5253e2b2404a', 'Splitterherz', NULL, '9783839001059', 'Es gibt genau einen Grund, warum Elisabeth Sturm nicht mit fliegenden Fahnen vom platten Land zurück nach Köln geht, und dieser Grund heißt Colin. Der arrogante, unnahbare, aber leider auch äußerst faszinierende Colin gibt Ellie ein Rätsel nach dem anderen auf, und obwohl sie sich mit aller Macht dagegen wehrt, kann sie sich seiner Ausstrahlung nicht entziehen. Bald muss Ellie einsehen, dass Colin viel mehr mit ihrer Familie verbindet, als sie sich je vorstellen könnte. Ihr Vater Leo verbirgt ein Geheimnis, das ihn und Colin zu erbitterten Gegnern macht - und das Ellie in tödliche Gefahr bringt. Dass sie mit ihren seltsamen nächtlichen Träumen den Schlüssel zu dem Rätsel in der Hand hält, begreift Ellie erst, als ihre Gefühle für Colin alles zu zerstören drohen, was sie liebt.', '01.01.2010', 'Script5', ARRAY['Deutsch']::text[], 631, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Elisabeth Sturm','Colin']::text[], '{}', '{}', 'cb3a3fdc-c8a6-540e-9ca6-1b14a1683dad', '1', '{}', 'sheet', :'owner') on conflict do nothing;
