insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('20f446da-c46a-56de-ad92-5fd65a25c6c7', 'Scherbenmond', NULL, '9783839001226', 'Längst ist der Sommer vergangen, der Elisabeth Sturm die Augen öffnete für die gefährliche Welt der Mahre, der Sommer, in dem sie sich in einen von ihnen verliebte. Seit Monaten ist Colin nun verschwunden und Ellie quält sich durch einen nicht enden wollenden Winter. Die Tage tröpfeln gleichförmig vor sich hin, in den Nächten dagegen wird Ellie von Albträumen heimgesucht, die sie verstört zurücklassen. Um auf andere Gedanken zu kommen, quartiert Ellie sich bei ihrem Bruder in Hamburg ein. Doch sie erkennt Paul kaum wieder: Er wirkt erschöpft und gehetzt und scheint etwas vor ihr zu verbergen. Je mehr sie in Pauls Welt eintaucht, desto deutlicher überkommt Ellie ein Gefühl der Bedrohung und plötzlich weiß sie nicht mehr, wem sie noch trauen kann. Sie ahnt nicht, dass ihre Sorge um Paul und ihre Liebe zu Colin sie tiefer verletzen könnten als der abgründigste Traum.', '01.01.2011', 'Script5', ARRAY['Deutsch']::text[], 687, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Elisabeth Sturm','Colin']::text[], '{}', '{}', 'cb3a3fdc-c8a6-540e-9ca6-1b14a1683dad', '2', '{}', 'sheet', :'owner') on conflict do nothing;
