insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('4c21e3a4-5731-5280-87d4-9350e8892a1f', 'fb3dd41a-40f7-5677-a6dd-8930118d3581', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b961faab-3edb-5de6-b7f6-245795846861', 'Dornenkuss', NULL, '9783839001233', 'Elisabeth Sturm hat am eigenen Leib erfahren, welche Gier, welche zerstörerische Kraft und welches Grauen in der Welt der Mahre lauern - und doch hält sie an ihrer Liebe zu Colin fest. Erschöpft und bis ins Mark verletzt, fürchtet und ersehnt sie den Tag, an dem er zurückkehrt und sie sich auf die Jagd nach Tessa machen, der uralten Mahrin, die ihr Glück bedroht. In Italien hoffen sie, Tessa auf die Spur zu kommen und Hinweise auf Ellies verschollenen Vater zu erhalten. Fast gegen ihren Willen findet Ellie in der Hitze, dem Meer und der Kargheit des Landes die Ruhe, nach der sie sich seit Monaten sehnt, und dankbar gibt sie sich diesem neuen, freien Leben hin. Als von unerwarteter Seite ein Verbündeter auftaucht, scheinen die Antworten auf Ellies Fragen plötzlich greifbar. Aber je tiefer sie in das Geheimnis der Mahre eindringt, desto größer werden Ellies Zweifel: Ist selbst ihre Liebe nicht stark genug, um gegen Colins Hunger zu bestehen?', '02.11.2011', 'Script5', ARRAY['Deutsch']::text[], 813, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Elisabeth Sturm','Colin']::text[], '{}', '{}', 'cb3a3fdc-c8a6-540e-9ca6-1b14a1683dad', '3', '{}', 'sheet', :'owner') on conflict do nothing;
