insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f409fdf2-efea-5b29-877e-19bfd943a7da', 'Bad Publicity', NULL, '9781526676443', 'Yesterday they were just exes. Today they''re a writer and a publicist... on tour in Europe... for a month. When Andie lands her dream job as a senior book publicist, she''s ready to take the world of New York publishing by storm. Until her first day, when she discovers that her biggest author is Jack Carlson - the same Jack who ruined her life in university. Who she hasn''t spoken to in five years. Who is not only still infuriatingly hot but incredibly successful. And whose campaign she definitely cannot mess up, if she wants to keep her job. To make matters even worse, the central part of this career-defining campaign is a book tour. For a month, Andie will have to travel across Europe with the man who, if she were being totally honest, she''d like to hit with her car. But she will not lose this opportunity, especially not because of him. One month on tour with Jack Carlson, visiting some of the most romantic spots in Europe. Deep breath. She can do this.', '27.02.2025', 'Bloomsbury', ARRAY['Englisch']::text[], 367, 27, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Single POV','1P']::text[], ARRAY['Andie','Jack Carlson']::text[], ARRAY['Enemies to Lovers','Second Chance','Work Adversaries']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
