insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d544960-c3a1-5b53-b31d-30501b9dff97', 'Der letzte erste Blick', NULL, '9783736324787', 'Das Einzige, was Emery Lance sich wünscht, als sie ihr Studium in West Virginia beginnt, ist ein Neuanfang. Sie möchte studieren, und zwar ohne das Gerede, das Getuschel und die verurteilenden Blicke der Leute zu Hause. Dafür nimmt sie sogar in Kauf, dass sie mit dem nervigsten Kerl aller Zeiten in einer WG landet. Doch es kommt schlimmer: Dessen bester Freund Dylan Westbrook bringt ihr Herz mit einem einzigen Blick zum Rasen. Dabei gehört er zu der Sorte Mann, von der Emery sich unbedingt fernhalten wollte: zu gut aussehend, zu nett, zu lustig. Und eine große Gefahr für ihr ohnehin schon zerbrechliches Herz ...', '06.06.2025', 'LYX', ARRAY['Deutsch']::text[], 442, 27, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', ARRAY['Double POV','1P']::text[], ARRAY['Emery Lance','Dylan Westbrook']::text[], ARRAY['Enemies to Lovers','Friends to Lovers','Universicy/College']::text[], '{}', '87573a33-56b5-5e09-9b56-b6b6e62d8015', '1', '{}', 'sheet', :'owner') on conflict do nothing;
