insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('09154717-4e99-5f4a-a643-638c8945cf8c', 'Sturmtochter - Für Immer Verboten', NULL, '9783473585311', 'Seit jeher herrschen fünf Clans, die die Elemente beeinflussen können, über Schottland. Ava ahnt davon nichts, obwohl sie Jagd auf Elementare macht – die Kreaturen, die ihre Mutter getötet haben. An Avas Seite kämpft der geheimnisvolle Lance. Sie kennt jede seiner Bewegungen, seiner Narben, den Blick aus seinen braunen Augen. Doch dann entdeckt Ava, dass sie die Gabe besitzt, Wasser zu beherrschen. Und plötzlich werden die Naturgesetze außer Kraft gesetzt, sobald sie und Lance sich näherkommen.', '12.06.2018', 'Ravensburger', ARRAY['Deutsch']::text[], 455, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Ava','Lance']::text[], '{}', '{}', '8c3d02e4-faf4-505f-b97a-caa13ef2465c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
