insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('507c5644-a542-585f-aff0-0159b7ab967f', 'Der letzte erste Kuss', NULL, '9783736324794', 'Elle und Luke sind beste Freunde - und das ist auch gut so. Zu oft sind sie in der Vergangenheit verletzt worden, als dass sie noch an die große Liebe glauben würden. Doch dann ändert ein leidenschaftlicher Kuss alles. Und auf einmal ist es unmöglich, das heftige Prickeln zwischen ihnen noch länger zu ignorieren. Dabei wissen Elle und Luke, wie viel für sie auf dem Spiel steht. Und sie wissen auch, dass sie ihre Freundschaft mehr denn je brauchen ...', '06.06.2025', 'LYX', ARRAY['Deutsch']::text[], 502, 29, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', ARRAY['Double POV','1P']::text[], ARRAY['Elle','Luke']::text[], ARRAY['Friends to Lovers','Second Chance']::text[], '{}', '87573a33-56b5-5e09-9b56-b6b6e62d8015', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
