insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c61e1a54-64c6-5bfe-b031-0cc18b60060e', 'Die letzte erste Nacht', NULL, '9783736324817', 'Sie hätten niemals miteinander im Bett landen dürfen - das ist Tate und Trevor klar. Und schon gar nicht sollten sie den Wunsch verspüren, das Ganze zu wiederholen. Doch für die beiden ist es unmöglich, das Kribbeln zwischen ihnen zu ignorieren. Dabei kann Trevor auf keinen Fall erneut bei Tate schwach werden. Zu nah kommt die junge Studentin seinem dunkelsten Geheimnis: Während sie versucht, herauszufinden, warum ihr Bruder starb, setzt er alles daran, die Antwort auf diese Frage für immer vor ihr zu verbergen ...', '06.06.2025', 'LYX', ARRAY['Deutsch']::text[], 395, 25, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', ARRAY['Double POV','1P']::text[], ARRAY['Tate','Trevor']::text[], ARRAY['Secred Identity','Universicy/College']::text[], '{}', '87573a33-56b5-5e09-9b56-b6b6e62d8015', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
