insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c604f673-fbf0-5ae1-b2ee-ff90d90d8300', 'Der letzte erste Song', NULL, '9783736324800', 'Ich werde nie wieder singen. Dieses Versprechen hat sich Grace vor langer Zeit gegeben. Doch als Masons Band eine Sängerin sucht, lässt sie sich dazu überreden mitzumachen. Allerdings ist sie nicht auf das Prickeln vorbereitet, das sie plötzlich in Masons Nähe spürt - und auch nicht auf die Erkenntnis, dass sich hinter seinen vorlauten Sprüchen viel mehr verbirgt, als es den Anschein hat. Mit ihm gemeinsam Songs zu schreiben fühlt sich richtiger an als alles andere. Aber Grace weiß, dass sie nie mehr als Freunde sein können. Denn Masons Herz gehört einer anderen ...', '06.06.2025', 'LYX', ARRAY['Deutsch']::text[], 451, 29, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', ARRAY['Double POV','1P']::text[], ARRAY['Grace','Mason']::text[], ARRAY['Friends to Lovers','Famous Person']::text[], '{}', '87573a33-56b5-5e09-9b56-b6b6e62d8015', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
