insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cda31298-ead1-551c-9463-6dc98e419d37', 'Midnight Chronicles - Schattenblick', NULL, '9783736312777', '449 entflohene Seelen. 449 Tage, um sie zurück in die Unterwelt zu schicken. Roxy weiß, dass ihre Mission so gut wie unmöglich ist. Dass sie jetzt auch noch ein Auge auf den mysteriösen Shaw haben soll, der von einem Geist besessen war und seitdem keinerlei Erinnerungen an seine Vergangenheit hat, passt ihr daher gar nicht. Vor allem weil das Kribbeln zwischen ihnen mit jedem Augenblick, den sie miteinander verbringen, heftiger wird. Und das ist nicht nur für Roxys Herz gefährlich - sondern auch für ihr Leben ...', '26.08.2020', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Roxy','Shaw']::text[], ARRAY['Enemies to Lovers']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '1', '{}', 'sheet', :'owner') on conflict do nothing;
