insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('395532e2-3523-584f-a17d-06c133c237ec', 'Midnight Chronicles - Blutmagie', NULL, '9783736313477', 'Cain und Warden können sich kaum vorstellen, dass sie vor drei Jahren noch Kampfpartner waren, die einander bedingungslos vertrauten. Zu groß sind die Differenzen, die die beiden Blood Hunter nun trennen, zu schwer wiegt der Schmerz, nachdem sie einander so sehr verletzt haben. Doch die Rückkehr des Vampirkönigs Isaac lässt ihnen keine andere Wahl, als erneut zusammenzuarbeiten. Und während sie gemeinsam um Leben und Tod kämpfen, müssen sie sich fragen, ob es für sie beide nicht vielleicht doch eine zweite Chance geben kann ...', '24.02.2021', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cain','Warden']::text[], ARRAY['Second Chance','Enemies to Lovers']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
