insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('acc5e1a3-a692-5f09-ad84-938c7b61f4b3', 'Midnight Chronicles - Dunkelsplitter', NULL, '9783736313484', 'Nur noch 93 Tage. Roxy weiß, dass es unmöglich ist, ihre Mission innerhalb dieser Zeit zu erfüllen. Eigentlich dürfte sie sich keine Ablenkung erlauben - aber das ist leichter gesagt als getan. Schließlich verbringt sie jede Minute gemeinsam mit Shaw, während sie durch Europa reisen und die Wesen einfangen, die Roxy versehentlich aus der Unterwelt befreit hat. Doch die Möglichkeit auf ein Happy End für die freie Huntress rückt in unerreichbare Ferne, als Shaw plötzlich erfährt, wer er wirklich ist - und daraufhin eine folgenschwere Entscheidung treffen muss ...', '25.08.2021', 'LYX', ARRAY['Deutsch']::text[], 412, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Roxy','Shaw']::text[], ARRAY['Soul Mates','Forced Proximity']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '3', '{}', 'sheet', :'owner') on conflict do nothing;
