insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('82050e9e-8481-565a-9954-b98751190c38', 'Midnight Chronicles- Seelenband', NULL, '9783736313491', 'Ella hat am Tag des Blutbades alles verloren - und gibt sich selbst die Schuld daran. Als einziger Ausweg bleibt der Soul Huntress die Flucht nach Prag, weit weg von all dem, was sie quält. Doch dann steht ausgerechnet die eine Person wieder vor ihr, die sie mit allen Mitteln zu vergessen versucht: Wayne McKinley. Einst ihr süßestes Geheimnis, scheint Wayne nun nur noch eine schmerzvolle Erinnerung zu sein. Ella bleibt jedoch keine andere Wahl, als mit ihm zusammenzuarbeiten, um ihren Fehler vom Tag des Blutbades wiedergutzumachen. Auch auf die Gefahr hin, dass ihre Gefühle für den Hunter mit jeder gemeinsam verbrachten Minute stärker werden.', '23.02.2022', 'LYX', ARRAY['Deutsch']::text[], 446, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Prag', '{}', ARRAY['Ella','Wayne McKinley']::text[], ARRAY['Second Chance','Forced Proximity','Enemies to Lovers']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
