insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8f9a51b6-abaf-5a5f-a937-967d8b6031d7', 'Midnight Chronicles - Todeshauch', NULL, '9783736313507', 'Endlich haben Roxy und Shaw ihren Gefühlen füreinander nachgegeben und sind sich nähergekommen. Da trennt das Schicksal sie auch schon wieder - und dieses Mal scheint es endgültig zu sein. Shaw würde Himmel und Hölle in Bewegung setzen, um Roxy zurückzubekommen, doch selbst wenn ihm das gelingt, wartet immer noch der Fluch des Todesboten auf sie. Wenn es Roxy nicht schafft, alle entflohenen Seelen in die Unterwelt zu schicken, landet sie selbst dort. Und die Enthüllung von Shaws Vergangenheit stellt sie vor eine schier unmögliche Entscheidung: Kann sie den Fluch brechen, selbst wenn das bedeuten würde, Shaw für immer zu verlieren?', '25.05.2022', 'LYX', ARRAY['Deutsch']::text[], 438, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Roxy','Shaw']::text[], ARRAY['Soul Mates','Forbidden Love','Star-crossed Lovers']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '5', '{}', 'sheet', :'owner') on conflict do nothing;
