insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9284c92d-7324-566b-a2b5-6e2bb0db4f62', 'Midnight Chronicles - Nachtschwur', NULL, '9783736313514', 'Schon seit ihrer gemeinsamen Hunter-Ausbildung ist Jules Marlowe unsterblich in Harper Iwanow verliebt. Er ist überzeugt, dass hinter der kühlen Fassade der Magic Huntress noch so viel mehr steckt. Doch als Jules in einen Vampir verwandelt wird, verschwindet auch der letzte Funken Hoffnung für Harper und ihn. Nicht nur, dass er nun zu den Wesen gehört, welche die Huntress bekämpft, er verletzt im Blutrausch auch ihren Zwillingsbruder schwer. Nun sinnt Harper auf Rache und macht unerbittlich Jagd auf Jules. Aber als sie ihm schließlich gegenübersteht, sieht sie vor sich keinen blutrünstigen Vampir, sondern nur den Mann, der ihr Herz gefährlich schnell schlagen lässt ...', '24.08.2022', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jules Marlowe','Harper Iwanow']::text[], ARRAY['Enemies to Lovers','He falls first']::text[], '{}', 'b11f16f2-0752-594b-910a-e23f94a910f7', '6', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
