insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b843181c-f6cd-58bb-8fd7-5ce90102c612', 'Ouran Highschool Host Club (Vol. 1)', 'ōran Kōkō Hosuto Kurabu', '9783551787118', 'Die Ouran High School ist eine Privatschule für die Sprösslinge der oberen Zehntausend. Als sich Haruhi Fujioka in das Musikzimmer 3 verirrt, steht sie plötzlich den sechs gut aussehenden Mitgliedern des »Host Clubs« gegenüber. Vor lauter Aufregung stößt sie eine unfassbar teure Vase um. Nur gut, dass Haruhi dank ihres jungenhaften Aussehens selbst als Host durchgehen kann, und so wird sie verpflichtet neue Gäste anzuwerben, um ihre Schulden zu begleichen. Dabei darf natürlich nicht auffliegen, dass sie eigentlich ein Mädchen ist.', '22.12.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Comedy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Ouran High School', ARRAY['3P Objective']::text[], ARRAY['Haruhi Fujioka']::text[], '{}', '{}', '74ed781f-b3af-5292-b1dc-a07322440142', '1', '{}', 'sheet', :'owner') on conflict do nothing;
