insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a56ac657-ae80-53aa-b6dd-202673cca39c', 'A Curse So Dark And Lonely', NULL, '9781408884614', 'Prince Rhen, the heir to Emberfall, is cursed. Forced to repeat the autumn of his eighteenth year over and over, he can only be freed by love. But at the end of each autumn he is transformed into a beast hell-bent on destruction, and after so many failed attempts, his kingdom and its people are barely holding on. Harper''s life has never been easy, but she''s learned to be tough enough to survive. She won''t let anything hold her back, not her cerebral palsy or her mother''s deteriorating health. But when she is sucked into Rhen''s world, nothing is as it seems. Powerful forces are standing against Emberfalll ... and it will take more than a broken curse to save it from utter ruin.', '29.01.2019', 'Bloomsbury', ARRAY['Englisch']::text[], 477, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Rhen','Harper']::text[], '{}', '{}', 'd6a46650-11e1-567c-ba44-e2cccb7c5acf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
