insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d65045f-be32-5ac0-bef3-98a65598aedf', 'A Heart So Fierce And Broken', NULL, '9781408885086', 'Harper has freed Prince Rhen from the curse that almost destroyed his kingdom. But all is not well; rumours are rife that there is a rival heir with a stronger claim to the throne and that ''Princess'' Harper of Disi is nothing but a fraud. Grey has fled the castle carrying a terrible secret. When he is discovered by soldiers and returned to Ironrose by force, Grey''s allegiances begin to shift. And as he grows closer to an enemy princess, he is forced to decide whether he will stand against Rhen for the crown he never wanted …', '07.01.2020', 'Bloomsbury', ARRAY['Englisch']::text[], 460, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Rhen','Harper']::text[], '{}', '{}', 'd6a46650-11e1-567c-ba44-e2cccb7c5acf', '2', '{}', 'sheet', :'owner') on conflict do nothing;
