insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f22cb013-e15d-5edd-8b14-e8e8ad761638', 'Was wir im Stillen fühlten', 'The Problem with Dating', '9783736321694', 'Yara Kingsley hat nach einer schlimmen Trennung genug um die Ohren. Dass sie ständig mit Sternekoch Alex aneinandergerät, der gerade sein neues Restaurant gegenüber von ihrem Geschäft eröffnet hat, ist das Letzte, was sie jetzt braucht. Doch beide können auch nicht leugnen, dass zwischen ihnen nicht nur die Fetzen fliegen, sondern bei jeder Begegnung auch ein heißes Knistern in der Luft liegt. Und als Alex Yaras Hilfe benötigt, ist das ihre Chance auf eine Gegenleistung: Sie gehen gemeinsam auf die Hochzeit von Alex’ bestem Freund, um Yaras Ex ein klares Signal zu senden. Doch sie hat nicht damit gerechnet, dass sie alles an Alex plötzlich viel zu sehr daran erinnert, wie die Liebe sein kann ...', '30.08.2024', 'LYX', ARRAY['Deutsch']::text[], 415, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Honey Creek', '{}', ARRAY['Yara Kingsley','Alex']::text[], ARRAY['Enemies to Lovers','Fake Dating']::text[], '{}', '828ae8b8-4cd8-5124-b20f-828aa31fbec6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
