insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cfceb7b0-cc41-5bed-83a0-ae62123141d3', 'Wenn der Morgen die Dunkelheit vertreibt', 'Between the Notes', '9783736310742', 'Jackson Emery glaubt nicht an Versprechen. Und ich glaube nicht mehr an die Liebe. Ich bin zu zerbrochen für ihn. Er ist nicht der Richtige für mich. Und doch sind wir perfekt füreinander. Weil wir wissen, dass das zwischen uns nicht für immer sein wird. Weil wir die Hoffnung längst aufgegeben haben, dass uns jemand für den Rest unseres Lebens lieben könnte. Bis der Moment des Abschieds gekommen ist und wir plötzlich merken, dass wir nie wieder ohneeinander sein können.', '31.10.2019', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jasmine Greene','Jackson Emery']::text[], ARRAY['Second Chance']::text[], '{}', '4314cc71-85d3-599a-b15b-268b6f0deae2', '2', '{}', 'sheet', :'owner') on conflict do nothing;
