insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('644fcd06-7318-5261-9356-18f631afc455', 'Wenn Donner und Licht sich berühren', 'Behind the Bars', '9783736308305', 'Sich in Jasmine Greene zu verlieben, fühlte sich an wie ein warmer Sommerregen. Leicht und unbeschreiblich schön. Aber als wir uns Jahre später wieder gegenüberstehen, ist von dem Sommerregen nichts mehr übrig. Stattdessen sehe ich in ihren Augen einen tosenden Sturm. Wie lange tobt er schon dort? Wie lange hat er sich schon in ihrer Seele zusammengebraut? Ihr Herz ist für immer gebrochen, und ich hasse mich dafür, dass ich es jetzt erst bemerke - wo es vielleicht schon zu spät ist.', '24.09.2019', 'LYX', ARRAY['Deutsch']::text[], 375, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jasmine Greene','Jackson Emery']::text[], ARRAY['Second Chance','He falls first']::text[], '{}', '4314cc71-85d3-599a-b15b-268b6f0deae2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
