insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6ce4c2d8-f6f8-5aa0-9a29-a2ecab077840', 'Was wir verloren glaubten', 'The Problem with Players', '9783736323032', 'Avery Kingsleys großer Traum geht in Erfüllung, als sie das Angebot bekommt. In der nächsten Saison das Baseball-Team der Highschool als Head-Coach zu trainieren. Doch plötzlich ist Baseball-Star Nathan Pierce zurück in Honey Creek - und mit ihm sorgsam verstaute Erinnerungen an Averys erste große Liebe. Nathan soll sich mit ihr die Leitung des Teams teilen, dabei möchte Avery nichts lieber, als sich von ihm fernzuhalten und ihr Herz zu beschützen. Denn sie spürt bei jeder Begegnung, dass das Spiel zwischen ihnen auch für Nathan noch nicht vorbei ist ...', '31.01.2025', 'LYX', ARRAY['Deutsch']::text[], 464, 51, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Honey Creek', '{}', ARRAY['Avery Kingsleys','Nathan Pierce']::text[], ARRAY['Second Chance','Sport','High School']::text[], '{}', '828ae8b8-4cd8-5124-b20f-828aa31fbec6', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
