insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7d6e337c-4913-502e-9d2e-42188349eedc', 'Was wir leise hofften', 'The Problem with Falling', '9783736323049', 'Für Willow Kingsley bedeutet Freiheit alles - immer unterwegs, ohne festes Zuhause. Doch als sie für einen Sommer nach Honey Creek zurückkehrt und ihr Wohnmobil auf dem Grundstück von Theo Langford parkt, gerät alles ins Wanken. Willow wirbelt das Leben ihres mürrischen Nachbarn komplett durcheinander, während sie selbst merkt, wie schwer es ist, die Fassade aufrechtzuerhalten, mit der sie sonst anderen Menschen begegnet. Theo erkennt bald, dass sich hinter ihrem Lächeln eine tiefe Traurigkeit und Gefühle verbergen, die er selbst nur zu gut kennt. Doch kann Willow alles, was sie sich aufgebaut hat, hinter sich lassen, um bei Theo endlich sie selbst zu sein?', '25.07.2025', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Honey Creek', '{}', ARRAY['Willow Kingsley','Theo Langford']::text[], ARRAY['Single Parent','Small Town','He falls first']::text[], '{}', '828ae8b8-4cd8-5124-b20f-828aa31fbec6', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
