insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('099cd7a8-0755-5b8c-b9ef-f57a6cfdcdea', 'Ewiglich - Die Sehnsucht', 'Everneath', NULL, 'Wenn die Unsterblichen das größte Opfer verlangen... Jack ist Nikkis große Liebe. Eine Liebe, die sie durch die Finsternis der Unterwelt getragen hat. Endlich, nach hundert Jahren der Sehnsucht, kehrt Nikki zurück. Doch ihr bleibt nur ein halbes Jahr … Ihre Freunde und ihr Vater glauben, dass sie einfach abgehauen war, doch in Wirklichkeit hat der Rockmusiker Cole sie mit in die Unterwelt genommen. Cole ist ein Unsterblicher, der sich von den Gefühlen der Menschen ernährt. Nur Nikkis Liebe zu Jack hat sie davor bewahrt zu sterben und ihr ermöglicht, auf die Erde zurückzukehren. Cole, mit dem sie ein seltsam enges Band verbindet, bedrängt sie, mit ihm gemeinsam in der Unterwelt zu herrschen. Doch Jack, der Nikki niemals wieder verlieren möchte, riskiert alles für sie …', '01.01.2012', 'Oetinger', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Jack','Nikki','Cole']::text[], '{}', '{}', '55e4a7b4-a905-5a7a-83b5-9f861107ea07', '1', '{}', 'sheet', :'owner') on conflict do nothing;
