insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('673ef3ae-7abf-5dd4-b5a2-2e170a008e3a', 'Ewiglich - Die Hoffnung', 'Everbound', NULL, 'Sehnsucht, stärker ist als jede Vernunft. Liebe, ewig und für alle Zeiten. Nichts wünscht sich Nikki sehnlicher zurück als Jack, der sich für sie geopfert hat und den Weg ins Ewigseits angetreten war. Nun versucht Nikki alles, um ihn zu retten. Doch die Träume, in denen Jack ihr erscheint, werden immer schwächer und sie weiß, dass ihr nicht mehr viel Zeit bleibt. Da macht der undurchschaubare Cole ihr ein unglaubliches Angebot und verspricht, Jack zu finden. Doch kann Nikki ihm wirklich trauen?', '03.12.2012', 'Oetinger', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Jack','Nikki','Cole']::text[], '{}', '{}', '55e4a7b4-a905-5a7a-83b5-9f861107ea07', '2', '{}', 'sheet', :'owner') on conflict do nothing;
