insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1bd6caf8-fb34-580e-9b41-9f0dabf23d91', 'Ewiglich - Die Liebe', 'Evertrue', NULL, 'Große Gefühle: das dramatische Finale der „Ewiglich“-Trilogie. Nikki hat einen hohen Preis zahlen müssen, um Jack zu retten: der Ewigliche Cole hat sich durch eine List ihres Herzens bemächtigt. Noch immer sieht er in ihr seine Persephone, die Herrscherin der Unterwelt. Während Nikki und Jack alles daran setzen, das Herz zurückzugewinnen, bereiten Cole und seine Freunde sich darauf vor, den Kampf um die Herrschaft des Ewigseits zu gewinnen. Nikki erkennt, dass sie nur eine Chance hat, die Ewiglichen zu vernichten: Sie muss Coles Persephone werden.', '15.05.2014', 'Oetinger', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Jack','Nikki','Cole']::text[], '{}', '{}', '55e4a7b4-a905-5a7a-83b5-9f861107ea07', '3', '{}', 'sheet', :'owner') on conflict do nothing;
