insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a3e965be-40a5-5c14-b6af-076279b3a44a', 'Taming the Tiger (Vol.1)', '범을 길들이는 요령', '9783551630704', 'Um seinen kleinen Bruder mit Tierblut medizinisch zu versorgen, macht sich Geum-Hoo, der älteste Sohn der Familie Ahn, auf die Suche nach einem Schlachter. Unterwegs trifft er auch auf einen solchen, der jedoch namenlos ist und einen seltsamen Eindruck macht. Geum-Hoo beschließt, den Fremden "Beom" zu nennen und ihm in seinem Haus ein Obdach zu gewähren. Noch ahnt er nicht, dass die ungewöhnliche Anziehungskraft zu Beom immer stärker werden und er einen wilden Tiger zu zähmen haben wird...', '09.01.2025', 'Lines', ARRAY['Deutsch']::text[], 256, 16, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Koreanischer Palast', ARRAY['3P Objective']::text[], ARRAY['Geum-Hoo Ahn','Beom']::text[], ARRAY['Queer','Rich vs. Poor','Royalty']::text[], '{}', '4df1c0a5-998d-5850-884d-358d9b5dd3cf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
