insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('13c5f69b-c10f-5945-9df6-85cd98a5f81b', 'Taming the Tiger (Vol.5)', '범을 길들이는 요령', '9783551630766', 'Um seinen kleinen Bruder mit Tierblut medizinisch zu versorgen, macht sich Geumhoo, der älteste Sohn der Familie Ahn, auf die Suche nach einem Metzger. Unterwegs trifft er auch auf einen solchen, der jedoch namenlos ist und einen seltsamen Eindruck macht. Geumhoo beschließt, den Fremden "Beom" zu nennen und ihm in seinem Haus ein Obdach zu gewähren. Noch ahnt er nicht, dass die ungewöhnliche Anziehungskraft zu Beom immer stärker werden und er einen wilden Tiger zu zähmen haben wird...', '02.09.2025', 'Lines', ARRAY['Deutsch']::text[], 256, 16, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Koreanischer Palast', ARRAY['3P Objective']::text[], ARRAY['Geum-Hoo Ahn','Beom']::text[], ARRAY['Queer','Rich vs. Poor','Royalty']::text[], '{}', '4df1c0a5-998d-5850-884d-358d9b5dd3cf', '5', '{}', 'sheet', :'owner') on conflict do nothing;
