insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c480b9b8-9909-5bae-96f8-f6835a654fe7', '653b5180-f64c-5b4e-9e9d-5fc416a0e503', :'owner', 1, '2025-09-04', '2025-09-07', NULL, NULL, 4, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('09ca54a4-da48-5f8d-ab87-17e81a55c1e2', 'Shadow Falls Camp - Geboren um Mitternacht', 'Shadow Falls Camp - Born at Midnight', '9783104010472', 'In Kylies Leben geht alles schief: Ihre Eltern lassen sich scheiden, ihr Freund hat Schluss gemacht, und ihre Mutter schickt sie auch noch in ein Sommercamp. Doch Shadow Falls ist anders: Hierher kommt nur, wer übernatürliche Kräfte hat – Feen, Hexen, Vampire, Gestaltwandler und Werwölfe. Auch Kylie soll besondere Fähigkeiten haben – wenn sie nur wüsste, welche… Doch plötzlich wird das Camp bedroht. Nur, wenn sie alle ihre besonderen Kräfte gemeinsam einsetzen, werden sie die übermächtigen Feinde besiegen können.', '21.06.2012', 'Fischer', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadow Falls Camp', '{}', ARRAY['Kylies']::text[], '{}', '{}', 'be3ef61d-acf9-5a6c-b5ef-1ce0438c6ca0', '1', '{}', 'sheet', :'owner') on conflict do nothing;
