insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('43837633-2d96-5233-9a07-4e5c9a465841', '4bfa9f55-9149-52cb-8576-acb7e74d3c8a', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fa627951-4066-563b-a845-93ea83cfe224', 'Shadow Falls Camp - Erwacht im Morgengrauen', 'Shadow Falls Camp - Awake at Dawn', '9783104010489', 'Von dem Moment an, als Kylie im Shadow Falls Camp angekommen ist, will sie nur eines wissen: Was bin ich? Umgeben von Werwölfen, Vampiren, Hexen und Gestaltwandler möchte Kylie endlich herausfinden, welche Art von Wesen sie ist, und was ihre übernatürlichen Kräfte zu bedeuten haben. Kaum hat Kylie sich einigermaßen im Camp eingelebt, überschlagen sich die Ereignisse. Ihre übernatürlichen Fähigkeiten entwickeln sich, ein Geist taucht auf und warnt sie, dass jemand, den sie liebt, sterben wird, und eine Vampirgang zieht mordend durch die umliegenden Städte. Auch in Kylies Liebesleben ist keine Besserung in Sicht: Sie versucht zwar ihre Zeit mit Derek zu genießen, kann aber Lucas nicht vergessen. Als sie ein Wochenende bei ihrer Mutter verbringen soll, um endlich Abstand zu gewinnen, findet sie auch dort keine Ruhe: Ohne den Schutz des Camps ist sie gefährlichen dunklen Mächten ausgeliefert und es kommt zu einem Kampf auf Leben und Tod.', '19.12.2012', 'Fischer', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadow Falls Camp', '{}', ARRAY['Kylies']::text[], '{}', '{}', 'be3ef61d-acf9-5a6c-b5ef-1ce0438c6ca0', '2', '{}', 'sheet', :'owner') on conflict do nothing;
