insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e1356582-ba57-51af-a629-7856aabf0236', 'Shadow Falls Camp - Entführt in der Dämmerung', 'Shadow Falls Camp - Taken at Dusk', '9783104010496', 'Diese geheimnisvolle Prophezeiung geht Kylie nicht mehr aus dem Kopf. Gemeinsam mit Hexen, Vampiren, Gestaltwandlern, Feen und Werwölfen ist sie im Shadow Falls Camp – und Kylie hat keinen sehnlicheren Wunsch, als endlich herauszufinden was sie ist und wer ihre wahre Familie ist. Außerdem fragt sie sich noch immer welcher Junge der Richtige für sie ist. Lucas und Kylie kommen sich zwar immer näher, aber dann erfährt sie, dass sein Rudel ihre Beziehung nicht gutheißt. War es falsch, sich für Lucas zu entscheiden? Um sich vom Liebeschaos abzulenken, versucht Kylie einem Geist zu helfen, der sein Gedächtnis verloren hat und es nur schafft, immer wieder eine mysteriöse Nachricht zu wiederholen: »Jemand wird leben … aber jemand anderes muss sterben.« Um diese Botschaft zu entschlüsseln, muss Kylie jedoch den sagenumwobenen, furchteinflößenden Friedhof von Shadow Falls betreten. Vielleicht kann sie dort endlich das Geheimnis ihrer Identität lösen – die ganz anders ist, als sie es sich je hätte vorstellen können.', '07.03.2013', 'Fischer', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadow Falls Camp', '{}', ARRAY['Kylies']::text[], '{}', '{}', 'be3ef61d-acf9-5a6c-b5ef-1ce0438c6ca0', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('18d1cd78-82d4-5f2b-b745-3bf60fb2a896', :'owner', 'e1356582-ba57-51af-a629-7856aabf0236', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, NULL, 'erfuellt'::expectation_kind, 0, NULL, NULL) on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('ade306f6-06f7-5e6d-a975-6620c71ec303', '18d1cd78-82d4-5f2b-b745-3bf60fb2a896', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d0ffea78-7049-5e2e-8c30-de87c5abf161', 'Shadow Falls Camp - Verfolgt im Mondlicht', 'Shadow Falls Camp - Whispers at Moonrise', '9783104028309', 'Kylie hat es endlich geschafft: Sie hat herausgefunden, was sie ist. Doch damit ist nur eins von vielen Rätseln gelöst. Denn über ihre Art ist kaum etwas bekannt. Wie kann sie ihre übernatürlichen Kräfte einsetzen, und was ist das für ein geheimnisvolles Flüstern im Wald, das nur sie hören kann? Außerdem verhält sich Lucas seltsam, nun da es sicher ist, dass sie keine Werwölfin ist. Derek hingegen akzeptiert ihre Identität und ist für sie da. War es falsch, ihn abzuweisen? Als plötzlich ein furchterregender Geist auftaucht, muss Kylie sich beeilen, um jemanden der ihren vor einer schrecklichen Gefahr retten zu können. Dabei wird ihr mehr und mehr klar, dass Veränderungen unausweichlich sind, und alles irgendwann ein Ende finden muss. Vielleicht auch ihre Zeit im Shadow Falls Camp …', '25.07.2013', 'Fischer', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadow Falls Camp', '{}', ARRAY['Kylies']::text[], '{}', '{}', 'be3ef61d-acf9-5a6c-b5ef-1ce0438c6ca0', '4', '{}', 'sheet', :'owner') on conflict do nothing;
