insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('01dc2cee-2e5e-518e-82c9-a6bb71641392', 'ab880655-5eb6-519d-9017-3a0748c68dd0', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6e81c16a-fd9b-5e7a-861b-1c451cdaeefb', 'Shadow Falls Camp - Erwählt in tiefster Nacht', 'Shadow Falls Camp - Chosen at Nightfall', '9783104028682', 'Feen, Hexen, Vampire, Gestaltwandler und Werwölfe: Sie alle sind im Shadow Falls Camp. Auch Kylie möchte dorthin zurück und einfach glücklich sein – doch zuvor muss sie sich ihrem gefährlichsten Gegner stellen und für ihre große Liebe kämpfen. Kylie hat das Shadow Falls Camp verlassen und ist zu ihrem Großvater und ihrer Großtante in die Chamäleon-Gemeinschaft gezogen. Dort will sie mit anderen Jugendlichen ihrer Art mehr über sich erfahren und lernen, wie sie ihre unglaublichen Kräfte anwenden kann. Aber Kylie vermisst das Shadow Falls Camp, vor allem ihre Freunde dort. Als im Shadow Falls Camp etwas Schreckliches geschieht, das auch Kylie in Gefahr bringen könnte, tauchen Burnett und Derek auf, um sie zurückzuholen. Doch die Chamäleon-Gemeinschaft will Kylie nicht gehen lassen, und es bleibt nur eine Möglichkeit… Kylie muss sich entscheiden: Wo ist ihr Zuhause? Und wen liebt sie wirklich – Lucas oder Derek?', '21.11.2013', 'Fischer', ARRAY['Deutsch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadow Falls Camp', '{}', ARRAY['Kylies']::text[], '{}', '{}', 'be3ef61d-acf9-5a6c-b5ef-1ce0438c6ca0', '5', '{}', 'sheet', :'owner') on conflict do nothing;
