insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a42e5fa8-21c0-5375-a12d-f92afc5e2039', 'New York Alpha (Prolog)', NULL, '9783759215529', 'Wow, das wird mir nie im Leben jemand glauben … Ich, das einfache Hooters Girl, bin mit zwei scharfen Kerlen unterwegs, die sich in riesige Wölfe – oder Canicore, wie sie sich nennen – verwandeln können. Sitze mit ihnen in einem Auto und fahre Richtung Manhattan zu ihrem luxuriösen Penthaus, wo noch vier weitere solche Typen wohnen. Entweder bin ich gerade auf einem Trip, der mich in ein heißes Paralleluniversum befördert hat, oder aber das hier ist der Start in ein äußerst aufregendes Leben. An der Seite dieses breitschultrigen Mannes, der neben mir sitzt, dessen Duft mich um den Verstand bringt, und der behauptet, der Anführer eines Rudels zu sein. Der Alpha. Und ich bin … ›eine‹ Omega. Nicht ›seine‹. Denn dafür müsste Adrian mit mir schlafen wollen …', '31.05.2024', 'Sternensand', ARRAY['Deutsch']::text[], 140, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Helena']::text[], ARRAY['Omegaverse','Reverse Harem']::text[], '{}', '9cf8eef6-1a27-5a79-a2fe-b0c034336502', '1', '{}', 'sheet', :'owner') on conflict do nothing;
