insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b5224620-7a84-5957-8146-2dae1a34f7f3', 'Run for Your Life', NULL, NULL, 'Homicide Detective Mitch Cannon’s weekend plans take a sinister turn when his sister, Marie, vanishes without a trace. His much-anticipated date with the bold and enigmatic Liza is canceled, and before he can catch his breath, Liza and his partner, Devon, also disappear. The only clue? A chilling phone call from a blocked number: “Ticktock, ticktock.“ As the hours slip away, Mitch races against the clock with the full force of the Habersham precinct behind him. With no leads and three lives hanging in the balance, the stakes couldn’t be higher. Can Mitch uncover the truth before the timer runs out—or will the people he cares about disappear forever?', '23.01.2022', NULL, ARRAY['Englisch']::text[], 260, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mitch Cannon']::text[], '{}', '{}', '434f05a8-13df-598b-b663-42e4a99b9026', '1', '{}', 'sheet', :'owner') on conflict do nothing;
