insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d22eec66-5e0e-5eb1-9466-6f68e9d3438b', 'Frost', NULL, '9783736325463', 'Ava Jones lebt als Fae in der Menschenwelt und macht gerade eine schlimme Zeit durch. Denn als sie ihren Freund beim Fremdgehen erwischt, verliert sie nicht nur ihr Zuhause, sondern auch den Glauben an die Liebe. Ausgerechnet da trifft sie auf den Fae-König Torin, der demnächst heiraten soll - und zwar die Gewinnerin eines Turniers um Leben und Tod. Davon hält Torin nicht viel, genau wie von der Liebe, und bietet Ava fünfzig Millionen Dollar, wenn sie das Turnier gewinnt und eine Fake-Ehe mit ihm eingeht. In ihrer Situation kann Ava nicht anders als zuzustimmen. Doch je mehr Zeit sie mit dem attraktive Torin verbringt, desto schwerer fällt es beiden, sich daran zu erinnern, dass nichts zwischen ihnen echt ist. Vor allem, weil eine Beziehung mit Torin Gefahren bergen würde, von denen Ava noch nichts ahnt ...', '01.08.2025', 'LYX', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ava Jones','Torin']::text[], '{}', '{}', 'daf356ac-7f05-5bf2-bdd9-0a26a70973c7', '1', '{}', 'sheet', :'owner') on conflict do nothing;
