insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('67677371-ca2a-55ca-ba87-11f9a417cec4', 'Dark Rise', NULL, '9783736318236', 'Die alte Magie ist in Vergessenheit geraten. Lediglich der Orden der Stewards hält seinen Schwur, die Menschheit vor der Rückkehr des Dunklen Königs zu schützen - die unmittelbar bevorsteht. All dies erfährt Will von den Kämpfern des Lichts, als sie ihn vor den Mördern seiner Mutter retten. Und seine Welt wird noch mehr auf den Kopf gestellt, als die Stewards ihm offenbaren, dass er der Auserwählte im Kampf gegen die Dunklen Mächte sein soll. Während Will versucht, sich in kürzester Zeit auf diese Rolle vorzubereiten, trifft er auf James St. Clair, den General des Dunklen Königs - und somit Wills Gegenspieler. Doch von Anfang an spürt Will, dass ihre Schicksale durch ein unsichtbares Band miteinander verbunden sind und dass ihr Aufeinandertreffen immer vorherbestimmt war ...', '30.09.2022', 'LYX', ARRAY['Deutsch']::text[], 535, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Will']::text[], ARRAY['The Chosen One','Soul Mates','Enemies to Lovers']::text[], '{}', 'ed9c314a-c7d4-5ce0-b7e1-b02d73d90256', '1', '{}', 'sheet', :'owner') on conflict do nothing;
