insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a58ac63a-2493-5455-8486-977985be1057', 'Dark Heir', NULL, '9783736318427', 'Der magische Krieg gegen die Dunklen Kräfte ist noch nicht vorüber: Eine neue Gefahr erhebt sich, doch nur eine Handvoll Kämpfer:innen des Lichts sind übrig. Will Kempen und seine Vertrauten müssen ins Herz der Alten Welt reisen, neue Bündnisse schließen und Rätsel der Vergangenheit entschlüsseln, um die Rückkehr des Dunklen Königs aufzuhalten. Doch Will selbst trägt ein Geheimnis in sich - die Wahrheit darüber, wer er wirklich ist. Jede wache Sekunde ringt er mit der Dunkelheit, die in ihm schlummert, und auch die Anziehung zu dem verführerischen, aber gefährlichen James St. Clair macht es ihm nicht leichter, gegen das Schicksal anzukämpfen, das ihm prophezeit wurde ...', '31.05.2024', 'LYX', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Will']::text[], ARRAY['Enemies to Lovers','The Chosen One']::text[], '{}', 'ed9c314a-c7d4-5ce0-b7e1-b02d73d90256', '2', '{}', 'sheet', :'owner') on conflict do nothing;
