insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('706fbf9a-c6f2-512a-a2c6-7d4bf2fa8b3f', 'Lover to go', NULL, NULL, 'Dylan versteht die Welt nicht mehr. Sein Freund beendet von heute auf morgen ihre – zugegeben etwas eingefahrene – Beziehung und verschwindet spurlos. Auch seine Arbeit im Coffeeshop leidet darunter, was seinem Chef Jeremy natürlich nicht verborgen bleibt. Als ihm die Situation schließlich über den Kopf wächst, verliert Dylan vor seinem Chef und den Kollegen die Beherrschung. Anstatt ihn jedoch zu feuern, überrumpelt Jeremy ihn mit einem atemberaubenden Kuss, der Dylans Leben für immer verändern wird…', '2017', 'FanFiktion', ARRAY['Deutsch']::text[], 490, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Villa Kunterbunt', '{}', ARRAY['Dylan','Jeremy']::text[], ARRAY['Queer','Holiday']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
