insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('947d5ae2-31b2-5823-8f26-24c65fb90cfe', 'Brimstone', NULL, '9781399745482', 'Saeris Fane doesn''t want power. The very last thing she needs is her name whispered on an entire court''s lips, but now that she''s been crowned queen of the Blood Court, she''s discovering that a queen''s life is not her own. A heavy weight rests upon her shoulders. Her ward - and her brother - need her back in her homeland . . . but the changes that have strengthened Saeris have also made her weak. Born under blazing suns, Saeris will surely die if she makes her way home through the Quicksilver. Which means that, once again, she must send someone else in her stead…', '18.11.2025', 'Hodder And Stoughton', ARRAY['Englisch']::text[], 660, 52, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantic Suspense']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Zilvaren, Yvelia', ARRAY['1P','Double POV']::text[], ARRAY['Saeris Fane','Kingfisher']::text[], ARRAY['Enemies to Lovers','Different Worlds','Soul Mates']::text[], '{}', '8b017d9c-46e6-56a6-b8ba-4127f8ced553', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a8d041fc-d647-5962-a63e-25cf78379066', :'owner', '947d5ae2-31b2-5823-8f26-24c65fb90cfe', 'gelesen'::reading_status, true, true, ARRAY['Print','Audiobook']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['In-Book Illustrationen','Map']::text[], 2099, false, false, ARRAY['Audible']::text[], ARRAY['Stella Bloom','Anthony Palmini']::text[], 1470, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'untertroffen'::expectation_kind, 4, 'fast'::burn_kind, 'Leider hat mich das Buch an einigen Stellen sehr genervt und ich wollte es einfach hinter mich bringen. Ich hab die ganze Zeit darauf gewartet, dass es spannend wird und mich catcht, aber leider kam es nicht dazu. Allle emotionalen Stellen haben sich sofort wieder ins nichts aufgelöst... Ich konnte auch irgendwie gar keine Verbindung zu den MCs aufbauen, weil die zwei einfach nur dauerhaft Horney waren, anstatt mal normal miteinander zu reden. Leider hat dieser Band stark abgenommen im Vergleich zum ersten. 1. Nervt es mich, dass Saeris und Kinfisher keine normale Unterhaltund mehr führen können ohne entweder zu bumsen oder darüber zu sprechen. 2. Nervt es, dass Saeris einfach nie zuhören kann und aus Prinzip immer gleich feindselig ist. Und 3. ist einfach gefühlt nichts passiert in diesem Buch. Und die paar Wendungen die es gab waren leider weniger überraschen und mehr random. Trotzdem fand ich das Buch nicht ausschließlich schlecht. Ich bin gespannt, wie es weiter geht.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3590f459-9079-5ab1-bd3b-a7eb3cc32389', 'a8d041fc-d647-5962-a63e-25cf78379066', :'owner', 1, '2025-11-18', '2025-12-11', NULL, NULL, 24, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('447f7c4a-cd9d-5778-87ce-c9e07bd8eaf6', 'Quicksilver', NULL, '9781399745413', 'Twenty-four-year-old Saeris Fane is good at keeping secrets. No one knows about the strange powers she possesses, or the fact that she has been picking pockets and stealing from the Undying Queen''s reservoirs for as long as she can remember. But a secret is like a knot. Sooner or later, it is bound to come undone. When Saeris comes face-to-face with Death himself, she inadvertently re-opens a gateway between realms and is transported to a land of ice and snow. The Fae have always been the stuff of myth, of legend, of nightmares... but it turns out they''re real, and Saeris has landed herself in the middle of a centuries-long conflict that might just get her killed. The first of her kind to tread the frozen mountains of Yvelia in over a thousand years, Saeris mistakenly binds herself to Kingfisher, a handsome Fae warrior, who has secrets and nefarious agendas of his own. He will use her Alchemist''s magic to protect his people, no matter what it costs him . . . or her. Death has a name. It is Kingfisher of the Ajun Gate. His past is murky. His attitude stinks. And he''s the only way Saeris is going to make it home.', '03.12.2024', 'Hodder And Stoughton', ARRAY['Englisch']::text[], 609, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantic Suspense']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Zilvaren, Yvelia', ARRAY['Single POV','1P']::text[], ARRAY['Saeris Fane','Kingfisher']::text[], ARRAY['Enemies to Lovers','Different Worlds','Soul Mates']::text[], '{}', '8b017d9c-46e6-56a6-b8ba-4127f8ced553', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('e5678ac1-10ea-568a-8871-106a57ae7ce7', :'owner', '447f7c4a-cd9d-5778-87ce-c9e07bd8eaf6', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print']::text[], ARRAY['eBook','Hardcover']::text[], 'Deluxe', ARRAY['Map']::text[], 2099, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 4, 'slow'::burn_kind, 'Das war ein auf und ab der Gefühle. Aber das Buch war tatsächlich auch richtig witzig (Danke Carrion). Wirklich ein richtig gutes Buch! Mir hat die Welt und die Charaktere gefallen. Und das Ende war auch richtig gut. Ein guter Abschluss für das erste Buch. Trotzdem bleibt es extrem spannend, wie es weiter geht.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b26d84e8-eb60-56df-a353-89b036aa2853', 'e5678ac1-10ea-568a-8871-106a57ae7ce7', :'owner', 1, '2025-09-11', '2025-09-30', NULL, NULL, 20, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0d6614ce-1a05-5194-953b-f56df07752c5', 'The Serpent and the Wings of Night', NULL, '9783646938654', 'The adopted human daughter of the Nightborn vampire king, Oraya carved her place in a world designed to kill her. Her only chance to become something more than prey is entering the Kejari: a legendary tournament held by the goddess of death herself. But winning won’t be easy amongst the most vicious warriors from all three vampire houses. To survive, Oraya is forced to make an alliance with a mysterious rival. Everything about Raihn is dangerous. He is a ruthless vampire, an efficient killer, an enemy to her father’s crown… and her greatest competition. Yet, what terrifies Oraya most of all is that she finds herself oddly drawn to him. But there’s no room for compassion in the Kejari. War for the House of Night brews, shattering everything that Oraya thought she knew about her home. And Raihn may understand her more than anyone – but their blossoming attraction could be her downfall, in a kingdom where nothing is more deadly than love.', '14.02.2024', 'Carlsen', ARRAY['Deutsch','Englisch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Oraya','Raihn']::text[], '{}', '{}', '59be77f4-71fa-5d34-8c46-dd3d808be669', '1', '{}', 'sheet', :'owner') on conflict do nothing;
