insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0e2d3459-ae48-505a-b9ae-862c8ceb0c13', 'Einfach Koreanisch!', 'Mon Premier Diner Coréen', '9783957281784', 'Koreanische Küche liegt im Trend und gehört zu den einfachsten, frischesten und gesündesten Küchen überhaupt. Dieses koreanische Kochbuch bietet in leicht nachvollziehbaren Schritt-für-Schritt-Anleitungen Rezepte für Kleinigkeiten und Beilagen, mariniertes koreanisches Barbecue, Eintöpfe und Suppen wie die Tofusuppe Sundubu, Reisbowls, Nudelgerichte wie die Glasnudelpfanne Japchae, schnelle Snacks für die Lunchbox (Dosirak) und natürlich das fermentierte Kimchi in verschiedensten Variationen. Außerdem werden die Basics und Grundzutaten der koreanischen Küche vorgestellt und in einem separaten Kapitel sind Grundrezepte für verschiedene Brühen, Dressings, Saucen und Würzpasten zu finden. Das koreanische Kochbuch wird abgerundet durch schmackhafte Fotografien und frische Illustrationen. Einfach koreanisch! ist ein Must-Have für alle Fans der asiatischen Küche.', '20.09.2018', 'Knesebeck', ARRAY['Deutsch','Koreanisch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kochen & Ernährung', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Korea', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
