insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('811eb023-f10a-5da0-94c1-3769665ff104', 'Savage Fae', NULL, '9781914425165', 'There''s more to my brother''s murder than I realised... Shadows in the halls, mysteries lurking around every corner. Whoever killed him is covering their tracks well. And now I''m walking a dangerous line between getting close to the four kings for information and wanting to crawl deeper under their skin for my own desires. I can''t trust anyone. I can''t let my guard down. And I must keep the urges of my body separate from my heart. But I''m starting to break all of my own rules. I just hope I''m not falling for my brother''s killer.', '15.03.2023', NULL, ARRAY['Englisch']::text[], 516, 42, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Aurora Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Elise Callisto']::text[], ARRAY['Academy','Disguised Identity','Enemies to Lovers','Magical School','Revenge Plot','Reverse Harem']::text[], '{}', 'f982c515-c9b9-5f44-acf5-d18a3ba83337', '2', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('74f74540-04ff-5f7a-9a19-a27a1b189601', :'owner', '811eb023-f10a-5da0-94c1-3769665ff104', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 699, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 3, 'fast'::burn_kind, 'Das Buch hat mich richtig gefesselt und Spaß gemacht zu lesen! Das Buch hat mir immer noch sehr gut gefallen, ich würde mir nur wünschen, dass es mit der Handlung ein bisschen schneller voran ginge. Leider bummelt Elise mehr herum, als wirklich nach dem Mörder von Gareth zu suchen.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f8426d3a-e73a-5b66-b101-65fe96efc2ce', '74f74540-04ff-5f7a-9a19-a27a1b189601', :'owner', 1, '2025-02-26', '2025-03-10', NULL, NULL, 13, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('911b96e0-7be4-5c1b-8b2c-57b8e6546194', 'Echo Fort', NULL, NULL, 'The sky is burning.The Reapers are keeping secrets. Vampires roam the wastes.And I’m headed down a path of destruction which can only end in death.I’m a soul cast adrift on a tide of grief and lies. A clock ticking down the moments to my inevitable destruction, and all I can do is race towards it.The nations are caught in this endless battle for supremacy and it’s hard to see myself as anything other than a pawn in the twisted games I’m helpless to control.The Waning Lands are screaming, soaked in blood for so long that even the rivers run red with it. But those screams are whispering riddles that only some of us can hear, begging us to see the signs and listen to the meaning beneath the words we chant so obediently.What if there is something more to this war? What if winning isn’t what actually matters? What if our magic isn’t the thing that truly divides us?My heart is hardened to the wants of the world and all who occupy it, yet still I hear them call my name. Perhaps it’s time I started listening and found out why the stars have set us this fate. Or if not the stars, then who?Something is rotting at the heart of our lands. So now I have a choice to make. Will I seek out the decay and work to destroy it? Or will I join it in its destruction of this world in vengeance for all the suffering it has offered me?I’m starting to want things I shouldn’t want. Desire a man I should hate. Care for a warrior I should only wish to harm. The point is, I’m beginning to feel like more than just another pawn in this endless game. But if I want to be the one who rolls the dice then I’m going to have to pay the price of playing for real.I only wanted to claim revenge for what I’d lost.Maybe Destiny isn’t done with me yet.', '17.06.2024', 'King''s Hollow', ARRAY['Englisch']::text[], 692, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', '30c9a875-81b6-5e70-8d3b-a5bbd75c3877', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
