insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5cf69fbd-b0b3-540f-86a1-15f1dad91052', 'Vicious Fae', NULL, '9781914425172', 'The King will fall. While I continue my hunt for the Fae who killed my brother, I have to try to keep my heart away from the vicious boys who could be responsible for his death. But as my investigation leads me down a dangerous road and answers seem closer than ever before, I''m whisked away to the elite school, Zodiac Academy, with the four Kings, and my heart becomes more vulnerable than ever. There are so many secrets left to uncover, and I sense something terrible is about to come to light. But I’m in so deep to this dangerous labyrinth, what if this road only ends in blood?', '15.03.2023', NULL, ARRAY['Englisch']::text[], 642, 53, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Aurora Academy, Solaria', ARRAY['1P','Multiple POV']::text[], ARRAY['Elise Callisto']::text[], ARRAY['Academy','Disguised Identity','Enemies to Lovers','Magical School','Revenge Plot','Reverse Harem']::text[], '{}', 'f982c515-c9b9-5f44-acf5-d18a3ba83337', '3', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
