insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c196c92e-b5e3-5185-9767-c7f699d67b79', '88ee3a06-54be-506d-b33d-e8aad86e2c7c', :'owner', 1, '2025-03-10', '2025-03-24', NULL, NULL, 15, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d57c1e89-30f9-5f53-bb37-61cb0ff08a58', 'Wild Wolf', NULL, NULL, 'Freedom never tasted so bitter. A stolen love. A strangled curse. A heart of sin. And a fate touched in moonlight. My men weave a tangled web around my soul, and I’ve formed a pack that will go to death and back for me. The moon hangs low over my heart as the call of the endless sky draws me closer and I find myself lost in the abyss that was waiting for me out here. Fate has left a bitter taste on my tongue, the haunting echoes of the past mocking me at every turn. But I’m not a pup anymore. And I won’t let another ten years pass without mending the rift in my heart. Darkness draws near enough to devour me but I have forged a pack of wild creatures at my back and I won’t be pulled into the grip of despair. I’ll find the stars in this endless night and force them to hear me howl. I am Rosalie Oscura and I will claim my happy ending, even if I have to claw it from the hands of destiny itself.', '30.07.2024', NULL, ARRAY['Englisch']::text[], 343, 56, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Darkmore Penitentiary, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalie Oscura']::text[], ARRAY['Magical Creatures','Reverse Harem']::text[], ARRAY['Physische Gewalt','Tod von Familienangehörigen','Gore','Body Horror','Depiction of Trauma','Tod','Mord','Kidnapping']::text[], '94271421-cb8d-5e6a-bae8-5d2ac303498a', '4', ARRAY['Spin Off','Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ea8f6c05-a4a3-5a40-88cb-1483c61ba10c', :'owner', 'd57c1e89-30f9-5f53-bb37-61cb0ff08a58', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 799, true, true, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 749, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 5, 'fast'::burn_kind, 'Ich kann noch gar nicht glauben, dass ich damit die Original-Zodiac-Titel alle beendet habe. Ich bin bereit für was noch kommt. Ein gutes Ende für die Reihe, auch wenn es teilweise sehr schnell ging und manche Szenen, meiner Meinung nach, unnötig waren.') on conflict do nothing;
