insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('79b53385-d8af-5c8e-ad2c-865c8a212ef6', 'Zodiac Academy - Origins of an Academy Bully', NULL, '9781914425349', 'Dark magic is forbidden at Zodiac Academy. That’s why I hide it so well. But now I’m supposed to mentor Darius Acrux: the son of the most ruthless Dragon Shifter in Solaria. If he’s caught using blood magic, he’ll lose his claim to the throne. The problem is? Our families are up to something, and we’re determined to find out what. No matter what dark power we must turn to…', '13.07.2022', NULL, ARRAY['Englisch']::text[], 132, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Double POV','1P']::text[], ARRAY['Lance Orion','Darius Acrux']::text[], ARRAY['Academy','Family Drama','Magical Creatures','Mentor & Protegee']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
