insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8aa2e56f-2edf-5052-9e99-ea3d90f8323c', 'Zodiac Academy - The Big A.S.S. Party', NULL, NULL, 'Once upon a moon, the wild wind whispered in my ear that the true queens were returning to Solaria and I made it my mission to open up their path to the throne so that they could slip right in like an oily oyster. Now, on this most special and wondrous of days, the very day of their birth – I will prove myself to be the most loyal and dependable of their followers. Though of course, Venus is in my chart and Lady Petunia has caught sight of the bothersome barracuda once more. Max Rigel is my most sinful of temptations, the shark in the dark who wishes to lure me to his sea cave and I don’t know if I’m Fae enough to resist him for long. But one thing is for sure, I will make certain the Vegas get the big A.S.S. party they deserve for their birthday or I’ll die trying. Succulent squids be damned!', '13.07.2022', NULL, ARRAY['Englisch']::text[], 71, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Double POV','1P']::text[], ARRAY['Geraldine','Max Riegel']::text[], ARRAY['Academy','Magical Creatures','Magical School']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '8', ARRAY['Novella']::text[], 'sheet', :'owner') on conflict do nothing;
