insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('bd6ea0d7-3553-5e5f-aa52-3c22710f9bc1', 'eea5b15b-7183-5091-89b9-7cd64102c1a3', :'owner', 1, '2025-05-22', '2025-05-25', NULL, NULL, 4, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ed7b9e06-da71-5d0f-8d65-be64d77b6c36', 'Zodiac Academy - Fated Throne', NULL, '9781914425233', 'Fate has torn us apart. Without my sister, the world seems darker than ever before and the shadows loom thicker, rising up to answer the call of the Shadow Princess and changing the face of Solaria for good. Now Lionel Acrux has the strength to make a move for the throne, I’m not sure how much time we have left to stop him. Our only hope is to find the Imperial Star before he does. We made the sacrifice the stars called for and we’re paying the price for that decision so it can’t be for nothing. But with the stars turning against us at every move, and the last light in the world seeming to fade, I’m afraid we’re almost out of time. Hope is a dangerous thing. It’s the key to us fighting on. But it could be what destroys us in the end. One thing is for certain, I won’t stop until I have been reunited with my other half and together we will fight to take our crowns. A war is coming. The throne is calling for a new monarch. And someone must answer its call.', '25.02.2022', NULL, ARRAY['Englisch']::text[], 739, 61, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '9', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('23bad575-e902-5da0-9726-59ea42cbb96a', :'owner', 'ed7b9e06-da71-5d0f-8d65-be64d77b6c36', 'gelesen'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 799, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 1565, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 2, 'slow'::burn_kind, 'Der Anfang dieses Buches hat mich schier wahnsinnig gemacht. Ich war mehr als froh, als Tory endlich wieder sie selbst wurde. Wie ekelhaft kann ein Bösewicht nur sein... Das besondere an dieser kleinen Zwischenstory war, dass man endlich auch mal all die Charaktere kennenlernen durfte, die kein fester Teil der eigentlichen Story mehr sind.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c5ce0593-123c-55e6-88ce-3245e777190b', '23bad575-e902-5da0-9726-59ea42cbb96a', :'owner', 1, '2025-05-22', '2025-05-31', NULL, NULL, 10, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('691c5f38-9cde-5cc0-9bcc-2f58d84b19c5', 'Zodiac Academy - The Awakening as Told by the Boys', NULL, NULL, 'The Vega twins are alive.Those five words circle in my mind like an oncoming storm. They change everything about the future we thought had been set in stone. They challenge everything we were raised to be and the stability of the entire kingdom.They’re coming to our academy looking for the life that was stolen from them, but we can’t let them take it back.So much hangs in the balance and we can’t risk the arrival of two naive princesses destroying everything we worked so hard for.I have trained in dark magic, overcome all challenges and stood in the shadow of Lionel Acrux for far too long already. I won’t let them come between me and his downfall.Which means they have to go before they discover how powerful they truly are.This is a retelling of the first book in the Zodiac Academy series from the point of view of Orion and the Heirs and should be read after you have finished the original story. It includes scenes from alternative points of view as well over 50k words of additional content and scenes which have never before been revealed. So prepare to step into the dark minds of the Zodiac boys and watch out for the heartbreak and carnage that will ensue.', '30.08.2021', NULL, ARRAY['Englisch']::text[], 562, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV']::text[], ARRAY['Orion','Darius','Caleb','Seth','Max']::text[], ARRAY['Academy','Magical Creatures','Magical School']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '10', ARRAY['Midquel']::text[], 'sheet', :'owner') on conflict do nothing;
