insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bec5e1d5-17b7-5ee8-a073-d565a019d19a', 'Zodiac Academy - The Awakening', NULL, '9781914425028', 'I’m a Gemini. Impulsive. Curious. Headstrong. A twin. Heir to a throne I know nothing about. And it turns out, I’m Fae. But of course there’s a catch - all I have to do to claim my birth right is prove that I’m the most powerful supernatural in the whole of Solaria. And sure, technically that’s true as I’m the daughter of the Savage King. But the bit they didn’t put in the brochure was that every single Fae in this Kingdom would claim my throne if they could. The school they’ve sent me to is both dangerous as sh*t and one helluva party. Vampires bite weaker students in the corridors, the Werewolf pack has orgies in the Wailing Wood at every full moon and don’t even get me started on the dark and twisted ways the Sirens use their powers on people’s emotions, or how my sinfully tempting Cardinal Magic teacher hosts detentions that leave people needing therapy. Classes are totally interesting if you manage to live through them. And that Gemini star sign I mentioned? It now determines my elemental magic and affects my destiny, so learning astrology is essential if I’m going to beat down my classmates – which is actively encouraged by the way. My biggest problem is the drool worthy Dragon shifter who has his eyes on my throne. He and his three psycho friends are determined to make my time here hell. All I’ve got to do is survive. But fate might have other ideas. Dammit, why couldn’t I have gotten a letter to Hogwarts?', '08.09.2021', 'UK Books; Mondlicht', ARRAY['Englisch','Deutsch']::text[], 436, 26, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('e42afe43-8153-57f3-a736-afffebb09dcf', :'owner', 'bec5e1d5-17b7-5ee8-a073-d565a019d19a', 'gelesen'::reading_status, true, true, ARRAY['Print','Audiobook']::text[], ARRAY['Taschenbuch','Hardcover']::text[], 'Special', ARRAY['Map','Sprayed Edges','In-Book Illustrationen']::text[], 3200, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux']::text[], 730, '👍🏻', false, 'buddy'::company_kind, 'middle'::verdict_kind, 3.0, 'erfuellt'::expectation_kind, 1, 'slow'::burn_kind, 'Ich bin mir noch nicht sicher wie ich mich fühlen soll mit dieser Reihe. Selten ein so trashiges Buch gelesen... Aber wie gehts weiter?') on conflict do nothing;
