insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3408329a-ad8e-5289-b1a0-f3581ddc2f86', 'Caged Wolf', NULL, NULL, 'What do you do when the man you’ve loved since you were fourteen is sent to the most dangerous prison in Solaria for saving your life? Okay, so maybe he doesn’t love me back. And maybe getting sent down would seem insane to some, butI’m Rosalie Oscura, alpha werewolf from the infamous Oscura Clan. My family wrote the book on criminal organisations, and I’ll be ruling this place by the time the next moon rises. Then I just need to work on busting us the hell out of here. ‘Us’ being me, the lion shifter I’ve loved for ten long years, and the most notorious criminal in here - a sinful incubus who’s been condemned to isolation for committing an unspeakable crime. What’s the worst that could happen? I mean, short of being rejected by the black-hearted werewolf who rules over my sworn enemies, or getting myself noticed by the sinister vampire guard who has a dark vendetta against me. But how likely is that? The trouble is, I need the help of those four alpha males to escape this place. And they happen to hate each other almost as much as they hate me. But I always did love a challenge. So how hard could it be to make them accept me as their leader?', '29.03.2020', NULL, ARRAY['Englisch']::text[], 521, 43, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Darkmore Penitentiary, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalie Oscura']::text[], ARRAY['Magical Creatures','Reverse Harem']::text[], ARRAY['Physische Gewalt','Häusliche Gewalt','Depiction of Trauma']::text[], '94271421-cb8d-5e6a-bae8-5d2ac303498a', '1', ARRAY['Spin Off','Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('be08c590-2a94-5b05-81ae-ff43f7061885', :'owner', '3408329a-ad8e-5289-b1a0-f3581ddc2f86', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 699, true, true, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 1007, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 3, 'slow'::burn_kind, 'Ich liebe Rosalie und die Boys. Ich bin so gespannt, wer ihr als erstes so richtig verfallen wird. Ich persönlich denke ja, es wird Eathan sein.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('ecc2ded1-4cad-599d-abb5-9b964db9ed1b', 'be08c590-2a94-5b05-81ae-ff43f7061885', :'owner', 1, '2026-01-22', '2026-01-27', NULL, NULL, 6, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('92d6bff1-3c0f-5d73-a75c-bbbf6b397ccc', 'Dark Fae', NULL, '9781914425158', 'What do a heartless Dragon Shifter, a cold-blooded Basilisk, an arrogant Lion Shifter and a brooding, tattooed Harpy have in common…? Me. Elise Callisto. Vampire. Angel of vengeance. And a girl on a mission to destroy one of them for murdering my brother. I just don’t know which one did it yet. When I interrogated/accidentally killed a Werewolf who was high on a new and dangerous drug called Killblaze, his final words painted a dark reality for me. The King of Aurora Academy killed my brother. The trouble is, there’s four kings at the academy and each of them have motive and bloodthirsty natures. Aurora Academy isn’t a place for the faint of heart. To put it lightly, my town is the cesspit of Solaria where the most cutthroat Fae in the kingdom reside. The school itself is divided by the two gangs who run this city. The Lunar Brotherhood and the Oscura Clan. And guess what? Two of the kings run the gangs at the academy, their hatred for each other so fierce I hear a day doesn’t go by without blood being spilled in the halls. I might be a petite, lilac-haired girl who looks like I couldn’t hurt a fly, but they haven’t been introduced to my fangs yet. And they don’t know why I’m really here. Or that I’ll do whatever it takes to bring down the Fae who took my flesh and blood from me. I don’t believe in fate, but I do know this… the King who killed my brother is a dead man walking. And I’m prepared to sacrifice my heart, body and soul to ensure I get my revenge.', '21.03.2023', NULL, ARRAY['Englisch']::text[], 538, 36, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Aurora Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Elise Callisto']::text[], ARRAY['Academy','Disguised Identity','Enemies to Lovers','Magical School','Revenge Plot','Reverse Harem']::text[], '{}', 'f982c515-c9b9-5f44-acf5-d18a3ba83337', '1', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('cf74c6fa-1fcd-5f4e-a1b8-ea42a1701d45', :'owner', '92d6bff1-3c0f-5d73-a75c-bbbf6b397ccc', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 699, true, true, ARRAY['Audible']::text[], ARRAY['Keira Stevens','Troy Duran']::text[], 853, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'uebertroffen'::expectation_kind, 3, 'fast'::burn_kind, 'Dieses Buch hat richtig Spaß gemacht. Super unterhaltsam. Schlecht und gut zugleich .Der erste Band dieser Reihe hat mir besser gefallen als der erste Band der Zodiac Academy Reihe') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('752e3609-41e7-5003-9644-bf89422c73e6', 'cf74c6fa-1fcd-5f4e-a1b8-ea42a1701d45', :'owner', 1, '2025-01-16', '2025-01-23', NULL, NULL, 8, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7fc29246-1330-5068-8630-08b4f97d753e', 'Alpha Wolf', NULL, NULL, 'I came here with a single goal in mind. An aim. A purpose. I will break out of Darkmore Penitentiary. But I was a fool to think that it would be so simple. And now with more and more Fae relying on me to get them out of this slice of hell, I find myself unable to do a damn thing. Mason Cain stabbed me in the back and left me to rot in the dark. So now I have another goal in mind before I escape this place, because no one messes with the Queen of the Oscura Clan and lives to tell the tale. The moment I get out of here, my sights will be set on him. Between the four alpha males luring me in, the psychopaths trying to kill me and the monster roaming the halls at night, I have my hands full in here. But one thing is for sure. I’m not throwing my life away in this place. So I’ll do whatever it takes to escape.', '16.10.2020', NULL, ARRAY['Englisch']::text[], 470, 41, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Darkmore Penitentiary, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalie Oscura']::text[], ARRAY['Magical Creatures','Reverse Harem']::text[], ARRAY['Sexuelle Gewalt','Physische Gewalt','Depiction of Trauma','Tod','Belästigung']::text[], '94271421-cb8d-5e6a-bae8-5d2ac303498a', '2', ARRAY['Spin Off','Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('bb206eac-0103-598a-af98-d95c138a4e6d', :'owner', '7fc29246-1330-5068-8630-08b4f97d753e', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 599, true, true, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 946, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 4, 'fast'::burn_kind, 'Es ist wirklich so viel passiert in diesem Buch, dass mir zu keinem Zeitpunkt langweilig wurde. Zum Teil mag ich es, wenn man so viele POVs hat, weil man alle Charaktere so gut kennenlernen kann. Aber manchmal kann es auch wirklich anstrengend sein.') on conflict do nothing;
