insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e002eed0-fae6-5f12-8351-a8f87c9b21d9', 'Zodiac Academy - Ruthless Fae', NULL, '9781914425035', 'They tried to break us. They almost did. But we''re not going anywhere. The Celestial Heirs think the stars are on their side. But they don''t know what''s coming. We have to be smart. Fighting them one on one isn''t an option so we need to be cunning. Remaining under the radar won''t be easy, but if we pull it off, they''ll never suspect our involvement when their lives start falling apart. Besides, they''ve already taken us to the brink of hell, what more can they really do?', '28.09.2021', NULL, ARRAY['Englisch']::text[], 475, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('2e0258ae-3f35-5613-bd6e-119109c40fa5', :'owner', 'e002eed0-fae6-5f12-8351-a8f87c9b21d9', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 699, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 950, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 1, 'slow'::burn_kind, 'Die Autorinnen wissen definitiv wie man es spannend hält... Endlich hören die mal auf nur Streit zu haben und dann so ein Ende! Ich hoffe Darius bekommt das wieder hin!') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b24aff6d-ef77-5fb0-b44b-e24efd401244', '2e0258ae-3f35-5613-bd6e-119109c40fa5', :'owner', 1, '2024-03-01', '2024-03-20', NULL, NULL, 20, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d62b1a3a-358d-5d35-89b2-5fa11149cb82', 'Feral Wolf', NULL, NULL, 'A morte e ritorno. My family’s motto circles in my mind as I look this problem dead on and try to figure it out. I’ve faced worse than this. Survived worse odds than this. I won’t let this failure break me. We have 72 hours to turn this around. 72 hours to make a new plan out of the dregs of the old. 72 hours until all hope is lost. This task is impossible, but I still like my chances. I have an ace in my pocket and his name is Mason Cain. He might not want to help me, but I don’t plan on giving him a choice in the matter. My name is Rosalie Oscura. And I refuse to let anything beat me.', '31.07.2021', NULL, ARRAY['Englisch']::text[], 354, 37, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Darkmore Penitentiary, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalie Oscura']::text[], ARRAY['Magical Creatures','Reverse Harem']::text[], ARRAY['Sexuelle Gewalt','Physische Gewalt','Depiction of Trauma','Tod','Belästigung']::text[], '94271421-cb8d-5e6a-bae8-5d2ac303498a', '3', ARRAY['Spin Off','Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
