insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ee099cb3-aed6-5713-86cd-11f71a2d0edf', 'Zodiac Academy - The Reckoning', NULL, '9781914425059', 'Hell Week has begun. Senior students have been tasked with making the freshmen''s lives pure torture as we prepare to face The Reckoning - the assessment that will decide whether we stay at Zodiac Academy or lose our places here forever. With the Lunar Eclipse on the horizon, my sister and I have more to worry about than just passing our exams. A dark plot is unfolding and the shadows are drawing closer. It looks like our enemies could be more powerful than we ever realised. Damn, who would have thought being a princess would be this hard?', '08.10.2021', NULL, ARRAY['Englisch']::text[], 562, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '3', '{}', 'sheet', :'owner') on conflict do nothing;
