insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cf2168cb-390a-5840-816e-196683393899', 'Broken Fae', NULL, '9781914425189', 'The stars have torn us apart. Just as we were finding a way to get past our difficulties, my kings and I have been shattered by a twist of fate. And while we''re left reeling from the wheel of destiny, our enemies are only growing more powerful. Felix Oscura is haunting Alestria with his bloodthirsty need to steal the power of the clan he was never destined to rule over, and the illusive King is growing closer to taking control of the entire city. With challenges around every corner, and the mysteries behind my brother''s death slowly starting to unravel, I don''t know if I''ll be able to overcome the will of the stars before it’s too late...', '15.03.2023', NULL, ARRAY['Englisch']::text[], 700, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Aurora Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Elise Callisto']::text[], ARRAY['Academy','Disguised Identity','Enemies to Lovers','Magical School','Revenge Plot','Reverse Harem']::text[], '{}', 'f982c515-c9b9-5f44-acf5-d18a3ba83337', '4', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('5c678511-22b4-5557-a922-41a0a5eca487', :'owner', 'cf2168cb-390a-5840-816e-196683393899', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 799, true, true, ARRAY['Audible']::text[], ARRAY['Keira Stevens','Troy Duran']::text[], 1258, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Der Anfang hat mich so wahnsinnig gemacht. Like... get your shit together :D Dieser Band hat mir ein bisschen zu viel Fokus auf Sex gelegt und zu wenig darauf die Handlung voran zutreiben... Trotzdem noch ein tolles Buch.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('7c7eb403-fdd3-51b9-b26b-41063140c33c', '5c678511-22b4-5557-a922-41a0a5eca487', :'owner', 1, '2025-03-24', '2025-03-28', NULL, NULL, 5, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3a4ae25e-68f3-5ddd-8706-398f43e67928', 'Warrior Fae', NULL, '9781914425196', 'I''ve been thrown into the den of a monster. I once thought one of my ruthless boys could be the killer I’m hunting. They’re all dark, deadly and more than capable of brutality. But now I’m held by the King I’ve been stalking in the shadows and when I unmask him, he’ll realise he made a huge mistake in taking my brother from this world. My Kings are coming for me, I know that in my soul. They’re on their way to rip me from my enemy’s arms and tear him apart for me. My heart beats to the sound of their names. But I won’t wait around to be rescued. Everything has led me to this moment and I’m ready to destroy the Fae who stole my brother from me. Secrets will be uncovered. Destiny will be decided. Death will deliver us all in the end. No one will escape the conclusion of this story without blood on their hands. I guess it’s a good thing I’m a Vampire then, because I just so happen to have a taste for blood.', '25.02.2022', NULL, ARRAY['Englisch']::text[], 955, 64, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Aurora Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Elise Callisto']::text[], ARRAY['Academy','Disguised Identity','Enemies to Lovers','Magical School','Revenge Plot','Reverse Harem']::text[], '{}', 'f982c515-c9b9-5f44-acf5-d18a3ba83337', '5', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('eafb5764-ef7c-517f-a815-af3ad51426e6', :'owner', '3a4ae25e-68f3-5ddd-8706-398f43e67928', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 899, true, true, ARRAY['Audible']::text[], ARRAY['Angelina Rocca','Troy Duran']::text[], 1777, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'uebertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Ich bin jetzt schon traurig, dass diese Reihe zu Ende ist! Ich werde die Charaktere alle vermissen und hoffe, dass sie in ZA noch viel mehr vorkommen werden. Das einzige was an dieser Reihe ein wenig genervt hat war, wie lange es gedauert hat zum eigentlichen Ziel zu kommen. Aber irgendwie hat es auch nicht gestört so viel Nebenstory zu haben.') on conflict do nothing;
