insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3cadaca5-8928-5a2c-bb8c-14bcb6e01bde', 'c350c030-0214-54bc-b7d7-e9e4df545063', :'owner', 1, '2025-04-12', '2025-04-28', NULL, NULL, 17, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6b648205-b1a8-5932-b8d4-9023650b7ba2', 'Zodiac Academy - Cursed Fates', NULL, '9781916926073', 'The stars have cursed us all. After the devastating events at Zodiac Academy, we have to deal with this hollow reality we''re faced with. Lionel seeks to destroy us, the Nymphs seek to destroy the entire Fae race, and between all of it, we have to try and survive each day and prove our worth in this forsaken place. I''m afraid of everything falling apart, but it looks like it already has. Death lurks around every corner, and it wants to claim me and my sister. But together, we will overcome the darkness that seeks to defeat us. Because we were forged in fire. And these flames will never die.', '02.11.2021', NULL, ARRAY['Englisch']::text[], 886, 60, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '7', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('eb0a316c-fa8c-5d54-89af-11d8e312150c', :'owner', '6b648205-b1a8-5932-b8d4-9023650b7ba2', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 799, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 1577, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 2, 'slow'::burn_kind, 'Dieses Buch hat mich an so vielen Stellen so wütend gemacht. Ich hasse es einfach, wenn Charaktere maßlos dumme Sachen machen, um andere zu Beschützen. Und dieses Buch war voll davon.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('69731e79-0507-5023-b98b-debb707549a3', 'eb0a316c-fa8c-5d54-89af-11d8e312150c', :'owner', 1, NULL, '2025-05-08', '28.04.25', NULL, 11, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('63bd1cfb-3c6d-5b6f-bb64-80ef71f65f50', 'Zodiac Academy - Heartless Sky', NULL, '9781914425523', 'The winds of fate are shifting. And it finally seems like they’ve been twisted in our favour. On the run and cast out from society, we’ve been forced to hide from the mad man who stole our throne. But as more secrets come to light and my sister and I work harder than ever before to reach our potential and claim our birth right, the end is finally drawing closer. There is no turning from this path now. The curse chases on our heels as time rushes by and the blood drenched destiny of the man I love looms ever closer just like the monster who stole our throne. We must prepare for the final battle, but three things are clear now. The cards have already been dealt. Blood will spill for a new future to rise. And the stars themselves can’t help us. The fight for the throne is upon us. All hail the heartless sky.', '15.12.2021', NULL, ARRAY['Englisch']::text[], 991, 71, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '11', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('040b7abd-6695-52b4-a92d-344f140f56e5', :'owner', '63bd1cfb-3c6d-5b6f-bb64-80ef71f65f50', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 899, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 1810, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 3, 'fast'::burn_kind, 'Eine Sache, die mich leider sehr genervt hat an diesem Buch, sind die dummen Entscheidungen die getroffen wurden und die ständigen übertriebenen Liebesbekundungen. Irgendwann reicht es. Ich liebe diese Reihe und sie ist auch einfach so unendlich spannend, aber bei manchen Szenen habe ich mir gewünscht, dass es endlich schneller voran geht. Es nervt halt auch einfach, wenn die Guten keinerlei Erfolge haben.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('94d5d058-79f9-5cb9-aea1-486ad79190cc', '040b7abd-6695-52b4-a92d-344f140f56e5', :'owner', 1, '2025-05-31', '2025-06-11', NULL, NULL, 12, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('52bb05af-2aed-5762-9686-b6136f36c26b', 'Zodiac Academy - Sorrow and Starlight', NULL, '9781914425615', 'All stars must fall. Bloody, lost, broken. We live to fight another day. But with so much stolen from us, can the fates ever twist in our favour again? My sister and I have been torn apart by shadows and despair, and now we each stand alone. Our sorrow is spun like a web, trapping us tight, and I fear our enemies will soon come to feast upon our souls. But if I have my way, the merciless sky will have dealt us its final fortune. It’s time for us to take back the power that’s been ripped from our grasp and turn the tide of this war. All stars must fall, and all Phoenixes must rise. Long live the Savage Queens.', '17.10.2023', NULL, ARRAY['Englisch']::text[], 1122, 83, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Enemies to Lovers','Heir of Throne','Hidden Powers','Magical Creatures','Magical School','Social/political Turmoil','Age Gap','Star-crossed Lovers']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '12', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7591950f-f8da-5991-93b4-6a2ba02c3c97', :'owner', '52bb05af-2aed-5762-9686-b6136f36c26b', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 899, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 2201, '👍🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 2.5, 'untertroffen'::expectation_kind, 3, 'slow'::burn_kind, 'Das Buch hat mich einfach so dermaßen genervt. Ich weiß nicht, wann ich das letzte mal so oft meine Augen verdreht habe während eines Buches. So langsam reicht es leider. Ich kann einfach die ganzen dramatischen Monologe die zu nichts führen nicht mehr hören. Die Geschichte wird einfach unnötig in die Länge gezogen. Am meisten nervt, dass ich jetzt im Band 8 bin und die MCs immer noch NICHTS erreicht haben!') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c6d9e568-f5dc-5c3b-a682-9bf327fe598d', '7591950f-f8da-5991-93b4-6a2ba02c3c97', :'owner', 1, '2025-07-30', '2025-08-09', NULL, NULL, 11, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e9266a09-275c-5cb8-8ada-8c08da11d811', 'Zodiac Academy - Beyond the Veil', NULL, '9781914425875', 'We were torn from life before our time, a Savage King, his queen, a betrayed son, a wronged brother, a scorned wife and so many more. We watch those we left behind as they struggle against the grip of the stars, the answers to so many of their questions within our grasp and yet out of their reach. But what if we could find a way to answer their pleas? What if we could find a way to help them from this side of the divide? And what price would such a thing come at?', '28.06.2023', NULL, ARRAY['Englisch']::text[], 416, 29, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Beyond the Veil', ARRAY['Multiple POV','1P']::text[], ARRAY['Darius Acrux','Hail Vega']::text[], ARRAY['Ancient Secrets','Different Worlds','Found Family']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '13', ARRAY['Interquel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('9e10e340-6cfb-5215-983d-590ad6c6ad01', :'owner', 'e9266a09-275c-5cb8-8ada-8c08da11d811', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 799, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 955, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Das besondere an dieser kleinen Zwischenstory war, dass man endlich auch mal all die Charaktere kennenlernen durfte, die kein fester Teil der eigentlichen Story mehr sind.') on conflict do nothing;
