insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cce9aa10-7d89-5e24-8489-e84281ed916f', 'Zodiac Academy - Live and Let Lionel', NULL, NULL, 'Savage - a short story about Hail and Merissa Vega''s love story. The Shimmering Springs - that night Caleb and Seth did or didn''t kiss... The moment Geraldine first saw the twins. Seth on the Moon - one Werewolf''s wanderings on the moon. Night - that time the twins met the Ruthless Boys - with a never before published chapter! Orion ‘blue’ alternate POV. Orion ‘Fairy Fair’ alternate POV. Darius ''throne room'' alternate POV. Darius ‘Stars’ alternate POV.', '16.02.2024', NULL, ARRAY['Englisch']::text[], 330, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], '{}', ARRAY['Academy','Magical Creatures','Magical School']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '14', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a42e0176-5b1a-5df6-a2ce-6d8136af7819', :'owner', 'cce9aa10-7d89-5e24-8489-e84281ed916f', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 499, true, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 621, '👍🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 3.0, 'erfuellt'::expectation_kind, 3, 'no'::burn_kind, 'Ich stelle mal wieder fest, dass ich nicht verstehe, warum alle Orion so mögen. Ich finde den Typ einfach nur massiv nervtötend. Also die Kapitel, mit Szenen, die man vorher nicht kannte, fand ich sehr süße Ergänzungen. Die Kapitel, die einfach nur die selben Szenen in einer anderen POV waren haben mir leider einfach nur genervt.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('a522a1c4-bb11-5ed2-a200-4d8ef26617c1', 'a42e0176-5b1a-5df6-a2ce-6d8136af7819', :'owner', 1, '2026-01-02', '2026-01-04', NULL, NULL, 3, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3ec1c24b-43ef-51fa-818b-71d585282244', 'Zodiac Academy - Restless Stars', NULL, NULL, 'We are all and nothing now, our fate weighed on the scales of the stars and counterbalanced by the forces that oppose us. The shadow of the false king spreads as thick as oil across the kingdom we were born to rule, and none remain untouched by its darkness. Our crowns lay within reach if only we can claim them. All souls are at risk now and when the final battle dawns, a new regime will rise. The time for the true reckoning is upon us and we have proven ourselves as savage as our father, as brutal as our mother, and as wild as the Elements which roar through our veins. We can only hope it is enough. When the last sword strikes the final death in this game of fate and fortune, only one side will be victorious. The Starfall Legion charges at first light. And our destiny rides upon our shoulders as we rush into the end. All hail the True Queens. May our rule last longer than this night.', '23.04.2024', NULL, ARRAY['Englisch']::text[], 1153, 119, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Zodiac Academy, Solaria', ARRAY['Multiple POV','1P']::text[], ARRAY['Tory & Darcy Vega','Celestial Heirs']::text[], ARRAY['Academy','Magical Creatures','Magical School']::text[], '{}', 'fcb72747-3c04-58f4-afd7-7c610af5fa88', '15', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('71a42e50-f3cd-536c-9a73-9a3959fa9265', :'owner', '3ec1c24b-43ef-51fa-818b-71d585282244', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, false, false, ARRAY['Audible']::text[], ARRAY['Bridget Bordeaux','Jake Bordeaux']::text[], 2163, '👍🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 3.5, 'erfuellt'::expectation_kind, 4, 'fast'::burn_kind, 'Also dafür dass es das Ende dieser "epischen" Reise war, hat es mich leider etwas kalt gelassen. Leider haben sich die letzten Bände einfach zu sehr gezogen. Das Buch war definitiv besser, als der letzte Band aber trotzdem habe ich mir mehr erhofft. Irgendwie mochte ich es, so viele POVs zu bekommen, aber es hat mich gleichzeitig auch genervt. Ich fand es aber auch sehr schön, einen Einblick in das Leben der MCs zu bekommen, nach dem Krieg.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('49419362-3609-526f-b080-a92068da8574', '71a42e50-f3cd-536c-9a73-9a3959fa9265', :'owner', 1, '2026-01-04', '2026-01-17', NULL, NULL, 14, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f530643b-e16d-5d6f-9bd1-ac670bdb9813', 'Liebewesen', NULL, '9783847901815', 'Lios Körper ist ihr Albtraum, daran ändert auch ihr Freund Max nichts. Als sie ungeplant schwanger wird, starrt sie nicht nur fassungslos auf den positiven Test, weil jemand wie sie doch gar nicht schwanger werden kann, sondern auch auf das Ende einer mühsam erarbeiteten Normalität. Sie ist unfähig, Max von der Schwangerschaft zu erzählen, und genauso unfähig, diese zu beenden. Während das Kind in Lios Bauch wächst, prasseln Erinnerungen auf sie ein: an ihre kalte Mutter, ihren hilflosen Vater und an all das andere, das sie für immer vergessen wollte. Zum ersten Mal stellt sie sich ihrer Vergangenheit - und riskiert damit, dass alles zusammenbricht.', '30.08.2024', 'eichborn', ARRAY['Deutsch']::text[], 219, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Coming of Age']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Lios']::text[], ARRAY['Coming-of-Age','Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
