insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('81cc8039-02c5-5efd-aac0-d8c5e00524db', 'Red, White & Royal Blue', NULL, '9781529099461', 'What happens when America''s First Son falls in love with the Prince of Wales? Alex Claremont-Diaz is handsome, charismatic, a genius – pure millennial-marketing gold for the White House ever since his mother first became President of the United States. There’s only one problem. When the tabloids get hold of a photo involving an altercation between Alex and Prince Henry, U.S./British relations take a turn for the worse. Heads of family and state devise a plan for damage control: stage a truce. But what begins as a fake, Instagrammable friendship grows deeper, and more dangerous, than either Alex or Henry could have imagined. Soon they are hurtling into a secret romance that could derail the presidential campaign and upend two nations . . .', '14.05.2019', 'St. Martins Geiffin', ARRAY['Englisch']::text[], 440, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'London, Washington', '{}', ARRAY['Alex Claremont-Diaz','Henry']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
