insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('abe76a1e-3719-5370-b4ad-d63b6ba63acd', 'The Penultimate Hours', NULL, NULL, 'Welcome to the Penultimate Hours! A collection of short stories covering the various characters in The Last Hours, originally released monthly in the leadup to Chain of Gold. The Penultimate Hours also contains two special extras: a letter from Lucie to Cordelia (originally part of the LitJoy Chain of Gold book box) and a letter from Ragnor to Magnus, originally included with the Waterstone''s special edition of Chain of Gold.', NULL, NULL, ARRAY['Englisch']::text[], 56, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', '{}', '{}', '{}', NULL, NULL, ARRAY['Sequel','Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
