insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0c909cff-969b-5cf4-9b25-ab3ed5b500b0', 'Der Schattenjäger Codex', 'The Shadowhunter Codex', '9783401069814', 'Werde Teil der sagenhaften Welt der Schattenjäger! Dies ist die ganz persönliche Ausgabe von Clarys Schattenjäger-Codex. Hier lernt sie den Umgang mit der Stele und erwirbt sich ihre Kenntnis über die Dämonen. Und weil Clary gerne zeichnet, finden sich darin ihre Skizzen von Freunden und Familie sowie handschriftliche Notizen am Rand. Irgendwie konnte sie Jace und Simon nicht davon abhalten, ebenfalls ihre Kommentare zu hinterlassen. Also ist dieses Handbuch ein einzigartiges Werk - teils Nachschlagewerk, teils Geschichtsbuch, teils Trainingsanleitung, ergänzt mit Kommentaren von Schattenjägern, die schon viel erlebt haben. Dieser aufwändig gestaltete Codex ist der ultimative Ratgeber für angehende Schattenjäger wie Clary und Tessa und eine perfekte Ergänzung zu den Bestsellerserien Chroniken der Unterwelt und Chroniken der Schattenjäger.', '04.03.2014', 'Arena', ARRAY['Deutsch']::text[], 306, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
