insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6b85a049-6267-5f6f-8ed4-697692e64dcc', 'Die Legenden der Schattenjäger-Akademie', 'Tales from the Shadowhunter Academy', '9783401601472', 'Ohne Erinnerungen muss Simon erneut herausfinden, wer er eigentlich ist. Hat er das Zeug zum Dämonen bekämpfenden Helden - wie ihm seine früheren Freunde Clary und Jace erzählen? Oder ist er doch der bleiche Comicfan, der nicht einmal die Kraft hat, eine Waffe der Nephilim richtig in der Hand zu führen? Und dann gibt es noch Isabelle, an deren Liebe er sich nicht erinnern kann, obwohl es in seinem Bauch kribbelt, immer wenn er an sie denkt. War er wirklich mit diesem tollen Mädchen zusammen, und wenn ja, wie hat er das nur angestellt?', '08.11.2016', 'Arena', ARRAY['Deutsch']::text[], 840, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Schattenjäger-Akademie', '{}', ARRAY['Simon']::text[], '{}', '{}', NULL, NULL, ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
