insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('449e94f1-9822-5dfd-8676-ee7b38bd2153', '0512d631-2d63-5060-bf94-b7a7724b6cc8', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8bb0beb-3743-5fb3-a668-00c01d122bbc', 'Ghosts of the Shadow Market', NULL, '9781406385366', 'The Shadow Market is a meeting point for faeries, werewolves, warlocks and vampires. There the Downworlders buy and sell magical objects, make dark bargains, and whisper secrets they do not want the Nephilim to know. Through two centuries, however, there has been a frequent visitor to the Shadow Market from the City of Bones, the very heart of the Shadowhunters. As a Silent Brother, Brother Zachariah is sworn keeper of the laws and lore of the Nephilim. But once he was a Shadowhunter called Jem Carstairs, and his love, then and always, is the warlock Tessa Gray. Follow Brother Zachariah and see, against the backdrop of the Shadow Market’s dark dealing and festival, Anna Lightwood’s doomed romance, Matthew Fairchild’s great sin and Tessa Gray plunged into a world war. Valentine Morgenstern buys a soul at the Market and a young Jace Wayland’s soul finds safe harbor. In the Market is hidden a lost heir and a beloved ghost, and no-one can save you once you have traded away your heart. Not even Brother Zachariah.', '06.06.2019', 'Walker Books', ARRAY['Englisch']::text[], 607, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Unbestimmt'::time_period, 'Shadow Market', '{}', ARRAY['Brother Zachariah']::text[], '{}', '{}', NULL, NULL, ARRAY['Sequel','Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
