insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e8cffbf3-27ad-57c7-9983-28ca7b3e4e3f', 'Clockwork Angel', 'The Infernal Devices - Clockwork Angel', '9783401064741', 'Nach langer Reise quer über den Atlantik trifft die sechzehnjährige Tessa Gray im Viktorianischen London ein. Dort hofft sie, ihren verschollenen Bruder wiederzufinden. Doch statt einer Familienzusammenkunft warten Gefahr und Dunkelheit auf sie in den engen Gassen der Stadt. Vampire, Hexenmeister und Schlimmeres treiben hier ihr Unwesen, und nur die Schattenjäger wagen es, sich den Dämonen der Unterwelt in den Weg zu stellen. Sie retten Tessa das Leben. Als die junge Frau dann herausfindet, dass sie selbst ein Wesen zwischen Schatten und Licht ist und über große Kräfte verfügt, muss sie sich entscheiden: zwischen Gut und Böse, zwischen Loyalität und Liebe ...', '01.02.2011', 'Arena', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Will','Tessa','Jem']::text[], '{}', '{}', 'de37a2f7-1a82-5207-abdf-be5c9fa54c4b', '1', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
