insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('740cba05-6cdd-548b-a74c-468ac87319fa', 'City of Bones', 'The Mortal Instruments - City of Bones', '9783401061320', 'Die fünfzehnjährige Clary lebt mit ihrer Mutter Jocelyn in New York. Als diese unter höchst merkwürdigen Umständen entführt wird, offenbart sich Clary ein wohlgehütetes Familiengeheimnis: Ihre Mutter war einst eine Schattenjägerin, Mitglied einer Bruderschaft, die seit über tausend Jahren Dämonen jagt. Als Clary selbst von düsteren Gestalten angegriffen wird, rettet der ebenso attraktive wie geheimnisvolle Jace ihr das Leben. Er nimmt sie mit ins New Yorker Institut der Gruppe, und nach und nach wird Clary immer tiefer in diese faszinierende Welt hineingezogen. Doch ein tödlicher Machtkampf zwischen Gut und Böse droht die Gemeinschaft der Dämonenjäger zu zerreißen. Werden Clary und Jace es schaffen, Jocelyn zu retten und die Welt der Schattenjäger vor dem Untergang zu bewahren?', '01.01.2009', 'Arena', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '1', '{}', 'sheet', :'owner') on conflict do nothing;
