insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('972099ff-3ae3-566c-9b6a-cd6d32d3933f', 'Lady Midnight', 'The Dark Artifices - Lady Midnight', '9783442314225', 'Als ihre Eltern starben, war Emma Carstairs noch ein Kind, und um sie herum tobte der Dunkle Krieg. Die Wesen der Unterwelt kämpften bis aufs Blut gegeneinander, und die Schattenjäger, Erzfeinde der Dämonen, wurden fast völlig ausgelöscht. Aber Emma glaubt bis heute, dass ihre Eltern aus einem anderen rätselhaften Grund sterben mussten. Inzwischen sind fünf Jahre vergangen, und zusammen mit ihrem engen Freund und Seelenverwandten Julian Blackthorn hat die 17-jährige Emma Zuflucht im Institut der Schattenjäger in Los Angeles gefunden. Dort sorgt eine mysteriöse Mordserie für große Unruhe. Immer wieder werden Leichen gefunden, übersät mit alten Schriftzeichen – Zeichen, wie sie auch bei Emmas Eltern entdeckt worden waren. Emma muss dieser Spur nachgehen, selbst wenn sie Julian dadurch in große Gefahr bringt …', '17.05.2016', 'Goldmann', ARRAY['Deutsch']::text[], 848, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Emma Carstairs']::text[], '{}', '{}', '9de2cfff-73de-56e3-974d-87e094d4b4e9', '1', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
