insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('baf6a556-5794-529c-9ed2-b083dfc0b12e', '883d7311-2447-5cfb-8bdc-9068cdbd6e61', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d20aaab2-ac7a-517a-9c6d-59e7049a0835', 'Chain of Gold', NULL, '9783442314546', 'Cordelia Carstairs is a Shadowhunter, a warrior trained since childhood to battle demons. When her father is accused of a terrible crime, she and her brother travel to Edwardian London in hopes of preventing the family''s ruin. Cordelia''s mother wants to marry her off, but Cordelia is determined to be a hero rather than a bride. Soon Cordelia encounters childhood friends James and Lucie Herondale and is drawn into their world of glittering ballrooms, secret assignations, and supernatural salons, where vampires and warlocks mingle with mermaids and magicians. All the while, she must hide her secret love for James, who is sworn to marry someone else. But Cordelia''s new life is blown apart when a shocking series of demon attacks devastate London. These monsters are nothing like those Shadowhunters have fought before - these demons walk in daylight, strike down the unwary with incurable poison, and seem impossible to kill. London is immediately quarantined. Trapped in the city, Cordelia and her friends discover that their own connection to an dark legacy has gifted them with incredible powers - and force a brutal choice that will reveal the true cruel price of being a hero.', '24.08.2020', 'Goldmann', ARRAY['Englisch']::text[], 624, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Cordelia Carstairs','James Herondale']::text[], '{}', '{}', 'a4e355cd-be18-575a-8c08-972f0d232c3f', '1', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
