insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2fa524c2-0ef6-5578-889d-39c49e4f6295', 'Clockwork Prince', 'The Infernal Devices - Clockwork Prince', '9783401064758', 'Tessa Gray glaubte, bei den Schattenjägern im Viktorianischen London endlich ein neues und sicheres Zuhause gefunden zu haben. Doch da stellen mysteriöse Hinweise auf ihre Herkunft plötzlich alles in Frage. Zumal sich andeutet, dass der ebenso düstere wie geheimnisvolle Magister einen Rachefeldzug gegen sie führt, der die gesamte Unterwelt zerstören könnte. Zerrissen zwischen ihren Gefühlen für den smarten Jem und den gutaussehenden Will begibt sich Tessa auf die gefährliche Suche nach der Wahrheit über sich selbst – und muss schmerzlich lernen, dass Liebe und Lügen ein hochexplosives Gemisch sind ...', '01.07.2012', 'Arena', ARRAY['Deutsch']::text[], 584, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Will','Tessa','Jem']::text[], '{}', '{}', 'de37a2f7-1a82-5207-abdf-be5c9fa54c4b', '2', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
