insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('913c0714-ddea-53f9-99ad-2c51e7c9f85b', 'City of Ashes', 'The Mortal Instruments - City of Ashes', '9783401061337', 'Clary glaubte, sie wäre ein ganz normale junge Frau – bis sie unter dramatischen Umständen erfuhr, dass sie eine Schättenjägerin ist, Teil einer Bruderschaft, die seit über tausend Jahren Dämonen jagt. Vampire, Werwölfe, Hexenmeister: Clary würde ihrem neuen Leben allzu gern den Rücken kehren. Doch die Unterwelt ist nicht bereit, sie gehen zu lassen. Dafür sorgt auch das starke Band zu ihren neuen Freunden, ihrer neugefundenen Familie. Und als Jace, der ihr mehr als einmal das Leben gerettet hat, in tödliche Gefahr gerät, stellt sich Clary schließlich ihrem Schicksal – und einem erbitterten Kampf gegen die Kreaturen der Nacht ...', '01.06.2008', 'Arena', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '2', '{}', 'sheet', :'owner') on conflict do nothing;
