insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('06db4295-95e2-5eae-8be4-e81f24d05522', 'Lord of Shadows', 'The Dark Artifices - Lord of Shadows', '9783442314256', 'Die Schattenjägerin Emma Carstairs hat ihre Eltern gerächt, doch sie findet keinen Frieden. Denn sie hat sich in ihren Parabatai Julian verliebt – eine Beziehung, die nach den Gesetzen der Schattenjäger fatale Konsequenzen hat. Um sie beide zu schützen, lässt Emma sich daher ausgerechnet auf Julians Bruder Mark ein. Mark, der lange bei den Feenwesen lebte und dessen Loyalität nicht wirklich geklärt ist. Schlimmer noch: Die Feenwesen, hart getroffen von den Vereinbarungen nach dem Dunklen Krieg, begehren auf, Unruhe herrscht in der Unterwelt. Emma, Julian und Mark müssen für all das kämpfen, was sie lieben – bevor ein neuer Krieg ausbricht ...', '09.10.2017', 'Goldmann', ARRAY['Deutsch']::text[], 832, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Emma Carstairs']::text[], '{}', '{}', '9de2cfff-73de-56e3-974d-87e094d4b4e9', '2', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
