insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('76e76c13-d748-5bb0-bc1b-95991955d2c9', 'City of Glass', 'The Mortal Instruments - City of Glass', '9783401061344', 'Um das Leben ihrer Mutter zu retten, begibt sich die junge Schattenjägerin Clary auf eine gefährliche Mission. Heimlich macht sie sich auf in die Hauptstadt Idris. Damit bricht sie ein uraltes Gesetz - doch das ist bald nicht mehr ihr größtes Problem: Ein Dämonenheer droht Idris zu überrennen, und es gibt nur eine einzige Möglichkeit, um zu überleben: Die Schattenjäger müssen ihren tief verwurzelten Hass überwinden und Seite an Seite mit den Wesen der Unterwelt in den Kampf ziehen. Während die Lage sich zuspitzt, versuchen Clary und Jace zudem ihre komplizierte Beziehung zu klären - und müssen erfahren, wie hoch der Preis für Liebe und Verrat sein kann ...', '01.08.2009', 'Arena', ARRAY['Deutsch']::text[], 728, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '3', '{}', 'sheet', :'owner') on conflict do nothing;
