insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c80522ab-eb14-5116-8155-993782aaa1db', 'Queen of Air and Darkness', 'The Dark Artifices - Queen of Air and Darkness', '9783442314263', 'Die Gemeinschaft der Schattenjäger steht kurz vor einem Bürgerkrieg. Unversöhnlicher Hass erfüllt die einzelnen Gruppen, und auf den Stufen des Ratssaales ist unschuldiges Blut vergossen worden. Auch die Blackthorns haben einen schrecklichen Verlust erlitten, und in tiefer Trauer flieht die Familie nach Los Angeles. Nur Julian und Emma machen sich auf den Weg ins Feenreich. Trotz der Gefahren, die der Fluch ihrer verbotenen Liebe mit sich bringt, wollen sie dort das Schwarze Buch der Toten wiederbeschaffen. Stattdessen entdecken sie ein Geheimnis, so dunkel und gefährlich, dass es die gesamte Unterwelt zu vernichten droht ...', '24.06.2019', 'Goldmann', ARRAY['Deutsch']::text[], 800, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Emma Carstairs']::text[], '{}', '{}', '9de2cfff-73de-56e3-974d-87e094d4b4e9', '3', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
