insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('025fddb9-bfd0-56c9-a5f6-a601f132949e', '1ec0c6e2-c60d-55e9-8ca2-e149baa1f1e3', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('01e6be56-9c8e-50c3-873e-63773b35f108', 'Chain of Thorns', NULL, '9781406358117', 'Cordelia Carstairs has lost everything that matters to her. In only a few short weeks, she has seen her father murdered, her plans to become parabatai with her best friend, Lucie, destroyed, and her marriage to James Herondale crumble before her eyes. Even worse, she is now bound to an ancient demon, Lilith, stripping her of her power as a Shadowhunter. After fleeing to Paris with Matthew Fairchild, Cordelia hopes to forget her sorrows in the city''s glittering nightlife. But reality intrudes when shocking news comes from home: Tatiana Blackthorn has escaped the Adamant Citadel, and London is under new threat by the Prince of Hell, Belial. Cordelia returns to a London riven by chaos and dissent. The long-kept secret that Belial is James and Lucie''s grandfather has been revealed by an unexpected enemy, and the Herondales find themselves under suspicion of dealings with demons. Cordelia longs to protect James, but is torn between a love for James she has long believed hopeless, and the possibility of a new life with Matthew. Nor can her friends help - ripped apart by their own secrets, they seem destined to face what is coming alone. For time is short, and Belial''s plan is about to crash into the Shadowhunters of London like a deadly wave, one that will separate Cordelia, Lucie, and the Merry Thieves from help of any kind. Left alone in a shadowy London, they must face Belial''s deadly army. If Cordelia and her friends are going to save their city - and their families - they will have to muster their courage, swallow their pride, and trust one another again. For if they fail, they may lose everything - even their souls.', '31.01.2023', 'Walker Books', ARRAY['Englisch']::text[], 688, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Cordelia Carstairs','James Herondale']::text[], '{}', '{}', 'a4e355cd-be18-575a-8c08-972f0d232c3f', '3', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('41a9632e-c700-57db-90d3-9280e1f07110', :'owner', '01e6be56-9c8e-50c3-873e-63773b35f108', 'gelesen'::reading_status, true, true, ARRAY['Print','Audiobook']::text[], ARRAY['Hardcover']::text[], NULL, '{}', 1999, true, true, ARRAY['Audible']::text[], ARRAY['Finty Williams']::text[], 1745, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, NULL, 'untertroffen'::expectation_kind, 0, NULL, 'Leider mag ich iher Bücher immer weniger, je älter ich werde. Es sind immer noch tolle Charaktere und tolle Geschichten. Aber was mich ärgert ist, dass so CC Main-Trope einfach immer Misscommunication ist. Wenn die Charaktere einfach mal miteinander sprechen würden, könnten 90% aller Probleme gelöst werden.') on conflict do nothing;
