insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e6a0e10-291e-51b0-a6c5-42dddb078ed1', 'City of Fallen Angels', 'The Mortal Instruments - City of Fallen Angels', '9783401065595', 'New York City, die Stadt, die niemals schläft. Hier finden auch die Wesen der Unterwelt ein Zuhause: Feen, Werwölfe und Vampire, Hexenwesen und Dämonen. Lange Zeit bekämpften sie alle sich bis aufs Blut – jetzt ist Frieden einkehrt. Endlich kann die 16-jährige Clary ihr Leben in vollen Zügen genießen: ihre Ausbildung zur Schattenjägerin ebenso wie das bevorstehende Hochzeitsfest ihrer Mutter. Und natürlich die Liebe zu ihrem Mitstreiter Jace, zu der sie sich nun bekennen kann. Doch abseits des Idylls braut sich ein dunkler Sturm zusammen. Ist der Krieg, den Clary und ihre Freunde gewonnen glaubten, doch noch nicht vorbei?', '01.11.2011', 'Arena', ARRAY['Deutsch']::text[], 567, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '4', '{}', 'sheet', :'owner') on conflict do nothing;
