insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('369c31a4-4ae8-50c2-bb10-b964e3b5af46', 'City of Lost Souls', 'The Mortal Instruments - City of Lost Souls', '9783401066677', 'In einem atemberaubenden Kampf über den Dächern von New York haben die junge Schattenjägerin Clary und ihre Freunde die Dämonin Lilith besiegt. Doch die Freude ist von kurzer Dauer: Von Jace, den Clary über alles liebt, fehlt jede Spur, und auch ihr finsterer Bruder Sebastian ist verschwunden. Wenig später muss Clary erfahren, dass Jace durch Liliths Zauber auf immer mit Sebastian und den Dunklen Mächten verbunden sein wird. Nur wenn seine Schattenjägerfreunde sich selbst der Schwarzen Magie verschreiben, haben sie eine Chance, dieses grausame Band zu zertrennen. Clary ist zu allem entschlossen – doch kann sie Jace überhaupt noch vertrauen?', '20.02.2013', 'Arena', ARRAY['Deutsch']::text[], 688, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '5', '{}', 'sheet', :'owner') on conflict do nothing;
