insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7291620-992d-5f2c-8a0f-2d9a72b6b9c1', 'City of Heavenly Fire', 'The Mortal Instruments - City of Heavenly Fire', '9783401066745', 'Dunkelheit ist hereingebrochen über die Welt der Schattenjäger, Chaos und Zerstörung drohen die Nephilim endgültig zu überwältigen. Clary, Jace und ihre Freunde stehen ihrem bisher gefährlichsten Feind gegenüber: Clarys eigenem Bruder Sebastian Morgenstern. Systematisch sät dieser Zwietracht zwischen den Nephilim und erschafft mithilfe Dunkler Magie eine Armee albtraumhafter Kreaturen. Er erscheint unbesiegbar, zumindest auf dieser Welt. Und so machen sich die jungen Engelskrieger auf ins Reich der Dämonen – um Sebastian dort mit seinen eigenen Waffen zu schlagen ...', '30.01.2015', 'Arena', ARRAY['Deutsch']::text[], 896, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Clary Fairchild']::text[], '{}', '{}', '220835a6-6d3d-5333-ade9-10d1162e15ac', '6', '{}', 'sheet', :'owner') on conflict do nothing;
