insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aac625ee-808a-5e16-9ada-4c41934a95de', 'Clockwork Princess', 'The Infernal Devices - Clockwork Princess', '9783401064765', 'Kurz vor ihrer Hochzeit sollte Tessa Gray eigentlich überglücklich sein. Wenn nicht die Gemeinschaft der Londoner Schattenjäger in ihrer Existenz bedroht wäre. Denn Tessas Widersacher Mortmain verfügt über eine Armee seelenloser Maschinen, die alles zu vernichten droht. Nur ein Detail fehlt ihm zur Ausführung seines Plans: Tessa selbst und ihre außergewöhnlichen Kräfte. Als er sie in seine Gewalt bringt, eilen Jem und Will, die beide Anspruch auf das Herz der jungen Frau erheben, zu ihrer Rettung. Doch am Ende ist es Tessa selbst, die über ihr Schicksal entscheiden muss, um dem Dunkel Einhalt zu gebieten ...', '06.09.2013', 'Arena', ARRAY['Deutsch']::text[], 616, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Will','Tessa','Jem']::text[], '{}', '{}', 'de37a2f7-1a82-5207-abdf-be5c9fa54c4b', '3', ARRAY['Prequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
