insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a1c16ff8-721b-5887-97dd-8fb4f6d9274b', 'Magisterium - Der Kupferne Handschuh', 'Magisterium - The Coppers Gauntlet', '9783732511815', 'Die Abenteuer am Magisterium, der unterirdischen Schule für Magie, gehen weiter. Am Ende des ersten Schuljahrs haben Callum und seine Freunde die erste Pforte durchschritten. Nun kann ihnen niemand mehr ihre Zauberkräfte nehmen. Doch auch im zweiten Schuljahr müssen sich die Schüler gefährlichen Aufgaben stellen, die alles bisher in den Schatten stellen. Dabei liegt das größte Abenteuer für Call außerhalb der Schulmauern. Schon seit Längerem fragt er sich, ob sein Vater ihm immer die Wahrheit über seine Vergangenheit erzählt. Höchste Zeit, dass er endlich herauszufindet, wem er trauen kann ...', '08.10.2015', 'One', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Callum']::text[], '{}', '{}', 'eb0287bc-465f-5ceb-b83f-a3af3ec2bf8e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
