insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('861fd61e-abe4-5a5e-9aeb-5dedf6412ade', 'The Mortal Instruments', NULL, '9780316465816', 'Hanging out with her best friend, Simon, is just about the most exciting thing in Clary''s life...that is, until she realizes there are people only she can see. But when her mother disappears and a monster attacks her, Clary has to embrace a world that she never even knew existed--a world full of vampires, werewolves, demons, and those who fight for the humans, Shadowhunters...', '31.10.2017', 'Yen Press', ARRAY['Englisch']::text[], 192, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['3P Objective']::text[], ARRAY['Clary Fairchild']::text[], '{}', '{}', '6c92d408-74da-505d-990f-e5fdeaf3694c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
