insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('93589bd2-70f9-5681-9c5a-baf0b0834eb0', 'The Mortal Instruments', NULL, '9780316465823', 'In the world of shadows, battling vampires and fending off wolves at knifepoint no longer frightens Clary. If it means finding her mother, she can deal with that much. But when a trusted ally betrays the Shadowhunters and Jace is nowhere to be found, she might have to face a truth too unsettling to bear...', '16.11.2018', 'Yen Press', ARRAY['Englisch']::text[], 192, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['3P Objective']::text[], ARRAY['Clary Fairchild']::text[], '{}', '{}', '6c92d408-74da-505d-990f-e5fdeaf3694c', '2', '{}', 'sheet', :'owner') on conflict do nothing;
