insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1f95df9b-14ca-5b42-90b6-536255d2fd21', 'Die Chroniken des Magnus Bane', 'The Bane Chronicles', '9783401069753', 'Tauche ein in die Welt von Magnus Bane! Der schillernde Oberste Hexenmeister von Brooklyn hat ein ereignisreiches Leben hinter sich. Sei es die Französische Revolution in Paris, der Börsencrash von New York oder das frühe London - Magnus war immer dabei und hatte seine funkensprühenden Finger im Spiel. Keine Frage, dass es dabei auch manchmal riskant wird für den vorlauten und lebenslustigen Draufgänger. Wenn man ewig lebt, muss man sich schließlich die Zeit vertreiben, da kommt eine kleine Romanze dann und wann gerade recht. Und wenn eine Situation doch mal zu heiß wird, gibt es ja immer noch den alles verhüllenden Zauberglanz. Alle Geheimnisse und Rätsel rund um Magnus Bane', '19.06.2014', 'Arena', ARRAY['Deutsch']::text[], 568, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', ARRAY['Magnus Bane']::text[], '{}', '{}', NULL, NULL, ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
