insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('8c683b00-40d7-5973-8d59-594b3ed9515b', '36081dd3-7e39-5fec-bf2d-107d59abbc89', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fa2da157-fe12-5042-987c-20a2185d3f22', 'The Lost Book of the White', NULL, '9781481495127', 'Life is good for Magnus Bane and Alec Lightwood. They’re living together in a fabulous loft, their warlock son, Max, has started learning to walk, and the streets of New York are peaceful and quiet—as peaceful and quiet as they ever are, anyway. Until the night that two old acquaintances break into Magnus’s apartment and steal the powerful Book of the White. Now Magnus and Alec will have to drop everything to get it back. They need to follow the thieves to Shanghai, they need to call some backup to accompany them, and they need a babysitter. Also, someone has stabbed Magnus with a strange magical weapon that is changing the very nature of his powers. Fortunately, their backup consists of Clary, Jace, Isabelle, and newly minted Shadowhunter Simon. In Shanghai, they learn that a much darker threat awaits them. Magnus’s magic is growing unstable, and if they can’t stop the demons flooding into the city, they might have to follow them all the way back to the source—to the very realm of the dead.', '01.09.2020', 'Simon & Schuster', ARRAY['Englisch']::text[], 365, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Magnus Bane','Alex Lightwood']::text[], '{}', '{}', 'a7d1915b-2860-513b-9301-cd4cb450e74f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
