insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('72d8e574-2c1e-50f2-b712-37a6fdea60dc', 'Trade', NULL, NULL, 'When my husband replaces me with a younger model, I’m entered into the lottery and traded to an Outsider for fuel. I expect a wasteland, but when the bunker doors open, I see green trees, blue skies, and him–a man half my age with a stone-cold face and a machete strapped to his thigh. I’ll be lucky to escape him alive. That’s what we’ve been told all our lives. And the people in charge wouldn’t lie to our faces us about everything. Would they?', '07.10.2025', NULL, ARRAY['Englisch']::text[], 184, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', '{}', ARRAY['Miscommunication']::text[], ARRAY['Dub-Con/Non-Con','Abtreibung','Physische Gewalt','Gore']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '7', '{}', 'sheet', :'owner') on conflict do nothing;
