insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('08a818b7-1878-5e57-b51c-8e8e55a1cd64', 'Immortal Beloved - Entflammt', 'Immortal Beloved', '9783785572535', 'Nastasja ist 459 Jahre alt, sieht aber aus wie 18. Kein Wunder, denn sie ist unsterblich. Mit ihrem Freund Incy, einem gefährlich dunklen Unsterblichen, zieht sie durch die Metropolen der Welt, immer auf der Suche nach der nächsten Party. Schon lange ist sie der Ewigkeit überdrüssig, zu schwer lasten die Erinnerungen auf ihr. Eines Tages hält sie es nicht mehr aus: Hals über Kopf flieht sie vor Incy – und vor sich selbst. Unterschlupf findet sie bei River, einer uralten Unsterblichen. Dort begegnet sie Reyn, in den sie sich auf den ersten Blick verliebt. Doch ausgerechnet er will, dass sie wieder geht. Nastasja bleibt – und schwebt schon bald in Gefahr. Wer ist es, der sie mit bösen Flüchen verfolgt? Incy, der ihr schon dicht auf den Fersen ist, oder Reyn, den sie von früher zu kennen glaubt? Trotz aller Zweifel nähert sie sich Reyn, bis sie mit Schrecken erkennt, wann sich ihre Wege schon einmal gekreuzt haben …', '01.01.2011', 'Loewe', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Nastasja']::text[], '{}', '{}', 'e809272d-1bdd-5d64-95ca-2dfea4fc5890', '1', '{}', 'sheet', :'owner') on conflict do nothing;
