insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e3802ed-8958-58ea-a584-373ac7d3160c', 'Immortal Beloved - Ersehnt', 'Darkness Falls', '9783785573440', 'Seit ihrem ersten Tag auf River''s Edge fühlt sich die unsterbliche Nastasja zu Reyn hingezogen. Doch ihre Liebe wird durch Nastasjas tragische Vergangenheit auf eine harte Probe gestellt: Sie erfährt, dass ihre Eltern blutrünstige Mörder waren. Nastasja fragt sich, ob sie überhaupt eine Chance hat, jemals die Dunkelheit in ihrem Wesen zu überwinden. Ihre größten Ängste scheinen wahr zu werden, als auf River''s Edge plötzlich einige Dinge aus dem Ruder laufen. Nastasja ist überzeugt, dass sie es ist, die alles verursacht. Kann sie gegen ihr mächtiges und dunkles Erbe ankämpfen? Und hat ihre Liebe zu Reyn eine Zukunft?', '09.01.2012', 'Loewe', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Nastasja']::text[], '{}', '{}', 'e809272d-1bdd-5d64-95ca-2dfea4fc5890', '2', '{}', 'sheet', :'owner') on conflict do nothing;
