insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('00b3ce6f-1d8e-546f-8103-3c5f530bb148', 'Immortal Beloved - Entfesselt', 'Eternally Yours', '9783785573457', 'Nur knapp ist Nastasja Incys Gewalt und damit dem Tod entronnen. Jetzt ist sie nach River''s Edge zurückgekehrt, wo die zarten Bande zwischen ihr und Reyn wieder aufleben. Doch ihre Liebe ist nicht ungetrübt, denn schon bald tauchen Rivers mächtige Brüder auf, die nur ein Ziel haben: River vor Nastasja zu schützen. Die Vorwürfe Nastasja gegenüber häufen sich, als immer wieder Unsterbliche von Unbekannten angegriffen werden und klar wird, dass es einen Verräter in den eigenen Reihen geben muss. Ist Nastasjas und Reyns Liebe stark genug, um alle Anfeindungen zu überstehen und am Ende zu siegen?', '16.01.2013', 'Loewe', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Nastasja']::text[], '{}', '{}', 'e809272d-1bdd-5d64-95ca-2dfea4fc5890', '3', '{}', 'sheet', :'owner') on conflict do nothing;
