insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38ea2cc6-7b32-5ad7-9b9e-74fce09081bf', 'Alera - Geliebter Feind', 'Allegiance', '9783492702164', 'Ich kam kurz vor Endes des Krieges zur Welt, als Kronprinzessin Hytanicas. Nachdem mein Volk sich im lang ersehnten Frieden eingerichtet hatte und Normalität eingekehrt war, wurde ich den Menschen präsentiert. Ich wuchs in einer Freiheit zu einer jungen Frau heran, die die kriegsgeplagten Generationen vor mir nie gekannt hatten. Doch alles Schöne geht einmal zu Ende, und genau hier setzt meine Geschichte ein', '09.08.2010', 'Piper', ARRAY['Deutsch']::text[], 555, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Alera']::text[], '{}', '{}', '6d6268d1-f40f-5219-a9d9-3c3294fde747', '1', '{}', 'sheet', :'owner') on conflict do nothing;
