insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c45382fd-ccb0-5e74-a040-d74e32f40e20', 'Alera - Zeit der Rache', 'Legacy', '9783492268769', 'Die junge Königin Alera hat gegen ihren Willen den herrschsüchtigen Steldor geheiratet. Ihre große Liebe zu Narian musste sie dem Wohl ihres Volkes opfern. Denn Narian steht auf der Seite des Feindes. Doch während der Krieg die Länder erschüttert und Hass und Rachegefühle nährt, kann Alera Narian nicht vergessen. Es gibt nur einen Weg, ihre Liebe zurückzugewinnen. Und dafür muss Alera das Undenkbare wagen …', '14.05.2012', 'Piper', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Alera']::text[], '{}', '{}', '6d6268d1-f40f-5219-a9d9-3c3294fde747', '2', '{}', 'sheet', :'owner') on conflict do nothing;
