insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ae5a4750-244d-5369-b267-3c000ededbd3', 'Der Ghostwriter', 'Herman Banks and the Ghost Writer', NULL, 'Herman Banks hat es vom armen Farmersjungen zum Multimillionär gebracht. Nur ein Wunsch treibt ihn noch um: Er möchte ein Buch schreiben, den großen, vollendeten Roman – und bezieht deshalb mit seiner jungen Frau das abgelegene Anwesen eines verstorbenen Autors in Südengland. Doch statt Inspiration zu finden, gerät Herman in eine mächtige Schreibblockade. Bis er im Zimmer mit der Kollektion alter Schreibmaschinen etwas Unheimliches vorfindet: das erste Kapitel seines geplanten Buchs ›Der Erlöste‹, von Geisterhand verfasst. Gleichzeitig beginnen Gegenstände aus dem Haus zu verschwinden … Ist Herman bereit, für seinen Lebenstraum alles zu opfern – wirklich alles?', '26.11.2015', 'Fischer', ARRAY['Deutsch']::text[], 160, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Herman Banks']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
