insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2712faed-12d5-5617-8e74-4ea19c2c2833', 'The Book of Tomorrow', NULL, '9780007290062', 'Lose yourself in the magical and mesmerising story from Cecelia Ahern of how tomorrow can change what happens today. Sometimes tomorrow has to start today… Tamara Goodwin has always lived in the here and now, never giving a second thought to tomorrow. Until a travelling library arrives in her tiny village, bringing with it a mysterious, large leather-bound book locked with a gold clasp and padlock. What she discovers within the pages takes her breath away and shakes her work to its core.', '01.10.2009', 'HarperCollins', ARRAY['Englisch']::text[], 339, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tamara']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
