insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fef704f6-5159-595b-b9c0-a3393565560c', 'Die Liebe deines Lebens', 'How to Fall in Love', '9783104027913', 'Adam will einfach nur, dass alles aufhört. Er ist über das Geländer der Brücke geklettert und schaut hinunter in das kalte, schwarze Wasser. Christine will einfach nur helfen. Mit einem Deal kann sie Adam vom Springen abhalten: Bis zu seinem nächsten Geburtstag wird sie ihn überzeugen, dass das Leben lebenswert ist! Schnell wird klar, dass sie ihn nur retten kann, wenn sie ihn wieder mit seiner großen Liebe zusammenbringt. Doch dann merkt Christine, wie sie sich selbst Hals über Kopf in Adam verliebt …', '08.10.2013', 'Fischer', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Christine','Adam']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
