insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('414aa9f5-8f8c-5b7f-a8bc-1364cf479760', 'Zwischen Himmel und Liebe', 'If You Could See Me Now; A Silver Lining', '9783104006536', 'Elizabeth hat ihr Leben fest im Griff. Sie kümmert sich um ihr Designbüro, ihren mürrischen Vater, die unzuverlässige Schwester und ihren sechsjährigen Neffen Luke. Doch niemanden lässt sie wirklich an sich heran – zu schmerzhaft war die Vergangenheit. Ivan ist nicht von dieser Welt. Niemand kann ihn sehen. Wirklich niemand? Nur seine Schützlinge: Sein Job ist, "bester Freund" zu sein für jemanden, der ihn braucht. So wie der einsame kleine Luke. Als Ivan jedoch plötzlich auch eine Verbindung zu Elizabeth spürt, ist er verwirrt – sie gehört doch gar nicht zu seinen Aufgaben …', '15.06.2010', 'Fischer', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Elizabeth','Ivan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
