insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ac00d146-f36d-577d-8010-f89eca0a16e7', 'Hundert Namen', 'One hundred names', '9783492605175', 'Journalistin Kitty Logan steht nach einem schweren Fehler vor dem Aus ihrer Karriere. Doch sie bekommt eine letzte Chance: eine geheimnisvolle Liste mit hundert Namen, über die sie einen Artikel schreiben soll. Niemand kann Kitty sagen, wer diese hundert Personen sind oder was sie miteinander verbindet. Neugierig begibt sie sich auf eine abenteuerliche Reise, auf der sie die unterschiedlichsten Menschen kennenlernt. Als diese sich Kitty langsam öffnen und ihre Träume und Wünsche mit ihr teilen, versteht sie endlich, dass in jedem eine außergewöhnliche Geschichte steckt, auch in ihr selbst.', '14.11.2013', 'Fischer', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kitty Logan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
