insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0278ebaa-742c-57c2-a9fc-9be0489b55f2', 'Ich hab dich im Gefühl', 'Thanks for the Memories', '9783492602983', 'Justin ist Gastdozent in Dublin und lässt sich trotz seiner Angst vor Nadeln zu einer Blutspende überreden. Joyce versteht seit ihrem schweren Unfall plötzlich Sprachen, die sie nie gelernt hat und erinnert sich an Dinge, die sie nicht erlebte. Als beide aufeinandertreffen, kommen sie sich ungewöhnlich bekannt vor, obwohl sie sich sicher sind, dass sie einander nicht kennen. Auf irgendeine Weise sind sie sich sofort vertraut …', '2008', 'Fischer', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Justin','Joyce']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
