insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4e6a12a8-3029-517c-89a2-34b4626b7dcb', 'Vermiss mein nicht', 'A Place Called Here', '9783104001142', 'Als Sandy Shortt zehn Jahre alt ist, verschwindet ein Mädchen aus ihrer Klasse. Seit dieser Zeit sucht sie leidenschaftlich nach allem, was vermisst wird: nach Socken, Schlüsseln und später auch nach Menschen. In ihrer Suchagentur macht sie Angehörigen Mut, denn sie gibt niemals auf. Doch als Sandy den Auftrag bekommt, den Bruder von Jack Ruttle wiederzufinden, verirrt sie sich im Wald und verschwindet selbst – an einen geheimnisvollen Ort, den alle nur »Hier« nennen ...', '05.10.2009', 'Fischer', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sandy Shortt']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
