insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0ecfad7a-d071-59ba-91e3-38567f9bd205', 'P.S. Ich liebe Dich', 'P.S. I Love You', '9783104001104', 'Nach dem Tod ihres Mannes Gerry ist Holly am Boden zerstört. Sie kann sich das Leben ohne ihre große Liebe einfach nicht vorstellen, und nichts kann sie aus ihrer Trauer reißen. Bis sie die Briefe entdeckt, die Gerry ihr kurz vor seinem Tod geschrieben hat. Endlich hat sie wieder einen Lichtblick in ihrem Leben, denn jeden Monat öffnet sie einen neuen Brief und widmet sich der Aufgabe darin. Schritt für Schritt heilen Gerrys Worte Hollys gebrochenes Herz – und sie erlebt mit den Briefen an ihrer Seite ein Jahr voller Überraschungen, neuer Freundschaft und ungeahntem Glück.', '05.10.2009', 'Fischer', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Holly']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
