insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('67d2ed19-2a63-58c6-8b99-31261f05dc13', 'Ein Moment fürs Leben', 'The Time of my Life', '9783492604208', 'Mit kleinen Lügen mogelt sich Lucy durchs Leben: eine winzige Flunkerei hier, eine verdrehte Wahrheit dort. Doch irgendwann beschließt ihre Familie, dass Lucy ihr verlogenes Leben in der viel zu kleinen Wohnung mit dem zu großen Sofa, und dazu noch arbeitslos, nicht weiterführen kann. Deshalb wird eine »Lebensagentur« eingeschaltet, und Lucy trifft, ob sie will oder nicht, ihr Leben in Gestalt eines Mannes. Und der ist alles andere als attraktiv, aber dafür sehr, sehr anhänglich …', '26.09.2012', 'Fischer', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lucy']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
