insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8bd9325c-2541-5b86-be2a-430f7e2c9a73', 'Flawed - Wie perfekt willst du sein?', 'Flawed', '9783104035420', 'Der erste Band des atemberaubenden Zweiteilers. Spannend und emotional erzählt Cecelia Ahern in dieser Dystopie die Geschichte der 17-jährigen Celestine, die darum kämpft, etwas anderes sein zu dürfen als perfekt. Celestines Leben scheint perfekt: Sie ist schön, bei allen beliebt und hat einen unglaublich süßen Freund. Doch dann handelt sie in einem entscheidenden Moment aus dem Bauch heraus. Und bricht damit alle Regeln. Sie könnte im Gefängnis landen oder gebrandmarkt werden – verurteilt als Fehlerhafte. Denn Fehler sind in ihrer Welt nicht erlaubt. Nichts geht über die Perfektion. Auch nicht die Menschlichkeit. Jetzt muss sie kämpfen – um ihre eigene Zukunft und um ihre große Liebe.', '29.09.2016', 'FJB', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Celestine']::text[], '{}', '{}', '1b59fe5f-edda-5774-89ef-24206e1f939f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
