insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a3ddb5ce-b6ef-5a3a-816a-0bdbbf56cadb', 'Für immer vielleicht', 'Where Rainbows End; Love, Rosie', '9783104006338', 'Rosie und Alex sind seit ihrer Kindheit beste Freunde. Schon allein ihre tiefe Freundschaft scheint eine Liebesbeziehung unmöglich zu machen, und so traut sich keiner, den ersten Schritt zu wagen. Als Alex nach dem Abschluss nach Amerika geht, trennen sich vorerst ihre Wege. Die ganze Zeit über bleiben Alex und Rosie allerdings in Kontakt. Sie schreiben sich Briefe und schicken sich Mails und SMS. Doch reicht das, um ihre Freundschaft, die eigentlich schon immer Liebe war, zu bewahren? Und gibt es wirklich nur eine einzige Chance für die große Liebe?', '01.01.2006', 'Fischer', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Rosie','Alex']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
