insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d38d526-f692-554f-b745-10d2e6b9d0ac', 'Winter Wolf (Vol.1)', '윈터 울프', '9783989501973', 'Lysithea hat alles verloren – ein Bürgeraufstand kostete ihrer Familie und ihrem Verlobten das Leben. Nun muss die junge Adlige aus ihrem eigenen Reich fliehen.\n In einem alten, verlassenen Herrenhaus im Wald trifft sie Taron, den Vermittler, der ihr zu einer sicheren Flucht verhelfen soll. Doch dann hindert ein Schneesturm die beiden an der Weiterreise, und das gegenseitige Misstrauen entwickelt sich schnell zu einer leidenschaftlichen Affäre. Nur ahnt Lythisea nicht, dass Taron ein düsteres Geheimnis hütet …', '19.01.2026', 'Papertoons', ARRAY['Deutsch']::text[], 240, 3, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Lysithea','Taron']::text[], ARRAY['Damsel in Distress']::text[], ARRAY['Tod von Familienangehörigen','Sexuelle Gewalt','Mord']::text[], '02db7c90-b530-54ec-b742-c7b517d4e5a9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('3b20a0a4-9419-5d4d-b6c5-65a10225f138', :'owner', '1d38d526-f692-554f-b745-10d2e6b9d0ac', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1600, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'dislike'::verdict_kind, 1.5, 'untertroffen'::expectation_kind, 2, 'fast'::burn_kind, 'Die Beiden MCs haben mich leider auch sehr genervt. Leider hat mir das hier gar nicht gefallen. Es ist alles viel zu schnell passiert. Die Gefühle der Charaktere haben sich gefühlt von Seite zu Seite verändert und dalles hat keinen Sinn gemacht. Werde ich nicht weiterlesen.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3a9bfdb6-0f90-5a3b-81fc-29d1237afa26', '3b20a0a4-9419-5d4d-b6c5-65a10225f138', :'owner', 1, '2026-03-12', '2026-03-15', NULL, NULL, 4, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('43f8e200-9452-5e61-b997-88d3fa3f3591', 'A Heir Comes to Rise', NULL, NULL, 'A SWORD… In the impoverished outer town of a kingdom where fae outrank humans, Faythe, an orphan with a talent for swordplay, knows the importance of keeping her head down around the fae patrol. She and best friend Jakon long for a better life, and her desire to swing her sword in combat may bring the purpose and coin she’s yearned for. A DREAM… When she draws the attention of royal guard Nik, she soon learns that her mortal nature isn’t the only reason to remain out of sight. Nik is a Nightwalker, a silent assassin of the mind with the power to enter others’ dreams, and whether she trusts him or not, he’s about to awaken abilities in Faythe that shouldn’t exist in a human. Nightmarish abilities. Deadly abilities. Abilities that will teach Faythe blood really does run thicker than water…and if she doesn’t trust in higher powers soon, blood will run indeed. AN HEIR… For this is no battle Faythe can fight with steel. Within the city walls, suspicions are arising, and here in the outer town she has deeper bonds to protect. It seems everyone will die with a dark secret to tell, but what if one unlikely human girl was born harboring the darkest secret of all…?', '25.02.2021', 'Lumarias Press', ARRAY['Englisch']::text[], 398, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Faythe','Nik']::text[], '{}', '{}', '9627c7c3-fcfd-520b-b7a0-3cac455b55bb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
