insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aa32297d-ebd8-5a5b-8e93-5c6d17f9bad3', 'Chicagoland Vampires - Verbotene Bisse', 'Friday Night Bites', '9783802583636', 'Nach ihrer Verwandlung in eine Vampirin zieht Merit in das Haus Cadogan ein. Im Auftrag ihres neuen "Meisters", dem Vampir Ethan Sullivan, soll sie fortan die Rolle der Vermittlerin zwischen Menschen und Vampiren spielen. Doch irgendjemand hat es darauf abgesehen, Zwietracht zwischen Sterblichen und Unsterblichen zu säen, und droht, eines der dunkelsten Geheimnisse der Vampire an die Öffentlichkeit zu bringen. Zu allem Überfluss beginnt Merit eine Affäre mit dem neuen Oberhaupt von Haus Navarre. Schon bald muss sie jedoch feststellen, dass sie noch immer Gefühle für Ethan hegt, dessen widersprüchliche Natur ihr wieder und wieder Rätsel aufgibt ...', '07.07.2011', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Merit']::text[], '{}', '{}', '64b76750-a2be-521c-98fc-039feb64baa6', '2', '{}', 'sheet', :'owner') on conflict do nothing;
