insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cab8bc49-1a39-5210-9db7-30301725b9a1', 'Bodycaught', NULL, NULL, 'Alecs Traum von Liebe und Zuneigung scheint sich zu erfüllen, als er dem attraktiven Adrian Adson begegnet. Doch schnell wird aus dem erotischen Spiel bitterer Ernst. Gefangen wie ein Tier, ist Alec Adrian hilflos ausgeliefert, bis ein Polizeieinsatz ihn und den Polizisten Mike zusammenführt. Mike muss sich bald fragen, ob seine Gefühle für den jungen Mann mehr als nur Beschützerinstinkte sind. Zudem ist Adrian noch immer auf freiem Fuß ...', '15.01.2021', 'CreateSpace', ARRAY['Deutsch']::text[], 936, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Alec','Mike']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
