insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f808d020-664a-5d85-aa04-8d61945fbc45', 'Kiss the Cop', NULL, '9783736871380', '"Bitte kräftig blasen!" "Den harten Schlagknüppel, den würde ich gerne mal anfassen." "Verhaftest du mich jetzt? Ich war unartig." Moritz hat genug von den ganzen dummen Sprüchen, nur weil er Polizist ist. Außerdem würde er viel lieber jemanden zum küssen haben, als ans Bett fesseln. Leider war er da bisher eher erfolglos. Und dann trifft er Deniz, der ein ganz anderes Klischee zu erfüllen scheint. Oder auch nicht.', '15.01.2015', 'BookRix GmbH & Co. KG', ARRAY['Deutsch']::text[], 17, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Moritz','Deniz']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
