insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5792d5e7-aece-5bb6-ae9e-3bde1be76ac2', 'Wer braucht schon Mathe?', NULL, '9783736871373', 'Mathis kann mit Mathe absolut nichts anfangen. Zu seinem Glück hat sein Freund Jonas viel mehr Ahnung. Und nicht nur von Mathe. Allerdings hat er auch das eine oder andere Geheimnis zu verbergen. Eine First Love Story.', '16.01.2015', 'BookRix GmbH & Co. KG', ARRAY['Deutsch']::text[], 21, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mathis','Jonas']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
