insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b8075bc4-b957-59bf-a0fc-1900ec1c321e', 'First Blinded Date', NULL, NULL, '„Blinded Date. Du wirst nie erfahren, wen du getroffen hast. Er wird nie wissen, wer du bist. Ihr beide werdet es nie vergessen können. Alles geht, nichts muss. Du alleine entscheidest.“ Durch eine Anzeige wird Silas auf das "Blinded Date" aufmerksam, einen Club mit ganz besonderen Regeln. Noch immer leidet er unter den Nachwehen seiner letzten Beziehung und erhofft sich nichts weiter als unverbindlichen Sex. Mit einiger Unsicherheit lässt er sich auf eine Probemitgliedschaft ein. Was er dabei erlebt, sprengt all seine Erwartungen und er erfährt am eigenen Leib, was es bedeutetet, Sex mit allen (anderen) Sinnen zu erleben.', '13.03.2020', 'CreateSpace', ARRAY['Deutsch']::text[], 96, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Silas']::text[], '{}', '{}', 'd355c2ec-a85f-590a-873e-f9a4bc0714ad', '1', '{}', 'sheet', :'owner') on conflict do nothing;
