insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8c573037-f5c2-5d9d-a368-877789387eec', 'Highspeed Love', NULL, NULL, 'Zu Beginn der Motocrosssaison bekommt der erfolgreiche Rennfahrer Cole einen neuen Mechaniker: Es ist ausgerechnet Maxwell, der Zwillingsbruder von Coles altem Erzfeind und härtestem Konkurrenten. Maxwell sieht seinem attraktiven Bruder zum Verwechseln ähnlich und bringt damit Coles Gefühle ganz schön durcheinander. Gleichzeitig weiß Cole nicht, ob er dem Neuen trauen kann. Während Cole sich mit seinen widerstreitenden Gefühlen auseinandersetzt, rückt der Tag des großen Rennens immer näher. Plötzlich häufen sich gefährliche technische Defekte an Coles Maschine. Steckt Maxwell dahinter? Kann Cole ihm noch trauen? Als es zu einem leidenschaftlichen Kuss zwischen den beiden kommt, steht ihre Welt auf einmal Kopf …', '17.11.2017', 'Ullstein', ARRAY['Deutsch']::text[], 290, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cole','Maxwell']::text[], '{}', '{}', '57ca766d-9ef8-557b-9dfa-6b6310c8b102', '1', '{}', 'sheet', :'owner') on conflict do nothing;
