insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6ad78252-99b8-5a50-846f-c6480802f375', 'Be My Bullet - Ehrensache', NULL, '9783959492256', 'Terry Hellfire, Rapper und Ex-Gangmitglied, ist der festen Überzeugung, selbst auf sich aufpassen zu können. Auch die eindrückliche Morddrohung seines Bruders, dem Anführer der Gang, jagt ihm keine Angst ein. Daher ist Terry nicht allzu begeistert, dass ihm sein Manager einen zusätzlichen Bodyguard besorgt hat. Jerome ist ein Bullet, der es sich offensichtlich zum Ziel gesetzt hat, Terry nicht nur den letzten Nerv zu rauben, sondern auch noch die Frechheit besitzt, unverschämt attraktiv zu sein. Ausgerechnet jetzt, wo er genug damit zu tun hat, sein neues Album aufzunehmen, kämpft Terry auch noch gegen die zunehmende Anziehung zwischen ihnen. Eine Liebe zwischen Bodyguard und Schützling, ist jedoch nicht nur extrem gefährlich, sondern einfach tabu. Denn Bullets schützen kompromisslos. Ihre Schuld ist erst dann beglichen, wenn sie ihr Leben gegeben haben. Doch was, wenn der Procept alles tut, dies zu verhindern und sich mit nicht weniger zufrieden geben will, als dem Herz seines Bullets?', '03.02.2023', 'MAIN', ARRAY['Deutsch']::text[], 333, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Terry Hellfire','Jerome']::text[], '{}', '{}', 'ba755f93-db76-5f3d-a2ff-75e77d79a33a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
