insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d5033b8-9245-5e03-bc6b-40c42444ddf1', 'Second Blinded Date', NULL, NULL, 'Nicht nur ein kleines Handicap, sondern auch seine besonderen Wünsche, machen es Sirius schwer, dauerhaft einen geeigneten Partner zu finden. Dabei arbeitet er in einem ganz speziellen Gay-Club, dem "Blinded Date", in dem: "Alles geht, nichts muss." Für seine Ehrlichkeit beim Abgeben einer gefundenen Uhr wird er doppelt belohnt: Neben dem Finderlohn, bekommt er auch eine Gratismitgliedschaft im "Blinded" und plötzlich eröffnen sich ihm neue Möglichkeiten. Schafft es Sirius die Selbstzweifel zu besiegen und den Mann seiner feuchten Träume zu erobern?', '02.02.2017', 'CreateSpace', ARRAY['Deutsch']::text[], 139, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sirius']::text[], '{}', '{}', 'd355c2ec-a85f-590a-873e-f9a4bc0714ad', '2', '{}', 'sheet', :'owner') on conflict do nothing;
