insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('45f2d225-6098-5453-9982-6bce9bcd6232', 'Irgendwie Top', NULL, NULL, 'Markus ist ein Jäger – willige Männer seine Beute. Jedes Wochenende macht er die einschlägigen Clubs unsicher. Er liebt den Kitzel der Jagd, bis zu dem Abend, an dem er Alex begegnet und in diesem eine Beute findet, die völlig unerreichbar erscheint. Denn Alex ist ein Top – in jeder Hinsicht ebenbürtig. Ein prickelndes Spiel beginnt, bei dem nicht klar ist, wer am Ende wen erlegt.', '24.11.2018', 'CreateSpace', ARRAY['Deutsch']::text[], 775, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Markus','Alex']::text[], '{}', '{}', '4d3b1dfe-b3a8-53fb-8a06-376b36509152', '2', '{}', 'sheet', :'owner') on conflict do nothing;
