insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6656485-86a7-56b5-87cb-3b8916653a72', 'Ironman', NULL, '9783736871144', 'Triathlet Kais Saisonhöhepunkt ist der Ironman auf Hawaii, für den er vor Ort wochenlang hart trainiert und seinen Körper an die Grenzen treibt. Für dieses Ziel muss auch seine Beziehung zu Leon zurückstehen, der sich im heimischen Mecklenburg um den Reitstall kümmert. Zum großen Ereignis fliegt er jedoch ein und Kai hat noch eine Überraschung für ihn: Einen exklusiven Urlaub im Waikiki Beach Resort.', '15.01.2015', 'BookRix GmbH & Co. KG', ARRAY['Deutsch']::text[], 18, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kai','Leon']::text[], '{}', '{}', '50770e4b-39aa-53b1-aa9e-2857e937967e', '2', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
