insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5aa49212-c64c-57dd-9ade-41d8b5d1fc5e', 'Downhill Love', NULL, '9783959492102', 'Battle of the best. Es soll das Sportereignis des Jahres werden. Um sein eher negatives und homophobes Image aufzupeppen, lässt sich Miles Bowders, amtierender Champion im Supercross, darauf ein, eine Serie von fünf Rennen gegen den King of Freeride, den Downhillbiker Luke Nodin zu fahren, nicht nur ein Native American, sondern zudem noch offen schwul. Im Schlagabtausch vor der Kamera zeigen sich beide als gleichwertige und erbitterte Gegner, auf dem Track hingegen lässt sich nicht leugnen, dass zwischen ihnen eine spezielle Art von Anziehung entsteht, die besonders Miles zu schaffen macht. Denn in seiner Vergangenheit lauern einige Ereignisse, deren Dämonen er kaum noch bändigen kann und die ihn immer mehr von innen heraus zerfleischen. Kann ausgerechnet Luke den Panzer seiner Abwehr durchbrechen, sein Herz berühren und ihm helfen zu heilen?', '07.08.2020', 'MAIN', ARRAY['Deutsch']::text[], 418, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Miles Bowders','Luke Nodin']::text[], '{}', '{}', '57ca766d-9ef8-557b-9dfa-6b6310c8b102', '2', '{}', 'sheet', :'owner') on conflict do nothing;
