insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4f6b8c01-2bbb-5a15-bd23-ee951b130db3', 'Irgendwie Lions Roar', NULL, NULL, 'Alex Rotkamp, ehemaliger Pornostar und Model, betreibt Sex als Kunstform, stets auf der Suche nach Perfektion. Er arrangiert die Situationen wie im Film: Inszenierungen aus Licht, Schatten und Lust. Während eines Besuchs im Gaytronic trifft er auf Markus, in dem er einen ebenbürtigen Gegner wittert. Das Spiel der beiden wird jedoch bald intensiver als gedacht, und Alex entgleitet zunehmend die Kontrolle.', '24.11.2018', 'CreateSpace', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Markus','Alex']::text[], '{}', '{}', '4d3b1dfe-b3a8-53fb-8a06-376b36509152', '3', '{}', 'sheet', :'owner') on conflict do nothing;
