insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c8373bcf-8dda-5ae1-b732-aa273568e1df', 'Be My Bullet - Geisterjagd', NULL, NULL, 'Für gewöhnlich bleibt ein Geist unsichtbar. Genau das möchte Anjou sein: nur am Rande existent im Bewusstsein anderer Menschen. Schon in jungen Jahren hat er eine schwere Schuld auf sich geladen, die ihn seither stark belastet. Am liebsten hält er sich daher fern von anderen Menschen. Bei den Bullets, einer Agentur besonderer Bodyguards, wacht er aus der Distanz über die Einsätze. In der Regel bekommt ihn niemand zu Gesicht. Als er bei einem Auftrag Noyan Morokh begegnet, bricht Anjou zum ersten Mal seine eigenen Regeln. Obwohl Noyans Verwandtschaft wahrscheinlich der japanischen Yakuza angehört, scheint der lebenslustige junge Mann mit deren Geschäften nichts zu tun zu haben. Noyan fasziniert und weckt Sehnsüchte in Anjou, die er sich selbst verboten hat. Denn er weiß, er bringt den Menschen, die ihm nahe stehen, kein Glück, nur den Tod. Umso mehr Ehrgeiz entwickelt er, Noyan vor unbekannten Angreifern zu beschützen. Bald stellt sich allerdings die Frage: Gelten die Anschläge wirklich Noyan oder betreibt nicht in Wahrheit jemand eine Geisterjagd?', '03.02.2023', 'MAIN', ARRAY['Deutsch']::text[], 500, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Anjou','Noyan Morokh']::text[], '{}', '{}', 'ba755f93-db76-5f3d-a2ff-75e77d79a33a', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('fcc56ba5-a21a-52f7-9a8b-9f1a4139fe04', :'owner', 'c8373bcf-8dda-5ae1-b732-aa273568e1df', 'tbr'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 799, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('45f5277b-3102-56a2-9ad1-9d1af04cc479', 'Fourth Blinded Date', NULL, NULL, '„Ich könnte nicht nur, ich würde diesen Raum zu deiner Realität werden lassen. Vier Wände, die ich zu deinem persönlichen Gefängnis mache, in dem einzig ich präsent bin und die Furcht vor dem, was kommen wird. Sie wird dich vereinnahmen, sie wird all dein Denken ausfüllen. Es gibt nichts, was du tun kannst, als dich zu ergeben, hinzunehmen, was dir geschehen wird. Du wirst keinerlei Wahl haben. Ich kann diesen Ort zu deiner persönlichen Hölle und deinem Himmel machen.“ Wenn MMA-Kämpfer Krystian eins liebt, dann sind es Herausforderungen. Zwischen Training, Kämpfen, Job und gelegentlichen Sexdates im Club Blinded Date, hat er sich sein Leben gut eingerichtet. Seine wahren Fantasien stehen dabei jedoch meistens hinter der Realität zurück. Als Jules Moreau ihm den Besuch von Zimmer Neunzehn „empfiehlt“, ahnt er noch nicht, dass dieses Mal nicht nur seine Fantasien erfüllt, sondern auch Gefühle geweckt werden, die nie einkalkuliert waren. Allerdings ist ein Spiel ein Spiel. Sich in der Realität jedoch einer Furcht zu stellen, erweist sich als weit schwieriger, als in der Fantasie.', '05.02.2020', 'CreateSpace', ARRAY['Deutsch']::text[], 204, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Krystian','Jules Moreau']::text[], '{}', '{}', 'd355c2ec-a85f-590a-873e-f9a4bc0714ad', '4', '{}', 'sheet', :'owner') on conflict do nothing;
