insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8ac8d961-21f2-5fdf-a853-07fddbf79367', 'Irgendwie Hochzeit', NULL, NULL, 'Seit aus Tim, der ehemaligen Nummer Fünfzehn die Nummer Eins in Marks Leben geworden ist, genießen die beiden ihre Zweisamkeit in Hamburg. Die Ehe für alle eröffnet ihnen neue Perspektiven für ihre Beziehung. Doch Mark kämpft mit Zweifeln und Eifersucht, während Tim unsicher ist, ob er Mark genügt. Zusammen müssen sie einen Weg finden und sich einander öffnen, denn beide träumen von einer gemeinsamen Zukunft und einer Hochzeit, die unvergessen bleiben wird.', '18.12.2020', 'CreateSpace', ARRAY['Deutsch']::text[], 245, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mark','Tim']::text[], '{}', '{}', '4d3b1dfe-b3a8-53fb-8a06-376b36509152', '5', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
