insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cf906682-7983-5747-bb47-73fea036bb5b', 'Bokeh - Schönheit der Unschärfe', NULL, '9781482706543', 'Nenn mich eine Schlampe und ich lache dir ins Gesicht, denn ja: Das bin ich. Aber ich bin erfolgreich, ich verdiene gut, ich habe ein tolles Leben. Das ist eben der Preis, den man zahlen muss. Mein Name ist Joschi Teschner. Du hast ihn bestimmt schon mal gehört … Erfolgsverwöhntes Supermodel, androgyn, selbstbewusst und reichlich arrogant, das ist Joschi, wie er sich der Welt präsentiert. Hinter dieser Fassade steht jedoch ein unglücklich verliebter junger Mann. Verliebt in den ebenso erfolgreichen Fotografen Dirk Landers, der allerdings nichts außerhalb des Fokus’ seiner Kamera wahrzunehmen scheint. Zwei Männer, die alle Gefühle gekonnt hinter ihrer Professionalität verbergen. Ein neuer Auftrag führt sie in der Ukraine zusammen ...', '21.03.2019', NULL, ARRAY['Deutsch']::text[], 142, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Joschi Teschner','Dirk Landers']::text[], '{}', '{}', NULL, NULL, ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
