insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f5df93e7-0fc2-5013-98b3-825e33b7f5b2', 'Irgendwie Anders', NULL, '9781480071124', 'Mark Benedikt ist Spezialist in Sachen One-Night-Stand. Mit seinem Kumpel Alex hat er eine Wette laufen: 30 Typen in 30 Tagen soll er flachlegen. Die Sache lässt sich gut an, bis er bei Nummer fünfzehn auf unerwartete Schwierigkeiten stößt.', '22.12.2018', 'CreateSpace', ARRAY['Deutsch']::text[], 148, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mark','Tim']::text[], '{}', '{}', '4d3b1dfe-b3a8-53fb-8a06-376b36509152', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
