insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dd92bfff-713f-5ed7-b381-77b4bcae9ceb', 'Mecklenburger Winter', NULL, '9781481871310', 'Der Winter hält das westliche Mecklenburg fest im Griff. Trotz eisiger Temperaturen hat der ehrgeizige Triathlet Kai nur ein großes Ziel vor Augen: den Sieg der Challenge Roth. Beim Training landet er unfreiwillig in einer Schneewehe und wird von dem jungen Leon gerettet. Der sportliche Reiter ist zwar alles andere als begeistert von Kais frecher Art und seinen offensiven Flirtversuchen, dennoch entsteht zwischen ihnen eine besondere Freundschaft. Je besser Kai Leon kennenlernt, umso komplizierter wird es allerdings. Aber Kai liebt Herausforderungen und seine Stärken sind enorme Ausdauer und ein absoluter Siegeswille. Eine ruhige Liebesgeschichte vor der herben Schönheit der Mecklenburger Landschaft.', '01.01.2012', 'CreateSpace', ARRAY['Deutsch']::text[], 492, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kai','Leon']::text[], '{}', '{}', '50770e4b-39aa-53b1-aa9e-2857e937967e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
