insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57d7cfad-144f-55fb-a815-66526fe56338', 'Magic Drowned in Blood', NULL, '9783736326941', 'Alle drei Jahre fordert das magische Königshaus des Nordens seinen Tribut: Um das Bündnis mit dem Nightcastle College zu erneuern, werden in einem gefährlichen Wettstreit zwei Studentinnen erwählt, die den Prinzen Loras und Tarabas als Schattengeliebte an deren Hof folgen. Halbvampirin Lark hält von dem ganzen Spektakel nichts, doch dann wird ihr Name bei der Auswahlzeremonie verlesen! Auf die Außenseiterin warten nicht nur tödliche Prüfungen, sie gerät auch in ein Machtspiel aus Intrigen, verbotenen Versuchungen und dunklen Geheimnissen zwischen den royalen Brüdern. Plötzlich stehen nicht nur ihr untotes Leben und ihre Zukunft auf dem Spiel - sondern auch ihr Herz ...', '02.02.2026', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Academia']::text[], 'NA'::audience_kind, NULL, 'Nightcastle College', '{}', ARRAY['Lark','Loras','Tarabas']::text[], ARRAY['Forbidden Love','Academy','Magical School']::text[], ARRAY['Tod von Familienangehörigen','Mobbing','Physische Gewalt','Gore','SVV','Sexuelle Gewalt']::text[], 'dfa4150f-5590-5a2e-a63d-1bdf74e15a74', '1', '{}', 'sheet', :'owner') on conflict do nothing;
