insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57deb067-68b6-585a-82dc-8d4f027cf120', 'Conviction - The Sophisticates', NULL, NULL, 'The Others are out there. Somewhere. And the Program wants the Deviant Dozen to find them. As a member of the Dozen, Cleo is still learning to master her deviation and she’s not having much luck. With the ability to cause explosions with just a thought, losing control always results in fiery disaster, making Cleo feel like a monster. She vows to ignore the urge to use her deviation and reclaim her humanity. But when terrible things start to happen at the Academy and Cleo is blamed for actions and events she doesn’t remember, she fears that the monster is taking over and she is becoming the dangerous weapon the Program created her to be. The one bright spot in Cleo’s life is Ozzy, the cocky Sophisticate with perfect aim who makes her heart race. But it seems whenever things start to heat up between them, Ozzy is sent away on another secret mission, and Cleo is left alone to ponder their relationship and deal with the aftermath of the accusations made against her. As the evidence against Cleo becomes more compelling and her closest friends turn against her, she finds her own conviction waning as she wonders if she really is as innocent as she wants to believe. And Cleo isn’t the only one struggling. Ozzy has always defined himself by his perfect aim and superior deviant skills, but after failed missions and bad choices, he realizes he can no longer trust his skills—or himself. Caught in a storm of shocking allegations and harsh punishments, will Cleo’s conviction finally break her?', '02.06.2014', NULL, ARRAY['Englisch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Cleo','Ozzy']::text[], '{}', '{}', 'ae3a5ff4-637a-5495-8c2c-29e6db212f37', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('94007418-8a1e-5344-9617-5c9e649d70fe', :'owner', '57deb067-68b6-585a-82dc-8d4f027cf120', 'ungelesen'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 299, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('757c950d-1265-5229-b165-b65eb20ca579', 'Redemption - The Sophisticates', NULL, NULL, 'The hunted have become the hunters. Cleo finally has the freedom that she’s always craved, but it’s come at a terrible price—the Program wants to terminate the Deviant Dozen and now she and her friends are on the run. To make matters worse, she’s finally learned to use her deviation—except when she’s around Ozzy. Even an innocent touch or kiss can cause her skills to spiral out of control. He’s the last person she’d ever want to hurt, but he’s also the one in the most danger if she can’t learn to master her skills and emotions. Ozzy’s duty has always been to protect the Dozen, but now he must make the difficult choice between laying low to stay safe or starting an all-out war so that the Dozen can truly be free. He knows that if they have any chance of outsmarting the Program, they’ll have to look for help in unlikely places—even if that means trusting their enemies. Rune and the Others have always been anonymous, hiding in the shadows as they carried out acts of terror and revenge. That all changed the moment the Program discovered they existed. To survive, Rune and the Others will be forced to make an alliance that is just as likely to kill them as it is to save them. Program officials are determined to erase their mistakes, but when they terrorize innocent civilians and Sophisticates in an effort to flush out the Dozen, they discover a harsh truth—the weapons they created are fighting back.', '17.12.2015', NULL, ARRAY['Englisch']::text[], 356, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Cleo','Ozzy']::text[], '{}', '{}', 'ae3a5ff4-637a-5495-8c2c-29e6db212f37', '3', '{}', 'sheet', :'owner') on conflict do nothing;
