insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba623c2d-c006-5886-99bd-de780b88d9d1', 'Heaven - Stadt der Feen', NULL, '9783401063829', 'London - das ist seine Stadt. Und über den Dächern von London - dort hat David sein zweites Zuhause gefunden. Hier oben kann er den Schatten der Vergangenheit entfliehen. Bis er eines Tages auf ein Mädchen trifft, das alles auf den Kopf stellt, woran er bisher geglaubt hat. Ihr Name ist Heaven. Sie ist wunderschön. Und sie behauptet, kein Herz mehr zu haben. Ehe David begreifen kann, worauf er sich einlässt, sind sie gemeinsam auf der Flucht. Und sie werden nur überleben, wenn sie Heavens Geheimnis lüften.', '15.08.2009', 'Arena', ARRAY['Deutsch']::text[], 356, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Heaven']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
