insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8573287c-5c40-5923-b5d0-ddcaf316cb77', 'Brood', NULL, NULL, 'For years, I’ve been waiting to turn twenty-one so I can marry, start breeding, and contribute to life in our bunker, but just before my spousal ceremony the council makes a change. Instead of marrying the boy who’s always been my best friend, I’m expected to marry Will instead. Will is a stranger–gruff, intimidating and fifteen years older than me. I’ll do my duty no matter what, but I really don’t want to marry and breed with him.', '07.10.2025', NULL, ARRAY['Englisch']::text[], 175, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', '{}', ARRAY['Pregnancy','Age Gap','Fake Marriage']::text[], ARRAY['Physische Gewalt','Dub-Con/Non-Con','Tod']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '5', '{}', 'sheet', :'owner') on conflict do nothing;
