insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ac000950-4fee-5ebe-b2ba-20217e605831', 'Bookboyfriend - Alex und Mia', NULL, NULL, 'Die Sache ist die: Ich bin kein schlechter Kerl. Mia anzulügen war nicht Teil eines Plans, es war eine simple Notlüge. Erfolg als Liebesromanautor mit einem weiblichen Pseudonym zu haben, gehörte auch nicht zum Plan. Wer hätte denn auch ahnen können, dass meine Bücher Bestseller werden? Und als wäre es nicht schon kompliziert genug, ist Mia auch noch Buchbloggerin und die beste Chat-Freundin meines Alter Egos. Online hält sie mich für die Bestsellerautorin Lexi Logan. Privat kennt sich mich als Alex Lawson und ist in mich verliebt. Ich weiß nicht, wie ich aus dem Schlamassel jemals wieder herauskommen soll ...', '02.06.2020', 'More', ARRAY['Deutsch']::text[], 290, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Alex','Mia']::text[], '{}', '{}', '6a4f9a42-809d-5680-8155-8143427d996f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
