insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d795c86-f398-5084-8d56-7c62cac299b9', 'X - Their Destiny was Foreordained. 1999. (Vol. 1)', 'Ekkusu', '9783551749116', 'Kamui Shiro ist nach Tokyo zurückgekehrt. Ein seltsames Geheimnis umgibt ihn. Kamui selbst weiß nichts über das Schicksal, das ihn erwartet. Aber er weiß, dass er denen, die ihm nahe stehen, Schmerz und Trauer bringt. Als weitere Wesen mit übernatürlichen Kräften in Tokyo auftauchen  die "Sieben Boten", die Kamuis Verbündete zu sein scheinen und die "Sieben Siegel", die seine Gegner sein könnten  wird allmählich klar, dass das Schicksal der Erde in den Händen dieses jungen Mannes liegt..', '15.02.2001', 'Carlsen', ARRAY['Deutsch']::text[], 188, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
