insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4e7ed28a-28f9-570e-96d6-9f1175e81b9d', 'X - Their Destiny was Foreordained. 1999. (Vol. 2)', 'Ekkusu', '9783551749123', 'Kamui Shiro ist nach sechs Jahren Abwesenheit nach Tokyo zurückgekehrt. Er selbst ahnt nichts von dem Schicksal, das ihn erwartet, er weiß nur, dass er denen, die ihm nahe stehen, Schmerz und Trauer bringt. Daher bewahrt er Abstand zu Kotori und Fuma Monou, den Freunden aus seiner Kindheit. Als andere Wesen mit übernatürlichen Kräften in Tokyo auftauchen, stellt sich allmählich heraus, dass das Schicksal der Erde in den Händen dieses jungen Mannes liegt. Gerade als Kamui beginnt, sich seiner Rolle bewusst zu werden, wird Fuma von unheilverkündenden Träumen heimgesucht.', '22.01.2001', 'Carlsen', ARRAY['Deutsch']::text[], 188, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
