insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('073a3230-2dba-57ba-936a-4fe146e910fd', 'X - Their Destiny was Foreordained. 1999. (Vol 7)', 'Ekkusu', '9783551749178', 'Das Ende der Welt ist für das Jahr 1999 vorhergesagt. Kamui Shiro ist nach sechs Jahren Abwesenheit nach Tokyo zurückgekehrt. In der Auseinandersetzung zwischen Himmelsdrachen und Erddrachen - den sieben Siegeln und den sieben Boten - soll Kamui über die Zukunft der Erde entscheiden. Kurz nachdem er erfährt, dass Kotoris Mutter starb, als sie an Stelle seiner eigenen Mutter das erste Heilige Schwert gebar, erleidet Tokiko Magami das gleiche schreckliche Schicksal. Während sich alle Himmels- und Erddrachen in Tokyo treffen, um über das Ende der Welt zu entscheiden, erfährt Kotori, dass sie wie ihre Mutter eine Entscheidung treffen muss...', '22.07.2001', 'Carlsen', ARRAY['Deutsch']::text[], 180, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '7', '{}', 'sheet', :'owner') on conflict do nothing;
