insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('641de596-d18c-5647-ae99-bc6de07d3c57', 'X - Their Destiny was Foreordained. 1999. (Vol.8)', 'Ekkusu', '9783551749185', 'Ein großes Erdbeben erschüttert Tokyo. Kamui schließt daraus, dass wieder Bannkreise zerstört wurden und das Ende der Welt immer näher rückt. Er wird von zwei mächtigen Magiern heimgesucht, deren Existenz ihm rätselhaft ist und lernt das 13. Oberhaupt des Sumeragi-Clans kennen, doch fühlt er sich durch die Ereignisse hin- und hergeworfen den Mächten völlig ausgeliefert. Kamui entschließt sich, ein Himmelsdrache zu werden, im Gegenzug entschließt sich Fuma, ein Erddrache zu werden und verübt eine schreckliche Tat...', '22.09.2001', 'Carlsen', ARRAY['Deutsch']::text[], 181, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '8', '{}', 'sheet', :'owner') on conflict do nothing;
