insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6c13edf-3923-5880-96b5-f1073cadb793', 'X - Their Destiny was Foreordained. 1999. (Vol.9)', 'Ekkusu', '9783551749192', 'Als Kamui entschieden hat, ein Himmelsdrache zu werden, wird im gleichen Moment ein zweiter Kamui dazu bestimmt, sein Schicksal als Erddrache anzunehmen. Nun steht Kamui plötzlich Fuma, sein liebster Kindheitsfreund, als zweiter Kamui und bitterster Feind gegenüber...', '22.11.2001', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '9', '{}', 'sheet', :'owner') on conflict do nothing;
