insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b5efe00f-6a82-5334-adc7-34d28a513d8e', 'X - Their Destiny was Foreordained. 1999. (Vol.10)', 'Ekkusu', '9783551749208', 'Als Kamui sich entschieden hat, ein Himmelsdrache zu werden, ist Fuma im gleichen Moment dazu bestimmt, sein Schicksal als Erddrache anzunehmen. Das zweite Heilige Schwert, von Tokiko Magami im Togakushi-Schrein geboren, wird von den Sieben Siegeln in einem Brunnen auf dem CLAMP-Campus versteckt. Kamu ist der Auserwählte, der es tragen darf, um im Kampf um das Schicksal der Erde gegen die Erddrachen zu bestehen...', '22.01.2002', 'Carlsen', ARRAY['Deutsch']::text[], 179, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '10', '{}', 'sheet', :'owner') on conflict do nothing;
