insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ad206cdc-a161-5fb7-8aeb-866e34019802', 'X - Their Destiny was Foreordained. 1999. (Vol.11)', 'Ekkusu', '9783551749215', 'Kamui erinnert sich an die Geschehnisse, seit er nach Tokyo gekommen ist, und wie es dazu kam, dass er nun mit Yuzuriha, Sorata und Arashi zusammen wohnt. Auf dem CLAMP-Campus lernt er Keiichi Segawa kennen, der Kamui sofort in sein Herz schließt und ihn zum Essen einlädt. Als plötzlich ein Erdbeben den CLAMP-Campus und die ganze Stadt erzittern lässt, sammeln sich die Himmelsdrachen, um dem Ernst der Lage zu begegnen...', '22.03.2002', 'Carlsen', ARRAY['Deutsch']::text[], 176, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '11', '{}', 'sheet', :'owner') on conflict do nothing;
