insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('50fa803e-a843-5470-a60e-c91e66accbaa', 'X - Their Destiny was Foreordained. 1999. (Vol.12)', 'Ekkusu', '9783551749222', 'Kamui muss hilflos mit ansehen, wie Subaru Sumeragi im Kampf mit Fuma ein Auge verliert. Als der Himmelsdrache im Kampf gegen den Erddrachen endgültig unterliegt, fällt auch sein Bannkreis und der Sunshine Tower stürzt in sich zusammen. Kamui macht sich schwere Vorwürfe, dass er nicht in den Kampf eingreifen konnte, aber seine Freunde muntern ihn wieder auf. Mit der Unterstützung von Prinzessin Hinoto versuchen die Himmelsdrachen, die schwierige Situation in den Griff zu kriegen..', '22.05.2002', 'Carlsen', ARRAY['Deutsch']::text[], 168, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '12', '{}', 'sheet', :'owner') on conflict do nothing;
