insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('20f2ecd9-6984-5600-bcff-156461878373', 'X - Their Destiny was Foreordained. 1999. (Vol.13)', 'Ekkusu', '9783551749239', 'Nachdem Subaru Sumeragi im Kampf mit Fuma ein Auge verloren hat, wird auch Fürst Saiki vom Kamui der Erddrachen grausam getötet. Als der Himmelsdrachen zu Boden geht, fällt auch sein Bannkreis. Kurz darauf stürzen auch die Wolkenkratzer in Shinjuku ein, als Yuzuriha Nekoi in ihrem Kampf gegen Satsuki Yatouji unterliegt. Der Kampf scheint verloren, die Erddrachen übermächtig...', '22.07.2002', 'Carlsen', ARRAY['Deutsch']::text[], 175, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '13', '{}', 'sheet', :'owner') on conflict do nothing;
