insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('45eaecc5-d330-5a65-ae52-2b2c93c5e920', 'X - Their Destiny was Foreordained. 1999. (Vol.14)', 'Ekkusu', '9783551749246', 'Kamui Shiro wird zum Kamui der Himmelsdrachen. Seine Bestimmung ist, gegen seinen Kindheitsfreund Fuma anzutreten, den Bruder seiner geliebten Kotori, der im Moment der Entscheidung Kamui Shiros, ein Himmelsdrachen zu werden, zum Kamui der Erddrachen wird. Können die beiden das ihnen vorherbestimmte Schicksal abwenden? Eine Auseinandersetzung bis auf den Tod scheint unausweichlich...', '15.02.2001', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '14', '{}', 'sheet', :'owner') on conflict do nothing;
