insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8ff8125d-60b3-5700-a752-6fd574c94507', 'X - Their Destiny was Foreordained. 1999. (Vol.15)', 'Ekkusu', '9783551749253', 'Kamui Shiros Bestimmung ist es, gegen seinen Kindheitsfreund Fuma anzutreten, der im Moment der Entscheidung Kamui Shiros, ein Himmelsdrachen zu werden, zum Kamui der Erddrachen wird. Es entbrennt ein erbarmungsloser Kampf zwischen Erddrachen und Himmelsdrachen, der viele Opfer fordert. Nun will Kamui alles in seiner Macht stehende tun, um den wahren Fuma zurückzubringen...', '22.11.2002', 'Carlsen', ARRAY['Deutsch']::text[], 171, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '15', '{}', 'sheet', :'owner') on conflict do nothing;
