insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d1ba55df-afeb-5ffc-92b3-39687e975b23', 'X - Their Destiny was Foreordained. 1999. (Vol.16)', 'Ekkusu', '9783551749260', 'In Tokyo ist ein erbarmungsloser Kampf zwischen Erddrachen und Himmelsdrachen entbrannt. Nicht nur unter den sieben Boten und den sieben Siegeln fordert der Kampf seine Opfer, sondern auch die Stadt Tokyo droht in Schutt und Asche zu zerfallen, als ein Bannkreis nach dem anderen zerstört wird. Doch nun will Kamui Shiro alles in seiner Macht stehende tun, um den wahren Fuma zurückzubringen...', '22.01.2003', 'Carlsen', ARRAY['Deutsch']::text[], 170, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '16', '{}', 'sheet', :'owner') on conflict do nothing;
