insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('80d24bef-e871-5eb8-aca0-ef4380c9f9d9', 'X - Their Destiny was Foreordained. 1999. (Vol.17)', 'Ekkusu', '9783551749277', 'Das Ende der Welt ist für das Jahr 1999 vorhergesagt. Kamui Shiro ist nach sechs Jahren Abwesenheit nach Tokyo zurückgekehrt. Damit nimmt die letzte Legende der Erde ihren Anfang. Kamui Shiro wird zum Kamui der Himmelsdrachen. Seine Bestimmung ist es, gegen seinen Kindheitsfreund Fuma Monou anzutreten, der im Moment der Entscheidung Kamui Shiros, ein Himmelsdrachen zu werden, zum Kamui der Erddrachen wird. Ein erbarmungsloser Kampf entbrennt, dessen Ausgang mehr als ungewiss ist...', '22.04.2003', 'Carlsen', ARRAY['Deutsch']::text[], 167, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '17', '{}', 'sheet', :'owner') on conflict do nothing;
