insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b2649bb0-bf0b-550f-9c85-eba2d51f2859', 'X - Their Destiny was Foreordained. 1999. (Vol.18)', 'Ekkusu', '9783551749284', 'Das Ende der Welt ist für das Jahr 1999 vorhergesagt. Yuzuriha und Arashi erzeugen ein Schutzschild, um sich auf den Kampf mit dem Erddrachen vorzubereiten. Sorata wird schwer verletzt und versucht dennoch verzweifelt, Arashi zu schützen. Kamui leidet Seelenqualen, weil er einsehen muss, dass alle, die er zu schützen hoffte, verloren sind. In der Zwischenzeit wird Hinotos Seele langsam von einem bösen Geist erobert und vergiftet.', '15.02.2001', 'Carlsen', ARRAY['Deutsch']::text[], 176, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Kamui Shiro']::text[], '{}', '{}', 'fe48ec11-28ca-5c14-baf1-719f9c17c5e3', '18', '{}', 'sheet', :'owner') on conflict do nothing;
