insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('764a7e63-4b71-5d77-8bb7-8c610abc9014', 'Spellcaster- Düstere Träume', 'Spellcaster', NULL, 'Dieser Ort ist böse: Dank ihrer Hexenmagie spürt Nadia es sofort, als sie mit ihrer Familie nach Captive’s Sound zieht. Aber wer steckt dahinter? Verlaine, das seltsame Mädchen mit den silberweißen Haaren, das ihr am ersten Schultag ihre Freundschaft anbietet? Hoffentlich ist es nicht Mateo, dieser faszinierende Junge, der ihr Herz höher schlagen lässt. Mateos Visionen bringen ihn fast an den Rand des Wahnsinns. Es ist ein dunkler Familienfluch, der seine Mutter in den Tod getrieben hat und nun auch ihm zum Verhängnis werden könnte. Immer wieder sieht er in seinen Träumen ein schönes, sterbendes Mädchen … und jetzt ist dieses Mädchen wirklich da! Mit ihrem Vater und ihrem Bruder ist Nadia nach Captive’s Sound gezogen. Mateo ahnt, was kommen wird: Auf magische Weise sind er und Nadia füreinander bestimmt. Doch ihr Ende ist ungewiss … Ein Junge, der von dunklen Visionen gequält wird. Ein Mädchen mit der magischen Gabe, ihn zu retten. Das Böse, das sie beide vernichten will.', '10.10.2015', 'ya!', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Nadia']::text[], '{}', '{}', '98a99a3e-d07e-5b87-ab32-c4541aa29e54', '1', '{}', 'sheet', :'owner') on conflict do nothing;
