insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1f54794f-228d-52ab-a035-0a9df1e6699a', 'Spellcaster - Schwarze Magie', 'The First Midnight Spell', '9783959676496', 'Die Ersten Gesetze der Hexenzunft verbieten es, eine Verbindung mit dem Sohn einer anderen Hexe einzugehen. Doch die junge Elizabeth ist unsterblich in Nathaniel Porter verliebt. Obwohl er der Sohn der Anführerin ihres Zirkels ist, will sie einen Weg finden, wie sie trotzdem zusammen sein können. Dafür begibt Elizabeth sich auf den Pfad der dunklen Künste. Nur ein bisschen schwarze Magie, um Nat nicht aufgeben zu müssen - was kann schon passieren?', '15.08.2016', 'ya!', ARRAY['Deutsch']::text[], 83, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Nadia']::text[], '{}', '{}', '98a99a3e-d07e-5b87-ab32-c4541aa29e54', '2', '{}', 'sheet', :'owner') on conflict do nothing;
