insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('29680339-422b-5021-a5ff-3eb2ed381490', 'Spellcaster - Dunkler Bann', 'Steadfast', '9783959679688', 'Endlich kann Nadia aufatmen: In der Nacht von Halloween ist die dunkle Zauberin Elizabeth in den Flammen umgekommen. Und in Mateo hat sie nicht nur ihre große Liebe gefunden, sondern auch einen treuen Verbündeten. Mit ihm verbindet sie ein magisches Band, das ihr neue Kräfte verleiht. Aber es gibt noch so viel, was sie über die Hexenkunst lernen muss. Und plötzlich kehrt auch noch Elizabeth zurück! Sie hat nicht nur einen Dämonen mitgebracht, sondern verfolgt einen höllischen Plan, der die ganze Stadt in ewige Dunkelheit stürzen soll.', '10.03.2016', 'ya!', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Nadia']::text[], '{}', '{}', '98a99a3e-d07e-5b87-ab32-c4541aa29e54', '3', '{}', 'sheet', :'owner') on conflict do nothing;
