insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('209669a1-0e47-5968-9b4d-b850a1ed88a8', 'Spellcaster - Finsterer Schwur', 'Sorceress', '9783959676168', 'Um die Bewohner von Captive’s Sound zu retten, hat Nadia dem Herrscher der Unterwelt die Treue geschworen. Nun muss sie Jenem dort unten an der Seite der Zauberin Elizabeth dienen und wird von ihr in der dunklen Magie unterwiesen. Doch anstatt dadurch mehr über ihre bösen Pläne zu erfahren, droht Nadia der Verlockung ihrer neuen Macht zu verfallen. Abgeschottet von ihren Freunden, ist sie so empfänglich für die Dunkelheit wie noch nie…', '12.09.2016', 'ya!', ARRAY['Deutsch']::text[], 336, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Nadia']::text[], '{}', '{}', '98a99a3e-d07e-5b87-ab32-c4541aa29e54', '4', '{}', 'sheet', :'owner') on conflict do nothing;
