insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('70c71baf-ec4f-54f0-951a-b9dfcaef0a1c', 'Balthazar', NULL, '9780062099150', 'Das Blut der 16-jährigen Skye verfügt über eine einzigartige Macht. Wenn ein Vampir davon trinkt, wird er in die Zeit zurückversetzt, in der er noch lebte. Diese Erfahrung macht den Blutsauger beinahe sofort abhängig. Da ist es nicht überraschend, dass der brutale Vampir Redgrave alles daran setzt, Skye in seine Gewalt zu bekommen. Denn wer Skyes Blut kontrolliert, beherrscht auch die Abhängigen. Nur der Vampir Balthazar nimmt den Kampf gegen Redgrave auf. Doch was anfangs lediglich Beschützerinstinkt und Rebellion gegen seinen vampirischen Erzeuger ist, entwickelt sich rasch zu mehr, als Balthazar erkennt, was Skye wirklich ist: die andere Hälfte seiner Seele.', '04.03.2013', 'Penhaligon', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Skye','Balthazar']::text[], '{}', '{}', '1d6950ac-e0ff-5695-9c93-0a6133857cda', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
