insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('55fda59d-aaa2-52f6-8648-f109c3177800', 'Evernight', 'Evernight', '9783764530457', 'An jedem Ort wäre Bianca lieber als an diesem: Das Evernight-Internat ist eine Eliteschule, und die anderen Schüler sind einfach zu perfekt – zu clever, zu schön, zu rücksichtslos. Als sie Lucas kennenlernt, ist sie davon überzeugt, er sei der einzige normale Mensch in ihrer Umgebung. Bianca merkt sofort, dass es eine besondere Verbindung zwischen ihr und Lucas gibt. Dabei verbirgt er ein Geheimnis, das nicht nur alles auf den Kopf stellt, woran sie glaubt – es könnte auch ihrer Familie und allen, die Bianca kennt, den Tod bringen.', '20.07.2009', 'Penhaligon', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Evernight-Internat', '{}', ARRAY['Bianca']::text[], '{}', '{}', '1d6950ac-e0ff-5695-9c93-0a6133857cda', '1', '{}', 'sheet', :'owner') on conflict do nothing;
