insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a61843f2-52a9-5aed-8eeb-22302503ec80', 'Constellation - Gegen alle Sterne', 'Defy the Stars', '9783570174395', 'Noemi ist bereit zu sterben, um ihren Planeten gegen die Erde zu verteidigen. Als sie in einem verlassenen Raumschiff nach Hilfe für ihre schwer verletzte Freundin sucht, trifft sie auf Abel, die perfekteste künstliche Intelligenz, die je entwickelt wurde. Er ist programmiert, sie zu töten. Gleichzeitig aber muss Abel dem ranghöchsten Menschen an Bord gehorchen. So gelingt es Noemi, ihm das Geheimnis zu entlocken, das ihren Planeten retten kann. Dafür müsste sie Abel zerstören. Doch Abel sieht nicht nur aus wie ein Mensch aus Fleisch und Blut. Je näher sich die beiden auf der lebensgefährlichen Mission kommen, desto klarer wird Noemi: Er fühlt auch wie ein Mensch. Bald steht er längst nicht mehr nur aus programmiertem Gehorsam zu ihr. Aber ist er wirklich frei, alles für sie zu tun?', '20.11.2017', 'cbj', ARRAY['Deutsch']::text[], 507, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Romantasy']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Noemi','Abel']::text[], '{}', '{}', '41414250-7832-587f-a7e2-27d9e9cae871', '1', '{}', 'sheet', :'owner') on conflict do nothing;
