insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('18fc4111-efce-5f4c-831a-77adeafcc107', 'Evernight - Tochter der Dämmerung', 'Stargazer', '9783764530525', 'Bianca liebt Lucas, auch wenn er als Jäger der eingeschworene Feind von Vampiren wie ihr war. Doch da erlebt sie mit, wie gnadenlos seine Familie auf eine Freundin von ihr Jagd macht, und ihr kommen Zweifel. Soll sie sich von ihm abwenden, wie ihre Eltern es wünschen? Jetzt muss sie sich entscheiden – zwischen ihrer Familie und der Liebe zu ihrem größten Feind.', '28.06.2010', 'Penhaligon', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Evernight-Internat', '{}', ARRAY['Bianca']::text[], '{}', '{}', '1d6950ac-e0ff-5695-9c93-0a6133857cda', '2', '{}', 'sheet', :'owner') on conflict do nothing;
