insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('36bf679f-7857-5117-bede-738ac50e69c8', 'Evernight - Hüterin des Zwielichts', 'Hourglass', '9783764530532', 'Bianca, die Tochter zweier Vampire, hat mit ihrem Volk gebrochen und sich entschlossen, den Vampirjägern vom Schwarzen Kreuz beizutreten. Denn nur so kann sie ihrer großen Liebe Lucas nahe sein. Da nähert sich Biancas achtzehnter Geburtstag und ihre Vampirnatur gewinnt immer mehr die Oberhand. Lucas ist bereit, sich zu opfern, damit sie endgültig zum Vampir werden kann. Doch Bianca lehnt ab und will lieber tot sein, als für alle Ewigkeit von Lucas getrennt zu werden. Da ahnt sie noch nicht, dass ihr wahres Schicksal noch viel erschreckender ist …', '25.07.2011', 'Penhaligon', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Evernight-Internat', '{}', ARRAY['Bianca']::text[], '{}', '{}', '1d6950ac-e0ff-5695-9c93-0a6133857cda', '3', '{}', 'sheet', :'owner') on conflict do nothing;
