insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4c1d37a5-26a9-5000-b5e1-c325ec3302bc', 'Evernight - Gefährtin der Morgenröte', 'Afterlife', '9783764530549', 'Noch nie war die Barriere zwischen Bianca und ihrem geliebten Lucas größer. Denn Lucas wurde in einen Blutsauger verwandelt und wird nicht nur von seiner Familie gejagt, die sich ganz dem Töten von Vampiren verschrieben hat. Er muss auch lernen, seinen Blutdurst zu bezwingen. Da entdeckt Bianca, dass sie als Geist doch nicht so machtlos ist, wie alle behaupten. Im Gegenteil! Es scheint sogar einen Weg zu geben, um Lucas zu erlösen – wenn Bianca bereit ist, sich für ihn zu opfern …', '27.02.2012', 'Penhaligon', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Evernight-Internat', '{}', ARRAY['Bianca']::text[], '{}', '{}', '1d6950ac-e0ff-5695-9c93-0a6133857cda', '4', '{}', 'sheet', :'owner') on conflict do nothing;
