insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('624b4efa-6ce8-50e8-ae3d-6ce12819604a', 'Fateful - In weite Ferne', 'Fateful', '9783442269945', '1912: Seit vielen Jahren steht die 18-jährige Tess in den Diensten einer reichen, kaltherzigen Familie. Auf einer Reise nach Amerika beschließt sie zu fliehen, sobald das Schiff - die RMS Titanic - den Hafen erreicht. An Bord trifft sie jedoch den gut aussehenden Alec, der sie von ihren Sorgen ablenkt. Aber Alec hütet düstere Geheimnisse - und er wird von gefährlichen Feinden verfolgt. Ihre Liebe zu ihm bringt Tess in ungeheuerliche Gefahr, und auch das Schicksal hält noch Einiges für sie bereit, bevor die Reise mit der Titanic vorüber sein wird.', '17.06.2014', 'blanvalet', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'RMS Titanic', '{}', ARRAY['Tess','Alec']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
