insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('b6531f4b-d7ff-5860-9919-8996aba32f15', :'owner', '9c56809f-56c9-5c5e-aa4c-acf31e8fbb9a', 'ungelesen'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1290, NULL, NULL, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5d50535d-4daf-5862-9fa8-d1790d3dc949', 'Maybe Someday', NULL, '9783423428972', 'Das Letzte, was Sydney will, als sie bei dem Musiker Ridge einzieht, ist, sich in ihn zu verlieben. Zu frisch ist die Wunde, die ihr Ex hinterlassen hat. Und auch Ridge hat gute Gründe, seine neue Mitbewohnerin nicht zu nah an sich heranzulassen, denn er hat seit Jahren eine feste Freundin: Maggie – hübsch, sympathisch, klug, witzig. Und dann passiert es doch. Als Sydney beginnt, Ridge beim Songschreiben zu helfen, kommen sie sich näher. Auch wenn beide die Stopptaste drücken, bevor wirklich etwas passiert, können sie nicht verhindern, dass ihre Gefühle füreinander immer intensiver werden, je verzweifelter sie diese zu unterdrücken versuchen …', '18.03.2016', 'dtv', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sydney']::text[], '{}', '{}', '490cc900-52da-5da7-808e-f796b12fb0ee', '1', '{}', 'sheet', :'owner') on conflict do nothing;
