insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d3044146-7613-526a-a0e6-01d2ef47cf62', 'Zurück ins Leben geliebt', 'Ugly Love', '9783423430951', 'Als Tate zum Studium nach San Francisco zieht, stolpert sie dort gleich am ersten Abend über Miles Archer: Miles, der Freund ihres Bruders, der niemals lächelt, meistens schweigt und offensichtlich eine schwere Bürde mit sich herumträgt. Miles, der so attraktiv ist, dass Tate bei seinem Anblick Herzflattern und weiche Knie bekommt. Miles, der, wie er selbst zugibt, seit sechs Jahren keine Frau mehr geküsst hat. Miles, von dem Tate sich besser fernhalten sollte, wenn ihr ihr Gefühlsleben lieb ist …', '22.07.2016', 'dtv', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tate','Miles Archer']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
