insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b22f601e-94b6-5468-ad67-e28ae57d9aa1', 'Weil ich Layken liebe', 'Slammed', '9783423421348', 'Nach dem Unfalltod ihres Vaters zieht die 18-jährige Layken mit ihrer Mutter und ihrem Bruder von Texas nach Michigan. Nie hätte Layken gedacht, dass sie sich dort bereits am ersten Tag Hals über Kopf verliebt. Und dass diese Liebe mit derselben Intensität erwidert wird. Es sind die ganz großen Gefühle zwischen Layken und Will. Das ganz große Glück – drei Tage lang. Denn dann stellt das Leben sich ihrer Liebe mit aller Macht in den Weg …', '01.11.2013', 'dtv', ARRAY['Deutsch','Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Layken','Will']::text[], '{}', '{}', 'd5cc27bf-3995-55a6-8c29-334f6526eb18', '1', '{}', 'sheet', :'owner') on conflict do nothing;
