insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('49f42ed1-e5cf-5ed4-8b17-9799319b9fc9', 'Love and Confess', 'Confess', '9783423428507', 'Vor fünf Jahren hat Auburn ihre erste große Liebe in Dallas zurücklassen müssen, verbunden mit einem Schmerz, den sie bis heute nicht ganz überwunden hat. Jetzt ist sie zurück in der Stadt und versucht, sich ein neues Leben aufzubauen. Ausgerechnet da trifft sie auf Owen, den jungen Künstler mit den grünen Augen, der sich von den Geschichten anderer Menschen für seine Bilder inspirieren lässt. Vom ersten Augenblick an fühlt Auburn sich zu ihm hingezogen – und Owen geht es genauso. Die beiden verlieben sich mit ungeahnter Wucht ineinander. Doch beide verbergen Geheimnisse voreinander, die alles zu zerstören drohen, was ihnen wichtig ist – vor allem Owen, der mehr mit Auburns Vergangenheit zu tun hat, als sie ahnt ...', '20.11.2015', 'dtv', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Auburn','Owen']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
