insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5737d2a5-a646-5f41-b7dc-5995db1a3b2a', 'Weil ich Will liebe', 'Point of Retreat', '9783423421362', 'Es ist jetzt über ein Jahr her, dass Will Layken zum ersten Mal begegnet ist. Und ihre Liebe scheint täglich stärker zu werden. Doch als Will im neuen Studienjahr auf seine Ex-Freundin Vaughn trifft, beschließt er, Layken nichts davon zu erzählen. Ein fataler Fehler, denn als Layken die beiden zufällig sieht, missversteht sie die Situation ...', '01.05.2014', 'dtv', ARRAY['Deutsch','Englisch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Layken','Will']::text[], '{}', '{}', 'd5cc27bf-3995-55a6-8c29-334f6526eb18', '2', '{}', 'sheet', :'owner') on conflict do nothing;
