insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5337c091-fce8-5767-87ff-f85cc64890c9', 'Finding Cinderella', NULL, '9783423428903', 'Nur ein einziges Mal sind sie sich begegnet, doch Daniel kann sie nicht vergessen: die Unbekannte, die nach einer mehr als romantischen Stunde vor ihm davonlief wie Cinderella vor dem Prinzen. Ein Jahr und eine gescheiterte Beziehung später hat Daniel den Glauben an die wahre Liebe verloren. Bis er bei seinem Freund Dean Holder Six kennenlernt, die beste Freundin von Sky – und es ihn trifft wie einen Blitzschlag.', '18.12.2015', 'dtv', ARRAY['Deutsch']::text[], 176, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Daniel','Holder Six']::text[], '{}', '{}', '35c28281-e403-575b-822c-2e7fb697e7f9', '3', '{}', 'sheet', :'owner') on conflict do nothing;
