insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('056737f6-2bf8-583a-84d9-37670b37286a', 'Weil wir uns lieben', 'This Girl', '9783423427036', 'Ein Auf und Ab der Gefühle – das ist die Liebesbeziehung von Will und Layken seit dem ersten Tag, an dem sie sich trafen. Erst jetzt, nach ihrer Hochzeit, scheint ihr Glück perfekt zu sein – wäre da nicht Wills Vergangenheit, die einen Keil zwischen die beiden zu treiben droht. Denn als Will von den Anfängen ihrer Beziehung erzählt und von seinen Versuchen, sich von Layken abzulenken, kommt ungeahnte Eifersucht in Layken auf …', '24.07.2015', 'dtv', ARRAY['Deutsch','Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Layken','Will']::text[], '{}', '{}', 'd5cc27bf-3995-55a6-8c29-334f6526eb18', '3', '{}', 'sheet', :'owner') on conflict do nothing;
