insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('55305d7f-3b6c-51c6-80e0-31b637493aa4', 'Looking for Hope', 'Losing Hope', '9783423716253', 'Dean Holder vermeidet es seit dem Tod seiner Schwester, auf die Vergangenheit zurückzublicken, und arbeitet stattdessen lieber kräftig an seinem Image als Bad Boy. Bis er Sky trifft, die seine Welt von einem Moment auf den anderen aus den Angeln hebt. Denn sie erinnert Dean an seine verschwundene Kindheitsfreundin Hope, nach der er seit Jahren vergeblich sucht. In Skys Gegenwart brechen Gefühle auf, die Dean längst verloren glaubte – doch immer mehr wird klar: Um in die Zukunft blicken zu können, muss Dean sich den Geistern seiner Vergangenheit ebenso stellen wie Sky ...', '01.04.2015', 'dtv', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sky','Dean Holder']::text[], '{}', '{}', '35c28281-e403-575b-822c-2e7fb697e7f9', '2', '{}', 'sheet', :'owner') on conflict do nothing;
