insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8dc5c679-7c6b-54eb-b984-d84840ac7be1', 'Hope Forever', 'Hopeless', '9783423716062', 'Die 17-jährige Sky hatte schon viele Beziehungen, doch nie waren romantische Gefühle im Spiel. Sie befürchtet bereits, dass sie sich niemals verlieben wird. Doch dann wird ihre Welt auf den Kopf gestellt, als sie Dean Holder kennenlernt. Zwischen den beiden knistert es heftig und Sky merkt, dass hinter der rauen Fassade des Bad Boys ein witziger, kluger und sensibler junger Mann steckt. Doch Dean weiß mehr über Sky, als sie ahnt – und mit der Wahrheit tun sich Abgründe auf, die tiefer und dunkler sind, als Sky es sich vorstellen kann. Gemeinsam müssen sie sich der Vergangenheit stellen, damit ihre Liebe eine Zukunft haben kann.', '01.10.2014', 'dtv; Simon & Schuster', ARRAY['Deutsch','Englisch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sky','Dean Holder']::text[], '{}', '{}', '35c28281-e403-575b-822c-2e7fb697e7f9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
