insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9c51b843-b3b7-5a85-b1fd-10fe5552c0d0', 'Too Late', NULL, '9783423790444', 'Asa: Drogendealer, Betrüger, notorischer Frauenheld. Er hat nur eine Schwachstelle: Sloan, seine große Liebe, von der er besessen ist. Carter: Undercover-Cop. Sein Auftrag: Asa zu überführen. Sein Unglück: dass ausgerechnet Sloan die erste Frau ist, in die er sich verliebt. Sloan würde für die, die sie liebt, durch die Hölle und zurück gehen. Und das tut sie, jeden einzelnen Tag. Sich mit dem verführerischen Asa Jackson einzulassen, bedeutet für sie die dringend benötigte finanzielle Sicherheit, auch wenn sie dafür ihre Moral aufgeben muss. Denn Asas Liebe zu ihr ist von einer abgründigen Obsession – und diese wird von Tag zu Tag gefährlicher. Als Carter in Asas Geschäfte eingeschleust wird, fühlt Sloan sich sofort zu ihm hingezogen, obwohl sie weiß, dass Asa ihn umbringen würde, wenn er es herausfindet. Und Asa war schon immer allen in seinem Leben einen Schritt voraus, auch Sloan. Niemand hat sich ihm jemals in den Weg gestellt. Niemand außer Carter. Gemeinsam müssen Sloan und Carter einen Ausweg finden, bevor es zu spät ist.', '22.03.2019', 'dtv', ARRAY['Deutsch']::text[], 419, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Dark Romance']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Asa','Carter','Sloan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
