insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('415a7ba9-c04d-5389-a7bc-57cc548d12a4', 'Forever in Love - Das Beste bist du', 'All Lined Up', '9783802598593', 'COLLEGE, FOOTBALL UND DIE LIEBE! Endlich frei! Dallas Cole kann es kaum erwarten, ihr Studium zu beginnen, fernab von ihrem strengen Vater. Doch gerade hat das Semester angefangen, verkündet dieser ihr, dass er einen anderen Job hat - ausgerechnet an ihrem neuen College, wo er das Football-Team trainieren soll. Dallas ist fassungslos! Ihr einziger Lichtblick ist Carson McClain, dessen attraktives Lächeln sie hoffen lässt, dass es das Schicksal vielleicht ausnahmsweise einmal gut mit ihr meint. Aber Carson ist im Football-Team des Colleges. Und die wichtigste Regel im Football lautet: Fang niemals etwas mit der Tochter deines Trainers an ...', '02.07.2015', 'LYX', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dallas Cole','Carson McClain']::text[], '{}', '{}', 'b8ff67c7-8bd5-5190-96de-ea184483fcac', '1', '{}', 'sheet', :'owner') on conflict do nothing;
