insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2119777a-24a1-5ba6-9eea-29bb39601016', 'Losing it - Alles nicht so einfach', 'Losing It', '9783802594434', 'Bliss Edwards steht kurz vor dem Collegeabschluss und ist immer noch Jungfrau. Um dem abzuhelfen, beschließt sie, sich auf einen One-Night-Stand einzulassen. Im letzten Moment bekommt sie jedoch kalte Füße und lässt den attraktiven Fremden allein im Bett zurück - der sich kurz darauf als ihr neuer College-Dozent entpuppt ...', '09.01.2014', 'LYX', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Bliss Edwards','Garrick']::text[], '{}', '{}', '4a7dfd02-66c3-5bcd-8d01-fe6c07244b8b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
