insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('80b7c3dc-928c-58f3-b905-af92444d04a9', 'Stormheart - Die Rebellin', 'Roar', NULL, 'Blicke dem Sturm in die Seele und finde dein Herz! Von der jungen Königstochter Aurora wird erwartet, dass sie ihre besonderen Fähigkeiten nutzt, um ihr Volk vor den zerstörerischen Stürmen zu schützen. Was keiner weiß: Noch hat Aurora diese Fähigkeiten nicht. Um ihr Geheimnis zu wahren, scheint eine arrangierte Heirat der einzige Ausweg. Doch bevor es dazu kommt, flieht sie aus dem Palast und schließt sich einer Gruppe von Sturmjägern an. Während sie eine ganz besondere Verbindung zu Stürmen findet, läuft sie Gefahr, ihr Herz zu verlieren.', '22.05.2017', 'Oetinger', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Aurora']::text[], '{}', '{}', '28b4e6d9-2048-5da0-84b6-65a0b5ff5659', '1', '{}', 'sheet', :'owner') on conflict do nothing;
