insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('50a9c20a-ade4-59c2-a54e-2c9bf241e06f', 'Faking it - Alles nur ein Spiel', 'Faking It', '9783802596575', 'Max Miller hat ein Problem: Ihre Eltern haben sich zu einem Besuch angekündigt, und all die beschönigenden Halbwahrheiten, die sie ihnen über ihr Leben in Philadelphia erzählt hat, drohen aufzufliegen. Vor allem ihr Freund Mace ist mit seinen Tätowierungen alles andere als vorzeigbar. Da trifft Max den angehenden Schauspieler Cade und bittet ihn, sich ihren Eltern gegenüber als ihr Freund auszugeben. Doch Cade spielt seine Rolle zu gut, und Max weiß schon bald nicht mehr, wo ihr Spiel endet und wo echte Gefühle beginnen ...', '02.10.2014', 'LYX', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Max Miller','Cade']::text[], '{}', '{}', '4a7dfd02-66c3-5bcd-8d01-fe6c07244b8b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
