insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b3dff5a2-6dfa-518c-beed-8cce49728239', 'Forever in Love - Keine ist wie du', 'All Broke Down', '9783802599118', 'Dylan hat eine Schwäche für hoffnungslose Fälle und engagiert sich deshalb in den verschiedensten Protestbewegungen. Bis sie auf einer Demonstration festgenommen wird und für ein paar Stunden im Gefängnis landet. Dort lernt sie Silas Moore kennen, der ganz eigene Probleme hat. Eigentlich ist Silas überhaupt nicht ihr Typ, und doch fasziniert er sie. Als Silas seine Position im Footballteam der Rusk University zu verlieren droht, bietet Dylan ihm ihre Hilfe an. Und die beiden stellen fest, dass sich Gegensätze durchaus anziehen können.', '03.12.2015', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dylan','Silas Moore']::text[], '{}', '{}', 'b8ff67c7-8bd5-5190-96de-ea184483fcac', '2', '{}', 'sheet', :'owner') on conflict do nothing;
