insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bb59c587-3b2d-591a-8367-454a0d4d35dd', 'Finding it - Alles ist leichter mit dir', 'Finding It', '9783802596582', 'Nach ihrem Collegeabschluss erfüllt sich für Kelsey Summers der Traum vieler junger Frauen: Sie darf eine Rundreise durch Europa machen. Doch so sehr sie sich auch bemüht - der Einsamkeit in ihrem Inneren kann sie nicht entkommen. Das ändert sich, als sie dem attraktiven Jackson Hunt begegnet, der ihr anbietet, sie auf ihrer Reise zu begleiten. Jackson weckt Gefühle in Kelsey, die sie noch nie gekannt hat.', '05.03.2015', 'LYX', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kelsey Summers','Jackson Hunt']::text[], '{}', '{}', '4a7dfd02-66c3-5bcd-8d01-fe6c07244b8b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
