insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2710ff7c-512a-5bc6-82d0-1896341c0178', 'Forever in Love - Meine Nummer eins', 'All Played Out', '9783736301641', 'Nur noch wenige Wochen bis zum Abschluss - und Antonella DeLuca wird klar, dass sie ihre Zeit am College vergeudet hat. Zu sehr hat sie sich aufs Lernen konzentriert und dabei ihr Liebesleben völlig vernachlässigt. Doch das wird Nell nun ändern, und zwar mit Hilfe des sexy Footballspielers Mateo Torres. Dieser ist nur zu gern bereit, der hübschen Nell in puncto Lebensgenuss auf die Sprünge zu helfen - auch wenn sie seinen Entschluss, sich niemals fest zu binden, gefährlich ins Wanken bringt.', '01.06.2016', 'LYX', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Antonella DeLuca','Mateo Torres']::text[], '{}', '{}', 'b8ff67c7-8bd5-5190-96de-ea184483fcac', '3', '{}', 'sheet', :'owner') on conflict do nothing;
