insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7047cb06-9de5-5431-b470-ba2a45763a9a', 'Keeping her - Nichts einfacher als das', 'Keeping Her', '9783802596155', 'Die Bonusstory zum E-Book-Bestseller "Losing It - Alles nicht so einfach"! Die Geschichte um Bliss und Garrick geht weiter: Als Garrick ihr einen Heiratsantrag macht, ist Bliss sich sicher, dass ihrem Happy End nichts mehr im Wege steht. Doch leider lässt es sich nicht vermeiden, dass sie vor der Hochzeit Garricks Eltern kennenlernen muss. Und als die beiden nach London reisen, wird ihnen plötzlich klar, dass sie - egal, wie sehr sie sich lieben - für eine gemeinsame Zukunft noch nicht ganz so bereit sind, wie sie ursprünglich dachten', '04.09.2014', 'LYX', ARRAY['Deutsch']::text[], 112, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Bliss Edwards','Garrick']::text[], '{}', '{}', '4a7dfd02-66c3-5bcd-8d01-fe6c07244b8b', '4', '{}', 'sheet', :'owner') on conflict do nothing;
