insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6a852c12-4c94-5a36-a99c-c84d74d75590', 'Seeking her - Nie wieder ohne dich', 'Seeking Her', '9783802599170', 'Die Bonusstory zu Cora Carmacks New Adult-Roman "Finding It - Alles ist leichter mit dir"! Jackson Hunt leidet noch immer unter den Narben, die sein Einsatz als Soldat in Afghanistan auf seiner Seele hinterlassen hat. Da scheint ein neuer Job eine willkommene Abwechslung zu sein - denkt er! Denn den Babysitter (oder wie es in der Stellenbeschreibung heißt: Bodyguard) für die verwöhnte Tochter eines reichen Geschäftsmannes zu spielen ist alles andere als leicht. Doch schnell stellt sich heraus, dass Kelsey Summers ihre ganz eigenen Dämonen hat, gegen die sie kämpft. Dämonen, die Jackson vielleicht für sie besiegen kann ...', '02.04.2015', 'LYX', ARRAY['Deutsch']::text[], 134, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kelsey Summers','Jackson Hunt']::text[], '{}', '{}', '4a7dfd02-66c3-5bcd-8d01-fe6c07244b8b', '5', '{}', 'sheet', :'owner') on conflict do nothing;
