insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('befb89bf-ef14-5a6e-9fb8-6e3004cf52e1', 'Tintenherz', NULL, '9783791504650', 'In einer stürmischen Nacht bekommen Meggie und ihr Vater, der Buchbinder Mo, Besuch von einem unheimlichen Gast, der Mo vor einem Mann namens Capricorn warnt. Am nächsten Morgen reisen Mo und Meggie zu Tante Elinor, die über eine sehr kostbare Bibliothek verfügt. Hier versteckt Mo jenes Buch, das im Mittelpunkt eines unglaublichen, magischen und atemberaubenden Abenteuers steht. Ein Abenteuer, in dessen Verlauf Meggie das Geheimnis um Zauberzunge und Capricorn löst und auch selbst in große Gefahr gerät. Furioser Auftakt der Tintenwelt-Reihe von Cornelia Funke, die es längst zu Weltruhm gebracht hat', '01.08.2003', 'Dressler', ARRAY['Deutsch']::text[], 567, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Maggie','Mo']::text[], '{}', '{}', '27f2295a-643d-5c33-a44c-dc9d0d8cd09a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
