insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('324d6ba9-d88c-5453-a4b9-68519126591e', 'Tintenblut', NULL, '9783791504674', 'Eigentlich könnte alles so friedlich sein. Doch der Zauber von "Tintenherz" lässt Meggie nicht los. Und eines Tages ist es so weit: Gemeinsam mit Farid geht Meggie in die Tintenwelt, denn sie will den Weglosen Wald sehen, den Speckfürsten, den Schönen Cosimo, den Schwarzen Prinzen und seine Bären. Sie möchte die Feen treffen und natürlich Fenoglio, der sie später zurückschreiben soll. Vor allem aber will sie Staubfinger warnen, denn auch der grausame Basta ist nicht weit.', '01.09.2005', 'Dressler', ARRAY['Deutsch']::text[], 736, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tintenwelt', '{}', ARRAY['Maggie','Mo']::text[], '{}', '{}', '27f2295a-643d-5c33-a44c-dc9d0d8cd09a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
