insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cee4f44b-8421-5c58-a308-3179d47d6d9c', 'Tintentod', NULL, '9783791504766', 'Die Weißen Frauen haben Staubfinger mit sich genommen. Meggie lebt mit ihren Eltern auf einem verlassenen Hof in den Hügeln östlich von Ombra, wo sich beinahe vergessen lässt, was auf der Nachtburg geschehen ist. Doch in der Dunkelheit, wenn Meggie am Fenster steht und auf Farid wartet, hört sie den Eichelhäher schreien. Dann verschwindet ihr Vater mit dem Schwarzen Prinzen und dem Starken Mann im Wald, denn es muss alles getan werden, damit die Schatten über Ombra weichen. Noch einmal nimmt Cornelia Funke ihre Leserinnen und Leser mit auf eine Reise voller Gefahren, wilder Schönheiten und magischer Fantasie – möge diese Reise niemals enden.', '28.10.2007', 'Dressler', ARRAY['Deutsch']::text[], 768, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tintenwelt', '{}', ARRAY['Maggie','Mo']::text[], '{}', '{}', '27f2295a-643d-5c33-a44c-dc9d0d8cd09a', '3', '{}', 'sheet', :'owner') on conflict do nothing;
