insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cffef36c-a612-5cc3-997e-5f9bb1cb1f62', 'Reckless - Steinernes Fleisch', NULL, '9783791504858', 'Obwohl Jacob Reckless stets darauf geachtet hat, die Welt hinter dem Spiegel vor seinem Bruder Will geheim zu halten, ist dieser ihm gefolgt und gerät in tödliche Gefahr: Will wird von einem Goyl angegriffen und beginnt, zu Jade zu versteinern. Allein die Feen besitzen die Macht, das Steinerne Fleisch aufzuhalten. Dennoch versucht Jacob verzweifelt, seinen Bruder zu retten. Gemeinsam mit Clara, Wills großer Liebe, und der Gestaltwandlerin Fuchs begibt Jacob sich auf die gefährliche Reise.', '14.09.2010', 'Dressler', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Welt hinter dem Spiegel', '{}', ARRAY['Jacob Reckless']::text[], '{}', '{}', '1edc9958-efb3-537b-937c-24b457c82305', '1', '{}', 'sheet', :'owner') on conflict do nothing;
