insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5415c070-be8d-5b54-8e51-28f282c5caf8', 'Das Labyrinth des Fauns', NULL, '9783733651886', 'Spanien, 1944: Ofelia zieht mit ihrer Mutter in die Berge, wo ihr neuer Stiefvater stationiert ist. Für den grausamen Hauptmann ist der dichte Wald lediglich ein Versteck für untergetauchte Widerstandskämpfer. Für Ofelia wird er eine Zufluchtsstätte vor dem unbarmherzigen Stiefvater: ein Königreich voller verzauberter Orte und magischer Wesen. Ein geheimnisvoller Faun stellt dem Mädchen drei Aufgaben. Besteht sie diese, ist sie die lang gesuchte Prinzessin des Reiches. Immer tiefer wird Ofelia in eine phantastische Welt hineingezogen, die wundervoll ist und grausam zugleich. Kann Unschuld über das Böse siegen?', '02.07.2019', 'Fischer', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Spanien', '{}', ARRAY['Ofelia']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
