insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ea513154-e6f8-5492-a1b4-d2050ed5bb2b', 'Meteor', 'Deception Point', '9783838705934', 'Als die NASA mithilfe modernster Satelliten-Technologie in der Arktis eine sensationelle Entdeckung macht, wittert die angeschlagene Raumfahrtbehörde Morgenluft. Tief im Eis verborgen liegt ein Meteorit von ungewöhnlicher Größe, der zudem eine außerirdische Lebensform zu bergen scheint. Rachel Sexton, Mitarbeiterin des Geheimdienstes, reist im Auftrag des US-Präsidenten zum Fundort des Meteoriten. Doch es gibt eine Macht im Hintergrund, die die bahnbrechende Entdeckung unter Verschluss halten möchte - und die bereit ist, dafür zu töten ...', '29.10.2010', 'Lübbe', ARRAY['Deutsch']::text[], 637, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'USA, Arktis', '{}', ARRAY['Rachel Sexton']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
