insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('519da59a-791b-5b0b-9403-12f8269e0c17', 'Illuminati', 'Angels and Demons', '9783838705927', 'Die Illuminati sind zurück... Ein Kernforscher wird in seinem Schweizer Labor ermordet aufgefunden. Auf seiner Brust finden sich merkwürdige Symbole eingraviert, Symbole, die nur der Harvardprofessor Robert Langdon zu entziffern vermag. Was er dabei entdeckt, erschreckt ihn zutiefst: Die Symbole gehören zu der legendären Geheimgesellschaft der Illuminati. Diese Gemeinschaft scheint wieder zum Leben erweckt zu sein, und sie verfolgt einen finsteren Plan, denn aus dem Labor des ermordeten Kernforschers wurde Antimaterie entwendet.', '25.02.2023', 'Lübbe', ARRAY['Deutsch']::text[], 731, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Schweiz', '{}', ARRAY['Robert Langdon']::text[], '{}', '{}', '536dcc1b-6e69-5d09-b5ef-9972d9b3eda4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
