insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bfba76e6-f6ee-54d9-a42b-8ccff7a659c6', 'Sakrileg - The Da Vinci Code', 'The Da Vinci Code', '9783838705910', 'Robert Langdon, Symbologe aus Harvard, befindet sich aus beruflichen Gründen in Paris, als er einen merkwürdigen Anruf erhält: Der Chefkurator des Louvre wurde mitten in der Nacht vor dem Gemälde der Mona Lisa ermordet aufgefunden. Langdon begibt sich zum Tatort und erkennt schon bald, dass der Tote durch eine Reihe von versteckten Hinweisen auf die Werke Leonardo da Vincis aufmerksam machen wollte – Hinweise, die seinen gewaltsamen Tod erklären und auf eine finstere Verschwörung deuten. Bei seiner Suche nach den Hintergründen der Tat wird Robert Langdon von Sophie Neveu unterstützt, einer Kryptologin der Pariser Polizei und Enkeltochter des ermordeten Kurators. Eine aufregende Jagd beginnt ..', '08.04.2026', 'Lübbe', ARRAY['Deutsch']::text[], 624, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Paris', '{}', ARRAY['Robert Langdon']::text[], '{}', '{}', '536dcc1b-6e69-5d09-b5ef-9972d9b3eda4', '2', '{}', 'sheet', :'owner') on conflict do nothing;
