insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('907b5741-f60a-5cae-baa6-b75a410a3886', :'owner', '6b3acdc0-0ec0-5784-b44f-c59dbf35cdda', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1199, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, 0, 'no'::burn_kind, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('69a9f7a1-f71d-5d7b-84b0-90756631c6a3', 'Inferno', NULL, '9783838730264', 'Robert Langdon, Harvard-Professor für Symbologie, erwacht mit einer Schusswunde in einem Krankenhaus in Florenz und kann sich nicht an die letzten zwei Tage erinnern. Doch viel Zeit zur Erholung bleibt ihm nicht, denn nach einem Anschlag muss er mit der jungen Ärztin Sienna Brooks in deren Wohnung flüchten. Dort stellt sich heraus, dass Langdon dabei war, die versteckte Botschaft in einem jahrhundertealten Gemälde zu Dantes "Inferno" zu entschlüsseln. Die Spur führt sie in den Palazzio Vecchio, wo sie sich von Dantes Totenmaske konkretere Hinweise erhoffen, doch diese ist gestohlen worden. Nun beginnt eine Jagd durch halb Europa, bei der Langdon die Maske wiederfinden und einen perfiden Plan vereiteln muss.', '14.05.2013', 'Lübbe', ARRAY['Deutsch']::text[], 688, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Florenz', '{}', ARRAY['Robert Langdon']::text[], '{}', '{}', '536dcc1b-6e69-5d09-b5ef-9972d9b3eda4', '4', '{}', 'sheet', :'owner') on conflict do nothing;
