insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('57d959ab-7e67-5c02-98f1-436c8e5f0134', :'owner', '69a9f7a1-f71d-5d7b-84b0-90756631c6a3', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1199, true, true, '{}', '{}', NULL, NULL, true, NULL, NULL, NULL, NULL, 0, 'no'::burn_kind, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2689c7f0-d3b2-5087-8d70-bc99eaee2f14', 'Origin', NULL, '9783732542215', 'Als der Milliardär und Zukunftsforscher Edmond Kirsch drei der bedeutendsten Religionsvertreter der Welt um ein Treffen bittet, sind die Kirchenmänner zunächst skeptisch. Was will ihnen der bekennende Atheist mitteilen? Was verbirgt sich hinter seiner "bahnbrechenden Entdeckung", das Relevanz für Millionen Gläubige auf diesem Planeten haben könnte? Nachdem die Geistlichen Kirschs Präsentation gesehen haben, verwandelt sich ihre Skepsis in blankes Entsetzen. Die Furcht vor Kirschs Entdeckung ist begründet. Und sie ruft Gegner auf den Plan, denen jedes Mittel recht ist, ihre Bekanntmachung zu verhindern. Doch es gibt jemanden, der unter Einsatz des eigenen Lebens bereit ist, das Geheimnis zu lüften und der Welt die Augen zu öffnen: Robert Langdon, Symbolforscher aus Harvard, Lehrer Edmond Kirschs und stets im Zentrum der größten Verschwörungen.', '31.08.2018', 'Lübbe', ARRAY['Deutsch']::text[], 672, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Robert Langdon']::text[], '{}', '{}', '536dcc1b-6e69-5d09-b5ef-9972d9b3eda4', '5', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('2a7cd02d-5852-52dd-bb21-8ef829e05bc1', :'owner', '2689c7f0-d3b2-5087-8d70-bc99eaee2f14', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1199, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, 0, 'no'::burn_kind, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('02c2ad7e-c26a-559e-bb6e-91e98c004351', 'The Secret of Secrets', NULL, '9783751784979', 'Robert Langdon, Symbolforscher aus Harvard, begleitet seine Freundin Katherine Solomon nach Prag. Katherine bereitet die Veröffentlichung eines Buches vor, das bahnbrechende Entdeckungen über die wahre Natur des menschlichen Bewusstseins offenbart. Doch ein brutaler Mord stürzt die Reise in ein unvorhersehbares Chaos, und Katherine verschwindet plötzlich, ebenso ihr Manuskript. Langdon sieht sich fortan einer mächtigen Organisation gegenüber und wird von einem unheimlichen Angreifer verfolgt, der aus Prags ältester Mythologie entsprungen zu sein scheint und nur ein Ziel verfolgt: gnadenlose Rache.', '09.09.2025', 'Lübbe', ARRAY['Deutsch']::text[], 800, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Prag', '{}', ARRAY['Robert Langdon']::text[], '{}', '{}', '536dcc1b-6e69-5d09-b5ef-9972d9b3eda4', '6', '{}', 'sheet', :'owner') on conflict do nothing;
