insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2bad35d6-a8e8-5c18-afdc-eeb925b3289b', 'No Love Zone (Vol.1)', '연애제한구역', '9783910530645', 'Von wegen Office Romance! Wenn es um Liebe geht, ist Eun-Gyeom der größte Pechvogel der Welt. Als er sich also auf den ersten Blick in einen fremden Mann in der Bahn verliebt, ist klar, dass das nicht gutgehen kann. Denn der Fremde entpuppt sich als Jihyuk Han, sein neuer Teamleiter bei der Arbeit! Und aus irgendeinem Grund hat er es auf Eun-Gyeom abgesehen und schikaniert ihn nun nonstop! Was Eun-Gyeom nicht ahnt: nichts passiert ohne Grund – und dies ist nicht ihre erste Begegnung …', '13.11.2023', 'Papertoons', ARRAY['Deutsch']::text[], 304, 4, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Korea', ARRAY['3P Objective']::text[], ARRAY['Eun-Gyeom','Jihuk Han']::text[], ARRAY['Queer','Work Adversaries']::text[], ARRAY['Dub-Con/Non-Con']::text[], '6b5152ad-9c19-5389-a140-b2ac66471500', '1', '{}', 'sheet', :'owner') on conflict do nothing;
