insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7cf66ac7-2279-59b6-93eb-0f4655264cd1', 'No Love Zone (Vol.2)', '연애제한구역', '9783910530652', 'Eun-Gyeom hat endlich herausgefunden, warum Jihyuk ihn bei der Arbeit ständig schikaniert: Als die beiden noch Schüler waren, hatte Jihyuk ihm seine Liebe gestanden – und Eun-Gyeom hatte ihn eiskalt abblitzen lassen! Jetzt hat Jihyuk den Spieß umgedreht und Eun-Gyeom eine Abfuhr erteilt. Trotzdem lässt ihm die Sache keine Ruhe. Als die beiden nach einem Abend mit den Kollegen betrunken miteinander im Bett landen, muss er sich eingestehen, dass er immer noch Gefühle für Eun-Gyeom hat. Aber der will nun nichts mehr von Liebe hören …', '15.01.2024', 'Papertoons', ARRAY['Deutsch']::text[], 304, 4, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Korea', ARRAY['3P Objective']::text[], ARRAY['Eun-Gyeom','Jihuk Han']::text[], ARRAY['Queer','Work Adversaries']::text[], ARRAY['Dub-Con/Non-Con']::text[], '6b5152ad-9c19-5389-a140-b2ac66471500', '2', '{}', 'sheet', :'owner') on conflict do nothing;
