insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('db0ae175-7a97-55c3-b187-0af537ed57ba', 'No Love Zone (Vol.3)', '연애제한구역', '9783910530669', 'Nachdem Jihyuk ihm seine Gefühle gestanden hat, erklärt Eun-Gyeom sich bereit, sein Sexpartner zu sein – eine Beziehung kann er jedoch vergessen! Eun-Gyeom freut sich, dass er nun die Oberhand hat, und will dies auszunutzen, so gut es geht. Die beiden verbringen immer mehr Zeit miteinander, doch dann muss Jihyuk plötzlich auf Geschäftsreise und hinterlässt eine Leere in Eun-Gyeom. Ist Sex wirklich alles, was er von Jihyuk will …?', '11.03.2024', 'Papertoons', ARRAY['Deutsch']::text[], 304, 4, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Korea', ARRAY['3P Objective']::text[], ARRAY['Eun-Gyeom','Jihuk Han']::text[], ARRAY['Queer','Work Adversaries']::text[], ARRAY['Dub-Con/Non-Con']::text[], '6b5152ad-9c19-5389-a140-b2ac66471500', '3', '{}', 'sheet', :'owner') on conflict do nothing;
