insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('060ce5cc-963d-52a2-8284-875522fb7098', 'No Love Zone (Vol.4)', '연애제한구역', '9783910530676', 'Eun-Gyeom ist klargeworden, dass auch er Gefühle für Jihyuk hegt, und die beiden werden endlich ein richtiges Paar. Eun-Gyeom kann sein Liebesglück kaum fassen – so fühlt sich also eine Beziehung an, die auf Zweiseitigkeit beruht! Doch bei der Arbeit will es für Eun-Gyeom immer noch nicht rund laufen, denn nun hat ein anderer Kollege ihn auf dem Kieker. Und zu allem Überfluss taucht auch noch sein Ex-Freund wieder auf …', '13.05.2025', 'Papertoons', ARRAY['Deutsch']::text[], 304, 4, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Korea', ARRAY['3P Objective']::text[], ARRAY['Eun-Gyeom','Jihuk Han']::text[], ARRAY['Queer','Work Adversaries']::text[], ARRAY['Dub-Con/Non-Con']::text[], '6b5152ad-9c19-5389-a140-b2ac66471500', '4', '{}', 'sheet', :'owner') on conflict do nothing;
