insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('27d273b6-f927-5a63-ab40-89f46688f54c', '78267207-a0d6-5307-82f2-954240b4e2bd', :'owner', 1, '2026-06-29', '2026-06-29', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6a9c17d4-0493-51d2-9665-4fd803d1cd70', 'Broken Dove', NULL, '9783736323704', 'Als Rebellin wurde Wren Darlington in die Silver-Elite eingeschleust. Nachdem ihre Tarnung aufgeflogen ist, findet sie Zuflucht in der Festung von Uprising, dem Rebellen-Netzwerk jener Modifizierten, zu denen sie selbst gehört. Wieder unter ihresgleichen konzentriert sie sich darauf, endlich ihren Platz im Widerstand einzunehmen. Währenddessen kämpft Cross Redden, ihr Geliebter und ehemaliger Kommandant, tief im Feindesgebiet weiter darum, das Regime von innen heraus zu zerschlagen. Doch Wren spürt, dass er etwas vor ihr verheimlicht. Als dann plötzlich jemand, der ihr einst so nah stand wie kaum jemand sonst, überraschend wieder in ihr Leben tritt, gerät für sie alles ins Wanken. Während der Kontinent am Rande eines entscheidenden Krieges steht, muss Wren sich fragen: Für wen ist sie bereit zu kämpfen - selbst wenn das bedeutet, jemanden dabei zu verlieren?', '29.06.2026', 'LYX; Cornerstone', ARRAY['Deutsch','Englisch']::text[], 674, 62, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, 'Der Kontinent', ARRAY['Single POV','1P']::text[], ARRAY['Wren Darlington','Cross Redden']::text[], ARRAY['Love Triangle','Enemies to Lovers']::text[], ARRAY['Kriegsszenarien','Mord','Physische Gewalt','Tod von Familienangehörigen','Folter','Sexuelle Gewalt','Suizidalität','Krankheit','Ableismus']::text[], 'e62ae929-7311-54dd-8a12-73d31a0ee973', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('abe20b4c-6350-51ab-98e6-86a123ee9654', :'owner', '6a9c17d4-0493-51d2-9665-4fd803d1cd70', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook','Print']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', ARRAY['Map']::text[], 1499, false, false, ARRAY['Spotify','Audible']::text[], ARRAY['Amanda Dolan','Teddy Hamilton']::text[], 1305, '👍🏻', false, 'buddy'::company_kind, 'hate'::verdict_kind, 1.5, 'untertroffen'::expectation_kind, 2, 'slow'::burn_kind, 'Ich weiß nicht, ob ich einfach nicht mehr die Zielgruppe bin, aber ich kann die guten Bewertungen zu diesem Buch einfach nicht verstehen. Ich hasse die Hauptcharakterin, alle anderen Charaktere fehlt es an Tiefe, einfach nur langweilig und eine Ansammlung an unnötigen Szenen. Und warum müssen alle Frauen in diesem Buch eifersüchtige Ziegen sein?? Triangle ist es auch nicht, weil Cross in diesem Buch einfach NICHT vorkommt abgesehen von dem ersten Kapitel und dem letzten. Ne... hat mich leider gar nicht überzeugt.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('407d4411-bf59-5163-aeeb-0517b63a8a74', 'abe20b4c-6350-51ab-98e6-86a123ee9654', :'owner', 1, '2026-06-14', '2026-06-21', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8eee4dd2-a6a1-54d5-97aa-5687b1ae4450', 'Silver Elite', NULL, '9783736323698', 'Wren Darlington hat ihr gesamtes Leben im Verborgenen verbracht. Sie unterstützt das Rebellen-Netzwerk Uprising, das seit Beginn der Neuen Ära Widerstand gegen General Redden leistet. Gleichzeitig muss sie ihre telepathischen Fähigkeiten verstecken. Denn auf dem Kontinent zu den Modifizierten mit übernatürlichen Kräften zu gehören, bedeutet den sicheren Tod. Aber dann gerät Wren in die Fänge der Company und soll im Trainingsprogramm der Silver-Elite ausgebildet werden - ihr schlimmster Albtraum, und vielleicht auch die einzige Chance das Regime endlich zu stürzen! Doch ihr Vorgesetzter ist niemand Geringeres als Captain Cross Redden, der misstrauische und viel zu attraktive Sohn des Generals, der den Auftrag hat, Wren nicht aus den Augen zu lassen ...', '16.09.2025', 'LYX', ARRAY['Deutsch']::text[], 665, 55, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, 'Der Kontinent', ARRAY['Single POV','1P']::text[], ARRAY['Wren Darlington','Cross Redden']::text[], ARRAY['Enemies to Lovers','Forbidden Love','Academy','Rivals to Lovers']::text[], ARRAY['Kriegsszenarien','Mord','Physische Gewalt','Tod von Familienangehörigen','Folter','Sexuelle Gewalt','Suizidalität','Krankheit','Ableismus']::text[], 'e62ae929-7311-54dd-8a12-73d31a0ee973', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('e8432633-ee6b-5d11-a375-c3ef558342d8', :'owner', '8eee4dd2-a6a1-54d5-97aa-5687b1ae4450', 'gelesen'::reading_status, true, false, ARRAY['Digital','Print','Audiobook']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', ARRAY['Sprayed Edges','Map']::text[], 1499, true, false, ARRAY['BookBeat']::text[], ARRAY['Vanida Karun']::text[], 1131, '👎🏻', false, 'buddy'::company_kind, 'like'::verdict_kind, 3.5, 'untertroffen'::expectation_kind, 3, 'slow'::burn_kind, 'Also das Buch war gut, aber auch leider nicht zu gut. Leider ist mir zwischenzeitlich zu wenig passier tund es wurde zu viel drauf herumgeritten, dass sie erst ihre Fähigkeiten verschleiert und dann doch ne Angeberin ist. Auch die Verbindung zwischen Cross und ihr war mir nicht tief genug, bis irgendwann klar wurde, dass er Wolf ist. Vorher hatten sie halt iwie keine wirklich tiefen Momente miteinander. Das Ende hat mich aber auf jeden Fall überrascht. Genervt hat mich noch, dass Whren einfach nur massiv naiv und unbesonnen ist. Ständig handelt sie ohne nachzudenken. Das ist dem Buch zwar bewusst, aber mich hat es einfach genervt.') on conflict do nothing;
