insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7913cc3e-354b-59b4-b4e0-a364474d62da', 'A Fate Inked in Blood', NULL, '9781529918700', 'Trapped in an unwanted marriage, Freya dreams of becoming a warrior – and of putting an axe in her controlling husband’s back. But those dreams become a nightmare when he makes a deal with their fanatical ruler, and she’s forced into a fight to the death. To survive, she must reveal her deepest secret: she possesses a drop of a goddess’s blood and magic that will unite their nation beneath the one who controls her fate. Believing he’s destined to be king, the ruler binds Freya with a blood oath and orders his fierce but charming son to train her to fight, to control her magic . . . and to make sure no one lays a hand on her. But the greatest test of all may be resisting her forbidden attraction to the son of her enemy.', '27.02.2024', 'Fairyloot', ARRAY['Englisch']::text[], 409, 36, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Freya']::text[], '{}', '{}', 'dca7458d-e2b6-5765-9592-36ad1c0afe4e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
