insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('29189da6-7f90-55d5-9eea-bf5ca0adff7f', 'Auf den ersten Blick', 'Charlotte Street', '9783453410787', 'Gibt es Liebe auf den ersten Blick? Jason glaubt nicht daran. Ganz im Gegenteil, seitdem ihn seine letzte Freundin verlassen hat, sieht er in Sachen Liebe schwarz. Bis er eines Tages einer jungen Frau beim Einsteigen in ein Taxi hilft. Sie schaut ihn an, und bei Jason macht es klick. Doch bevor er auch nur ein Wort herausbringt, ist das Taxi weg. Zurück bleibt eine Einwegkamera mit zwölf Fotos. Jason zögert, doch dann lässt er die Bilder entwickeln und macht sich mithilfe seines Kumpels Dev auf die Suche nach der Unbekannten. Eine witzige und hinreißend romantische Odyssee durch London beginnt.', '13.01.2014', 'Heyne', ARRAY['Deutsch']::text[], 493, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Comedy']::text[], NULL, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Jason']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
