insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('11f5837e-820f-540b-a621-244f9441ed41', 'Puerta Oscura - Totenreise', 'La puerta oscura - El viajero', '9783785568637', 'Eigentlich ist Pascal nur wegen Michelle zu der Gothic-Party in die Pariser Wohnung der Familie Marceaux gekommen. Doch bei der Suche nach passenden Klamotten für seine Kostümierung findet er in einer alten Truhe die Puerta Oscura, den geheimen Zugang zum Reich der Toten. Nur alle 100 Jahre, in der Nacht zu Allerheiligen, wird die Pforte geöffnet und gestattet einem einzelnen Wanderer den Eintritt in die Unterwelt. Aber das Gleichgewicht zwischen dem Totenreich und unserer Welt ist fragil. Wann immer ein Lebender in das Totenreich geht, gelangt ein Wesen aus der Unterwelt in die Wirklichkeit. Pascal hat einen Vampir befreit, der nun Michelle entführt, und sie in den tiefsten Winkeln der Hölle verstecken lässt. Zögernd, und nur mit einem magischen Medaillon bewaffnet, begibt sich Pascal erneut in das Reich der Toten. Er hat nur sieben Tage Zeit. Und die vergehen schnell - in der Ewigkeit!', '01.06.2010', 'Loewe', ARRAY['Deutsch']::text[], 607, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], NULL, NULL, NULL, '{}', ARRAY['Pascal']::text[], '{}', '{}', 'bd99b346-ee6f-50f6-81a4-8917a5f2ddcb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
