insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cb053a8b-b984-579e-b6f3-d980c0af9ef0', 'Der Wolkenatlas', 'Cloud Atlas', NULL, 'Sechs Lebenswege, die sich unmöglich kreuzen können: darunter ein amerikanischer Anwalt, der um 1850 Ozeanien erforscht, ein britischer Komponist, der 1931 vor seinen Gläubigern nach Belgien flieht, und ein koreanischer Klon, der in der Zukunft wegen des Verbrechens angeklagt wird, ein Mensch sein zu wollen. Und dennoch sind diese Geschichten miteinander verwoben. Mitchells originelle Menschheitsgeschichte katapultiert den Leser durch Räume, Zeiten, Genres und Erzählstile und liest sich dabei so leicht und fesselnd wie ein Abenteuerroman.', '01.11.2012', 'Rowohlt', ARRAY['Deutsch']::text[], 672, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['Multiple POV']::text[], ARRAY['Adam Ewing','Robert Frobisher','Luisa Rey','Rufus Sixsmith','Timothy Cavendish','Sonmi','Zachry','Hae-Jo','Vyvyan Ayrs','Jocasta','...']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
