insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ace2f7ae-2686-5270-b4c9-1788a82efb2b', 'Chaos', 'Ghostwritten', '9783644043817', 'Ein japanischer Sektierer verübt einen Giftgasanschlag auf die U-Bahn. Doch was verbindet ihn mit dem Jazzfan in einem Tokioter Plattenladen? Eine Frau auf einem heiligen Berg in China spricht mit einem Baum, ohne zu ahnen, wie sich gewisse illegale Börsengeschäfte in Hongkong auf ihr Leben auswirken werden. Ein mongolischer Gangster, ein Kunstfälscher in St. Petersburg, ein Nuklearwissenschaftler in Irland, ein New Yorker Late-Night-DJ und ein mysteriöser Ghostwriter - alle tragen zu dieser Geschichte bei.', '02.06.2014', 'Rowohlt', ARRAY['Deutsch']::text[], 573, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
