insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('51f598c0-a4de-5110-8899-6364232a45fa', 'Der dreizehnte Monat', 'Black Swan Green', '9783644044012', 'Der dreizehnjährige Jason Taylor steht vor einem Jahr voller Herausforderungen in dem verschlafenen englischen Dorf Black Swan Green. Der heimliche Stammler und zögernde Poet muss sich nicht nur mit Schulschwänzern herumschlagen, die ihm das Leben schwer machen, sondern auch mit Familienzwist, einer rätselhaften belgischen Immigrantin und den Wirren des Falklandkriegs. Und dann sind da noch diese geheimnisvollen Wesen namens Mädchen, die Jasons Welt gehörig auf den Kopf stellen.', '03.06.2014', 'Rowohlt', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Black Swan Green', '{}', ARRAY['Jason Taylor']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
