insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2ae6531f-a199-5ee1-97df-aca23846d739', 'Die Knochenuhren', 'The Bone Clocks', '9783644047211', 'An einem verschlafenen Sommertag des Jahres 1984 begegnet die junge Holly Sykes einer alten Frau, die ihr im Tausch für «Asyl» einen kleinen Gefallen tut. Jahrzehnte werden vergehen, bis Holly Sykes genau versteht, welche Bedeutung die alte Frau dadurch für ihre Existenz bekommen hat.', '11.03.2016', 'Rowohlt', ARRAY['Deutsch']::text[], 799, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Großbritannien', '{}', ARRAY['Holly Sykes']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
