insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e8234abb-96a1-55b0-b1a0-c24fe83e300c', 'Die tausend Herbste des Jacob Zoet', 'The Thousand Autumns of Jacob de Zoet', '9783644044715', 'Im Jahr 1799 erreicht der junge holländische Kaufmann Jacob de Zoet die Insel Dejima, den einzigen europäischen Handelsposten im hermetisch abgeriegelten Japan. Auf der von Geschäftemachern und zwielichtigen Gestalten bevölkerten künstlichen Insel hofft er, sein Glück zu machen und dem niederländischen Kolonialismus zu dienen. Doch als er sich in eine geheimnisvolle Japanerin verliebt, eröffnet sich ihm unversehens eine fremde Welt voller Schönheit und Schrecken.', '02.06.2014', 'Rowohlt', ARRAY['Deutsch']::text[], 701, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Dejima', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
