insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bd06a94f-ddd0-55cc-9cbc-6e44d73a784e', 'Number 9 Dream', 'Number 9 Dream', '9783644043916', 'Der neunzehnjährige Träumer Eiji Miyake kommt aus dem ländlichen Japan nach Tokio, um seinen Vater zu suchen, der die Familie früh verlassen hat. Während er in der faszinierenden großen Stadt herumirrt, gerät er in Berührung mit den Kräften, die ihre geheime Unterwelt beherrschen: Yakuza-Gangs und Cyberpunks. Plötzlich ist das Rätsel der Identität seines Vaters nur noch eines von vielen, die er lösen muss. Warum ist die Grenze zwischen der Welt seiner Erfahrungen und der seiner Träume so verschwommen? Und was hat es mit dem Geheimnis der Zahl 9 auf sich? Diese Fragen verlangen Eiji Einsichten ab, die jedem schwerfielen, erst recht einem Jungen vom Lande, der weniger Geld in der Tasche hat, als das titelgebende Album mit dem Lennon-Song kostet.', '02.06.2014', 'Rowohlt', ARRAY['Deutsch']::text[], 521, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, NULL, 'Tokio', '{}', ARRAY['Eiji Miyake']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
