insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('75fe8495-4337-5596-94dc-79d33a5a331d', 'Die Seelen der Nacht', 'A Discovery of Witches', '9783764503918', 'Diana Bishop ist Historikerin mit Leib und Seele. Dass in ihr zudem das Blut eines uralten Hexengeschlechts fließt, versucht sie im Alltag mit aller Kraft zu ignorieren. Doch als Diana in der altehrwürdigen Bodleian-Bibliothek in Oxford ein magisches Manuskript in die Hände fällt, kann sie ihre Herkunft nicht länger verleugnen: Hexen, Dämonen und Vampire heften sich an ihre Fersen, um ihr das geheime Wissen zu entlocken – wenn nötig mit Gewalt. Hilfe erfährt Diana ausgerechnet von Matthew Clairmont, Naturwissenschaftler, 1500 Jahre alter Vampir – und der Mann, der Diana bald schon mehr bedeuten wird als ihr eigenes Leben …', '26.09.2011', 'blanvalet', ARRAY['Deutsch']::text[], 832, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], NULL, NULL, 'Oxford', '{}', ARRAY['Diana Bishop']::text[], '{}', '{}', 'fe024fe8-a50d-56ee-8b6e-7324e6a817be', '1', '{}', 'sheet', :'owner') on conflict do nothing;
