insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17f96cd8-9d55-5de9-83f4-d5ace635d611', 'Swimming in Light', 'Stealing the Stars', '9783736316973', 'Ruffian will nur eins: seiner verstorbenen Mutter ein Denkmal setzen, indem er die obdachlosen Menschen, um die sie sich gekümmert hat, aus der bitteren Armut befreit. Dafür ist er sogar bereit, das Gesetz zu brechen und ins Gefängnis zu gehen. Als es ihm gelingt, sich in die Kreise der wohlhabenden Gesellschaft einzuschleichen, trifft er auf ein unerwartetes Hindernis: Teddi Burathon und ihre liebevolle Familie. Ein Kuss ist genug, um zu begreifen, dass Teddi die Eine für Ruffian ist. Aber um seinen Plan durchzuziehen, muss er sie belügen, ganz gleich, wie sehr sein Herz dabei blutet. Doch er hat nicht mit Teddis Entschlossenheit gerechnet, ihn vor sich selbst zu beschützen und für ihre Liebe zu kämpfen ...', '25.03.2022', 'LYX', ARRAY['Deutsch']::text[], 525, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ruffian','Teddi Burathon']::text[], '{}', '{}', '6dc5dcba-b802-5956-ab7a-4b035d277cbf', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('600fde18-4223-5912-b0c3-79831fbb6533', :'owner', '17f96cd8-9d55-5de9-83f4-d5ace635d611', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3ebad90c-1ebf-5a47-bedd-f873f1ec63ef', 'Drowning in Stars', NULL, '9783736316676', 'Das Leben war nie einfach für Pixie und Gaze. Pixies Mutter ist nur selten zu Hause, Gaze’ Vater trinkt zu viel. Aber sie haben einander - und für Gaze war eins von Anfang an klar: Pixie ist die Eine. Sie hat ihn beschützt, als er neu im Viertel war. Ohne einander wären sie untergegangen. Sie haben sich versprochen, immer zusammenzubleiben. Doch eines Tages muss sich Pixie entscheiden: für ihr Versprechen oder für Gaze’ Leben. Als sie sich Jahre später wiedertreffen, ist es Gaze, der für sie beide stark sein muss. Denn nur wenn Pixie sich von ihren Dämonen befreien kann, hat ihre Liebe eine Chance ...', '23.12.2021', 'LYX', ARRAY['Deutsch']::text[], 452, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Pixie','Gaze']::text[], '{}', '{}', '6dc5dcba-b802-5956-ab7a-4b035d277cbf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
