insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('15b6cd65-f290-58a4-979f-82a7b3a4a9da', 'Ghost Hunter - Das Licht, das tötet', NULL, NULL, 'Ian ist 17 Jahre alt, als er eine unglaubliche Entdeckung macht: Er kann Geister sehen, die alles, was sie berühren, verbrennen. Durch Zufall erfährt er, dass auch sein Vater die mysteriösen Lichtwesen sah. Sind die Geister gar schuld am Tod seines Vaters oder am Verschwinden seines Großvaters, der seit 1967 als verschollen gilt? Gemeinsam mit seinem besten Freund Bpm beschließt er, das Geheimnis zu lüften. Ian ahnt nicht, dass sein Vater ein gefährliches Doppelleben führte - und dass sein Schicksal eng mit dem der 19-jährigen Chiyo aus Tokio verknüpft ist. Doch während Chiyo auf der Flucht vor der Polizei ist, liefern sich Bpm und Ian eine wilde Verfolgungsjagd mit zwei Killern.', '23.02.2009', 'Loewe', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], NULL, NULL, NULL, '{}', ARRAY['Ian']::text[], '{}', '{}', '10072d6d-a63c-51f2-8caa-f87267580e7a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
