insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('632938c1-a660-539e-81f4-e98a03177a42', 'Fire with Fire', NULL, '9781529369762', 'Dani and Eden Rivera were both born to kill dragons, but the sisters couldn''t be more different. For Dani, dragon slaying takes a back seat to normal high school life, while Eden prioritizes training above everything else. Yet they both agree on one thing: it''s kill or be killed where dragons are concerned. Until Dani comes face-to-face with one and forges a rare and magical bond. As she gets to know Nox, she realizes that everything she thought she knew about dragons is wrong. And, with Dani lost to the dragons, Eden turns to the mysterious and alluring sorcerers to help save her sister. Now on opposite sides of the conflict, the sisters will do whatever it takes to save the other. But the two are playing with magic that is more dangerous than they know, and there is another, more powerful enemy waiting for them both in the shadows.', '08.06.2022', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dani Rivera','Eden Rivera']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
