insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d6f35740-9ec1-5f52-8062-6ac5cc9d77f5', 'Howl''s Moving Castle', NULL, '9780061478789', 'Sophie has the great misfortune of being the eldest of three daughters, destined to fail miserably should she ever leave home to seek her fate. But when she unwittingly attracts the ire of the Witch of the Waste, Sophie finds herself under a horrid spell that transforms her into an old lady. Her only chance at breaking it lies in the ever-moving castle in the hills: the Wizard Howl''s castle. To untangle the enchantment, Sophie must handle the heartless Howl, strike a bargain with a fire demon, and meet the Witch of the Waste head-on. Along the way, she discovers that there''s far more to Howl—and herself—than first meets the eye. What will happen to Sophie Hatter when she enters Howl''s castle?', '27.11.2019', 'HarperCollins', ARRAY['Deutsch']::text[], 429, 21, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Moving Castle', '{}', ARRAY['Sophie','Howl']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
