insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cb27bf99-1af4-5f31-a89d-688cd86229e2', 'Der neunte Arm des Oktopus', NULL, '9783751707473', 'Der Klimawandel - eine Katastrophe ungeahnten Ausmaßes steht uns bevor. Verändert unsere Erde. Verändert unser aller Leben. Das Fiasko scheint unaufhaltsam. Bis die drei Supermächte China, Russland und die USA einen radikalen Weg einschlagen. Doch wird diese starke Klima-Allianz das Ruder noch herumreißen? Die Maßnahmen der Allianz greifen gravierend in das Leben der Menschen ein, und nicht jeder will diese neue Wirklichkeit kampflos akzeptieren. Alle Mittel sind den Gegnern recht, um ihre ökonomischen und machtpolitischen Interessen zu verteidigen. Die Situation spitzt sich dramatisch zu, und plötzlich liegt das Schicksal der Erde in den Händen eines schüchternen Kochs und einer unscheinbaren Geheimagentin.', '16.11.2020', 'Lübbe', ARRAY['Deutsch']::text[], 605, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Politthriller']::text[], NULL, 'Zukunft'::time_period, 'Weltweit', '{}', '{}', '{}', '{}', '8dc9a51d-60b1-5861-8a67-dd64329a8fd3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
