insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('deee7f65-ca3c-5fe9-98d8-0787620423d9', 'Der Zorn des Oktopus', NULL, '9783751721301', 'Das Jahr 2029, die Klimakatastrophe ist da, und die Menschheit kämpft ums Überleben. Die Klima-Allianz, ein Bündnis der großen Machtblöcke, will Chaos und Hungerkriege verhindern. Ihr wichtigstes Instrument: ein Supercomputer. Doch dann fällt dieser Quantencomputer in die Hände eines ebenso brillanten wie besessenen Verbrechers. Und plötzlich sind da nur noch zwei Menschen, die das Allerschlimmste verhindern müssen - Thomas Pierpaoli, ein kleiner Beamter, und Ariadna, eine temperamentvolle Millionärin. Gejagt und in Gefahr - und mit nur einem Ziel vor Augen: die Welt zu retten.', '18.10.2021', 'Lübbe', ARRAY['Deutsch']::text[], 397, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Politthriller']::text[], NULL, 'Zukunft'::time_period, 'Weltweit', '{}', '{}', '{}', '{}', '8dc9a51d-60b1-5861-8a67-dd64329a8fd3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
