insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('abfa3aee-da1d-5924-bf1a-a76b41743118', 'Das dritte Herz des Oktopus', NULL, '9783751748261', 'Das Jahr 2032, die Weltregierung kämpft gegen die Klimakatastrophe. Aber immer noch sperren und sträuben sich auf der Welt viel zu viele Menschen - wie kann man sie überzeugen, zur Einsicht bringen? Oder sogar - ändern? Ein ehrgeiziger Wissenschaftler hat eine Lösung: Ein Parasit, der unser Denken verwandelt, der uns zu besseren Menschen macht. Doch als ein Verbrecher diesen Parasiten für seine skrupellosen Ziele benutzen will, liegt unser aller Schicksal in den Händen eines kleinen Beamten und einer temperamentvollen Millionärin.', '16.10.2023', 'Lübbe', ARRAY['Deutsch']::text[], 700, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Politthriller']::text[], NULL, 'Zukunft'::time_period, 'Weltweit', '{}', '{}', '{}', '{}', '8dc9a51d-60b1-5861-8a67-dd64329a8fd3', '3', '{}', 'sheet', :'owner') on conflict do nothing;
