insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6999f095-0cf5-532d-bef9-19896b031cf1', 'You’ve Reached Sam', NULL, '9781250836748', 'Seventeen-year-old Julie has her future all planned out: move out of her small town with her boyfriend Sam, attend college in the city, spend a summer in Japan. But then Sam dies. And everything changes. Desperate to hear his voice one more time, Julie calls Sam’s phone just to listen to his voicemail. And Sam picks up the phone . . .', '26.05.2022', 'Wednesday Books', ARRAY['Englisch']::text[], 293, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Julie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
