insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5e5c0d58-e2d0-533f-b832-922e78855007', 'Fifty Shades of Grey - Gefährliche Liebe', 'Fifty Shades Darker', NULL, 'Verunsichert durch die gefährlichen Leidenschaften und dunklen Geheimnisse ihres Liebhabers Christian Grey, bricht Ana Steele ihre Beziehung zu dem attraktiven jungen Mann ab und versucht wieder ein ruhiges Leben zu führen. Aber Anas Verlangen nach Christian ist ungebrochen, so sehr sie dies auch zu verleugnen sucht. Als Christian vorschlägt, sich wenigstens noch ein einziges Mal mit ihr zu treffen, willigt Ana daher sofort ein – und beginnt erneut eine Affäre mit ihm. Eine höchst gefährliche Affäre, in der sie immer wieder Grenzen überschreitet, in der sie aber auch mehr über die Vergangenheit von Christian erfährt – eine Vergangenheit, die ihn zu einem ebenso verletzlichen wie faszinierenden Mann gemacht hat, der seitdem mit seinen inneren Dämonen kämpft. Gleichzeitig sieht sich Ana der Eifersucht der Frauen gegenüber, die vor ihr Christians Liebhaberinnen waren. Und sie muss die wichtigste Entscheidung ihres Lebens treffen. Eine Entscheidung, bei der ihr niemand helfen kann ...', '05.09.2012', 'Goldmann', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ana Steele','Christian Grey']::text[], '{}', '{}', 'bb0c0ea3-0be4-5e42-aa03-f32f9719a68f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
