insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7f19bd14-c5c5-5812-8338-0ed35ba7e8ce', :'owner', '5e5c0d58-e2d0-533f-b832-922e78855007', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17f3a14a-ac82-51bb-a998-cc57dcfda09f', 'Fifty Shades of Grey - Befreite Lust', 'Fifty Shades Freed', NULL, 'Als die noch unerfahrene Studentin Ana Steele den attraktiven und faszinierenden Christian Grey kennenlernt, beginnt sie eine gefährliche Affäre mit ihm, die das Leben von beiden für immer verändert. Doch schon bald ist Ana von Christians dunklen Leidenschaften verunsichert und verlangt nach einer tieferen Beziehung und mehr Nähe. Zunächst scheint sich Christian tatsächlich auf Ana einzulassen, und die beiden genießen ihre Leidenschaft und die unendlichen Möglichkeiten ihrer Liebe. Aber Ana ist sich bewusst, dass es nicht einfach sein wird, mit Christian zusammenzuleben. Ana muss vor allem lernen, Christians Lebensstil zu teilen, ohne ihre Persönlichkeit und ihre Unabhängigkeit zu verlieren. Und Christian muss sich von den Dämonen seiner Vergangenheit befreien. Gerade in dem Moment, als ihre Liebe alle Hindernisse zu überwinden scheint, werden Ana und Christian Opfer von Missgunst und Intrigen, und Anas schlimmste Albträume werden wahr. Ganz auf sich allein gestellt, muss sich Ana endlich Christians Vergangenheit stellen.', '24.10.2012', 'Goldmann', ARRAY['Deutsch']::text[], 672, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ana Steele','Christian Grey']::text[], '{}', '{}', 'bb0c0ea3-0be4-5e42-aa03-f32f9719a68f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
