insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ed4d043c-a527-5c4c-a95a-7b263e679560', 'Fifty Shades of Grey - Geheimes Verlangen', 'Fifty Shades of Grey', NULL, 'Sie ist 21, Literaturstudentin und in der Liebe nicht allzu erfahren. Doch dann lernt Ana Steele den reichen und ebenso unverschämt selbstbewussten wie attraktiven Unternehmer Christian Grey bei einem Interview für ihre Uni-Zeitung kennen. Und möchte ihn eigentlich schnellstmöglich wieder vergessen, denn die Begegnung mit ihm hat sie zutiefst verwirrt. Sosehr sie sich aber darum bemüht: Sie kommt von ihm nicht los. Christian führt Ana ein in eine dunkle, gefährliche Welt der Liebe – in eine Welt, vor der sie zurückschreckt und die sie doch mit unwiderstehlicher Kraft anzieht …', '09.07.2012', 'Goldmann', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ana Steele','Christian Grey']::text[], '{}', '{}', 'bb0c0ea3-0be4-5e42-aa03-f32f9719a68f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
