insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e804b46-83c9-5f49-b59f-22abd15fb445', 'My gently raised Beast (Vol.4)', '곱게 키웠더니, 짐승', '9783910530270', 'Blondina und Amon haben sich geküsst! Blondina kann ihr Glück kaum fassen, doch ist sie sich immer noch unsicher darüber, was Amon eigentlich für sie empfindet. Währenddessen holt Amon sich Rat bei seinen Freunden, was er tun muss, um seine Briddy gemäß den Menschenregeln zu heiraten. Daraufhin macht er sich auf den Weg, um ihren Vater, den König, zu treffen …', '16.09.2024', 'Papertoons', ARRAY['Deutsch']::text[], 272, NULL, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Ates Imperium', ARRAY['3P Objective']::text[], ARRAY['Blondina']::text[], '{}', '{}', '1690bf07-37ed-52ca-9ec7-8d103b237306', '4', '{}', 'sheet', :'owner') on conflict do nothing;
