insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cd7e1e84-35f3-5865-9379-54b499c536eb', 'Pretty Lies - Lucy und Ryan', NULL, '9783492982665', 'Seit einem schweren Autounfall besteht Lucys Leben aus Studium, einem Nebenjob im Café – und vor allem daraus, sich um ihre schwerverletzte Mutter im Pflegeheim zu kümmern. Das Geld ist knapp, das Studentenheim kann sich die junge Frau kaum noch leisten. Da erbt sie auf einmal von ihrer Großtante eine wunderschöne Wohnung mitten in Edinburgh. Der einzige Haken an der Sache: Ryan, der ebenfalls in der Wohnung lebt. Und es gibt nur drei Dinge, die Ryan so sehr liebt wie sich selbst: Partys, sein Schlagzeug – und Mädchen …', '02.05.2016', 'Piper', ARRAY['Deutsch']::text[], 252, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lucy','Ryan']::text[], '{}', '{}', 'e053a5f7-be4e-5c0d-8c11-21f1742e96ca', '1', '{}', 'sheet', :'owner') on conflict do nothing;
