insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('927c2727-ae6e-5459-97e3-23da2b7154f2', 'Pretty Lies - Holly und Tyler', NULL, '9783492982672', 'Für Holly scheint endlich alles gut zu werden: mit neuer Wohnung und neuem Job will sie für sich und ihre kleine Tochter Amy eine bessere Zukunft. Doch da hat sie die Rechnung ohne das Schicksal gemacht! Auf einmal klopft ein längst vergessenes Kapitel ihrer Vergangenheit an und reißt alte Wunden wieder auf: Tyler – und er ist fest entschlossen, Holly von seinen Gefühlen zu überzeugen …', '02.07.2016', 'Piper', ARRAY['Deutsch']::text[], 238, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Holly','Tyler']::text[], '{}', '{}', 'e053a5f7-be4e-5c0d-8c11-21f1742e96ca', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
