insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6fbfbe80-fa41-5fae-8a54-87f491c19abc', 'Kissed by an Angel', NULL, '9783785573600', 'Ivy hat ihr Leben lang den Engeln vertraut und sie oft um Hilfe gebeten, wenn es ihr schlecht ging. Aber als sie und ihre große Liebe Tristan zusammen im Auto verunglücken und Tristan dabei getötet wird, verliert Ivy ihren Glauben an die Himmelswesen. Und so kann sie auch nicht spüren, dass ihr geliebter Tristan selbst nach seinem Tod bei ihr ist - als ihr persönlicher Schutzengel. Während Ivy mit ihrem Schmerz kämpft, bemüht sich Tristan verzweifelt um ihre Aufmerksamkeit. Darüber vergisst er fast seinen himmlischen Auftrag: Herauszufinden, wer ihn töten wollte.Ihn - oder vielleicht Ivy?', '06.06.2011', 'Loewe', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ivy']::text[], '{}', '{}', '5e6d0c54-9c3e-595a-84e0-4bf433dfbc40', '1', '{}', 'sheet', :'owner') on conflict do nothing;
