insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('cb80f0e6-7806-5dd6-b747-964dd4c26470', '17cc8556-5221-5084-9b91-ca6ab3806994', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('62b105f6-4b6c-542e-b97e-835a94b38806', 'Loved by an Angel', 'The Power of Love', '9783785573693', 'Tristan ist sich sicher, dass der Autounfall, der ihn das Leben gekostet hat, kein Zufall war. Und schlimmer noch: Er glaubt, dass der Anschlag eigentlich Ivy galt. Sie schwebt also noch immer in Lebensgefahr! Nur weiß außer Tristan, der als Ivys persönlicher Schutzengel auf der Erde zurückgeblieben ist, niemand davon. Verzweifelt sucht er nach einem Weg, Ivy zu warnen. Doch der Mörder schmiedet bereits neue Pläne. Ein Wettlauf gegen die Zeit beginnt … Weil Ivys Mutter erneut geheiratet hat, muss Ivy nun mit ihr in die Villa ihres Stiefvaters und dessen Sohnes ziehen. In solchen Notsituationen erbittet Ivy meist die Hilfe der Engel. Doch niemals hätte sie geahnt, dass ausgerechnet ihr verstobener Freund als Himmelsbote zu ihr zurückkehrt! Eine himmlisch romantische Geschichte mit fesselnder Spannung von Elizabeth Chandler für Mädchen ab 13 Jahren.', '04.10.2011', 'Loewe', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ivy']::text[], '{}', '{}', '5e6d0c54-9c3e-595a-84e0-4bf433dfbc40', '2', '{}', 'sheet', :'owner') on conflict do nothing;
