insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8b2bea3-2790-5047-ae9b-e4db79f924cb', 'Prince of the Arena', NULL, '9781998945108', 'Farron, the Prince of Autumn, wants nothing less than to be tangled up with Dayton, the Prince of Summer. Dayton is reckless, wild, and probably hasn’t opened a book once in his life. Meanwhile, Farron likes to think everything through—including how to survive the next few weeks while his family is staying in the Summer Realm. But Dayton has set his sights on Farron, and despite his better judgment, Farron finds himself drawn into the storm that is the Summer Prince. The deeper he falls, the more Dayton pulls away, and Farron can’t hold onto him any more than the sand can hold onto the tide. Amid the dangerous landscape of gladiator battles, political intrigue, and the scorching heat of a Summer sky, Farron and Dayton are set on a path that will lead to true love or eternal heartbreak. A love story years in the making before a certain Rose blooms in the hearts of two men destined to save the Enchanted Vale… or destroy it.', '20.06.2025', 'Luna Fox Press', ARRAY['Englisch']::text[], 149, 26, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Double POV','1P']::text[], ARRAY['Dayton','Farron']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '8', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('127e23ca-8287-5890-a66a-de29ac00abf6', :'owner', 'a8b2bea3-2790-5047-ae9b-e4db79f924cb', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['In-Book Illustrationen']::text[], 341, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 4, 'slow'::burn_kind, 'Also es war definitiv eine sehr sehr cute story und genau das, was ich zwischendurch gebraucht habe. Das einzige was mich wirkich genervt hat, war wie schnell Farron Dayton immer wieder vergeben hat, ohne ihm wirklich zu sagen was er denkt. Auf der anderen Seite passt es zu den Charaktern.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('dd67bf0b-96d1-515a-9514-42c91a04a1e8', '127e23ca-8287-5890-a66a-de29ac00abf6', :'owner', 1, '2026-05-08', '2026-05-09', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0e020b79-25a4-5637-af34-720e1198d0b9', 'Bonded By Thorns', NULL, '9780008670542', 'Rosalina O’Connell lives her life in Orca Cove as quietly as she can. When her father turns up missing, Rosie goes after him and finds herself in the Enchanted Vale, the land of the fae. Where her father has been imprisoned and Rosie has no choice but to make a deal with four fae Princes to take his place. As Rosie begins to learn more about the four Princes, she discovers that they have been cursed. The Princes must take on the form of demonic wolves every night and with every year that passes, more of their magic fades away. If the Princes can each find their mate, they will break their curse and free their realm. Rosie is determined to help them… The only problem is, the more time she spends with the Princes, the more she’s convinced that she’s the one they’re all meant to be with.', '18.07.2024', 'Magpie', ARRAY['Englisch']::text[], 369, 61, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], ARRAY['Belästigung','Suizidalität']::text[], '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
