insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('26478e8d-ccad-5526-91c8-59a3bc73b6ae', 'Forged by Malice', NULL, '9780008670658', 'Since journeying to the fae realm, Rosalina O’Connell has discovered that she is the fated mate of both Prince Keldarion and Prince Farron. Rosie has also learned that she is half fae. When goblins attack Castletree, using steel from the Spring Realm, Rosie and the princes must travel to Spring to solve this deadly mystery. In the Spring realm, Prince Ezryn’s brother is set on bringing the realm to ruin. To stop his brother’s evil plan, Prince Ezryn, High Prince of Spring, must reclaim his birthright and break his curse. Could Rosie be Ezryn’s salvation and the key to saving Spring?', '18.07.2024', 'Magpie', ARRAY['Englisch']::text[], 655, 112, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c783649a-8739-50fb-a01e-315fe5c4cef3', :'owner', '26478e8d-ccad-5526-91c8-59a3bc73b6ae', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 1745, true, false, ARRAY['Audible']::text[], ARRAY['Laurent Darnell','Josie Gold','Hunter Johns','Todd Roddington','Sally Roma','Robin Speare']::text[], 1116, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 5, 'slow'::burn_kind, 'Again... Caspian hat mein Herz erobert. Wenn ich die Boys ranken müsste wäre es wie folgt: 1. Caspian 2. Ezryn 3. Keldarion 4. Dayton 5. Farron. Ich mochte das Buch und hab es praktisch inhaliert. Trotzdem muss ich sagen: Die Charaktere sind so inkonsequent! Innerhalb von einer Unterhaltung wechseln sie gefühlt 5 mal ihre Meinung und das konnte etwas anstregend sein.') on conflict do nothing;
