insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('97784d42-fea0-5ff5-a982-2f73affcb326', 'Broken by Daylight', NULL, '9780008670702', 'War has come to the Enchanted Vale. The forces of the Below have enacted their evil plan and both the Spring and Summer Realm are now under their influence. Will Autumn and Winter be next? Rosie and Dayton, High Prince of the Summer Realm, enter a deadly tournament to reclaim the Bow of Radiance and save Summer together. But can they keep fighting their growing feelings for each other? As the Realms fall prey to the Below’s schemes, Rosie must take her place as the Princess of the Enchanted Vale and fated mate to three of the High Princes. The fight has only just begun…', '10.09.2024', 'Magpie', ARRAY['Englisch']::text[], 672, 125, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('52c1609d-c2e9-59c0-8a6a-2972d10e3af8', :'owner', '97784d42-fea0-5ff5-a982-2f73affcb326', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 1745, true, false, ARRAY['Audible']::text[], ARRAY['Laurent Darnell','Josie Gold','Hunter Johns','Todd Roddington','Sally Roma','Robin Speare']::text[], 1429, '👍🏻', false, 'solo'::company_kind, 'like'::verdict_kind, 3.0, 'erfuellt'::expectation_kind, 5, 'slow'::burn_kind, 'Ich glaube ich würde mein Ranking überdenken, einfach weil manche Charaktere zu nervig waren in diesem Band. 1. Caspian 2. Keldarion 3. Dayton 4. Farron 5. Ezryn. Ich mag die Reihe und ich bin auch gespannt wie sie Endet, aber so langsam nerven mich die Charaktere. Dieses ständige Selbstmittleid und beharren auf dummen Entscheidungen...') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b40890ce-7062-518b-8072-eafb61d1e97b', '52c1609d-c2e9-59c0-8a6a-2972d10e3af8', :'owner', 1, '2025-06-27', '2025-07-04', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('30ea85a9-80a5-5b2f-87ac-8a67178a7eb4', 'Stolen by Shadows', NULL, '9781464261848', 'Once upon a time, I used to look upon the sun. Now, there is only darkness. And the Prince of Thorns. I am his captive, his thrall. Caspian, the man he used to be, is nothing but a memory. And if the Prince of Thorns gets his way, all of the Enchanted Vale-and the four other princes bound to my heart-will fall to ruin. As I navigate the treacherous Below, my mates risk everything to reach me. But the Green Flame is spreading across the realms, corrupting all it touches. If they can''t fight it, Caspian won''t be the only one consumed by its power. It''s now or never. Either we defeat the god who seeks to tear our world apart...or we die together, becoming nothing but shadow. But I''ve learned something down here. Beautiful things can grow in the dark. I''ll do whatever it takes to protect my home and family...and bring Caspian back to me.', '21.07.2026', 'Sourcebooks', ARRAY['Englisch']::text[], 485, 87, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '6', '{}', 'sheet', :'owner') on conflict do nothing;
