insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('fcaabcdf-7650-5476-baec-087a8ea478cf', '8f1f8289-05fb-565b-a1d6-6cafd397555c', :'owner', 1, '2026-10-10', NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5d28e661-9508-5655-a885-8be963215798', 'Woven by Gold', NULL, '9780008670603', 'Rosalina O’Connell has been exiled from the fae realm and sent back to Orca Cove, against her wishes. Betrayed by her own mate, Prince Keldarion of the Winter Realm. But nothing will stop her from returning to her true home. When Rosie manages to tap into the magic of Castletree, and make contact with Prince Ezryn of the Spring Realm, she begs him to rescue her. But when Rosie returns to the Enchanted Vale, she and the princes discover that there is a frost attacking the Autumn Realm. If Rosie can’t figure out how to stop it, war will be declared in the Enchanted Vale. Can Rosie unearth the magic inside herself and save her princes and the Autumn realm?', '18.07.2024', 'Magpie', ARRAY['Englisch']::text[], 563, 90, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('8451d372-c1d3-5822-adc5-8847554bf148', :'owner', '5d28e661-9508-5655-a885-8be963215798', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 1579, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 4, 'slow'::burn_kind, 'Mein Herz schlägt für Caspian! Poor Boy. Ich hab so mit ihm gelitten, als Farron sein Buch zerstört hat. Alles manches in diesem Buch geht mir zu schnell und viele Twist sind einfach für den Leser zu offensichtlich, während die Charaktere ahnungslos herumstolpern. Trotzdem ist es eine spannende und tolle Story.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3bacd52a-a072-5b3a-86c6-42853ab50f5c', '8451d372-c1d3-5822-adc5-8847554bf148', :'owner', 1, '2025-06-01', '2025-06-15', NULL, NULL, 15, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a032af37-47cd-51ad-8442-de2b7cf627c6', 'Frozen by Stardust', NULL, '9781464272240', 'Nowhere in the Enchanted Vale is safe anymore. Sira, the queen of the Below, has threatened open war, and there are no lengths she won''t go to destroy us. But she might not get the chance... we may destroy ourselves first. After months apart, I''m finally reunited with my five mates in the heart of Winter. Our only hope to defeat Sira lies in the shattered remains of an enchanted rose. If my father can restore it, we''ll gain control over Sira''s creations and end her reign for good. But deep beneath the snow, a new threat stirs, one with vengeance in its heart and Keldarion in its sights. As Winter braces for war, my mates each face their own reckonings. Farron has embraced a terrifying power beyond imagination. Dayton has risen from the land of the dead, only to wish he were still there. Echoes of Spring''s empty throne follow Ezryn everywhere he goes. And Caspian and Kel continue to wage their own war--one of trust and love that has haunted them for decades. The realms are fracturing. Castletree is fading. And darkness has crept into my heart, too. I''m the Princess of the Enchanted Vale. If I can''t find a way through this, no one will. Everyone is intent on taking away everything that I love. My home. My people. My mates. I won''t let them. Even if that means becoming the very thing I''ve sworn to destroy.', '21.04.2026', 'Sourcebooks', ARRAY['Englisch']::text[], 731, 96, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Enchanted Vale', ARRAY['Multiple POV','1P']::text[], ARRAY['Rosalina O''Connell','Keldarion','Dayton','Farron','Ezryn','Caspian']::text[], ARRAY['Dark Secrets','Different Worlds','Enemies to Lovers','Magical Artifacts','Magical Creatures','Reverse Harem','Soul Mates','Why Chose']::text[], '{}', '62f0845c-1824-5e09-a33b-cbc040dd8c1f', '5', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7fbfcbb4-9cdd-5a5c-86ac-7150970c380f', :'owner', 'a032af37-47cd-51ad-8442-de2b7cf627c6', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital','Audiobook']::text[], ARRAY['Taschenbuch','eBook']::text[], 'Normal', ARRAY['Map','Floppy']::text[], 1799, true, false, ARRAY['Audible']::text[], ARRAY['Stefanie Kay','Robert Hatchet']::text[], 1310, '👌🏻', false, 'solo'::company_kind, 'dislike'::verdict_kind, 1.5, 'untertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Dieses Buch war leider einfach nur schlecht. Kapitelweise nichts anderes als Sex-Szenen, die vollkommen unangebracht waren zu den jeweiligen Zeitpunkten. Die Handlung war basically nicht existent und wenn dann einfach komplett unnötig. Es gab zu keinem Zeitpunkt einen Plan, sondern immer nur ein naives drauf los hauen. Vor allem Ferron und Keldarion gingen mir so dermaßen auf die nerven mit ihrer Sturheit und dummen Naivheit. Das Buch hatte einfach viel zu viele Seiten, dafür, dass nichts passiert ist. Schade. Die Reihe hat mir so gut gefallen, und ich werde auch weiter lesen, aber das Buch hier war leider ein Flop.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('e14c2375-f5c6-5be5-94fc-18067c281ff4', '7fbfcbb4-9cdd-5a5c-86ac-7150970c380f', :'owner', 1, '2026-05-09', '2026-05-22', NULL, NULL, 14, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38418990-41b7-54f5-8964-a454af30ecd1', 'Ein Kleid aus Seide und Sternen', 'Spin the Dawn', '9783551584151', 'Maia Tamarin träumt davon, die beste Schneiderin des Reiches zu werden. Sie lernt diese Kunst von ihrem Vater und ist sehr begabt, aber als Mädchen ist ihr die Ausübung dieses Berufes untersagt. Als der Kaiser einen Wettbewerb um den Posten des Hofschneiders ausruft, fasst sie einen gewagten Plan: Verkleidet als Junge reist sie unter dem Namen ihres Bruders an den Hof, um für ihren Traum zu kämpfen. Unter den zwölf Schneidern, die sich bewerben, herrscht hohe Konkurrenz, das Leben am Hof ist von Intrigen bestimmt – und keiner darf Maias Geheimnis erfahren, denn dann erwartet sie der Tod. Doch schon bald zieht sie die Aufmerksamkeit des geheimnisvollen Magiers Edan auf sich: Er scheint ihre Verkleidung zu durchschauen. Und Maia braucht seine Hilfe, um die schier unmögliche letzte Aufgabe des Wettbewerbs zu erfüllen: Sie muss drei magische Kleider für die kaiserliche Prinzessin nähen, die aus Elementen der Sonne, der Sterne und des Mondes gewirkt sind. Zusammen mit Edan begibt sich Maia auf eine gefährliche Reise, die sie fast alles kostet, was ihr lieb und teuer ist …', '02.07.2020', 'Carlsen', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Maia Tamarin']::text[], '{}', '{}', 'fd20d7cc-ded9-599e-b6d6-d6d6ef8a51d6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
