insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('4737846f-7e8a-5e9c-8901-57feb2957d27', 'b49b237d-ea31-5070-a888-d85c86d258c7', :'owner', 1, '2021-12-17', '2021-12-20', NULL, NULL, 4, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('776f86e8-0de6-5c88-8c65-082cd3060b31', 'Bestickt mit den Tränen des Mondes', 'Unravel the Dusk', '9783551584496', 'Maia Tamarin hat alle drei magischen Kleider aus dem Blut der Sterne, dem Lachen der Sonne und den Tränen des Mondes vollendet. Doch der Preis dafür war hoch: Sie kehrt in ein Königreich zurück, das am Rande eines Krieges steht. Edan, der geheimnisvolle Magier, den sie liebt, ist verschwunden – und kaum hat sie den Herbstpalast betreten, ist sie gezwungen, das Kleid der Sonne anzuziehen und den Platz der zukünftigen Braut des Kaisers einzunehmen, um den Frieden zu wahren. Als die Rivalen des Kaisers die Wahrheit erfahren, bricht der Krieg los – doch das ist nicht der einzige Kampf, den Maia durchstehen muss: Seit sie von Dämon Bandur berührt wurde, verwandelt sich Maia langsam, aber stetig in einen Dämon. Wird sie Edan finden und hat sie eine Chance, den bösen Mächten zu entkommen?', '29.07.2021', 'Carlsen', ARRAY['Deutsch']::text[], 395, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Maia Tamarin']::text[], '{}', '{}', 'fd20d7cc-ded9-599e-b6d6-d6d6ef8a51d6', '2', '{}', 'sheet', :'owner') on conflict do nothing;
