insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('d479f436-8c54-5ff3-9b05-6d22c268facd', '75a852ae-5dff-59a2-8d75-6b9e66cc1dbd', :'owner', 1, '2021-12-29', '2022-01-31', NULL, NULL, 34, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('919480bb-2bb7-5877-bd2c-263432b089a5', 'Taken', NULL, NULL, 'There’s been a malfunction in my pod. Only my pod. Fanfreakingtastic. Instead of waking up thousands of years after the fall of civilization, I’ve woken up early – to a world filled with monsters. When one of them – the biggest one – decides to take me to his tent for the night, I have no choice but to go with him. The big guy and I can’t communicate. I can''t tell him that I need to return to fix the bunker, so I''m gonna have to try to escape. My odds look bleak, because he watches me with the possessiveness of a male who wants me for more than a night…but maybe to keep.', '07.10.2025', NULL, ARRAY['Englisch']::text[], 128, 19, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, 'Earth', ARRAY['1P','Double POV']::text[], ARRAY['Rhen']::text[], ARRAY['Monster Love','He falls first','Shapeshifters','End of World']::text[], ARRAY['Dub-Con/Non-Con','Physische Gewalt','Tod']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '6', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('1e72598e-62c1-5ae7-af1f-b8ed77bfe3b2', :'owner', '919480bb-2bb7-5877-bd2c-263432b089a5', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Collector''s', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Also wie bei den meisten Kurzgeschichten ging mal wieder alles sehr schnell und einige Dinge waren einfach etwas unbedacht. Der Fokus lag viel von dem Erotik-Part. Trotzdem hat es Spaß gemacht zu lesen. Ich mag so Stories einfach. Ich mag nur leider nicht den "Breeding" Kink den da immer alle zu haben scheinen.') on conflict do nothing;
