insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('238e4f69-71c4-5a45-8633-243539d6f771', 'Ever Since I Needed You', 'Bad Girl Reputation', '9783736319165', 'Als Genevieve West für die Beerdigung ihrer Mutter nach Avalon Bay zurückkommt, hat sie nur ein Ziel: sich von ihrem Ex-Freund Evan Hartley fernzuhalten. Der Bad Boy ist immer noch so sexy und unwiderstehlich wie früher, aber Gen hat mit ihrem alten Leben abgeschlossen. Keine wilden Partys, keine unverantwortlichen Fehler mehr. Sie wird ihren Vater in seinem Geschäft unterstützen, bis dieser einen Ersatz gefunden hat, und dann ihrer Heimatstadt den Rücken kehren. Doch Evan hat da andere Pläne: Er ist fest entschlossen, für das einzige Mädchen zu kämpfen, das er je geliebt hat.', '28.04.2023', 'LYX', ARRAY['Deutsch']::text[], 382, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Avalon Bay', '{}', ARRAY['Genevieve West','Evan Hartley']::text[], '{}', '{}', '547c20b2-e3ab-5432-99ab-4a7ddc68ec28', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
