insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d7f9cfd0-d798-5650-8b15-4d6b06f4f58d', 'The Charlie Method', NULL, '9783736324848', 'Manchmal ist nichts schwerer, als einfach man selbst zu sein. Charlotte Kingston führt ein Doppelleben: Tagsüber ist sie Vorzeigetochter, studiert Biomedical Engineering und ist das perfekte Sorority-Girl. Bei Nacht ist sie Charlie, die einfach nur Spaß haben und sich gehen lassen will. Über eine Dating-App trifft sie die beiden Eishockey-Spieler Will und Beckett, die überhaupt nichts gegen ein Date zu dritt haben. Das Problem ist nur, dass Will einen Journalisten an der Backe hat, der von seinem lästigen Politikervater engagiert wurde und der auf keinen Fall etwas von seinem unkonventionellen Liebesleben mitbekommen darf ...', '25.07.2025', 'LYX', ARRAY['Deutsch']::text[], 688, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Charlotte Kingston']::text[], ARRAY['Sport','Universicy/College','Multiple Love Interests']::text[], '{}', '4bb50fdc-863b-538e-819a-dd449c44bcbf', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
