insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('dacfbba1-6bd8-54ef-96ea-5cee833e880d', '73d1f3a8-8f16-5006-b642-a9b2c69b3888', :'owner', 1, '2024-05-14', '2024-05-15', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('553f7b6e-046c-52d5-84fc-f7d0f6427b15', 'Girl Abroad', NULL, '9783736324749', 'Als Abbey Bly einen Studienplatz in London erhält, ist sie überglücklich, denn es ist die perfekte Chance, dem scharfen Auge ihres überbehütenden Rockstar-Vaters zu entfliehen. In England angekommen, erlebt sie erst mal eine gehörige Überraschung. Ihre drei »Mitbewohnerinnen« entpuppen sich als Jungs. Ziemlich unwiderstehliche Jungs! Rugbyspieler Jack lässt Abbeys Herz direkt höherschlagen. Es gibt nur zwei kleine Probleme. Zum einen besagen die WG-Regeln: keine Beziehungen unter den Bewohnern. Und zum anderen tritt schon bald auch noch der Musiker Nate in Abbeys Leben, der sie ebenfalls nicht kaltlässt und gehörig ins Gefühlschaos stürzt.', '28.03.2025', 'LYX', ARRAY['Deutsch']::text[], 544, 52, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Abbey Bly']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
