insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('28b5c91a-7da0-5b7a-bdd8-7244a648dddc', 'Ever Since I Found You', 'The Summer Girl', '9783736320819', 'Als die Collegestudentin Cassie Soul nach vielen Jahren wieder Avalon Bay besucht, ist sie auf der Suche nach einer heißen Sommerliebe - und findet Tate Bartlett. Der attraktive Segellehrer ist eigentlich immer für einen Flirt zu haben. Doch als er Cassie das erste Mal sieht, weiß Tate sofort, dass sie keine Frau ist, der er das Herz brechen will - und weist sie ab. Trotzdem entwickelt sich zwischen den beiden eine Freundschaft, und je mehr Zeit sie miteinander verbringen, desto mehr wächst die Anziehung zwischen ihnen. Aber kann Tate es wagen, seinen Gefühlen für Cassie nachzugeben, oder wird dieser Sommer mit zwei gebrochenen Herzen enden?', '29.02.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Avalon Bay', '{}', ARRAY['Cassie Soul','Tate Bartlett']::text[], '{}', '{}', '547c20b2-e3ab-5432-99ab-4a7ddc68ec28', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
