insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5c539dd5-9a24-5cec-b622-6c2282469147', 'Ever Since I Loved You', 'Good Girl Complex', '9783736318465', 'Mackenzie Cabot soll auf Wunsch ihrer Eltern ihren College-Abschluss machen. Widerwillig schreibt sie sich für das Garnet College in Avalon Bay ein, obwohl sie sich viel lieber weiter um ihr erfolgreiches Online-Start-up kümmern würde. Aber als sie Cooper Hartley trifft, stellt das ihre Welt auf den Kopf, denn er ist ganz anders als alle Männer, die sie bisher kennengelernt hat. Der Bad Boy mit den Tattoos ist der Einzige, der sie wirklich sieht: ihre Hoffnungen und Wünsche, ihre Träume und Ängste. Und schon bald kann sie seiner Anziehungskraft nicht länger widerstehen. Doch was Mackenzie nicht weiß: Es war kein Zufall, dass sie Cooper begegnet ist ...', '25.11.2022', 'LYX', ARRAY['Deutsch']::text[], 349, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Avalon Bay', ARRAY['Double POV','1P']::text[], ARRAY['Mackenzie Cabot','Cooper Hartley']::text[], ARRAY['Bad Boy X Good Girl','Universicy/College','Opposites Attract']::text[], '{}', '547c20b2-e3ab-5432-99ab-4a7ddc68ec28', '1', '{}', 'sheet', :'owner') on conflict do nothing;
