insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('884e0ce3-88a0-527f-8d73-bc948aaf310a', 'Fire & Frost - Vom Eis berührt', 'Frostblood', '9783473401574', 'Ruby lebt in ständiger Gefahr, denn sie besitzt die Gabe, mit Feuer zu heilen und zu zerstören. Firebloods wie sie werden von der Frostblood-Elite des Königreichs gnadenlos gejagt. Als die königlichen Soldaten Ruby aufspüren, wird sie ausgerechnet von dem jungen Frostblood-Krieger Arcus gerettet. Kälte und Eis sind seine Waffen, doch er braucht Rubys Feuer, um eine Rebellion gegen den verhassten König anzuzetteln. Ruby weiß, dass sie einem Frostblood nicht vertrauen sollte, doch jede Berührung zwischen ihnen knistert wie eine Flamme im Schneesturm. Sie ahnt nicht, welch dunkles Geheimnis sich hinter Arcus‘ eisiger Fassade verbirgt …', '14.02.2018', 'Ravensburger', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Ruby']::text[], '{}', '{}', '24bf7c80-b143-5091-a1c3-f8d4e00f244c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
