insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('03359675-32fd-5554-a8db-7f9a7d2ba8db', 'Fire & Frost - Vom Feuer geküsst', 'Fireblood', '9783473401659', 'Ruby und Arcus haben den Thron des Frostkönigs zerstört, doch bis zum Frieden zwischen Firebloods und Frostbloods ist es noch ein weiter Weg. Denn Ruby ist mit dem dunklen Wesen verbunden, das aus dem Frostthron befreit wurde und nun mordend durchs Königreich zieht. Um es aufzuhalten, muss Ruby an den Hof der Feuerkönigin reisen – an der Seite des charmanten Firebloods Kai. Und schon bald spürt sie, dass sein Feuer ihr auf mehr als eine Weise gefährlich werden könnte.', '19.09.2018', 'Ravensburger', ARRAY['Deutsch']::text[], 444, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Ruby']::text[], '{}', '{}', '24bf7c80-b143-5091-a1c3-f8d4e00f244c', '2', '{}', 'sheet', :'owner') on conflict do nothing;
