insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6087923a-d85d-5378-abc4-ab809fcedf60', 'Wild Card', NULL, '9783736326378', 'Nach einer magischen Nacht verliert Bash Rousseau die lebenslustige Gwen Dawson aus den Augen - und staunt nicht schlecht, als er ihr ein paar Monate später zufällig wiederbegegnet. Auf der Geburtstagsfeier seines Sohnes, der ihm Gwen als seine Freundin vorstellt. Als Gwen dann jedoch wenig später nach Rose Hill zieht, ist die Anziehung zwischen den beiden augenblicklich wieder da, auch wenn eine Beziehung zwischen ihnen absolut unmöglich ist - schließlich ist Bash immer noch der Dad ihres mittlerweile Ex-Freundes. Aber je öfter sie aufeinandertreffen, desto schwerer fällt es ihnen, die Finger voneinander zu lassen, und die beiden stellen sich zunehmend die Frage, wie etwas, das sich so gut anfühlt, falsch sein kann ...', '02.02.2026', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Rose Hill', ARRAY['Double POV','1P']::text[], ARRAY['Bash Rousseau','Gwen Dawson']::text[], '{}', '{}', '89b741b1-cd6f-5fca-97fd-78b04c802246', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
