insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ce7dc19a-8213-59f5-8364-915e37703a27', 'Wild Eyes', NULL, '9783736324633', 'Eine abgelegene Ranch abseits einer kanadischen Kleinstadt klingt für die ausgebrannte Sängerin Skylar Stone wie der perfekte Ort, um sich vor ihren Fans und der Presse zu verstecken. Hier will sie zurück zu ihrer Musik und sich selbst finden, doch stattdessen trifft sie auf Weston Belmont. Der heiße Single Dad lässt sie eine Geborgenheit spüren, die ihr aus ihrem Celebrity-Leben völlig fremd ist, und seine zwei Kinder schleichen sich schnell in Skylars Herz. Zum ersten Mal in ihrem Leben erfährt sie, was es bedeutet, eine Familie und ein Zuhause zu haben. Doch schon bald holt ihr Ruhm sie wieder ein und bedroht ihr Glück mit West ...', '30.05.2025', 'LYX', ARRAY['Deutsch']::text[], 500, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Rose Hill', ARRAY['Double POV','1P']::text[], ARRAY['Skylar Stone','Weston Belmont']::text[], '{}', '{}', '89b741b1-cd6f-5fca-97fd-78b04c802246', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
