insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e892f05a-065a-5830-b892-d4e097bdaf74', 'Wild Side', NULL, '9783736325456', 'Tabitha liebt ihren kleinen Neffen über alles, und als sie Gefahr läuft, das Sorgerecht für ihn an ihren größten Feind Rhys Dupris zu verlieren, greift sie zu extremen Mitteln - sie heiratet ihn. Einen Mann, der so schweigsam wie geheimnisvoll ist, manchmal für Wochen verschwindet, dann mit Verletzungen wieder nach Rose Hill zurückkehrt und nicht darüber reden will. Doch als sie unter einem Dach leben, entdeckt Tabitha auch eine andere Seite an Rhys, eine liebevolle und fürsorgliche. Und das macht es immer schwerer für die junge Frau, ihren Ehemann zu hassen, und sehr leicht, sich in ihn zu verlieben ...', '29.08.2025', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Rose Hill', ARRAY['Double POV','1P']::text[], ARRAY['Tabitha','Rhys Dupris']::text[], '{}', '{}', '89b741b1-cd6f-5fca-97fd-78b04c802246', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
