insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fd9a26f5-1b38-5773-8b79-11d24381cdaa', 'Wild Love', NULL, '9783736324541', 'Ford Grant, »World’s hottest Billionaire« laut der Forbes und erfolgreicher Musikproduzent, staunt nicht schlecht, als ein fremdes Mädchen vor seiner Tür steht, das behauptet, seine Tochter zu sein. Völlig überfordert von der neuen Rolle als Vater und dem Umbau seines Tonstudios auf Rose Hill, nimmt er die Hilfe von Rosie Belmont an — auch wenn er weiß, dass dies keine gute Idee ist. Denn Ford ist schon immer in Rosie verliebt, obwohl sie als kleine Schwester seines besten Freundes absolut tabu ist ...', '28.02.2025', 'LYX', ARRAY['Deutsch']::text[], 469, 44, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Rose Hill', ARRAY['Double POV','1P']::text[], ARRAY['Ford Grant','Rosie Belmont']::text[], ARRAY['Rich vs. Poor','He falls first','Small Town','Work Adversaries','Family Drama']::text[], '{}', '89b741b1-cd6f-5fca-97fd-78b04c802246', '1', '{}', 'sheet', :'owner') on conflict do nothing;
