insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('722c9d92-a922-515b-9224-c5add33451bd', 'Wuthering Heights', NULL, NULL, 'Emily Brontë''s novel of impossible desires, violence and transgression is a masterpiece of intense, unsettling power. It begins in a snowstorm, when Lockwood, the new tenant of Thrushcross Grange on the bleak Yorkshire moors, is forced to seek shelter at Wuthering Heights. There he discovers the history of the tempestuous events that took place years before: the intense passion between the foundling Heathcliff and Catherine Earnshaw, her betrayal of him and the bitter vengeance he now wreaks on the innocent heirs of the past.', '24.11.1847', NULL, ARRAY['Englisch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Gothic']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Heathcliff','Catherine']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
