insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e7f8daa8-96b5-5a7b-8d59-8a6ba82dbae7', 'You and Me on Vacation', NULL, '9780241992234', '12 YEARS AGO: Poppy and Alex meet. They hate each other, and are pretty confident they''ll never speak again. 11 YEARS AGO: They''re forced to share a ride home from college and by the end of it a friendship is formed. And a pact: every year, one vacation together. 10 YEARS AGO: Alex discovers his fear of flying on the way to Vancouver. Poppy holds his hand the whole way. 7 YEARS AGO: They get far too drunk and narrowly avoid getting matching tattoos in New Orleans. 2 YEARS AGO: It all goes wrong. THIS YEAR: Poppy asks Alex to join her on one last trip. A trip that will determine the rest of their lives.', '11.05.2021', 'Penguin', ARRAY['Englisch']::text[], 361, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Poppy','Alex']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
