insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dd6bd0b8-a067-57d5-a8cd-ef030bd1df56', 'Bevor ich dich sah', 'Next to You', '9783453425439', 'Als Alice Gunnersley ausgerechnet das Krankenhausbett neben dem immer gut gelaunten Alfred Mack zugeteilt wird, kann sie ihr Pech kaum fassen. Denn während Alfie in einer Tour quasselt, will Alice einfach nur ihre Ruhe haben. Seit sie mit schweren Verbrennungen ins St.-Francis-Hospital eingeliefert wurde, spricht sie mit niemandem, vermeidet jeden Blick in den Spiegel und hält den Vorhang, der ihr Bett vom Rest der Station trennt, fest verschlossen. Als sie eines nachts jedoch hört, wie Alfred heftige Albträume quälen, wird ihr klar, dass sie nicht die einzige ist, die mit ihrem Schicksal hadert. Von nun an teilen sie Nacht für Nacht ihre Ängste und Sorgen miteinander. Gemeinsam stellen sie fest, dass es in Ordnung ist, wenn das Leben mal nicht in Ordnung ist. Dass die unsichtbaren Verletzungen oft mehr weh tun als die sichtbaren. Dass die Welt da draußen manchmal mehr Mut erfordert als ein Krankenhausaufenthalt. Und dass man sich in einen Menschen verlieben kann, ohne ihn je gesehen zu haben…', '12.07.2021', 'Penguin Random House', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Krankenhaus', '{}', ARRAY['Alice Gunnersley','Alfred Mack']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
