insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f6d0ae71-8b80-550c-8427-4e2b30d2d208', 'Cat & Cole - Vergessene Wunden: Short Story', 'These Precious Scars', '9783522654197', 'Jun Bei, Cole, Anna, Leoben und Ziana sind keine normalen Kinder. Sie leben abgeschottet in dem Labor des berühmten Genetikers Lachlan Agatta, der an ihnen forscht, um einen Impfstoff gegen das ausgebrochene Virus zu finden. Als aber eines Tages ein Mann und eine Frau der Cartaxus-Organisation auftauchen, scheint sich eine einzigartige Gelegenheit aufzutun: Sie bieten den Kindern einen Ausweg aus der Versuchshölle. Doch eine von ihnen würde sogar diese einmalige Chance aufs Spiel setzen, um das zu bekommen, was sie will …', '15.03.2019', 'Planet!', ARRAY['Deutsch','Englisch']::text[], 30, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Catarina Agatta','Cole']::text[], '{}', '{}', 'a9cb6b14-55b5-524a-bc8d-75f818d75a99', '4', ARRAY['Midquel']::text[], 'sheet', :'owner') on conflict do nothing;
