insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('66dc2b8b-b6c7-5a38-8727-f32b1e8dac20', 'Cat & Cole - Die letzte Generation', 'This Mortal Coil', '9783522505598', '1 Milliarde Leben am Abgrund. 2 Menschen, die sie retten können. 1 Geheimnis, versteckt in ihrer DNA. Krankheiten, Schönheitsmakel, körperliche Einschränkungen: von der Erde gelöscht! Mensch und Technik sind verschmolzen, jeder trägt ein Panel in sich, das den eigenen Körper perfektioniert. Fast! Eine mörderische Seuche ist ausgebrochen, und nur eine einzige Person auf der Welt ist fähig, den Impfstoff zu entschlüsseln – Catarina Agatta. Gemeinsam mit Cole, dessen Körper gentechnisch verändert wurde, kommt die geniale Hackerin Cat einer Wahrheit näher, die grausamer ist als jedes tödliche Virus!', '16.09.2018', 'Planet!', ARRAY['Deutsch']::text[], 477, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Catarina Agatta','Cole']::text[], '{}', '{}', 'a9cb6b14-55b5-524a-bc8d-75f818d75a99', '1', '{}', 'sheet', :'owner') on conflict do nothing;
