insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0720f706-8099-52bd-88a5-d80b915855f7', 'Cat & Cole - Ein grausames Spiel', 'This Cruel Design', '9783522506359', 'Die Seuche ist vorüber, aber der Kampf hat gerade erst begonnen! Cat ist erschöpft, verwundet und schockiert über die grausame Entdeckung über ihren Vater. Sein Plan: die komplette Menschheit nach seinen Wünschen umzuprogrammieren. Cat und Cole müssen ihn aufhalten und dafür eine Allianz mit dem Feind eingehen. Aber überall warten Lügen und Betrug. Cat muss alles und jeden, dem sie vertraut, infrage stellen. Und während ihr Vater immer zwei Schritte voraus ist, stellen sich Cats Geheimnisse, versteckt in ihrem eigenen Kopf, als größte Bedrohung heraus ...', '11.04.2019', 'Planet!', ARRAY['Deutsch']::text[], 458, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Catarina Agatta','Cole']::text[], '{}', '{}', 'a9cb6b14-55b5-524a-bc8d-75f818d75a99', '2', '{}', 'sheet', :'owner') on conflict do nothing;
