insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d38b473e-9a96-5352-aa94-ee474c7d93eb', 'This Vicious Cure', NULL, '9781534440951', 'Two factions at war. A plague that can''t be stopped. A cure that could destroy them all . . . Cat''s hacking skills weren''t enough to keep her from losing everything - her identity, her past, and now her freedom. Meanwhile, the person who''s stolen everything from her is close to realizing a hacker''s dream: the solution to humanity''s problems in gene form. Or so she thinks . . . But now a new threat has emerged - a threat that could bring the world to the brink of a devastating war. Both sides will stop at nothing to seize control of humanity''s future, and that the centre of this war is Cat, and a race against the clock save millions of lives . . .', '19.01.2021', 'McElderry Books', ARRAY['Englisch']::text[], 438, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Catarina Agatta','Cole']::text[], '{}', '{}', 'a9cb6b14-55b5-524a-bc8d-75f818d75a99', '3', '{}', 'sheet', :'owner') on conflict do nothing;
