insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0f6c00a6-3470-5131-9fd8-74cfbff8a091', 'Princess of Passion - Jane', 'Royally Raised', '9783644004481', 'Ein Blick in die Zukunft von Henrys Familie. «Fünf Kinder! Warum dachten wir, es wäre eine gute Idee, fünf Kinder zu bekommen?» Als Henry seiner Frau Sarah diese Frage stellt, meint er es nicht wirklich ernst. Die beiden lieben ihre Kinder abgöttisch. Aber fünf royale Sprösslinge in einem Palast großzuziehen bringt so seine Tücken mit sich. Und jetzt gerade bereitet Henry seine älteste Tochter Kopfzerbrechen. Mit ihren neunzehn Jahren ist Jane intelligent, schön und bereit, die Welt zu erobern. Und wehe dem, der ihr dabei im Weg steht …', '21.05.2019', 'Rowohlt', ARRAY['Deutsch']::text[], 115, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Historischer Liebesroman']::text[], NULL, NULL, NULL, '{}', ARRAY['Jane']::text[], '{}', '{}', '2777eebb-57da-5ceb-8630-3bcef2cc34d4', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
