insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cee30a30-a610-5f72-a667-f77bdb284935', 'We Conquer the Dark', 'The Sinner', '9783736322172', 'Seit dem Tod ihres Vaters hat sich die introvertierte Lucy in ihr Schneckenhaus zurückgezogen. Als eines Tages ein scheinbar toter, äußerst attraktiver Mann vor ihrer Tür liegt, wird ihre Welt aus den Fugen gehoben. Casziel ist ein mächtiger Dämon, der nach Erlösung sucht, aber nicht mehr wirklich daran glaubt - zu viel Leid hat er einst über die Menschen gebracht. Er möchte Lucy dabei helfen, ihr Glück zu finden, und dann seine eigene Existenz beenden. Bald schon wird klar, dass die beiden etwas verbindet, was über irdische Anziehungskraft hinausgeht. Zum ersten Mal in ihrem Leben fühlt Lucy nicht mehr diese schmerzliche Leere in sich. Doch um Casziel zu erlösen, muss sich Lucy den finstersten Mächten der Unterwelt stellen ...', '26.07.2024', 'LYX', ARRAY['Deutsch']::text[], 384, 25, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lucy','Casziel']::text[], '{}', '{}', 'f201462a-71d9-599f-8b39-f86b62b54932', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('4e1157ac-bf9f-548b-911c-aba83ef7aca0', :'owner', 'cee30a30-a610-5f72-a667-f77bdb284935', 'tbr'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Paperback']::text[], 'Normal', '{}', 1600, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('71973292-0260-5830-bb57-126dbaaba6cc', 'The Girl in the Love Song', NULL, '9783736317482', 'Miller Stratton ist in bitterer Armut aufgewachsen und hofft, sich mit seinem außergewöhnlichen Musiktalent ein besseres Leben aufbauen zu können. Doch auch wenn der Erfolg zum Greifen nah ist, so scheint ihm eines verwehrt zu bleiben: Violet, das Mädchen in all seinen Love Songs. Sie ist die Eine für ihn, war es schon seit dem schicksalhaften Tag, als sie ihm mit dreizehn Jahren das Leben rettete. Jeder weiß das, außer Violet selbst, die sich mit aller Macht gegen die Gefühle für ihren besten Freund stemmt. Denn sie sieht jeden Tag bei ihren Eltern, was passiert, wenn die Liebe scheitert. Aber wie lange kann sie ihm bei seinem Aufstieg zum Ruhm zusehen, ohne sich einzugestehen, dass auch ihr Herz schon immer nur ihm gehört hat?', '26.08.2022', 'LYX', ARRAY['Deutsch']::text[], 509, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Miller Stratton','Violet']::text[], '{}', '{}', '99e9d13a-19bc-5def-9f69-a88c2d69fb86', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('47451631-0a73-5c2e-8ab2-989542ece4af', :'owner', '71973292-0260-5830-bb57-126dbaaba6cc', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d1836643-0130-5700-8898-3eece6fb5164', 'We Reach for the Lieght', 'The Muse', '9783736322509', 'Der sensible Künstler Cole hat die Hoffnung auf Erfolg schon fast aufgegeben, als die mitternächtliche Begegnung mit einem Wesen der Nacht alles verändert. Er ahnt nicht, dass seine Seele in Gefahr ist. Denn der Dämon Ambri entfacht in ihm ein kreatives Feuer, dass er so nie kannte - und noch viel mehr. Auch Ambri bleibt nicht unberührt von Cole. Obwohl er den Auftrag hat, Cole zu korrumpieren, kann er sich den Gefühlen nicht entziehen, die der junge Maler in ihm weckt. Aber den Mächten der Finsternis wurde eine reine Seele versprochen, und sie kommen, um diese einzufordern ...', '23.12.2024', 'LYX', ARRAY['Deutsch']::text[], 416, 34, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cole','Ambri']::text[], '{}', '{}', 'f201462a-71d9-599f-8b39-f86b62b54932', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
