insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6592cd09-aa31-5934-b8e1-d918e32fa277', 'When You Come Back to Me', NULL, '9783736317970', 'Holden Parrish ist ein brillanter Geist - und bis ins tiefste Innere zerbrochen. Er hat sich geschworen, niemals wieder anderen Macht über sich zu geben, und flüchtet mit Zynismus, Alkohol und bedeutungslosen One-Night-Stands vor jeglicher Nähe. Nur noch ein Jahr Highschool, bevor er endlich sein Milliardenvermögen erbt und sich aus dem Staub machen kann. Was er am wenigsten erwartet hat, ist, sich zu verlieben. Ausgerechnet in River Whitmore, den Star-Quarterback der Footballmannschaft! Doch bald erkennt Holden, dass River eine Lüge lebt und die explosiven Gefühle zwischen ihnen nicht nur seine eigene eisern auf-rechterhaltene Fassade zum Einsturz bringen könnten ...', '23.12.2022', 'LYX', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Holden Parrish','River Whitmore']::text[], '{}', '{}', '99e9d13a-19bc-5def-9f69-a88c2d69fb86', '2', '{}', 'sheet', :'owner') on conflict do nothing;
