insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fa89082c-1b0b-5ad6-8f7d-69ff684236f8', 'The Last Piece of His Heart', NULL, '9783736318045', 'Ronan Wentz hat die Hölle gesehen. Nachts durchstreift er die Straßen, um seinen Albträumen und seiner Wut zu entfliehen. Da trifft er Shiloh, die clever und kreativ ist und scheinbar ihr Leben völlig im Griff hat. Doch alles, was Shiloh tut, hat nur ein Ziel: die Zuneigung ihrer Mutter zu gewinnen, welche ihren Anblick kaum ertragen kann. An Liebe glaubt keiner der beiden, aber die Anziehungskraft und aufkeimenden Gefühle zwischen ihnen ist zu stark, um sie zu ignorieren. Bis eine Nacht alles zum Einsturz bringt und sie sich entscheiden müssen, ob sie zulassen wollen, dass ihre Vergangenheit weiterhin ihre Zukunft bestimmt.', '28.04.2023', 'LYX', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ronan Wentz','Shiloh']::text[], '{}', '{}', '99e9d13a-19bc-5def-9f69-a88c2d69fb86', '3', '{}', 'sheet', :'owner') on conflict do nothing;
