insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('158104e2-689b-58da-a736-197d6b0c8795', 'The Night Circus', NULL, '9780099554790', 'The circus arrives without warning. It is simply there, when yesterday it was not. Against the grey sky the towering tents are striped black and white. A sign hanging upon an iron gates reads: Opens at Nightfall. Closes at Dawn. Full of breath-taking amazements and open only at night, Le Cirque des Rêves seems to cast a spell over all who wander its circular paths. But behind the glittering acrobats, fortune-tellers and contortionists a fierce competition is underway. Celia and Marco are two young magicians who have been trained since childhood for a deadly duel. With the lives of everyone at the Circus of Dreams at stake, they must test the very limits of the imagination, and of their love.', '24.05.2012', 'Vintage Books', ARRAY['Englisch']::text[], 486, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, 'The Night Circus', '{}', ARRAY['Celia','Marco']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
