insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('478ced7d-7dc5-5d75-b4ee-e1fb8fa78964', 'Mit Büchern leben-  Buchliebhaber und ihre Bibliotheken', 'At Home with Books: How Booklovers Live with and Care for Their Libraries', '9783763246205', 'Mit Büchern leben stellt 40 Bibliotheken und ihre Besitzer vor - Bücherliebhaber, die sich über ihre zwanghafte, verzehrende Besessenheit definieren, ihre Buchbestände unablässig zu mehren. Bücher sind Sinn und Inhalt ihres Lebens, Bücher bestimmen ihre Interessen, Berufe und Wertvorstellungen. Der ausführliche Anhang wurde für diese Sonderausgabe vollständig überarbeitet. Er ist eine Fundgrube und enthält die ersten Adressen für: Antiquariate und Auktionshäuser, Antiquariatsmessen, Buchbinder und Restauratoren, Bibliothekseinrichtung, Beleuchtung, Accessoires und Zubehör sowie künstlerische Buchobjekte in Deutschland, Österreich, der Schweiz, Großbritannien und den USA.', '01.01.1997', 'Gerstenberg Verlag', ARRAY['Deutsch']::text[], 256, NULL, 'Bildband'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kunst & Kultur', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
