insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5467da31-e056-552c-9c9e-cc5cbe805b46', 'Dark Love - Dich darf ich nicht liebe', 'Did I Mention I Love You', '9783641184735', 'Die 16-jährige Eden ist genervt: Sie soll den ganzen Sommer bei ihrem Vater verbringen, der eine neue Frau geheiratet hat. Immerhin wohnt er in Los Angeles, und so hofft Eden auf heiße Nachmittage am Strand und coole Partys. Nie jedoch hätte sie sich träumen lassen, was sie dort erwartet: nämlich ihr absolut unmöglicher neuer Stiefbruder, der 17-jährige Tyler. Der pöbelt sich durch die gepflegte Willkommensparty, beleidigt alle, inklusive Eden, und zieht türenschlagend wieder ab. Eden ist zugleich abgestoßen und fasziniert von ihm. Denn seine smaragdgrünen Augen verraten, dass irgendwo in ihm eine sehr verletzliche Seele ist, die sich mit extrem grobem Äußeren panzert. Und auch Tyler scheint wider Willen von Eden angezogen zu sein …', '11.04.2016', 'Heyne', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Eden','Tyler']::text[], '{}', '{}', '13e94755-3441-550f-ac65-c8d834ef5662', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ed3dd618-9aef-5d9b-b38b-4c6dc2308271', :'owner', '5467da31-e056-552c-9c9e-cc5cbe805b46', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e9bb21e6-b34d-56b2-b4c8-5734008f3355', 'Dark Love - Dich darf ich nicht finden', 'Did I Mention I Need You', '9783641184742', 'Vor genau dreihundertneunundfünzig Tagen hat Eden ihn zuletzt gesehen – ihren Stiefbruder Tyler. Den Jungen, den sie heimlich liebt. Den sie aber eigentlich nicht lieben darf, weil ihre Familie strikt dagegen ist. Doch nun endlich werden sie einen herrlichen Sommer gemeinsam verbringen: in New York, der Stadt, die nie schläft. Mit tausend Schmetterlingen im Bauch kommt Eden am Flughafen an, und als sie in Tylers smaragdgrüne Augen blickt, ist es auch schon um sie geschehen. Gemeinsam streifen sie durch den Big Apple, und es wird immer klarer, dass die beiden nicht voneinander losgekommen sind. Werden sie ihren verbotenen Gefühlen widerstehen können?', '13.06.2016', 'Heyne', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Eden','Tyler']::text[], '{}', '{}', '13e94755-3441-550f-ac65-c8d834ef5662', '2', '{}', 'sheet', :'owner') on conflict do nothing;
