insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('426a77fa-82cc-5786-b88a-136792e48771', 'Dark Love - Dich darf ich nicht begehren', 'Did I Mention I Miss You', '9783641184759', 'Zwischen Tyler und Eden war es von Anfang an die große Liebe - tief, echt und kompromisslos. Als Tyler einfach abhaut, weil er den Konflikt mit seiner Familie nicht erträgt, ist Eden tief verletzt. Um Tyler endgültig zu vergessen, geht sie zum Studium nach Chicago und stürzt sich sogar in eine halbherzige Beziehung zu einem anderen Jungen. Doch kaum steht sie Tyler in den Semesterferien wieder gegenüber, muss Eden feststellen: Sie kommt einfach nicht über ihn hinweg. Und Tyler geht es genauso, ob er will oder nicht. Wird er nun endlich über seinen Schatten springen und sich zu Eden bekennen, koste es, was es wolle?', '19.09.2016', 'Heyne', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Eden','Tyler']::text[], '{}', '{}', '13e94755-3441-550f-ac65-c8d834ef5662', '3', '{}', 'sheet', :'owner') on conflict do nothing;
