insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('83eda1a0-b70b-59e8-b763-dda55e24e9cb', 'Pandora - Wovon träumst du?', NULL, '9783641182854', 'Sophie lebt in einer Welt, in der alle durch einen Chip im Kopf jederzeit unbeschwert online gehen können. Als sie erfährt, dass sie adoptiert ist und eine Zwillingsschwester hat, erkunden die Mädchen damit ihre Vergangenheit – und stoßen schon bald auf seltsame Geheimnisse. Ihre Recherchen bringen den Sandman auf ihre Spur. Er will die Menschheit mithilfe eines perfekt getarnten Überwachungssystems beherrschen, und nur die Zwillinge können ihn und seine allmächtige NeuroLink Solutions Inc. zu Fall bringen. Doch das bringt sie in höchste Gefahr ...', '11.04.2016', 'Penguin Random House', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], NULL, NULL, NULL, '{}', ARRAY['Sophie','Liz']::text[], '{}', '{}', '3682486f-7223-510b-ad00-e47de1d98bca', '1', '{}', 'sheet', :'owner') on conflict do nothing;
