insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('784dbb13-a03b-5e82-804a-09cb42b48cd7', 'Die Namen', 'The Names', '9783751791540', 'Es ist 1987 und Cora ist auf dem Weg zum Amt, um die Geburt ihres Sohnes anzumelden - und seinen Namen. Noch ahnt sie nicht, wie sehr dieser Moment ihr Leben und das ihres Sohnes prägen wird. Coras Mann Gordon, ein allseits beliebter Arzt, erwartet, dass sein Sohn nach alter Tradition den Namen des Vaters bekommt - und somit den von Generationen herrischer Männer vor ihm. Ihre Tochter Maia möchte den kleinen Bruder Bear nennen, und Cora selbst bevorzugt Julian, in der Hoffnung, dass ihr Sohn sich so zu einer eigenständigen Persönlichkeit entwickeln kann.', '02.03.2026', 'Eichborn', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Cora']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
