insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cd72d55e-be78-522d-8e66-8dca840ba278', 'Sturm im Elfenland', NULL, '9783760763736', 'Im Elfenland herrscht Unruhe. Seit König Auberon die Ausübung von Magie verboten hat, regt sich im ganzen Reich Widerstand. Das Leben der jungen Elfe Alana verläuft jedoch unbeschwert - bis eines Tages unerwarteter Besuch auf das Gut ihres Vaters kommt: Der junge Elf Ivaylo soll in Alanas Familie eine neue Heimat finden. Doch bald erkennt Alana, dass der geheimnisvolle Junge in den alten magischen Künsten bewandert ist… Was ist das Geheimnis des Sternensteins, den Ivaylo bei sich trägt? Und warum öffnen sich plötzlich überall im Elfenland gefährliche Dämonentore? Tiefer und tiefer gerät Alana in einen Strudel mysteriöser Ereignisse… doch wie kann sie ihren Gefühlen trauen, wenn sie dabei ist, sich in einen Verräter zu verlieben? Ein faszinierender Roman über die Abenteuer und die Liebe einer jungen Elfe.', '16.02.2011', 'arsEdition', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Alana']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
