insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8e44af9-f653-5a57-a3a8-9849afacd9a1', 'Korea fürs Handgepäck', NULL, '9783293205765', 'Mirok Li flieht vor den japanischen Besatzern - Basil Hall trifft auf skeptische Eingeborene - Juliette Morillot berichtet vom Schicksal der Trostfrauen - Wan-Seo Park kostet den Wein der Korea-Kirsche - Jürgen Kremb blickt über die Grenze nach Norden Jonas Ley mag die einheimische Küche - Barbara Demick begleitet einen nordkoreanischen Flüchtling - Munyol Yi erlebt den Sturz eines Despoten - Vera Hohleiter ist Gast auf einer Hochzeit - Simon Winchester entziffert das koreanische Alphabet - Dies und vieles mehr über Korea', '24.09.2012', 'Unionsverlag', ARRAY['Deutsch','Koreanisch']::text[], 192, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Reisen', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
