insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d80e69be-50f6-5339-8d0f-9d8d5b4df39d', 'Dune', NULL, '9780441172719', 'A game of power, only those who can conquer their fear will survive. Melange, or ''spice'', is the most valuable - and rarest - element in the universe. And it can only be found on a single planet: the inhospitable desert world Arrakis.Whoever controls Arrakis controls the spice. And whoever controls the spice controls the universe. When stewardship of Arrakis is transferred to his house, Paul Atreides must travel to the planet''s dangerous surface to ensure the future of his family and his people. But as malevolent forces explode into conflict around him, Paul is thrust into a great destiny beyond his understanding.', '01.08.1965', 'ACE', ARRAY['Englisch']::text[], 867, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Space Opera']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, 'Arrakis', '{}', ARRAY['Paul Atreides']::text[], '{}', '{}', '927e00aa-4f7f-5622-9e69-db1ba9994a90', '1', '{}', 'sheet', :'owner') on conflict do nothing;
