insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('259de074-3c06-53b9-8b65-50fde344d173', 'Keine Angst', NULL, '9783863580513', 'Nervenkitzel garantiert: Dreizehn Geschichten aus Unterwelt und Schattenwelt. Teils erschreckend, teils komisch, immer spannend. Frank Schätzing, der Meister des Thrillers, beweist in diesem Buch, dass er auch die kurze Form souverän beherrscht. „Eine Fingerübung durch sämtliche kriminologischen Topoi und Tatmuster“ (Kölner Stadt-Anzeiger). Also keine Angst … oder doch?', '12.12.2011', 'Goldmann', ARRAY['Deutsch']::text[], 220, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Psychologie', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
