insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b0834892-f700-5d03-b7fa-ed108ae94efc', 'Lautlos', NULL, '9783863580520', 'Sieht Dr. Liam O’Connor, genialer Physiker und Bestsellerautor, Gespenster? Wird Köln wirklich von einer unbekannten Macht unterwandert, wenige Tage bevor hier die weltpolitische Elite zum G-8-Gipfel zusammenkommt? Tatsächlich stößt O’Connor auf eine Verschwörung und eine unheimliche Waffe, die einen neuen Kalten Krieg auslösen könnte. In einem atemlosen Katz- und Mausspiel versucht er, die Katastrophe zu verhindern. Doch die Gegner scheinen immer einen Schritt voraus zu sein…', '12.12.2011', 'Goldmann', ARRAY['Deutsch']::text[], 704, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', '{}', 'Adult'::audience_kind, NULL, 'Köln', '{}', ARRAY['Liam O''Connor']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
