insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('91a9e5df-0994-5c29-a2bb-54464d32e28b', 'Nachrichten aus dem unbekannten Universum', NULL, NULL, 'Mensch und Meer - eine Beziehung geprägt von Faszination und Unkenntnis zugleich. Wie entstand das Leben im Urozean und woher stammt die unvorstellbare Menge an Wasser? Warum ging die Evolution ausgerechnet diesen Weg und keinen anderen? Mit Sachverstand und einer Prise Ironie nimmt uns Bestsellerautor Frank Schätzing in seinem Sachbuch Nachrichten aus einem unbekannten Universum mit auf eine Reise vom Urknall bis in die kommenden 100.000 Jahre.', '01.06.2009', 'Kiepenheuer & Witsch', ARRAY['Deutsch']::text[], 864, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Wissenschaft', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
