insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('929044bc-ea37-5e3e-ae4c-74795cb044a5', 'Der Schwarm', NULL, '9783462033748', 'Vor Peru verschwindet ein Fischer. Spurlos. Norwegische Ölbohrexperten stoßen auf merkwürdige Organismen, die Hunderte Quadratkilometer Meeresboden in Besitz genommen haben. Währenddessen geht mit den Walen entlang der Küste British Columbias eine unheimliche Veränderung vor. Nichts von alledem scheint miteinander in Zusammenhang zu stehen. Doch Sigur Johanson, Biologe und Schöngeist, glaubt nicht an Zufälle. Auch der indianische Walforscher Leon Anawak gelangt zu beunruhigenden Schlüssen: Eine Katastrophe kündigt sich an. Die Suche nach dem Urheber konfrontiert die Forscher mit ihren schlimmsten Albträumen. Frank Schätzing inszeniert den Feldzug der Natur gegen den Menschen als atemberaubendes Schreckensszenario mit Tempo und Tiefgang.', '17.02.2004', 'Kiepenheuer & Witsch', ARRAY['Deutsch']::text[], 992, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, NULL, 'Weltweit', '{}', ARRAY['Leon Anawak','Sigur Johanson','Judith Li','Jack „Greywolf“ O’Bannon','Tina Lund','...']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
