insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7dcc4bd5-5c7e-51e6-81de-ad516e7d4453', 'Limit', NULL, '9783462037043', '2025: Bahnbrechende Technologien haben die Raumfahrt revolutioniert. In einem atemlosen Wettlauf fördern Amerikaner und Chinesen auf dem Mond Helium-3, ein Element, das sämtliche Energieprobleme der Welt zu lösen verspricht. Zur selben Zeit soll Detektiv Owen Jericho in Shanghai die untergetauchte Dissidentin Yoyo ausfindig machen. Was nach Routine klingt, entwickelt sich zu einer albtraumhaften Jagd, denn die ebenso schöne wie anstrengende Chinesin ist im Besitz streng gehüteter Geheimnisse und ihres Lebens nicht mehr sicher. Die Spur führt rund um den Erdball - und zum Mond, wo eine Gruppe Weltraumtouristen eine bedrohliche Entdeckung macht.', '05.10.2009', 'Fischer', ARRAY['Deutsch']::text[], 1312, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Owen Jericho']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
