insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6b05a1a-80ba-5004-8810-aa2d9c9e067e', 'Frühlings Erwachen', NULL, '9783150079515', 'Melchior möchte seinem ängstlichen und durch das Erwachsenwerden verunsicherten Freund Moritz helfen, indem er eine Aufklärungsschrift für ihn verfasst. Doch anstatt ihm zu helfen, verstört diese den Jungen nur noch mehr, sodass Moritz sich schließlich verzweifelt das Leben nimmt. Eines Tages trifft Melchior Wendla und sie verlieben sich ineinander. Als Wendla von Melchior schwanger wird, veranlasst ihre Mutter eine Abtreibung, die die Jugendliche jedoch nicht überlebt. Nachdem man bei Moritz Melchiors Aufklärungsschrift gefunden hat, geben die Lehrer ihm die Schuld für den Selbstmord und er muss die Schule verlassen und fortan in einer Erziehungsanstalt leben. Am Grab Wendlas begegnen sich Melchior und der tote Moritz noch einmal, doch als der Tote Melchior ermutigen will, sich auch das Leben zu nehmen, zieht ihn ein „vermummter Herr“ von Moritz fort. Lebendig stellt Wedekind die auch heute noch aktuellen schulischen und sexuellen Probleme Jugendlicher und die Folgen, die mangelhaftes Einführungsvermögen seitens der Eltern und Lehrer und versäumte Aufklärung haben können, dar.', '1891', 'Reclam', ARRAY['Deutsch']::text[], 112, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Melchior Gabo','Moritz Stiefel','Wendla Bergmann','vermummter Herr','...']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
