insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('58200995-4124-54a3-9b65-a41bd5efc110', 'Das Schloss', NULL, NULL, 'Eines Nachts gelangt der Landvermesser K. in ein Dorf, dessen Geschicke von einer geheimnisvollen Macht, dem Schloss, gelenkt werden. Er ersucht dort um eine Anstellung, die ihm jedoch verwehrt wird. Der Grund für diese Ablehnung bleibt ebenso im Dunkeln wie die Natur des ominösen Schlosses und K. beginnt einen aussichtslos scheinenden Kampf um seine Anerkennung.', '1922', NULL, ARRAY['Deutsch']::text[], 240, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['K.']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
