insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2ca7330b-6408-5d04-bf4b-3648f18f0ff0', 'One By One', NULL, '9781464221392', 'A night spent sleeping on dirt and leaves is not how Claire Matchett expected to spend her vacation. She thought this would be a break from the stresses of work and raising her young children. A chance to repair her damaged marriage. A week of hiking and hot tubs with friends. It sounded like heaven. Then Claire''s minivan breaks down on a lonely dirt road. With no cell reception, the group has no choice but to hike the rest of the way to their hotel. But it turns out the woods aren''t as easy to navigate as they thought. Hours later, they are lost. Hopelessly lost. And as they navigate deeper into the woods, the members of their party are struck down mysteriously one by one. Has a wild animal been hunting them? Or is the hunter one of them? But as more time passes, one thing becomes clear: Only one of them will return home alive.', '02.04.2024', 'Poisoned Pen', ARRAY['Englisch']::text[], 260, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Im Wald', '{}', ARRAY['Claire Matchett']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
