insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b45f5dc3-f677-5056-ac81-eb98ee960fc9', 'Prinz sucht Bräutigam', 'Zettai Kyuuai Prince', '9782889510009', '„Hab ich dich gefunden … mein Bräutigam!“ Mit diesen Worten wird Yuki, Student und Sohn hoch verschuldeter Eltern, von einem edlen Prinzen überrascht – und geküsst! Der Prinz hört auf den fremdländischen Namen Julian, und angeblich haben er und Yuki sich schon vor Jahren ein Heiratsversprechen gegeben. Allerdings kann sich Yuki daran überhaupt nicht erinnern. Doch ein Prinz hat eben Geld. Und nichts braucht Yuki dringender als das …', '05.12.2019', 'Kaze Manga', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Yuki','Julian']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
