insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c10babde-7c18-5e05-879e-e61175ed984b', 'Bibliotheca Mysteria (Vol.1)', NULL, NULL, 'Huey erbt von seinem verstorbenen Großvater Dantalians mystisches Bücherarchiv, das auch magische Bücher umfassen soll, in denen das Wissen und die Einsichten des Bösen niedergeschrieben sind. Mit dem Antritt seines Erbes spürt er auch die Verantwortung, die nun auf seinen Schultern lastet, und so bereist er zusammen mit dem stets in schwarz gekleideten Mädchen namens Dalian, das über spezielle Kräfte verfügt, allerlei geheimnisvolle Orte, um die in alle Winde verstreuten, verbotenen „Magischen Bücher“ aufzuspüren … Ein Fantasy-Mystery-Manga von Chako Abeno („Chrome Breaker“) der süchtig macht – aber Vorsicht … nichts für schwache Nerven!', '2012', 'Egmont Manga', ARRAY['Deutsch']::text[], 196, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Dantalians mystisches Bücherarchiv', ARRAY['3P Objective']::text[], ARRAY['Huey']::text[], '{}', '{}', '119096ca-8d86-5144-9550-82e74e670c53', '1', '{}', 'sheet', :'owner') on conflict do nothing;
