insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('da8bf5cb-0ca0-52c1-ab31-11deb3d09d3d', 'Royal Passion', 'Command Me', '9783641182007', 'Auf ihrer Abschlussfeier an der Oxford University trifft Clara Bishop auf einen attraktiven Fremden. Ohne Vorwarnung zieht er sie an sich, küsst sie leidenschaftlich und verschwindet. Clara hat keine Ahnung, wer der Unbekannte ist – bis ein Bild von ihnen beiden in der Zeitung auftaucht: Ihr heißer Flirt ist Prinz Alexander von Cambridge, Thronfolger von England, königlicher Bad Boy … Dieser Mann ist gefährlich, in ihm lauern Abgründe, die Clara ins Verderben stürzen können. Ist Clara dieser magischen Anziehungskraft gewachsen?', '14.12.2015', 'blanvalet', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'England', '{}', ARRAY['Clara Bishop','Prinz Alexander von Cambridge']::text[], '{}', '{}', 'a7b38e67-8d18-56f9-9592-543f306d4095', '1', '{}', 'sheet', :'owner') on conflict do nothing;
