insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fcad115d-20ab-5ed3-ad79-6bc5677f86b2', 'Royal Desire', 'Conquer Me', '9783641182014', 'Enttäuscht und verletzt hat Clara ihre Beziehung zu Prinz Alexander nach einer letzten gemeinsamen Nacht beendet. Sie stürzt sich in die Arbeit, um ihn zu vergessen – vergeblich. Die Erinnerungen an ihn, an ihre gemeinsame Zeit lassen sich nicht auslöschen. Und Alexander ist kein Mann, der so leicht aufgibt. Kann er Clara von seiner wahren Liebe überzeugen? Und wird sie zu ihm stehen, wenn er seine dunkle Vergangenheit vor ihr enthüllt?', '15.02.2016', 'blanvalet', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'England', '{}', ARRAY['Clara Bishop','Prinz Alexander von Cambridge']::text[], '{}', '{}', 'a7b38e67-8d18-56f9-9592-543f306d4095', '2', '{}', 'sheet', :'owner') on conflict do nothing;
