insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('62b6f542-962b-5939-a2b0-868150e38bb2', 'Royal Love', 'Crown Me', '9783641182021', 'In wenigen Wochen wird sie den Mann heiraten, den sie liebt, dem sie verfallen ist mit Körper, Herz und Seele. Doch Alexanders Vater lehnt ihre Verbindung kategorisch ab, und Clara findet heraus, dass Alexander immer noch Geheimnisse vor ihr hat und sie heimlich beschatten lässt. Clara liebt Alexander, aber kann sie ihm auch vertrauen? Und ist ihre Liebe stark genug, um ihre Unabhängigkeit und ihr eigenes Leben für das Königshaus zu opfern?', '18.04.2016', 'blanvalet', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'England', '{}', ARRAY['Clara Bishop','Prinz Alexander von Cambridge']::text[], '{}', '{}', 'a7b38e67-8d18-56f9-9592-543f306d4095', '3', '{}', 'sheet', :'owner') on conflict do nothing;
