insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3c0107a7-27fe-52f1-9367-8098261d59da', 'Game of Hearts', 'By Invitation Only', '9783734104831', 'Als Emma Southerly auf einer exklusiven Party, auf der sie eigentlich weder sein will noch erwünscht ist, den attraktiven, geheimnisvollen Jamie trifft, klopft ihr Herz vom ersten Augenblick an einen Takt schneller. Wer ist dieser Mann mit dem raubtierhaften Charme, und warum fühlt sie sich so zu ihm hingezogen? Trotz aller Bedenken verbringt sie eine leidenschaftliche Nacht mit ihm, die sie so schnell nicht vergessen wird – auch, weil es am nächsten Morgen in Las Vegas nur ein Thema gibt: Eine Leiche wurde gefunden – und Jamie ist der Hauptverdächtige. Aber er war doch die ganze Nacht bei ihr, oder etwa nicht?', '18.12.2017', 'blanvalet', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Las Vegas', '{}', ARRAY['Emma Southerly']::text[], '{}', '{}', '8f614181-e4eb-5a3d-bd6d-b9f5770f13d8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
