insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d907d793-f46e-5233-82b4-e25d33b23cd4', 'Night Head Genesis (Vol.3)', NULL, '9783551785183', 'Bei einer Begegnung mit ihren Eltern erfahren Naoto und Naoya, dass diese sie mittlerweile für tot halten, und müssen wieder erleben, dass ein normales Leben für sie nicht möglich ist. Kurz darauf geraten sie in die Fänge der Ark Corporation, einer einflussreichen Organisation, die ihre Finger in mysteriösen Aktivitäten hat. Die Vorsitzende Akiko Okuhara versucht die Brüder auf ihre Seite zu ziehen, doch was sie wirklich im Schilde führt, wird Naoto und Naoya erst nach und nach klar...', '27.05.2011', 'Carlsen', ARRAY['Deutsch']::text[], 232, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Action']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Naoto','Naoya']::text[], '{}', '{}', '237fa2ea-aa6a-5031-b0b1-abaa0153506f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
