insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('429a72f8-0da8-5cc8-8675-661a961882b5', 'Gone Girl - Das perfekte Opfer', 'Gone Girl', '9783596520725', '„Was denkst du gerade, Amy?” Diese Frage habe ich ihr oft während unserer Ehe gestellt. Ich glaube, das fragt man sich immer wieder: Was denkst du? Wer bist du? Wie gut kennt man eigentlich den Menschen, den man liebt? Genau diese Fragen stellt sich Nick Dunne am Morgen seines fünften Hochzeitstages, dem Morgen, an dem seine Frau Amy spurlos verschwindet. Die Polizei verdächtigt sogleich Nick. Amys Freunde berichten, dass sie Angst vor ihm hatte. Er schwört, dass das nicht wahr ist. Dann erhält er sonderbare Anrufe. Was geschah mit Nicks wunderbarer Frau Amy? Selten wurde so raffiniert, abgründig und brillant manipuliert wie in diesem Psychogramm einer Ehe - ein teuflisch gutes Lesevergnügen.', '23.07.2015', 'Fischer', ARRAY['Deutsch']::text[], 832, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Nick Dunne']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
