insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('16a6a6cc-1078-5d99-aec5-a2c5a5d7b5d1', 'Romeo und Julia auf dem Dorfe', NULL, '9783150061725', 'Romeo und Julia auf dem Dorfe, geschrieben von Gottfried Keller, gilt zurecht als als Kanon der deutschsprachigen Literatur und wird oft als Schullektüre behandelt. Gottfried Keller Romeo und Julia auf dem Dorfe beschreibt das Schicksal zwei junger Leute, Sohn und Tochter wohlhabender Bauern, die sich trotz der erbitterten Feindschaft ihrer Väter lieben. Nachdem diese Feindschaft den Ruin beider Familien herbeigeführt und die Aussicht der Kinder auf eine gemeinsame Zukunft zerstört hat, sieht das Paar keinen anderen Ausweg, als gemeinsam in den Tod zu gehen. Keller Romeo und Julia gehört in den Bücherschrank eines jedermann.', '1856', 'Reclam', ARRAY['Deutsch']::text[], 68, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Sali','Vrenchen']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
