insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5efdf4ea-f91e-5ad5-a9b2-7a12b54b0d03', 'Das Rosie-Projekt', 'The Rosie Project', '9783596520831', 'Don Tillman will heiraten. Allerdings findet er menschliche Beziehungen oft höchst verwirrend und irrational. Was tun? Don entwickelt das Ehefrau-Projekt: Mit einem 16-seitigen Fragebogen will er auf wissenschaftlich exakte Weise die ideale Frau finden. Also keine, die raucht, trinkt, unpünktlich oder Veganerin ist. Und dann kommt Rosie. Unpünktlich, Barkeeperin, Raucherin. Offensichtlich ungeeignet. Aber Rosie verfolgt ihr eigenes Projekt: Sie sucht ihren biologischen Vater. Dafür braucht sie Dons Kenntnisse als Genetiker. Ohne recht zu verstehen, wie ihm geschieht, lernt Don staunend die Welt jenseits beweisbarer Fakten kennen und stellt fest: Gefühle haben ihre eigene Logik.', '20.08.2015', 'Fischer', ARRAY['Deutsch']::text[], 347, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Don Tillman']::text[], '{}', '{}', '6698ee89-e054-5d3b-ae93-d9ae82c0a033', '1', '{}', 'sheet', :'owner') on conflict do nothing;
