insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('137ab934-3f9d-5fad-afe2-518c2a4b8961', 'Beyond Eternity - Der Schwur der Götter', NULL, '9783473402076', 'Jupiter, Mars, Minerva, Venus: Die alten römischen Gottheiten spielten in Naylas Leben bisher überhaupt keine Rolle. Doch das ändert sich, als sie einen furchtbaren Autounfall hat - und ihn auf unerklärliche Weise unverletzt überlebt. Als kurz darauf die zwei mysteriösen Typen Philemon und Cyrian an Naylas High School auftauchen, spürt sie, dass die beiden etwas verbergen und auch in ihr selbst ein Geheimnis erwacht. Besonders zu dem unnahbaren Cyrian fühlt Nayla sich auf eine fast magische Weise hingezogen. Doch ihre Gefühle haben keine Zukunft, denn ihre Liebe würde Nayla in Lebensgefahr bringen ...', '01.09.2021', 'Ravensburger', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Nayla']::text[], '{}', '{}', 'dff58931-5bf5-542b-b0c1-50f8010f6dfe', '1', '{}', 'sheet', :'owner') on conflict do nothing;
