insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7477cd70-92aa-5872-92ee-102c77ee9c61', 'Das Buch der Zeit - Die steinerne Pforte', NULL, '9783401060705', 'Wer Bücher liest, lebt gefährlich. Das hätte sich Sam niemals träumen lassen, als er eines Tages auf der Suche nach seinem verschollenen Vater ein mysteriöses Buch entdeckt. Doch dieser Fund ist es, der ihn zusammen mit seiner Cousine Lili auf eine Reise schickt, die noch niemand zuvor erlebt hat. Denn Sam und Lili sind auf ein uraltes Geheimnis gestoßen: auf das Buch der Zeit.', '01.01.2006', 'Arena', ARRAY['Deutsch']::text[], 297, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', ARRAY['Sam']::text[], '{}', '{}', '7aa3a93f-d89e-554c-9f21-05d3c34d723a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
