insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fe045171-511a-5e37-a600-e727b707eb76', 'Stranger Things - Suspicious Minds', NULL, '9783641242510', 'A mysterious lab. A sinister scientist. A secret history. If you think you know the truth about Eleven’s mother, prepare to have your mind turned Upside Down. It''s the summer of 1969. The world is changing, and Terry Ives isn''t content to watch from the sidelines. When word gets around about an important government experiment, she signs on as a test subject. But behind the walls of Hawkins National Laboratory – and the piercing gaze of its director, Dr Martin Brenner – lurks a dark conspiracy. To face it, she''ll need the help of her fellow test subjects, including a mysterious young girl with unexplainable powers. . .', '18.02.2019', 'Penguin Random House', ARRAY['Englisch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Terry Ives']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
