insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ffd5adae-7b21-523b-b1c3-2437831978ae', 'Männerlieben', NULL, '9783934442771', 'Ein Soldat an der türkischen Ägäisküste, ein arbeitsloser Jugendlicher ohne Perspektive, ein karrieregeiler Reporter eines amerikanischen Kunstmagazins, ein betrogener Student auf dem Weg durch die Provence, ein Gay-Event-Organisator aus Berlin, sie alle haben eines gemeinsam. Sie sind verliebt – in einen Mann. Entgegen den gesellschaftlichen Konventionen kämpfen sie um ihr Glück.', '17.02.2016', 'Dead Soft', ARRAY['Deutsch']::text[], 94, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
