insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cacaec9f-571f-5b40-9a37-39d43fd35699', 'Icebreaker', NULL, '9781398525689', 'Anastasia Allen has worked her entire life for a shot at Team USA. It looks like everything is going according to plan when she gets a full scholarship to the University of California, Maple Hills and lands a place on their competitive figure skating team. Nothing will stand in her way, not even the captain of the hockey team, Nate Hawkins. Nate''s focus as team captain is on keeping his team on the ice. Which is tricky when a facilities mishap means they are forced to share a rink with the figure skating team-including Anastasia, who clearly can''t stand him. But when Anastasia''s skating partner faces an uncertain future, she may have to look to Nate to take her shot. Sparks fly, but Anastasia isn''t worried . . . because she could never like a hockey player, right?', '10.01.2023', 'Simon & Schuster', ARRAY['Englisch']::text[], 429, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Maple Hills', ARRAY['Double POV','1P']::text[], ARRAY['Anastasia','Nate']::text[], ARRAY['Academy','Sport','Family Drama','Mental Issues']::text[], '{}', '6d732998-ef6b-566c-b90b-25d7b55007d3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
