insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('996f8f15-f803-5548-884b-9a225aee1554', 'Wildfire', NULL, '9781398525719', 'When Russ and Aurora cross paths at a university party, a drinking game ends with them spending the night together. The next day, Aurora slips away before Russ learns her full name. This anonymity ends when they both turn up to their first day of work as camp counsellors. A job they had both chosen to escape Maple Hills for the summer. Given their history, there''s still an obvious tension between the two but the camp has a strict "no staff fraternizing" rule. Russ doesn''t want to risk heading home early but Aurora has never been one for rules. As things heat up, they''ll have to resist or risk starting something they just can''t stop.', '28.03.2024', 'Simon & Schuster', ARRAY['Englisch']::text[], 400, 37, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Summer Camp', ARRAY['Double POV','1P']::text[], ARRAY['Aurora','Russ']::text[], ARRAY['Addiction','Family Drama','First Love','Secret Relationship','Universicy/College','Sport']::text[], '{}', '6d732998-ef6b-566c-b90b-25d7b55007d3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
