insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('dca00cea-92b3-5730-ad5d-864fe99b34af', '871cfa73-6944-5a4e-bd3a-4ad0f1088fad', :'owner', 1, '2025-03-19', '2025-03-23', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('45d8ce14-6136-5ee4-b99b-ffda0f00235d', 'Daydream', NULL, '9783736322486', 'Seit sie denken kann, ist Halle Jacobs für das Glück anderer zuständig. Doch als ihr Freund plötzlich mit ihr Schluss macht, hat sie genug. Sie will endlich ihr eigenes Glück an die erste Stelle setzen und sich ihren Traum erfüllen: einen Liebesroman zu schreiben. Nur fehlen ihr dafür die romantischen Erfahrungen - ein Problem, bei dem ihr ausgerechnet Henry Turner, der neue Captain der UCMH-Eishockeymannschaft, helfen kann. Er bietet Halle einen Deal an: Sie gibt ihm Nachhilfe, damit er den Kurs bei seinem meistgehassten Professor besteht, und dafür hilft er ihr, ihre Schreibblockade aufzulösen. Sie stellen Regeln auf, die garantieren sollen, dass keine echten Gefühle ins Spiel kommen - doch Halle und Henry merken schnell, dass die Liebe keiner Anleitung folgt ...', '23.12.2024', 'LYX', ARRAY['Deutsch']::text[], 528, 40, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Maple Hills', ARRAY['Double POV','1P']::text[], ARRAY['Henry Turner','Halle Jacobs']::text[], ARRAY['Universicy/College','Sport','Friends to Lovers']::text[], '{}', '6d732998-ef6b-566c-b90b-25d7b55007d3', '3', '{}', 'sheet', :'owner') on conflict do nothing;
