insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('561dbbf1-0f21-59d9-ad88-12a30c33405c', 'Holiday Ever After', NULL, '9783736327153', 'Happy Holidays aus Fraser Falls!Statt wie geplant die Karriereleiter im Unternehmen ihrer Familie zu erklimmen, hat Clara Davenport einen PR-Skandal am Hals. Die Spielzeugfirma soll das Design einer Puppe von einem Betrieb aus Fraser Falls gestohlen haben. Kurzerhand reist Clara in die verschneite Kleinstadt, um Schadensbegrenzung zu betreiben. Doch der Erfinder der Holly-Puppe ist ausgerechnet Jack Kelly - der verboten gut aussehende Problemlöser der Stadt, der nicht vorhat, sich ein zweites Mal von einer Davenport übers Ohr hauen zu lassen. Clara will ihm beweisen, dass sie anders ist, und merkt dabei, dass sie ihr Herz nicht nur an die malerische Kleinstadt, sondern auch an Jack verliert', '31.10.2025', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Fraser Falls', '{}', ARRAY['Clara Davenport','Jack Kelly']::text[], ARRAY['Holiday']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
