insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('23bd6df9-9017-5eca-b485-8fd2c0f69eab', 'Apprentice to the Villain', NULL, '9781529917765', 'Evie Sage has never been happier to be the assistant to The Villain. Who would have thought that working for an outrageously handsome (shhh, bad for his brand) evil overlord would be so rewarding? But Rennedawn is in grave trouble, and all signs point to catastrophe. Something peculiar is happening with the kingdom’s magic, and it’s made The Villain’s manor vulnerable to their enemies ... including their nemesis, the king. Now it’s time for Evie to face her greatest challenge: protecting The Villain’s lair, all of his nefarious works, and maybe (provided no one finds out) the entire kingdom. No pressure, Evie. It’s time to step out of her comfort zone and learn new skills. Like treason. Dagger work. Conspiring with the enemy. It’s all so…so…delightfully fun. But what happens when the assistant to The Villain is ready to become his apprentice?', '08.08.2024', 'Penguin', ARRAY['Englisch']::text[], 376, 83, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Rennedawn', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Evie Sage','Trystan Maverine']::text[], ARRAY['Good vs. Evil','Grumpy x Sunshine','Magical Creatures','Work Adversaries','Found Family']::text[], '{}', '220cc934-4c79-5bd9-b23a-5192440af186', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('625e5309-3755-5369-8cda-4dd2215af0a1', :'owner', '23bd6df9-9017-5eca-b485-8fd2c0f69eab', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 807, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 0, 'slow'::burn_kind, 'Es macht einfach richtig Spaß diese Reihe zu lesen. Und ganz abgesehen davon, bin ich total verknallt in Trystan. Für mich ist der zweite Teil genauo gut wie der erste Teil. Einfach genialer Humor und eine tolle Story! Ich finds toll, dass in diesem Band die POV von anderen Charakteren ein wenig mehr in den Fokus gerückt ist.') on conflict do nothing;
