insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e90c8b47-d3dd-54bf-8bab-28dfe9d1c085', 'Accomplice to the Villain', NULL, '9781529917772', 'REWARD OFFERED: Apprentice to The Villain wanted for treason (light), magical property damage (alleged), and one incident involving a weaponized scone (accurate). Frequently seen with a grumpy frog (crowned, judgmental). Answers to “Evie” or “Stop that.” Evie Sage didn’t mean to become the right-hand woman to the kingdom’s most terrifying villain. One minute, she was applying for an entry-level position that promised “light paperwork and occasional beheadings,” and the next, she was knee-deep in magical mayhem, murder plots, and an entirely inappropriate crush on her brooding, sharp-jawed, walking disaster of a boss. Now, with a magical prophecy unraveling, assassins showing up in the break room, and a suspicious amount of frogs wearing crowns, Evie has to figure out how to survive her job without setting the kingdom on fire?or her dignity, which is hanging by a very sarcastic thread. Being evil-adjacent was never part of the five-year plan. But then again…neither was falling for The Villain.', '07.08.2025', 'Penguin', ARRAY['Englisch']::text[], 440, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Rennedawn', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Evie Sage','Trystan Maverine']::text[], ARRAY['Good vs. Evil','Grumpy x Sunshine','Magical Creatures','Work Adversaries','Found Family']::text[], '{}', '220cc934-4c79-5bd9-b23a-5192440af186', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('05f2d5d0-0130-5a5d-9e94-00e089be7747', :'owner', 'e90c8b47-d3dd-54bf-8bab-28dfe9d1c085', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 899, true, false, ARRAY['Audible']::text[], ARRAY['Em Eldridge']::text[], 924, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 0, 'slow'::burn_kind, 'Das Warten darauf, dass sie endlich zusammen kommen, hat mich wahnsinnig gemacht. Und dann in Kapitel 53, wenn man endlich hofft.. und dann... Nope :D Tolles Buch! Ich liebe es, wie sie Stück für Stück ihrem Ziel näher kommen und ich tatsächlich gar nicht mit den Twists gerechnet habe. Vor allem das Ende hat mich wirklich geschockt.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('8975ea75-d1cb-5fe9-b2bf-a54064314cdc', '05f2d5d0-0130-5a5d-9e94-00e089be7747', :'owner', 1, '2025-08-22', '2025-09-02', NULL, NULL, 12, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d6fd9d61-2851-56b6-b000-19e7be45d17c', 'Assistant to the Villain', NULL, '9781804993385', 'With ailing family to support, Evie Sage''s employment status isn''t just important, it''s vital. So, when a mishap with Rennedawn''s most infamous Villain results in a job offer, naturally, she says yes. No job is perfect, of course, but even less so when you develop a teeny crush on your terrifying, temperamental, and undeniably hot boss. Don''t find evil so attractive, Evie. But just when she''s getting used to severed heads suspended from the ceiling and the odd squish of an errant eyeball beneath her heel, Evie suspects this dungeon has a huge rat...and not just the literal kind. Because something rotten is growing in the kingdom of Rennedawn, and someone wants to take the Villain-and his entire nefarious empire-out. Now Evie must not only resist drooling over her boss but also figure out exactly who is sabotaging his work... and ensure he makes them pay. After all, a good job is hard to find....', '14.09.2023', 'Penguin', ARRAY['Englisch']::text[], 340, 60, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Rennedawn', ARRAY['Double POV','2P']::text[], ARRAY['Evie Sage','Trystan Maverine']::text[], ARRAY['Good vs. Evil','Grumpy x Sunshine','Magical Creatures','Work Adversaries','Found Family']::text[], '{}', '220cc934-4c79-5bd9-b23a-5192440af186', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('5ba5ebe2-8178-525d-ba87-1df1793f0f55', :'owner', 'd6fd9d61-2851-56b6-b000-19e7be45d17c', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 849, true, false, '{}', '{}', NULL, NULL, false, 'group'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Ich glaube ich habe noch nie ein so verdammt witziges Buch gelesen. Dieser trockene Humor und der ständige Sarkasmus ist einfach genau meins! Definitiv eins meiner Jahres-Highlights. Schon lange kein Buch mehr gelesen, dass mich so begeistert hat und mich auch gleichzeitig so überrascht hat. Ganz toll.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('8d6a8270-686d-5d31-8b17-fbbe9e2c57d2', '5ba5ebe2-8178-525d-ba87-1df1793f0f55', :'owner', 1, '2025-06-01', '2025-06-29', NULL, NULL, 29, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('991a76ad-86d8-5eaa-a4d3-051049a53b5f', 'Adversary to the Villain', NULL, '9781804999677', 'Evie has always tried to be helpful, loyal, and only mildly involved in treason. But with a dangerous prophecy threatening the very magic of Rennedawn - not to mention the race to claim its necessary artifacts before King Benedict does - things are starting to feel... less like a career path and more like a serious problem. The prophecy won''t stop pointing in Evie''s direction. The Villain''s magic keeps choosing her. And honestly, if you''re going to be accused of evil anyway, you might as well commit. Unfortunately, the more Evie leans into her alleged villain era, the more her boss starts acting like the hero of a completely different story. Trystan is getting closer - closer than is wise, advisable, or even remotely professional - and looking at her like she''s already chosen a side. His. Which is deeply inconvenient, because if Evie can''t save the kingdom''s magic, she might just become its greatest threat.', '06.08.2026', 'Penguin', ARRAY['Englisch']::text[], 325, 82, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Rennedawn', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Evie Sage','Trystan Maverine']::text[], ARRAY['Good vs. Evil','Grumpy x Sunshine','Magical Creatures','Work Adversaries','Found Family']::text[], '{}', '220cc934-4c79-5bd9-b23a-5192440af186', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('9df5db17-1085-5a97-bb4c-94330518cb36', :'owner', '991a76ad-86d8-5eaa-a4d3-051049a53b5f', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['Taschenbuch','eBook']::text[], 'Normal', ARRAY['Map']::text[], 1349, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'untertroffen'::expectation_kind, NULL, 'slow'::burn_kind, 'Ich mag noch immer den Humor und die Charaktere der Geschichte, aber irgendwie ist einfach nichts passiert in diesem Buch, was dazu geführt hat, dass ich irgendwann gelangweilt war. Sehr schade. Das Ende verspricht jedoch, dass der nächste Teil interessant wird.') on conflict do nothing;
