insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('508091bb-cda6-54d3-a32a-28a6b6570e36', 'A Little Life', NULL, '9780804172707', 'A Little Life follows four college classmates—broke, adrift, and buoyed only by their friendship and ambition—as they move to New York in search of fame and fortune. While their relationships, which are tinged by addiction, success, and pride, deepen over the decades, the men are held together by their devotion to the brilliant, enigmatic Jude, a man scarred by an unspeakable childhood trauma. A hymn to brotherly bonds and a masterful depiction of love in the twenty-first century, Hanya Yanagihara’s stunning novel is about the families we are born into, and those that we make for ourselves.', '26.01.2016', 'Random House LLC US', ARRAY['Englisch']::text[], 814, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['JB','Jude','Malcolm','Willem']::text[], ARRAY['Found Family']::text[], ARRAY['Physische Gewalt','Sexuelle Gewalt','Toxische Beziehungsdynamiken','SVV','Psychische Erkrankung/Belastung','Drogenmissbrauch','Depiction of Trauma','Ableismus','Essstörung','Tod','Krankheit','Suizidalität']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('661c302c-cb8a-5f06-94bb-84885f2c68f4', '508091bb-cda6-54d3-a32a-28a6b6570e36', 'Musical/Theater') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('8c98473e-b2af-5814-b318-bf9de258925e', :'owner', '508091bb-cda6-54d3-a32a-28a6b6570e36', 'gelesen'::reading_status, true, false, ARRAY['Print','Audiobook']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1099, NULL, NULL, ARRAY['Spotify','Audible']::text[], ARRAY['Matt Bomer']::text[], 1718, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Ich weiß gar nicht wo ich anfangen soll bei diesem Buch. Es ist mir sehr schwer gefallen dieses Buch zu lesen aus verschiedenen Gründen. Aber selten hat ein Buch es geschafft so viele Emotionen in mir hervorzurufen. Vor allem aber auch sehr viele negative Emotionen: Trauer, Wut und so viel Frusttration. Oft musste ich das Buch aus der Hand legen und erst mal wieder klarkommen. Ich würde das Buch nicht als "schön" bezeichnen aber als wirklich wirklich gut.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('290d06e3-2985-5159-8949-eb5ae47091cf', '8c98473e-b2af-5814-b318-bf9de258925e', :'owner', 1, '2026-06-19', '2026-07-21', NULL, NULL, 33, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d53942a0-b8d8-5b99-83d0-57bb4d738203', 'Knotting With a Stranger', NULL, NULL, 'It started with a message to the wrong number… now I’m craving a stranger. Running the bakery with my sister is my life–early mornings, endless dough, and just enough sugar to keep me sane. I don’t have time for distractions.But when I accidentally text a stranger, everything changes.He’s not just mysterious–he’s sharp-tongued, wickedly charming, and far too good at making me forget common sense. What starts as playful banter turns into something more… something that stirs my Omega instincts in ways I don’t understand. His words make me burn, his voice wraps around me like a promise, and when he finally asks to meet… I panic.Because no one this intense, this consuming, can be real.I tell myself to forget him, but fate has other plans. A snowstorm, a wrong turn… and suddenly I’m face-to-face with the man who’s haunted my thoughts. Only he’s not alone. His world is sharp edges and whispered threats, tangled in power plays and ruthless Alphas.I should walk away. But his touch ignites something primal inside me, and resisting him feels impossible.He says I belong to him.But in a world ruled by Alphas, giving in might mean losing myself… and I’m not sure I’ll make it out whole.This standalone Cozy Omegaverse romance is filled with slow-burning tension, and a thrilling edge that’ll leave you breathless.', '31.03.2025', NULL, ARRAY['Englisch']::text[], 436, 19, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lily']::text[], ARRAY['Omegaverse']::text[], '{}', 'eb9e4ee7-7ac9-5695-9b68-510998317c79', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('f1c8ee20-f4bf-58e2-8059-425f70ae2d56', :'owner', 'd53942a0-b8d8-5b99-83d0-57bb4d738203', 'tbr'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 499, false, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e2651939-ba2b-57d8-9879-b163f3a7deb6', 'What Lies Beyond the Veil', NULL, '9781399711685', 'Once, we''d worshipped them as Gods. For nearly 400 years, the Veil has protected us from the Fae of Alfheimr. In their absence, our lives have shifted from decadence and sin to survival and virtue under the guidance of the New Gods. I''ve spent my entire life tending to the gardens next to the boundary between our worlds, drawn to the shimmering magic like a moth to the flame. Then, we died on their swords. All of that changes the day the Veil shatters, unleashing the fae upon our world once again. The magic of faerie marks those of us they mean to take, but the Mist Guard protecting Nothrek will kill us all before they let the fae have us. There''s no choice but to flee everything I''ve ever known, not if I want to live to see my twenty-first birthday as a free woman. Now, they''ll claim what''s theirs. But before they capture me, Caelum saves me from the Wild Hunt. Fae-marked and on the run, he is able to fight back in ways I only dream of. From tentative alliance to all-consuming passion, our bond strengthens as the fae close in and evil lurks ever nearer. With my life on the line, he is everything I shouldn''t dare to want and a distraction I can''t afford. I can''t seem to stay away, not even with something greater on the line. My heart.', '30.08.2022', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, NULL, 'Alfheimr', '{}', ARRAY['Estrella','Caelum']::text[], '{}', '{}', '8c2f9e0f-7fa6-5697-b10a-96e59f7e71c6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
