insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5a2f9d66-53a0-5786-a49f-1b47331fe21a', 'Eine Frau - Ein Buch', NULL, '9783442472505', 'Was jede Frau über das Leben wissen sollte: Wie kommt man in jeden Klub? Wie parkt man einen LKW ein? Wie erkennt man einen Diamanten? Oder: Wie heult man auf Kommando los? Nach dem Bestseller „Ein Mann. Ein Buch.“ kommt nun DAS Buch für Frauen: für Mütter und Töchter, für It-Girls, Damen und Diven, für Singles wie Verheiratete, für die Stillen und die Lauten, die Bescheidenen und die Karrierefrauen, für Amazonen, Bundeskanzlerinnen und Industriekapitäninnen – ja sogar für Feministinnen.', '08.12.2010', 'Süddeutsche Zeitung', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Ratgeber', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
