insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d596b4ee-154c-57e5-8589-663ef1531f0b', 'Tacky der Pinguin', NULL, '9783880101906', 'Auf einem hübschen kleinen Eisberg lebt eine kleine Gruppe Pinguine. Sie sind ordentlich und gesittet und in ihrem schwarzen Fräcken kaum voneinander zu unterscheiden. Nur Tacky mit seinem buntegeblümten Hemd und der karierten Fliege fällt sofort auf - und ständig aus der Rolle. Richtig peinlich ist es den anderen, wenn er mal wieder aus der Reihe tanzt und lauthals lustige Lieder singt. Bis eines Tages ein Rudel grimmiger Räuber auftaucht, die nur eines wollen: Pinguine fangen! Jetzt ist Tackys große Stunde gekommen. Stolpernd, singend und wasserspritzend schlägt er die Bösewichte in die Flucht...', '01.01.1990', 'Lentz', ARRAY['Deutsch']::text[], 30, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Tacky']::text[], '{}', '{}', 'eddbfbfb-47fd-5c08-b522-7a7dcfe9e15e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
