insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('00467720-0edd-5db8-b97b-6da399f10585', 'Lean on Me', 'The Good Luck Charm', '9783736313293', 'So hatte sich Ethan Kase sein Leben als Eishockey-Profi nicht vorgestellt! Nachdem er vor acht Jahren seine Heimatstadt und seine große Liebe Lilah verlassen hat, um ein erfolgreicher NHL-Spieler zu werden, ist er nun wieder zurück und hofft auf eine zweite Chance mit der Frau, die er nie vergessen konnte. Doch Lilah hat nicht vor, ihm so leicht zu verzeihen. Auch sie kann sich noch an die glückliche Zeit mit Ethan erinnern - und an die Trauer, die sie nach der Trennung empfunden hat. Ethan muss jetzt in das härteste Spiel seines Lebens einsteigen - und es geht um nicht weniger als Lilahs Herz ...', '30.04.2021', 'LYX', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ethan Kase','Lilah']::text[], ARRAY['Second Chance']::text[], '{}', '3bb38645-c9a1-5808-8676-c91ac22c171c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
