insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1f81aacf-1e46-584c-94a1-7731b37c1912', 'Stand by Me', 'Meet Cute', '9783736314788', 'Als Kailyn mit dem Jurastudium beginnt, hat sie nur ein Ziel: den Abschluss als Jahrgangsbeste zu schaffen. Doch an ihrem ersten Tag am College stolpert sie buchstäblich über ihren Teenie-Schwarm, den Schauspieler Daxton Hughes. Trotz dieses peinlichen Vorfalls entwickelt sich zwischen den beiden schnell eine freundschaftliche Rivalität - bis Dax ihr völlig unerwartet in den Rücken fällt. Als ihre Wege sich 8 Jahre später wieder kreuzen und Dax sie um Hilfe bittet, hat Kailyn ihm diesen Verrat zwar noch nicht verziehen, aber sie kann ihn in seiner Notsituation auch nicht einfach im Stich lassen. Und schon bald ist das Knistern zwischen ihnen heiß wie nie zuvor. Doch kann Kailyn ihr Herz einem Mann anvertrauen, der sie schon einmal so enttäuscht hat?', '27.08.2021', 'LYX', ARRAY['Deutsch']::text[], 380, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kailyn','Daxton Hughes']::text[], '{}', '{}', '3bb38645-c9a1-5808-8676-c91ac22c171c', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
