insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('03d61a35-2ef6-5d4d-b464-ccaee502675f', 'Sweet On Me', 'Kiss My Cupcake', '9783736316362', 'Endlich ist Blaire Calloways großer Tag gekommen. Monatelang hat sie darauf hingearbeitet, ihren Traum zu verwirklichen: die Cupcake- und Cocktailbar Buttercreme and Booze. Doch dann muss sie feststellen, dass direkt nebenan eine rustikale Sportsbar eröffnet - und dass der ebenso attraktive wie unverschämte Besitzer Ronan Knight zum Problem werden könnte. Schafft er es doch, mit seinem Charme und seinem umwerfenden Lächeln ihre Kundschaft abzuwerben. Aber das lässt sich Blaire nicht gefallen! Sie mag zwar süß und harmlos aussehen, doch für ihren Traum ist sie bereit zu kämpfen. Allerdings muss Blaire bald feststellen, dass der Kleinkrieg mit Ronan ihr mehr Spaß macht, als er sollte ...', '26.11.2021', 'LYX', ARRAY['Deutsch']::text[], 344, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Blaire Calloways','Ronan Knight']::text[], '{}', '{}', '3bb38645-c9a1-5808-8676-c91ac22c171c', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
