insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a006569a-65b4-5edc-8284-d6e11a4f3688', 'Keep out', NULL, '9783842007826', 'Der Anti-Terror-Spezialist Toranosuke Fuyuki erhält den Auftrag, den Großunternehmer Kagami zu bewachen. Die Arbeit als Bodyguard bereitet ihm eigentlich keine Schwierigkeiten, würde sein Auftraggeber nicht fortwährend aufdringliche Annäherungsversuche machen! Doch eine Reihe von Ereignissen lässt Fuyuki langsam seine Meinung gegenüber Kagami ändern: Als Kagami auf der Straße attackiert wird, stellt er sich schützend vor Fuyuki. Doch gerade, wenn sich Beruf und Privatleben vermischen, kann es gefählich werden.', '15.07.2013', 'TokyoPop', ARRAY['Deutsch']::text[], 260, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Toranosuke Fuyuki','Kagami']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
