insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3bd24ddf-76e6-5dd7-9c67-813842c360f7', 'Die Verlorenen Schwestern', 'The Lost Sisters', '9783641245511', 'Während Jude sich am Hof von Elfenheim mit Prinz Cardan einen erbitterten Machtkampf liefert, verliebt sich ihre Zwillingsschwester Taryn in Locke, den schönen und betrügerischen Freund Cardans. Hier beschreibt Taryn in ihren eigenen Worten, wie es zu dem Verrat kommen konnte und wie sie versucht, die Vergebung ihrer Schwester zu erlangen …', '08.06.2019', 'cbj', ARRAY['Deutsch']::text[], 87, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], NULL, 'Vergangenheit'::time_period, 'Elfhame', '{}', ARRAY['Taryn']::text[], '{}', '{}', 'acfad41a-c462-53d3-b6b4-d342ec10238b', '2', ARRAY['Spin Off','Midquel']::text[], 'sheet', :'owner') on conflict do nothing;
