insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e218fb16-dec5-544b-952b-d6dc57509ee6', 'The Queen of Nothing', NULL, '9781471407598', 'After being pronounced Queen of Faerie and then abruptly exiled by the Wicked King Cardan, Jude finds herself unmoored, the queen of nothing. She spends her time with Vivi and Oak, watching reality television, and doing odd jobs, including squaring up to a cannibalistic faerie. When her twin sister Taryn shows up asking a favour, Jude jumps at the chance to return to the Faerie world, even if it means facing Cardan, who she loves despite his betrayal. When a dark curse is unveiled, Jude must become the first mortal Queen of Faerie and break the curse, or risk upsetting the balance of the whole Faerie world.', '23.07.2020', 'Hot Key Books', ARRAY['Englisch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Elfhame', '{}', ARRAY['Jude']::text[], '{}', '{}', 'acfad41a-c462-53d3-b6b4-d342ec10238b', '4', '{}', 'sheet', :'owner') on conflict do nothing;
