insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25e7100d-488f-59b0-a283-99c402924f82', 'How the King of Elfhame Learned to Hate Stories', NULL, '9781471410017', 'Before Cardan was a cruel prince or a wicked king, he was a faerie child with a heart of stone. #1 New York Times bestselling author, Holly Black reveals a deeper look into the dramatic life of Elfhame''s enigmatic high king, Cardan. This tale includes delicious details of life before The Cruel Prince, an adventure beyond The Queen of Nothing, and familiar moments from The Folk of the Air trilogy, told wholly from Cardan''s perspective.', '07.05.2024', 'Hot Key Books', ARRAY['Englisch']::text[], 173, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Elfhame', '{}', ARRAY['Cardan']::text[], '{}', '{}', 'acfad41a-c462-53d3-b6b4-d342ec10238b', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
