insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ddff6edd-2f04-554e-8182-813e213e65aa', 'The Wicked King', NULL, '9781471407369', 'I have heard that for mortals, the feeling of falling in love is very like the feeling of fear. Jude has tricked Cardan onto the throne, binding him to her for a year and a day. But the new High King does everything in his power to humiliate and undermine her, even as his fascination with her remains undimmed. Meanwhile, a traitor in the court is scheming against her. Jude must fight for her life and the lives of those she loves, all while battling her own complicated feelings for Cardan. Now a year and a day seems like no time at all . . .', '22.08.2019', 'Hot Key Books', ARRAY['Englisch']::text[], 322, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Elfhame', '{}', ARRAY['Jude']::text[], '{}', '{}', 'acfad41a-c462-53d3-b6b4-d342ec10238b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
