insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0d913d2d-45d7-5b94-ba4e-5b12ab5ce892', 'This is not a love story', 'Soulmates', '9783423423984', 'An die wahre Liebe oder gar an Seelenverwandtschaft hat die 17-jährige Penny nie geglaubt. Bis sie eines Abends bei einem Konzertbesuch auf Noah trifft. Wie ein Magnet fühlt sie sich von ihm angezogen – und Noah geht es anscheinend nicht anders. Sie spürt die gewaltige Kraft der Gefühle und lässt Noah doch mit dem ihr eigenen Sarkasmus abblitzen. Erst als sie sich ein paar Monate später wiedersehen, ist klar: Penny und Noah können nicht voneinander lassen. Doch je näher sie sich kommen, desto gefährlicher scheint ihre Leidenschaft für sie und ihre Umgebung zu sein . . . Ist diese Liebe zu groß für sie?', '06.03.2014', 'dtv', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Penny','Noah']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
