insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7a18bb83-7d1e-5e81-ac52-2fd3ce243391', 'Not Quite Dead Yet', NULL, '9783751782784', 'In sieben Tagen wird Jet Mason tot sein. Jet ist die Tochter einer der reichsten Familien in Woodstock, Vermont. Mit 27 Jahren wartet sie immer noch darauf, dass ihr Leben endlich beginnt. "Das kann ich später noch machen", sagt sie immer. Denn Jet hat Zeit. Bis zu jener Halloween-Nacht, als sie von einem unsichtbaren Eindringling brutal angegriffen wird. Dabei erleidet Jet eine schwere Kopfverletzung, und die Ärzte sind sich sicher: In spätestens einer Woche wird ein tödliches Aneurysma Jet umbringen. Jet hätte nie gedacht, dass sie Feinde hat. Doch plötzlich sieht sie alle Menschen in ihrem Umfeld in einem neuen Licht: ihre Familie, ihre ehemalige beste Freundin, die jetzt ihre Schwägerin ist, ihren Ex-Freund. Sie weiß, ihr bleiben höchstens sieben Tage. Tage, in denen sich ihr Zustand verschlechtert und nur Billy, ein Freund aus Kindertagen, an ihrer Seite ist. Dennoch ist sie fest entschlossen, endlich etwas zu Ende zu bringen: Jet wird ihren eigenen Mord aufklären.', '17.07.2025', 'One', ARRAY['Deutsch']::text[], 474, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jet Mason']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
