insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ad575b80-44db-527a-8396-8b1f02f3936a', 'A Good Girl''s Guide to Murder', NULL, '9783846601594', 'Vor fünf Jahren wurde die siebzehnjährige Andie Bell ermordet. Der Fall ist längst abgeschlossen, denn alle sind sich sicher, dass ihr Freund Sal Singh die Tat begangen hat. Nur Pippa glaubt nicht daran und will den Fall für ein Schulprojekt noch einmal aufrollen. Sie beginnt nachzuforschen und Fragen zu stellen. Aber was ist, wenn der Mörder noch frei herumläuft? Wie weit wird er gehen, um Pippa davon abzuhalten, die Wahrheit ans Licht zu bringen?', '18.10.2022', 'one', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Little Kilton', ARRAY['Single POV','1P']::text[], ARRAY['Pippa']::text[], ARRAY['Amateur Detektiv','High School','Whodunit','Strong FMC','Small Town']::text[], '{}', 'a18dffa3-15b7-5e88-ab46-5468ea7132f1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
