insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('e4186f57-ffc6-5739-a301-ab4b5d28e442', '6e617fe7-d541-51ce-8c1f-4b52e6db1e6c', :'owner', 1, '2024-01-16', '2024-01-23', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('336e750b-836c-5133-a658-db18e53757b8', 'Five Survive', NULL, '9783846602577', 'Eigentlich sollte es ein spaßiger Ausflug werden: Red ist mit fünf Freunden losgefahren, um Spring Break zu feiern. Doch unterwegs bleibt der alte Campingbus liegen -und sie stecken mitten im Nirgendwo fest. Kein Empfang, keine Aussicht auf Hilfe. Und es kommt noch schlimmer, denn draußen im Dunkeln lauert jemand. Sobald sie den Bus verlassen, schießt er auf sie. Seine Behauptung: Jemand aus der Gruppe verheimlicht etwas. Doch wen meint er? Alle sind gezwungen, ihre brisantesten Geheimnisse preiszugeben. Die Spannungen innerhalb des engen Campers steigen. Und nicht alle werden die Nacht überleben ...', '21.01.2025', 'One', ARRAY['Deutsch']::text[], 448, 40, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Red Kenny']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
