insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25c51556-99ae-5a74-a283-59807791567b', 'Good Girl, Bad Blood', NULL, '9783846601600', 'Seit sie den Mordfall an Andie Bell aufgeklärt hat, ist Pip geradezu berühmt. Vom Ermitteln hat sie trotzdem erst mal genug - lieber erzählt sie in einem True-Crime-Podcast mehr darüber, wie sie geholfen hat, den wahren Mörder Andies zu finden. Doch dann erfährt sie, dass ein Bekannter aus der Nachbarschaft verschwunden ist. Und weil die Polizei erst mal nichts unternimmt, fängt Pip doch wieder an, Fragen zu stellen. Schon bald sind die Fans ihres Podcasts live dabei, wie sie nicht nur dem Verschwinden von Jamie Reynolds auf den Grund geht. Es scheint, dass Pip mal wieder an den dunklen Geheimnissen von Little Kilton rührt. Und das bringt erneut auch sie selbst in große Gefahr ...', '27.01.2023', 'one', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Little Kilton', ARRAY['Single POV','1P']::text[], ARRAY['Pippa']::text[], ARRAY['Small Town','Amateur Detektiv','High School','Lost','Revenge Plot','Secred Identity','Tragic Backstory','Whodunit','Strong FMC']::text[], '{}', 'a18dffa3-15b7-5e88-ab46-5468ea7132f1', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('baec77fe-5e8b-5be4-960f-65868fcd8690', :'owner', '25c51556-99ae-5a74-a283-59807791567b', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', ARRAY['Map','In-Book Illustrationen']::text[], 1400, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 0, 'no'::burn_kind, 'Die zwei emotionalsten Punkte waren für mich, als Ant Pip vorwirft zu lügen und als Stanley am Ende stirbt. Ant ist einfach ein blöder Wichser. Wie kann man so zu einer Freundin sein. Und Stanley hatte das wirklich nicht verdient. Wirklich gutes Buch! Ich hatte zwar zwischendurch mal die Vermutung, dass Charlie was mit all dem zu tun haben könnte, aber ich war mir bis zum Ende hin nicht sicher.') on conflict do nothing;
