insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('56e51be4-ba5a-5eb0-b58e-8ee7ccd6fec0', 'As Good as Dead', NULL, '9783846601730', 'In letzter Zeit erhält Pip immer wieder anonyme Nachrichten mit der Frage: Wer wird nach dir suchen, wenn du verschwindest? Und nicht nur das: Ein Stalker stellt ihr nach - und der Täter weiß, wo Pip wohnt. Als sie Zusammenhänge zwischen dem Stalker und einem Serienmörder aus der Gegend aufdeckt, kommt ihr ein schrecklicher Verdacht: Kann es sein, dass der Mann, der seit sechs Jahren wegen der Morde im Gefängnis sitzt, gar nicht der eigentliche Täter ist? Pip wird klar, dass sie einem weiteren ungeheuren Fall auf der Spur sein könnte. Und wenn sie nicht schnell die richtigen Antworten auf all ihre Fragen findet, könnte dieses Mal sie diejenige sein, die zum Opfer wird ...', '15.03.2023', 'One', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Pippa']::text[], '{}', '{}', 'a18dffa3-15b7-5e88-ab46-5468ea7132f1', '3', '{}', 'sheet', :'owner') on conflict do nothing;
