insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0a708aee-489a-5ff0-99b2-200ca348fa7f', 'Kill Joy', NULL, '9783846602058', 'Statt an ihrem Schulprojekt zu arbeiten, soll Pippa Fitz Amobi den Abend mit einem albernen Krimidinner verbringen? Nur widerwillig sagt sie zu - und erscheint passend zum Zwanzigerjahre-Motto des Spiels in Abendkleid und Federboa kostümiert. Doch bald weckt der Kriminalfall ihren detektivischen Spürsinn, und sie stellt fest, dass es ihr Spaß macht, dem Täter Hinweis um Hinweis auf die Schliche zu kommen. Am Ende ist der erfundene Mord nicht mehr der einzige Fall, der ihr nicht aus dem Kopf gehen will ...', '27.10.2023', 'One', ARRAY['Deutsch']::text[], 160, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Pippa']::text[], '{}', '{}', 'a18dffa3-15b7-5e88-ab46-5468ea7132f1', '4', '{}', 'sheet', :'owner') on conflict do nothing;
