insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e07d6e2a-d214-5212-a9fc-3d16295d0eaa', 'The sight of you', NULL, '9781529324389', 'Joel is afraid of the future. Since he was a child he''s been haunted by dreams about the people he loves. Visions of what''s going to happen - the good and the bad. And the only way to prevent them is to never let anyone close to him again. Callie can''t let go of the past. Since her best friend died, Callie''s been lost. She knows she needs to be more spontaneous and live a bigger life. She just doesn''t know how to find a way back to the person who used to have those dreams. Joel and Callie both need a reason to start living for today. And though they''re not looking for each other, from the moment they meet it feels like the start of something life-changing.', '08.06.2021', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, NULL, NULL, '{}', ARRAY['Joel','Callie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
