insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('2af12bf1-aea0-5d75-a7a4-01b492365930', '1c0cc21e-fb12-5b15-80b4-2fd1ef9b138d', :'owner', 1, '2023-11-23', '2023-11-24', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8fc94cd1-15a7-5723-94f3-c066ac89f5ca', 'The Bare Essentials', NULL, NULL, 'Can Janet survive the heat of an alien desert? And the heat of the alien warrior who finds her? One minute Janet is sliding into a snow bank. The next she is alone in the middle of a strange pink desert. Alone and naked. When a huge, golden-scaled male appears out of the shifting sands, she is convinced that he is a mirage. But the fiery pleasure of his touch feels too real to be an illusion. Sabrost is preparing for his final initiation as a priest of Tetlana when he is snatched away from his temple. The desert in which he awakens reminds him of his ancestral sands. But his ancestors would never have accepted the delicate female who arouses all of his protective instincts. The desert holds many secrets - not the least of which are the secrets of the heart. Which will prove most treacherous as Janet and Sabrost make the perilous trek to safety?', '18.03.2021', NULL, ARRAY['Englisch']::text[], 144, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', ARRAY['Janet','Sabrost']::text[], '{}', '{}', '544e6765-ad58-575f-ad4a-45ee66ba6839', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
