insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('402d64ad-c5db-5f16-883f-839018c3ff6a', '924a7da9-9aa4-5a14-99f8-aadb243f274e', :'owner', 1, '2023-11-24', '2023-11-25', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('12b16556-75ef-55fc-8082-4982177faa62', 'A Nude Attitude', NULL, NULL, 'Can Erica survive the hidden dangers of an alien ocean? And the charms of the alien convict stranded with her? Erica desperately needs a break from her domineering father - especially his latest scheme to marry her off so she can produce an heir. When she wakes up on a tropical island, it almost seems like the answer to a prayer… Except she’s naked, alone, and she’s never seen an island quite like this before. She’s certainly never seen anyone like the big blue alien who walks out of the sea with a fierce grin and a massive spear. A’rien is smooth, charming - and unlucky. When his latest scheme goes awry, he is tried and convicted of a crime he didn’t commit. His fate seems certain, but instead, he wakes up on an unknown planet. He has everything he needs to survive, including a strange, beautiful female. Has his luck finally turned? But the more time A''rien spends with Erica - teasing her, protecting her, touching her - the more he realizes that she doesn’t belong in this world. Will he give in to his desire to keep her - or will the conscience he never knew he had insist that he let her go?', '15.04.2021', NULL, ARRAY['Englisch']::text[], 142, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', ARRAY['Erica','A’rien']::text[], '{}', '{}', '544e6765-ad58-575f-ad4a-45ee66ba6839', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
