insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('91cec1a9-5046-5ac0-9fb4-730e1f1fadf2', '806a1e2d-0fda-5026-950a-04f46bb98fe7', :'owner', 1, '2023-11-27', '2023-11-28', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e9d8a1f-ec87-548f-830b-611c428db40b', 'The Strip Down', NULL, NULL, 'Can Amanda discover the secrets behind an alien ruin? And the mysterious alien with the haunted eyes? Amanda is happy with her life as an elementary school teacher - and making plans to expand her family. Waking up naked and alone on an alien planet is not on her schedule. Desperate to return to Earth, she reluctantly accepts the help of the massive alien who appears out of the sands. But the more time they spend together, the more complicated her need to return becomes. Va’rik awakens to find himself alone on the edge of an ancient desert. He is quite sure he has an important task to perform - the only problem is that he can’t quite remember what he needs to accomplish. When he encounters a strange, beautiful female, assisting her becomes his mission. But as his memories start to return, he realizes that helping her leave is the last thing he truly wants. Can Va’rik keep his vow to Amanda, even if it means the future of his race - and his own happiness - are in jeopardy?', '10.06.2021', NULL, ARRAY['Englisch']::text[], 130, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', ARRAY['Amanda','Va’rik']::text[], '{}', '{}', '544e6765-ad58-575f-ad4a-45ee66ba6839', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
