insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b28e55c4-0c95-5284-a704-a4e6555fbe28', 'A Student’s Introduction to English Grammar', NULL, '9780521612883', 'A new edition of a successful undergraduate textbook on contemporary international Standard English grammar, based on Huddleston and Pullum''s earlier award-winning work, The Cambridge Grammar of the English Language (2002). The analyses defended there are outlined here more briefly, in an engagingly accessible and informal style. Errors of the older tradition of English grammar are noted and corrected, and the excesses of prescriptive usage manuals are firmly rebutted in specially highlighted notes that explain what older authorities have called ''incorrect'' and show why those authorities are mistaken. Intended for students in colleges or universities who have little or no background in grammar or linguistics, this teaching resource contains numerous exercises and online resources suitable for any course on the structure of English in either linguistics or English departments. A thoroughly modern undergraduate textbook, rewritten in an easy-to-read conversational style with a minimum of technical and theoretical terminology.', '2005', 'Cambridge', ARRAY['Englisch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Sprache', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
