insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('02bc96e5-82b6-5a51-8ea8-5e92f7472337', 'Silo', NULL, '9783492055857', 'Drei Jahre nach dem mysteriösen Tod seiner Frau Allison setzt Sheriff Holston seiner Aufgabe ein Ende und entschließt sich, die strengste Regel zu brechen: Er will das Silo verlassen. Doch die Erdoberfläche ist hoch toxisch, ihr Betreten bedeutet den sicheren Tod. Holston nimmt das in Kauf, um endlich mit eigenen Augen zu sehen, was sich hinter der großen Luke befindet, die sie alle gefangen hält. Seine Entdeckung ist ebenso ungeheuerlich wie die Folgen, die sein Handeln nicht zuletzt für seine Nachfolgerin Juliette hat … Hugh Howeys verstörende Zukunftsvision ist rasanter Thriller und faszinierender Gesellschaftsroman in einem. »Silo« handelt von Lüge und Manipulation, Loyalität, Menschlichkeit und der großen Tragik unhinterfragter Regeln.', '12.03.2013', 'Piper', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Silo', '{}', ARRAY['Juliette Nichols']::text[], '{}', '{}', 'e7a1f151-b9ee-5804-8062-53aee462a1bc', '1', '{}', 'sheet', :'owner') on conflict do nothing;
