insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1c2e72cc-10e8-53a6-9e76-3d67ac737982', 'Ich bin aber größer als Du!', NULL, '9783930299140', 'Der Stadtzoo hat eine neue Attraktion: Zwei Giraffenkinder sind zur Welt gekommen! Doch kaum stehen Ria und Pia, so heißen die Zwillinge, auf ihren eigenen Beinen, geht das Streiten los: Welche von beiden kann wohl schneller wachsen? Anfangs wetten sie nur darum, wer wohl als erste über den großen Zaun schauen kann, aber dann werden ihre Ziele immer höher. Sie vergessen völlig, dass Spielen und Toben eigentlich viel mehr Spaß machen. Doch als sie eines Nachts sogar ein Wettwachsen zum Mond veranstalten, wird beiden klar, dass es Wichtigeres gibt als solch einen Wettkampf.', '01.01.1996', 'Albarello', ARRAY['Deutsch']::text[], NULL, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Gegenwart'::time_period, 'Zoo', ARRAY['3P Objective']::text[], ARRAY['Ria','Pia']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
