insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d4defb8-7a75-5151-a136-7d67d302a169', 'The Female', NULL, NULL, 'The female decline was swift. Birth rates dropped at an alarming rate, and within years, men across all realms grew restless and aggressive. Their desperation led to women being collected at birth and sold at auction, and humans gradually became one of the most sought after. Parents began hiding their daughters, birthing and stowing their females underground in a desperate attempt to keep them safe. Charlotte is one of them. Hidden from the men who would tear her family apart to get to her, she’s accepted that she’ll live her entire life within the thick walls of her childhood home. When the human government permits a large-scale raid, Charlotte is one of the unlucky women caught. Forced out of hiding and thrown into the home of three powerful demons, Charlotte must learn how to stay alive in a world she’s only experienced through stories from her parents.', '11.02.2023', NULL, ARRAY['Englisch']::text[], 405, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Charlotte']::text[], '{}', '{}', '283fdcbc-b66f-56eb-a3b3-0631692d7486', '1', '{}', 'sheet', :'owner') on conflict do nothing;
