insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('0666a0cf-1df5-58ad-9d4a-61355475e8b4', '5273e82e-0e6b-5f2f-993a-5630f608cb31', :'owner', 1, '2023-04-28', '2023-05-03', NULL, NULL, 6, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('84c751cb-1f34-547a-9933-ac1a62c121f1', 'The Cursed Kingdom', NULL, NULL, 'Abby’s come up with a brilliant plan.Sneak into the faerie realm, travel to the shifter forest and collect all the delysum she can get her hands on, and return home before anybody discovers who she is. Simple.The only problem is she’s never actually been to the faerie realm, and it turns out the few stories she’s been told were wildly deceiving. The plant she’s meant to collect is being cultivated into a weapon, and the faeries are on the cusp of war with the shifters.An impending war Abby quickly finds herself caught in the middle of.Captured in the forest by the faerie and shifter princes, Abby must find a way to escape and return home before they figure out who she really is.This slow-burn, enemies-to-lovers romance ends on a cliffhanger. Tensions rise and attraction simmers, which will lead to even steamier scenes in book two.', '15.12.2024', NULL, ARRAY['Englisch']::text[], 403, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, NULL, 'Faerie Realm', '{}', ARRAY['Abby']::text[], '{}', '{}', 'a1a6908f-5030-5d48-9f8c-abc9421181b6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
