insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('83ef8feb-f0d3-521a-86cf-f40bd099b492', 'Aine', NULL, NULL, 'Condemned to die at the hands of the beasts, Aine enters the woods expecting death—only to be claimed by one instead. When Aine is sent into the woods for her crimes, she accepts she''ll be met with death. The beasts are known to kill any human that wanders into their territory, their razor-sharp teeth ripping through flesh and bone with practiced ease. Aine knows she''ll be no different from all the others who have been executed before her, and when she''s forced into the woods by her own people, it doesn''t take long for the beasts to attack. What she doesn''t expect is for them to take the shape of humans and spare her, and even more, for one to claim her as his own.', '24.10.2022', NULL, ARRAY['Englisch']::text[], 436, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Aine']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
