insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('31720e8f-3695-5069-bfd3-8aec4294b8f5', 'Her Males', NULL, NULL, 'Living with three powerful demons is not easy, especially when they’re dead set on making you theirs. Charlotte’s life was decided for her the moment she was born, but now she’s faced with the opportunity to change the fate of millions of purchased females—and the generations to follow. Her males have agreed to fight to free her kind, righting the mistake they made so many years ago. Thrust into a world of politics and nuances too subtle to understand, Charlotte quickly learns the truth is never what it seems. Lies and deceit pull her in different directions, and she soon begins questioning who she can trust. Charlotte finds herself navigating alliances and broken promises with the strongest rulers of the realms, all while discovering who she is beyond just a purchased female.', '21.03.2023', NULL, ARRAY['Englisch']::text[], 390, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Charlotte']::text[], '{}', '{}', '283fdcbc-b66f-56eb-a3b3-0631692d7486', '2', '{}', 'sheet', :'owner') on conflict do nothing;
