insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('fca6e7b1-0e58-56fd-b375-c8e331fe1bfa', '5c75dbba-a883-51ee-a2fc-bc6d88c63620', :'owner', 1, '2023-05-03', '2023-05-08', NULL, NULL, 6, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('22761659-17d1-5655-b172-13e25fed6afb', 'The Shattered Kingdom', NULL, NULL, 'The second in an epic romantic fantasy series from the hugely popular author of The Female series in which a young woman is forced to choose sides in the midst of a conflict that threatens to shake the alliance between the faerie and shifter kingdoms.Abby thought things couldn’t get worse. She was wrong.Her best friend shares a mate bond with her two sworn enemies, Mason won’t stop following her around, and Lill has been accused of treason.Alibis aren’t adding up, memories don’t align, and Abby has no idea who to trust. The only constant? Every path leads back to the shifters.When the faerie royal family is attacked, every finger points toward Lill and the shifters. Tensions peak, and when Mason publicly calls into question the shaky peace agreement between the faerie and shifter kingdoms, everything unravels.Abby is forced to choose sides. Does she stand by Lill, her best friend since childhood? Or does she trust Kie and Mason, the two men who have shown her nothing but cruelty and indifference?', '12.08.2025', NULL, ARRAY['Englisch']::text[], 354, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, NULL, 'Faerie Realm', '{}', ARRAY['Abby']::text[], '{}', '{}', 'a1a6908f-5030-5d48-9f8c-abc9421181b6', '2', '{}', 'sheet', :'owner') on conflict do nothing;
