insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d5416eb3-d891-58b8-889e-4a01f3c21b35', 'Their War', NULL, NULL, 'Charlotte’s managed to secure a powerful alliance with the shifters, but this comes at a cost. The news of her plans to rescue the females has spread, and many aren’t eager for the control it gives Charlotte’s males. The Queen of Greed has joined forces with the ogres, and they’ve invaded Wrath. She’s dead set on destroying Charlie’s males and everything they’ve been working toward, and the demon kingdoms quickly find themselves divided. Shifting priorities and untimely attacks strain Charlotte’s carefully crafted plan, and the treads that hold everything together quickly begin to unravel.', '21.05.2023', NULL, ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Charlotte']::text[], '{}', '{}', '283fdcbc-b66f-56eb-a3b3-0631692d7486', '3', '{}', 'sheet', :'owner') on conflict do nothing;
