insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c05d7503-909c-55a2-a637-67bc3e1882f2', '2d84198a-9cf2-56ae-87f9-34e9f17b87cd', :'owner', 1, '2024-06-11', '2024-06-18', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ea9a1690-f8b3-531c-9eb0-64e9040a300f', 'Queens', NULL, NULL, 'Cassia has spent years plotting her revenge. The Queen of Greed attacked her family, and Cassia swore she’d be the one to deliver the queen’s severed head to the people of Wrath. Every step, every breath, has led to this moment. But when she finally makes her move… someone else lands the killing blow. Rexton has been undercover in Greed for over twenty years, waiting patiently for the opportunity to bring down their queen. He doesn’t know Cassia, and he certainly doesn’t know of her plans. When the moment to kill the queen finally presents itself, he doesn’t hesitate to strike. He has no way of knowing he’s just stolen the Crown Princess of Wrath’s vengeance—or her glory. Now Cassia has a new target. Rexton.', '18.11.2025', NULL, ARRAY['Englisch']::text[], 378, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Wrath', ARRAY['Double POV','1P']::text[], ARRAY['Cassia','Rexton']::text[], ARRAY['Enemies to Lovers','Family Drama','Mental Issues','Soul Mates']::text[], '{}', '283fdcbc-b66f-56eb-a3b3-0631692d7486', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ca80d582-fa81-5447-b08e-f5ab8e27a774', :'owner', 'ea9a1690-f8b3-531c-9eb0-64e9040a300f', 'gelesen'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 426, false, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.0, 'erfuellt'::expectation_kind, 3, 'slow'::burn_kind, 'Leider ging mir Cassia nur so dermaßen auf den Sack, dass die Story teilweise kaum zu ertragen war. Selten habe ich einen so nervigen Charakter erlebt, der einfach gleichzeitig viel zu insecure und von sich selbst überzeugt ist. Anstrengend. Gegen Ende wurde sie dann jedoch erträglicher und nachvollziehbarer. Ich mag die Welt und ich mag den Schreibstil. Ich kehre immer wieder gerne zurück, auch wenn ich die ursprüngliche Story am besten Fand.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('2b844fb4-f2d0-56e1-9039-4e8895d7d69d', 'ca80d582-fa81-5447-b08e-f5ab8e27a774', :'owner', 1, '2026-01-03', '2026-01-19', NULL, NULL, 17, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('116d5b98-c74e-542d-927c-521640fa57ea', 'Taken by the Tide', NULL, NULL, 'Sadie has spent her life chasing the horizon—working aboard her father’s crabbing boat and laughing off myths of the deep—until Kyros boards their ship. There’s a storm. Blood stains his hands. Before she can understand what’s happening, Kyros throws her overboard and leaves her to die. Except Sadie doesn’t drown. She isn’t human. She’s something forbidden. When Kyros realizes what she is, he takes her back to Tideborn—an underwater city on the brink of collapse. Only somebody with Sadie’s blood can fix it. But there are monsters that lurk in the depths, the Red Bloom is near, and Kyros—the man who betrayed her—is the only one who can keep her alive. He says she’s their last hope. Sadie isn’t sure she wants to save his world. She might rather watch it burn.', '25.08.2026', NULL, ARRAY['Englisch']::text[], 308, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, NULL, 'Tideborn', '{}', ARRAY['Sadie','Kyros']::text[], ARRAY['Enemies to Lovers']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
