insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b9687e2-8250-5d44-a4d2-934ac39557a6', 'Rosemarys Baby', NULL, NULL, 'Rosemary Woodhouse and her struggling actor-husband, Guy, move into the Bramford, an old New York City apartment building with an ominous reputation and only elderly residents. Neighbours Roman and Minnie Castavet soon come nosing around to welcome them; despite Rosemary''s reservations about their eccentricity and the weird noises that she keeps hearing, her husband starts spending time with them. Shortly after Guy lands a plum Broadway role, Rosemary becomes pregnant, and the Castavets start taking a special interest in her welfare. As the sickened Rosemary becomes increasingly isolated, she begins to suspect that the Castavets'' circle is not what it seems...', '1968', NULL, ARRAY['Englisch']::text[], 246, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Rosemary Woodhouse']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
