insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bcd71b8d-bf30-5925-a069-d9542a9ce389', 'Meine erste Liebe', 'Kare no hatsukoi wa, doku ka arui wa', '9782889511136', 'Zehn Jahre ist es jetzt her, seit Miyako vor den Gefühlen zu seinem Jugendfreund die Flucht ergriffen hat. Erst die Einladung zu dessen Hochzeit bringt die beiden wieder miteinander in Kontakt. Während Miyako noch versucht, seine unerfüllte Liebe endgültig zu vergessen, tritt plötzlich ein anderer Mann auf den Plan. Yuya, der jüngere und äußerst attraktive Bruder seines Jugendschwarms, gesteht Miyako seine jahrelange Zuneigung und entfacht damit einen Sturm aus alten und neuen Sehnsüchten ...', '06.06.2018', 'Kaze Manga', ARRAY['Deutsch']::text[], 186, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Miyako','Yuya']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
