insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5747ac96-b3ca-5b80-99f5-319a3c3d33fa', 'Meine Freunde die Roboter', 'I, Robot', '9783453308534', 'Dr. Susan Calvin war fünfzig Jahre lang als Robotpsychologin bei der U. S. Robot Company angestellt, einem der größten Unternehmen der Welt. Sie erlebte hautnah mit, wie Robots zum alltäglichen Bestandteil der menschlichen Kultur wurden und welche Probleme es mit sich bringt, wenn Menschen mit Robotern zusammenleben. Vor allem aber stellt sich eine Frage: Was passiert, wenn sich Mensch und Roboter kaum noch voneinander unterscheiden? In neun Erzählungen zeigt sie einem jungen Reporter, wie eine Zukunft, geprägt von gigantischen Positronengehirnen, für uns Menschen aussieht.', '1978', 'Heyne', ARRAY['Deutsch']::text[], NULL, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Dr. Susan Calvin']::text[], '{}', '{}', '8b74f04b-5ce3-5011-adab-c67aa3186985', '1', '{}', 'sheet', :'owner') on conflict do nothing;
