insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7bf3da5f-5e73-5603-b6e0-2ccfc9c3baef', 'Froschprinz', NULL, NULL, 'Nichts kann Ludwigs supertolerante Familie schocken. Grüne Haare? Homosexuell? Alles kein Problem! Wie soll ein vernünftiger Teenager da noch rebellieren? Aber das ist nicht Ludwigs einziges Problem. Als Jungfrau auf der Suche nach der großen Liebe zu sein, ist schon eine Herausforderung. Und dann zieht auch noch Paul im Haus nebenan ein und macht das Chaos mit seinem ungesunden Drang nach Sex perfekt. Doch wenn Ludwig gedacht hat, dass nach dem Abitur alles besser wird, hat er die Rechnung ohne Paul gemacht.', NULL, NULL, ARRAY['Deutsch']::text[], 612, NULL, 'Buch'::book_kind, ARRAY['Fiction','Fanfiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ludwig Lohmeier']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
