insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b11dfedb-76d3-54dd-98e0-86e154770708', 'L.O.V.E. - A Single Word', NULL, '9783734108563', 'Als Oxy den Bruder ihrer neuen Mitbewohnerin Ella kennenlernt, weiß sie sofort, dass Henri nichts als Ärger bedeutet. Denn der gut aussehende Erbe des Modeunternehmens »French Chic« steht nicht nur im Ruf, ein notorischer Frauenheld zu sein, er verhält sich auch wie der weltgrößte Rüpel. Was Oxy nicht weiß: Henri hütet ein dunkles, traumatisches Geheimnis. Gefühle will er nicht zulassen, und dennoch weckt die schlagfertige Oxy etwas in ihm – etwas, dem sich Oxy all seiner Sabotageversuche zum Trotz ebenfalls nicht entziehen kann …', '13.07.2020', 'blanvalet', ARRAY['Deutsch']::text[], 504, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Oxy','Henri']::text[], '{}', '{}', 'ab8068d1-31f9-506c-8f0e-a06f4149eb09', '2', '{}', 'sheet', :'owner') on conflict do nothing;
