insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38f6f9dd-de32-5df4-9e78-9e61b4086293', 'Broken Bonds', NULL, '9791041200689', 'After the death of my mother and her Bonded, I was relieved to find my own Bonds. I was sure everything would be okay if I had them. It wasn’t. The fate of our people is in my hands and I know we’re better off if I’m alone. After five years on the run, I’m caught and dragged back to face the men I ran away from. I thought I was doing the right thing. Now, I’m not so sure. North, Nox, Gryphon, Atlas, and Gabe may never forgive me but one thing is for sure. I won’t ever forgive myself.', '13.09.2023', 'Korrigan', ARRAY['Englisch']::text[], 422, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Oli']::text[], '{}', '{}', '3f0ab07c-2c03-5a4d-b0f5-777e00e4c844', '1', '{}', 'sheet', :'owner') on conflict do nothing;
