insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fe330baa-6927-5a84-b1f0-f4d1a81eb70d', 'Shadows of Perl', NULL, NULL, 'Quell Marionne ist erneut zur Gejagten geworden. Nachdem sie während ihres Initiationsritus die zerstörerischen Schatten offenbart hat, die sie beherrscht, ist die Bruderschaft der Dragune hinter der jungen Magierin her. Denn ihre dunklen Kräfte sollen angeblich die Quelle der Magie selbst gefährden und sind daher streng verboten. Darum flüchtet Quell zum Haus Perl, wo ihr Unterschlupf gewährt wird. Zu ihren Verfolgern gehört ausgerechnet auch Jordan Wexton: zweiter Kommandant der Dragune und der Mann, dem Quells Herz gehört. Er hat geschworen, jede Bedrohung für die Magie auszuschalten - selbst wenn das bedeutet, die Frau zu töten, die er liebt. Aber werden sich die beiden voneinander fernhalten können, obwohl ihre Entscheidungen sie zu Feinden gemacht haben?', '25.04.2025', 'LYX', ARRAY['Deutsch']::text[], 541, 64, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Quell Marionne']::text[], '{}', '{}', 'a32a1f51-ff86-5453-b9cc-bfd258c777b2', '2', '{}', 'sheet', :'owner') on conflict do nothing;
