insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a3e63e0a-c0e7-5c38-a970-45151032e39b', 'House of Marionne', NULL, '9783736323124', 'Quell Marionne wurde mit einer verbotenen dunklen Magie geboren. Ständig auf der Flucht fällt ihr nur noch ein Ort ein, an den sie sich retten kann: das luxuriöse Internat House of Marionne. Unter der Leitung ihrer Großmutter werden dort Schüler:innen mit magischen Fähigkeiten ausgebildet, um nach dem Abschluss einer elitären Vereinigung beizutreten. Quell hofft, mehr über ihre Kräfte zu erfahren und sie vor der Welt verbergen zu können. Auch vor Jordan Wexton, dem attraktiven und talentierten Mündel ihrer Großmutter, der zu ihrem Tutor ernannt wird. Denn auch wenn beide sich dagegen zu wehren versuchen, bei jeder Begegnung knistert es stärker zwischen ihnen - obwohl nicht nur Quell ein tödliches Geheimnis hütet ...', '25.20.2024', 'LYX', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Quell Marionne']::text[], '{}', '{}', 'a32a1f51-ff86-5453-b9cc-bfd258c777b2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
