insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d2b1957-45ae-5433-a099-64d8bcfd4607', 'Into the Fire', 'Consumed', '9783736311398', 'Anne Ashburn ist Firefighterin mit Leib und Seele. Kein Feuer ist ihr zu gefährlich, kein Risiko zu hoch. Doch bei einem Einsatz unterschätzt sie die Gefahr und kommt fast ums Leben. Nur eine extreme Rettungsaktion von Danny Maguire, dem Bad Boy des Fire Departments, bewahrt sie vor dem sicheren Tod. Verletzt an Körper und Seele hat Anne danach nur noch ein Ziel: den Brandstifter zu finden, der für das Feuer verantwortlich ist, das ihr Leben so drastisch veränderte. Immer wieder trifft sie während ihrer Ermittlungen auf ihre alte Einheit - und Danny! Dabei lodern auch längst vergessene Gefühle wieder auf ...', '30.04.2020', 'LYX', ARRAY['Deutsch']::text[], 461, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Anne Ashburn','Danny Maguire']::text[], '{}', '{}', '55df5ba2-04c6-5125-8fd2-dc5e4ff1e23d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
