insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('23c8aadb-b58e-52c5-9b0c-95ebc6385494', 'Into the Heart', 'Wedding from Hell', '9783736313576', 'Anne Ashburn und Danny Maguire arbeiten in derselben Einheit des New Brunswick Fire Departments. Seit Anne vor zwei Jahren zu der Truppe gestoßen ist, knistert es zwischen ihnen, doch private Beziehungen innerhalb eines Teams sind verboten. Als ein Kollege heiratet, kommen sie sich während der Hochzeitsvorbereitungen näher und können sich der Leidenschaft, die zwischen ihnen herrscht, nicht länger erwehren. Aber dann kommt es zu einem Brand, der ihr Leben für immer verändern wird ...', '01.04.2020', 'LYX', ARRAY['Deutsch']::text[], 124, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Anne Ashburn','Danny Maguire']::text[], '{}', '{}', '55df5ba2-04c6-5125-8fd2-dc5e4ff1e23d', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
