insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('118f8d77-42d1-5cf3-a074-7b3b002849c4', 'Very Bad Kings', NULL, '9783969665169', 'Wir sind fünf Könige und teilen alles. Die Herrschaft über diesen Campus, unsere tödlichen Geheimnisse und … unsere Frauen. Niemand widersetzt sich unseren Regeln. Wie lange wird es dauern, bis du fällst? Mable ist eine von fünf Stipendiatinnen, die jedes Jahr an der Kingston University angenommen werden. Die reiche Elite des Colleges hält allerdings nichts vom Charity-Programm ihrer Eltern und will Mable mit aller Macht vertreiben. Allen voran die Kings. Fünf abtrünnige Seniorstudenten, die im Hintergrund ein unmoralisches Spiel veranstalten. Wird Mable gewinnen? Und wie soll sie sich dagegen wehren, dass drei der Kings plötzlich nur sie wollen? Du dachtest, Kingston biete dir eine akademische Zukunft? Lektion eins: Alles, was du je lernen wirst, ist das Überleben zwischen uns. Der Elite. Und wenn du deine Hausaufgaben nicht anständig machst, Belle, müssen wir dich leider bestrafen …', '10.06.2021', NULL, ARRAY['Deutsch']::text[], 447, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Kingston University', '{}', ARRAY['Mable']::text[], '{}', '{}', 'b476693f-1494-5ec4-b742-549f802ab912', '1', '{}', 'sheet', :'owner') on conflict do nothing;
