insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('42e30f0a-22f7-5d6e-8675-77c5eaa5e0bf', 'Die Auserwählten - Im Labyrinth', 'Maze Runner', '9783646921014', 'Sein Name ist Thomas. An mehr kann er sich nicht erinnern. Und er ist an einem bizarren Ort gelandet – einer Lichtung, umgeben von einem riesigen Labyrinth. Zusammen mit fünfzig Jungen, denen es genauso geht wie ihm, sucht Thomas einen Weg in die Freiheit. Der führt durch das Labyrinth, dessen gewaltige Mauern sich Nacht für Nacht verschieben, und in dem mörderische Kreaturen lauern. Doch gibt es wirklich einen Weg hinaus? Und wer hat sich dieses grauenvolle Szenario ausgedacht? Den Jungen bleibt nicht viel Zeit, um es herauszufinden ...', '21.03.2011', 'Carlsen', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Thomas']::text[], '{}', '{}', '8fdf0044-d5ff-5bde-87d1-970ecaf851d3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
