insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fad96a26-8334-5f9e-a765-7be40d0f1551', 'Die Auserwählten - In der Brandwüste', 'Scorch Trials', '9783646923278', 'Sie haben einen Ausweg aus dem tödlichen Labyrinth gefunden und geglaubt, endlich wären sie frei. Doch auf Thomas und seine Freunde wartet das Grauen: sengende Hitze, verbranntes Land und ein tödlicher Virus. Und noch immer halten die undurchsichtigen Schöpfer die Fäden in der Hand. Damit steht den Jungen die nächste Prüfung bevor. Sie müssen innerhalb von zwei Wochen die Brandwüste durchqueren, sonst sind sie verloren …', '26.06.2012', 'Carlsen', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Thomas']::text[], '{}', '{}', '8fdf0044-d5ff-5bde-87d1-970ecaf851d3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
