insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fafe2a71-7b80-5640-897b-f9a8502489c8', 'Die Auserwählten - In der Todeszone', 'Death Cure', '9783646924879', 'Thomas wird sich auf keinen Fall den Kopf aufschneiden lassen! Auch wenn er durch diese Operation sein Gedächtnis zurückbekommen soll. Denn den Wissenschaftlern von ANGST darf man nicht trauen. Nicht nach all den grausamen Prüfungen, die Thomas und seine Freunde durchstehen mussten. Nicht nach all den Versprechen, die gebrochen worden sind. Thomas muss endlich dafür sorgen, dass ANGST ihn nie wieder kontrollieren und manipulieren kann.', '24.05.2013', 'Carlsen', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Thomas']::text[], '{}', '{}', '8fdf0044-d5ff-5bde-87d1-970ecaf851d3', '3', '{}', 'sheet', :'owner') on conflict do nothing;
