insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('441fa0d6-cd4a-5ec1-b1a6-9bd6b544da3b', 'Dinosaurier-Freundschaft', 'Dinosaur Friendship', '9783847901921', 'Spätestens seit den ersten beiden Comic-Bänden des Erfolgsduos von @dinosaurcouch wissen wir: Dinosaurier sind auch nur Menschen! Genau wie wir versuchen sie, mit den Tücken des Alltags zurechtzukommen, genau wie wir sind sie psychisch oft etwas angeknackst, genau wie wir suchen sie nach einem tieferen Sinn im Leben. Und: Genau wie wir Menschen brauchen auch die knuffeligen Urzeit-Echsen echte Freund:innen, die ihnen zur Seite stehen - in guten wie in schlechten Zeiten. So erkunden die Dinos in diesem neuesten Buch die Bedeutung wahrer Freundschaft und wie wertvoll es ist, einander zu Halt zu geben. Voller Augenzwinkern und Hoffnung - die kleinen schlauen Dinos treffen mitten ins Herz!', '25.10.2024', 'Eichborn', ARRAY['Deutsch']::text[], 144, NULL, 'Comic'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['3P Objective']::text[], '{}', '{}', '{}', '3da5a2f5-5419-576f-a5e9-abd6dd0eaf2b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
