insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('be2db4ae-6aec-559f-947d-28b06acbe384', 'Rock My Heart', 'Mayhem', '9783734102684', 'Feiern, tanzen – einfach Spaß haben! Das ist der Plan von Rowan Michaels und ihrer Freundin Dee, als sie zu einem Konzert der Band The Last Ones to Know in den angesagtesten Club der Stadt gehen. Was Rowan allerdings gründlich die Laune versaut, ist ihr Freund Brady, den sie dort mit einer anderen Frau beim Knutschen sieht. Noch vor Beginn des Konzertes flüchtet sie nach draußen, und trifft dort auf Adam Everest, den absolut heißen, verdammt attraktiven Sänger der Band. Sie lässt sich zu einem Kuss hinreißen – zu einem Kuss, der nicht nur ihr ganzes Leben auf den Kopf stellen wird …', '13.02.2017', 'blanvalet', ARRAY['Deutsch']::text[], 369, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Rowan Michaels','Adam Everest']::text[], '{}', '{}', 'add6d6c8-1484-5541-9728-158de6f05ee4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
