insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('77fdb091-e0dc-584f-a0c4-4d5ec284425f', 'f1b92218-43fc-5030-9b26-44cb7393a4ba', :'owner', 1, '2020-07-31', '2020-08-01', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6c1bb836-87dd-5f6c-ba6d-9e355ef06b76', 'Riot', NULL, '9780062379672', 'When Dee Dawson meets sexy mohawked guitarist Joel Gibbon, she knows it won''t be long before she has him wrapped around her finger. No guy has ever been able to resist her … but Dee''s met her match in a player like Joel. Dee''s not the relationship type—not after seeing the pain "love" has caused her friends and family—yet she''s desperate to make Joel want her more than anyone else. He quickly becomes an obsession, and when a reckless attempt to make him jealous ends in disaster, Dee turns into the damsel in distress she never wanted to be. With her carefree world crashing down around her, the last thing she needs is Joel''s pity. But Joel is suddenly determined to prove he cares, and no matter how hard Dee tries to push him away, he refuses to let her shut him out. Now the girl who swore she''d never say those three little words must choose between guarding her heart and losing Joel forever … or falling head over heels for the tattooed rock star of her dreams.', '17.03.2015', 'Avon Impulse', ARRAY['Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dee Dawson','Joel Gibbon']::text[], '{}', '{}', 'add6d6c8-1484-5541-9728-158de6f05ee4', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
