insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('79984c71-318a-5fe8-b942-d462aec7aab0', 'Stolz und Vorurteil', 'Proud and Prejudices', NULL, 'Frauen sind Verfügungsmasse. Sie werden auserkoren, oder auch nicht. Jane Austens Roman folgt oberflächlich dem konservativen Wertesystem der damaligen Zeit, und ist gleichzeitig ein schreiender Protest dagegen: Ist das alles richtig so? Muss mein Leben so eingerichtet sein? Leben wir nicht in furchtbaren Zwängen? Das sind die Fragen, mit denen Elizabeth Bennet ringt. Hin- und her gerissen ist sie zwischen ihrem eigenen starken Willen, und dem, was die Gesellschaft von ihr erwartet. Abgestoßen und angezogen von ihrem Verehrer ist sie – gleichermaßen.', '1813', NULL, ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Historischer Liebesroman']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Elizabeth Bennet','Fitzwilliam Darcy']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
