insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('78936079-610c-52bb-90be-f16d17508397', 'Kollaps - Warum Gesellschaften überleben oder Untergehen', 'Collapse. How Societies Choose to Fail or Succeed', '9783596192588', 'Die überwucherten Tempelruinen von Angkor Wat, die zerfallenden Pyramiden der Maya in Yucatan und die rätselhaften Moai-Statuen der Osterinsel – sie alle sind stille Zeugen von einstmals blühenden Kulturen, die irgendwann verschwanden. Doch was waren die Ursachen dafür? Jared Diamond zeichnet in seiner erweiterten, faszinierenden wie hochaktuellen Studie die Muster nach, die dem Untergang von Gesellschaften (oder ihrem Überleben) zugrunde liegen, und zeigt, was wir für unsere Zukunft daraus lernen können.', '09.09.2011', 'Fischer', ARRAY['Deutsch']::text[], 736, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Politik & Gesellschaft', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
