insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1e9ebebe-80f5-5dfe-9055-5bdf1c7037c9', 'Grau', 'Shades of Grey - The Road to High Saffron', '9783838723327', 'Es läuft gut für Eddie Russett: Seine Rotsicht ist exzellent, er wird mit etwas Glück auf der Farbskala nach oben heiraten, und sein Leben plätschert angenehm ereignislos dahin - bis zu dem Tag, an dem er sich unrettbar und wider jede Vernunft verliebt. Denn Jane ist nicht nur geheimnisvoll und wunderbar stupsnasig, sie ist auch komplett farbenblind und gehört damit der gesellschaftlichen Unterschicht an: eine Graue! Jane hebt Eddies geordnete Welt aus den Angeln: Plötzlich hat er einflussreiche Feinde, wird mit unbequemen Wahrheiten konfrontiert, und zu allem Überfluss versucht seine Angebetete auch noch immer wieder, ihn umzubringen. Denn Jane hütet ein hochexplosives Geheimnis, und Eddie weiß bereits zu viel ...', '16.11.2012', 'eichborn', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Eddie Russett']::text[], '{}', '{}', '8b57de5a-771a-51bb-b8a2-7e8a7ce148c4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('692c4026-ccaa-5daf-9ac8-f8a9d40f1d91', :'owner', '1e9ebebe-80f5-5dfe-9055-5bdf1c7037c9', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2a2ef84d-9541-5a81-a4eb-68be02fd6a10', 'Rot', 'Red Side Story', '9783751755641', 'Fünfhundert Jahre nach dem von allen nur als »Etwas, das passiert ist« bezeichneten Ereignis ist eine neue Gesellschaft entstanden. Eine Gesellschaft, in der die eigene Stellung davon abhängt, welchen Teil des Farbspektrums man sehen kann. Dies ist die Welt, in der Eddie Russett und Jane Grey leben. Jane und Eddie müssen die engen Regeln der Farbpolitik überwinden und die Wahrheit über ihre Welt herausfinden: Was ist sie, wo ist sie, ja sogar, wann ist sie? Während sie die Lügen entlarven, die ihre Existenz bedrohen, kommen sie zu einem beunruhigenden Schluss: Sie sind nicht allein. Jenseits des Meeres ist die Welt überhaupt nicht zu Ende, hier fängt sie womöglich erst an.', '06.02.2024', 'eichborn', ARRAY['Deutsch']::text[], 507, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Eddie Russett']::text[], '{}', '{}', '8b57de5a-771a-51bb-b8a2-7e8a7ce148c4', '2', '{}', 'sheet', :'owner') on conflict do nothing;
