insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8650f382-a294-5ad1-a0a0-86966437be6b', 'For Whom the Belle Tolls', NULL, '9781398550711', 'Lily isn''t exactly thrilled with her arrival in the Afterlife, but what awaits her there is more fantastical than she ever could have imagined. Deities wait in line at the coffee shop. Fae flit between realms. Souls find ways to make death a beginning. As she explores the many corners of the Afterlife, Lily finds herself surprisingly drawn to a place most people would avoid at all costs: Hell. Armed with years of customer service experience and pent-up sarcasm, Lily carves a job out for herself amongst Hell''s demons, sending souls to their rightful circles with more than a hint of sass. Lily''s expectations are subverted every day in Hell - especially by Bel, a demon general with a distractingly sexy voice. The two meet by chance and form an immediate, deeply healing friendship, but the undeniable heat between them threatens to combust. Meanwhile, something stirs beyond the boundaries of their world, threatening to destroy everything they''ve known and everything that could be... unless they fight like Hell to stop it.', '06.05.2025', 'Simon & Schuster', ARRAY['Englisch']::text[], 621, 64, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Afterlife', ARRAY['Double POV','3P Limited']::text[], ARRAY['Lily','Bel']::text[], ARRAY['Forbidden Love','Found Family','Strong FMC']::text[], ARRAY['Tod','Tod von Familienangehörigen','Kindesmishandlung','Physische Gewalt','Religious Abuse']::text[], 'f560cf8d-3ee1-5c12-a0ac-2be333e1f197', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c9bbcecc-67f7-57e5-b9b8-d7d0215f16c1', :'owner', '8650f382-a294-5ad1-a0a0-86966437be6b', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print','Audiobook']::text[], ARRAY['eBook','Paperback']::text[], 'Normal', ARRAY['Map']::text[], 1950, false, false, ARRAY['Spotify']::text[], ARRAY['Elena Wolfe','Sean Masters']::text[], 1438, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 3, 'slow'::burn_kind, 'Ich habe noch nie ein Buch gelesen, dass so "wholesome" war und in dem so viele wichtige Themen aufgearbeitet wurden auf eine so angenehme Art und Weise. Die Charaktere haben sich einfach IMMER richtig verhalten und es war einfach nur schön.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c7e7b74e-c43d-5815-aad7-c6a843b6d5ed', 'c9bbcecc-67f7-57e5-b9b8-d7d0215f16c1', :'owner', 1, '2026-03-18', '2026-04-05', NULL, NULL, 19, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cc21817f-63ac-5091-b075-ffddafa06940', 'The Beast', NULL, NULL, 'What if the Beast never turned into the prince? My father had just sold me off. Bartered my body to erase his debt to the very devil himself. A Beast of a man. Literally. A creature whispered about amongst the villagers and feared by all. He was a beastly visage at three times the size of a man, his monstrously huge body covered in fur. Sharp fangs and eyes that held an unearthly red glow. He had pawlike hands tipped with claws and horns that arched back from his inhuman face. I was to live with him, to be his in every way—all ways—he saw fit. I was to be his wife, and so I offered myself up as the proverbial sacrifice to the very devil himself. I just didn’t expect to enjoy being with a monster as much as I did.', '13.06.2022', NULL, ARRAY['Englisch']::text[], 122, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Bella','Beast']::text[], ARRAY['Fairytale Retelling']::text[], '{}', 'e7de2e83-d1f7-5913-91a5-a4f16b342c66', '1', '{}', 'sheet', :'owner') on conflict do nothing;
