insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('883d03f2-7ff0-5353-b0f7-95b9a82909ff', 'The Demon', NULL, NULL, 'I ran from one monster, only to stumble into the clutches of another.Fleeing a brutal father and a forced marriage, I escaped deep into the forest, hoping to disappear.Bleeding, exhausted, and desperate, I hid in a cave–but I quickly realized I wasn’t alone.Something watched me from the darkness.He was massive, horned… a creature pulled from nightmares.And the moment his glowing eyes locked onto me, I knew one thing without a doubt. I was his.Now, I was trapped in his lair, claimed by a beast who refused to let me go.I thought I was running toward freedom.But I only ran straight into his arms.And I was even more terrified, because… I didn’t want to leave.', '24.02.2025', NULL, ARRAY['Englisch']::text[], 64, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', '{}', ARRAY['Fairytale Retelling']::text[], '{}', 'e7de2e83-d1f7-5913-91a5-a4f16b342c66', '4', '{}', 'sheet', :'owner') on conflict do nothing;
