insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dd33a4d7-dfb7-57b7-ae17-4bc24c868937', 'One True Queen - Von Sternen gekrönt', 'One True Queen', '9783473401796', 'Dunkelheit. Das Gefühl, zu fallen. Und dann: nichts. Eben noch stand Mailin in ihrer Heimatstadt, plötzlich wacht sie in einer anderen Welt auf. Im Königreich Lyaskye trachtet ihr alles und jeder nach dem Leben – nur nicht der mysteriöse Fremde, der Mailin aus einer Falle rettet. Der so gefährlich wirkt und sie dennoch beschützt. Erst als er sie zum Königshof bringt, erkennt Mailin, dass sie nicht ohne Grund in Lyaskye ist: Sie soll Königin werden. Und das ist in dieser Welt ein Todesurteil.', '21.08.2019', 'Ravensburger', ARRAY['Deutsch']::text[], 509, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Königreich Lyaskye', '{}', ARRAY['Mailin']::text[], '{}', '{}', 'ca58c511-6884-5d86-9266-b3e6d27d543e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
