insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b047da5f-414d-59a5-aa73-03574b26fadb', 'One True Queen - Aus Schatten geschmiedet', 'One True Queen', '9783473401840', 'Mailins Schicksal ist besiegelt: Sie wurde zur Königin von Lyaskye gekrönt und damit ist ihr Leben verwirkt, sollte sie je wieder einen Fuß in ihr Königreich setzen. Allerdings ist genau das Mailins Ziel. Denn wie soll sie in ihr altes Leben zurückkehren, wenn ihr Herz bei Liam geblieben ist? Mailin muss zu ihm, koste es, was es wolle. Doch um nach Lyaskye zurückzukehren, braucht sie ausgerechnet Nathaniel, den Königskrieger und Weltenspringer, dem sie das Herz aus der Brust gerissen hat …', '22.01.2020', 'Ravensburger', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Königreich Lyaskye', '{}', ARRAY['Mailin']::text[], '{}', '{}', 'ca58c511-6884-5d86-9266-b3e6d27d543e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
