insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7ed0a71-e375-5211-afb2-71e228f5e63a', 'The Right Kind of Wrong', NULL, '9783958184725', 'Zoes Leben könnte perfekt sein. Sie hat sich aus den Fesseln ihres Ex-Partners gelöst und lebt zusammen mit ihrer besten Freundin Kate im Herzen Londons. Wären da nicht ihre inneren Dämonen und der Druck ihrer Eltern, die ihr jeden Tag die Luft zum Atmen nehmen. Als Kates neuer Freund Noah vorübergehend bei ihnen einzieht, ist Chaos vorprogrammiert. Obwohl ihr Aufeinandertreffen alles andere als reibungslos verläuft, fühlt sich Zoe mit der Zeit dank Noahs Hilfe freier, lebendiger und mutiger als jemals zuvor. Zoe weiß, dass Noah tabu ist, und trotzdem knistert es zwischen ihnen gewaltig. Zwischen Sehnsucht und Schuldgefühlen steht Zoe bald vor einer Entscheidung, die alles verändern könnte: Freundschaft oder Liebe?', '31.01.2020', 'Forever', ARRAY['Deutsch']::text[], 420, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Zoe']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
