insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('68b76974-cd83-5876-81be-0c1fb8ded4e7', '453c8aa9-0dc0-53b5-bca7-a2403a02ff12', :'owner', 1, '2021-04-11', '2021-04-18', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c44e8bb0-6ac2-5b9b-902e-5fe458155455', 'Everything We Had', NULL, '9783864931611', 'Offen, optimistisch, lebensfroh – das ist Kate. Bis ein zutiefst traumatisches Erlebnis sie aus der Bahn wirft. Sie bricht das College in London ab und zieht sich zurück. Nur eines hält sie aufrecht: ihr Traum vom eigenen Café. Als sie die Chance bekommt, einen kleinen Laden in London zu mieten, setzt sie alles auf eine Karte. Doch sie hat die Rechnung ohne Aidan gemacht. Der Neffe der Inhaberin möchte das Geschäft in einen Buchladen verwandeln. Um ihren Traum zu verwirklichen, muss Kate mit Aidan zusammenarbeiten. Dabei kommen sie einander gefährlich nahe. Doch Kate kann es sich nicht leisten, dass jemand einen Blick hinter ihre Fassade wirft und entdeckt, dass ihre Seele in Scherben liegt …', '03.05.2021', 'Forever', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Kate']::text[], '{}', '{}', '9ed14fc3-153f-501d-ac52-a5b1a9716b93', '1', '{}', 'sheet', :'owner') on conflict do nothing;
