insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bdcfb426-2586-5187-8e7a-4cb9f05f763e', 'Onyx - Schattenschimmer', 'Onyx', '9783646926392', 'Seit Daemon Katy geheilt hat, sind sie für immer miteinander verbunden. Doch heißt das, dass sie auch füreinander bestimmt sind? Auf keinen Fall, findet Katy und versucht sich gegen ihre Gefühle zu wehren. Das ist allerdings gar nicht so einfach, denn Daemon ist nun fest entschlossen, sie für sich zu gewinnen. Dann taucht ein neuer Mitschüler auf – und mit ihm eine dunkle Gefahr. Katy weiß nicht mehr, wem sie trauen kann. Was geschah mit Daemons Bruder? Welche Rolle spielt das zwielichtige Verteidigungsministerium? Und wie lange wird sie Daemons enormer Anziehungskraft noch widerstehen können?', '21.11.2024', 'Carlsen', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', '{}', ARRAY['Katy','Daemon Black']::text[], '{}', '{}', '53dc4781-262a-5f62-aaee-cbcc9a041b39', '2', '{}', 'sheet', :'owner') on conflict do nothing;
