insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8e7d7cba-21ca-5fb3-86ff-9d2a64889ccf', 'Opal - Schattenglanz', 'Opal', '9783646926606', 'Auf den ersten Blick ist alles perfekt: Dawson lebt noch und niemand scheint nach ihm zu suchen. Katy wehrt sich nicht länger gegen ihre Gefühle für Daemon und alles könnte so schön sein – aber es ist nur die Ruhe vor dem Sturm. Plötzlich ist Blake zurück und mit ihm ein gewagter Plan. Zu Katys großem Erstaunen bittet er sie um Hilfe. Katy weiß nicht, was sie tun soll, denn Blake ist nicht zu trauen, das hat sie schon einmal schmerzlich zu spüren bekommen. Doch für ihre Freunde – und für Daemon – würde sie alles tun. Selbst ihr eigenes Leben aufs Spiel setzen.', '24.04.2015', 'Carlsen', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', '{}', ARRAY['Katy','Daemon Black']::text[], '{}', '{}', '53dc4781-262a-5f62-aaee-cbcc9a041b39', '3', '{}', 'sheet', :'owner') on conflict do nothing;
