insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('597d6d9e-abe7-5339-abec-395a3c7870d2', 'Origin - Schattenfunke', 'Origin', '9783646927580', 'Daemons Leben hat jeglichen Wert verloren, seit Katy von Daedalus festgehalten wird. Auch Katy ist verzweifelt. Täglich muss sie neue Experimente über sich ergehen lassen. Trotzdem beginnt sie zu ahnen, dass Daedalus nicht nur schlechte Seiten hat. Und sind die Lux wirklich so friedlich, wie sie es bisher immer annahm? Wer sind hier die Guten und wer die Bösen? Katy ist fest entschlossen, eine Antwort auf diese Fragen zu finden – doch dann könnte es bereits zu spät sein. Vor allem, wenn Daemon bis dahin nicht wieder an ihrer Seite ist …', '18.12.2015', 'Carlsen', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', '{}', ARRAY['Katy','Daemon Black']::text[], '{}', '{}', '53dc4781-262a-5f62-aaee-cbcc9a041b39', '4', '{}', 'sheet', :'owner') on conflict do nothing;
