insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('48b18ca9-4bd4-540a-b75b-442d25e483f3', 'Opposition', NULL, '9781633757042', 'Katy knows the world changed the night the Luxen came. She can''t believe Daemon stood by as his kind threatened to obliterate every last human and hybrid on Earth. But the lines between good and bad have blurred. Daemon will do anything to save those he loves, even if it means betrayal. But when it quickly becomes impossible to tell friend from foe, and the world is crumbling around them, they may lose everything to ensure the survival of their friends…and mankind.', '08.11.2016', 'Entangled', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', '{}', ARRAY['Katy','Daemon Black']::text[], '{}', '{}', '53dc4781-262a-5f62-aaee-cbcc9a041b39', '5', '{}', 'sheet', :'owner') on conflict do nothing;
