insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4f1c2158-8060-59c9-ab26-a27b6099fa37', 'Blood and Ash', 'From Blood and Ash', '9783453321410', 'Poppy ist eine Auserwählte. Wenn sie den Segen der Götter erhält, wird sie die Einzige sein, die ihre Heimat vor dem Angriff des Verfluchten Königreiches retten kann. So will es die Tradition. So will es das Gesetz. Das Leben einer Auserwählten ist einsam. Niemand darf sie ansehen, geschweige denn mit ihr sprechen oder sie berühren. Eines Tages wird der attraktive Hawke – mit den goldenen Augen, dem frechen Grinsen und den provokanten Sprüchen – Poppys Leibwache zugeteilt, und sie merkt, dass es in ihrem Leben so viel mehr geben könnte als nur ihr Amt. Dass sie ein Herz hat, eine Seele und die Sehnsüchte einer ganz normalen jungen Frau. Als an den Landesgrenzen die Schatten der Verfluchten immer drohender werden, muss Poppy sich zwischen Liebe und Pflicht entscheiden ...', '12.07.2021', 'Heyne', ARRAY['Deutsch']::text[], 666, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', '{}', ARRAY['Poppy']::text[], '{}', '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '1', '{}', 'sheet', :'owner') on conflict do nothing;
