insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('66126289-6f79-562b-93b3-1ae8b279a2c7', 'Obsidian - Schattendunkel', 'Obsidian', '9783551316011', 'Als Katy vom sonnigen Florida ins graue West Virginia ziehen muss, ist sie alles andere als begeistert. In dem kleinen Nest kommt sie anfangs nicht einmal ins Internet, was für die leidenschaftliche Buchbloggerin eine Katastrophe ist. Sie beschließt, bei ihren Nachbarn zu klingeln, und lernt so den atemberaubend gut aussehenden, aber unfassbar unfreundlichen Daemon Black kennen. Was Katy jedoch nicht weiß, ist, dass genau dieser Junge, dem sie von nun an aus dem Weg zu gehen versucht, ihrem Schicksal eine ganz andere Wendung geben wird …', '10.01.2018', 'Carlsen', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'West Virginia', '{}', ARRAY['Katy','Daemon Black']::text[], '{}', '{}', '53dc4781-262a-5f62-aaee-cbcc9a041b39', '1', '{}', 'sheet', :'owner') on conflict do nothing;
