insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e88c64e5-b154-591a-a38b-3cb0c5f73c35', 'Light and Flame', 'A Light in the Flame', '9783453322875', 'Kolis, der falsche König der Götter, ist ins Iliseeum zurückgekehrt und droht nicht nur die Welt der Götter, sondern auch die der Sterblichen in ewige Dunkelheit zur stürzen. Seraphena Mierel, die einst sterbliche Prinzessin, die die Macht der Primarin des Lebens in sich erstarken fühlt, ist die Einzige, die Kolis aufhalten kann. Doch dazu braucht sie die Hilfe von Nyktos, dem Primar des Todes – dem Mann, den sie heiraten, verführen und töten sollte. Doch inzwischen liegen die Dinge anders: Sera will nicht mehr nur der Form halber Nyktos Gemahlin sein, sie hat sich unsterblich in ihren Gatten verliebt. Doch Nyktos hat von Seras Mission erfahren und sein Vertrauen in sie ist erschüttert. Als Kolis Angriffe sich verstärken, muss Sera kämpfen – nicht nur um ihr eigenes Überleben und das der Welten, sondern auch um Nyktos'' Liebe ...', '11.10.2023', 'Heyne', ARRAY['Deutsch']::text[], 848, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Lasania, Iliseeum', '{}', ARRAY['Seraphena Mierel']::text[], '{}', '{}', 'ebc6591d-e6ad-5fff-8851-5e42971ef8fd', '2', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
