insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ec726888-4117-5cb6-8aab-a7633146b41e', 'Fire in the Flesh', 'A Fire in the Flesh', '9783453323407', 'Nach einem schrecklichen Verrat befinden sich Sera und Nyktos in der Gewalt des falschen Königs der Götter. Kolis glaubt, in Sera die Wiedergeburt seiner großen Liebe gefunden zu haben, und wenn sie Nyktos befreien und einen Krieg zwischen den Primaren verhindern will, muss Sera dafür sorgen, dass das auch so bleibt. Zwar wurde sie ihr ganzes Leben lang darin ausgebildet, einen Gott zu verführen – doch einen Gott zu verführen, während ihr Herz einem anderen gehört, darauf war sie nicht vorbereitet ...', '16.10.2024', 'Heyne', ARRAY['Deutsch']::text[], 688, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Lasania, Iliseeum', '{}', ARRAY['Seraphena Mierel']::text[], '{}', '{}', 'ebc6591d-e6ad-5fff-8851-5e42971ef8fd', '3', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
