insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f48500e9-3662-50c5-ae84-0be1f0084f8d', '986c88cd-f665-5bd9-a87f-d4e750706f5d', :'owner', 1, '2024-10-16', '2024-10-29', NULL, NULL, 14, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d576b04b-fa92-5f98-a82a-82264624b01c', 'Soul and Ash', 'A Soul of Ash and Blood', '9783453323162', 'Der Kampf den Poppy, Casteel und ihre Getreuen ausfechten müssen, hat gerade erst begonnen. Überall – sowohl im Iliseeum als auch in der Welt der Sterblichen – erwachen die Götter und bereiten sich auf den Krieg vor. Als Poppy kurz davor steht, die Fülle ihrer Macht zu erlangen, fällt sie ins Koma, und Cas muss fürchten, sie für immer zu verlieren. Die einzige Chance auf Rettung liegt in ihrer gemeinsamen Vergangenheit, und so beginnt für die beiden Liebenden eine Reise zum Beginn ihrer Geschichte …', '15.05.2024', 'Heyne', ARRAY['Deutsch']::text[], 800, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', '{}', ARRAY['Poppy']::text[], '{}', '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '5', '{}', 'sheet', :'owner') on conflict do nothing;
