insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('4bcbf553-4a1d-5fbc-82e8-ae57dc5c1187', '126ae939-38d3-56fc-aebc-424190c87453', :'owner', 1, '2024-06-04', '2024-06-18', NULL, NULL, 15, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d9b97ccd-2365-5cba-9039-6669b873c35e', 'Born of Blood and Ash', NULL, '9783453323537', 'Nachdem Sera sich in die Hände Kolis‘ begeben hat, musste sie zahlreiche Prüfungen über sich ergehen lassen. Die schwerste war jedoch, die Trennung von ihrem geliebten Nyktos zu ertragen. Nun sind Sera und Nyktos endlich wieder vereint, doch Kolis ist noch immer an der Macht. Wird es den beiden gelingen, das Reich der Sterblichen und das der Primare vor dem falschen König der Götter zu retten? Und wird ihre Liebe diese Zerreißprobe überstehen?', '12.03.2025', 'Heyne', ARRAY['Deutsch']::text[], 1229, 65, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Lasania, Iliseeum', '{}', ARRAY['Seraphena Mierel']::text[], '{}', '{}', 'ebc6591d-e6ad-5fff-8851-5e42971ef8fd', NULL, ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
