insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('1210d5c3-bac6-5c52-aea5-02198d5395cf', '2e002924-bcef-589d-a949-e00c2b9c32bd', :'owner', 1, '2024-11-01', '2024-12-06', NULL, NULL, 36, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('07aa5083-8ff2-568f-99c4-871630801ce7', 'The Primal of Blood and Bone', NULL, '9781963135480', 'What was dreamt. Poppy was never meant to awaken, and the consequences are devastating and far-reaching, stirring ancient powers from their slumber and transforming Casteel and Kieran in ways even the Fates couldn’t have foreseen. But what that means is the least of their concerns. For now. What was foreseen. The Blood Crown has fallen, but what has risen is a far greater danger than they’ve ever faced. From flesh and fire, the Great Conspirator has returned to the mortal realm, and he wants only one thing. They must stop the true Primal of Death before he regains his strength, and it won’t be easy. Even weakened, his influence is undeniable. His power, unthinkable. Has come to be. While the future of the realms rests upon them, they won’t stand alone. The gods have awakened—each harboring their own blood-soaked secrets. But they must navigate an unbalanced realm, where every choice—past and present—has the potential to not only undo everything they’ve fought for but also destroy the very bonds that have Joined them together. For the Harbinger and the Bringer of Death and Destruction has risen.', '23.09.2025', 'Simon & Schuster', ARRAY['Englisch']::text[], 1288, 60, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', ARRAY['Multiple POV','1P']::text[], ARRAY['Poppy']::text[], ARRAY['Ancient Secrets','End of World','Prophezeiung']::text[], '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '6', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ba8b58a8-a549-57a2-9c5a-f7b34c6b02a5', :'owner', '07aa5083-8ff2-568f-99c4-871630801ce7', 'abgebrochen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 849, false, false, ARRAY['Audible']::text[], ARRAY['Stina Nielsen','Tim Campbell','Dane Williams']::text[], 2434, '👍🏻', false, 'solo'::company_kind, 'hate'::verdict_kind, 0.0, 'untertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Mal abgesehen davon, dass das Buch nur aus unnötigen Infos besteht, sind mir die Charaktere auch einfach nur auf den Geist gegangen. Vor allem Casteel. Es nervt, dass ihn wirklich NICHTS interessiert außer Poppy. Get your shit together.... es gibt auch noch andere wichtige Sachen. Ich musste dieses Buch abbrechen, weil es mich einfach so sehr genervt hat. Ich bin bis Seite 518 gekommen und es ist einfach noch nichts relevantes passiert. Die Autorin weiß einfach nicht wie man sich kurzfasst und nicht andauern widerholt.') on conflict do nothing;
