insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8351c249-2eb5-565c-a0e2-9115f9dab4ee', 'Shadow and Ember', 'A Shadow in the Ember', '9783453322387', 'Seraphena Mierel ist die erstgeborene Tochter des Königs von Lasania. Doch in ihrem Fall bedeutet das nicht, dass sie auch die Thronerbin ist, denn ihr Schicksal stand schon lange vor ihrer Geburt fest: Sie würde Nyktos, Primar des Todes heiraten, als Gegenleistung für einen Pakt, den ihre Vorfahren einst geschlossen hatten. Seras Aufgabe könnte nicht eindeutiger sein: Bring den Primar dazu, sich in dich zu verlieben. Töte ihn. Rette Lasania. Doch als Sera den geheimnisvollen Ash kennenlernt, gerät ihre Entschlossenheit ins Wanken. Wird sie es schaffen, ihre Pflicht zu erfüllen und ihr Königreich über ihre Gefühle zu stellen?', '09.11.2022', 'Heyne', ARRAY['Deutsch']::text[], 779, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Lasania, Iliseeum', '{}', ARRAY['Seraphena Mierel']::text[], '{}', '{}', 'ebc6591d-e6ad-5fff-8851-5e42971ef8fd', '1', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
