insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('745c0fbd-0501-580d-9ad7-7961e14fc480', 'Flesh and Fire', 'Kingdom of Flesh and Fire', '9783453321533', 'Alles, woran die junge Poppy jemals geglaubt hat, hat sich als Lüge herausgestellt. Auch ihre große Liebe. Das Volk, das sie bis vor Kurzem noch als Auserwählte verehrt hat, will nun ihren Tod. Ihr ganzes Leben lang hat Poppy sich auf ihr Amt vorbereitet – wenn sie keine Auserwählte mehr ist, was ist sie dann? Als sich der ebenso attraktive wie dunkle Prinz von Atlantia erhebt, ist Poppy gezwungen zu kämpfen, wenn sie das Königreich retten will. Doch der Prinz verwickelt sie in ein perfides Spiel aus Intrigen und Verrat, und schon bald kann Poppy niemandem mehr trauen – nicht einmal sich selbst ...', '08.03.2022', 'Heyne', ARRAY['Deutsch']::text[], 830, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', '{}', ARRAY['Poppy']::text[], '{}', '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '2', '{}', 'sheet', :'owner') on conflict do nothing;
