insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b773342f-3cd0-54c2-8600-0e2e6ffd194c', 'Crown and Bones', 'The Crown of Gilded Bones', '9783453321540', 'Niemals hätte die Auserwählte Poppy gedacht, einmal die große Liebe zu finden. Doch bevor sie und Prinz Casteel ihr Glück genießen können, müssen sie Casteels Bruder aus seiner Gefangenschaft befreien. Ihre Mission gerät in Gefahr, als sich im fernen Westen die Blutkönigin erhebt, um Atlantia ein für alle Mal zu vernichten. Wie weit wird das königliche Paar gehen, um sein Volk – und seine Liebe – zu retten?', '09.05.2022', 'Heyne', ARRAY['Deutsch']::text[], 782, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', '{}', ARRAY['Poppy']::text[], '{}', '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '3', '{}', 'sheet', :'owner') on conflict do nothing;
