insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4ab4a00d-b490-5e73-9e19-7fd762a10e74', 'War and Queens', 'The War of Two Queens', NULL, 'Nachdem die Blutkönigin Casteel in ihre Gewalt gebracht hat, erklärt Poppy ihr den Krieg. Sie ist fest entschlossen, ihre große Liebe zu retten und die Aufgestiegenen daran zu hindern, Atlantia und Solis einzunehmen. Doch der Kampf gegen die Aufgestiegenen ist erst der Beginn: In den Schatten sind uralte Mächte erwacht, die die Schrecken längst vergangener Zeiten mit sich bringen. Nun ist die Stunde gekommen, in der Poppy ihr Schicksal annehmen und die Prophezeiung erfüllen muss ...', '09.11.2022', 'Heyne', ARRAY['Deutsch']::text[], 877, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Solis, Antlantia', '{}', ARRAY['Poppy']::text[], '{}', '{}', '70beb366-44e1-5a1b-90c3-63be3ff49012', '4', '{}', 'sheet', :'owner') on conflict do nothing;
