insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0f47c114-bd04-5f84-abdc-321e5d63bd1d', 'Der Klon', NULL, '9783641241551', 'Berlin im Jahr 2033. Die Journalistin Mara Erhardt hat herausgefunden, dass ein koreanischer Biologe jahrelang illegal Menschen geklont hat. Eine Spur führt nach Berlin, zu zwei Studenten. Doch als sie die jungen Männer ausfindig macht, überstürzen sich die Ereignisse. Denn es gibt noch eine Spur nach Deutschland – zu einem Klon des größten Verbrechers der Geschichte: Adolf Hitler. Und die Auftraggeber wollen nicht, dass dessen Identität zu früh enttarnt wird. Für Mara beginnt ein tödlicher Wettlauf gegen die Zeit – und gegen eine verhängnisvolle Wiederholung der deutschen Vergangenheit …', '14.06.2022', 'Heyne', ARRAY['Deutsch']::text[], 481, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Berlin', '{}', ARRAY['Mara Erhardt']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
