insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e5f71c0b-b471-58f4-88e5-fca42def41d0', 'Our Sunny Days (Vol.1)', '해 뜨는 집', '9783989501041', 'Ho Sung hat seine Ex-Freundin ein Jahr lang nicht gesehen - bis sie plötzlich vor ihm steht, ihm ein Baby überreicht, \nund wieder verschwindet.Trotz der Umstände erfüllt Ho Sung die Vorstellung, zum ersten Mal eine Familie zu haben, mit unerwarteter Freude. Kurzerhand lässt er sein Leben beim Militär hinter sich und zieht aufs Land, um als alleinerziehender Vater ein neues Leben anzufangen. \n\nUnd als er beim Besuch des örtlichen Supermarktes dem schroffen Ladenbesitzer Haebeom Kwon begegnet, wird sein Leben endgültig auf den Kopf gestellt ...', '13.10.2025', 'Papertoons', ARRAY['Deutsch']::text[], 240, 12, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nuldongmae', ARRAY['3P Objective']::text[], ARRAY['Ho Sung','Haebeom']::text[], ARRAY['Queer','Family Drama']::text[], ARRAY['Tod von Familienangehörigen']::text[], 'c3a4620d-b2c8-5ada-b2de-c00f0ee932ed', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('b91fe7f6-43f9-53eb-9fcd-dece6379ae2f', :'owner', 'e5f71c0b-b471-58f4-88e5-fca42def41d0', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1800, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'uebertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Mir ist jedes mal das Herz aufgegangen, wenn diese zwei Männer sich so herzerwärmend um das kleine Baby kümmern. Einfach nur ZUCKER! Ich finde es einfach zu süß wie Haebeom versucht ein harter Kerl zu sein, doch eigentlich ist er einfach nur sweet.') on conflict do nothing;
