insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('063ed98f-5353-5633-9f31-81c493a761e7', 'Our Sunny Days (Vol.2)', '해 뜨는 집', '9783989501904', 'Obwohl ihr erstes Zusammentreffen etwas holprig verlief, haben sich Ho und Haebeom schnell angefreundet … und sind einander überraschend nähergekommen. \nHo tut den gemeinsamen Kuss zwar als Versehen ab, aber Haebeom geht die Sache nicht mehr aus dem Kopf! Wenn der Neuankömmling im Dorf wirklich nicht schwul ist, warum halten sie dann gerade unter dem Sternenhimmel Händchen? Was soll das bitte werden …?', '19.01.2026', 'Papertoons', ARRAY['Deutsch']::text[], 272, 13, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nuldongmae', ARRAY['3P Objective']::text[], ARRAY['Ho Sung','Haebeom']::text[], ARRAY['Queer','Family Drama']::text[], ARRAY['Tod von Familienangehörigen']::text[], 'c3a4620d-b2c8-5ada-b2de-c00f0ee932ed', '2', '{}', 'sheet', :'owner') on conflict do nothing;
