insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('8ce6f824-e33a-5a1e-bf11-2cea92d6f3de', :'owner', '1a22bb86-e571-5ac4-be95-b836fc2d6ea7', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Limited', '{}', 1800, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 1, 'slow'::burn_kind, 'Die Geschichte ist einfach schön. Ich liebe es wie über die verschiedensten Probleme gesprochen wird und wie positiv die Charaktere denken. Einfach süß. Außerdem habe ich das Gefühl meine Familie mehr schätzen zu müssen nach dieser Story.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('63d70625-8bd2-5e09-a971-ecd7c8a88ff0', '8ce6f824-e33a-5a1e-bf11-2cea92d6f3de', :'owner', 1, '2026-07-21', '2026-07-21', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e501b3d7-d0c6-5546-8efc-27b1b09918bf', 'Mein Herz wird dich finden', 'Things We Know by Heart', '9783733602246', 'Eine Liebe, die tragisch endet. Eine neue Liebe, die tragisch beginnt. Ein Herz, das nicht aufhört zu lieben. Und am Ende der Tränen: das Glück. 400 Tage ist es her. Vor 400 Tagen ist Mias große Liebe bei einem Autounfall ums Leben gekommen. Vor 400 Tagen hat Noah eine zweite Lebenschance bekommen. Als sie einander begegnen, spüren sie beide sofort, dass sie zusammen gehören. Doch nur Mia weiß, dass Noah ihr niemals begegnen wollte. Dass sie gegen seinen ausdrücklichen Willen gehandelt hat, als sie sich auf die Suche nach ihm gemacht hat. Dass Noah niemals wissen wollte, wer vor 400 Tagen ums Leben gekommen ist. Weil es irgendwie nicht richtig ist, dass er weiterleben darf – nur weil jemand anderes gestorben ist. Doch für Mia ist es, als wäre die Welt plötzlich wieder in Ordnung. Als wäre das Leben wieder bunt und schön. Und als hätte sie Noah nicht verschwiegen, dass sie einander nur begegnet sind, weil sie wissen wollte, wer der Mensch ist, der das Spenderherz ihres Freundes bekommen hat. Doch wie glücklich darf sie nach Jacobs Tod eigentlich sein? Und wann wird aus Schweigen … Verrat? Mia muss Noah erzählen, wer sie ist. Aber was bedroht ihre Liebe mehr? Eine Lüge – oder die Wahrheit?', '25.02.2016', 'Fischer', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mia','Noah']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
