insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3bd82d07-e18f-5633-b14d-df5083ae08e7', 'Eine Liebe über dem Meer', 'Letters from Skye', '9783641122669', 'Isle of Skye, 1912. Eines Tages erhält die schottische Schriftstellerin Elspeth einen Brief aus Amerika. Der Absender, ein junger Mann namens David, bewundert ihre Gedichte. Obwohl ein Ozean zwischen ihnen liegt, ist es der Beginn einer tiefen Liebe. Erst die Wirren des Weltkrieges führen die beiden zusammen, nur um sie unter tragischen Umständen wieder zu trennen. Mehr als zwei Jahrzehnte später stößt Elspeths Tochter Margaret auf Davids Briefe und kommt so der Geschichte dieser schicksalhaften Liebe auf die Spur …', '24.03.2014', 'Diana', ARRAY['Deutsch']::text[], 336, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Historischer Liebesroman']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Isle of Skye', '{}', ARRAY['Elspeth','David']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
