insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('849f6a5e-7006-566f-9a25-2ed3d8585526', 'The Hollow - Wahre Liebe ist unsterblich', 'The Hollow', '9783401064956', 'Abbeys beste Freundin Kristen ist verschwunden. Alle Bewohner von Sleepy Hollow glauben, dass das Mädchen tot ist. Dann taucht plötzlich Caspian auf - ein umwerfender, rätselhafter Junge, der immer dort aufkreuzt, wo auch Abbey ist. Und schließlich stößt sie im Tagebuch ihrer Freundin auf ein dunkles Geheimnis - und muss bald erfahren, dass auch Caspian nicht der ist, der er zu sein scheint.', '01.06.2010', 'Arena', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Sleepy Hollow', '{}', ARRAY['Abbey','Caspian']::text[], '{}', '{}', '1ef96e80-a28f-578a-a4a4-12fc48c7fc18', '1', '{}', 'sheet', :'owner') on conflict do nothing;
