insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0d6b3771-1825-54bd-bb8e-faea2a67a1b1', 'The Haunted - Wahre Liebe ist unsterblich', 'The Haunted', '9783401066714', 'Abbey hat sich damit abgefunden, dass Caspian kein Geist, sondern reine Halluzination ist. Sie beschließt, ihr Leben wieder selbst in die Hand zu nehmen. Doch dann kehrt Caspian zurück – und Abbey kann sich ihm einfach nicht entziehen. Als sie kurz davor steht, das Rätsel um den Tod ihrer besten Freundin zu lösen, muss sie eine Entscheidung treffen, bei der ihre Liebe und ihr Leben auf dem Spiel stehen.', '01.03.2011', 'Arena', ARRAY['Deutsch']::text[], 424, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Sleepy Hollow', '{}', ARRAY['Abbey','Caspian']::text[], '{}', '{}', '1ef96e80-a28f-578a-a4a4-12fc48c7fc18', '2', '{}', 'sheet', :'owner') on conflict do nothing;
