insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8c69ea0c-a505-514e-a7ff-cfe1747f0c8e', 'Picnic the Hanging Rock', NULL, '9780099577140', 'A cloudless summer day in the year nineteen hundred... Everyone at Appleyard College for Young Ladies agreed it was just right for a picnic at Hanging Rock. After lunch, a group of three girls climbed into the blaze of the afternoon sun, pressing on through the scrub into the shadows of Hanging Rock. Further, higher, till at last they disappeared. They never returned.', '07.02.2013', 'Random House UK', ARRAY['Englisch']::text[], 210, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, NULL, 'Mount Macedon, Victoria', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
