insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('200894c3-7c38-5b84-a6a1-e5c15ef8e5aa', 'Harry Potter and the Chamber of Secrets', NULL, NULL, 'Harry Potter''s summer has included the worst birthday ever, doomy warnings from a house-elf called Dobby, and rescue from the Dursleys by his friend Ron Weasley in a magical flying car! Back at Hogwarts School of Witchcraft and Wizardry for his second year, Harry hears strange whispers echo through empty corridors - and then the attacks start. Students are found as though turned to stone... Dobby''s sinister predictions seem to be coming true.', '02.07.1998', 'Bloomsbury', ARRAY['Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Hogwarts', '{}', ARRAY['Harry Potter']::text[], '{}', '{}', '73c84852-b198-531f-a74d-3ebbb12e089f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
