insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('df8711c2-1f8e-5826-89ac-3161a9874b28', 'Harry Potter and the Goblet of Fire', NULL, NULL, 'The Triwizard Tournament is to be held at Hogwarts. Only wizards who are over seventeen are allowed to enter - but that doesn''t stop Harry dreaming that he will win the competition. Then at Hallowe''en, when the Goblet of Fire makes its selection, Harry is amazed to find his name is one of those that the magical cup picks out. He will face death-defying tasks, dragons and Dark wizards, but with the help of his best friends, Ron and Hermione, he might just make it through - alive!', '08.07.2000', 'Bloomsbury', ARRAY['Englisch']::text[], 638, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Hogwarts', '{}', ARRAY['Harry Potter']::text[], '{}', '{}', '73c84852-b198-531f-a74d-3ebbb12e089f', '4', '{}', 'sheet', :'owner') on conflict do nothing;
