insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8011a7d2-8044-54f5-9bc2-44d4bce7da45', 'Harry Potter and the Order of the Phoenix', NULL, NULL, 'Dark times have come to Hogwarts. After the Dementors'' attack on his cousin Dudley, Harry Potter knows that Voldemort will stop at nothing to find him. There are many who deny the Dark Lord''s return, but Harry is not alone: a secret order gathers at Grimmauld Place to fight against the Dark forces. Harry must allow Professor Snape to teach him how to protect himself from Voldemort''s savage assaults on his mind. But they are growing stronger by the day and Harry is running out of time...', '21.06.2003', 'Bloomsbury', ARRAY['Englisch']::text[], 816, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Hogwarts', '{}', ARRAY['Harry Potter']::text[], '{}', '{}', '73c84852-b198-531f-a74d-3ebbb12e089f', '5', '{}', 'sheet', :'owner') on conflict do nothing;
