insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('edb01b57-f1ed-5f61-96bc-247ecef1779f', 'Harry Potter and the Half-Blood Prince', NULL, NULL, 'When Dumbledore arrives at Privet Drive one summer night to collect Harry Potter, his wand hand is blackened and shrivelled, but he does not reveal why. Secrets and suspicion are spreading through the wizarding world, and Hogwarts itself is not safe. Harry is convinced that Malfoy bears the Dark Mark: there is a Death Eater amongst them. Harry will need powerful magic and true friends as he explores Voldemort''s darkest secrets, and Dumbledore prepares him to face his destiny...', '16.07.2005', 'Bloomsbury', ARRAY['Englisch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Hogwarts', '{}', ARRAY['Harry Potter']::text[], '{}', '{}', '73c84852-b198-531f-a74d-3ebbb12e089f', '6', '{}', 'sheet', :'owner') on conflict do nothing;
