insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d42fa365-80c6-5c46-a1e0-a95fc96c6529', 'Harry Potter and the Deathly Hallows', NULL, NULL, 'As he climbs into the sidecar of Hagrid''s motorbike and takes to the skies, leaving Privet Drive for the last time, Harry Potter knows that Lord Voldemort and the Death Eaters are not far behind. The protective charm that has kept Harry safe until now is broken, but he cannot keep hiding. The Dark Lord is breathing fear into everything Harry loves and to stop him Harry will have to find and destroy the remaining Horcruxes. The final battle must begin - Harry must stand and face his enemy...', '21.07.2007', 'Bloomsbury', ARRAY['Englisch']::text[], 640, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Hogwarts', '{}', ARRAY['Harry Potter']::text[], '{}', '{}', '73c84852-b198-531f-a74d-3ebbb12e089f', '7', '{}', 'sheet', :'owner') on conflict do nothing;
