insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f892df5e-a3ee-59a5-9d15-1f459f987b8a', 'Die Auslese - Nur die Besten überleben', 'The Testing', '9783764531171', 'Sie wurden auserwählt, um zu führen - oder zu sterben. Nach den verheerenden Fehlern der Vergangenheit war sich die Gesellschaft einig, dass nur noch die Besten politische Macht ausüben dürfen. Von nun an sollten die Psychologen darüber urteilen, in wessen Händen die Zukunft des Landes liegen sollte. So entstand die Auslese. Cia ist sechzehn und damit eine der Jüngsten, die zu den Prüfungen antreten, die darüber entscheiden, ob man für ein Amt geeignet ist. Zunächst ist sie von Stolz erfüllt – bis die erste Kandidatin stirbt! Jetzt breitet sich Angst aus, und Cia erkennt: Nur die Besten überleben …', '26.08.2013', 'blanvalet', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], NULL, NULL, NULL, '{}', ARRAY['Cia Vale']::text[], '{}', '{}', '345fde31-60a0-5277-9218-df7b33c4e997', '1', '{}', 'sheet', :'owner') on conflict do nothing;
