insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d9659265-d767-5d0c-b377-05dd63546081', 'Die Auslese - Nichts vergessen und nie vergeben', 'Independent Study', '9783764531188', 'Cia Vale ist gemeinsam mit ihrem Freund Tomas an der Akademie von Tosu City aufgenommen worden. Und obwohl die Regierung ihnen ein Medikament verabreicht hat, das alle Erinnerungen an das brutale Auswahlverfahren der »Auslese« löschen soll, hat Cia nichts vergessen – weder die schrecklichen Todesfälle noch ihre Liebe zu Tomas. Ab sofort kennt sie nur noch ein Ziel: die »Auslese« zu beenden, indem sie dafür sorgt, dass die ganze Welt die grausame Wahrheit erfährt. Doch damit bringt Cia nicht nur sich selbst, sondern auch alle, die sie liebt, in größte Gefahr ...', '21.01.2015', 'blanvalet', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], NULL, NULL, NULL, '{}', ARRAY['Cia Vale']::text[], '{}', '{}', '345fde31-60a0-5277-9218-df7b33c4e997', '2', '{}', 'sheet', :'owner') on conflict do nothing;
