insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba44e6ab-95c9-5d2a-bf4a-bc5c876ee1a7', 'Das Schicksal ist ein mieser Verräter', 'The fault in our stars', '9783423625838', '„Krebsbücher sind doof“, sagt die 16-jährige Hazel, die selbst Krebs hat. Sie will auf gar keinen Fall bemitleidet werden und kann mit Selbsthilfegruppen nichts anfangen. Bis sie in einer Gruppe auf den intelligenten, gut aussehenden und umwerfend schlagfertigen Gus trifft. Der geht offensiv mit seiner Krankheit um. Hazel und Gus diskutieren Bücher, hören Musik, sehen Filme und verlieben sich ineinander - trotz ihrer Handicaps und Unerfahrenheit. Gus macht Hazels großen Traum wahr: Gemeinsam fliegen sie nach Amsterdam, um dort Peter Van Houten zu treffen, den Autor von Hazels absolutem Lieblingsbuch. Ein tiefgründiges, emotionales und zugleich freches Jugendbuch über Krankheit, Liebe und Tod.', '01.05.2014', 'dtv', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hazel','Gus']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
