insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9f14bdd0-a5dc-5f4c-966c-cc1492076ada', 'Eine wie Alaska', 'Looking for Alaska', '9783423624039', 'Miles ist 16. Viel ist nicht gerade los bei ihm. Keine Liebe, keine Kumpels - ein stinknormales Leben. Bis er Alaska trifft. Miles verknallt sich in das schöne Mädchen und gerät in eine Achterbahn der Gefühle: Alaska - Göttin und Rätsel, euphorisch und voller verrückter Ideen, aber auch unberechenbar und verletzlich. Was verbirgt sich hinter ihrer coolen Fassade? Und was hat der lang ersehnte Kuss zu bedeuten? Alles hätte so schön werden können, wäre Alaska nicht betrunken Auto gefahren … John Greens vielfach ausgezeichnetes Jugendbuch über das Erwachsenwerden und die erste Liebe.', '01.06.2009', 'dtv', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Miles']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
