insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b9636d83-66d1-56a7-88c6-d8568e192491', 'Kill Your Friends', NULL, '9781407010953', 'Meet Steven Stelfox. London 1997: New Labour is sweeping into power and Britpop is at its zenith. A&R man Stelfox is slashing and burning his way through the music industry, fuelled by greed and inhuman quantities of cocaine, searching for the next hit record amid a relentless orgy of self-gratification. But as the hits dry up and the industry begins to change, Stelfox must take the notion of cut throat business practices to murderous new levels in a desperate attempt to salvage his career.', '16.12.2008', 'Cornerstone Digital', ARRAY['Englisch']::text[], 337, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Krimi', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'London', '{}', ARRAY['Steven Stelfox']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
