insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('595d4b4e-999f-546c-a119-467d391db811', 'Safari des Lebens', 'Life Safari', NULL, 'Der junge Amerikaner Jack hat einen Traum. Einen Traum von Afrika. Dort, das weiß er genau, wird er sein Glück finden. Also macht er sich auf eine abenteuerliche Reise. Er begegnet der alten weisen Frau Ma Ma Gombe, die den sagenumwobenen »Geburtsort von allem« finden möchte, von dem ihr einst ihr Großvater erzählt hat. Ma Ma Gombe wird Jacks Führerin, sie vermittelt ihm viele Lebenslehren, die seine Sicht der Welt für immer verändern. So begreift er, dass jeder seine eigenen fünf großen Ziele erkennen und verwirklichen muss, wenn er ein erfülltes und glückliches Leben führen will. Am Ende ihres langen Wegs weiß Jack, dass er die Verwirklichung seiner Lebensträume nie mehr aus den Augen verlieren wird.', '23.12.2023', 'dtv', ARRAY['Deutsch']::text[], 161, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, NULL, 'Afrika', '{}', ARRAY['Jack']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
