insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4c5f6f99-950f-5505-8904-305ae2aa053a', 'The Big Five for Life - Was wirklich zählt im Leben', 'The Big Five for Life', NULL, 'Durch Zufall lernt Joe, ein unzufriedener Angestellter, den charismatischen Geschäftsmann Thomas kennen. Dieser wird zu Joes Mentor und offenbart ihm die Geheimnisse seines Erfolgs. Seine Unternehmen führt Thomas anhand zweier Leitlinien: Jeder Mitarbeiter muss seine Bestimmung sowie seine »Big Five for Life« kennen, also wissen, welche fünf Ziele er im Leben erreichen will. Diese Ideen helfen Joe, seine Wünsche zu verwirklichen. Doch Thomas will möglichst viele an seinem Wissen teilhaben lassen: Seine gesammelten Aufzeichnungen liegen hier vor Ihnen.', '14.08.2012', NULL, ARRAY['Deutsch']::text[], 239, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Joel']::text[], '{}', '{}', '6f2d981c-b482-54ac-b307-898015e52f9c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
