insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d8cb1640-64b1-52c4-b4ce-256060c6e3a4', 'Ein ganzes halbes Jahr', 'Me Before You', '9783644902312', 'Louisa Clark weiß, dass nicht viele in ihrer Heimatstadt ihren etwas schrägen Modegeschmack teilen. Sie weiß, dass sie gerne in dem kleinen Café arbeitet und dass sie ihren Freund Patrick eigentlich nicht liebt. Sie weiß nicht, dass sie schon bald ihren Job verlieren wird – und wie tief das Loch ist, in das sie dann fällt. Will Traynor weiß, dass es nie wieder so sein wird wie vor dem Unfall. Und er weiß, dass er dieses neue Leben nicht führen will. Er weiß nicht, dass er schon bald Lou begegnen wird.', '21.03.2013', 'Rowohlt', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Louisa Clark','Will Traynor']::text[], '{}', '{}', '282e9a15-11f5-58e6-8695-511868a01c26', '1', '{}', 'sheet', :'owner') on conflict do nothing;
