insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cbe2bf38-2b43-5e30-8ef6-9a4bec847a50', 'Ein ganz neues Leben', 'After You', '9783644549012', 'Sechs Monate hatten Louisa Clark und Will Traynor zusammen. Ein ganzes halbes Jahr. Und diese sechs Monate haben beide verändert. Lou ist nicht mehr das Mädchen aus der Kleinstadt, das Angst vor seinen eigenen Träumen hat. Aber sie führt auch nicht das unerschrockene Leben, das Will sich für sie gewünscht hat. Denn wie lebt man weiter, wenn man den Menschen verliert, den man am meisten liebt? Eine Welt ohne Will, das ist für Lou immer noch schwer zu ertragen. Ein einsames Apartment, ein trister Job am Flughafen – Lou existiert, aber ein Leben ist das nicht. Bis es eines Tages an der Tür klingelt – und sich eine Verbindung zu Will auftut, von der niemand geahnt hat. Endlich schöpft Lou wieder Hoffnung. Hoffnung auf ein ganz neues Leben', '24.09.2015', 'Rowohlt', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Louisa Clark']::text[], '{}', '{}', '282e9a15-11f5-58e6-8695-511868a01c26', '2', '{}', 'sheet', :'owner') on conflict do nothing;
