insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5a6f3f6e-4522-5df9-8b23-87da5fd2c705', 'Ein Bild von dir', 'The Girl You Left Behind', '9783644498112', 'Während um sie herum der Erste Weltkrieg tobt, versucht Sophie, stark zu sein – für ihre Familie, für ihren Mann Édouard, der aufseiten Frankreichs kämpft. Nur ein Gemälde ist ihr geblieben, das sie an ihr gemeinsames Glück erinnert. Ein Porträt, das Édouard einst von ihr malte. Und das ihn jetzt retten soll … Hundert Jahre später. Liv trauert um ihren Mann David. Vor vier Jahren ist er gestorben, viel zu früh. Livs kostbarster Besitz: ein Gemälde, das er ihr einst schenkte. Der Maler: Édouard. Das Modell: Sophie. Als ihr dieses Gemälde genommen werden soll, ist sie bereit, alles zu opfern. Auch das eigene Glück …', '23.01.2015', 'Rowohlt', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Historischer Liebesroman']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Sophie','Liv']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
