insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('78c94aef-364d-5d0e-b142-9e7b9648d467', 'Auf diese Art zusammen', 'Lockdown With Lou', '9783644009660', 'Louisa Clark sitzt fest. Eigentlich wollte sie nur kurz zurück nach England, um neue Ware für ihren Vintage-Mode-Verleih The Bees Knees zu kaufen. Aber plötzlich ist alles anders. Lockdown. Die Welt steht still. Lou hat keine andere Wahl, als die nächsten Wochen bei ihrer liebenswert chaotischen Familie zu verbringen. Dabei macht sie sich große Sorge um ihren Freund Sam, der als Sanitäter in New York arbeitet. Wie so viele andere Mediziner und Pflegekräfte überall auf der Welt bringt er sich täglich in Gefahr, um anderen zu helfen. Doch Lou wäre nicht Lou, wenn sie nicht selbst aus dieser Situation etwas Gutes machen würde ...', '20.06.2020', 'Rowohlt', ARRAY['Deutsch']::text[], 42, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Louisa Clark']::text[], '{}', '{}', '282e9a15-11f5-58e6-8695-511868a01c26', '4', ARRAY['Novella']::text[], 'sheet', :'owner') on conflict do nothing;
