insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('922a0b2a-f2ce-5e01-984a-0b96ff119969', 'Weit weg und ganz nah', 'The One Plus One', '9783499267369', 'Einmal angenommen, dein Mann hat sich aus dem Staub gemacht. Du schaffst es kaum, deine Familie über Wasser zu halten. Deine hochbegabte Tochter bekommt eine einmalige Chance. Und du bist zu arm, um ihren Traum Wirklichkeit werden zu lassen. Plötzlich liegt da ein Bündel Geldscheine. Du weißt, dass es falsch ist. Aber auf einen Schlag wäre dein Leben so viel einfacher … Und einmal angenommen, du strandest mitten in der Nacht mit deinen Kindern am Straßenrand – und genau der Mann, dem das Geld gehört, bietet an, euch mitzunehmen. Würdest du einsteigen? Würdest du ihm irgendwann während eures verrückten Roadtrips gestehen, was du getan hast? Und kann das gut gehen, wenn du dich ausgerechnet in diesen Mann verliebst?', '23.05.2014', 'Rowohlt', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Jess']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
