insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fe7a310c-b59e-59d0-b48a-6f02f843e1a9', 'Mein Herz in zwei Welten', 'Still Me', '9783499272349', 'Die glamouröse Welt ihrer Arbeitgeber könnte von Lous altem Leben in der englischen Kleinstadt nicht weiter entfernt sein. Dort ist ein Teil ihres Herzens zurückgeblieben: bei ihrer liebenswert chaotischen Familie und vor allem bei Sam, dem Mann, der sie auffing, als sie fiel. Während Lou versucht, New York zu erobern und herauszufinden, wer Louisa Clark wirklich ist, muss sie feststellen, wie groß die Gefahr ist, sich selbst und andere auf dem Weg zu verlieren. Und am Ende muss sie sich die Frage stellen: Ist es möglich, ein Herz zu heilen, das in zwei Welten zuhause ist?', '17.05.2019', 'Rowohlt', ARRAY['Deutsch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, NULL, 'New York', '{}', ARRAY['Louisa Clark']::text[], '{}', '{}', '282e9a15-11f5-58e6-8695-511868a01c26', '3', '{}', 'sheet', :'owner') on conflict do nothing;
