insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('20c84a2e-841a-5cfb-8322-3fb5dda541a1', 'Our Korean Kitchen', NULL, '9780297609711', 'OUR KOREAN KITCHEN is a celebration of the food, culture and flavours of Korea, a cuisine that is fast becoming the biggest trend in the culinary world. Capturing this movement, it introduces us to Korean food through a collection of classic and well-loved dishes. Beautifully illustrated throughout, the book will explore the secrets of authentic Korean food. Covering an extensive range of over 100 dishes, from Korean staples such as bibimbap and kimchi to stir-fried spicy squid, sesame & soy-marinated beef and pecan & cinnamon-stuffed pancakes, catering for beginners as well as those with a little more experience of cooking K-Food.', '03.09.2015', 'Orion', ARRAY['Englisch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kochen & Ernährung', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
