insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6ad80065-b9c4-503f-8078-e9ee6a217684', 'Bitten', NULL, '9783736324213', 'Als Vanessa Hart von einem Wolfsrudel angegriffen wird, ist ihr Leben nicht mehr dasselbe: ihre beste Freundin überlebt den Angriff nicht, und Vanessa wird schwer verletzt an den magischen Hof der Werwölfe gebracht. Doch statt ihren Verletzungen zu erliegen, geschieht das Unglaubliche: Sie verwandelt sich in eine Alpha-Wölfin! An der Werwolf-Academy soll sie sich mit ihren neu gewonnenen Kräften vertraut machen, doch trotz der charmanten Art ihres Mentors und Beschützers Prinz Sinclair fällt es ihr schwer, sich auf Mating-Rituale, Blutmagie und die Bedeutung der Mondphasen zu konzentrieren. Sie will Sins Vertrauen nur aus einem einzigen Grund: den Mörder ihrer Freundin finden und sich rächen ...', '30.09.2025', 'LYX', ARRAY['Deutsch']::text[], 585, 46, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Castle Severi', ARRAY['Single POV','1P']::text[], ARRAY['Vanessa Hart']::text[], ARRAY['Omegaverse','Universicy/College','Academy','Forced Proximity']::text[], ARRAY['Tod','Gore']::text[], '681f7d77-4c98-53e1-82ec-f7c633666e4e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('b0c18c41-c7eb-55d6-a7fb-c41598eba69a', :'owner', '6ad80065-b9c4-503f-8078-e9ee6a217684', 'abgebrochen'::reading_status, true, false, ARRAY['Digital','Print','Audiobook']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', ARRAY['In-Book Illustrationen']::text[], 1499, false, false, ARRAY['Audible']::text[], ARRAY['Ann-Kathri Hinz','Demet Fey']::text[], 1024, '👌🏻', false, 'solo'::company_kind, 'hate'::verdict_kind, 0.5, 'untertroffen'::expectation_kind, NULL, 'slow'::burn_kind, 'Dieses Buch war wirklich furchtbar schlecht. Es hat schon damit angefangen, dass die FMC erst 16 ist und sich benimmt wie die unreifste 16 jährige auf diesem Planeten. Alles geht viel zu schnell und ist viel zu dramatisch beschrieben. Mit dem "Mean Girl Drama" da einfach vollkommen unnötig ist, fange ich gar nicht erst an. Schlecht geschrieben.') on conflict do nothing;
