insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('763e9935-1650-5d87-aa59-419a4c6b4316', 'Taylor Swift. 100 Seiten.', NULL, '9783159622293', 'Wenn es um die 1989 in West Reading, Pennsylvania, geborene Taylor Swift geht, ticken die Uhren anders. Kein Wunder. Schließlich ist Swift die bedeutendste Songwriterin ihrer Generation und zugleich der größte Popstar unserer Zeit. Ihr Ruhm, ihre Kunst und die Begeisterung, die sie mit ihrer Musik entfacht – all dies spielt sich in bislang unbekannten Größenordnungen ab. Jörn Glasenapp, bekennender Swiftie, führt mit Verve durch das bunt glitzernde Taylorverse.', '16.02.2024', 'Reclam', ARRAY['Deutsch']::text[], 100, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Biografie & Autobiografie', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Taylor Swift']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
