insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bc00033b-30fb-5473-9bd6-65b8161e74d4', 'Göttlich verdammt', 'Starcrossed', '9783791526256', 'Die 16-jährige Helen lebt bei ihrem Vater auf Nantucket – und langweilt sich. Ihre beste Freundin Claire hofft, dass nach den Ferien endlich etwas Aufregendes passiert. Der Wunsch geht in Erfüllung, als die Familie Delos auf die Insel zieht. Alle sind hin und weg von den äußerst attraktiven Neuankömmlingen. Nur Helen spürt von Anfang an großes Misstrauen. Gleichzeitig plagen sie plötzlich düstere Albträume, in denen drei unheimliche Frauen Rache nehmen wollen. Es scheint eine Verbindung zwischen ihnen und Lucas Delos zu geben. Was dahintersteckt, erfährt Helen erst nach und nach: Lucas und sie stammen von Halbgöttern ab und sind dazu verdammt, einen erbitterten Kampf auszulösen – indem sie sich ineinander verlieben …', '01.05.2011', 'Oetinger', ARRAY['Deutsch']::text[], 494, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nantucket', '{}', ARRAY['Helen']::text[], '{}', '{}', '28279254-9b3a-5272-8fb9-9d3aa80135ea', '1', '{}', 'sheet', :'owner') on conflict do nothing;
