insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('71cb5519-4e00-565a-8f7c-b6031de1ec46', 'Göttlich verloren', 'Dreamless', '9783791526263', 'In der Unterwelt ist die Zeit für immer Helen muss die Hölle gleich zweifach durchstehen: Nachts schlägt sie sich durch die Unterwelt, noch schlimmer quält sie tags, dass Lucas und sie sich unmöglich lieben dürfen. In der Unterwelt trifft Helen auf Orion. Je mehr Zeit die beiden miteinander verbringen, umso näher kommen sie sich. Dann geschieht etwas völlig Unerwartetes, das ausgerechnet Orion und Lucas zum Zusammenhalten zwingt: Die vier Häuser Scion werden vereint und ein neuer Trojanischer Krieg scheint unausweichlich!', '01.05.2012', 'Oetinger', ARRAY['Deutsch']::text[], 511, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nantucket', '{}', ARRAY['Helen']::text[], '{}', '{}', '28279254-9b3a-5272-8fb9-9d3aa80135ea', '2', '{}', 'sheet', :'owner') on conflict do nothing;
