insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4d5cf64b-e36f-5d4a-bd20-d9a8ada0ee90', 'Göttlich verliebt', 'Goddess', '9783791526270', 'Ein zweiter Trojanischer Krieg steht unmittelbar bevor. Weil die Scions sich gegenseitig bekämpfen, liegt es allein an Helen, Lucas und Orion, neue Verbündete für ihr bislang größtes Gefecht zu finden. Zugleich wächst Helens Macht und mit ihr das Misstrauen ihrer Freunde. Doch Helen kann deren Vertrauen zurückgewinnen und den unsterblichen Zeus in letzter Minute bezwingen. Aber was wird aus Helens ganz persönlichem Kampf um ihre Liebe zu Lucas? Um zu verhindern, dass die sterbliche Welt in die Hände der 12 unsterblichen Götter fällt, brauchen Helen, Lucas und Orion neue Verbündete. Zugleich wächst Helens Macht und mit ihr das Misstrauen ihrer Freunde. Wie kann Helen deren Vertrauen zurückgewinnen? Womit lassen sich die Götter besiegen? Und was wird aus ihrem Kampf um die Liebe zu Lucas?', '01.03.2013', 'Oetinger', ARRAY['Deutsch']::text[], 459, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nantucket', '{}', ARRAY['Helen']::text[], '{}', '{}', '28279254-9b3a-5272-8fb9-9d3aa80135ea', '3', '{}', 'sheet', :'owner') on conflict do nothing;
