insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b1da37ec-2d88-5bb1-b9f7-3d1b3b62df21', 'Incidents Around the House', NULL, '9780593723135', 'To eight-year-old Bela, her family is her world. There''s Mommy, Daddo, and Grandma Ruth. But there is also Other Mommy, a malevolent entity who asks her every day: "Can I go inside your heart?" When horrifying incidents around the house signal that Other Mommy is growing tired of asking Bela the question over and over, Bela understands that unless she says yes, her family will soon pay. Other Mommy is getting restless, stronger, bolder. Only the bonds of family can keep Bela safe, but other incidents show cracks in her parents'' marriage. The safety Bela relies on is about to unravel. But Other Mommy needs an answer.', '25.06.2024', 'Random House', ARRAY['Englisch']::text[], 371, 51, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Bella']::text[], ARRAY['Haunted House']::text[], ARRAY['Tod von Familienangehörigen','Tod','Body Horror']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
