insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fc8403f2-e171-593c-96db-d279248ec0d8', 'Heads Will Roll', NULL, '9781405968881', 'Cancelled after a drunken, ill-advised post, TV-star Willow McKenzie is sent to Camp Castaway - a retreat in the woods where you hide from your mistakes. Spoiler #1: there''s nowhere to hide. That first night, fellow campers gather round a fire, telling ghost stories. And Willow hears the tale of Knock-Knock Nancy - a beheaded local woman whose spirit still roams the woods. Spoiler #2: she takes her victim''s heads. Willow doesn''t believe in ghosts - until next day, a camper vanishes. And, that evening, Willow hears it: Knock. Knock. Knock. Spoiler #3: It''s already too late . . .', '07.08.2025', 'Penguin Books Ltd', ARRAY['Englisch']::text[], 351, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Camp Castaway', ARRAY['Single POV','1P']::text[], ARRAY['Willow McKenzie']::text[], ARRAY['Slasher']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
