insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('155f766c-023e-5d05-8e18-e853e85600ed', 'Als Hitler das rosa Kaninchen stahl', NULL, '9783473580033', 'Berlin, 1933: Die Nazis stehen kurz vor ihrem entscheidenden Wahlsieg. In letzter Minute reist die neunjährige Jüdin Anna mit ihrer Familie in die Schweiz. Doch vieles von dem, was zu ihrem Alltag gehörte, muss in Berlin bleiben – auch Annas rosa Stoffkaninchen. Und so beginnt für die Familie ein Leben auf der Flucht …', '01.02.1997', 'Ravensburger', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', '{}', 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Berlin', '{}', ARRAY['Anna']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
