insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6977187e-91c6-5b99-9d10-fe3fd6b386b3', 'Golden Throne', 'Torrid Throne', '9783736313651', 'Noch vor zwei Monaten war Emilia Lancaster eine ganz normale junge Frau mit ganz normalen Problemen. Nun ist sie die Kronprinzessin von Caerleon und muss sich Herausforderungen stellen, auf die sie kaum vorbereitet wurde. Neben ihren neuen Verpflichtungen und der öffentlichen Aufmerksamkeit machen ihr vor allem die Intrigen und Machtspielchen im Königshaus zu schaffen. Eine Situation, die nicht einfacher wird, als plötzlich eine ganze Handvoll Verehrer darum kämpft, ihr Interesse zu gewinnen. Und außerdem ist da ja noch Carter Thorne, ihr Stiefbruder, der einzige Mann, für den sie nichts empfinden darf - und dessen Anwesenheit im Palast sie trotzdem überall spüren kann ...', '27.11.2020', 'LYX', ARRAY['Deutsch']::text[], 295, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Caerleon', '{}', ARRAY['Emilia Lancaster','Carter Thorne']::text[], ARRAY['Forbidden Love','Step Brother','Multiple Love Interests','Royalty','Strong FMC']::text[], '{}', '122f6bc9-1030-5893-9c77-7e45a8f4bfee', '2', '{}', 'sheet', :'owner') on conflict do nothing;
