insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('23ad2d47-f9e7-56d8-804d-de5493c25c9d', 'Diamond Empire', 'Sordid Empire', '9783736313668', 'Durch ein tragisches Ereignis findet sich Emilia Lancaster viel zu früh in der Rolle wieder, in der sie sich selbst nie gesehen hat - als Königin von Caerleon. Doch auch wenn ihr eigenes Herz durch den Verlust ihres Vaters und den Verrat ihrer engsten Verbündeten in tausend Scherben liegt, muss sie ihre Pflichten erfüllen und nach außen hin Stärke zeigen. Denn Emilia steht vor ihrer größten Herausforderung: Sie muss für ihr trauerndes Volk da sein, ihren intriganten Feinden die Stirn bieten und vor allem versuchen, den Mann zu vergessen, der ihr einst mehr bedeutete als alle Kronjuwelen des Königreichs - Carter Thorne.', '26.02.2021', 'LYX', ARRAY['Deutsch']::text[], 477, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Caerleon', '{}', ARRAY['Emilia Lancaster','Carter Thorne']::text[], ARRAY['Forbidden Love','Step Brother','Multiple Love Interests','Royalty','Strong FMC']::text[], '{}', '122f6bc9-1030-5893-9c77-7e45a8f4bfee', '3', '{}', 'sheet', :'owner') on conflict do nothing;
