insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8d23fe27-026a-5b7c-afb8-c4a4918bc819', 'Silver Crown', 'Dirty Halo', '9783736313033', 'Emilia Lancaster führt ein vollkommen normales Leben. Doch als ein Schicksalsschlag die Thronfolge des Landes ändert und ihr Vater zum König gekrönt werden soll, findet sich Emilia als seine illegitime Tochter plötzlich in der Rolle der Kronprinzessin wieder. Ihr neues Leben im Palast könnte der Anfang eines Märchens sein. Aber Emilia merkt schnell, dass sie von Intrigen und Machtspielen umgeben ist - und von Menschen, die alles andere als begeistert von ihrem unerwartetem Aufstieg sind. Ganz besonders Carter Thorne, der Sohn ihrer Stiefmutter, scheint ihre bloße Anwesenheit als Provokation zu empfinden. Anders kann sich Emilia seine düsteren Blicke nicht erklären, die trotz allem ihr Herz höher schlagen lassen...', '28.08.2020', 'LYX', ARRAY['Deutsch']::text[], 295, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Caerleon', '{}', ARRAY['Emilia Lancaster','Carter Thorne']::text[], ARRAY['Forbidden Love','Step Brother','Multiple Love Interests','Royalty','Strong FMC']::text[], '{}', '122f6bc9-1030-5893-9c77-7e45a8f4bfee', '1', '{}', 'sheet', :'owner') on conflict do nothing;
