insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('94e2743f-9637-5ecb-b3ea-b9ca71acf84e', 'Talon - Drachenzeit', 'Talon', '9783641165680', 'Strand, Meer, Partys – einen herrlichen Sommer lang darf Ember Hill das Leben eines ganz gewöhnlichen kalifornischen Mädchens leben! Danach muss sie in die strenge Welt des Talon-Ordens zurückkehren – und kämpfen. Denn Ember verbirgt ein unglaubliches Geheimnis: Sie ist ein Drache in Menschengestalt, auserwählt, um gegen die Todfeinde der Drachen, die Krieger des Geheimordens St. Georg, zu kämpfen. Garret ist einer jener Krieger, und er hat Ember sofort als Gefahr erkannt. Doch je näher er ihr kommt, umso mehr entflammt er für das ebenso schöne wie mutige Mädchen. Und plötzlich stellt er alles, was er je über Drachen gelernt hat, infrage …', '05.10.2015', 'Heyne', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ember Hill','Garret']::text[], '{}', '{}', 'bc3c8372-f393-526f-836c-5916d17ebb7d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
