insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('31e3b3ba-456b-5ab4-a667-66b41e959659', 'Unsterblich - Tor der Dämmerung', 'The Immortal Rules', '9783641100148', 'Unsere Welt ist in Dunkelheit getaucht. Die Menschen sind zu Gefangenen geworden. Nur wer sich an die Regeln hält, hat eine Chance zu überleben. Doch die junge Allison will sich nicht mehr an diese Regeln halten. Sie fordert das Schicksal heraus und lehnt sich gegen ihre Unterdrücker auf – mit ungeahnten Folgen. Grenzen, Mauern und Verbote gehören zum Alltag der 17-jährigen Allison, seit sie denken kann. Denn sie wächst in einer Stadt auf, in der die Menschen von den Vampiren regiert werden, grausamen Fürsten der Nacht. Sie haben sich eine Luxuscity errichtet und lassen ihre Gefangenen, die ihnen regelmäßig Blutzoll schulden, für sich schuften. Jeder kleinste Verstoß gegen die Regeln wird geahndet, und Allison erfährt schon früh, dass ihr Leben nicht viel wert ist. Als sie vor die Wahl gestellt wird, zu sterben oder ihren Unterdrückern gleich zu werden, entscheidet sie sich für den Weg der Unsterblichkeit – und hofft, nun endlich unangreifbar zu sein. Doch vor den Toren der festungsartig abgeriegelten Stadt lauert etwas, vor dem sich sogar die Vampire fürchten …', '10.06.2013', 'Heyne', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Allison']::text[], '{}', '{}', 'f9fad259-0d7c-51e4-8bce-74bce402045d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
