insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('74db8e8d-3d09-5189-be8f-b2b920d7a8c8', 'Plötzlich Fee - Winternacht', 'The Iron Daughter', '9783641066154', 'So richtig hat Meghan noch nie irgendwo dazugehört: Halb Mensch, halb Feenprinzessin steht sie immer zwischen den Welten. Während sich im Feenland Nimmernie ein Krieg zwischen Oberons Sommerhof und dem Reich der Winterkönigin Mab anbahnt, spitzt sich Meghans Lage zu: Als Gefangene des Winterreichs in all seinem eiskalten, trügerischen Glanz sieht sie das Unheil in seinem ganzen Ausmaß heraufziehen, kann aber nichts unternehmen. Ihre magischen Fähigkeiten scheinen mit jedem Tag zu schwinden, und niemand glaubt ihr, dass die gefährlichen Eisernen Feen, Geschöpfe von unglaublicher Macht, längst darauf lauern, Nimmernie zu unterjochen. Denn keiner hat die dunklen Feen, die selbst Mabs Grausamkeit in den Schatten stellen, je gesehen. Nur Meghan – und Ash, der Winterprinz, dem Meghan ihr Herz schenkte und der sie verlassen hat …', '03.10.2011', 'Heyne', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nimmernie', '{}', ARRAY['Meghan Chase']::text[], '{}', '{}', '7ed6cec4-0944-5fbc-a3a9-9575aaa15e48', '2', '{}', 'sheet', :'owner') on conflict do nothing;
