insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('981d8013-9044-599d-bc14-a3bcf959eea9', 'Talon - Drachenherz', 'Rogue', '9783641171865', 'Seit sich das Drachenmädchen Ember und der St.-Georgs-Ritter Garret das erste Mal gesehen haben, ist ihr Leben aus den Fugen geraten. Sie sind dazu bestimmt, einander bis zum Tode zu bekämpfen, doch sie kommen nicht gegen die starken Gefühle füreinander an. Als Garret Ember in der Stunde der Entscheidung rettet, wird er als Verräter eingekerkert. Ember fasst den halsbrecherischen Entschluss, ihn mitten aus dem Hauptquartier der Georgsritter zu befreien. Das kann ihr aber nur mithilfe des abtrünnigen Drachen Cobalt gelingen. Doch wird der sein Leben aufs Spiel setzen, um seinen Erzfeind – und Rivalen um Embers Herz! – zu retten? Und falls der Plan gelingt: Welche Chance hätten die drei ungleichen Gefährten, wenn der Talonorden und die Georgsritter sie jagen?', '11.01.2016', 'Heyne', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ember Hill','Garret']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
