insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1655d24a-01af-5c42-bd8a-fb74af5206de', 'Plötzlich Prinz - Das Schicksal der Feen', 'The Iron Traitor', '9783641128692', 'Einfach so wie die anderen sein – das hat sich der siebzehnjährige Ethan Chase immer gewünscht. Ein Ding der Unmöglichkeit mit einer älteren Schwester, die eine der mächtigsten Herrscherinnen im Feenreich Nimmernie ist. Immer wieder kreuzen sich Ethans Wege mit denen der Feen. Als Ethans Neffe Keirran spurlos verschwindet, hat Ethan eine böse Vorahnung, die sich schon bald bewahrheitet: Keirran, der sich ausgerechnet in eine Fee des Sommerhofs verliebt hat, erregt den Zorn einer uralten Kreatur, die selbst die Feen fürchten. Ethan bleibt nichts anderes übrig, als nach Nimmernie zu reisen, um Keirran zu retten. Begleitet wird er von Kenzie, dem Mädchen, das er mehr liebt, als er je zugeben würde. Ein Abenteuer mit unbekanntem Ausgang erwartet sie …', '10.11.2014', 'Heyne', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, 'Nimmernie', '{}', ARRAY['Ethan Chase']::text[], '{}', '{}', 'd382c83a-f7a6-5505-930c-ade07f1bfa86', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
