insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a184820c-aa8e-5744-816b-529a1cef841d', 'Plötzlich Fee - Herbstnacht', 'The Iron Queen', '9783641070533', 'Am Vorabend ihres siebzehnten Geburtstags findet sich Meghan als Wanderin zwischen den Welten wieder: Sie und Ash, der Winterprinz, wurden wegen ihrer verbotenen Liebe aus Nimmernie verbannt. Nun sind sie auf der Flucht. Denn die Eisernen Feen, denen Meghan im letzten großen Kampf empfindlichen Schaden zufügte, sinnen auf Rache und machen auch vor der Welt der Sterblichen nicht halt. Für Meghan gibt es keinen sicheren Ort mehr.', '23.01.2012', 'Heyne', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nimmernie', '{}', ARRAY['Meghan Chase']::text[], '{}', '{}', '7ed6cec4-0944-5fbc-a3a9-9575aaa15e48', '3', '{}', 'sheet', :'owner') on conflict do nothing;
