insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38d496a4-c4e5-52e1-8277-3238ddfcb20a', 'Plötzlich Fee - Frühlingsnacht', 'The Iron Knight', '9783641085476', 'Ash, der Winterprinz, hat für seine Liebe zu Meghan bereits alles riskiert. Seine eigene Mutter, die eisige Königin Mab, stellte sich ihm in den Weg, aus Nimmernie wurde er verstoßen, und sein einstiger bester Freund Puck wurde zu seinem Rivalen. Eigentlich müssten nun endlich bessere Zeiten anbrechen, denn die Eisernen Feen sind geschlagen und Meghan wurde zur rechtmäßigen Königin ihres Reiches gekrönt – eines Reiches, in dem Ash nur dann überleben kann, wenn er das Einzige, das ihm von Mabs Erbe noch geblieben ist, preisgibt: seine Unsterblichkeit. Und so steht für Meghan und Ash ein weiteres Mal alles auf dem Spiel, und in seiner dunkelsten Stunde muss der Winterprinz eine Entscheidung fällen, die ihm Meghan nicht abnehmen kann: ob ihre Liebe stark genug sein wird, die Schatten der Vergangenheit zu besiegen …', '20.08.2012', 'Heyne', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nimmernie', '{}', ARRAY['Meghan Chase']::text[], '{}', '{}', '7ed6cec4-0944-5fbc-a3a9-9575aaa15e48', '4', '{}', 'sheet', :'owner') on conflict do nothing;
