insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4bdceed9-6098-517e-a745-ae4b1d12fd03', 'Plötzlich Fee - Das Geheimnis von Nimmernie', 'Iron Legends: Winter''s Passage, Summer''s Crossing, Iron''s Prophecy', '9783641098490', 'Meghan Chase, die unerschrockene Feenprinzessin, und Ash, ihr geliebter Winterprinz, dachten eigentlich, dass sie als erprobte Grenzgänger zwischen Nimmernie und der Menschenwelt nichts mehr aus der Fassung bringen könnte. Doch dann muss Meghan schmerzvoll erfahren, dass es nie ratsam ist, einer Fee ein Versprechen zu geben – denn sie wird es nicht vergessen und unter den unmöglichsten Umständen auf seiner Einhaltung beharren. Aber auch auf den stolzen Ash wartet erneut eine Prüfung, die ihm alles abverlangt: In der Stunde der höchsten Not muss er über seinen Schatten springen und sich mit seinem Rivalen Puck verbünden. Wird es Meghan und Ash am Ende gelingen, einer Herausforderung zu trotzen, die alles infrage stellt, was ihnen jemals etwas bedeutete?', '28.11.2012', 'Heyne', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nimmernie', '{}', ARRAY['Meghan Chase']::text[], '{}', '{}', '7ed6cec4-0944-5fbc-a3a9-9575aaa15e48', '5', '{}', 'sheet', :'owner') on conflict do nothing;
