insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('58d37395-345e-5663-a4ed-d2c2f45da032', '3af1a339-0272-5805-a332-8ce50d46d99a', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eac15885-2516-5a1d-89fb-48a8612688c7', 'Shadow of the Fox', NULL, '9781335145161', 'Every millennium, whoever holds the Scroll of a Thousand Prayers has the power to call the great Kami Dragon from the sea and ask for one wish. The time is near...and the missing pieces of the scroll will be sought throughout the land of Iwagoto. When demons kill half-kitsune Yumeko’s adoptive family, she’s forced to flee her home with one part of the ancient scroll. Fate thrusts her into the path of mysterious samurai Kage Tatsumi, who is Yumeko’s best hope for survival. But he’s under orders to retrieve the scroll. An uneasy alliance forms, and Yumeko begins the deception of a lifetime, knowing her secrets are more than a matter of life or death—they’re the key to the fate of the world.', '02.10.2018', 'HHarlequin Teen', ARRAY['Englisch']::text[], 409, 35, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Yumeko']::text[], ARRAY['Asia Mythology']::text[], '{}', '72276e14-a977-52d6-a8f2-a9bb4405ef7b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('77a90b0b-0641-5383-8770-d595f967a59f', :'owner', 'eac15885-2516-5a1d-89fb-48a8612688c7', 'tbr'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Hardcover']::text[], 'Normal', ARRAY['Map']::text[], 1499, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('945cd954-360c-5887-83be-eb78d821ca27', 'Soul of the Sword', NULL, '9781335184993', 'Kitsune shapeshifter Yumeko has one task: take her piece of the ancient and powerful Scroll of a Thousand Prayers to the Steel Feather temple in order to prevent the summoning of the great Kami Dragon, who will grant one wish to whomever holds the scroll. But she has a new enemy now, more dangerous than any she has yet faced. The demon Hakaimono is free at last, and he has possessed the very person Yumeko trusted to protect her—Kage Tatsumi of the Shadow Clan. Hakaimono has one goal: break the curse of the sword and set himself free to rain chaos and destruction over the land forevermore. To do so, he will need the scroll. And Yumeko is the only one standing in his way.', '18.06.2019', 'inkyard press', ARRAY['Englisch']::text[], 425, 29, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Yumeko']::text[], ARRAY['Asia Mythology']::text[], '{}', '72276e14-a977-52d6-a8f2-a9bb4405ef7b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('4f08223c-5ffb-5e89-bc94-22ace3a99977', :'owner', '945cd954-360c-5887-83be-eb78d821ca27', 'tbr'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Hardcover']::text[], 'Normal', ARRAY['Map']::text[], 1828, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d9f9fb4-610e-56c7-9e9a-43a48743b759', 'Night of the Dragon', NULL, '9781335146786', 'To save everyone she loves from imminent death, kitsune shapeshifter Yumeko gave up the final piece of the Scroll of a Thousand Prayers. Now she and her ragtag band of companions must make one desperate final effort to stop the Master of Demons from using the scroll to call the Great Kami Dragon and make the wish that will plunge the empire into chaos. Shadow clan assassin Kage Tatsumi has regained control of his body and agreed to a true deal with the devil—the demon inside him, Hakaimono. They will share his body and work with Yumeko to stop a madman, and to separate Hakaimono from Tatsumi and the cursed sword that trapped the demon for nearly a millennium. But even with their combined skills and powers, this unlikely team of heroes knows the forces of evil may be impossible to overcome. And there is another player in the battle for the scroll, a player who has been watching, waiting for the right moment to pull strings that no one even realized existed…until now.', '31.03.2021', 'inkyard press', ARRAY['Englisch']::text[], 355, 30, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Yumeko']::text[], ARRAY['Asia Mythology']::text[], '{}', '72276e14-a977-52d6-a8f2-a9bb4405ef7b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
