insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('36163266-f061-5f5f-b1fb-ab3bf3e05de0', 'Talon - Drachennacht', 'Soldier', '9783453269729', 'Auch wenn ihr dadurch größte Gefahr droht, hat sich das Drachenmädchen Ember endgültig von der mächtigen Organisation Talon losgesagt. Nun hat sie auch noch ihren wichtigsten Verbündeten verloren: Garret, den Georgsritter, der ihr Feind sein sollte, der sie aber liebt. Obwohl Ember tief für ihn empfindet, hat sie ihn doch von sich gestoßen. Zutiefst verletzt, reist Garret nach London. Dort entdeckt er ein schreckliches Geheimnis über den Georgsorden. Ein Geheimnis, das sie alle, Ritter wie Drachen, ins Verderben reißen könnte. Und er erfährt, dass Ember dabei ist, in eine tödliche Falle zu laufen. Er muss zurück zu ihr …', '31.10.2016', 'Heyne', ARRAY['Deutsch']::text[], 479, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ember Hill','Garret']::text[], '{}', '{}', 'bc3c8372-f393-526f-836c-5916d17ebb7d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
