insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('556510a7-bfed-56cd-b7cf-c9923cec7214', 'Talon - Drachenblut', 'Legion', '9783453269743', 'Auf alles war das unerschrockene Drachenmädchen Ember vorbereitet - aber nicht auf den Schmerz, den sie empfindet, als der Sankt-Georgs-Ritter Garret leblos in ihren Armen niedersinkt, vom Schwert des Gegners schwer verwundet. Ohne zu wissen, ob Garret jemals wieder die Augen aufschlagen wird, muss Ember in den nächsten Kampf ziehen. Denn die mächtige Organisation Talon rüstet sich zum endgültigen großen Schlag gegen die Ritter und die aufständischen Drachen. Ganz vorne mit dabei: Dante, Embers Zwillingsbruder. Gemeinsam mit dem rebellischen Drachen Riley, der weiter um ihr Herz kämpft, dringt Ember in Dantes Versteck vor. Was die beiden nicht ahnen: Dante erwartet sie bereits. Und in seinen finsteren Plänen spielt Ember eine der Hauptrollen. Sollte sie sich widersetzen, ist ihr Leben nichts mehr wert ...', '29.09.2017', 'Heyne', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ember Hill','Garret']::text[], '{}', '{}', 'bc3c8372-f393-526f-836c-5916d17ebb7d', '4', '{}', 'sheet', :'owner') on conflict do nothing;
