insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('71e3541f-319a-5671-9dde-7bb56df63163', 'Talon - Drachenschicksal', 'Inferno', '9783453269750', 'Das mutige Drachenmädchen Ember hat sich entschieden: gegen Riley und für Garret, ihren Sankt-Georgs-Ritter. Auch wenn sie weiß, dass er nur ein kurzes Menschenleben hat und sie ihn für immer verlieren könnte. Denn der große Kampf gegen Talon steht bevor: Ember, Garret und der rebellische Riley brechen noch einmal zusammen zu einer gefährlichen Mission auf. Es gilt, die letzten mächtigen Drachen zu finden, die vielleicht bereit sind, es mit Talon aufzunehmen. Doch der Weg zu ihrem Versteck könnte die drei das Leben kosten. Und sie haben nur eine Chance, wenn sie einander bedingungslos vertrauen … Die Stunde der Entscheidung bricht an – das Schicksal aller freien Menschen und Drachen steht auf dem Spiel.', '01.10.2018', 'Heyne', ARRAY['Deutsch']::text[], 461, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ember Hill','Garret']::text[], '{}', '{}', 'bc3c8372-f393-526f-836c-5916d17ebb7d', '5', '{}', 'sheet', :'owner') on conflict do nothing;
