insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d868fe2f-5e32-566f-920b-414dc92d06ce', 'Roses in Chains', NULL, '9780008711719', 'The war is over, the dark forces have won, and the hero who was supposed to save them is dead. Captured as her castle is overrun by the enemy, Princess Briony Rosewood is stripped of her magic and auctioned off to the highest bidder. She''s sold to Toven Hearst: scion of a family known for their cruel control of magic - and her long-time, and unresolved, infatuation. Yet despite the horrors of her new world and the role she must learn to play within it, all is not lost. Help - and hope - may yet arise in the most unlikely of places...', '07.05.2026', 'HarperCollins', ARRAY['Englisch']::text[], 443, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Evermore', '{}', ARRAY['Briony Rosewood','Toven Hearst']::text[], ARRAY['Enemies to Lovers','Forbidden Love','Forced Proximity']::text[], ARRAY['Gore','Physische Gewalt','Sexuelle Gewalt','Tod','Folter']::text[], '05517941-bdf6-5633-b699-b9d2707079b6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
