insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5ba1aacb-4d66-5836-a33d-fad371fe88e7', 'Pandora Hearts (Vol.2)', 'Pandora Hātsu', '9783551794222', 'Als Spross einer Adelsfamilie verbringt Oz seine Zeit im Wesentlichen damit, seinem Freund und Diener Gilbert Schwierigkeiten zu machen. Doch dann wird er plötzlich von drei schwarzen Gestalten in die Unterwelt namens Abyss gestoßen, wo Verbrecher für ihre schlimmsten Sünden büßen müssen. Was Oz nicht weiß: Die geheimnisvolle Organisation Pandora will durch ihn an die Familie Baskerville rankommen. Und schon wird er von seiner Vergangenheit eingeholt...', '27.05.2011', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, 'Abyss', ARRAY['3P Objective']::text[], ARRAY['Oz Vessalius']::text[], '{}', '{}', 'b14165ce-db5c-5043-96b1-9d48b94b6ea7', '2', '{}', 'sheet', :'owner') on conflict do nothing;
