insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c3eff18c-c3cd-5505-9009-0d630e113d73', 'Pandora Hearts (Vol.3)', 'Pandora Hātsu', '9783551794239', 'Die unheilvollen Worte, die die Persönlichkeitsstörung des jungen Sünders mit sich bringen, sind der Bodensatz einer Erinnerung, die nicht weichen will. Nachdem seine reine Existenz abgelehnt wurde, weisen seine Augen nun jedes Licht zurück...', '29.07.2011', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, 'Abyss', ARRAY['3P Objective']::text[], ARRAY['Oz Vessalius']::text[], '{}', '{}', 'b14165ce-db5c-5043-96b1-9d48b94b6ea7', '3', '{}', 'sheet', :'owner') on conflict do nothing;
