insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4bb5d9c8-2448-5f0c-9169-4547c794717d', 'Royal Houses - Haus der Drachen', 'House of Dragons', '9783757702199', 'Als Kind wurde Kerrigan auf den Stufen des Hauses der Drachen ausgesetzt. Ihr Vater ist ein Fae-Prinz, und ihre Mutter war menschlich. Ihr Leben lang hat Kerrigan mit der Verachtung umgehen müssen, die in einer Welt herrscht, in der die Fae regieren und Menschen und Halb-Fae wenig Rechte haben. Doch eines Tages bekommt sie die Chance, einen Platz in der Hohen Gesellschaft zu erhalten. Denn gegen alle Regeln und Gepflogenheiten soll sie am Drachenturnier teilnehmen. Es werden fünf Drachen bereit sein, sich zu binden. So viele wie seit einhundert Jahren nicht mehr. Die Konkurrenz ist erbarmungslos. Und besonders hart kämpft der Prinz des grausamen Hauses der Schatten, um die jahrhundertelange Verbannung seines Hauses zu rächen ...', '02.02.2026', 'Lübbe', ARRAY['Deutsch']::text[], 525, 56, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Alandria', ARRAY['Single POV','3P Limited']::text[], ARRAY['Kerrigan']::text[], '{}', '{}', 'af6e4585-94c7-5827-8630-e278eb2b59ca', '1', '{}', 'sheet', :'owner') on conflict do nothing;
