insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('69ee59f4-6123-5883-9a56-205f9d7ad5f0', 'Leave Me Behind', NULL, '9781963474077', 'Nachdem ihr letzter Einsatz in einer Tragödie endete, soll Scharfschützin Nell Gallows in die Spezialeinheit Malum versetzt werden. Die Soldaten dieser Truppe sind bekannt dafür, nur die gefährlichsten Einsätze zu übernehmen – und Neuzugängen das Leben zur Hölle zu machen. Was also tun, wenn bald die Qual beginnt? Eine letzte Nacht der Freiheit! Doch der Unbekannte, mit dem Nell sie verbringt, ist ausgerechnet der Mann, den sie am meisten fürchten sollte: Bradshaw, ihr künftiger Vorgesetzter. Bradshaw ist grausam und gnadenlos – und dennoch ist da etwas, das die beiden magnetisch zueinander zieht.', '02.09.2025', NULL, ARRAY['Englisch']::text[], 455, 43, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Kalifornien, Rocky Mountains, Labrador', ARRAY['Double POV','1P']::text[], ARRAY['Nell Gallows','Bradshaw Bones']::text[], ARRAY['War Romance','Haunted Past','Mental Issues','Forced Proximity','Military','Enemies to Lovers','Strong FMC','Bullying']::text[], ARRAY['Sexuelle Gewalt','Dub-Con/Non-Con','Physische Gewalt','Tod von Familienangehörigen','Gore','Toxische Beziehungsdynamiken','Kriegsszenarien','Depiction of Trauma','Tod']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c58d3d91-af9f-5196-9818-bb198b9c8f75', :'owner', '69ee59f4-6123-5883-9a56-205f9d7ad5f0', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['In-Book Illustrationen']::text[], 2295, NULL, NULL, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Es hat sich komisch angefühlt dieses Buch zu lesen und all die "Grausamkeiten" zu genießen. Ich weiß nicht, ob ich das toxische mochte, aber ich mochte definitiv das von hate to love. Es gibt ein paar Lücken und ein wenig Kritik die ich üben könnte. Manches ging einfach zu schnell zB... Aber alles in allem ein echt gutes Buch. Es war spannend und ich hab es genossen. Mein erstes Dark Romance Buch.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('8d06491c-6a3a-5b5d-b9d7-52c818f7f0bf', 'c58d3d91-af9f-5196-9818-bb198b9c8f75', :'owner', 1, '2025-07-04', '2025-07-08', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b26da063-ee1a-5d7b-bfe9-3d795eddf024', 'Your Knife, My Heart', NULL, '9781464260155', 'Cameron Mortem has a problem: he can''t stop killing his partners. Officially labelled clinically insane, he''s also one of the most lethal assets in the Dark Forces - a brutal underground military operation built on obedience, survival, and silence. But an experimental drug has fractured his control, making him a liability whenever someone else is on the field. As punishment, he''s thrown back into the Under Trials: a merciless boot camp designed to break the weak and sharpen the ruthless. His one directive? Don''t kill the new girl. Emery Maves narrowly escapes a death sentence after her own brutal crimes, only to find herself forced into the same violent world. Assigned to Cameron, she''s expected to survive the Trials and her partner''s unstable nature. But Emery quickly realises there''s more to Cameron than bloodlust and body counts. Beneath the madness lies a terrifying allure - and a strange, dangerous tenderness. As the Trials push them to their limits, Emery must navigate the brutal demands of the Dark Forces while resisting the pull of a man who could just as easily kill her as protect her. And Cameron must fight the one urge he''s never been able to overcome. Their bond is intoxicating, chaotic, and born of violence. And if it doesn''t destroy them both, it might just save them.', '11.11.2025', 'Bloom', ARRAY['Englisch']::text[], 301, 35, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cameron Mortem','Emery Maves']::text[], ARRAY['War Romance','Mental Issues','Military']::text[], ARRAY['Physische Gewalt','Tod','Gore','Kriegsszenarien']::text[], 'c4e1bf05-bc01-5291-b8bc-93780843e3c1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
