insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bca82887-32bc-5d45-b918-b9e4ead05778', 'As you wish', 'Onozominomamani', '9783551786098', 'WIE SIE WÜNSCHEN, JUNGER HERR... Der Highschool-Schüler Kaname Nishino hat ein reiches Erbe angetreten, zu dem ein Luxusappartement inklusive Butler zählt. Aber verbindet die beiden wirklich nur ein Arbeitsverhältnis...? Neben dieser titelgebenden Story finden sich in dem Einzelband AS YOU WISH weitere ausdrucksstarke Boys-Love-Kurzgeschichten voller Romantik, Tragik und Leidenschaft.', '22.01.2009', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Kaname Nishino']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
