insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2323017b-194a-54fb-8429-573425062a38', 'Noble Contract', 'Taiyou No Kikoushi', '9783551752833', 'Hikaru ist bei einem Reiseveranstalter angestellt und wünscht sich nichts mehr, als im Ausland zu arbeiten. Dafür muss er jedoch erst ein Examen bestehen, bei dem er kläglich scheitert. Sein Leben ändert sich unerwartet, als er im Park auf einen Fremden stößt. Hikaru nimmt den gutaussehenden Leo mit zu sich nach Hause. Er erklärt sich bereit, Leo während seines einwöchigen Besuchs in Japan zu begleiten. Doch immer wieder stellt sich Hikaru die Frage, wer Leo wirklich ist und aus welchem Land er stammt! Welche Absichten verfolgt der mysteriöse Fremde?!', '30.07.2010', 'Carlsen', ARRAY['Deutsch']::text[], 232, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Hikaru','Leo']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
