insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('24832c22-b745-59e7-8b90-748e9da5363d', 'Secret Contract', NULL, '9783551789662', 'Japan in den 20er Jahren: Der ambitionierte Geschäftsmann Yuuichi ist schon seit seiner Kindheit eng mit dem anmutigen Iori befreundet - doch die beiden verbindet mehr als nur Freundschaft. Als Iori, Sohn einer einflussreichen Familie, von seinen Eltern mit einer fremden Frau verheiratet werden soll, wird die Liebe der beiden auf eine harte Probe gestellt...', '25.06.2009', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Japan', ARRAY['3P Objective']::text[], ARRAY['Yuuichi','Iori']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
