insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('de152f2e-671f-5ea6-a058-cfa251701a68', 'Cool as You (Vol.1)', 'Toshishita No Ryugi', '9783551740212', 'Yusuke schlägt sich im Großstadtdschungel als Kellner und Model mehr schlecht als recht durchs Leben. Als der jüngere Atsushi zum Studium in die Stadt und in Yusukes Wohnung zieht, wächst bei diesem die Unzufriedenheit. Denn derjenige, der früher doch so bewundernd zu ihm aufgeblickt hat, ist nicht nur angehender Basketballstar, sondern auch dank seines Aussehens dabei, Yusuke ernsthaft Konkurrenz beim Modeln zu machen. Denn dieser ist schlank und hoch gewachsen und einfach viel cooler, als Yusuke es jemals sein könnte. Wie geht man mit dem wachsenden Unmut um, wenn man den anderen eigentlich doch ganz gerne hat?', '01.01.2011', 'Carlsen', ARRAY['Deutsch']::text[], 210, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Yusuke','Atsushi']::text[], ARRAY['Queer']::text[], '{}', '343f520d-9ee7-509f-9ff3-42fb4db31e89', '1', '{}', 'sheet', :'owner') on conflict do nothing;
