insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('005d379e-9e7a-5557-82d5-3c0e00110877', 'Arkadien erwacht', NULL, NULL, 'Die Einsamkeit Siziliens birgt düstere Mythen und Legenden. Raubtiere jagen menschliche Beute in den Hügeln. Raubtiere, die sich hinter der Maske verfeindeter Mafiaclans verbergen. Als eine Tragödie Rosa aus New York nach Italien führt, ahnt sie nicht, dass sie viel mehr ist als nur ein Mädchen auf der Flucht. Bis sie Alessandro begegnet. Seine kühle Anmut, seine animalische Eleganz faszinieren und verunsichern sie. Nach den Gesetzen der Mafia müsste er ihr Todfeind sein – doch dann stoßen sie gemeinsam auf das uralte Geheimnis ihrer Familien.', '15.01.2010', 'Carlsen', ARRAY['Deutsch']::text[], 415, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Sizilien', '{}', ARRAY['Rosa','Alessandro']::text[], '{}', '{}', 'fb8e3a97-1d4f-5477-97e3-baf1b159cb34', '1', '{}', 'sheet', :'owner') on conflict do nothing;
