insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('027bb8d7-35ee-5a48-b777-f2cea2ecf05d', 'Arkadien brennt', NULL, '9783551582027', 'Menschen, die sich in Raubtiere verwandeln. Kämpfe zwischen Mafiaclans. Die verbotene Liebe zu Alessandro. Rosa braucht dringend Abstand und kehrt der wilden Schönheit Siziliens vorübergehend den Rücken. In New York will sie ihrer eigenen Vergangenheit nachspüren. Doch auch dort herrschen Dynastien von Gestaltwandlern hinter den Masken der Mafia. Alle Antworten auf Rosas Fragen führen direkt in die Arme ihrer Gegner. Und entfernen sie immer weiter von Alessandro …', '29.09.2010', 'Carlsen', ARRAY['Deutsch']::text[], 399, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Sizilien', '{}', ARRAY['Rosa','Alessandro']::text[], '{}', '{}', 'fb8e3a97-1d4f-5477-97e3-baf1b159cb34', '2', '{}', 'sheet', :'owner') on conflict do nothing;
