insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('20551146-c52e-52d2-b7f0-c2fafcca2d23', 'Arkadien fällt', NULL, '9783551582034', 'Rosa und Alessandro wollen ihre Gefühle füreinander nicht länger verbergen. Doch ihre Liebe bringt die Clans der Gestaltwandler gegen sie auf. Nach einer atemlosen Jagd durch die Weiten Siziliens erkennt Rosa, wer wirklich hinter dem Komplott gegen sie steckt: Der Hungrige Mann, der Herrscher aller Dynastien, ist zurückgekehrt – und die Welt der Arkadier wird niemals mehr sein wie zuvor.', '29.09.2011', 'Carlsen', ARRAY['Deutsch']::text[], 443, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Sizilien', '{}', ARRAY['Rosa','Alessandro']::text[], '{}', '{}', 'fb8e3a97-1d4f-5477-97e3-baf1b159cb34', '3', '{}', 'sheet', :'owner') on conflict do nothing;
