insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('86c44ec6-5862-5882-8318-2f990f97c256', 'The Promised Neverland (Vol.1)', 'Yakusoku no Neverland', '9783551739148', 'Die Frau, die sie wie ihre Mutter lieben, ist nicht ihre wirkliche Mutter, und die Kinder, mit denen sie zusammenleben, sind nicht ihre Geschwister. Denn Emma, Norman und Ray wachsen wohlbehütet in einem kleinen Waisenhaus auf. Doch eines Tages endet ihr glücklicher Alltag abrupt, als sie die schockierende Wahrheit über ihr Zuhause erfahren. Welches Schicksal wird die Kinder erwarten…?!', '20.03.2018', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Thriller (K)']::text[], NULL, NULL, 'Grace Field House orphanage', ARRAY['3P Objective']::text[], ARRAY['Emma','Norman','Ray']::text[], '{}', '{}', '9e784fcb-6925-54cd-9b73-b5cbd8e1295d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
