insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4102fc04-b73e-5fb3-9917-89624cd261e9', 'Sixteen Moons - Eine unsterbliche Liebe', 'Beautiful Creatures', '9783570138281', 'Liebe noch vor dem ersten Blick. Schon bevor Ethan sie zum ersten Mal gesehen hat, hat sie ihn in seinen Träumen verfolgt: Lena, die Neue an Ethans Schule. Lena, das Mädchen mit dem schwarzen Haar und den grünen Augen. Lena, die in Ravenwood wohnt, der verrufenen alten Plantage, von der sich alle in Gatlin fernhalten – alle außer Ethan. Lena, in die Ethan sich unsterblich verliebt. Doch Lena umgibt ein Fluch, den sie mit aller Kraft geheim zu halten versucht: Sie ist eine Caster, sie entstammt einer Familie von Hexen, und an ihrem sechzehnten Geburtstag soll sie berufen werden. Dann wird sich entscheiden, ob Lena eine helle oder eine dunkle Hexe wird… Ethan aber weiß: Auch ihm bleibt keine Wahl – ihm ist vorherbestimmt, Lena für immer zu lieben. Aber wird er bei ihr bleiben können, gleich, welcher Seite sie künftig angehört?', '09.08.2010', 'cbj', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'High School', '{}', ARRAY['Ethan','Lena']::text[], '{}', '{}', '04287a7a-8ebe-5008-8899-f7c333171697', '1', '{}', 'sheet', :'owner') on conflict do nothing;
