insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3dd6d563-2144-5160-b2c2-20c232cb546d', 'Honey x Honey Drops (Vol.1)', 'Mitsu x Mitsu Drops', '9783842003316', 'Als Yuzuru während der Sommerferien jobbt, lernt sie den betuchten und nervigen Kai Renge kennen, der dieselbe Schule besucht wie sie. Kai ist Mitglied der Kuge-ka, einer Klasse für die reichen Schüler der Akademie, und hat Yuzuru kurzerhand zu seinem "Honey" gemacht! Diese müssen fortan den reichen Schülern als Assistenten zur Seite stehen, im Gegenzug werden aber ihre Schulgebühren übernommen. Yuzuru will sich nicht in diese Rolle drängen lassen, doch der einzige Ausweg wäre, die Schule zu verlassen.', '07.03.2012', 'TokyoPop', ARRAY['Deutsch']::text[], 388, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'High School', ARRAY['3P Objective']::text[], ARRAY['Yuzuru','Kai']::text[], '{}', '{}', '2fba4919-a55b-543f-af41-818279bf92c0', '1', '{}', 'sheet', :'owner') on conflict do nothing;
