insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('429160b6-02b7-5786-a345-7d564857b456', 'Honey x Honey Drops (Vol.4)', 'Mitsu x Mitsu Drops', '9783842003347', 'Kai und sein Honey Yuzuru sind wieder glücklich vereint. Doch in der Schule ist die Hölle los, denn laut der neuen Schulordnung soll das Honey-System abgeschafft werden! Verzweifelt versuchen die Schüler der Kuge-ka, diese Neuregelung zu verhindern, denn keiner der Master möchte zukünftig auf sein Honey verzichten. Wird es auch nach dieser Revolution noch eine Zukunft für Yuzuru und Kai geben können?', '12.12.2012', 'TokyoPop', ARRAY['Deutsch']::text[], 388, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'High School', ARRAY['3P Objective']::text[], ARRAY['Yuzuru','Kai']::text[], '{}', '{}', '2fba4919-a55b-543f-af41-818279bf92c0', '4', '{}', 'sheet', :'owner') on conflict do nothing;
