insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7f58b94d-73ad-53a2-99ab-0113d4ad083b', 'Black Bird (Vol.1)', 'Burakku Bādo', '9783770471812', 'Misao hat ihr ganzes Leben versucht, die teuflischen Erscheinungen, die scheinbar nur sie sehen konnte, zu ignorieren. Mit ihrem 16. Geburtstag werden diese jedoch entschieden zu aufdringlich: denn als Auserwählte verspricht ihr Blut längeres Leben, ihr Fleisch gar die Unsterblichkeit. Doch zum Glück setzt ihr Jugendfreund Kyo in seiner Dämonenform alles daran, sie zu beschützen – und mehr… Black Bird bietet einfach alles, was ein Manga heute haben muss: Dämonisch angehauchte Fantasy, eine wunderbare Story und Romantik - brillant umgesetzt von Mangaka Kanako Sakurakouji, die für Black Bird den 54. Shogakukan-Mangapreis im Bereich Shojo erhielt!', '09.22.2009', 'Egmont Manga', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Misao Harada']::text[], '{}', '{}', '52920307-7840-5a29-95ed-5b38967876c1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
