insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('842ae732-851e-53aa-a385-3cbef02cf669', 'Devil from a foreign Land (Vol.6)', 'Iki no Ki', '9783646717365', 'Sorato trifft einen schweren Entschluss – er zieht gegen seinen Freund Garan in den finalen Kampf. Garan hat sich nämlich so verändert, dass er, um sein Ziel zu erreichen, nicht mal davor zurückschreckt, Hand an seine eigene Tochter zu legen. Kiyora ist zur Fessel für den Bann des Großen Königs des Schreckens geworden. Wraith und Nonoha werden in einem Turm, der über der Pforte der Hölle emporragt, gefangen gehalten. Das letzte Gefecht, bei dem alle vor hundert Jahren geknüpften schicksalshaften Beziehungen auf dem Spiel stehen, beginnt…', '2011', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Sorato']::text[], '{}', '{}', '7faef84a-f850-5045-9c39-1e33942ade1e', '6', '{}', 'sheet', :'owner') on conflict do nothing;
