insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('de3f891d-5645-582d-8c0c-d5a213a77877', 'Blood Hound', 'Yorugata Aijin Senmonten – Buraddo Haundo', '9783551781994', 'Als Rions beste Freundin Shiho spurlos verschwindet, bleibt ihr als einziger Anhaltspunkt eine Visitenkarte. Diese führt sie in einen zwielichtigen Club, in dem ein gewisser Suou arbeitet, den Shiho scheinbar gekannt hat. Um Nachforschungen anstellen zu können, lässt Rion sich dort anstellen. Was sie entdeckt, bestätigt ihre Vermutung...', '22.03.2006', 'Carlsen', ARRAY['Deutsch']::text[], 148, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rion Kanou','Suou']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
