insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1cd6b0d6-dcc5-5e54-ae1c-08cd8a277cad', 'Kaine', NULL, '9783551781857', 'Shinogus Zwillingsbruder Kaine ist Sänger der angesagten Band "Endorphine". Eines Nachts erleiden die Brüder einen Autounfall, den Kaine nicht überlebt. Plötzlich aber hält jeder Shinogu für seinen toten Zwillingsbruder! Von nun an übernimmt er Kaines Rolle als Superstar und findet bald heraus, was sein Bruder wirklich für ein Leben führte...', '22.05.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Shinogu','Kaine']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
