insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a5f44085-9597-5f23-96d4-ba9dfe570cbc', 'Neji Screw', 'Neji', '9783551768230', '"Ich bin Screw. Meinen wirklichen Namen kenne ich nicht. Im Jahr 1992 wurden meine Freundin Snow White und ich umgebracht und anschließend eingefroren. Heute, im Jahre 2033, holt mich die Regierung G.E.R.A. ins Leben zurück. Ich bin ein Wiederkehrer ohne Gedächtnis. Und nicht nur das: Ich soll meine übernatürlichen Kräfte als Attentäter in den Dienst der Regierung stellen..."', '15.02.2001', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Neji']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
