insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('83db6d58-9214-5331-92b1-1391b6f7f037', 'Perfume Master', 'Zero no Sōkōshi', '9783551777782', 'Parfumeur Kanade ist im Besitz einer der feinsten Nasen der Welt, mit der er sogar die unscheinbarsten Gerüche wahrnehmen und identifizieren kann. Zusammen mit seiner Cousine (und Sidekick) Anais stolpert er von Mordfall zu Mordfall. Denn mit seinem ausgeprägten olfaktorischen Sinn kann er selbst den Geruch des Todes wahrnehmen...', '22.09.2007', 'Carlsen', ARRAY['Deutsch']::text[], 180, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Kanade','Anais']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
