insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('28b18661-4e0c-5346-8ce9-0fab1fbe9029', 'Alice in Murderland (Vol.1)', 'Ansatsu Kyoushitsu', '9783551743923', 'Jeden Monat treffen sich die Mitglieder der superreichen und extrem einflussreichen Familie Kuonji zu ihrer »Mad Tea Party« – die einzige bewährte Familientradition. Auf einem jener Treffen teilt die Mutter Olga Kuonji ihren neun Kindern eine völlig unerwartete und schreckliche Nachricht mit: Die Geschwister müssen solange gegen einander kämpfen, bis nur noch einer von ihnen lebt und so zum neuen Oberhaupt des Clans wird… Die blutigen Spiele sind eröffnet!', '26.01.2016', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '1', '{}', 'sheet', :'owner') on conflict do nothing;
