insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d91e586-04d7-5aa3-a717-dfe6bac00b6e', 'Angel Sanctuary (Vol.1)', 'Tenshi Kinryōku', '9783551751812', 'Die Engel Alexiel und Rosiel sind Geschwister und bekämpfen sich auf Grund einer unglücklichen Liebe unerbittlich. Schließlich verbannt Alexiel ihren Bruder Rosiel ins Erdreich. Gott sperrt sie als Strafe für diese Tat in einen Kristall ein. Ihre Seele muss fortan in Menschen weiterleben. Der junge Setsuna Mudo weiß zunächst nicht, dass er einer der Träger Alexiels ist. Rosiel will sich währenddessen mit Hilfe des Videospiels "Angel Sanctuary" aus seinem Gefängnis befreien ...', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '1', '{}', 'sheet', :'owner') on conflict do nothing;
