insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6b47dbb6-b9f9-57df-9973-0af3743d4247', 'Belle und das Biest im verlorenen Paradies (Vol.1)', 'Rakuen no Bijo to Yajū', '9783551795977', 'Das Mädchen Belle hat, anders als ihr Vater und ihre Mutter, eine seltene, blasslila Haarfarbe. Eines Tages läuft sie in einen verbotenen Wald und begegnet dort einer Bestie, die schöne Mädchen entführt. Ihre Mutter, die ihr hinterherläuft, um sie zum Umkehren zu bewegen, gerät anstelle von Belle in die Fänge der Bestie. Ihr Vater, der seine Frau abgöttisch liebte, kommt über diesen Verlust nicht hinweg. Jahre später erscheint die Bestie wieder vor Belle... Eine Geschichte über Schönheit, Liebe und Hass.', '28.09.2021', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Belle']::text[], '{}', '{}', '1107edb8-6368-5aef-99cf-4c579b4127f1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
