insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('91a0fb8a-e803-52f5-ac29-48c9aa3306ba', 'Devil from a foreign Land (Vol.1)', 'Iki no Ki', '9783551766557', 'Ein großes Erdbeben hat ganz Tokyo zerstört. Ganze zwei Wochen nach dem Beben entdeckt man unter Massen von Schutt einen geheimnisvollen Jungen lebend – in seiner Handfläche prangt ein schwarzes Brandmal, sein Gesicht verdeckt eine Teufelsmaske. Das geheimnisumwobene Findelkind wächst als Diener und Freund bei seinem Retter Garan auf, dem Spross des ebenso reichen wie skrupellosen Barons Kamichika. Zwei Jahre nach der Katastrophe werden immer wieder Leichen gefunden, denen verschiedene Körperteile fehlen...', '04.12.2012', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Sorato']::text[], '{}', '{}', '7faef84a-f850-5045-9c39-1e33942ade1e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
