insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a2de7eff-d084-52df-acff-2e36bd241c09', 'Fairy Cube (Vol.1)', 'Fearī Kyūbu', '9783551751119', 'Ian Hasumi ist ein Junge, der schon immer Feen und ähnliche Fabelwesen sehen konnte, weswegen er mit seiner Umgebung immer wieder aneckt. »Ian der Lügner« wird er genannt und von allen ob seiner Spinnereien verspottet. Doch eines Tages wird der Junge Zeuge eines der mysteriösen Feenmorde, die so oft in den Zeitungen stehen, da der Täter bei seinen Opfern am Rücken blutige Male hinterlässt, die wie Flügel aussehen. Aber... stecken vielleicht nicht doch Feen hinter diesen Morden?', '22.12.2006', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Ian']::text[], '{}', '{}', '9bd4e5ad-2db6-53e9-801d-caae29a0edbb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
