insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('489dcb5a-5883-592f-8f97-d80a7e15ea3b', 'God Child (Vol.1)', 'Hakushaku Cain', '9783551769411', 'Die Geschichten um Count Cain, seinen treuen Butler Riff und seine für dunkle Vorlieben berüchtigte Familie spielen im viktorianischen England, Ende des 19. Jahrhunderts - der Zeit, als auch »Jack the Ripper« in London sein Unwesen trieb... Für den jungen Grafen gibt es einige mysteriöse Kriminalfälle zu lösen, die nicht selten etwas mit seiner geheimnisumwobenen Familie zu tun haben - der Stammbaum der reichen Grundbesitzer gibt zahlreiche ungelöste Rätsel auf. Auch ihn, den Count höchstpersönlich, umgibt eine geheimnisvolle Aura, hervorgerufen durch sein seltsames Äußeres, seiner Leidenschaft fürs Mysteriöse, und einer beachtlichen Sammlung von tödlichen Giften...', '22.12.2003', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
