insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5b8a1195-cdf9-58a9-9371-1facb693177b', 'Ludwig Revolution (Vol. 1)', 'Rūdovihhi Kakumei', '9783551781864', 'Ludwig ist das Infant Terrible des Königreichs und wahrlich kein Märchenprinz. Weder seine Kleidung noch seine Manieren sind seines Standes angemessen. Als sein verzweifelter Vater ihm aufträgt, endlich zu heiraten, machen sich Ludwig und sein Diener auf den Weg, die passende Märchenprinzessin zu finden. Ob es zum Happy-End kommt?', '22.08.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Ludwig']::text[], '{}', '{}', 'f559df76-d9e7-5173-b9f9-9d685d736218', '1', '{}', 'sheet', :'owner') on conflict do nothing;
