insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('169173bd-f5ee-55fe-bdab-08732f12e3d4', 'The Royal Doll Orchestra (Vol.1)', 'Ginyōru Kyūtei Gakudan', '9783551752253', 'In einer Welt, die von einem furchtbaren Virus heimgesucht wird, reist das Königliche Orchester durch das Königreich, um mit ihrer Musik den Menschen beizustehen. Denn der Galatea-Virus verwandelt einen Menschen unwiderruflich in einen Guignol, eine hungrige Puppe, die auf Fleisch aus ist. Nur die Musik von Rutil Chanteur und seinem Orchester scheint die Guignol stoppen zu können...', '24.12.2009', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rutil Chanteur']::text[], ARRAY['End of World','Monsters','Social/political Turmoil']::text[], '{}', '186b88e2-ee64-51cb-8410-038d59766fda', '1', '{}', 'sheet', :'owner') on conflict do nothing;
