insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba9322de-5cf8-5863-abee-ff0175779eb6', 'Angel Sanctuary (Vol.2)', 'Tenshi Kinryōku', '9783551751829', 'Eine verbotene Liebe verbindet die beiden Geschwister Setsuna und Sara Mudo. Aber Setsuna ist vom Schicksal als die Wiedergeburt des Engels Alexiel bestimmt. Dazu kommt noch, dass Alexiels Zwillingsbruder Rosiel durch den "Angel Sanctuary"-Plan zu neuem Leben erwacht ist und die beiden unentwegt verfolgt. Nur Setsunas bester Freund Kira hält noch zu ihm. Doch auch er birgt ein dunkles Geheimnis...', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '2', '{}', 'sheet', :'owner') on conflict do nothing;
