insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('091e32ca-d619-5945-a69e-94fe85e5532f', 'The Royal Doll Orchestra (Vol.2)', 'Ginyōru Kyūtei Gakudan', '9783551752260', 'In einer Welt, die von einem furchtbaren Virus heimgesucht wird, reist das Königliche Orchester durch das Königreich, um mit ihrer Musik den Menschen beizustehen. Denn der Galatea-Virus verwandelt einen Menschen unwiderruflich in einen Guignol, eine hungrige Puppe, die auf Fleisch aus ist. Nur die Musik von Rutil Chanteur und seines Orchesters scheint die Guignol stoppen zu können...', '26.08.2010', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rutil Chanteur']::text[], ARRAY['End of World','Monsters','Social/political Turmoil']::text[], '{}', '186b88e2-ee64-51cb-8410-038d59766fda', '2', '{}', 'sheet', :'owner') on conflict do nothing;
