insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b50c749d-f524-5dd6-bb8b-0bd857d96bc9', 'Alice in Murderland (Vol.3)', 'Ansatsu Kyoushitsu', '9783551743947', 'Das Labor der tanzenden Leichen... Ihrem geliebten Bruder Zeno zuliebe setzt Stella den Kampf auf Leben und Tod gegen ihre Geschwister fort. Nun muss sie gegen die zweitälteste Tochter Miser antreten, die durch eine Intrige aus Marés Hand zur Königin der Leichen wurde. »Lass uns ein Experiment mit diesen Kinderchen machen, die mein ''Blut'' aufgesaugt haben ...« Als sie sich Miser gegenüber sieht, die mit ihrem Blut Leichen steuert, kann »Bloody Alice« ihren Impuls nicht unterdrücken und zieht ihre Waffe... Willkommen zur Haunted Party, ausgerichtet von der bemitleidenswerten Miser.', '27.09.2016', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '3', '{}', 'sheet', :'owner') on conflict do nothing;
