insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7d4303b2-2701-5a6d-a350-ec155677569f', 'Devil from a foreign Land (Vol.3)', 'Iki no Ki', '9783551766571', 'Um Nonoha aus den Klauen eines Teufels zu befreien, dringt Sorato in die Höhle des Löwen ein. Dort wird er Zeuge einer öffentlichen Hinrichtung. Ein gewaltiges Menschenopfer, Wraiths Verrat, das geliebte Kind als Geisel genommen – dazu Soratos Erinnerungen an jene Nacht, als er seinen Freund verlor... Mit Menschenleben als Köder wird der Große König des Schreckens herbeigerufen. Ob Sorato ihm erneut im Kampf gegenüberstehen wird?!', '29.05.2013', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Sorato']::text[], '{}', '{}', '7faef84a-f850-5045-9c39-1e33942ade1e', '3', '{}', 'sheet', :'owner') on conflict do nothing;
