insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('34b2d2fe-e045-58ed-911c-92ddfea924dd', 'Alice in Murderland (Vol.4)', 'Ansatsu Kyoushitsu', '9783551743954', 'Nach dem tödlichen Kampf mit dem vierten Sohn Maré ist Stella völlig erschöpft. Während ihr Bewusstsein schwindet, taucht wie aus einem Nebel die Erinnerung an das traumatische Flugzeugunglück aus der Vergangenheit auf. War in dem Flugzeug nicht auch der weißhaarige Junge, der Stella früher zusetzte, und hat er nicht etwas Furchtbares getan?! »Sind wir beide uns früher... schon einmal begegnet? Zum Beispiel in einem Flugzeug?« An ihrer Seite sind Tsukito, der Weißhase, der ihren Kampf beobachtet und ihre erste große Liebe, ihr älterer Bruder Zeno. Wer von den beiden wird ihr Schicksal teilen und an ihrer Seite sein?', '31.01.2017', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '4', '{}', 'sheet', :'owner') on conflict do nothing;
