insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2cc7208b-c86d-590c-a1dc-2ddc2afd3276', 'Angel Sanctuary (Vol.4)', 'Tenshi Kinryōku', '9783551751843', 'Als seine über alles geliebte Sara durch die Machenschaften des inorganischen Engels Rosiel getötet wird, erwachen in Setsuna endlich die Kräfte des organischen Engels Alexiel. Er treibt in seiner Rage die Welt an den Rand der Vernichtung und stellt sich gegen sein Schicksal. Letztendlich bricht er auf gen Hades, um Saras Seele zurückzuholen..', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '4', '{}', 'sheet', :'owner') on conflict do nothing;
