insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9acc008b-9178-5dea-bb57-c67d82969486', 'Belle und das Biest im verlorenen Paradies (Vol.4)', 'Rakuen no Bijo to Yajū', '9783551796004', 'Endlich erwacht die zweite Belle, die Verlobte des Biests, aus ihrem langjährigen Schlaf. Wohlwissend, dass ihre Liebe nicht erwidert werden kann, hatte die Näherin Belle ihre Gefühle unter Verschluss gehalten. Doch da verrät die Verlobte vor dem Biest, was sie wirklich empfindet…! Derweil arbeitet La Media, die sich beim König beliebt machen konnte, am letzten Schliff ihres Racheplans gegenüber dem Biest…', '26.09.2022', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Belle']::text[], '{}', '{}', '1107edb8-6368-5aef-99cf-4c579b4127f1', '4', '{}', 'sheet', :'owner') on conflict do nothing;
