insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e5d4861c-25c3-5863-96ce-eb167bc28170', 'Devil from a foreign Land (Vol.4)', 'Iki no Ki', '9783551766588', 'Als Sorato der Spur eines Teufels hinterherjagt, landet er auf der Einweihungszeremonie des Riesensendeturms Zikkurat. Aufgrund von Falschmeldungen, die die Teufel verbreiten, werden Menschen fanatisiert und zu Schachfiguren eines größeren Plans. In diesem Chaos stößt Sorato auf die Person, von der er dachte, sie einst mit eigenen Händen getötet zu haben...', '03.09.2013', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Sorato']::text[], '{}', '{}', '7faef84a-f850-5045-9c39-1e33942ade1e', '4', '{}', 'sheet', :'owner') on conflict do nothing;
