insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4dea572b-5fae-5820-805f-f16c109e9e01', 'God Child (Vol.4)', 'Hakushaku Cain', '9783551769442', 'Mit seinem Besuch bei seiner Verlobten Emelyne stürzt Cain mitten in sein neuestes Abenteuer. Eine Begegnung mit der schönen Wahrsagerin Merediana führt ihn erneut auf die Spur von Dr. Disraeli und seinen makabren Machenschaften. Derweil freundet sich Merry mit Emelynes geistig verwirrtem Bruder Gilford an. Doch was hat es mit dem »roten Schaf« auf sich, das Gilford gesehen hat? Und welche Verbindung gibt es zwischen ihm, Merediana und »Jack the Ripper«, der in ihrer Nähe sein blutiges Unwesen treibt?', '22.09.2004', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '4', '{}', 'sheet', :'owner') on conflict do nothing;
