insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7ef16516-f6e3-54cf-b62b-595ca7da487f', 'Devil from a foreign Land (Vol.5)', 'Iki no Ki', '9783646717358', 'Im »Zikkurat«, dem Riesensendeturm, offenbart sich Etsuros wahre Identität: Er ist Garan! Sorato ist völlig verwirrt über das plötzliche Wiedersehen mit dem Freund, den er damals getötet hat und der ihm nun eine Falle nach der anderen stellt. Außerdem reißen Garans Machenschaften die Freunde auseinander. Was wird Sorato jetzt tun?', '2011', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, NULL, 'Tokyo', ARRAY['3P Objective']::text[], ARRAY['Sorato']::text[], '{}', '{}', '7faef84a-f850-5045-9c39-1e33942ade1e', '5', '{}', 'sheet', :'owner') on conflict do nothing;
