insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('45a33292-f79e-592a-b1c7-22d45c584d39', 'Alice in Murderland (Vol.5)', 'Ansatsu Kyoushitsu', '9783551743961', 'Die Narbe auf der Hand ihres geliebten Bruders Zeno befindet sich auf einmal auf der falschen Seite – diese schockierende Tatsache verwirrt Stella zutiefst. Und nach und nach entdeckt sie die grausame Wahrheit hinter diesem Geheimnis... »Ich habe die ganze Zeit über geglaubt, dass der Kerl, der ihn getötet hat, mein geliebter Bruder Zeno ist.« Das große Geheimnis, seit der »Beginning Tea Party« vor fünf Jahren wohl behütet, wird gelüftet!', '30.05.2017', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '5', '{}', 'sheet', :'owner') on conflict do nothing;
