insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d2fdb7d-5cb4-5fe6-a904-c10f9d121bf3', 'Angel Sanctuary (Vol.5)', 'Tenshi Kinryōku', '9783551751850', 'Um die Seele seiner geliebten Schwester Sara zu retten, versetzt Setsuna seinen Körper in einen Scheintod und tritt so als Geist seine Reise in den Hades an. Aber Setsuna bleiben nur 7 Tage, nach denen sein Körper vollkommen stirbt... Gleichzeitig spitzt sich im Hohen Himmel der Wettstreit zwischen Rosiel und Sevothtarte immer mehr zu.', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '5', '{}', 'sheet', :'owner') on conflict do nothing;
