insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6c6126ce-13a0-5314-ad21-65e8fc4309f8', 'Alice in Murderland (Vol.6)', 'Ansatsu Kyoushitsu', '9783551743978', 'Plötzlich erscheint der echte Zeno, der eigentlich auf der Beginning Tea Party vor fünf Jahren gestorben ist. Und er lüftet das letzte und größte Geheimnis von Tsukito. »Du darfst Tsukitos Hand nicht mehr loslassen!« Inmitten des Chaos verliert Stella jede Motivation zu kämpfen. Da erscheint ihr Vater und spricht von einer Möglichkeit, mit dem Brauch zu brechen und das Death Game zu beenden...', '31.10.2017', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '6', '{}', 'sheet', :'owner') on conflict do nothing;
