insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2eb0aad2-bc15-56c8-9670-abea80b166b5', 'Alice in Murderland (Vol.8)', 'Ansatsu Kyoushitsu', '9783551743992', 'Nachdem sie ihre älteste Schwester Ibara im Duell knapp besiegt hat, folgen für Stella für eine Weile friedliche Tage. Doch dann wird sie im Bad von dem vermeintlich verstorbenen Maré angegriffen! »Hast du mich, Maré, etwa vergessen?« Bald darauf beginnt der Kampf gegen dessen Zwillingsbruder Sol, den dritten Sohn des Hauses. Doch der nimmt sich Tsukito als Geisel und Alice sind die Hände gebunden. Haben die beiden gegen die mächtigen Flammen von Sol eine Chance?!', '02.10.2018', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '8', '{}', 'sheet', :'owner') on conflict do nothing;
