insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('63a43f27-92a4-595d-af7d-1760a24a36a4', 'Angel Sanctuary (Vol.8)', 'Tenshi Kinryōku', '9783551751881', 'Setsuna und Voice sind nach Assiah zurückgekehrt, um Setsunas Körper in Tokyo in Sicherheit zu bringen. Doch dort wartet schon Michael, der Feuerengel, um sie zum Kampf herauszufordern. Inzwischen verstärkt im Hohen Himmel die Geheimbewegung um den schlafenden Wasserengel Jibril urplötzlich ihre Aktivitäten. Und Jibril steht unter der Obhut Sevothtartes...', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '8', '{}', 'sheet', :'owner') on conflict do nothing;
