insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ed91104a-f73c-5e9c-b237-f2e28c83d3d4', 'God Child (Vol.8)', 'Hakushaku Cain', '9783551769480', 'Der dunkle Schatten seines Vaters Alexis verbreitet immer noch Angst und Schrecken in Cains Umgebung. Diesmal ist Cains Onkel Neal, einer seiner wenigen Vertrauten, das Ziel von Delilahs Attentätern. Als ein Pfeil diesen tödlich verletzt, schwört Cain, von nun an keinen der von ihm geliebten Menschen mehr dem Tod zu überlassen. Doch wird er dieses Versprechen einhalten können?', '22.04.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '8', '{}', 'sheet', :'owner') on conflict do nothing;
