insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a1bdaebc-ba0b-5e87-b6f5-5acf2b644ff7', 'Alice in Murderland (Vol.9)', 'Ansatsu Kyoushitsu', '9783551744005', 'Der Kampf der neun Geschwister um die Nachfolge des Kuonji-Oberhaupts geht weiter. Mittlerweile sind nur noch die zweitälteste Tochter Miser, der Jüngste, Melm, und Stella übrig. Stella, die nicht kämpfen möchte, sucht nach einer Möglichkeit, zu dritt aus dem Anwesen zu fliehen. Doch sie trifft auf ihre Mutter, die eiskalt lächelnd verkündet: »Dem Brauch dieses Hauses entkommt niemand.« Schließlich wird ihr befohlen, ein zweites Mal auf Leben und Tod gegen ihre geliebte Schwester Miser zu kämpfen. Die Schwestern beschließen, Olga hinters Licht zu führen und den Kampf vorzutäuschen. Doch dann geschieht etwas...', '26.02.2019', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '9', '{}', 'sheet', :'owner') on conflict do nothing;
