insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c53cc081-5a5f-5685-a368-4ee0d7fb79e9', 'Angel Sanctuary (Vol.9)', 'Tenshi Kinryōku', '9783551751898', 'Um seine geliebte Schwester Sara zu befreien, bricht Setsuna in den Hohen Himmel auf. Doch auf der Reise verliert er seinen Körper, und seine Seele schlüpft in den des Engels Alexiel. Nun gerät Kurai, die Setsunas wirklichen Körper wiederbeleben will, durch eine List Mad Hatters in die Fänge der Dämonenwelt. Unbekannte Gefahren erwarten Setsuna auf dem Weg zur Hölle..', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '9', '{}', 'sheet', :'owner') on conflict do nothing;
