insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('527579e2-0cec-5e0a-ba5c-9a9f03bfde54', 'God Child (Vol.9)', 'Hakushaku Cain', '9783551769497', 'Als seine tote Cousine Shuzette ihm im Traum erscheint, zieht es Cain zurück an das Grab seiner einstigen Geliebten. Dort wird er nicht nur in einen neuen Mordfall verwickelt - ihm erscheint ein junges Mädchen, das Shuzette wie aus dem Gesicht geschnitten ist. Ist sie Teil einer neuen, dunklen Machenschaft Delilahs, oder ein Puzzlestück eines viel älteren, tieferen Übels?', '22.06.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '9', '{}', 'sheet', :'owner') on conflict do nothing;
