insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f959b1aa-bf98-5a76-bf86-88164cebd10b', 'Alice in Murderland (Vol.10)', 'Ansatsu Kyoushitsu', '9783551745583', 'Die einzigen Geschwister, die im Haus Kuonji übrig sind, sind der jüngste Sohn Melm und Stella. Aber entgegen Stellas Wunsch, ihren kleinen Bruder zu beschützen, beginnt der Kampf. Der Ort, an dem Melm Stella zum Duell erwartet, ist die Grabstätte ihrer toten Geschwister. Dort sieht Stella ihre Schwester Claire, die eigentlich tot sein müsste… »Jetzt stirb schon endlich, Stella. Ich will, dass du dich zu meinen Puppen gesellst.« Stella ist verwirrt, da ihr niedlicher Bruder wie ausgewechselt ist. Und während der Kampf tobt, wird das Geheimnis um Melm gelüftet…!!', '27.08.2019', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '10', '{}', 'sheet', :'owner') on conflict do nothing;
