insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25eea8e0-d8e1-510a-bd8b-a629fab09c93', 'Alice in Murderland (Vol.11)', 'Ansatsu Kyoushitsu', '9783551745590', 'Gezwungen durch den Brauch der Kuonji, dass der Überlebende das nächste Familienoberhaupt wird, musste sich Stella gegen ihren Willen mit ihren Geschwistern duellieren. Doch nachdem sie sogar ihren fünf Jahre alten Bruder Melm getötet und das Recht, Familienoberhaupt zu werden, erworben hat, sagt ihre Mutter Olga zu ihr: »Ich habe beschlossen, mir deinen Körper zu rauben und damit weiterzuleben.« Für ihre eigenen Begierden hat Olga alle Kinder geopfert. Stella und Alice beschließen, gegen diese absolute Existenz anzutreten, auch wenn sie dafür sterben müssen! Der letzte, schicksalsschwere Kampf beginnt!', '28.01.2020', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Stella Kuonji']::text[], '{}', '{}', 'bfe1e98b-614b-5905-b764-9a0180e0c535', '11', '{}', 'sheet', :'owner') on conflict do nothing;
