insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('28c00c77-1ee9-553f-bea0-07155c65a4b6', 'God Child (Vol.11)', 'Hakushaku Cain', '9783551769510', 'Cain zieht erstmals Oscar, Merry und Clehadol in sein Vertrauen, um gemeinsam seinen Vater zu stürzen, bevor dieser seine Drohung, London zu vernichten, wahr machen kann. Eine Reihe von Menschenopfern führt sie auf die Spur seiner neusten Pläne. Bald jedoch verdichten sich die Beweise, dass sich unter Cains Freunden ein Verräter befindet. Eine schreckliche Wahrheit kommt ans Licht', '22.10.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '11', '{}', 'sheet', :'owner') on conflict do nothing;
