insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fd53c97c-99c4-5c87-9ecb-e5e1357bdf5f', 'Angel Sanctuary (Vol.12)', 'Tenshi Kinryōku', '9783551751928', 'Mit Zaphikels Hilfe gelingt es Setsuna, alleine den Hohen Himmel Yetzirah zu erreichen. Dieser bietet ihm an, ihn zu Sara zu führen, wenn Setsuna einwilligt als Symbol für seine Rebellenbewegung zu dienen. Als jedoch auch Sara erfährt, dass sich Setsuna im Himmel befindet, schmiedet sie von sich aus Pläne... Welche neuen Gefahren erwarten die beiden, sobald das Schicksal sie wieder vereint?', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '12', '{}', 'sheet', :'owner') on conflict do nothing;
