insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('abc44e40-4427-558b-8c15-f2e666af4afb', 'God Child (Vol.12)', 'Hakushaku Cain', '9783551769527', 'Die Erkenntnis, dass Riff ein Untergebener seines Vaters ist, stürzt Cain in tiefe Verzweiflung. Doch bald rappelt er sich auf, um seinem Vater ein letztes Mal entgegen zu treten und so seine Seele zu retten. Als Cain kurz darauf Delilah in die Hände fällt, erhält er Hilfe von unerwarteter Seite. Und auch die traurige Vergangenheit des Doktors wird endlich enthüllt..', '22.12.2005', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Gothic Horror']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Cain']::text[], '{}', '{}', 'ec1b5fd6-a3ce-5b27-bf67-30f96bfdaacb', '12', '{}', 'sheet', :'owner') on conflict do nothing;
