insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('156d0559-6463-557f-8a13-bdca2985f54d', 'Angel Sanctuary (Vol.13)', 'Tenshi Kinryōku', '9783551751935', 'Sara und Setsuna ist nur ein kurzes Wiedersehen vergönnt. Aus Sorge um Lil, die als ihr Double zurückblieb, lässt sich Sara aus freien Stücken von Sevothtarte gefangen nehmen und im Himmelskorridor einsperren. Währenddessen wird Zaphikel, der Setsuna vor dem Kugelhagel seiner Verfolgern schützte, zum »Flügelschlag« verurteilt - die höchste Strafe, die einen Engel im Himmel treffen kann. Setsuna fragt sich, wie er den Schaden, den sein gedankenloses Handeln verursacht hat, je wieder gut machen kann..', '01.03.2000', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '13', '{}', 'sheet', :'owner') on conflict do nothing;
