insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('48a26104-92eb-58a3-ba8b-419e36b0527a', 'Angel Sanctuary (Vol.16)', 'Tenshi Kinryōku', '9783551751966', 'Es wird wieder spannend im Kampf zwischen Himmel und Hölle! Setsuna konnte Saras Verurteilung verhindern und hat dadurch den ganzen Himmel in helle Aufruhr versetzt. Unterdessen rettet der verliebte Raphael die ohnmächtige Sara aus dem zerstörten Gerichtspalast. Sara ist hin- und hergerissen. Sie ist Raphael zwar dankbar, doch ihre Gefühle für Setsuna sind stark wie eh und je. Rosiel nutzt das Chaos um Sevothtartes Demaskierung in der Zwischenzeit zu seinen Gunsten. Doch wer ist der unheimliche Mann in der schwarzen Rüstung an seiner Seite...?', '01.10.2003', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '16', '{}', 'sheet', :'owner') on conflict do nothing;
