insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3dd17684-4b02-575c-adac-670fa897014c', 'Angel Sanctuary (Vol.17)', 'Tenshi Kinryōku', '9783551751973', 'Endlich erfährt Setsuna, wo er Sara finden kann. Doch ihr droht schon die nächste Gefahr in Form der bösen Machenschaften Sandalphons. Während Setsuna loszieht, um Sara zu retten hat Rosiel die Herrschaft über den Himmel erlangt. An seiner Seite steht Luzifer, der im Körper von Kira wieder auferstanden ist. Was führt Rosiel im Schilde? Start des letzten Kapitels der Saga, das noch viele verblüffende Enthüllungen bereit hält!', '01.12.2003', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '17', '{}', 'sheet', :'owner') on conflict do nothing;
