insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('14cb71bc-664c-50e0-bd8a-0800a34b41dd', 'Angel Sanctuary (Vol.18)', 'Tenshi Kinryōku', '9783551751980', 'Seit Rosiel mit Sandalphon verschmolzen ist, ist sein Name gleichbedeutend mit der absoluten Macht im Himmel. Währenddessen stellt Setsuna sich seinem Schicksal als Messias und tritt zum letzten Kampf mit Luzifer an. Sein Entschluss heilt seine Verletzungen und Setsuna erwacht zum wahren Messias! Auch Kato rüstet sich zu einem letzten, ganz privaten Kampf gegen den Herrn der Hölle..', '01.02.2004', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '18', '{}', 'sheet', :'owner') on conflict do nothing;
