insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bfc08f2d-238e-58f2-ba03-c0b99a38421d', 'Angel Sanctuary (Vol.19)', 'Tenshi Kinryōku', '9783551751997', 'Unter vielen Entbehrungen und dem Verlust ihres Freundes Kato haben Setsuna und seine Gefährten endlich Atziluth erreicht. Doch als Setsuna auf der Suche nach dem heiligen Turm, Etemenanki, den Garten Eden betritt, brechen Alexiels Erinnerungen aus seinem Unterbewusstsein hervor! Luzifer wartet dort schon auf ihn, und mit ihm Rosiel, der plant, die himmlischen Tafeln an sich zu reißen...', '01.04.2004', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '19', '{}', 'sheet', :'owner') on conflict do nothing;
