insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ff8efec4-c91e-589f-8d8c-a71c054ae013', 'Angel Sanctuary (Vol.20)', 'Tenshi Kinryōku', '9783551752000', 'Im letzten Band der Serie ist es Setsuna und seinen Freunden auf der Suche nach Adam Kadamon gelungen, den heiligen Turm Etemenanki zu betreten. Dort wartet das letzte große Geheimnis ihrer Reise auf sie: Die wahre Identität des Schöpfers und die Enthüllung von Alexiels und Rosiels Vergangenheit. Doch auch Sara, die noch immer unter Sandalphons Einfluss steht, erreicht den Turm und stellt sich gegen ihren Liebsten. Das Schicksal der Erde hängt nun von Setsunas Entscheidung ab...', '22.05.2004', 'Carlsen', ARRAY['Deutsch']::text[], 224, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Heaven, Earth, Hell', ARRAY['3P Objective']::text[], ARRAY['Setsuna Mudo']::text[], ARRAY['Forbidden Love']::text[], '{}', '0801e4e6-50ba-52e0-85c6-4be3d55a7106', '20', '{}', 'sheet', :'owner') on conflict do nothing;
