insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4d8f0df2-ba7e-5fa8-9dce-391fef168da2', 'Forever Free', 'Moments - Raelyn & Hunter', '9783736312555', 'Raelyn Miller kann es kaum erwarten, ihr Studium in Kalifornien zu beginnen und weit weg von zu Hause noch einmal ganz von vorn anzufangen. Doch schnell stellt sie fest, dass es gar nicht so leicht ist, auf eigenen Beinen zu stehen und dass ihr altes Leben sie stärker im Griff hat, als sie dachte. Vor allem, als sie den geheimnisvollen Hunter kennenlernt, zu dem sie sich magisch hingezogen fühlt, obwohl er doch alles verkörpert, was Raelyn endlich hinter sich lassen wollte ...', '30.04.2020', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'San Teresa University', '{}', ARRAY['Raelyn Miller','Hunter']::text[], '{}', '{}', '913275cf-9f03-5ecb-a5cf-3e3b115881e6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
