insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e1f5972b-8016-5182-ac40-e53b156cd354', 'Forever Mine', 'Moments - Kate & Alec', '9783736313316', 'Als die gesamte Universität von Kates One-Night-Stand mit Alec Volcov, dem Playboy der San Teresa University, erfährt, ist ihr sauberes Image als Bloggerin von einem Tag auf den anderen zerstört. Kate will einfach nur vergessen, was passiert ist, und zieht deshalb in ein neues, ruhigeres Wohnheim um. Was sie nicht ahnt: Ihr Zimmernachbar ist ausgerechnet Alec, der sie nicht nur bei jeder Begegnung an die Nacht erinnert, die ihr Leben für immer verändert hat, sondern der ihr plötzlich auch nicht mehr aus dem Kopf gehen will ...', '30.10.2020', 'LYX', ARRAY['Deutsch']::text[], 479, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'San Teresa University', '{}', ARRAY['Kates','Alec Volcov']::text[], '{}', '{}', '913275cf-9f03-5ecb-a5cf-3e3b115881e6', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
