insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b47d560f-014a-53bf-b7e7-f7d8cee0e4d6', 'The Finishing Touch', NULL, '9783736321786', 'Modedesignerin Veronica Edevane droht alles zu verlieren, als Rapper Damian Lewis ihre neue Kollektion in einem Interview als uninspiriert und konventionell beschreibt. Ein paar gemeinsam entworfene Designerstücke sollen Schadensbegrenzung betreiben, doch Roni hat wenig Lust, sich mit dem selbstverliebten Bad Boy und seiner großen Klappe herumzuschlagen. Damian wiederum weigert sich, für die Entwürfe einfach nur seinen Namen herzugeben, und so fliegen in Ronis Amsterdamer Atelier schon bald die Fetzen - und die Funken ...', '30.08.2024', 'LYX', ARRAY['Deutsch']::text[], 381, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Amsterdam', '{}', ARRAY['Veronica Edevane','Damian Lewis']::text[], '{}', '{}', '1ce5605a-f21a-54b1-8e91-933bf213433f', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
