insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('26c961de-c4a4-59bb-95b6-f6f2a20e05d5', 'Forever Close', 'Moments - April & Tyler', '9783736313347', 'Das letzte Jahr am College ist angebrochen, doch während alle schon begeistert Pläne schmieden und nach ersten Jobs suchen, ist April wie gelähmt. Im Gegensatz zu ihrem Freundeskreis will sie nicht, dass das Studium endet, weil das, was danach kommt, ihr die Luft zum Atmen nimmt. Aber da ist auch noch Tyler, ihr bester Freund, der einfach nicht aufhört, sie aus ihrer Schockstarre lösen zu wollen - und dabei Gefühle in ihr weckt, die April, seit sie sich kennen, tief in ihrem Herzen verschlossen gehalten hat ...', '30.07.2021', 'LYX', ARRAY['Deutsch']::text[], 439, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'San Teresa University', '{}', ARRAY['April','Tyler']::text[], '{}', '{}', '913275cf-9f03-5ecb-a5cf-3e3b115881e6', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
