insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bfd1ad26-bca8-5d58-a418-9ed949e05549', 'The Perfect Fit', NULL, '9783736319868', 'Ellie Cox kann ihr Glück kaum fassen, als sie auf der Fashion Week in Mailand kurzfristig als Stylistin für Sänger Roan engagiert wird. Einmal zum festen Stylist:innen-Team eines Brand Ambassadors zu gehören, war schon immer ihr großer Traum. Nur Caleb Lee, der verschlossene (und viel zu attraktive) Manager des Teams, ist wenig begeistert von Ellie und dem Chaos, das durch sie entsteht. Und als auch noch herauskommt, dass Ellie single ist und damit Einstellungskriterium Nummer eins nicht erfüllt, sieht sie sich endgültig auf gepackten Koffern sitzen. Aber dann macht Caleb ihr ein Angebot, das sie nicht ausschlagen kann: Er spielt ihren Fake-Boyfriend, wenn sie seinen Fehler bei ihrem Background-Check vertuscht! Und schneller als ihr lieb ist, steht für Ellie so viel mehr auf dem Spiel als nur ihre Karriere ...', '28.07.2023', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ellie Cox','Caleb Lee']::text[], '{}', '{}', '1ce5605a-f21a-54b1-8e91-933bf213433f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
