insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('206e52f1-cca4-5eb4-be88-5bb61467684b', 'The Brightest Colours', NULL, '9783736320741', 'Seit Make-up-Artist Mia Knight denken kann, ist sie ihrem Kindheitsfreund Roan nicht von der Seite gewichen. Nicht als er nach London zog, um seinen Traum zu leben. Nicht als er als Sänger von Parallel weltberühmt wurde. Immer für ihren besten Freund da zu sein, ist für Mia selbstverständlich. Genauso wie es selbstverständlich ist, dass das zwischen ihnen niemals mehr als Freundschaft sein wird, ganz egal was sie tatsächlich für Roan empfinden mag. Das, was sie haben, ist einzigartig. Unzerstörbar. Etwas, das niemand für die flüchtige Chance auf Liebe riskieren würde. Niemand außer Roan ...', '26.01.2024', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mia Knight','Roan']::text[], '{}', '{}', '1ce5605a-f21a-54b1-8e91-933bf213433f', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
