insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('55a405ec-0b5f-5064-93fe-645a7db93348', 'Iron Witch - Das Mädchen mit den magischen Tattoos', 'The Iron Witch', '9783838720111', 'Donna ist ein Freak. Eine Außenseiterin. Das zumindest behaupten ihre Mitschüler. Seit einem Angriff der Dunklen Elfen vor Jahren ist sie gebrandmarkt mit Tätowierungen aus Silber, Eisen und voller Magie, die sie vor anderen versteckt. Eines Tages kehren die einst aus Faerie vertriebenen, Unheil stiftenden Dunklen Elfen zurück. Jetzt muss Donna sich entscheiden. Wird sie ihren besten Freund retten und dafür eines der wohlbehütetsten Geheimnisse der Welt verraten?', '12.10.2012', 'Baumhaus', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Donna']::text[], '{}', '{}', '22d4e57a-4871-5f2c-b951-09276959d86c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
