insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4891eba3-2619-5226-a8cc-8c10bed98c72', 'Die Träumenden', 'The Dreamers', '9783959672603', 'Santa Lora, Kalifornien: Es beginnt an einem College. Ein junges Mädchen auf einer Party fühlt sich plötzlich müde, so müde wie noch nie in ihrem Leben. Sie wacht nicht wieder auf. Zuerst denken sie, es kommt aus der Luft, ein Gift, eine Art Virus. Aber niemand kann es nachweisen. Was auch immer es ist, es breitet sich rasend schnell in Santa Lora aus: Menschen werden müde, legen sich hin - und schlafen für immer. Sie sind nicht tot, sie wachen aber auch nicht mehr auf. Panik bricht aus, die Stadt wird von der Außenwelt abgeriegelt. Mittendrin: Eine junge Studentin, die im College unter Quarantäne steht. Zwei kleine Mädchen, deren Vater ihr Haus in eine Festung verwandelt. Und ein Paar, das verzweifelt versucht, sich und ihr Neugeborenes zu schützen, während um sie herum alles im Chaos versinkt.', '01.02.2019', 'HarperCollins', ARRAY['Deutsch']::text[], 333, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Santa Lora, Kalifornien', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
