insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('251a53c8-5172-5b4b-bfb4-e9953d17a9cc', 'Die 100', 'The 100', '9783641156022', 'Seit einem vernichtenden Atomkrieg lebt die Menschheit auf Raumschiffen. 300 Jahre lang hat niemand mehr die Erde betreten. Doch nun sollen 100 jugendliche Straftäter das Unmögliche wagen: zurückkehren und herausfinden, ob ein Leben auf dem blauen Planeten wieder möglich ist. Doch was die idealistische Clarke, der geheimnisvolle Bellamy und die anderen Verurteilten nach ihrer Ankunft vorfinden, raubt ihnen den Atem. Ein tödliches Abenteuer beginnt, auf das sie kein Training der Welt hätte vorbereiten können ...', '27.07.2015', 'Heyne', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Erde', '{}', ARRAY['Clarke Griffin','Wells Jaha','Bellamy Blake','Glass Sorenson']::text[], '{}', '{}', 'c521a00e-29fe-599c-a5a3-c3f85e00a02f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
