insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('36f039b8-5147-5b43-8b49-bd940b68d352', 'Neon Gods - Hades & Persephone', 'Dark Olympus', '9783736318571', 'Als ihre Mutter Persephone auf einem Ball überraschend Zeus verspricht, bleibt der jungen Frau keine Wahl: Sie flieht über die Brücke des Styx in die Unterstadt, wo sie plötzlich dem geheimnisvollen Hades gegenübersteht. Seit Jahren hat ihn niemand mehr gesehen, er ist ein Mythos, ein Monster - und ihre einzige Chance, Zeus und ihrer Mutter zu entkommen. Vom ersten Augenblick an übt Hades eine Faszination auf Persephone aus, der sie sich nicht entziehen kann. Und so bietet sie ihm einen Deal an, der ihrer beider Leben für immer verändern wird ...', '25.11.2022', 'LYX', ARRAY['Deutsch']::text[], 431, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Hades','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '1', '{}', 'sheet', :'owner') on conflict do nothing;
