insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ea9934a7-7525-529c-bac2-198a05e6fa3b', 'Neon Gods - Eros & Psyche', 'Electric Idol', '9783736319134', 'Psyche weiß, dass alles in Olympus seinen Preis hat. Und als sie Aphrodites Zorn erweckt, verlangt diese einen unbezahlbaren Tribut: ihr Herz. Ausgerechnet Aphrodites Sohn soll es ihr überbringen. Eros ist als gewissenloser Auftragskiller bekannt. Kalt, berechnend und gefährlich. Doch als er Psyche gegenübersteht, bringt er es nicht über sich, sie zu töten. Fasziniert von der wunderschönen jungen Frau, tut er das Einzige in seiner Macht Stehende, um sie zu retten: Er bietet ihr an, sie zu heiraten, um sie vor seiner Mutter zu schützen ...', '31.03.2023', 'LYX', ARRAY['Deutsch']::text[], 445, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Eros','Psyche']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
