insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e4eb380b-cc8d-56ba-a93e-2cd569afc012', 'Neon Gods - Helena & Achill & Patroklos', 'Wicked Beauty', '9783736319929', 'Um ihrem goldenen Käfig zu entfliehen, ist Helena Kasios fest entschlossen, der nächste Ares von Olympus zu werden. In einem aus drei Prüfungen bestehenden Turnier soll entschieden werden, wer den freien Platz einnimmt und damit einer der Dreizehn wird. Gewinnen bedeutet Macht und für Helena vor allem eines: Freiheit. Doch dann verkündet Zeus, dass der Sieger des Turniers neben Ares'' Titel Helena zur Frau erhält. Plötzlich muss Helena alle schlagen, um sich selbst zu retten. Sie findet sich in einem Wettstreit wieder, in dem sie niemandem vertrauen sollte. Besonders nicht dem unwiderstehlichen Duo Achill und Patroklos ...', '30.06.2023', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Helena','Achill','Patroklos']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
