insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d1c4f687-9773-57c1-ae94-277464f48abd', 'Neon Gods - Orpheus & Eurydike & Charon', 'Midnight Ruin', '9783736321977', 'Eurydike ist es leid, im Schatten ihrer mächtigen Familie zu stehen und ihrem Ex-Freund Orpheus nachzutrauern. Das Schicksal führt sie zu Charon, der als rechte Hand von Hades zwar alles für Olympus tun würde, aber ebenfalls endlich eigene Entscheidungen treffen will. Doch Eurydike kann ihre Vergangenheit nicht vergessen, und auch Charon merkt, dass zu ihrem Glück noch jemand fehlt: Orpheus. Als die Mauern von Olympus jedoch zu bröckeln beginnen und feindliche Truppen in die Stadt eindringen, kommt alles anders ...', '28.06.2024', 'LYX', ARRAY['Deutsch']::text[], 344, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Orpheus','Eurydike','Charon']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '6', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
