insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d65bb379-55fd-5ddf-aec3-9a5a76cbf202', 'Neon Gods - Ariadne & Minotaurus', 'Dark Restraint', '9783736323261', 'Ariadnes einzige Chance zu überleben, ist eine Zweckehe. Denn nachdem sie ihren Vater Minos verraten hat, ist sie auf die Gnade der Olympier angewiesen und bereit, das leidenschaftslose, aber sichere Bündnis mit Dionysos einzugehen. Doch es dauert nicht lange, bis ihre Vergangenheit sie einholt und der Mann, den Ariadne gleichermaßen fürchtet wie begehrt, wieder auftaucht: der Minotaurus. Bereits einmal zuvor hat sie sich an dem zwischen ihnen lodernden Feuer verbrannt. Und dennoch bringt jeder seiner Blicke, jede einzelne seiner Berührungen sie in Versuchung - auch wenn ihre Liebe den Untergang von Olympus bedeuten könnte ...', '29.11.2024', 'LYX', ARRAY['Deutsch']::text[], 362, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Ariadne','Minotaurus']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '7', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
