insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e01b3708-4bd9-5805-a95e-9c091c44069b', 'Neon Gods - Apollon & Kassandra', 'Radiant Sin', '9783736320314', 'Kassandra wird seit dem Tod ihrer Eltern von den mächtigen Familien von Olympus gemieden. Ihr einziges Ziel ist es, genug Geld anzusparen, um aus der Stadt zu entkommen und ihrer kleinen Schwester ein besseres Leben bieten zu können. Dafür arbeitet sie als persönliche Assistentin für Apollon, einen der mächtigen Dreizehn. Doch als Olympus in Gefahr gerät, braucht Apollon Kassandras Hilfe und bietet ihr einen unwiderstehlichen Deal an: Sie begleitet ihn auf eine legendäre Hausparty, um Informationen zu sammeln, und im Gegenzug garantiert Apollon ihr und ihrer Schwester die Flucht aus der Stadt. Der Plan scheint perfekt - wäre da nicht diese unvergleichliche Anziehungskraft zwischen ihnen, die alles zu verändern droht ...', '27.10.2023', 'LYX', ARRAY['Deutsch']::text[], 409, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Apollon','Kassandra']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
