insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e50ebac7-c0d9-5bc6-85c0-d38730f29aef', 'Neon Gods - Aphrodite & Hephaistos & Adonis & Pandora', 'Cruel Seduction', '9783736320345', 'Um ihre geliebte Stadt zu beschützen, heiratet Aphrodite den in ganz Olympus verrufenen Hephaistos. Auch wenn sie nichts als Hass für ihren frischangetrauten Ehemann verspürt, kann sie das unwiderstehliche Prickeln zwischen ihnen nicht leugnen, und sie gehen noch einen Schritt weiter: Während Aphrodite Hephaistos’ Kindheitsfreundin Pandora verführt, verwickelt ihr neuer Ehemann ausgerechnet Aphrodites Ex-Geliebten Adonis in ihr sinnliches Spiel. Die Grenzen zwischen Kalkül und Liebe verschwimmen, doch dann erreichen die Unruhen in Olympus einen neuen Höhepunkt ...', '26.01.2024', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Erotik']::text[], 'NA'::audience_kind, NULL, 'Olympus', '{}', ARRAY['Aprodite','Hephaistos','Adonis','Pandora']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '0dbf6e8f-c340-59bf-93ec-f4756d252f72', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
