insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7395375f-853b-5650-9010-04be0b6e48f9', 'Faye - Herz aus Licht und Lava', NULL, '9783743201910', 'Seit der Ankunft auf Island geschehen merkwürdige Dinge. Gleich am ersten Abend führt ein Schwarm Glühwürmchen Faye zu einer Lichtung, auf der ein uralter Baum steht. Der Sage nach soll hier der Eingang zur Elfenwelt sein. Aber vor Jahren wurde das Herz des Baumes gestohlen. Und jetzt stirbt er. Faye beschließt, den Baum zu retten. Keine leichte Aufgabe. Vor allem seitdem ihr der impulsive und jähzornige Aron über den Weg gelaufen ist. Wenn Faye wüsste, auf was für ein Abenteuer sie sich da einlässt …', '24.07.2019', 'Loewe', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, 'Island', '{}', ARRAY['Faye']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
