insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('80e53ef3-cb17-5099-9a51-77955ef34044', 'Beautiful Liars - Gefährliche Sehnsucht', 'The Thousandth Floor: Dazzling Heights', '9783473401642', 'New York, 2118: Im höchsten Wolkenkratzer der Welt wird für vier Jugendliche nichts mehr so sein wie vor der schlimmsten Nacht ihres Lebens. Denn einer von ihnen hat ein Menschenleben auf dem Gewissen. Und die anderen haben die Tat verheimlicht. Sie ahnen nicht, dass jemand weiß, was sie auf dem Dach des Towers getan haben. Und dieser Jemand wird sie nicht so einfach davonkommen lassen ... Um ihr dunkles Geheimnis zu verbergen, müssen sie den schönen Schein um jeden Preis wahren. Doch das ist alles andere als einfach. Denn einer von ihnen kämpft mit gefährlichen Gefühlen für ein gefährliches Mädchen. Eine von ihnen muss zu dem Jungen zurückkehren, dessen Herz sie in tausend kleine Teile zerbrochen hat. Eine von ihnen gerät in einen gefährlichen Strudel aus Hass und Schuld. Und eine von ihnen muss ihre große Liebe verleugnen, um ihre Familie nicht zu zerstören.', '20.06.2018', 'Ravensburger', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], NULL, 'Zukunft'::time_period, 'New York', '{}', '{}', '{}', '{}', '13a7ae3a-6a4e-52d6-b71a-4b93240fafa0', '2', '{}', 'sheet', :'owner') on conflict do nothing;
