insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ee49405c-55fc-50a8-908a-0ccbe768db56', 'Eve & Adam', NULL, '9788581634425', 'Liebe, Freundschaft, Gefühle, Action: der neue Jugendroman der Bestseller-Autoren Michael Grant und Katherine Applegate bei Ravensburger! Kann man die perfekte Liebe erschaffen? Als Tochter aus reichem Haus genießt die 17-jährige Evening Spiker so manches Privileg: zum Beispiel einen Aufenthalt in der Privatklinik ihrer Mutter, wo sie nach einem schweren Verkehrsunfall behandelt wird. Damit sich das Mädchen im tristen Krankenhausalltag nicht langweilt, soll sie ihren Traummann am Computer entwerfen. Größe, Augenfarbe, IQ – Eve darf alles selbst entscheiden und sich ihre große Liebe basteln. Sie hält es für ein lustiges Spiel, doch kurz darauf steht ihr ihr Traummann leibhaftig gegenüber ...', '01.02.2014', 'Ravensburger', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', '{}', 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Evening Spiker']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
