insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('97daa8b9-05d8-55c2-8752-d1234a1e6d94', 'c81bb04c-001e-516a-ad37-ec9861cddd76', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3bd400f6-fff8-5ac0-80d3-cada727120e3', 'Dylan und Gray', 'First Comes Love', NULL, 'Gray ist ein cooler Typ. Er interessiert sich nicht sonderlich für das, was um ihn herum passiert. Dylan ist das pure Gegenteil: Sie sprüht vor Energie und will aus jedem Tag etwas Besonderes machen. Die beiden könnten nicht unterschiedlicher sein - und doch lernen sich kennen und verlieben sich ineinander. In Dylans klapprigem Auto erkunden sie die Wüste, schreiben eine Ode auf einen Kaktus und adoptieren einen zotteligen Hund. Doch irgendwann ist der Sommer zu Ende, und die beiden müssen erkennen, wie leicht es ist, sich zu verlieben - und wie viel schwerer es sein kann, sich zu verzeihen und wiederzufinden, wenn man sich einmal verloren hat.', '21.09.2012', 'Lübbe', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Maddie Freeman']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
