insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('88dfeebd-8e14-5f52-83e6-798f1f5be223', 'f77139b3-074f-5bba-8744-19d159120091', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('af3d4f11-a0bf-5983-bb0d-7d43cd0a9124', 'Die Rebellion der Maddie Freeman', 'Awaken', '9783838711898', 'Eine Stadt in den USA, wenige Jahre in der Zukunft: Maddie, 17, lebt wie alle um sie herum ein digitales Leben. Schule und Verabredungen - das alles findet im Netz statt. Doch dann verliebt sie sich in Justin - für den nur das wahre Leben offline zählt. Gemeinsam mit seinen Freunden kämpft Justin gegen die Welt der sozialen Netzwerke, in der alles künstlich ist. Dieser Kampf richtet sich gegen die ganz oben - und damit auch gegen Maddies Vater, der das System der Digital School gesetzlich verankert hat. Maddie wird für die Bewegung zu einer Schlüsselfigur. Und sie muss sich entscheiden: Auf welcher Seite will sie stehen?', '22.07.2011', 'Lübbe', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Maddie Freeman']::text[], '{}', '{}', 'b504e0d2-c9f0-5fa5-a387-9ebd5c6ccd4b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
