insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3c54a308-567c-5353-92d5-fa3b00300b3f', '58164268-3a57-5639-bcaa-e26fe5055298', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('34879fdd-0aae-50ad-b47d-b404d7011d84', 'Der Widerstand geht weiter', 'Middle Ground', '9783838725147', 'Auch nachdem Maddie bei ihrem Bruder in L.A. eingezogen ist, setzt sie ihren Kampf fort. Gemeinsam mit Justin hilft sie Jugendlichen, die der Digital School den Rücken kehren wollen. Doch dann wird Maddie geschnappt und von der Polizei in eine Jugendstrafanstalt gesteckt. Hier werden alle inhaftiert, die sich gegen das System stellen. Isolationshaft und Gehirnwäsche sind im Gefängnis an der Tagesordnung und der Wille der meisten Insassen wird innerhalb kürzester Zeit gebrochen. Maddie ist lange standhaft! Doch die Haftbedingungen zermürben auch sie und schließlich ist sie kurz davor, aufzugeben. Wie soll sie alleine im Gefängnis gegen die übermächtig erscheinenden Gegner bestehen? Erst als der junge Aufseher Gabe ihr zu verstehen gibt, dass er auf ihrer Seite steht, schöpft Maddie neue Hoffnung. Aber um das System zu besiegen, muss sie sehr weit gehen ...', '15.12.2013', 'Lübbe', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Maddie Freeman']::text[], '{}', '{}', 'b504e0d2-c9f0-5fa5-a387-9ebd5c6ccd4b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
