insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('a3db1a1f-f6d5-58a6-a8aa-6add55427a25', 'eb5ef547-8624-5bba-8740-66e892e48219', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f3e7b4bd-df8d-5df8-b979-0f570c013484', 'Hotel Ambrosia - Du. Entkommst. Nicht.', NULL, '9783846602591', 'Die 17-jährige Robyn ist wie besessen vom Ambrosia, dem Hotel gegenüber ihrer Wohnung. Seine düstere Geschichte und die zwielichtigen Langzeitgäste faszinieren die True-Crime-Liebhaberin so sehr, dass sie oft mit dem Fernglas am Fenster sitzt. Sie kennt die Routinen des Personals, die Gewohnheiten der Gäste und das ein oder andere schmutzige Geheimnis. Insgeheim träumt Robyn davon, einen Cold Case zu knacken. Doch dann wird sie Zeugin einer Entführung - und das Opfer ist für Robyn keine Unbekannte. Sofort ist ihr klar: Sie muss etwas tun! Aber wie? Aufgrund einer Erkrankung kann Robynm ihre Wohnung im sechsten Stock nicht verlassen. Kurzerhand schickt sie A.J., einen Jugendlichen von der Straße, ins Ambrosia, um gemeinsam mit ihr zu ermitteln. Doch keiner von beiden ahnt, welche Schrecken im Hotel auf ihn lauern ...', '28.02.2025', 'One', ARRAY['Deutsch']::text[], 477, 66, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Krimi', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Hotel Ambrosia', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
