insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f9d850ca-530f-5e2f-90fe-62474d12bb69', 'Love Hour', NULL, '9783551763853', 'Der Oberschüler Naoto Sena ist schon lange in Go Kamikawa verliebt, den er seit seiner Kindheit kennt. Eines Tages eröffnet Go ihm, dass er sich verliebt hat, und zwar in einen Mann! Und dass dieser Mann auch in ihn verliebt sei!! Ein Drama für Naoto, wie soll er es bloß eine gute Miene aufsetzen, wenn seine heimliche Liebe einen Freund hat?!', '30.04.2013', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], NULL, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Naoto Sena','Go Kamikawa']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
