insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6432532f-1ad4-5eb8-bc42-2e0f3370a401', 'After School Dates Re.', NULL, '9783842049659', 'Das Schulfest der Tendomiya-Akademie steht an, das letzte große Event, das die Schulsprecher beider Schulzweige aus dem 3. Jahr leiten werden. Dabei werden sie von ihren Nachfolgern aus dem 2. Jahr, Tsukumo und Kawamura, tatkräftig unterstützt. Tsukumo aus der ISB kennt Makabe schon von Kindheit an und hegt augenscheinlich Bewunderung für ihn. Das sieht Shirota natürlich gar nicht gern, doch als er sich Tsukumo zur Brust nimmt, ist doch alles anders, als es scheint …', '14.02.2019', 'TokyoPop', ARRAY['Deutsch']::text[], 196, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Itsuki','Seiya']::text[], ARRAY['Queer']::text[], '{}', 'fab4748d-980a-5a30-a8a0-681c69a9f39b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
