insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4a69657b-7647-514d-8dfd-818de7cccc06', 'Redwood Love', 'Puppy Love: Redwood Ridge', '9783499275388', 'Redwood, ein malerisches kleines Städtchen in Oregon. Genau der richtige Ort für einen Neuanfang. Und den braucht Avery Stowe nach einer desaströsen Ehe dringend, ebenso für sich wie für ihre autistische Tochter Hailey. Da gibt es nur ein Problem: den attraktiven Tierarzt Cade O''Grady. Eine neue Beziehung ist das Letzte, was Avery will. Sie ist sich nur nicht sicher, wie lange sie Cade widerstehen kann. Vor allem, da sich anscheinend der ganz Ort gegen sie verschworen hat und Amor spielt …', '19.09.2018', 'Rowohlt', ARRAY['Deutsch']::text[], 364, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Redwood, Oregon', '{}', ARRAY['Flynn O’Grady','Gabby']::text[], '{}', '{}', '5cf7b3f5-d341-5bd4-8065-e86785bceace', '1', '{}', 'sheet', :'owner') on conflict do nothing;
