insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('63b62512-0fdc-5a26-8578-4d9e4ac0f635', 'Cinder & Ella', NULL, '9783846600702', 'Ella hat ein hartes Jahr hinter sich. Ihre Mutter starb bei einem Autounfall, den sie selbst nur knapp überlebte. Nach etlichen Klinikaufenthalten zieht sie nun zu ihrem Vater und dessen neuer Familie. Dabei will Ella nur eins: Alles soll so sein wie früher. Sie vermisst ihre Mom, ihren heißgeliebten Bücher-Blog - und Cinder, ihren Chatfreund. Brian Oliver ist der neue Star am Hollywoodhimmel. Doch der Ruhm hat seine Schattenseiten, echte Freunde sind selten geworden. Vor allem vermisst er seine Chatfreundin Ella, mit der er unter seinem Nickname Cinder stundenlang gechattet hat. Als die sich nach einem Jahr Funkstille plötzlich wieder meldet, ist Brian überglücklich. Langsam wird ihm klar, dass er mehr will als nur Freundschaft. Doch Ella hat keine Ahnung, wer er in Wirklichkeit ist ...', '28.09.2018', 'one', ARRAY['Deutsch']::text[], 312, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cinder','Ella']::text[], '{}', '{}', 'fef03b6f-7e4c-593f-8df3-c9a294cfbdb3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
