insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('59b309c1-c6a1-5f46-b83e-2b1e8a2c0726', 'Anathema', NULL, '9783736326477', 'Jede Berührung von ihm ist ein Spiel mit dem Tod. Niemand kehrt lebend aus den Eating Woods zurück. Ein Schicksalsschlag zwingt Maevyth Bronwick das tödliche Labyrinth zu betreten. Niemals hätte sie damit gerechnet, dort ihm zu begegnen: Zevander Rydainn, dem gefürchtetsten Assassinen des gesamten Kontinents - kalt, gnadenlos und berüchtigt als The Scorpion. Er würde Maeve lieber den Kreaturen des Waldes überlassen, als ihr zu helfen. Doch nur gemeinsam haben sie eine Chance zu überleben, selbst wenn das Feuer zwischen ihnen gefährlicher ist als alles, was im dunklen Wald lauert...', '01.06.2026', 'LYX', ARRAY['Deutsch']::text[], 809, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Romance']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Eating Woods', '{}', ARRAY['Maevyth Bronwick','Zevander Rydainn']::text[], '{}', '{}', 'bac23323-30f9-5a7b-93ea-679d967175c2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
