insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f74b648c-4c2d-56b5-be4c-4450e249e89d', 'Nocticadia', NULL, '9783736325944', 'Lilia Vespertine ist sich sicher: Der Tod ihrer Mutter war kein Selbstmord. Sie weiß, dass sie sich die seltsamen Parasiten nicht eingebildet hat, und erforscht sie auf eigene Faust - mit Erfolg. Ihr Ehrgeiz wird belohnt, und sie erhält ein Stipendium für die abgelegene Dracadia University. Eine einmalige Chance, denn dort lehrt der Experte ihres Forschungsgebiets, Professor Devryck Bramwell. Doch Dracadia ist kein gewöhnlicher Ort. Und Devryck ist kein gewöhnlicher Mann. Er ist Doctor Death, ebenso brillant wie unnahbar, ebenso faszinierend wie gefährlich. Und als seine talentierteste Studentin kommt Lilia schon bald nicht mehr nur der Wahrheit, sondern auch ihm immer näher ...', '31.10.2025', 'LYX', ARRAY['Deutsch']::text[], 816, 69, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Academia']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Dracadia University', '{}', ARRAY['Lilia Vespertine']::text[], ARRAY['Academy','Rivals to Lovers','Forbidden Love','Universicy/College']::text[], ARRAY['Physische Gewalt','Body Horror','Krankheit','Mord','Tod von Familienangehörigen','Tod','Kindesmishandlung','Häusliche Gewalt','Sexuelle Gewalt','Psychische Erkrankung/Belastung','Suizidalität','Tierquälerei','Drogenmissbrauch','Ableismus','Toxische Beziehungsdynamiken']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
