insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c4a2cd44-5fc2-5ba8-92b3-62b8153f5e75', 'Kingdom of the Wicked', NULL, '9781529350487', 'Emilia and her twin sister Vittoria are witches, forced to live their lives in secret to avoid persecution. Until one night, Vittoria doesn''t come home . . . Then Emilia finds her body, desecrated beyond belief. Devastated, she vows revenge at any cost: even if it means using forbidden magic - or summoning Wrath, one of the princes of the Wicked. Deadly, handsome, and brooding, Wrath claims to be on Emilia''s side, tasked with solving a series of murders on the island. But when it comes to the Wicked, nothing is as it seems . . .', '28.04.2022', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], NULL, NULL, NULL, '{}', ARRAY['Emilia','Wrath']::text[], '{}', '{}', '2c1160fd-7f72-5c39-9256-df9a87bbe74b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
