insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('de1f0ce1-401e-5599-b12d-786abbb116aa', 'Rubinrot - Liebe geht durch alle Zeiten', NULL, '9783401067636', 'Manchmal ist es echt nicht leicht, in einer Familie zu leben, die jede Menge Geheimnisse hat. Der Überzeugung ist zumindest Gwendolyn – bis sie sich eines Tages aus heiterem Himmel im London um die letzte Jahrhundertwende wiederfindet. Und ihr klar wird, dass ausgerechnet sie das allergrößte Geheimnis ihrer Familie ist. Sie ist eine Zeitreisende! Was ihr dagegen nicht klar ist: Dass man sich zwischen den Zeiten möglichst nicht verlieben sollte. Denn das macht die Sache erst recht kompliziert!', '01.06.2012', 'Arena', ARRAY['Deutsch']::text[], 343, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Gwendolyn']::text[], '{}', '{}', 'e6ab4fbe-0cc1-551c-add2-e79925013ed9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
