insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e2f228f3-ce3e-5cb7-a84c-9d533f9a7949', 'Saphirblau - Liebe geht durch alle Zeiten', NULL, NULL, 'Nachdem Gwendolyn herausgefunden hat, dass sie das Zeitreise-Gen in sich trägt, muss sie alles lernen, was zum Zeitreisen dazugehört: Menuett tanzen zum Beispiel oder die Etikette des 18. Jahrhunderts (beides nicht wirklich einfach!). Dabei ist sie viel mehr damit beschäftigt, zu verstehen, warum Gideon sich so seltsam verhält. Erst küsst er sie, dann lässt er sie links liegen. Doch während ihrer Zeitreise-Mission gerät Gwendolyn immer tiefer in ein Netz aus Intrigen und Verrat. Kann sie dem Grafen von Saint Germain vertrauen? Gwendolyn muss sich zusammenreißen. Schluss mit Liebeskummer und Sehnsucht. Stattdessen muss sie herausfinden, was der Graf vorhat. Denn sonst wird das nichts mit der Liebe zwischen allen Zeiten.', '01.06.2012', 'Arena', ARRAY['Deutsch']::text[], 389, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Gwendolyn']::text[], '{}', '{}', 'e6ab4fbe-0cc1-551c-add2-e79925013ed9', '2', '{}', 'sheet', :'owner') on conflict do nothing;
