insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('93b03260-d185-5156-b537-9a498b1e4c93', 'Smaragdgrün - Liebe geht durch alle Zeiten', NULL, NULL, 'Was tut man, wenn einem das Herz gebrochen wurde? Richtig, man telefoniert mit der besten Freundin, schaut Liebesfilme und isst Schokolade. Dumm nur, dass Gwendolyn ihre Energie für ganz andere Dinge braucht: zum Überleben zum Beispiel. Denn die Fäden, die der zwielichtige Graf von Saint Germain in der Vergangenheit gesponnen hat, ziehen sich nun auch in der Gegenwart zu einem gefährlichen Netz zusammen. Um dem Geheimnis auf die Spur zu kommen, müssen Gwendolyn und Gideon – Liebeskummer hin oder her – nicht nur zu einem rauschenden Ball ins 18. Jahrhundert reisen, sondern sich zu jeder Zeit kopfüber ins Abenteuer stürzen …', '01.06.2012', 'Arena', ARRAY['Deutsch']::text[], 482, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Gwendolyn']::text[], '{}', '{}', 'e6ab4fbe-0cc1-551c-add2-e79925013ed9', '3', '{}', 'sheet', :'owner') on conflict do nothing;
