insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7d76147c-648c-5ea9-81d7-bcfd19515176', 'Amaenbo Honey', NULL, '9783551621313', 'Tsubame und Miyama sind Omega und Alpha, aber trotzdem schon seit ihrer Kindheit beste Freunde. Obwohl Tsubame nie eine Chance gegen den stärkeren Alpha hat, fordert er ihn immer wieder zum Wettstreit heraus. Als er eines Tages vergisst, seine Pheromonhemmer zu nehmen, gerät er in Hitze und Miyama kann sich nicht mehr zurückhalten. Um Tsubame vor einem erneuten Ausbruch seiner Triebe zu schützen, geht Miyama auf Distanz. Doch das gefällt Tsubame ganz und gar nicht. Hat diese Liebe zwischen Alpha und Omega überhaupt eine Chance?', '28.09.2021', 'Carlsen', ARRAY['Deutsch']::text[], 200, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Tsubame','Miyama']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
