insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('882d9114-fee6-5e12-892e-5db71ee8c4bb', 'Selection', 'The Selection', NULL, 'Die Chance deines Lebens? 35 perfekte Mädchen – und eine von ihnen wird erwählt. Sie wird Prinz Maxon, den Thronfolger des Staates Illeá, heiraten. Für die hübsche America Singer ist das die Chance, aus einer niedrigen Kaste in die oberste Schicht der Gesellschaft aufzusteigen und damit ihre Familie aus der Armut zu befreien. Doch zu welchem Preis? Will sie vor den Augen des ganzen Landes mit den anderen Mädchen um die Gunst eines Prinzen konkurrieren, den sie gar nicht begehrt? Und will sie auf Aspen verzichten, ihre heimliche große Liebe?', '01.01.2013', 'Fischer', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Illeá', '{}', ARRAY['America Singer','Maxon']::text[], '{}', '{}', '6b422b8a-b1fb-51a2-a728-c23097ffc502', '1', '{}', 'sheet', :'owner') on conflict do nothing;
