insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b22d45d4-1b9d-5535-ac1c-81ba441ea5f4', 'Selection - Die Elite', 'The Elite', NULL, 'Das ganz große Glück? Von den 35 Mädchen, die um die Gunst von Prinz Maxon und die Krone von Illeá kämpfen, sind mittlerweile nur noch 6 übrig. America ist eine von ihnen, und sie ist hin- und hergerissen: Gehört ihr Herz nicht immer noch ihrer großen Liebe Aspen? Aber warum hat sich dann der charmante, gefühlvolle Prinz hineingeschlichen? America muss die schwerste Entscheidung ihres Lebens treffen. Doch dann kommt es zu einem schrecklichen Vorfall, der alles ändert.', '20.02.2013', 'Fischer', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Illeá', '{}', ARRAY['America Singer','Maxon']::text[], '{}', '{}', '6b422b8a-b1fb-51a2-a728-c23097ffc502', '2', '{}', 'sheet', :'owner') on conflict do nothing;
