insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fcc7b1a1-0289-5e0d-8a94-b06a655db0ff', 'The Betrothed', NULL, '9780008158828', 'When King Jameson declares his love for Lady Hollis Brite, Hollis is thrilled. After all, she''s grown up at Keresken Castle, vying for the king''s attention alongside other daughters of the nobility. Capturing his heart is a dream come true. But Hollis soon realizes that falling in love with a king and becoming queen may not be the happily ever after she thought it would be. And when she meets a commoner with the mysterious power to see right into her heart, she finds that the future she really wants is one that she never thought to imagine.', '14.05.2020', 'HarperCollins', ARRAY['Englisch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Keresken Castle', '{}', ARRAY['Hollis Brite']::text[], '{}', '{}', '490e6d60-e89f-55f8-bda3-b634164b1176', '1', '{}', 'sheet', :'owner') on conflict do nothing;
