insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e0695db1-8aca-508b-9529-17c2b0cc800a', 'Selection - Der Erwählte', 'The One', '9783737364980', '35 perfekte Mädchen waren angetreten. Nun geht das Casting in die letzte Runde: Vier Mädchen träumen von der Krone Illeás und einer Märchenhochzeit. America ist noch immer die Favoritin des Prinzen, doch auch ihre Jugendliebe Aspen umwirbt sie heftig. Sie zögert, denn sie liebt beide. Doch jetzt ist der Moment der Entscheidung gekommen: America hat ihr Herz vergeben, mit allen Konsequenzen. Komme, was wolle …', '19.02.2015', 'Fischer', ARRAY['Deutsch']::text[], 367, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Illeá', '{}', ARRAY['America Singer','Maxon']::text[], '{}', '{}', '6b422b8a-b1fb-51a2-a728-c23097ffc502', '3', '{}', 'sheet', :'owner') on conflict do nothing;
