insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5dd516a4-6b75-5e07-bb32-bb7adec192a3', 'Selection - Die Kronprinzessin', 'The Heir', '9783737352246', 'Nun ist es an Maxons Tochter Eadlyn, der Kronprinzessin, sich ihren Prinzen aus 35 jungen Männern zu erwählen. Alles könnte perfekt sein, wäre da nicht ein Problem: Eadlyn hat dem Casting nur zugestimmt, um das aufgebrachte Volk mit einer glamourösen Show zu besänftigen. Und an die große Liebe glaubt sie sowieso nicht. Aber vielleicht glaubt die Liebe ja an Eadlyn!', '23.07.2015', 'Fischer', ARRAY['Deutsch']::text[], 398, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Illeá', '{}', ARRAY['Eadlyn']::text[], '{}', '{}', '6b422b8a-b1fb-51a2-a728-c23097ffc502', '4', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
