insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f403ba6c-1456-5351-944a-b2ee0906d869', 'daebf83f-6c48-5da3-b09f-fc515e4d54a1', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aeffdbe2-f69e-5427-bdcc-269df91337aa', 'Selection - Die Krone', 'The Crown', '9783737354219', 'Als das Casting begann, war Eadlyn wild entschlossen, sich nicht zu verlieben und keinen der Bewerber an sich heranzulassen. Doch nun muss sie sich eingestehen, dass einige von ihnen doch Eindruck bei ihr hinterlassen haben: Henri, der charmante Lockenkopf, und sein bester Freund Erik. Der aufmerksame und rücksichtsvolle Hale. Der selbstsichere und attraktive Ean. Und natürlich Kile, Eadlyns Lieblingsfeind aus Sandkastenzeiten, der sie zu ihrem Ärger immer wieder aus der Reserve lockt. Sie alle haben es geschafft, einen Platz in Eadlyns Welt zu erobern. Aber wird es auch jemand in das Herz der Prinzessin schaffen?', '25.08.2016', 'Fischer', ARRAY['Deutsch']::text[], 325, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Illeá', '{}', ARRAY['Eadlyn']::text[], '{}', '{}', '6b422b8a-b1fb-51a2-a728-c23097ffc502', '5', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
