insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ed38496f-882a-5095-9ca4-3e14e32f685c', 'Tears N Kisses', 'Endlessly', '9783785572405', 'Von wegen normal! Eigentlich ist Evie vollauf damit beschäftigt, Weihnachtsgeschenke zu besorgen und den großen Winterball zu planen. Doch wie soll sie sich auf die wirklich wichtigen Dinge im Leben konzentrieren, wenn sie auf einmal das Gerichtsverfahren gegen ihre Ersatz-Mum Raquel verhindern, ihren Freund Lend aus den Fängen der Dunklen Elfenkönigin befreien und sich entscheiden muss, ob sie nun dieses verpiepte Tor in eine andere Dimension öffnen soll oder nicht.Dort hindurch will nämlich die gesamte Mannschaft der Paranormalen. Doch was, wenn Lend ebenfalls mitgeht und die Erde verlässt? Plötzlich ist Evies Entscheidung noch viel schwieriger als gedacht.', '17.06.2013', 'Loewe', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Evie']::text[], '{}', '{}', '5796f252-f217-5052-a76f-a25975515359', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('217ceb94-ad3c-5fd7-a6dd-391df6141cce', :'owner', 'ed38496f-882a-5095-9ca4-3e14e32f685c', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 499, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fbb05daa-3570-5826-bad2-eb154084f497', 'Slayer', NULL, '9781534404953', 'Into every generation a Slayer is born… Nina and her twin sister, Artemis, are far from normal. It’s hard to be when you grow up at the Watcher’s Academy, which is a bit different from your average boarding school. Here teens are trained as guides for Slayers – girls gifted with supernatural strength to fight the forces of darkness. But while Nina’s mother is a prominent member of the Watcher’s Council, Nina has never embraced the violent Watcher lifestyle. Instead she follows her instincts to heal, carving out a place for herself as the school medic. Until the day Nina’s life changes forever. Thanks to Buffy, the famous (and infamous) Slayer that Nina’s father died protecting, Nina is not only the newest Chosen One – she’s the last Slayer, ever. As Nina hones her skills with her Watcher-in-training, Leo, there’s plenty to keep her occupied: a monster fighting ring, a demon who eats happiness, a shadowy figure that keeps popping up in Nina’s dreams… But it’s not until bodies start turning up that Nina’s new powers will truly be tested – because someone she loves might be next. One thing is clear: Being Chosen is easy. Making choices is hard.', '08.01.2018', 'Simon & Schuster', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
