insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('480b0a48-fa1b-5d77-8b44-fa3990ef288c', 'Flames N Roses', 'Paranormalcy', '9783785572382', 'Hi, ich bin Evie und eigentlich total normal. Dachte ich zumindest immer. Also, mit Ausnahme von meiner besten Freundin, die eine Meerjungfrau ist, und von meinem Exfreund - einer Fee. Und abgesehen davon, dass ich die einzige Person auf der Welt bin, die die Tarnung von paranormalen Wesen durchschauen kann. Deswegen arbeite ich für die Internationale Behörde zur Kontrolle Paranormaler. So viel zum Thema normal. Und dann ist Lend auf der Bildfläche erschienen. Lend ist supersüß, kann gut zuhören und ist - ein Gestaltwandler. Und weil er in unsere Zentrale eingebrochen ist, steht nun meine ganze Welt auf dem Kopf und es ist die Rede von einer dunklen Prophezeiung, die leider bis ins Detail auf mich zutrifft. Nee, böse bin ich nicht, das muss eine Verwechslung sein. Ich muss dem Ganzen auf den Grund gehen, denn ich will endlich wissen, wer ich wirklich bin, und: Ich will Lend nicht verlieren!', '06.06.2011', 'Loewe', ARRAY['Deutsch']::text[], 381, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Evie']::text[], '{}', '{}', '5796f252-f217-5052-a76f-a25975515359', '1', '{}', 'sheet', :'owner') on conflict do nothing;
