insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('da78a486-5281-52f8-a39d-756ff0275f53', 'Dreams N Whispers', 'Supernaturally', '9783785572399', 'Sportstunden, Zickenkrieg auf der Mädchentoilette und ein eigener Spind! Evie ist glücklich, endlich das Leben eines gewöhnlichen Teenagers zu führen. Doch Normalsein kann auf die Dauer auch ziemlich … langweilig sein.Als die Internationale Behörde zur Kontrolle Paranormaler Evies Hilfe braucht, zögert sie nicht lange - und schon überschlagen sich die Ereignisse: Ihr Exfreund Reth konfrontiert sie mit niederschmetternden Enthüllungen über ihre Vergangenheit und im Feenreich bahnt sich ein Kampf an, bei dem es um niemand anders geht als - Evie selbst.', '01.06.2012', 'Loewe', ARRAY['Deutsch']::text[], 380, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Evie']::text[], '{}', '{}', '5796f252-f217-5052-a76f-a25975515359', '2', '{}', 'sheet', :'owner') on conflict do nothing;
