insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('31357163-b6f9-5062-8e83-7c0b4c264c7f', 'Masked by Nightfall', NULL, '9783736326552', 'Um ihre Familie zu retten, tritt Elodie Havare zur gefürchteten Auslese an - einem Trainingslager, das nur die besten Anwärter überstehen. Danach dienen sie als Schattensoldaten am Bruch. Eine riskante Aufgabe, da an der Grenze zum Reich der gefallenen Götter regelmäßig Menschen verschwinden. Um es so weit zu schaffen, will Elodie unsichtbar bleiben und nicht zur Zielscheibe werden. Doch ausgerechnet Jax Elder, ein ebenso gefährlicher wie faszinierender Anwärter, wird ihr als Partner zugeteilt. Elodie weiß nicht, ob sie Jax vertrauen kann, aber so sehr sie auch versucht, ihn auf Abstand zu halten, wenn sie Hilfe braucht, ist er da. Schließlich kämpfen sie gemeinsam ums Überleben - während zwischen ihnen eine Anziehung wächst, die alles zerstören könnte. Denn Elodie verbirgt ein Geheimnis, von dem niemand erfahren darf ...', '27.04.2026', 'LYX', ARRAY['Deutsch']::text[], 688, 65, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Elodie Havare','Jax Elder']::text[], ARRAY['He falls first','Secred Identity','Found Family','Forced Proximity','Enemies to Lovers']::text[], ARRAY['Krankheit','Tod von Familienangehörigen','Mord','Sexuelle Gewalt']::text[], 'b2a8d92d-e823-52f5-a75b-f62d5f641c89', '1', '{}', 'sheet', :'owner') on conflict do nothing;
