insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3e73a5d9-43b2-5b9c-9980-8a43f21b7d7b', 'Every Little Secret', NULL, '9783736317444', 'Die Nachricht, dass ihre biologische Mutter, die sie nie kennengelernt hat, ihr ein großes Vermögen vererbt, trifft Julie Penn vollkommen unvorbereitet. Um das Erbe antreten zu können, muss sie allerdings Teil des einflussreichen Familienunternehmens ihrer Mutter werden - eine Entscheidung, die ihr ganzes Leben verändert: Julie taucht in eine Welt voller Luxus und Reichtum ein, aber auch voller Intrigen und Geheimnisse - und sie trifft auf Caleb, den Adoptivsohn ihrer Mutter, dessen intensive Blicke Julies Herz trotz seiner abweisenden Art gefährlich schnell schlagen lassen. Doch plötzlich erreichen sie beunruhigende Anrufe und mysteriöse Drohbriefe, die Julie Angst einjagen ...', '29.07.2022', 'LYX', ARRAY['Deutsch']::text[], 544, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Julie Penn','Caleb Bonham']::text[], '{}', '{}', 'a58803d5-7048-57b2-be2d-6ac29b2593a4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
