insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b3fdcf56-99cc-56a4-afe8-b1f9de0b564e', 'Every Little Lie', NULL, '9783736318090', 'Julie Penn weiß nicht mehr, wem sie glauben oder vertrauen kann. Seit sie vorübergehend ein Teil des einflussreichen Familienunternehmens ihrer verstorbenen Mutter geworden ist, wurde ihr Leben vollkommen auf den Kopf gestellt. Und als sie auf Caleb Bonham traf - attraktiv, arrogant und ebenfalls Erbe des Unternehmens -, wurden auch ihre Gefühle ins Chaos gestürzt. Denn nachdem Caleb in bedrohlichen Situationen an Julies Seite war, konnten die beiden die Anziehung und das Knistern zwischen ihnen nicht mehr verleugnen. Julie war sich sicher, dass sie gemeinsam mit Caleb herausfinden würde, wer hinter den Drohungen und Einbrüchen steckt. Aber dann macht Julie eine Beobachtung, die ihr Herz in tausend Scherben zerbrechen lässt ...', '23.12.2022', 'LYX', ARRAY['Deutsch']::text[], 528, 40, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Julie Penn','Caleb Bonham']::text[], '{}', '{}', 'a58803d5-7048-57b2-be2d-6ac29b2593a4', '2', '{}', 'sheet', :'owner') on conflict do nothing;
