insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ee818166-52c0-58f4-96f3-a1ed14d5c779', 'One of Six - Verrat', NULL, '9783736320109', 'Die Studentin Luca Murphy erhält eine einmalige Chance: Sie wird eingeladen, an einem Auswahlverfahren für die Stelle als Social-Media-Managerin eines luxuriösen Skihotels teilzunehmen. Aber als sie in dem abgeschiedenen Ortiz Resort auf ihre Mitbewerber:innen trifft, befindet sich unter ihnen auch der attraktive Devan Sandoval, der sie auf einer College-Party angeflirtet und dann stehengelassen hat. Doch von dem Kribbeln, das Devans intensive Blicke in ihr auslösen, will Luca sich nicht ablenken lassen. Und auf einmal hat die Gruppe auch ganz andere Probleme, denn als ein Schneesturm und ein Stromausfall sie von der Außenwelt abschneiden, müssen sie sich fragen, ob da draußen jemand sein Unwesen treibt, der dort nicht hingehört ...', '29.09.2023', 'LYX', ARRAY['Deutsch']::text[], 474, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], NULL, 'Gegenwart'::time_period, 'Ortiz Resort, Eagle Creek', '{}', ARRAY['Luca Murphy']::text[], '{}', '{}', 'c006fe46-32b9-5520-a43a-7e9897b14e1e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
