insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2242a21b-51b8-563b-a8c8-8d9a81b6a97c', 'One of Six - Vertrauen', NULL, '9783736320192', 'Die Tage der Angst sind vorbei. Die sechs College-Studierenden mussten sich in dem abgeschiedenen Luxus Ski Resort in Eagle Creek ihren dunkelsten Geheimnissen stellen und lernen sich zu vertrauen. Denn nur gemeinsam konnten sie dem mysteriösen Unbekannten entkommen, der sie erpresst und bedroht hat. All das hat die Gruppe zusammengeschweißt - und bei einigen auch romantische Gefühle entstehen lassen. Doch nun wird diese Anziehung im beschaulichen Belville erneut auf die Probe gestellt, als sie sich nach einer Reihe von unerklärlichen Ereignissen die Frage stelle müssen, ob sie der Gefahr wirklich entkommen sind ...', '29.02.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], NULL, 'Gegenwart'::time_period, 'Ortiz Resort, Eagle Creek', '{}', ARRAY['Luca Murphy']::text[], '{}', '{}', 'c006fe46-32b9-5520-a43a-7e9897b14e1e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
