insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bd961b9e-a996-546e-a604-d86282deec93', 'Body Finder - Das Echo der Toten', 'The Body Finder', '9783815798737', 'Seit Violet ein kleines Mädchen ist, nimmt sie die Aura der Toten wahr. Wie magisch wird sie von ihnen angezogen, spürt ihre pulsierenden Echos unter der Haut vibrieren. Für sie ist diese Gabe jedoch alles andere als ein Geschenk - und nur widerwillig findet sie sich damit ab, dass sie die Einzige ist, die den Serienmörder aufhalten kann, der die kleine Stadt heimsucht, in der sie mit ihrer Familie lebt. Mithilfe ihres besten Freundes Jay macht sie sich auf die Suche. Aber dann passiert etwas, womit Violet nie gerechnet hätte: Sie verliebt sich in Jay. Und merkt dabei gar nicht, wie nahe sie dem Mörder bereits gekommen ist. Bis sie selbst zu seiner Beute wird.', '01.09.2010', 'Coppenrath', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Paranormal']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Violet Ambrose']::text[], '{}', '{}', 'ae1a8447-746e-59aa-8779-4672620138a0', '1', '{}', 'sheet', :'owner') on conflict do nothing;
