insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8f08c05f-eb6d-5891-9285-5632e6c3f551', 'Body Finder - Ruf der verlorenen Seelen', 'Desire of the Dead', '9783649601494', 'Als Violet die Leiche eines ermordeten Jungen entdeckt, zieht sie unweigerlich die Aufmerksamkeit des FBI auf sich. Nur widerstrebend bietet sie ihre Unterstützung bei den Ermittlungen an. Sie weiß, dass sie mit äußerster Vorsicht vorgehen muss, um ihre Gabe, die Aura der Toten wahrzunehmen, geheim zu halten. Doch schon bald geht es um sehr viel mehr: Ihre Beziehung zu Jay ist in Gefahr und ihr Leben.', '01.01.2012', 'Coppenrath', ARRAY['Deutsch']::text[], 344, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Paranormal']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Violet Ambrose']::text[], '{}', '{}', 'ae1a8447-746e-59aa-8779-4672620138a0', '2', '{}', 'sheet', :'owner') on conflict do nothing;
