insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cd8f6323-7a5b-5804-bed3-00335915743e', 'Von wegen Liebe', 'The Duff', NULL, 'Das hat Bianca gerade noch gefehlt. Der eingebildete Wesley, dem alle Mädchen an ihrer Schule zu Füßen liegen, spricht sie an. Und hat die Stirn, ihr rundheraus zu sagen, dass er das nur tut, um an ihre hübsche Freundin ranzukommen. Schneller, als er denken kann, hat er ihre Cola im Gesicht. Auf so jemand fällt Bianca nicht rein. Aber als zu Hause alles schief geht, lässt sie sich doch mit ihm ein. Heimlich und völlig unverbindlich, versteht sich. Mit Liebe hat das nichts zu tun. Oder?', '11.02.2013', 'cbt', ARRAY['Deutsch']::text[], 350, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Bianca','Wesley']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
