insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b669ac7e-4c26-5a43-95ab-8748e8334b15', 'Game On - Schon immer nur du', 'The Game Plan', '9783736313248', 'Ethan Dexter ist der Superstar der National Football League: Er sieht aus wie ein Rockstar, die Frauen liegen ihm zu Füßen - und er ist noch Jungfrau! Zumindest besagen das die Gerüchte. Doch Fiona Mackenzie fällt es schwer, das zu glauben. Vor allem, nachdem sie und Dex den heißesten Kuss der Weltgeschichte miteinander geteilt haben. Seitdem lässt Dex keinen Zweifel daran, was er will: Fiona. Doch die muss ihr Herz unbedingt vor einer weiteren Enttäuschung schützen ...', '27.11.2020', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ethan Dexter','Fiona Mackenzie']::text[], '{}', '{}', 'cf973c9d-a93f-5c3d-aeb8-623e139050ba', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
