insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d56ede4c-3407-54a2-ae48-bfbd86e386ec', 'Game On - Trotz allem du', 'Game On', '9783736313255', 'Für Quarterback Finn Mannus verläuft ein simples Kalender-Shooting anders als erwartet: Die toughe Fotografin Chess bringt ihn völlig aus der Fassung. Eigentlich hat Finn schon seine Erfahrungen mit Frauen gemacht, aber vom ersten Augenblick an spürt er in der Gegenwart von Chess eine nie gekannte, knisternde Anziehung. Für ihn steht fest: Er muss diese faszinierende Frau unbedingt für sich gewinnen - ist sie doch die erste, von der er mehr will als nur eine einzige Nacht. Aber dieses Vorhaben ist schwieriger als gedacht, denn ein Sportler mit dem Ruf eines Playboys ist das Letzte, was Chess gerade sucht ...', '29.01.2021', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Finn Mannus','Chess']::text[], '{}', '{}', 'cf973c9d-a93f-5c3d-aeb8-623e139050ba', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
