insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6a7863d4-7a4d-5cc0-850a-728839e7ce19', 'Dear Enemy', NULL, '9783736315396', 'In der Highschool waren sie Erzfeinde - zehn Jahre später hassen sie sich noch immer. Delilah Baker und Macon Saint sind wie Hund und Katz, doch als Delilahs Schwester den erfolgreichen Schauspieler bestiehlt und dieser Samantha anzeigen will, muss Delilah alles tun, um ihre Familie zu beschützen. Sie bietet Saint an, ein Jahr als persönliche Assistentin für ihn zu arbeiten. Und während sie ihre Feindschaft weiter pflegen, stellen sie fest, dass Hass und Liebe sehr dicht beieinander liegen ...', '28.05.2012', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Delilah Baker','Macon Saint']::text[], '{}', '{}', 'f2e399bf-354f-508d-b61e-07a902230c95', '1', '{}', 'sheet', :'owner') on conflict do nothing;
