insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7495d873-5070-5705-b326-c253a6a734f6', 'Idol - Gib mir die Welt', 'Idol', '9783736306967', 'Ruhig, unaufgeregt, zurückgezogen - so würde Libby Bell ihr Leben beschreiben. Doch das ändert sich, als sie eines Morgens einen fremden Typ in ihrem Vorgarten findet. Killian ist sexy und charmant - und ihr neuer Nachbar. Obwohl Libby sich nach dem Tod ihrer Eltern geschworen hat, niemanden mehr an sich heranzulassen, berührt Killian ihr Herz auf eine ganz besondere Art und Weise. Was Libby nicht weiß: Sie ist drauf und dran, sich in niemand anders als Killian James zu verlieben - Leadsänger und Gitarrist der erfolgreichsten Rockband der Welt ...', '27.07.2018', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Libby Bell','Killian James']::text[], '{}', '{}', '068b0bd1-4c42-521d-bdca-6e99228512f3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
