insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8de37dcd-7221-5ad4-a92a-8ea9b0af5249', 'Sweet Enemy', NULL, '9783736315778', 'Emma erlebt den schlimmsten Tag ihres Lebens. Nicht nur wurde ihre Rolle in der erfolgreichen Serie Dark Castle gestrichen, nein, sie findet auch heraus, dass ihr Freund sie betrügt. Am Boden zerstört zieht sich die Schauspielerin für einen Neuanfang auf ein Anwesen in Kalifornien zurück und trifft dort auf Lucian. Er ist verschlossen, abweisend und scheint nichts an ihr zu mögen. Und doch fühlt Emma sich von ihm angezogen, denn sie spürt, dass er ebenso verletzt ist wie sie. Kann sie Lucians Schutzmauern einreißen?', '30.09.2021', 'LYX', ARRAY['Deutsch']::text[], 494, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Emma','Lucian']::text[], '{}', '{}', 'f2e399bf-354f-508d-b61e-07a902230c95', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
