insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('513fe3c6-3690-5148-8847-37431fc51ea9', 'Idol - Gib mir dein Herz', 'Managed', '9783736307834', 'Sophie Darling kann ihr Glück kaum fassen, als sie für ihren Flug nach London ein Upgrade in die erste Klasse erhält - bis sie ihren Sitznachbarn kennenlernt. Gabriel Scott ist zwar der attraktivste Mann, den sie seit Langem gesehen hat, leider aber auch der unverschämteste. Und das ist noch nicht alles: Während des Flugs findet sie heraus, dass er niemand anders ist als der Manager der Rockband Kill John. Und somit womöglich bald ihr neuer Chef ...', '30.11.2018', 'LYX', ARRAY['Deutsch']::text[], 438, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sophie Darling','Gabriel Scott']::text[], '{}', '{}', '068b0bd1-4c42-521d-bdca-6e99228512f3', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
