insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('05642f8f-cd42-5203-b56d-a407078cca33', 'Idol - Gib mir deine Liebe', 'Fall', '9783736308435', 'Kurz vor einem Schneesturm will Stella Grey noch schnell ihre Vorräte aufstocken. Doch ein attraktiver Unbekannter reißt sich die letzte Packung Eis unter den Nagel. Eins ist klar: Ohne das Minzeis mit Schokoladensplittern wird Stella das Unwetter nicht überstehen. Und so greift sie zu einer drastischen Maßnahme: Sie küsst den Fremden und lenkt ihn damit ab, sodass sie mit dem Eis fliehen kann. Wer hätte schon ahnen können, dass es sich bei dem Überrumpelten um Jax Blackwood, Sänger und Leadgitarrist der erfolgreichen Rock Band Kill John, handelt? Und dass ausgerechnet er sich als Stellas neuer Nachbar entpuppt?', '28.06.2019', 'LYX', ARRAY['Deutsch']::text[], 569, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Stella Grey','Jax Blackwood']::text[], '{}', '{}', '068b0bd1-4c42-521d-bdca-6e99228512f3', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
