insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2ba6fc00-0051-5fd5-9013-07b5d56af71d', 'Idol - Gib mir alles von dir', 'Exposed', '9783736311077', 'Schon lange knistert es gewaltig zwischen Rye Peterson, dem Bassisten von Kill John, und der PR-Agentin der Band, Brenna James. Doch beide verbergen ihre Anziehung hinter bissigen Kommentaren und hitzigen Wortgefechten. Als Rye zufällig mitbekommt, dass Brenna auf der Suche nach einem Mann ist, der ihr Intimität und körperliche Nähe schenkt, schlägt er ihr einen Deal vor, der alles verändert. Eigentlich lautet die Regel: nur Sex, keine Gefühle. Aber mit jeder Berührung und jedem Kuss beginnen ihre Schutzmauern zu bröckeln ...', '28.01.2022', 'LYX', ARRAY['Deutsch']::text[], 506, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Rye Peterson','Brenna James']::text[], '{}', '{}', '068b0bd1-4c42-521d-bdca-6e99228512f3', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
