insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8b880b7c-c403-5c91-9a02-d0851ba13df1', 'Game On - Mein Herz will dich', 'The Hook Up', NULL, 'Anna Jones will vor allem eins: einen guten Collegeabschluss. Dass sie sich in den Star-Quarterback Drew Baylor verliebt, passt daher ganz und gar nicht in ihren Plan. Auch nach der ersten gemeinsamen Nacht mit ihm ist Anna sich sicher, dass daraus nicht mehr als ein One-Night-Stand werden darf. Daher stellt sie gleich ein paar Regeln auf, um ihr Herz vor dem charmanten Footballspieler zu schützen. Aber Drew will Anna für sich gewinnen. Und wenn er beim Football eins gelernt hat, dann, dass man hartnäckig bleiben muss, wenn man den Sieg davontragen will.', '29.06.2020', 'LYX', ARRAY['Deutsch']::text[], 498, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Anna Jones','Drew Baylor']::text[], '{}', '{}', 'cf973c9d-a93f-5c3d-aeb8-623e139050ba', '1', '{}', 'sheet', :'owner') on conflict do nothing;
