insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7bad77fc-3b74-5d01-87ee-b6caf5390187', 'Game On - Chancenlos', 'The Friend Zone', '9783736313194', 'Ivy kann es nicht fassen: Ihr Vater hat ihren geliebten rosafarbenen Fiat an den Footballstar Gray Grayson verliehen. Empört schreibt sie Gray eine Nachricht. Aus einer SMS werden Hunderte, und ohne dass die beiden sich je begegnet sind, werden sie Freunde. Doch dann stehen sie sich zum ersten Mal gegenüber, und das heiße Prickeln zwischen ihnen wirft Ivy völlig aus der Bahn. Aber egal wie sehr Gray ihr Herz zum Rasen bringt - die Klienten ihres Vaters sind für sie absolut tabu!', '28.08.2020', 'LYX', ARRAY['Deutsch']::text[], 406, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ivy','Gray Grayson']::text[], '{}', '{}', 'cf973c9d-a93f-5c3d-aeb8-623e139050ba', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
