insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0e4406f1-b6fe-5947-8999-440853f35f2d', 'The Crimson Moth', 'Heartless Hunter', '9780008650575', 'The only thing more treacherous than being a witch is falling in love… A HUNTED WITCH. The revolution reigns. The witches who once ruled are hidden, hunted. Rune is one of them. A socialite by day, she is the Crimson Moth by night. A vigilante bent on saving her own, her next rescue demands she court Gideon Sharpe – a notorious witch hunter and unforgiving revolutionary. A WITCH HUNTER. Gideon will pursue the Crimson Moth to the ends of the earth, and her trail leads him to Rune. But beneath her façade might be his match. Except what if she’s the very villain he’s been hunting?', '30.01.2025', 'Magpie', ARRAY['Englisch']::text[], 404, 62, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'The New Republic', ARRAY['Double POV','3P Limited']::text[], ARRAY['Rune','Gideon Sharpe']::text[], ARRAY['Enemies to Lovers','Disguised Identity','Secred Identity','Brother''s Best Friend']::text[], ARRAY['Tod von Familienangehörigen']::text[], '32e48620-4d69-536e-9099-677b19af8e2b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('e53801f2-5a94-5bfd-a76b-2f33b4b6afc4', :'owner', '0e4406f1-b6fe-5947-8999-440853f35f2d', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['eBook','Paperback']::text[], 'Normal', ARRAY['Map']::text[], 1849, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 0, 'slow'::burn_kind, 'Ok, das hier war ein kompliziertes Buch für mich. Auf der einen Seite hat es wirklich Spaß gemacht zu lesen, auf der anderen Seite habe ich mir wirklich viel aufgeregt. Gideon ist wirklich so ein schlimmer Charakter für mich. Er ist so scheinheilig wie er einfach Genocid für sich rechtfertigt. Ich verstehe, dass er schlechte Erfahrungen gemacht hat, aber er ist nicht besser. Alex hätte wirklich einfach so viel mehr verdient. Sein Tod hat mich wirklich zerstört. Außerdem hätte ich mir gewünscht, dass etwas mehr passiert und das Gideon und Rune sich besser kennengelernt hätten, bevor sie sich verliebt haben. Den Verity Twist hab ich auch nicht wirklich kommen sehen, obwohl ich irgendwie schon damit gerechnet habe, dass mit Verity etwas nicht stimmt.') on conflict do nothing;
