insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d3868341-f696-5f97-9f5c-e5f4ba6afb4d', 'The Rebel Witch', NULL, '9780008650629', 'Rune Winters is on the run from the republic who condemned her and the boy who betrayed her. Her friends, her home, and the life she knew are lost. An ocean away, her only ally is the unlikeliest one: Cressida Roseblood, the deposed witch queen intent on taking back what she thinks hers - the crown, the country, and Gideon Sharpe with it. Gideon will not allow the terrors of his past to rise again, even if this means hunting down every last witch. But there is only one witch who holds the key to Cressida''s return...and Gideon''s heart. And he will stop at nothing to find her. Rune Winters will meet her end. Even if it ends him too.', '27.02.2025', 'HarperCollins', ARRAY['Englisch']::text[], 455, 78, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'The New Republic', ARRAY['Double POV','3P Limited']::text[], ARRAY['Rune','Gideon Sharpe']::text[], ARRAY['Enemies to Lovers','Forbidden Love']::text[], ARRAY['Tod von Familienangehörigen']::text[], '32e48620-4d69-536e-9099-677b19af8e2b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c33375f8-cecf-5390-8404-5863b23e4cbc', :'owner', 'd3868341-f696-5f97-9f5c-e5f4ba6afb4d', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['Paperback','eBook']::text[], 'Normal', ARRAY['Map']::text[], 1292, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'hate'::verdict_kind, 0.5, 'untertroffen'::expectation_kind, 1, 'slow'::burn_kind, 'Dieses Buch war leider grauenhaft schlecht. Die Charaktere gingen mir auf die Nerven, die Autorin hat super inkonsequent geschrieben und ständig vergessen, was sie vorher behauptet hat und die Twists waren entweder extrem hervorsehbar oder kamen so sehr aus dem nichts, dass man gemerkt hat, dass sie spontan dazuerfunden wurden. Ich hab in einer Tour die Augen verdreht und die letzten paar Kapitel mehr überflogen als wirklich gelesen, weil ich einfach nur zum Ende kommen wollte') on conflict do nothing;
