insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ff3a8f77-643c-5821-8af2-22fd20a87938', 'Die Beschenkte', 'Graceling', '9783551310095', 'Lady Katsa wird überall gefürchtet, denn sie hat die Gabe des Tötens. Doch sie ist es leid, ständig als Racheengel eingesetzt zu werden – und als sie dem geheimnisvollen Prinzen von Lienid begegnet, schöpft sie Hoffnung, mit ihrer Gabe auch Gutes bewirken zu können. Prinz Bo zieht Lady Katsa magisch an und scheint genau wie sie ein Beschenkter zu sein. Schon bald verbünden sich die beiden, um gemeinsam in den Kampf zu ziehen. Und nicht nur das ...', '22.02.2011', 'Carlsen', ARRAY['Deutsch','Englisch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Lienid', '{}', ARRAY['Katsa']::text[], '{}', '{}', '188e83f8-9004-5efd-abc6-391324a86343', '1', '{}', 'sheet', :'owner') on conflict do nothing;
