insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b44fd88a-dd25-5459-a175-ff522e2a0017', 'Die Flammende', 'Fire', '9783551582119', 'Wer das Mädchen mit den Haaren wie Feuer einmal gesehen hat, wird es nie wieder vergessen: Fire übt eine unwiderstehliche Macht auf alle Lebewesen in ihrer Nähe aus. Sie kann in die Gedanken anderer Menschen eindringen. Nur nicht in die von Prinz Brigan. Wer ist dieser unnahbare Feldherr und welche Rolle spielt er im Kampf um den Thron? Um Fire herum entspinnt sich ein Netz aus Verschwörungen. Und obwohl sich ihr Innerstes dagegen sträubt, kommt sie dem Prinzen immer näher.', '12.01.2011', 'Carlsen', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, 'Vergangenheit'::time_period, 'Lienid', '{}', ARRAY['Katsa']::text[], '{}', '{}', '188e83f8-9004-5efd-abc6-391324a86343', '2', '{}', 'sheet', :'owner') on conflict do nothing;
