insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1c4a0467-7b2e-5754-883c-73d7c83bc3b9', 'Die Königliche', 'Bitterblue', '9783551582683', 'Finstere Verschwörungen und das Versprechen auf ein neues Leben ... Seit dem Tod ihres tyrannischen Vaters ist Bitterblue die alleinige Herrscherin eines ganzen Königreichs. Während sie langsam in ihre Aufgabe hineinwächst, muss sie sich unausweichlich der Vergangenheit stellen: Wer war ihr Vater, König Leck, wirklich? Was gehört zu den Lügengebäuden seiner Herrschaft und was ist tatsächlich die Wahrheit? Für ihre Nachforschungen schleicht sich Bitterblue Nacht für Nacht verkleidet aus dem Schloss, schließt unter falschem Namen ungewöhnliche Freundschaften in den Straßen und Wirtshäusern und verstrickt sich ihrerseits in ganz neue Lügen ...', '24.08.2012', 'Carlsen', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, 'Vergangenheit'::time_period, 'Lienid', '{}', ARRAY['Katsa']::text[], '{}', '{}', '188e83f8-9004-5efd-abc6-391324a86343', '3', '{}', 'sheet', :'owner') on conflict do nothing;
