insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('76edb3ce-97a7-58b7-90a7-4db0bade9b86', 'Verdammt', 'Kisses from Hell', '9783442477524', 'Die erste Begegnung, die ersten Blicke, der erste Kuss: Liebe kann etwas Wunderbares sein. Doch was, wenn die Liebenden Vampire, Strigoi oder Unsterbliche sind? Niemand liebt dramatischer, intensiver, gefährlicher. Und für niemand anderen bekommt der Ausdruck „ewige Liebe“ diesen ganz besonderen Sinn. Fünf Bestsellerautorinnen, die sich mit dem Thema bestens auskennen, erzählen fünf einzigartige Geschichten über die Liebe zwischen Vampiren und vielen anderen faszinierenden Wesen der Nacht.', '18.06.2012', 'Goldmann', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
