insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0463b1b9-e722-527a-8874-cc66980318d6', 'Dunkle Verführung', NULL, '9783404167104', 'Kein Geschöpf der Nacht übt eine solche erotische Faszination aus wie der Vampir. Das geheimnisvolle Wesen, dessen Libido so unersättlich ist wie sein Hunger nach sterblichem Fleisch, verspricht denen, die sich ihm hingeben, immerwährendes Vergnügen. Lernen Sie drei dieser dunklen Liebhaber kennen - und lassen Sie sich verführen.', '22.06.2012', 'Lübbe', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], NULL, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
