insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5ddd1b64-390c-5c6c-bcec-9dbc1694d93f', 'Das Tal - Das Spiel', NULL, '9783401064727', 'Mitten in den kanadischen Wäldern liegt das berühmte Grace-College, Ausbildungsschmiede für Hochbegabte. Doch seltsame Dinge gehen in dem abgeschlossenen Tal vor sich: Warum ist der Ort nicht auf Google Earth zu finden? Was hat es mit der Gruppe Jugendlicher auf sich, die Mitte der 70er in den Bergen verschwanden? Julia und ihre Clique sind ahnungslos, als sie ihr erstes College-Jahr beginnen. Doch sie werden bald herausfinden, dass im Tal nichts ist, wie es scheint. Und dass sie alle nicht ganz zufällig an diesem Ort sind. Eine hippe Einweihungsparty im Bootshaus: So feiern die Freshmen ihre Ankunft im Grace College. Doch dann beobachtet der stille Robert das Unfassbare: Ein Mädchen läuft in tiefer Nacht in den See. Sie wird von einem merkwürdigen Strudel erfasst und ertrinkt. Robert versucht zu helfen - doch er hat keine Chance. Am nächsten Morgen glaubt ihm niemand seine Geschichte, obwohl tatsächlich ein Mädchen spurlos verschwunden ist. Aber Angela kann nicht in den See gelaufen sein. Denn Angela sitzt seit ihrer Geburt im Rollstuhl.', '10.05.2010', 'Arena', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('97789ad2-abac-5d9a-be46-44a04ff0d0be', :'owner', '5ddd1b64-390c-5c6c-bcec-9dbc1694d93f', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 999, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, NULL, NULL, 0, NULL, NULL) on conflict do nothing;
