insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aa4ff86d-230a-5bd4-8622-e7e7e77617eb', 'Das Tal - Die Katastrophe', NULL, '9783401064734', 'Mitten in den kanadischen Wäldern liegt das berühmte Grace-College, Ausbildungsschmiede für Hochbegabte. Doch seltsame Dinge gehen in dem abgeschlossenen Tal vor sich: Warum ist der Ort nicht auf Google Earth zu finden? Was hat es mit der Gruppe Jugendlicher auf sich, die Mitte der 70er in den Bergen verschwanden? Julia und ihre Clique sind ahnungslos, als sie ihr erstes College-Jahr beginnen. Doch sie werden bald herausfinden, dass im Tal nichts ist, wie es scheint. Und dass sie alle nicht ganz zufällig an diesem Ort sind. Katie hat nur ein Ziel. Den Gipfel des Ghosts, jenes legendären Dreitausenders, der das Tal überragt. Unheimliche Mythen ranken sich um den Berg, seit dort in den 70er Jahren eine Gruppe von Jugendlichen verschwunden ist. Und doch machen sich Katie und ihre Freunde auf den Weg. Aber am Berg wird sehr schnell klar, wer zum Freund wird, wer ein Feind ist. Und als dann noch ihre Führerin, die Cree-Indianerin Ana, spurlos verschwindet, sind die College-Studenten völlig auf sich gestellt. Niemand von ihnen ahnt, dass ein gefährlicher Schneesturm heraufzieht.', '01.08.2010', 'Arena', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '2', '{}', 'sheet', :'owner') on conflict do nothing;
