insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f3699268-e632-593a-a56e-eccb2e4b66af', 'Das Tal - Der Sturm', NULL, '9783401065311', 'Remembrance Day! Ein Tag mit einer besonderen Bedeutung für Chris. Und nichts wünscht er sich sehnlicher, als mit Julia über den Feiertag aus dem Tal zu verschwinden, wie die anderen Studenten auch. Doch als sie endlich aufbrechen wollen, zieht ein Jahrhundertsturm auf. Chris, Julia, Debbie, Rose und Benjamin werden von der Außenwelt abgeschnitten. Aber im verlassenen College geht es nicht mit rechten Dingen zu. Wohin ist der Sicherheitsbeamte Ted verschwunden? Warum verhält sich Debbie so seltsam? Und wer spielt ihnen die DVD mit Bildern in die Hände, die direkt in die Vergangenheit des Tals führen? Während der Sturm seinen Höhepunkt erreicht, wird Chris klar, dass ein Unbekannter ein perfides Spiel mit ihnen treibt. Die Frage ist nur, wer ist es und auf wen hat er es abgesehen?', '01.11.2010', 'Arena', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '3', '{}', 'sheet', :'owner') on conflict do nothing;
