insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('403652a8-a446-5a3e-9943-df1d876a94da', 'Das Tal - Die Prophezeiung', NULL, '9783401065328', 'Es ist Prüfungszeit am Grace College - und ausgerechnet jetzt verschwindet Ben, für drei lange Tage. Als er ins College zurückkehrt, ist er kaum wiederzuerkennen. Was immer ihn auf diesen Horrortrip gebracht hat, jetzt schwebt er in Lebensgefahr. Hat Ben etwas über die Vergangenheit des Tals herausgefunden, was ihm nun gefährlich wird? Die einzige Möglichkeit, sein Leben zu retten und das Geheimnis endgültig zu lüften, ist, Benjamins Spur zu folgen. Katie, Robert und David machen sich auf den Weg in die Berge und ahnen nicht, was für ein unfassbarer Fund sie erwartet.', '01.02.2011', 'Arena', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '4', '{}', 'sheet', :'owner') on conflict do nothing;
