insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c2efd1d7-0108-5bde-868b-757a88831335', 'd3f183fb-3441-5861-a2f1-960a294ee171', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e257052f-d2c1-539c-8499-841b331b94ea', 'Das Tal - Der Fluch', NULL, '9783401066073', 'Das Tal ist zur Ruhe gekommen. So scheint es zumindest. Nur Robert ist der Einzige, der der Wahrheit über den versteckten Ort mitten in den Rocky Mountains ein Stück nähergekommen ist. Doch während er verzweifelt versucht, seine Erkenntnisse zu überprüfen, gerät Rose in große Gefahr. Wer ist der Unbekannte, der ständig in ihr Zimmer im College einbricht? Und was hat das mit Roses Vergangenheit zu tun? Während das sonst so ruhige Mädchen mehr und mehr außer sich gerät, entdeckt Robert das Unfassbare...', '01.11.2011', 'Arena', ARRAY['Deutsch']::text[], 248, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '5', '{}', 'sheet', :'owner') on conflict do nothing;
