insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8e66f5e2-2de1-52df-9ad8-b2aadcbd33e7', 'Das Tal - Das Erbe', NULL, '9783401066103', 'Es ist Prüfungszeit am Grace College und Rose, Chris, Katie und die anderen haben beschlossen, die Geheimnisse des Tals für ein paar Tage ruhen zu lassen. Aber während die Studenten gerade über der Englischklausur brüten, passiert das Unfassbare. Einer ihrer Kommilitonen dreht völlig durch. Er droht, sie alle zu töten. Während der Sicherheitsdienst das Collegegebäude räumt, um die anderen Studenten in Sicherheit zu bringen, versuchen Rose, Katie, Debbie und Chris vergeblich, den Amokläufer zu beruhigen. Doch der will nur mit einem sprechen. Mit David. Und der ist spurlos verschwunden ...', '01.04.2012', 'Arena', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '6', '{}', 'sheet', :'owner') on conflict do nothing;
