insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6f26a93-9218-568c-b035-7100df268f41', 'Das Tal - Die Jagd', NULL, '9783401066332', 'Das Tal liegt düster zwischen den Berghängen der Rocky Mountains. Ben und die anderen Studenten am Grace College, die seit zwei Jahren merkwürdigen und unerklärlichen Ereignissen ausgesetzt sind, scheinen am Ende ihrer Kräfte. Wer spielt dieses geheimnisvolle und tödliche Spiel mit ihnen? Und was haben ihre Eltern und Großeltern mit der Vergangenheit des Tals zu tun? Während sich überall auf der Welt die Katastrophen häufen, stoßen die acht Studenten endlich auf das Geheimnis. Nun müssen sie ihr ureigenes Erbe antreten. Doch sie kämpfen gegen die Zeit.', '01.05.2013', 'Arena', ARRAY['Deutsch']::text[], 264, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, 'Grace-College', '{}', ARRAY['Chris','Julia','Debbie','Rose','Benjamin','Katie','Robert','David']::text[], '{}', '{}', '84a61edf-701b-5dd7-8b18-289e927b8bed', '7', '{}', 'sheet', :'owner') on conflict do nothing;
