insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('62ffafa0-6498-5377-809d-478b11755535', 'Kein Rockstar für eine Nacht', 'Rockstars', '9783736317888', 'Am Morgen nach ihrem einundzwanzigsten Geburtstag wacht Evelyn Thomas in einem Hotelzimmer in Las Vegas auf - neben einem attraktiven, tätowierten und leider vollkommen fremden jungen Mann. Sein Name ist David Ferris, er ist Gitarrist und Songwriter der erfolgreichen Rockband Stage Dive - und seit weniger als zwölf Stunden Evelyns rechtmäßig angetrauter Ehemann ...', '27.05.2022', 'LYX', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Evelyn Thomas','David Ferris']::text[], '{}', '{}', '2119315b-f05b-5753-9cbd-9d547340b231', '1', '{}', 'sheet', :'owner') on conflict do nothing;
