insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9d899b26-c047-5a46-ad02-6ae819e8e9f6', 'Rockstars bleiben nicht für immer', 'Lead', '9783736300033', 'Partys, Alkohol und Frauen - Jimmy, der charismatische Sänger der Rockband "Stage Dive", bekommt stets, was er will. Doch als er es mit seinem Lebenstil zu weit treibt und sich in einer Entzugsklinik wiederfindet, wird ihm die hübsche Lena als Assistentin zugeteilt. Sie soll aufpassen, dass er nicht noch einmal über die Stränge schlägt, und ist fest entschlossen, dem sexy Charme ihres Bosses zu widerstehen. Doch das heiße Prickeln zwischen ihr und Jimmy lässt sich schon bald nicht mehr ignorieren.', '01.10.2015', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jimmy','Lena']::text[], '{}', '{}', '2119315b-f05b-5753-9cbd-9d547340b231', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
