insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2a5ea68f-6bfb-544a-ab22-4cd2c842b659', 'Rockstars küsst man nicht', 'Deep', '9783736301511', 'Schwanger! Und das ausgerechnet von Ben Nicholson, dem Bassisten der erfolgreichsten Rockband der Welt! Lizzy Rollins kann es nicht fassen. Schon lange hegt sie tiefe Gefühle für den attraktiven Rockstar, aber sie weiß, dass Ben keine feste Beziehung sucht. Ihre gemeinsame Nacht in Las Vegas war für ihn nur ein One-Night-Stand, nichts weiter. Nur gibt es da nun eine neue, viel tiefere Verbindung zwischen ihnen. Doch ist diese stark genug, Bens Mauern zu durchbrechen?', '07.04.2016', 'LYX', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Ben Nicholson','Lizzy Rollins']::text[], '{}', '{}', '2119315b-f05b-5753-9cbd-9d547340b231', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
