insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17d31b63-0bed-5796-babb-a631c18e5226', 'Perfect Mistake', 'It seemed like a goood idea at the time', '9783736309845', 'Als Adele für die Hochzeit ihres Vaters in ihre Heimatstadt zurückkehrt, weiß sie, dass es kein einfacher Besuch werden wird. Sieben Jahre ist es her, dass sie fortging. Sieben Jahre, seit sie den größten Fehler ihres Lebens begangen hat. Nun muss sie dem Mann gegenübertreten, der ihr damals die Welt bedeutet hat. Augenblicklich kommen die Gefühle wieder hoch, noch intensiver und heftiger als zuvor. Doch eine Liebe zwischen ihnen ist unmöglich ... oder?', '31.07.2019', 'LYX', ARRAY['Deutsch']::text[], 303, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Adele']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
