insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f91cde36-e0a5-58ae-a7d3-95790c22b3fb', 'Wer will schon einen Rockstar?', 'Play', '9783736317895', 'Anne Rollins hat den schlimmsten Tag ihres Lebens hinter sich: Ihre Mitbewohnerin ist aus der gemeinsamen Wohnung verschwunden - mit allen Möbeln und ohne ihre Mietschulden zu begleichen. Um sich abzulenken, beschließt Anne kurzerhand, eine Freundin auf eine Party zu begleiten. Doch dort steht sie plötzlich niemand anderem gegenüber als Malcolm Ericson, dem Drummer der weltberühmten Rockband Stage Dive. Als dieser von Annes Problemen erfährt, macht er ihr ein Angebot, das verrückter nicht sein könnte: Er hilft ihr aus ihrer finanziellen Notlage, wenn sie im Gegenzug eine Zeit lang seine Freundin spielt ...', '30.09.2022', 'LYX', ARRAY['Deutsch']::text[], 365, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Anne Rollins','Malcolm Ericson']::text[], '{}', '{}', '2119315b-f05b-5753-9cbd-9d547340b231', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
