insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('72ea7e11-5f5d-503e-94c0-b4418a4795d6', 'Thorn Princess', NULL, NULL, 'After Hallie lands in hot water with the tabloids again, her father issues an ultimatum: be cut off from the family fortune or agree to a live-in bodyguard. Not one to have the credit card cut up again, Hallie reluctantly agrees. Enter sexy, brooding Ransom Lockwood . . . He is cold and rude but after spending time with Hallie, something begins to light up inside him. Neither believe the other can change. But as they get to know each other it becomes clear that Hallie isn''t the only one in need of protecting. And that romance can blossom in the most unlikely of places .', '26.07.2024', 'Penguin Random House', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, NULL, 'Los Angeles', '{}', ARRAY['Hallie Thorne','Ransom Lockwood']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
