insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2173f697-94ec-5b65-ae04-9c585c074658', 'All Saints High - Die Prinzessin', 'Pretty Reckless', '9783736311435', 'Daria Followhill ist reich, wunderschön und das beliebteste Mädchen der All Saints High. Sie müsste sich wie eine Prinzessin fühlen. Doch ihr Leben ist alles andere als perfekt. Seit sie vor vier Jahren aus Eifersucht die Zukunft der gleichaltrigen Silvia Scully zerstört hat, plagen sie schlimme Schuldgefühle. Als sie nun erfährt, dass Silvias Zwillingsbruder Penn nach dem Tod seiner Mutter kein Zuhause mehr hat, sorgt sie kurzerhand dafür, dass ihre Eltern Penn bei sich aufnehmen. Und obwohl er keinen Zweifel daran lässt, dass er Daria hasst, ist sie machtlos gegen das heftige Kribbeln zwischen ihnen. Dabei weiß sie, dass seine Liebe sie zerstören könnte ...', '27.03.2020', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'All Saints High', '{}', ARRAY['Daria Followhill','Penn']::text[], '{}', '{}', '226d7c90-b150-57b6-b84d-2dbd0ea673bc', '1', '{}', 'sheet', :'owner') on conflict do nothing;
