insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9176c147-8844-5b32-bf81-517bf0f5526a', 'Cruel Castaways - Rival', 'Ruthless Rival', '9783736318496', 'Christian Miller hat sich als rücksichtsloser Anwalt in New York einen Namen gemacht. Der Selfmade-Millionär hat nur ein Ziel: endlich Rache an Hedgefonds-Tycoon Philipp Roth nehmen, der Christians Leben zerstörte, weil er als Teenager dessen Tochter Arya küsste. Als eine Klientin Roth nun der sexuellen Belästigung beschuldigt, sieht Christian seine Chance gekommen. Nur eins steht ihm im Weg: seine Jugendliebe Arya, die als Pressesprecherin ihren Vater verteidigt. Arya weiß nicht, dass Christian der Junge von damals ist, doch er hat sie nie vergessen können. Als beide auf entgegengesetzten Seiten stehen, entflammen alte Gefühle. Und Christian muss sich entscheiden: Rache oder die große Liebe?', '23.12.2022', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Upper East Side', '{}', ARRAY['Christian Miller','Arya Roth']::text[], '{}', '{}', '30c258db-2be5-5891-82a6-4ac050269983', '1', '{}', 'sheet', :'owner') on conflict do nothing;
