insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8568edf7-6802-54f4-8c4d-683d19ba57e2', 'All Saints High - Die Verlorene', 'Broken Knight', '9783736311992', 'Als Lenora Astalis erfährt, dass Vaughn Spencer eines der begehrten Stipendien für die Kunst-Akademie ihres Vaters bekommen hat, sieht sie ihre Chance gekommen: Endlich kann sie sich dafür rächen, dass Vaughn ihr an der All Saints High das Leben zur Hölle gemacht hat. Doch es kommt ganz anders, denn Lenora soll Vaughns Assistentin werden und mit ihm zusammenarbeiten! Je besser sie das Künstler-Genie mit dem eiskalten Blick kennenlernt, desto deutlicher wird, dass sich hinter seiner grausamen Fassade mehr verbirgt als angenommen. Und bald kann Lenora das Prickeln, das sie schon immer in Vaughns Nähe gespürt hat, nicht mehr ignorieren ...', '21.12.2020', 'LYX', ARRAY['Deutsch']::text[], 463, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Lenora Astalis','Vaughn Spencer']::text[], '{}', '{}', '226d7c90-b150-57b6-b84d-2dbd0ea673bc', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
