insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a26c43d3-f043-589a-8623-5505dd4d4183', 'Cruel Castaways - Fallen', 'Fallen Foe', '9783736319295', 'Milliardär Arsène Corbin ist ein eiskalter und berechnender Geschäftsmann. Deshalb gerät er auch immer wieder mit der leidenschaftlichen Schauspielerin Winnifred Ashcroft aneinander, die die Hauptrolle in seinem Theaterstück spielt. Denn Winnie ist alles, was Arsène nicht ist - warmherzig und liebevoll. Dennoch können die beiden nicht leugnen, dass eine ganz besondere Verbindung zwischen ihnen besteht. Als schmerzhafte Geheimnisse aus der Vergangenheit ans Licht kommen, die zeigen, wie eng sie wirklich durch das Schicksal miteinander verbunden sind, müssen sie sich entscheiden: Ist trotz aller Unterschiede eine gemeinsame Zukunft möglich?', '29.09.2023', 'LYX', ARRAY['Deutsch']::text[], 445, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Arsène Corbin','Winnifred Ashcroft']::text[], '{}', '{}', '30c258db-2be5-5891-82a6-4ac050269983', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
