insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8fdd9f11-b248-5253-b5cb-4b874d0aa9ab', 'All Saints High - Der Rebell', 'Angry God', '9783736311954', 'Knight Cole und Luna Rexroth sind schon seit ihrer Kindheit beste Freunde, auch wenn sie völlig unterschiedlich sind. Knight ist Captain des Footballteams und der Star der Schule, Luna schüchtern, introvertiert und am liebsten für sich. Und dennoch fühlen sich die beiden, als wären sie zwei Teile eines Ganzen. Ohne den anderen sind sie einfach nicht vollständig. Aber genau dieses Gefühl hält sie davon ab, dem Knistern nachzugeben, das sie nun schon seit ein paar Jahren immer stärker spüren. Denn das Risiko, einander zu verlieren, ist mehr, als sie ertragen könnten ...', '28.07.2020', 'LYX', ARRAY['Deutsch']::text[], 456, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'All Saints High', '{}', ARRAY['Knight Cole','Luna Rexroth']::text[], '{}', '{}', '226d7c90-b150-57b6-b84d-2dbd0ea673bc', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
