insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f917a97d-cbdb-526d-b539-94e34de24cae', 'Fierce King - Empty Kingdom', NULL, '9783736324329', 'Tate King ist Chief of Marketing der millionenschweren King Group - und ein Playboy. Doch damit soll jetzt Schluss sein! Tate will seinen Ruf verbessern und seinen Brüdern beweisen, dass er sich verändert hat. Eine Fake-Beziehung soll die Lösung all seiner Probleme sein. Die perfekte Kandidatin ist ausgerechnet Violet Sinclair, die kleine Schwester seines ehemaligen College-Mitbewohners, die dringend Geld benötigt, um das Café ihres verstorbenen Vaters finanziell über Wasser zu halten. Dass Tate und sie sich zuvor in seinem exklusiven Club wiedergetroffen und sich dort als maskierte Fremde nähergekommen sind, versuchen sie hinter sich zu lassen - doch bald schon wird es unmöglich, der Anziehungskraft von damals zu widerstehen ...', '27.06.2025', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tate King','Violet Sinclair']::text[], ARRAY['Brother''s Best Friend','Enemies to Lovers','Forced Proximity','Fake Dating']::text[], '{}', 'ede3aab1-2b62-5827-853c-04878adefa53', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
