insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('183143a1-a73c-5e5d-8134-c958d3c2810a', 'Cold King - Empty Kingdom', 'Coldhearted King', '9783736323810', 'Cole King bekommt immer, was er will. Als COO der millionenschweren King Group mangelt es dem gut aussehenden Geschäftsmann an nichts - bis er Delilah kennenlernt. Die Frau mit den funkelnden grünen Augen löst Gefühle in Cole aus, die er so bisher nicht kannte. Sie verbringen eine leidenschaftliche Nacht miteinander, und auch wenn es eine einmalige Sache sein sollte, kann er Delilah einfach nicht vergessen. Und dann stehen sie sich plötzlich auf der Arbeit gegenüber! Denn Delilah ist Mitglied von Elite Architecture, einem Architekturteam, das gerade frisch von der King Group für ein Projekt engagiert wurde. Und obwohl sich Cole und Delilah vornehmen, professionell zu bleiben und ihren One-Night-Stand hinter sich zu lassen, dauert es nicht lange, bis die Erinnerungen an jene Nacht ihre guten Vorsätze ins Wanken bringen ...', '31.01.2025', 'LYX', ARRAY['Deutsch']::text[], 448, 46, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cole King','Delila']::text[], '{}', '{}', 'ede3aab1-2b62-5827-853c-04878adefa53', '1', '{}', 'sheet', :'owner') on conflict do nothing;
