insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('91a21110-6d9a-5cf4-9e82-6f78d07ae7ad', 'Love All Apartment', NULL, '9783770436378', 'Isumi sucht eigentlich nur etwas Ruhe, nachdem er sein altes Leben hinter sich gelassen hat und in ein neues Apartment gezogen ist. Doch genau diese Ruhe ?ndet er dort nicht – die Wände sind sehr dünn und jeden Morgen dringt lustvolles Stöhnen aus der Nachbarwohnung zu ihm herüber. Als er eines Tages auf seinen geräuschvollen Nachbarn trifft, wird die Begegnung unerwartet intensiv.', '04.08.2021', 'Egmont Manga', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Isumi']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
