insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ef42c41f-a8d9-5a04-b409-4a12b39bad2f', 'The Darlington - Ethan & Grace', NULL, '9783736324893', 'Nach einem schweren Schicksalsschlag ist Grace am Boden zerstört. Das Einzige, was sie noch aufrecht hält, ist der Wunsch nach Gerechtigkeit. Sie hegt den Verdacht, dass die Familie Darlington mehr über den Vorfall weiß, der ihr Leben für immer verändert hat, und ist wild entschlossen, der Sache nachzugehen. Doch ausgerechnet Ethan Darlington wird für Grace zur Ablenkung. Schon immer haben sich das Zimmermädchen und der arrogante Hotelerbe hitzige Wortgefechte geliefert, aber plötzlich ist da mehr zwischen ihnen: eine körperliche Anziehung, der Grace nicht widerstehen kann - und will. Aber so ganz kann sich Grace nicht auf Ethan einlassen, weil sie das Gefühl hat, dass er ihr etwas verschweigt.', '15.10.2025', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'London, The Darlington', '{}', ARRAY['Ethan','Grace']::text[], '{}', '{}', '61a6d488-2e6f-5ff3-b1de-0d84950e8e86', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
