insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8ef7d63a-a5d8-5eda-aa96-be7e6ebc0732', 'Berühre mich. Nicht.', NULL, '9783736305274', 'Als Sage in Nevada ankommt, besitzt sie nichts - kein Geld, keine Wohnung, keine Freunde. Nichts außer dem eisernen Willen, neu zu beginnen und das, was zu Hause geschehen ist, zu vergessen. Das ist allerdings schwer, wenn einen die Erinnerungen auf jedem Schritt begleiten und die Angst immer wieder über einen hereinbricht. So auch, als Sage ihren Job in einer Bibliothek antritt und dort auf Luca trifft. Mit seinen stechend grauen Augen und seinen Tätowierungen steht er für alles, wovor Sage sich fürchtet. Doch Luca ist nicht der, der er auf den ersten Blick zu sein scheint, und als es Sage gelingt, hinter seine Fassade zu blicken, lässt dies ihr Herz gefährlich schneller schlagen ...', '26.10.2017', 'LYX', ARRAY['Deutsch']::text[], 459, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', '{}', ARRAY['Sage','Luca']::text[], '{}', '{}', '51b34f1e-88f8-5a10-8cf4-8c6a597681f8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
