insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bc02d998-08af-5157-9883-8daa590e88b6', 'Someone New', NULL, '9783736308299', 'Als Micah auf ihren neuen Nachbarn trifft, kann sie es nicht glauben: Es ist ausgerechnet Julian, der wenige Wochen zuvor ihretwegen seinen Job verloren hat. Micah fühlt sich schrecklich, vor allem, weil Julian kühl und abweisend zu ihr ist und ihr nicht mal die Gelegenheit gibt, sich zu entschuldigen. Doch gleichzeitig fasziniert Micah seine undurchdringliche Art, und sie will ihn unbedingt näher kennenlernen. Dabei findet sie heraus, dass Julian nicht nur sie, sondern alle Menschen auf Abstand hält. Denn er hat ein Geheimnis, das die Art, wie sie ihn sieht, für immer verändern könnte ...', '28.01.2019', 'LYX', ARRAY['Deutsch']::text[], 550, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Micah','Julian']::text[], '{}', '{}', 'f0d27cdc-acc5-597c-9129-df399f8c3e51', '1', '{}', 'sheet', :'owner') on conflict do nothing;
