insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('886a175a-563b-5436-adfc-3541be14616d', 'Verliere mich. Nicht.', NULL, '9783736305496', 'Mit Luca war Sage glücklicher als je zuvor in ihrem Leben. Er hat ihr gezeigt, was es bedeutet, zu vertrauen. Zu leben. Und zu lieben. Doch dann hat Sage'' dunkle Vergangenheit sie eingeholt - und ihr Glück zerstört. Sage kann Luca nicht vergessen, auch wenn sie es noch so sehr versucht. Jeder Tag, den sie ohne ihn verbringt, fühlt sich an, als würde ein Teil ihrer selbst fehlen. Aber dann taucht Luca plötzlich vor ihrer Tür auf und bittet sie, zurückzukommen. Doch wie soll es für die beiden eine zweite Chance geben, wenn so viel zwischen ihnen steht?', '26.01.2018', 'LYX', ARRAY['Deutsch']::text[], 467, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', '{}', ARRAY['Sage','Luca']::text[], '{}', '{}', '51b34f1e-88f8-5a10-8cf4-8c6a597681f8', '2', '{}', 'sheet', :'owner') on conflict do nothing;
