insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5404df1a-68b9-587f-925e-bfa2aecdb555', 'Someone Else', NULL, '9783736311213', 'Eigentlich könnten Cassie und Auri das perfekte Paar sein: Sie sind beste Freunde, wohnen zusammen und teilen ihr größtes Hobby - die Fantasyliteratur. Und obwohl Cassie das Gefühl hat, dass niemand auf der Welt sie besser kennt als Auri, scheinen die beiden manchmal Welten zu trennen. Während Auri Football spielt, viele Bekanntschaften hat und gern unter Menschen geht, zieht Cassie sich lieber von der Außenwelt zurück und pflegt einen kleinen, aber engen Freundeskreis. Doch je mehr Zeit vergeht und je stärker ihre Gefühle für Auri werden, desto größer ist ihre Angst, dass das, was sie und Auri verbindet, vielleicht nicht so stark ist wie das, was sie trennt ...', '27.01.2020', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Cassie','Auri']::text[], '{}', '{}', 'f0d27cdc-acc5-597c-9129-df399f8c3e51', '2', '{}', 'sheet', :'owner') on conflict do nothing;
