insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('48468ecc-84ab-5eea-867a-a10d8bd9b179', 'Vergiss uns. Nicht.', NULL, '9783736318885', 'Sich zu verlieben ist Aprils größter Wunsch. Sie sehnt sich nach jemandem, der ihr Herz zum Flattern und ihren Bauch zum Kribbeln bringt. Der einzige Mann, der sie all das jemals hat fühlen lassen, ist Gavin Forster. Während er vor fünf Jahren noch ein wichtiger Teil ihres Lebens war, ist heute von ihrer Freundschaft nur noch Wut und Schmerz übrig. Eigentlich hätte April ihn längst vergessen sollen, aber das ist leichter gesagt als getan, schließlich ist Gavin immer noch der beste Freund ihres Bruders. Doch als Gavins Vergangenheit droht, ihn einzuholen, kann April nicht anders, als ihm zu helfen. Auch wenn sie weiß, dass sie ihr Herz dadurch erneut in Gefahr bringt ...', '22.03.2023', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', '{}', ARRAY['Aprils','Gavin Forster']::text[], '{}', '{}', '51b34f1e-88f8-5a10-8cf4-8c6a597681f8', '3', '{}', 'sheet', :'owner') on conflict do nothing;
