insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('36d67499-90c4-525c-9141-0965aea6b981', 'Someone to Stay', NULL, '9783736314528', 'Aliza weiß nicht, wo ihr der Kopf steht. Nicht nur versucht sie, ihr Jurastudium durchzuziehen, sie hat auch mit ihrem erfolgreichen Instagram-Account alle Hände voll zu tun, und ihr erstes Kochbuch steht kurz vor der Veröffentlichung. Da kann sie sich keine Ablenkung erlauben - selbst dann nicht, wenn sie so attraktiv und faszinierend ist wie Lucien. Doch obwohl Aliza fest entschlossen ist, das heftige Prickeln zwischen ihnen zu ignorieren, fällt es ihr immer schwerer, sich von Lucien fernzuhalten. Dabei hat dieser seine ganz eigenen Gründe, warum die Liebe für ihn zurzeit an letzter Stelle steht ...', '16.10.2020', 'LYX', ARRAY['Deutsch']::text[], 422, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Aliza','Lucien']::text[], '{}', '{}', 'f0d27cdc-acc5-597c-9129-df399f8c3e51', '3', '{}', 'sheet', :'owner') on conflict do nothing;
