insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4759f90c-0422-5c76-af4d-afd0b5467dc4', 'Zerbrich uns. Nicht.', NULL, '9783736319332', 'Nach fünf Jahren ist Gavin plötzlich zurück in Aprils Leben. Damals war er der Junge, an den sie ihr Herz verlor, heute ist er der Mann, dem sie es ein zweites Mal geschenkt hat. April glaubte, mit Gavin endlich die Liebe gefunden zu haben, nach der sie sich sehnte. Doch was so perfekt schien, endete für sie erneut in Liebeskummer. Ihr bleibt keine andere Wahl, als ihre Gefühle für Gavin endgültig zu vergessen. Das ist allerdings gar nicht so leicht, denn unerwartet müssen die beiden für ein Projekt zusammenarbeiten, und Gavins Anblick lässt Aprils verräterisches Herz immer noch viel zu schnell schlagen. Nur wie kann sie ihm verzeihen, wenn sie ihm nicht mehr vertraut?', '28.06.2023', 'LYX', ARRAY['Deutsch']::text[], 469, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', '{}', ARRAY['Aprils','Gavin Forster']::text[], '{}', '{}', '51b34f1e-88f8-5a10-8cf4-8c6a597681f8', '4', '{}', 'sheet', :'owner') on conflict do nothing;
