insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('39ae9a56-7de3-5dc0-b14f-2f5ab59aaae9', 'Verliebe dich. Nicht.', NULL, '9783736321069', 'Die 21-jährige Megan lebt für ihre Kunst. Der erhoffte Erfolg bleibt jedoch aus und sie wird von ihren Eltern vor die Wahl gestellt: Entweder sie studiert oder sie streichen ihr die Unterstützung. Megan entscheidet sich für ihre Kunst und zieht kurzerhand nach Melview, um dort ihren Traum zu verwirklichen. Aber das ist leichter gesagt als getan, denn sie braucht dringend einen Job. Doch als ihr angeboten wird, als Barista im Le Petit zu arbeiten, zögert sie. Grund dafür ist Cameron, der attraktive Cafébesitzer, auf den sie schon lange ein Auge geworfen hat. Allerdings hat Cam sie bei ihrem letzten Treffen eiskalt abblitzen lassen ...', '12.12.2023', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', '{}', ARRAY['Megan','Cameron']::text[], '{}', '{}', '51b34f1e-88f8-5a10-8cf4-8c6a597681f8', '5', '{}', 'sheet', :'owner') on conflict do nothing;
