insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('23138790-ea3f-532b-8218-3c6748feab23', 'Herz aus Schatten', NULL, '9783736318304', 'Kayla hat ihre Angst bezwungen! Sie hat einen Schattenwolf gezähmt, der nun an sie gebunden ist. Als Bändigerin ist es ihre Aufgabe, die Stadt Praha mithilfe ihres Monsters gegen die dunklen Kreaturen zu verteidigen, die jenseits der Stadtmauer in den Wäldern lauern und nach dem Blut der letzten verbliebenen Menschen gieren. Doch dann geschieht das Unfassbare: Ihr Schattenwolf verwandelt sich in einen jungen Mann! Einen attraktiven, eindeutig menschlichen Mann, der sich nicht an seine Vergangenheit erinnern kann - und den die Dunkelheit immer wieder einzuholen droht ...', '28.01.2022', 'LYX', ARRAY['Deutsch']::text[], 472, 45, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Vergangenheit'::time_period, 'Praha', '{}', ARRAY['Kayla']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
