insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c3e9e898-55d5-5208-ac07-c8d022343cb1', 'The Darlington - Henry & Kate', NULL, '9783736323551', 'Kate hat alles verloren: ihre Familie, ihren Job, ihr Zuhause. Seit Monaten schlägt sie sich allein auf der Straße durch. Als sie eines Tages den attraktiven Henry bestiehlt, ahnt sie nicht, dass sich ihr Leben für immer verändern wird. Seiner Familie gehört das luxuriöseste Hotel ganz Londons - The Darlington. Das Hotel ist durch einen Skandal jedoch in Verruf geraten, und als ältester Sohn ist es Henrys Aufgabe, das gute Image wiederherzustellen. Und obwohl Henry und Kate nicht unterschiedlicher sein könnten, lädt er sie zu sich ins The Darlington ein. Dort angekommen lernt Kate nicht nur eine völlig neue Welt, sondern auch Henry besser kennen, der ungeahnte Gefühle in ihr weckt.', '07.07.2025', 'LYX', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'London, The Darlington', '{}', ARRAY['Kate','Henry']::text[], '{}', '{}', '61a6d488-2e6f-5ff3-b1de-0d84950e8e86', '1', '{}', 'sheet', :'owner') on conflict do nothing;
