insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('db2b277c-7ff0-5a2f-b4b9-b68f9cba5c16', 'Berühre mich. Nicht. (GN Vol. 1)', NULL, '9783736319394', 'Als Sage in Nevada ankommt, besitzt sie nichts - kein Geld, keine Wohnung, keine Freunde. Nichts außer dem eisernen Willen, neu zu beginnen und das, was zu Hause geschehen ist, zu vergessen. Das ist allerdings schwer, wenn einen die Erinnerungen auf jedem Schritt begleiten und die Angst immer wieder über einen hereinbricht. So auch, als Sage ihren Job in einer Bibliothek antritt und dort auf Luca trifft. Mit seinen stechend grauen Augen und seinen Tätowierungen steht er für alles, wovor Sage sich fürchtet. Doch Luca ist nicht der, der er auf den ersten Blick zu sein scheint. Und als es Sage gelingt, hinter seine Fassade zu blicken, lässt das ihr Herz gefährlich schneller schlagen ...', '26.01.2024', 'LYX', ARRAY['Deutsch']::text[], 201, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', ARRAY['3P Objective']::text[], ARRAY['Sage','Luca']::text[], ARRAY['Second Chance','Friends to Lovers']::text[], ARRAY['Depiction of Trauma','Sexuelle Gewalt','Häusliche Gewalt']::text[], '45546e1a-d05c-555f-8d8b-40fc380e1f92', '1', '{}', 'sheet', :'owner') on conflict do nothing;
