insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('540f03e2-cf4a-5dcc-b9bd-d4fe5dfcb96a', '1c688e8c-5370-5414-8467-4f605c2a0326', :'owner', 1, '2024-04-18', '2024-04-19', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cdef3713-faf7-507a-82e2-24ee39c98421', 'Verliere mich. Nicht. (Vol.4)', NULL, '9783736325074', 'Die Trennung von Luca hat Sages Herz in tausend Stücke gebrochen. Doch dann stand er plötzlich vor ihr und bat sie, wieder bei ihm einzuziehen. Luca jeden Tag zu sehen und zu versuchen, nur mit ihm befreundet zu sein, ist jedoch alles andere als leicht. Seine Blicke lassen Sages Herz noch immer schneller schlagen. Und seine Berührungen bringen ihre Haut nach wie vor zum Kribbeln. Aber sie können nicht zusammen sein - ausgeschlossen. Das Risko, dass Luca von ihrem Geheimnis erfährt, ist zu groß. Als Sages dunkle Vergangenheit an die Tür klopft, ist es allerdings unmöglich, ihm die Wahrheit noch länger zu verschweigen. Hat ihre Liebe trotz allem eine zweite Chance?', '02.02.2026', 'LYX', ARRAY['Deutsch']::text[], 208, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', ARRAY['3P Objective']::text[], ARRAY['Sage','Luca']::text[], ARRAY['Second Chance','Friends to Lovers']::text[], ARRAY['Depiction of Trauma','Sexuelle Gewalt','Häusliche Gewalt']::text[], '45546e1a-d05c-555f-8d8b-40fc380e1f92', '4', '{}', 'sheet', :'owner') on conflict do nothing;
