insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b6d151e7-f315-504b-9d7d-a34fd61dcdf5', '13ec5329-dbc1-521e-97a6-5ef9f2569b20', :'owner', 1, '2026-06-14', '2026-06-14', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9dc41771-9842-5607-a7e8-3d5a4ddb7df5', 'Verliere mich. Nicht. (GN Vol. 3)', NULL, '9783736322233', 'Sie fürchtet sich vor der Liebe. Doch noch mehr fürchtet sie, ihn zu verlieren ... Mit Luca war Sage glücklicher als je zuvor in ihrem Leben. Er hat ihr gezeigt, was es bedeutet, zu vertrauen. Zu leben. Und zu lieben. Doch dann hat Sages dunkle Vergangenheit sie eingeholt - und ihr Glück zerstört. Sage kann Luca nicht vergessen, auch wenn sie es noch so sehr versucht. Jeder Tag, den sie ohne ihn verbringt, fühlt sich an, als würde ein Teil ihrer selbst fehlen. Aber dann taucht Luca plötzlich vor ihrer Tür auf und bittet sie, zurückzukommen. Doch wie soll es für die beiden eine zweite Chance geben, wenn so viel zwischen ihnen steht?', '29.11.2024', 'LYX', ARRAY['Deutsch']::text[], 206, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Nevada, Melview', ARRAY['3P Objective']::text[], ARRAY['Sage','Luca']::text[], ARRAY['Second Chance','Friends to Lovers']::text[], ARRAY['Depiction of Trauma','Sexuelle Gewalt','Häusliche Gewalt']::text[], '45546e1a-d05c-555f-8d8b-40fc380e1f92', '3', '{}', 'sheet', :'owner') on conflict do nothing;
