insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('68292d40-8f30-5f07-bf34-c6c43958d056', 'f4438b0b-9c9e-5a81-8b5d-1a5673a16ea4', :'owner', 1, '2025-07-08', '2025-07-08', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('50b35c0c-c715-5033-baa4-c0742f7ef713', 'Ash Princess', NULL, '9781509855209', 'Theodosia was six when her country was invaded and her mother, the Fire Queen, was murdered before her eyes. On that day, the Kaiser took Theodosia''s family, her land, and her name. Theo was crowned Ash Princess--a title of shame to bear in her new life as a prisoner. For ten years Theo has been a captive in her own palace. She''s endured the relentless abuse and ridicule of the Kaiser and his court. She is powerless, surviving in her new world only by burying the girl she was deep inside. Then, one night, the Kaiser forces her to do the unthinkable. With blood on her hands and all hope of reclaiming her throne lost, she realizes that surviving is no longer enough. But she does have a weapon: her mind is sharper than any sword. And power isn''t always won on the battlefield. For ten years, the Ash Princess has seen her land pillaged and her people enslaved. That all ends here.', '24.09.2018', 'Macmillan', ARRAY['Englisch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', ARRAY['Theo']::text[], '{}', '{}', '1bba949e-fa2c-5e41-8979-c398778fd9a5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
