insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9b4573cf-6c8c-5c2a-9a1b-17c3b8bbe275', 'The Fine Print', NULL, '9780349433448', 'Rowan: I''m in the business of creating fairy tales. Theme parks. Production companies. Five-star hotels. Everything could be all mine if I renovated Dreamland. My initial idea of hiring Zahra was good in theory, but then I kissed her. Things spiraled out of control once I texted her using an alias. By the time I realized where I went wrong, it was too late. People like me don''t get happy endings. Not when we''re destined to ruin them. Zahra: After submitting a drunk proposal criticizing Dreamland''s most expensive ride, I should have been fired. Instead, Rowan Kane offered me a dream job. The catch? I had to work for the most difficult boss I''d ever met. Rowan was rude and completely off-limits, but my heart didn''t care. At least not until I discovered his secret. It was time to teach the billionaire that money couldn''t fix everything. Especially not us.', '27.01.2022', 'Piatkus', ARRAY['Englisch']::text[], 434, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Dreamland', '{}', ARRAY['Zahra','Rowan Kane']::text[], '{}', '{}', '16e22e7b-e23a-5ded-a500-666375581bc5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
