insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c793051c-6d1d-5d9d-9e84-e3087b3482ec', '291eb501-f8c2-519e-8b8b-5a934f7c4463', :'owner', 1, '2023-08-07', '2023-08-08', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6f255a1f-d4a5-5e8c-b362-2d8d9ce4ab2c', 'Throttled', NULL, '9781734258769', 'Noah: Maya Alatorre is the sister of my teammate…and my new obsession. Keeping my distance during the Formula 1 season should be easy, except I always find ways to see her. Press tours. Pre-race rituals. Sponsor events and black-tie galas.The more time we spend together, the stronger my desire grows. Sneaking around with her is one thing, but wanting more? Never going to happen. She might be a distraction dressed like a daydream, but no woman is worth risking the championship title over. Or so I thought. Maya: Noah Slade is Formula 1 royalty and my brother’s biggest rival. When I’m invited to join my sibling while he competes for the World Championship, I promise to avoid Noah at all costs. Twenty-one races. Two drivers who hate each other. And one forbidden attraction I can’t ignore. Developing feelings for Noah wasn’t part of my plan. But then again, neither was anyone finding out. Turns out the man I was warned about happens to be the one I can’t stay away from. Even if he breaks my heart once the season comes to an end.', '09.01.2020', NULL, ARRAY['Englisch']::text[], 457, 44, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Maya Altorre','Noah Slade']::text[], ARRAY['Sport']::text[], '{}', '2aecc643-def4-5b21-92b6-efdcadf3b07f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
