insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('467f5b99-f2b2-57ff-a859-0698b22b145d', 'effb7e77-c73f-5b5f-a223-0217ddae9019', :'owner', 1, '2023-08-23', '2023-09-03', NULL, NULL, 12, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a0fc4bd5-a61e-5bd4-bcf2-a40ecf842fa6', 'Final Offer', NULL, '9780349433479', 'Callahan: I''m the Kane brother everyone gossips about behind closed doors. Trust fund brat. Washed-up athlete. High-functioning alcoholic. No one knows the real me but her. Lana Castillo—my childhood best friend and the only woman I ever loved. When I broke her heart six years ago, I promised to never return to Lake Wisteria. I kept my word until my grandfather''s will changed everything. To receive my inheritance, I was tasked with spending a summer at the family lake house before selling it. The request was simple in theory until my entire plan blew up on the very first day. Turns out Lana doesn''t just live at the house, but she claims to own it, too. Alana: Falling in love with Callahan Kane was a mistake. He told me so before destroying my heart and our friendship six summers ago. When he promised never to come back, I foolishly believed him. But then Cal showed up again, intending to sell his grandfather''s lake house. The biggest flaw in his plan? My name is on the deed.', '31.01.2023', 'Piatkus', ARRAY['Englisch']::text[], 577, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Lake Wisteria', '{}', ARRAY['Alana Castillo','Callahan Kane']::text[], '{}', '{}', '16e22e7b-e23a-5ded-a500-666375581bc5', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
