insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f857dc98-1b56-588a-92c5-4b8a775b175c', 'Das böse Spiel der Natalie Hargrove', 'The Betrayal of Natalie Hargrove', NULL, 'Natalie Hargrove hat es geschafft: Wenn sie und ihr Freund Mike King in wenigen Tagen zum Prinzenpaar ihrer Schule gewählt werden, dann gehört sie endgültig zur Crème de la Crème der Stadt – und keiner ahnt, dass sie in Wahrheit aus der Trailersiedlung jenseits der Stadtgrenze stammt. Keiner außer Justin Balmer – dem einzigen, der Mike den Ruhm streitig machen kann. Um sicherzustellen, dass Mike und nicht etwa Justin zum Prinz gekürt wird, beschließt Natalie, Justin einen fiesen Trick zu spielen. Doch was nicht mehr als ein böses Spiel hatte sein sollen, nimmt einen unerwartet tragischen Verlauf: Justin stirbt, und Natalie versucht verzweifelt, die Wahrheit zu kaschieren …', '09.07.2012', 'cbt', ARRAY['Deutsch']::text[], 288, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], NULL, NULL, NULL, '{}', ARRAY['Natalie Hargrove']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
