insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5e1236d1-923e-5105-b8f9-1852a35775c8', 'Engelsnacht', 'Fallen', '9783641048785', 'Lucinda ist 17 und den ersten Tag auf dem Internat, als sie ihn sieht: Daniel Grigori, den unglaublich attraktiven Jungen, von dem sie sicher ist, dass sie ihm schon einmal begegnet ist. Daniel jedoch behauptet, sie nicht zu kennen – er scheint sie sogar zu hassen und weicht ihr aus, wo immer er kann. Doch immer wenn Luce etwas Schlimmes widerfährt, ist er zur Stelle. Mehrfach rettet er ihr Leben. Allmählich kommen die beiden sich näher, und da erst erfährt Luce, welches Geheimnis sie beide umgibt: Daniel ist ein gefallener Engel, dazu verdammt, für immer auf der Erde umherzuwandern. Luce aber ist dazu verdammt, alle siebzehn Jahre wiedergeboren zu werden, sich jedes Mal aufs Neue unsterblich in Daniel zu verlieben – und den Tod zu finden, sobald sie sich näherkommen …', '16.08.2010', 'cbt', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Shoreline', '{}', ARRAY['Lucinda','Daniel']::text[], '{}', '{}', '98142ce8-e8de-5eb7-9742-723ca5ca63b2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
