insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('fa1b2831-7c8d-52fa-86da-c8c926c87462', :'owner', '5e1236d1-923e-5105-b8f9-1852a35775c8', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, true, false, '{}', '{}', NULL, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e09a71dd-8506-593b-bd2e-5d62fb0ddc57', 'Teardrop', NULL, '9783641124403', '»Vergieße nie eine einzige Träne!« Dieses Versprechen musste Eureka ihrer Mutter geben und siebzehn Jahre lang hat sie sich daran gehalten. Selbst als ihre Mutter bei einem Autounfall starb. Doch dann trifft sie Ander, einen attraktiven und äußerst mysteriösen Jungen. Er bringt sie so durcheinander, dass sie eine Träne vergießt – und Ander fängt sie mit seiner Fingerspitze auf. Auch er scheint zu wissen, dass Eureka nicht weinen darf. Doch was ist ihr großes Geheimnis? Warum wissen alle anderen davon, nur sie nicht? Und warum verhält sich ihr bester Freund, Brooks, plötzlich so aggressiv ihr gegenüber? Waren sie nicht kurz davor, ein Paar zu werden? Wem kann Eureka noch vertrauen?', '25.08.2014', 'cbt', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Eurekas']::text[], '{}', '{}', 'ade5accc-51b1-5863-9c21-178346fc93af', '1', '{}', 'sheet', :'owner') on conflict do nothing;
