insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7aaffe2-ed6b-50a1-acb5-89a418f80fdb', 'Engelsmorgen', 'Torment', '9783641056629', 'Die Hölle auf Erden ist für Luce, von ihrer großen Liebe, dem gefallenen Engel Daniel, getrennt zu sein. Seit einer Ewigkeit suchten sie nacheinander, und nun, da sie sich endlich gefunden haben, muss Daniel die Unsterblichen bekämpfen, die Luce töten wollen. Daniel versteckt Luce in Shoreline, einem Internat in Kalifornien. Dort lernt Luce, die furchterregenden Schatten, die sie seit frühester Kindheit umgeben, zu kontrollieren und mit ihrer Hilfe in die Vergangenheit zu blicken. Doch je mehr Luce dadurch über ihre und Daniels frühere Leben erfährt, desto mehr ahnt sie, dass er ihr etwas verschweigt – etwas Wichtiges und Gefährliches ...', '12.09.2011', 'cbt', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Shoreline', '{}', ARRAY['Lucinda','Daniel']::text[], '{}', '{}', '98142ce8-e8de-5eb7-9742-723ca5ca63b2', '2', '{}', 'sheet', :'owner') on conflict do nothing;
