insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b378e823-dc34-5981-bd7e-52e331475e22', 'Waterfall', NULL, '9783641153366', 'Dank Eurekas Tränen hat sich der verlorene Kontinent Atlantis aus der Versenkung erhoben – und mit ihm sein durch und durch böser Herrscher, König Atlas. Jetzt ist Eureka die Einzige, die die Welt vor Tod und Zerstörung retten kann. Zusammen mit dem mysteriösen Ander macht sie sich auf eine atemberaubende Reise, um Solon zu finden – jenen rätselhaften, verschollenen Saathüter, der alle Antworten auf ihre Fragen kennt. Da kommt Eureka hinter ein Geheimnis, das sie vor eine folgenschwere Entscheidung stellt: Ist sie bereit, für den Sieg über Atlas alles aufzugeben – auch die Liebe?', '24.08.2015', 'cbt', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Eurekas']::text[], '{}', '{}', 'ade5accc-51b1-5863-9c21-178346fc93af', '2', '{}', 'sheet', :'owner') on conflict do nothing;
