insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c9f03abd-347c-5de1-ab8a-8453b9b32038', 'Engelsflammen', 'Passion', '9783641079840', 'Luce würde für Daniel sterben. Und sie hat es getan, immer wieder: Seit einer Ewigkeit finden die beiden einander, nur um sich wieder zu verlieren. Luce weiß, dass in ihrer Vergangenheit der Schlüssel liegt, um den Fluch zu brechen. Sie reist zurück in der Zeit, um einen Weg aus der Verdammnis zu finden. Cam, die gefallenen Engel, Luces‘ Freunde Miles und Shelby, sie alle brechen auf, um Luce in der Vergangenheit zu suchen. Doch keiner sucht sie so verzweifelt wie Daniel – voller Angst, Luce könnte die Geschichte neu schreiben. Dann könnte ihre große Liebe in Flammen aufgehen … für immer.', '23.07.2012', 'cbt', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Shoreline', '{}', ARRAY['Lucinda','Daniel']::text[], '{}', '{}', '98142ce8-e8de-5eb7-9742-723ca5ca63b2', '3', '{}', 'sheet', :'owner') on conflict do nothing;
