insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5656a609-45bf-54a9-97d2-04517bf3fe54', 'Engelslicht', 'Rapture', '9783641089252', 'Luzifer will die Welt endgültig vernichten. Nur neun Tage bleiben Luce und Daniel, um seinen Plan zu vereiteln. Gemeinsam machen sie sich auf die Suche nach drei unschätzbar wertvollen Reliquien. Sollten sie diese rechtzeitig zum Berg Sinai bringen, haben sie noch eine Chance. Doch die Zeit läuft ihnen davon und der letzte Kampf erfordert große Opfer, denn auch Engel können sterben ...', '22.07.2013', 'cbt', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Shoreline', '{}', ARRAY['Lucinda','Daniel']::text[], '{}', '{}', '98142ce8-e8de-5eb7-9742-723ca5ca63b2', '4', '{}', 'sheet', :'owner') on conflict do nothing;
