insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('01a1f473-2ed6-5d2a-9d96-6d1d9c007df8', 'Suddenly a Murder', NULL, '9783846602188', 'Eigentlich will Izzy Morales bloß mit ihren Freunden den Schulabschluss feiern. Dafür hat ihre beste Freundin Kassidy sie alle in ein Herrenhaus auf einer abgelegenen Insel eingeladen. Es soll eine mehrtägige Party unter dem Motto der 1920er werden, stilecht in Vintage-Kleidern und teuren Diamanten. Am Anfang genießen sie tatsächlich einige glamouröse Tage - bis Kassidys Freund plötzlich tot aufgefunden wird. Kurz nachdem die Polizei auf der Insel eintrifft, bricht ein schlimmer Sturm los. Nun sitzen sie alle auf Ashwood Manor fest. Und schon bald stellt sich heraus: Jeder von ihnen hätte ein Motiv für den Mord gehabt. Doch Izzy ist diejenige, die das Messer mit auf die Insel gebracht hat ...', '28.06.2024', 'One', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Ashwood Manor', '{}', ARRAY['Izzy Morales']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
