insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d4e0eced-e6ee-520c-954a-b5a911d60fc8', 'Als ich dich suchte', 'Vanishing Girls', '9783646927948', 'Die beiden Schwestern Nick und Dara sind grundverschieden und doch unzertrennlich. Bis Dara Parker küsst, Nicks besten Freund - und vielleicht mehr ... Bis zu dem Autounfall, bei dem Dara im Gesicht verletzt wird. Seitdem sprechen die Schwestern nicht mehr miteinander. Als Dara an ihrem Geburtstag spurlos verschwindet, glaubt Nick zuerst an einen dummen Scherz. Doch Dara ist schon das zweite Mädchen in der Gegend, das wie vom Erdboden verschluck ist. Nick spürt, dass ihre Schwester in großer Gefahr ist und dass sie sie finden muss – bevor es zu spät ist.', '01.02.2017', 'Carlsen', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Dara','Nick']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
