insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e16ed8b-3efb-5493-b259-c6c110f584fe', 'Wenn du stirbst, zieht dein ganzes Leben an dir vorbei, sagen sie', 'Before I Fall', NULL, 'Was wäre, wenn heute dein letzter Tag wäre? Was würdest du tun? Wen würdest du küssen? Und wie weit würdest du gehen, um dein Leben zu retten? Samantha Kingston ist hübsch, beliebt, hat drei enge Freundinnen und den perfekten Freund. Der 12. Februar sollte eigentlich ein Tag werden wie jeder andere in ihrem Leben: mit ihren Freundinnen zur Schule fahren, die sechste Stunde schwänzen, zu Kents Party gehen. Stattdessen ist es ihr letzter Tag. Sie stirbt nach der Party bei einem Autounfall. Und wacht am Morgen desselben Tages wieder auf. Siebenmal ist sie gezwungen diesen Tag wieder und wieder zu durchleben. Und begreift allmählich, dass es nicht darum geht, ihr Leben zu retten. Zumindest nicht so, wie sie dachte ...', '15.03.2013', 'Carlsen', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Samantha Kingston']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
