insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e8130f3-7264-500b-920a-a92029bc30e5', 'Delirium - Amor Deliria Nervosa', 'Delirium', NULL, 'Früher, in den dunklen Zeiten, wussten die Leute nicht, dass die Liebe tödlich ist. Sie strebten sogar danach, sich zu verlieben. Heute und in Lenas Welt ist Amor Deliria Nervosa als schlimme Krankheit identifiziert worden. Doch die Wissenschaftler haben ein Mittel dagegen gefunden. Auch Lena steht dieser kleine Eingriff bevor, kurz vor ihrem 18. Geburtstag. Danach wird sie geheilt sein. Sie wird sich nicht verlieben. Niemals. Aber dann lernt sie Alex kennen. Und kann einfach nicht mehr glauben, dass das, was sie in seiner Anwesenheit spürt, schlecht sein soll.', '2011', 'Carlsen', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lena','Alex']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
