insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cac1f9ec-08cb-5412-a7d9-0103379d496f', 'Pandemonium - chaos, wirrnis, tumult', 'Pandemonium', NULL, 'Die angepasste Lena von früher gibt es nicht mehr. Das Mädchen, das glaubte, was man ihm sagte, und sich gegen die Liebe heilen lassen wollte. Dieses alte Ich hat Lena zurückgelassen auf der anderen Seite des Zauns, über den sie mit Alex geflohen ist. Hier, in der Wildnis, schließt sie sich dem Widerstand an. Ein Auftrag führt sie erneut in die Stadt. Und tief in ihrem Innern gibt sie die Hoffnung nicht auf, dass Alex doch noch am Leben ist. Sie muss ihn finden. Denn in ihrem Herzen lodert immer noch die Liebe.', '25.10.2012', 'Carlsen', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lena','Alex']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '2', '{}', 'sheet', :'owner') on conflict do nothing;
