insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('90a98eff-f295-5366-bf9b-def32139e23e', 'Requiem - missa pro defunctis', 'Requiem', NULL, 'Lena und Julian sind endlich zurück in der Wildnis. Hier sind sie vorerst in Sicherheit und alles könnte gut sein. Doch etwas zwischen den beiden hat sich verändert, und Lena spürt, dass sie eigentlich zu Alex gehört. Aber auch Alex ist nicht mehr der, den sie immer geliebt hat, und wirkt seltsam abweisend. Hana dagegen, Lenas Freundin von früher, führt ein ruhiges und geordnetes Leben ohne Liebe mit dem für sie ausgewählten Partner. Und während die Rebellen alles für den entscheidenden Angriff auf Portland vorbereiten, muss sich Lena ihrer Vergangenheit stellen.', '24.01.2014', 'Carlsen', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lena','Alex']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '3', '{}', 'sheet', :'owner') on conflict do nothing;
