insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7444d2bf-2d35-5ded-9758-ec13df66c2e6', 'Hana - amor deliria nervosa', 'Hana', NULL, 'Wilde Partys, laute Musik, Treffen mit Jungs - all das ist verboten. Doch Hana ist das egal. Im letzten Sommer vor der OP, die sie endgültig gegen die Liebe immun machen wird, will Hana nur eins: leben. Lena dagegen, ihre beste Freundin, war schon immer die Angepasste. Aber dann entdeckt Hana, dass auch Lena ihre gut gehüteten Geheimnisse hat - und sie verspürt einen Stich der Eifersucht.', '23.05.2012', 'Carlsen', ARRAY['Deutsch']::text[], 72, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Hana']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
