insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d1799689-3858-5000-afc8-2f41b3509b2a', 'Annabel - amor deliria nervosa', 'Annabel', NULL, 'Lenas Mutter Annabel hatte nie ein leichtes Leben. Ihre Flucht von zu Hause als junges Mädchen glückt nicht – sie wird gegen ihren Willen geheilt, um nicht mehr lieben zu müssen. Und doch liebt sie, selbst dann noch, als man sie in die Grüfte wirft und von ihrer Tochter Lena trennt. Doch Annabel war schon immer eine Kämpferin. Und sie wird niemals aufgeben.', '20.12.2013', 'Carlsen', ARRAY['Deutsch']::text[], 49, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Anabelle']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
