insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8595a11f-b26a-59b2-bc08-01e8effecd66', 'Raven - amor deliria nervosa', 'Raven', NULL, 'Raven wächst in einer Welt auf, in der Gefühle verboten sind. Doch als sie ein ausgesetztes Baby findet, entscheidet sie sich zu fliehen. Mit der halb verhungerten Blue überquert sie die Grenze zur Wildnis und lernt dort Tack kennen. Er rettet Blue das Leben – und gewinnt so Ravens Vertrauen. Fortan kämpfen sie beide gemeinsam für die Liebe und für die Freiheit. Doch Raven zweifelt, ob sie dem richtigen Pfad folgen.', '22.11.2013', 'Carlsen', ARRAY['Deutsch']::text[], 39, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Raven']::text[], '{}', '{}', '35fd4fde-d503-5812-afea-a5c4ee4757a1', '6', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
