insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e7389a3b-e751-58a8-9d20-775f90c09dd9', 'Powerless', NULL, '9781398529489', 'Only the extraordinary belong in the kingdom of Ilya . . . The exceptional. The Elites. The Elites have possessed powers for decades, gifted to them by the Plague, while those born Ordinary are just that, banished from the kingdom and shunned from society. No one knows this better than Paedyn Gray, an Ordinary posing as an Elite. When she unsuspectingly saves one of Ilya’s princes, Kai Azer, she’s thrown into the Purging Trials, a brutal competition to showcase her ‘Elite’ powers. If the Trials and the opponents don’t kill her, the prince she’s fighting feelings for will if he discovers what Paedyn really is . . . completely Ordinary.', '14.08.2024', 'Simon & Schuster', ARRAY['Englisch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], NULL, NULL, 'Ilya', '{}', ARRAY['Paedyn Gray','Kai Azer']::text[], '{}', '{}', '7a7e0017-71ed-5355-96eb-7d078714b59a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
