insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5ead5e22-af2e-59d6-802f-6ad1ef2261bf', 'Big Bad Wolf', NULL, '9780008831783', 'Ruby Bellerose lives on the edge of the woods, in a cottage more akin to a fairy tale than modern day life. Her love life is practically non-existent, and she keeps away from the whispered gossip that travels through Maple Hollow. Until a chance encounter with Rafe. As mysterious as he is brooding, Ruby is drawn to the woodsman, curious to find out about the stranger who lives deep within the woods. But Rafe is hiding a secret. And with something lurking in the shadowy forest, will Ruby find that Rafe is her knight in shining armor, or something altogether more dangerous…', '08.09.2026', 'HarperCollins', ARRAY['Englisch']::text[], 367, 58, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Maple Hollow', ARRAY['3P Limited','Double POV']::text[], ARRAY['Ruby Bellerose','Rafe']::text[], ARRAY['Small Town','Soul Mates','Grumpy x Sunshine','Forced Proximity','Found Family']::text[], ARRAY['Tod von Familienangehörigen']::text[], '04beca9e-7dc8-5289-819e-091be78660a5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ac1f09fe-08b5-5646-a5e7-dfad9c354733', :'owner', '5ead5e22-af2e-59d6-802f-6ad1ef2261bf', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital']::text[], ARRAY['Taschenbuch','eBook']::text[], 'Normal', ARRAY['Map','Playlist']::text[], 1169, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'dislike'::verdict_kind, 1.5, 'untertroffen'::expectation_kind, 4, 'slow'::burn_kind, 'Der Anfang des Buches war sehr vielversprechend, doch dann hat es leider stark nachgelassen. Mal ganz abgesehen davon, dass ich es hasse, wenn Mating-Bonds als Ausrede genutzt werden, dafür dass sich Charaktere unsterblich lieben, ohne sich wirklich zu kennen, war er einfach nur ätzend. Seine bevormundende Art ihr gegenüber hat mich irgendwann einfach nur noch angekotzt egnauso wie seine unnötigen Komplexe.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f5d5853a-5411-5221-be23-daa6f0affaad', 'ac1f09fe-08b5-5646-a5e7-dfad9c354733', :'owner', 1, '2026-09-30', '2026-10-09', NULL, NULL, 10, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('28c5296a-b632-56ee-8568-dae624e54c0a', 'Devil''s Deal', NULL, NULL, 'The devil craves my soul. It calls to him like the scent of fresh blood.I am not afraid.The night of summer solstice, I do something stupid. Drawn to the fire of magic, I approach the gods in their sacred circle. I am just a mortal, one of many. I shouldn’t merit their attention.But behind the royal figures of the gods a shadow looms, menacing yellow eyes burning in its gloom. He asks me to dance. His clawed hands circle my waist, turning me to the sound of hoofbeats while his demonic voice whispers seductive lies in my ear. For one night, and one night only, I let him touch me.When it’s morning and gods return to their shrines, he stays. His bloodthirsty shadow follows me, a dark cloak hiding me from the sun and the light of hope. Where I walk, flowers wither and children sicken, touched by his suffocating darkness.The harder I chase him away, the more he enshrouds me in his powerful presence, his claws trapping my body, his will reaching for my soul.He takes away my tribe and poisons my life, trying to break me so I take his deal. But the devil is in for a surprise.I may give him my body, but I’ll never break. With nothing to lose, I am ready to fight', '21.06.2024', NULL, ARRAY['Englisch']::text[], 642, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Jaga']::text[], '{}', '{}', 'a438963c-8ef8-5cff-b4bd-16d7c175b87d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('f082858e-0741-5aad-a8ca-a5d3a62b20e7', :'owner', '28c5296a-b632-56ee-8568-dae624e54c0a', 'tbr'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 799, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b7ee93ae-4aaa-5ab2-8f40-d6cd94709e00', 'Devil''s Doom', NULL, NULL, 'The devil won’t let me run. I feel his hot breath on my nape wherever I go.I’m trapped in a world of magic and monsters, ruled by laws I don’t understand, inhabited by creatures older and far more vicious than me. Here, I am a mere mortal. I am food or entertainment or both.If I want to get anywhere, I must tame my newfound power and find allies, but in the war-ravaged Slawa, no one trusts anyone. I must prove myself, risking my life and evading the devil, even though he seems unavoidable. He does everything in his might to force his way back into my graces and heart.When the biggest powers in Slawa find out who I am, everything changes, and I learn my lesson one more time.I shouldn’t have trusted the devil. But he should have learned, too. I bite so hard when I’m cornered.', '20.03.2025', NULL, ARRAY['Englisch']::text[], 623, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Jaga']::text[], '{}', '{}', 'a438963c-8ef8-5cff-b4bd-16d7c175b87d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
