insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('15470bc8-d988-5d0e-8b34-568a3a37e247', 'Devil''s Dance', NULL, NULL, 'Slawa’s gods are at war, and I am the prize they fight for.I am broken. A piece of my soul burned away, leaving me hollow and unfeeling. I wander the caverns of Nawie, the only place that’s not entirely unsafe. When I can’t stand the boredom of a life with no meaning, I amuse myself watching Woland’s pitiful attempts to atone.He grovels. He begs. He brings me gifts. His despair grows deeper with every shake of my head. Oh, how well he lies.Little does he know, nothing will make me trust him again. And if that broken part of my soul ever heals, I will rip it out and destroy it.Because Woland was right. Love is a terrible weakness.The final book in the Jaga and the Devil trilogy will come out on the winter solstice.', '21.12.2025', NULL, ARRAY['Englisch']::text[], 559, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Jaga']::text[], '{}', '{}', 'a438963c-8ef8-5cff-b4bd-16d7c175b87d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
