insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d2f86e8f-dac9-5815-a8a1-9c7fc0737ec1', 'Shifter Island - Die Akademie der Wölfe', 'Shifter Island - Midnight Kisses', '9783846602287', 'Nai hat sich ihr ganzes Leben darauf vorbereitet, den Platz als Anführerin ihres Rudels einzunehmen. An der Alpha Academy, einer Eliteschule, soll sie nun die dafür nötige Elementar-Magie erlernen. Die vier Wächter, die sie dorthin eskortieren, entpuppen sich jedoch als jene Männer, die Nai vor langer Zeit zu ihren Erzfeinden erklärt hat. Als auf ihrer Haut plötzlich magische Runen erscheinen und ausgestoßene Gestaltwandler die Schule angreifen, scheint Nais Lage verzwickter denn je. Doch dann trifft sie auf einem Maskenball ihren Mate - ihre große Liebe, vom Schicksal vorherbestimmt. Und er sieht nicht nur unverschämt gut aus - er ist auch unter allen Umständen verboten ...', '29.11.2024', 'LYX', ARRAY['Deutsch']::text[], 384, 21, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, 'Alpha Academy', '{}', ARRAY['Nai']::text[], ARRAY['Academy','Omegaverse','Shapeshifters']::text[], '{}', 'c0cf8824-a51b-5038-9b03-2febb05c241e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
