insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c2fdb209-ace2-51ae-8ef6-9c84a1726acb', 'Shifter Island - Der Wächter der Seelen', 'Shifter Island - Midnight Lies', '9783846602515', 'Nais erste Monate auf der Alpha Academy waren nicht gerade einfach: Ihr Schicksalsgefährte ist aus dem rivalisierenden Clan, Selkie-Angriffe halten die Schule in Atem, und sie entkommt nur knapp einem Mordanschlag. Eins ist klar: Das Leben auf Shifter Island ist schwieriger als gedacht. Als einer von Nais Freunden umgebracht wird, ist sie fest entschlossen, ihn zurückzuholen. Sie macht sich auf nach Dark Row, um Wächter der Seelen aufzusuchen. Aber die Reise ins Totenreich verläuft ganz anders als geplant. Nai entdeckt nicht nur ein riesiges Familiengeheimnis, sondern verliert auch beinahe ihren Seelengefährten. Dabei würde sie lieber sterben, als Rage seinem Schicksal zu überlassen ...', '25.04.2025', 'LYX', ARRAY['Deutsch']::text[], 336, 15, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, 'Alpha Academy', '{}', ARRAY['Nai']::text[], ARRAY['Academy','Omegaverse','Shapeshifters']::text[], '{}', 'c0cf8824-a51b-5038-9b03-2febb05c241e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
