insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba0c8eeb-934c-5a9d-8df8-d34114ba5ef8', 'Shifter Island - Der Geist des Magiers', 'Shifter Island - Midnight Lies', '9783846602522', 'Für Nai steht alles auf dem Spiel: das Band zu ihrem Schicksalsgefährten, die Sicherheit ihrer Familie und ihre eigene Freiheit. Die Akademie der Hochmagier ist völlig anders, als sie es ich vorgestellt hat, und Nai wünscht sich nichts sehnlicher, als zurück an Rage‘ Seite zu kehren. Doch als dunkle Mächte nicht nur Shifter Island, sondern auch High Mage Island bedrohen, müssen sich die Magier und Gestaltwandler zusammenraufen, um nicht jede Hoffnung auf Frieden zu verlieren. Nai muss sich fragen, wer wirklich auf der Seite des Bösen und des Guten steht - und wem sie vertrauen kann.', '27.06.2025', 'LYX', ARRAY['Deutsch']::text[], 368, 21, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, NULL, 'Alpha Academy', '{}', ARRAY['Nai']::text[], ARRAY['Academy','Omegaverse','Shapeshifters']::text[], '{}', 'c0cf8824-a51b-5038-9b03-2febb05c241e', '3', '{}', 'sheet', :'owner') on conflict do nothing;
