insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b68fdb0c-46d9-58db-a6bf-daa82ad4e094', 'Six of Crows', NULL, '9781780622286', 'Ketterdam: a bustling hub of international trade where anything can be had for the right price—and no one knows that better than criminal prodigy Kaz Brekker. Kaz is offered a chance at a deadly heist that could make him rich beyond his wildest dreams. But he can''t pull it off alone. . . . A convict with a thirst for revenge. A sharpshooter who can''t walk away from a wager. A runaway with a privileged past. A spy known as the Wraith. A Heartrender using her magic to survive the slums. A thief with a gift for unlikely escapes. Six dangerous outcasts. One impossible heist. Kaz''s crew is the only thing that might stand between the world and destruction—if they don''t kill each other first.', '02.06.2016', 'Hachette', ARRAY['Englisch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Kaz Brekker']::text[], '{}', '{}', '3ab867e3-f084-5867-a804-4ef86842c69f', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
