insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a2e206b7-f8a8-5329-a12d-da10e5dfcade', 'Coldhart - Right & Wrong', NULL, '9783736321175', 'Elijah Coldwell hat genug - genug von der Panik, genug von all dem Leid, genug von seiner Angst. Alles, was er jetzt will, ist, Harrison Grant ein für alle Mal das Handwerk legen und ihn für seine Taten zu bestrafen. Denn Grant verwandelte Elijahs Leben vor dreizehn Jahren nicht nur in einen Albtraum; er sorgt seither auch dafür, dass dieser Albtraum nicht endet. Eli weiß, dass er seine Familie nur vor seinem mächtigen Gegner beschützen kann, wenn er bereit ist, alles aufs Spiel zu setzen. Selbst wenn das bedeutet, dass er nicht nur die Frau verlieren könnte, die ihm mehr alles andere auf der Welt bedeutet, sondern auch sein eigenes Leben ...', '18.11.2024', 'LYX', ARRAY['Deutsch']::text[], 470, 41, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Elijah Coldwell','Felicity Everhart']::text[], '{}', '{}', 'b6ebfd5e-de57-534c-b52d-3b5275a0611f', '3', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
