insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2bfb46c5-7253-56c8-a4ff-a760cc4936a1', 'Coldhart - Strong & Weak', NULL, '9783736320734', 'Elijah Coldwell hat sein Leben unter Kontrolle: Studium, Firma, Sport, alles ist strengstens durchorganisiert. Die Ängste, die ihn seit einer Entführung in der Kindheit quälen, hat er auf diese Weise im Griff. Nur sich zu verlieben, kommt für ihn nicht infrage, zu groß ist das Risiko, noch einmal so verwundbar zu sein wie damals. Doch dann trifft er auf Felicity Everhart, die ihn mehr fasziniert als irgendjemand zuvor. Eigentlich hat Felicity gerade andere Sorgen, bemüht sie sich doch vergebens darum, endlich ihrem Vater näherzukommen, von dem sie kaum etwas weiß. Aber das, was zwischen ihnen ist, können weder Elijah noch Felicity lange ignorieren - nicht ahnend, dass ihre Liebe unter denkbar schlechten Vorzeichen steht. Denn als Elijah neue Hinweise zu seinen Kidnappern erhält, hat er keine Ahnung, dass einer der Namen auf seiner Liste ausgerechnet der von Felicitys Vater ist ...', '23.01.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Elijah Coldwell','Felicity Everhart']::text[], '{}', '{}', 'b6ebfd5e-de57-534c-b52d-3b5275a0611f', '1', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
