insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('8d4e7bd3-a3ef-52de-b19f-298428ac2ce6', '6cfc4230-6d97-54db-bdbf-3c5ba7cfc408', :'owner', 1, '2024-06-25', '2024-07-02', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ce4e83f4-5bec-52bc-b3fb-158c2365a36a', 'Westwell - Heavy & Light', NULL, '9783736317628', 'Als Helena Weston nach New York zurückkehrt, hat sie nur ein Ziel: den Ruf ihrer Schwester wiederherstellen, koste es, was es wolle. Zweieinhalb Jahre ist es her, dass Valerie und ihre große Liebe Adam nach einer Partynacht tot in ihrer Hotelsuite aufgefunden wurden, und seitdem lässt Adams Familie keine Gelegenheit aus, Valerie die alleinige Verantwortung am tragischen Tod der beiden zu geben. Einzig Helena glaubt fest an die Unschuld ihrer Schwester, und sie setzt alles daran, herauszufinden, was in jener schicksalhaften Nacht wirklich geschehen ist. Aber auf der Suche nach der Wahrheit kommt ihr ausgerechnet Jessiah Coldwell - Adams jüngerer Bruder - in die Quere. Helena weiß, dass sie Jess eigentlich mit jeder Faser ihres Seins hassen müsste. Und doch weckt er Gefühle in ihr, gegen die sie schon bald machtlos ist ...', '22.06.2022', 'LYX', ARRAY['Deutsch']::text[], 470, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Helena Weston','Jessiah Coldwell']::text[], '{}', '{}', '99c0f2fe-bc05-524a-8d63-ba844602e318', '1', '{}', 'sheet', :'owner') on conflict do nothing;
