insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2ebb4062-02bf-5ba4-a3a4-2397b3dcce0c', 'Coldhart - Deep & Shallow', NULL, '9783736321151', 'Vier Monate ist es her, dass Elijah die Frau von sich gestoßen hat, die ihm alles bedeutet. Und auch wenn sich jeder Gedanke an Felicity anfühlt wie ein Stich mitten ins Herz, bereut er nicht, es getan zu haben, denn es war der einzige Weg, sie zu beschützen. Jetzt verfolgt Elijah nur noch ein Ziel: denjenigen zu finden, der ihn vor dreizehn Jahren entführt hat und ihm das Leben seitdem zur Hölle macht. Doch er kann Felicity nicht vergessen, vor allem nicht, als er ihren Vater als seinen Entführer entlarvt. Mit einem Mal steht er vor der Entscheidung, Felicity weiterhin in dem Glauben zu lassen, er hätte nie etwas für sie empfunden - oder ihr die Wahrheit zu sagen und damit alles zu riskieren ...', '28.05.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Elijah Coldwell','Felicity Everhart']::text[], '{}', '{}', 'b6ebfd5e-de57-534c-b52d-3b5275a0611f', '2', ARRAY['Sequel','Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
