insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a3c460d6-37f2-5783-af67-80fab19f8ea9', 'Westwell - Bright & Dark', NULL, '9783736318052', 'Helena vermisst Jess mit jeder Faser ihres Seins. Vor zwei Monaten musste sie die schwerste Entscheidung ihres Lebens treffen und sich von ihm trennen, und noch immer zerreißt ihr allein der Gedanke an ihn das Herz. Einzig ihre Nachforschungen zum Tod ihrer Schwester schaffen es, sie über Wasser zu halten. Doch als sie dabei auf eine Information stößt, die Jess’ gesamte Welt auf den Kopf stellen könnte, bleibt ihr nichts anderes übrig, als erneut Kontakt mit ihm aufzunehmen. Jess ist außer sich, als er erfährt, dass Helena im Todesfall ihrer Geschwister ermittelt, ist er doch überzeugt, dass sie sich dadurch in große Gefahr begibt. Daher beschließt er, ihr zu helfen - und obwohl beide wissen, dass sie nicht zusammen sein dürfen, ist es bald unmöglich, ihre Gefühle zu ignorieren ...', '26.10.2022', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Helena Weston','Jessiah Coldwell']::text[], '{}', '{}', '99c0f2fe-bc05-524a-8d63-ba844602e318', '2', '{}', 'sheet', :'owner') on conflict do nothing;
