insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3c99e9dc-2967-5823-9610-f59d35dd3f15', 'Westwell - Hot & Cold', NULL, '9783736318137', 'Helena kann es nicht fassen: In dem Moment, als ihr Glück mit Jess endlich zum Greifen nah ist, wird es ihr schon wieder entrissen. Gerade haben die beiden beschlossen, sich all denen zu widersetzen, die ihre Liebe verhindern wollen, da greifen Unbekannte Jess an und verletzen ihn lebensgefährlich. Doch wer hat es auf ihn abgesehen? Und warum? Helena muss sich erneut auf die Suche nach Antworten begeben, die gefährlich eng mit dem Tod von Valerie und Adam verwoben sind. Und je näher sie der Wahrheit kommt, desto mehr fragt sie sich, ob sie und Jess jemals eine gemeinsame Zukunft haben können - oder ob ihre Liebe nicht von Anfang an zum Scheitern verurteilt war ...', '22.02.2023', 'LYX', ARRAY['Deutsch']::text[], 459, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Thriller (K)']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', ARRAY['Double POV','1P']::text[], ARRAY['Helena Weston','Jessiah Coldwell']::text[], '{}', '{}', '99c0f2fe-bc05-524a-8d63-ba844602e318', '3', '{}', 'sheet', :'owner') on conflict do nothing;
