insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('672610ad-6333-5f4e-8113-ecc296201ce5', 'Die Sehnsucht der Tulipane', NULL, NULL, 'Janna verkauft Blumen. Doch seit Jahren nimmt sie die Schönheit um sich herum kaum mehr wahr. Nach einem tragischen Verlust hat sie sich in ihre eigene Welt zurückgezogen. Dann begegnet sie einem seltsamen Fremden, der behauptet, er sei ein Engel. Was ihm Janna natürlich nicht glaubt. Doch nach und nach bringt er ihr das Leben zurück ... "Seine Hand war fest und warm und wirklich. Manuels sanfte braune Augen glitzerten. "Ich will nichts von dir, sondern alles für dich."', '25.08.2014', 'adeo', ARRAY['Deutsch']::text[], 160, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', ARRAY['Historischer Liebesroman']::text[], NULL, NULL, NULL, '{}', ARRAY['Janna']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
