insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d248d55d-321b-58e3-9cfe-6cc953433ab3', 'Katzenmagie - Das Element der Nacht', NULL, NULL, 'Vielleicht hat Ari, siebzehn Jahre alt, rothaarig und trotzig, den schönen weißblonden Nachbarsjungen Alaric schon immer geliebt. Sonst hätte sie längst versucht, ihrer bösartigen, katzenmordenden Großmutter zu entkommen. Doch dann entdeckt sie einen verletzten Kater und nimmt ihn heimlich mit nach Hause. Wie hätte sie ahnen können, dass sie dadurch Alarics Erzfeind das Leben gerettet hat? Schließlich haben Alaric und ihre Großmutter ihr nie erzählt, was es mit den Elemente-Formern auf sich hat – mit der Morgenkönigin, der Herrin der Luft, und ihrem finsteren Gegenspieler, dem Nachtkönig ...', '21.06.2014', NULL, ARRAY['Deutsch']::text[], 258, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Ari']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
