insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('713f77c1-5e58-5c51-aa4f-928f40553504', 'Wild', NULL, NULL, 'In einer Welt der Zukunft, einer Stadt des Glücks, ist alles rosarot - bis du die Augen öffnest und die Wahrheit erkennst ... Gezähmte Gefühle. Eine Welt ohne Krankheit und Kummer. Kein Leid und keine Leidenschaft. Einmal wöchentlich bekommt jeder in "Neustadt" seine Glücksinjektion. Trotzdem ist die siebzehnjährige Pi nicht so glücklich wie alle anderen. Stimmt etwas nicht mit ihr? Oder warum darf sie nicht mit Lucky zusammen sein, ihrem besten Freund? Anders zu sein ist gefährlich, denn hinter dem Zaun, der "Neustadt" umgibt, liegt die Wildnis. Dort herrschen noch Krankheit und Gewalt - und dorthin werden alle verbannt, die aus der Reihe tanzen. Dann geschieht etwas Unfassbares: Die Glücksdroge versagt. Und plötzlich steht Pi vor der Entscheidung ihres Lebens: Liebe oder Freiheit?', '11.03.2013', 'Drachenmond', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Neustadt, Wald', '{}', ARRAY['Pi']::text[], '{}', '{}', '045733c1-16cb-5594-b404-6ec735ab430b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
