insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e83c1b2c-e3b0-505d-94f4-68185d879ff9', 'Meeresstreicheln - Das Element der Nacht', NULL, NULL, 'James Meerwin ist schon sein Leben lang auf der Flucht, denn niemand darf erfahren, was er und seine kleine Schwester mit dem Element Wasser anrichten können. Bis ihm im Traum der Nachtprinz begegnet, der einen Pakt mit ihm schließt. Auf der Suche nach dem geheimnisvollen Fremden trifft James auf einen Jungen mit verbrannten Händen. Doch Romeo ist schon lange kein Nachtprinz mehr …', '01.12.2014', NULL, ARRAY['Deutsch']::text[], 246, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['James Meerwin']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '2', '{}', 'sheet', :'owner') on conflict do nothing;
