insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d298113-2e89-5139-8f2f-895e8c674267', 'Wach', NULL, NULL, 'Gezähmte Gefühle, eine Welt ohne Krankheit und Kummer, kein Leid und keine Leidenschaft – das ist Neustadt, in der die Bevölkerung mit der Glücksdroge unter Kontrolle gehalten wird. Dagegen ist das Leben im Wald voller Risiken und Herausforderungen. Doch auch hier gibt es keine wahre Freiheit, und zwischen heimlichem Verrat und offener Rebellion muss die junge Peas, genannt Pi, herausfinden, was ihr wirklich etwas bedeutet. Dann begegnet sie eines Tages mitten in der Wildnis dem Feind, und alles ändert sich … "Er stand im Schatten, nicht mehr als zehn Meter entfernt, und nur seine Haare schimmerten wie ein verwaschener heller Fleck in der Nacht. Eine Weile standen wir nur da, keiner von uns rührte sich, und ich hätte fast glauben können, dass ich mir alles nur einbildete. Dann bewegte sich die Gestalt fort und verschwand in der undurchdringlichen Finsternis. Was konnte ich gewinnen, wenn ich ihn verriet? Vielleicht meine Entscheidungsfreiheit. Vielleicht mein eigenes Leben, meine Rückkehr zu den Damhirschen, meine Freiheit. Ich hatte Lucky geopfert, den ich geliebt hatte, um frei zu sein. Wie viel würde es mich kosten, einen Feind zu opfern, der mir nichts bedeutete?"', '18.07.2016', 'Drachenmond', ARRAY['Deutsch']::text[], 600, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Wald', '{}', ARRAY['Pi']::text[], '{}', '{}', '045733c1-16cb-5594-b404-6ec735ab430b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ff1d2025-2b91-5c70-898a-cdbc4f527c2b', :'owner', '3d298113-2e89-5139-8f2f-895e8c674267', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 599, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'middle'::verdict_kind, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
