insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c548cb73-a3ee-532d-b607-0aa16e05f4ad', 'Feuerwinter - Das Element der Nacht', NULL, NULL, 'Die 18 jährige Schülerin Noelle ist Feuer. Die letzte Feuerformerin zu sein hat allerdings einen entscheidenden Nachteil: Sie darf ihre Gefühle nicht ausleben, weil sie sonst alles in Brand stecken würde. Küsse, Berührungen, Liebe – alles ist ihr verboten. Trotzdem hätte sie vielleicht besser nicht auf den Rat des geheimnisvollen Nachtprinzen hören dürfen. Denn nachdem sie die Gesetze des Morgens gebrochen und sich auf das Treffen mit einem zweiten Feuerformer eingelassen hat, kann sie den rätselhaften Adam nicht vergessen. Was verbirgt er? Ist er ein Spieler? Als Noelle nach Adam sucht, entdeckt sie ein gefährliches Geheimnis und findet sich in einem Spiel um Leben und Tod wieder, in dem es nur um eins geht: um Rache …', '21.12.2014', NULL, ARRAY['Deutsch']::text[], 239, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Noelle']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '3', '{}', 'sheet', :'owner') on conflict do nothing;
