insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('41f921b7-e689-5c31-a451-03125cbcc230', 'Magyria - Der Traum des Schattens', NULL, NULL, 'Die Finsternis hat gesiegt und Kunun, der Prinz der Schatten, ist der neue, selbst ernannte Herrscher des magischen Reichs Magyria. Doch sein Bruder Mattim, der Prinz des Lichts, ist in unsere Welt entkommen und bereitet sich gemeinsam mit seiner großen Liebe Hanna auf die Rückkehr nach Magyria vor. Denn Hannas Gefühle für ihn sind ein Funken Hoffnung. Ein Funken, der in der Dunkelheit Magyrias wie ein Fanal leuchten und die Anhänger des Lichts führen wird. Doch Kunun erwartet sie bereits …', '15.04.2013', 'blanvalet', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, 'Magyria', '{}', ARRAY['Hanna']::text[], '{}', '{}', '526f685c-74af-5522-9a46-8383e231354d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
