insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('13d1d9ed-d23f-5db5-b2fa-184376902634', 'Traumwispern - Das Element der Nacht', NULL, NULL, 'Ari ist erwacht – und bereit, um ihr Leben und ihr Glück zu kämpfen. Doch sie zögert, der Elitetruppe des mysteriösen Nachtprinzen beizutreten. Denn wer ist Rean wirklich, und was ist sein wahres Ziel? Die Suche nach ihrem Anführer führt die jungen Spieler in einen Abgrund aus Verrat und Täuschung, und Ari muss über sich selbst hinauswachsen, um ihren Freunden zu helfen und den Mann zu retten, mit dem sie viel mehr als ein Pakt verbindet. Ihre Träume weisen ihr den Weg … in die Dunkelheit.', '09.02.2015', NULL, ARRAY['Deutsch']::text[], 293, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Ari']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '4', '{}', 'sheet', :'owner') on conflict do nothing;
