insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2b8e2aa6-f3f3-5b47-96de-e18db1044e57', 'Wolkenbrand - Das Element der Nacht', NULL, NULL, 'Seit vielen Jahrhunderten warten die Hüter der Welt auf den wahren König des Morgens, auf den König, der die Nacht endgültig besiegen kann. Das Kind, das einem der mächtigsten Spielerpaare geboren wird, ist entweder die Rettung oder der Untergang. Doch dann liegt plötzlich ein zweites Kind in der Wiege, ein Kind, von dem niemand weiß, wo es herkommt ... Dies ist die Geschichte von Ice. Eine Geschichte von Liebe und Hass, von Luft und Feuer, von einem Jungen, der dazu bestimmt ist, die Welt zu retten. Doch wie könnte er gegen die Nacht kämpfen? Denn da ist auch noch Aramis, sein dunkler Zwilling. Und Lilla, das Mädchen, das er liebt.', '29.10.2015', NULL, ARRAY['Deutsch']::text[], 281, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Ice']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '5', '{}', 'sheet', :'owner') on conflict do nothing;
