insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f4b98d41-5b85-53de-b489-36f88030db00', 'Eismorgen - Das Element der Nacht', NULL, NULL, 'James, der dunkle König des Morgens, hat seiner Schwester Lilla ihre Wassergabe genommen, als sie ein Kleinkind war. Jahrelang ist es ihm gelungen, sie von den Geheimnissen der Formergesellschaft fernzuhalten. Doch als er sie vor einem Gedankenleser warnt, der aus seiner Kerkerzelle ausgebrochen ist, ist es bereits zu spät. Denn Lilla träumt von einem schwarzhaarigen Jungen mit goldenen Augen – den sie auch tagsüber nicht mehr los wird. Und Aramis ist längst nicht die größte Gefahr, die Lilla und den Spielern droht.', '16.03.2016', NULL, ARRAY['Deutsch']::text[], 275, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['James','Lilla']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '6', '{}', 'sheet', :'owner') on conflict do nothing;
