insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e58836f5-8f98-5732-a278-1217881f9bb8', 'Sturmstille - Das Element der Nacht', NULL, NULL, 'Die Welt am Abgrund, bedroht von Feuer und Flut – und ein Traum, den alle gemeinsam träumen. Doch nun holt der Morgen zu einem vernichtenden Schlag aus mit dem Ziel, die Spieler endgültig zu vernichten. Und während Ari und ihre Freunde nach einer Möglichkeit suchen, die Katastrophe aufzuhalten, taucht ein alter Feind auf und zwingt Aramis zu einem verhängnisvollen Schwur. Das packende Finale der Trilogie um Ice, Aramis und Lilla.', '18.05.2016', NULL, ARRAY['Deutsch']::text[], 404, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Ari']::text[], '{}', '{}', '885ba1e9-e350-5e80-afaf-9f9704c3e1a1', '7', '{}', 'sheet', :'owner') on conflict do nothing;
