insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('942b3eae-819c-5f71-aed7-ad29fe89878c', 'Magyria - Das Herz des Schattens', NULL, '9783764530440', 'Ein Jahr als Au-pair in Budapest – das klingt für die junge Deutsche Hanna nach einer schönen und aufregenden Zeit. Wie aufregend ihr Aufenthalt in der ungarischen Hauptstadt tatsächlich werden soll, ahnt sie allerdings erst, als sie eines Nachts Mattim begegnet. Denn der rätselhafte junge Mann erzählt ihr eine unglaubliche Geschichte – von Schatten, von einem geheimnisvollen Tor und von einer Stadt, die parallel zu Budapest existiert. Und von Kunun, seinem Bruder, der wie er selbst ein Schatten – ein Vampir – ist, der sich im Gegensatz zu Mattim jedoch ganz in den Dienst der Finsternis gestellt hat. Mattim hingegen versucht, das Gute in sich zu bewahren. Um jedoch nicht von der Dunkelheit in seinem Inneren überwältigt zu werden, braucht er einen starken Halt auf der lichten Seite – den nur Hanna ihm geben kann. Doch Kununs Pläne sind weitreichender und bösartiger, als sie es sich jemals hätten vorstellen können. Und schon bald muss Hanna sich fragen, ob sie bereit ist, für ihre Liebe zu Mattim alles aufzugeben. Sogar ihre Menschlichkeit …', '07.12.2009', 'Penhaligon', ARRAY['Deutsch']::text[], 573, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, 'Magyria', '{}', ARRAY['Hanna']::text[], '{}', '{}', '526f685c-74af-5522-9a46-8383e231354d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
