insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17b455c6-a835-5a4d-9dac-d8ba76c946d4', 'Magyria - Die Seele des Schattens', NULL, NULL, 'Mattim ist ein Vampir, der aus der geheimnisvollen Welt Magyria nach Budapest gekommen ist. Doch durch die Liebe der jungen Deutschen Hanna ist es ihm gelungen, das Gute in sich zu bewahren. Nun hofft er, mit Hannas Hilfe den König von Magyria – seinen Vater – davon zu überzeugen, dass Menschen und Vampire gemeinsam in Frieden leben können. Doch der König ist verblendet, weil er all seine Söhne an die Finsternis verloren hat. Lieber will er Mattim hinrichten lassen, als erneut vergebliche Hoffnung auf Rettung zu hegen. Hat Hanna ihren geliebten Mattim etwa nur vor der Dunkelheit bewahrt, um ihn nun durch die Kämpfer des Lichts zu verlieren? Da steht plötzlich Mattims finsterer Bruder Kunun mit einer Armee von Vampiren vor den Toren der Stadt, und Hanna könnte ihm ohne es zu wollen den Weg hinter die Mauern ermöglicht haben. Plötzlich kämpft die junge Frau nicht mehr nur um das Leben ihrer großen Liebe – jetzt steht das Überleben des Guten in Magyria auf dem Spiel!', '21.01.2013', 'Penhaligon', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, 'Magyria', '{}', ARRAY['Hanna']::text[], '{}', '{}', '526f685c-74af-5522-9a46-8383e231354d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
