insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cc9cdc3e-913f-522c-8905-29400326785b', 'Nathan der Weise', NULL, '9783140222877', 'Nathan der Weise ist der Titel und die Hauptfigur eines fünfaktigen Ideendramas von Gotthold Ephraim Lessing, das 1779 veröffentlicht und am 14. April 1783 in Berlin uraufgeführt wurde.', '1783', 'Schöningh', ARRAY['Deutsch']::text[], 224, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Nathan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
