insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c33b5eb5-74aa-54cf-b051-832118a85ff1', '09418cba-b5cf-5e00-af83-652a6101315d', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4bde5f6d-c575-5e9e-a27b-4ed7c34c8c9a', 'Beneath These Cursed Stars', NULL, '9781399733304', 'Princess Jasalyn has a secret. Armed with an enchanted ring that gives her death’s kiss, Jas has been sneaking away from the palace at night to assassinate her enemies. Shape-shifter Felicity needs a miracle. Fated to kill her magical father, she’s been using her unique ability to evade a fatal prophecy. When rumors of evil king Mordeus’s resurrection spread through the shadow court, Jasalyn decides to end him once and for all. Felicity agrees to take the form of the princess, allowing Jas to covertly hunt Mordeus—and starting Felicity on the path that could finally take her home. While Jasalyn teams up with the charming and handsome Kendrick, Felicity sets out to get closer to the Wild Fae king, Misha. Kendrick helps Jasalyn feel something other than anger for the first time in three years, and Misha makes Felicity wish for a world where she’s free to be her true self. Soon, the girls’ missions are at risk right alongside their hearts. The future of the human and fae realms hangs in the balance as fates intertwine. Between perilous tasks, grim secrets, and forbidden romances, Jasalyn and Felicity find that perhaps their stars are the most cursed of all.', '30.07.2024', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 419, 33, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Faerie', ARRAY['Multiple POV','1P']::text[], ARRAY['Jasalyn','Felicity','Misha','Kendrick']::text[], ARRAY['Different Worlds','Disguised Identity','Forbidden Love','Heir of Throne','Hidden Powers','Magical Artifacts','Mental Issues','Prophezeiung','Race Against Time','Revenge Plot','Secred Identity']::text[], '{}', '256545fd-b04d-5bfb-b974-7cf1c45254a2', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('6515651a-c6dd-59c6-94d8-8b4407f4fe34', :'owner', '4bde5f6d-c575-5e9e-a27b-4ed7c34c8c9a', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 1499, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'slow'::burn_kind, 'Ich mochte Felicity mehr als Jas, trotzdem haben mich beide Storylines mitgerissen und ich bin sehr gespannt wie es weitergeht. Ich hätte mir nur gewünscht, dass Jas nicht immer so irrational handelt.  Meine einzige Kritik ist es, dass ich es nicht mag, wenn man als Leser:in die Geheinisse schon alle kennt und das Drama daraus besteht, dass die Nebencharaktere es auch endlich herausfinden. Ansoonsten hat mir die Story wirklich gut gefallen. Es wurde immer spannender und am Ende musste ich sogar ein paar Tränchen lassen.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('963723a0-c7e6-5a9a-b6f3-b94b5ff57a6c', '6515651a-c6dd-59c6-94d8-8b4407f4fe34', :'owner', 1, '2026-02-17', '2026-02-22', NULL, NULL, 6, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8571926-1bfc-5479-95ac-609cf1e76ec0', 'These Hollow Vows', NULL, '9780358386575', 'Brie hates the Fae and refuses to have anything to do with them, even if that means starving on the street. But when her sister is sold to the sadistic king of the Unseelie court to pay a debt, she''ll do whatever it takes to get her back—including making a deal with the king himself to steal three magical relics from the Seelie court. Gaining unfettered access to the Seelie court is easier said than done. Brie''s only choice is to pose as a potential bride for Prince Ronan, and she soon finds herself falling for him. Unwilling to let her heart distract her, she accepts help from a band of Unseelie misfits with their own secret agenda. As Brie spends time with their mysterious leader, Finn, she struggles to resist his seductive charm. Caught between two dangerous courts, Brie must decide who to trust with her loyalty. And with her heart.', '20.07.2021', 'Houghton Mifflin Harcourt', ARRAY['Englisch']::text[], 439, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Faerie', '{}', ARRAY['Brie','Ronan','Finn']::text[], '{}', '{}', 'c95f6e32-bb65-5d93-9c75-104359726486', '1', '{}', 'sheet', :'owner') on conflict do nothing;
