insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cf665559-4b90-5e64-972b-7d8ac89bf2c8', 'These Twisted Bonds', NULL, '9780358386582', 'After Abriella''s sister was sold to the fae, she thought life couldn''t get any worse. But when she suddenly finds herself caught in a web of lies of her own making--loving two princes and trusting neither--things are not quite as clear as she once thought. As civil war wages in the Unseelie Court, Brie finds herself unable to choose a side. How can she know where she stands when she doesn''t even know herself anymore? In this darkly romantic thrill ride, the more Faerie is torn apart from the inside, the clearer it becomes that prophecies don''t lie and Brie has a role to play in the fate of this magical realm--whether she likes it or not.', '19.07.2022', 'Clarion Books', ARRAY['Englisch']::text[], 476, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Faerie', '{}', ARRAY['Brie','Ronan','Finn']::text[], '{}', '{}', 'c95f6e32-bb65-5d93-9c75-104359726486', '2', '{}', 'sheet', :'owner') on conflict do nothing;
