insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('c532d96b-72ac-553d-b432-49a75232e30a', 'd307b6d5-d435-5d88-a09b-7e989015e9fc', :'owner', 1, '2022-10-06', '2022-10-10', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('37959950-96ba-59de-8dff-6abfaf8b9ff6', 'Between These Broken Hearts', NULL, '9781399733359', 'A human princess armed with death''s kiss and a fae shifter on the run become unlikely allies when a mission to assassinate an evil king collides with a fatal prophecy. Princess Jasalyn has eleven days to live. Jasalyn is facing the repercussions of a deadly bargain. Her life, and the future of the shadow court, are forfeit on her birthday unless she can stop the evil fae king Mordeus. She needs to face her greatest fears and find him before she runs out of time, but even after everything, Kendrick won''t let her face this alone. Shape-shifter Felicity has vanished. Felicity disappeared from King Misha''s dungeons, and her friends have been searching for her to no avail. But even if she''s found, Felicity will never be able to escape the oracle''s tragic prophecy for her and her family. In her lonely battle with fate, Misha is the last person she can ask to stand by her side, but the first one she''ll need.', '22.07.2025', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 449, 50, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Faerie', ARRAY['Multiple POV','1P']::text[], ARRAY['Jasalyn','Felicity','Misha','Kendrick']::text[], ARRAY['Different Worlds','Disguised Identity','Forbidden Love','Heir of Throne','Hidden Powers','Magical Artifacts','Mental Issues','Prophezeiung','Race Against Time','Revenge Plot','Secred Identity']::text[], '{}', '256545fd-b04d-5bfb-b974-7cf1c45254a2', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c12575ee-a532-5e74-b37b-420063ff23c2', :'owner', '37959950-96ba-59de-8dff-6abfaf8b9ff6', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', ARRAY['Map']::text[], 1579, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'slow'::burn_kind, 'Was mich wirklich massiv an Büchern nervt ist, wenn es Prophezeiungen oder Verträge oder ähnliches gibt und die Charaktere einfach nicht richtig zuhören und deshalb das wichtigste ignorieren oder nicht für wichtig erachten. Wirklich es nervt. Vor allem, wenn ich als Leserin schon verstanden habe was passiert aber die Charaktere noch ewig brauchen. Genauso gut wie der erste Band. Wirklich ein tolles Buch, das auch endlich mal ohne den ganzen Smut auskommt. Es war ein auf und ab der Gefühle. Ich habe gelacht, geweint und mich mehr als einmal aufgeregt.') on conflict do nothing;
