insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a03ff765-2f53-53e6-aaed-a7a70ecf4d41', 'Across the Nightingale Floor: Tales of the Otori', NULL, NULL, 'In his palace at Inuyama, Lord Iida Sadamu, warlord of the Tohan clan, surveys his famous nightingale floor. Its surface sings at the tread of every human foot, and no assassin can cross it. But sixteen-year-old Otori Takeo, his family murdered by Iida''s warriors, has the magical skills of the Tribe – preternatural hearing, invisibility, a second self – that enable him to enter the lair of the Tohan. He has love in his heart and death at his fingertips . . .', NULL, 'KNV Besorgung', ARRAY['Englisch']::text[], 324, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, 'Vergangenheit'::time_period, 'Otori', '{}', ARRAY['Otori Takeo']::text[], '{}', '{}', 'ccdb156f-11e8-5175-b16e-440f453c13cc', '1', '{}', 'sheet', :'owner') on conflict do nothing;
