insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e21cf2f7-9d94-5926-9e10-6bb1a70c5ac3', 'Bianca und die drei wilden Kater', NULL, '9783855812486', 'Max, Arnold und Frederico sind drei gefürchtete Kater. Der eine ist klug, der zweite gewieft und der dritte stark. Alle zusammen sind sie unschlagbar. Bis eines Tages ein kleines Mäusemädchen auftaucht und die drei wilden Kater gehörig an der Nase herumführt.', '01.01.1994', 'Bohem Press', ARRAY['Deutsch']::text[], 32, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Max','Arnold','Frederico.']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
