insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ebc996f9-b084-57f4-87b8-51088c7a8c88', 'Angel Eyes - Zwischen Himmel und Hölle', 'Personal Demons', '9783862520060', 'Zwischen Himmel und Hölle liegt nur ein Herzschlag. Als Frannie zum ersten Mal Luc begegnet, fehlen ihr die Worte. Dabei ist sie sonst nicht auf den Mund gefallen. Doch der Neue sieht einfach unverschämt gut aus: ein echter Drauf­gänger mit dunkler Aura – genau ihr Typ. Was Frannie nicht weiß: Luc ist ein Dämon mit besonderer Mission. Er soll ihre Seele für die Hölle sichern. Denn Frannie hat eine wertvolle Gabe, von der sie selbst nichts ahnt. Doch auch die himmlischen Mächte schicken einen Kandidaten ins Rennen: Gabe, einen attraktiven jungen Engel. Und ehe sie sich´s versieht, steht Frannie nicht nur zwischen zwei Männern, sondern auch im Zentrum eines uralten Kampfes ...', '01.08.2011', 'Rowohlt', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Frannie']::text[], '{}', '{}', '4d32d400-c18c-5abe-8e9f-70622cf6ad98', '1', '{}', 'sheet', :'owner') on conflict do nothing;
