insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3efb5da9-99e7-526c-b6a5-fb76b3f5c655', 'Angel Eyes - Im Bann der Dunkelheit', 'Original Sin', '9783862520077', 'Engel sind auch nur Männer. Nichts wünscht Frannie sich sehnlicher, als ein normales Leben zu führen. Stattdessen sind ihr die höllischen Mächte auf den Fersen, denn Frannie hat eine ganz besondere Gabe. Eine Gabe, die den uralten Kampf zwischen Licht und Dunkel ein für alle Mal entscheiden könnte. Dass es Frannie gelungen ist, ihre große Liebe, den Dämon Luc, in einen Menschen zu verwandeln, hat sie nur noch interessanter gemacht. Seitdem Luc seine magischen Kräfte verloren hat, kann er sie nicht mehr beschützen. Diese Aufgabe muss nun ihr Schutzengel Matt übernehmen, Frannies verstorbener Zwillingsbruder. Doch Engel sind auch nur Männer, und als die schöne Lili nebenan einzieht, gerät Matt ganz schön durcheinander. Damit bringt er seine Schwester in höchste Gefahr …', '01.08.2012', 'Rowohlt', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Frannie']::text[], '{}', '{}', '4d32d400-c18c-5abe-8e9f-70622cf6ad98', '2', '{}', 'sheet', :'owner') on conflict do nothing;
