insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2bd2a78e-da79-5338-80a7-acef771f7d6d', 'Hier musst du glücklich sein', 'Seed', '9783551583383', 'Eine kleine Gemeinschaft, abgeschottet von der Welt. Hier ist Pearl aufgewachsen und hier fühlt sie sich sicher, denn ihr Oberhaupt Papa S. beschützt sie alle vor der vergifteten Welt da draußen. Doch als sich der gleichaltrige Ellis und seine Familie ihrer Gemeinschaft anschließen, wird Pearls Weltbild auf die Probe gestellt: Ellis wächst Pearl täglich mehr ans Herz – und er scheint nicht an die Lehren von Papa S. zu glauben! Langsam wird auch Pearl klar, dass sie fliehen müssen, um sich zu retten …', '22.12.2016', 'Carlsen', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Dystopie']::text[], NULL, NULL, NULL, '{}', ARRAY['Pearl']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
