insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('dd5edf97-325e-5fac-aeac-0823c68ecee3', 'ccf04a45-45ba-5136-87e8-e07572ca1cff', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('861b1cfb-93ef-594d-8eac-e4bdaea3ec53', 'Tagebuch eines Vampirs - Bei Dämmerung', 'The Vampire Diaries - The Struggle', '9783570304983', 'Damon scheint aus dem erbitterten jahrhundertelangen Kampf mit seinem Bruder Stefano als Sieger hervorgegangen zu sein, denn Stefano ist und bleibt spurlos verschwunden. Doch Elena setzt alles daran, ihre große Liebe wiederzufinden – und sucht auf dem Friedhof die Konfrontation mit Damon. Obwohl sie Stefano bedingungslos liebt, spürt sie die dunkle Faszination, die von seinem atemberaubend schönen Vampirbruder ausgeht. Angezogen und abgestoßen zugleich ist Elena versucht, Damon das zu geben, was er verlangt – ihr Blut! Doch noch hat sie die Willenskraft, sich gegen Damon zu wehren. Trotz eines von Damon heraufbeschworenen Schneesturms macht sie sich auf die verzweifelte Suche nach Stefano. Als sie ihn tatsächlich findet, ist ihr Blut das einzige, was seine Kräfte wieder stärken kann … Doch auch nach ihrer glücklichen Wiedervereinigung bleibt die drohende Gefahr, die von Damon ausgeht. Elena will einen Kampf zwischen ihm und Stefano um jeden Preis verhindern – und so gibt sie schließlich Damon, wonach er verlangt. Ein folgenschwerer Fehler! Denn nun bekämpfen sich die Brüder auf Leben und Tod … Währenddessen scheint eine unbestimmte, dunkle Macht im Hintergrund alle Fäden in der Hand zu halten und Unheil über Fell’s Church zu bringen. Steckt tatsächlich Damon dahinter – oder hat noch eine andere Macht ihre Finger im Spiel?', '03.11.2008', 'Cbt', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Fell’s Church', '{}', ARRAY['Elena','Damon','Stefano']::text[], '{}', '{}', 'd5d5b798-90f6-5316-b7e4-b41d13a76c67', '2', '{}', 'sheet', :'owner') on conflict do nothing;
