insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('20a2bfe6-68a9-50c0-bc78-0237c1f8281a', 'Tagebuch eines Vampirs - In der Schattenwelt', 'The Vampire Diaries - The Reunion', '9783570305003', 'Mit dem Tod Catarinas scheint das Böse in Fell’s Church endgültig begraben zu sein. Doch auch Elena hat ihre Liebe zu Stefano bitter mit dem Leben bezahlt. Gefangen in einer Schattenwelt, spürt sie, dass das Grauen noch lange kein Ende hat: Ihr Geist wird von einer furchtbaren Macht gebannt, und die hat es auch auf ihre irdischen Freunde abgesehen! Zur Tatenlosigkeit verdammt, empfängt Elena die verzweifelten Hilferufe ihrer telepathisch begabten Freundin Bonnie, denn über Fell’s Church ist das Unheil bereits hereingebrochen – und hat sich mit der hübschen Sue schon das erste Menschenleben einverleibt! Elena weiß: Diese unheilvolle Macht ist die älteste, stärkste und gefährlichste, mit der sie es je zu tun hatten. Und es gibt nur eine Möglichkeit, sie zu besiegen: Wenn Stefano und Damon ihre Feindschaft – die das Böse aus Rache für die Jahrhunderte zurückliegende Vergangenheit unbarmherzig aufs Neue schürt – überwinden und Seite an Seite kämpfen. Doch der Hass sitzt tief und das Grauen hat viele Gesichter … Während Elena verzweifelt darauf hofft, von ihrem Schattendasein erlöst zu werden, steht Stefano in einem blutigen Showdown Auge in Auge mit dem Ursprung alles Bösen: Es ist Nicolaus, der schier übermächtige Vampir, der einst schon Catarina in seine blutrünstige Schöpfung verwandelt hatte. Aber kein Preis ist Stefano zu hoch, um Elena zu rächen und Fell’s Church zu retten! Doch auf welcher Seite steht Damon?', '03.11.2008', 'Cbt', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Fell’s Church', '{}', ARRAY['Elena','Damon','Stefano']::text[], '{}', '{}', 'd5d5b798-90f6-5316-b7e4-b41d13a76c67', '4', '{}', 'sheet', :'owner') on conflict do nothing;
