insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('09543f8d-25a3-5f8f-88a8-2b8d330d90f5', 'Tagebuch eines Vampirs - Seelen der Finsternis', 'The Vampire Diaries - The Return: Shadow Souls', '9783570307038', 'Elenas große Liebe Stefano Salvatore wurde von Dämonen gefangengenommen und in ein grausames Reich verschleppt. Jetzt liegt es an Elena, Stefano zu befreien und zurückzuholen. Dafür ist sie bereit, jeden Preis zu bezahlen, auch wenn es bedeutet, sich in die Hände von Damon Salvatore zu begeben, Stefanos Bruder und ewigem Widersacher. Auf der Reise mit Damon wird Elena mit der alles entscheidenden Frage konfrontiert: Welchen Bruder will sie wirklich?', '11.10.2010', 'Cbt', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Fell’s Church', '{}', ARRAY['Elena','Damon','Stefano']::text[], '{}', '{}', 'd5d5b798-90f6-5316-b7e4-b41d13a76c67', '6', '{}', 'sheet', :'owner') on conflict do nothing;
