insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b640342b-8348-51a7-aa03-594fac717553', 'Tagebuch eines Vampirs - Schwarze Mitternacht', 'The Vampire Diaries - The Return: Midnight', '9783570380123', 'Über 600 Jahre ist es her, dass die Brüder Stefano und Damon zu erbitterten Feinden wurden – und zu Vampiren. Der Kampf der Rivalen ist noch immer nicht entschieden. Denn das Grauen hat viele Gesichter ... Endlich sind Stefano und Elena wieder in Fell’s Church vereint – da schlägt die Welle des Unheils erneut über ihnen zusammen: Durch einen mysteriösen Zauber verwandelt sich ausgerechnet Damon in einen Menschen – und kehrt in wilder Verzweiflung in die Dunkle Dimension zurück, um wieder zum Vampir zu werden. Als mit ihm auch Bonnie spurlos verschwindet, bleibt Elena und Stefano keine andere Wahl: Um Bonnie zu retten, müssen sie den beiden ins Höllenreich der Nacht folgen ...', '18.04.2011', 'Cbt', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Fell’s Church', '{}', ARRAY['Elena','Damon','Stefano']::text[], '{}', '{}', 'd5d5b798-90f6-5316-b7e4-b41d13a76c67', '7', '{}', 'sheet', :'owner') on conflict do nothing;
