insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ac9db4c2-1a86-5e56-bdd0-c38379f1cddd', 'Mile High', NULL, '9781399751926', 'ZANDERS. Chicago hockey isn''t complete without me - everyone''s favourite player to hate. I know my role, and I play it well. In fact, I thoroughly enjoy spending the majority of my game time in the penalty box before leaving the arena with a new girl on my arm each night. What I don''t like is the new flight attendant on our team''s private plane. She works for me, not the other way around. But I''ll be sure to remind her of that, and I can guarantee, by the end of the season, she''ll be begging to quit her job. But every road trip blurs the lines, and I can''t quite figure out if I keep pushing that flight attendant call button in order to push her buttons, or if it''s more than that. STEVIE. I’ve been a flight attendant for years. I thought I''d seen it all, but when my new job lands me onboard working for the most egotistical and self-righteous diva in the NHL, I start to second guess everything. Including the promise I made to myself of never hooking up with an athlete again . . . no matter how annoyingly tempting he may be. Evan Zanders is unfiltered, unapologetic, and too attractive for his own good. He loves his image, but I hate everything about it. Everything but him.', '07.06.2022', 'Hodder & Stoughton', ARRAY['Englisch']::text[], 598, 56, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'NA'::audience_kind, 'Gegenwart'::time_period, 'Chicago', ARRAY['Double POV','1P']::text[], ARRAY['Zanders','Stevie']::text[], ARRAY['Secret Relationship','Sport','Forbidden Love','Enemies to Lovers','Found Family','Forced Proximity']::text[], '{}', 'e3b5baf3-8a6c-5fac-8191-702b1d67a4cd', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('d32831a4-454f-543d-b90c-54cd71ee7047', :'owner', 'ac9db4c2-1a86-5e56-bdd0-c38379f1cddd', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print','Audiobook']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', ARRAY['Playlist','In-Book Illustrationen']::text[], 1079, true, true, ARRAY['Audible']::text[], ARRAY['Winston James','Mari']::text[], 1008, '👎🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 3, 'fast'::burn_kind, 'Ich weiß nicht, ob es daran liegt, dass ich so hohe Erwartungen hatte für dieses Buch, doch es hat mich leider ziemlich enttäuscht. Ich fand die ganze Handlung hervorsehbar und irgendwie auch etwas unnötig an manchen Stellen. Das einzige, was ich wirklich mochte, war die Art und Weise wie Stevie mit ihren Body Issues umgegangen ist und wie diese beschrieben wurden. Damit konnte ich mich sehr identifizieren.') on conflict do nothing;
