insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('796cc73a-bba3-56f3-b210-15ca9152ec71', 'Löcher', NULL, '9783407740984', 'Schon der Anfang ist unglaublich: Stanley Yelnats geht nichts ahnend unter einer Brücke durch, als ihm die riesigen, übel riechenden Turnschuhe eines berühmten Baseballspielers auf den Kopf fallen. Und weil sein Vater an einem bahnbrechenden Recycling-Verfahren mit gebrauchten Turnschuhen arbeitet, hält Stanley die müffelnden Treter für ein Zeichen und nimmt sie mit. Pech, dass die Polizei schon nach dem Dieb sucht. Der Jugendrichter lässt Stanley die Wahl: Jugendgefängnis oder 18 Monate Camp Green Lake. Er entscheidet sich für das Camp. Die Hitze dort ist unerträglich, der Alltag hart, doch so schnell gibt Stanley nicht auf.', '07.10.2008', 'Gulliver von Beltz & Gelberg', ARRAY['Deutsch']::text[], 296, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Camp Green Lake', '{}', ARRAY['Stanley Yelnats']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
