insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c49f127c-8c70-5612-9fbc-ad51674ff85a', 'Die Halbwertszeit von Glück', NULL, '9783757700225', 'Was ist eigentlich Glück? Wann hat man verdient, glücklich zu sein? Und kann man das Glück festhalten? Diese Fragen bewegen Mylène, Johanna und Holly zu drei verschiedenen Zeiten an drei verschiedenen Orten dieser Welt. Jede der Frauen versucht auf unterschiedliche Art und Weise, eigene Antworten zu finden. Mylène folgt der Spur eines geheimnisvollen Briefes, der sie nach Amsterdam führt. Johanna rettet einer verletzten 17-Jährigen das Leben. Und Holly kümmert sich um die Familie einer verstorbenen Kollegin. Doch letzten Endes ist es ein gemeinsames Schicksal, durch das die drei Frauen Antworten auf die Frage nach dem Glück finden.', '29.02.2024', 'Lübbe', ARRAY['Deutsch']::text[], 430, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Coming of Age']::text[], NULL, NULL, NULL, '{}', ARRAY['Mylène','Johanna','Holly']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
