insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('82045a79-a53d-5422-914e-5fa1f3f95c66', 'More Than a Star', 'Bias - A K-Pop-Romance', NULL, 'Die Amerikanerin Madison liebt K-Pop, kann jeden Song ihrer Lieblingsband mitsingen und hat ihr Herz an den Sänger Wooyeong verloren. Als sie einen Job in Seoul ergattert, scheint ihr Glück perfekt. Doch dann sitzt sie in einem Restaurant plötzlich ihrem Schwarm gegenüber und ahnt, dass die Dinge in Zukunft ein bisschen komplizierter werden dürften. Wooyeong ist ein K-Pop-Idol, und er kennt die wichtigste Regel im K-Pop-Business: Date niemals einen Fan! Er hatte nie ein Problem damit. Bis zu dem Moment, als er Madison kennenlernt. Denn er kann seither nicht mehr aufhören, an sie zu denken.', '01.09.2022', 'Everlove', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Madison','Wooyeong']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
