insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e907a6ab-4ac7-529b-ab97-f716771e482a', 'Der Himmel gehört uns', 'We own the Sky', '9783764506285', 'Rob Coates kann sich wirklich glücklich schätzen: Er ist mit seiner großen Liebe Anna verheiratet und nach vielen gemeinsamen Jahren krönt der gemeinsame Sohn Jack endlich das große Glück der beiden. Bis zu dem Moment, an dem die Familie eine unfassbare Diagnose erhält: Der kleine Jack leidet an einer unheilbaren Krebsart. Während es Rob den Boden unter den Füßen wegzieht, versucht Anna, stark zu bleiben – doch anstatt zusammenzuhalten, entfernen die beiden sich immer weiter voneinander. Bis Rob einen Entschluss fasst, der das Leben der Familie für immer verändern wird …', '12.11.2018', 'blanvalet', ARRAY['Deutsch']::text[], 444, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Contemporary YA']::text[], NULL, NULL, NULL, '{}', ARRAY['Rob Coates']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
