insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c30a87ac-8198-55e5-88e8-13344d0f23f2', 'Sadisten', NULL, NULL, 'Wie dunkel ist die menschliche Seele? Lydia Benecke beweist mit ihrem Buch "Sadisten: Tödliche Liebe - Geschichten aus dem wahren Leben", dass so mancher Abgrund darin lauert. Wo fantasievolle Gedankenspielereien in völliger Grausamkeit umgesetzt werden, entsteht eine kriminelle Energie, die sich kaum vergleichen lässt. Die junge Kriminalpsychologin schafft es in ihrem neuesten Werk, den Leser zwar mit einem faktischen Sachbuch zu konfrontieren, dabei aber zeitgleich eine Spannung entstehen zu lassen, die nicht allein durch die grausamen realen Fallbeispiele zustande kommt. Als Kennerin der Szene und Expertin auf dem Gebiet der Verbrechenspsychologie kann Lydia Benecke zudem mit überraschend neuen Einblicken in die verborgenen Seiten des menschlichen Geistes auftrumpfen. Ein Lesevergnügen der anderen Art.', '12.02.2015', 'Lübbe', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Psychologie', '{}', NULL, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
