insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8d60dc19-cc55-5142-ad33-d4624c67f82e', 'Prison Healer - Die Schattenheilerin', 'The Prison Healer', '9783743209862', 'Seit ihrer Kindheit lebt die siebzehnjährige Kiva in Zalindov, dem brutalsten Gefängnis von Wenderall. Als Heilerin kümmert sie sich um alle Insassen. Doch um die Rebellenkönigin zu retten, muss Kiva nicht nur herausfinden, woran Tilda erkrankt ist, sondern sich auch an ihrer Stelle dem Elementarurteil unterziehen: vier Prüfungen, die Tildas Schuld oder Unschuld beweisen sollen. Besteht Kiva, sind beide frei. Sollte sie scheitern, wird nicht nur die Rebellenkönigin sterben …', '09.02.2022', 'Loewe', ARRAY['Deutsch']::text[], 504, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, 'Zalindov', '{}', ARRAY['Kiva']::text[], '{}', '{}', '03ba6ef7-92fe-52b4-a3b6-676df20f238f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
