insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('54b28459-7a14-5a56-97b6-ac513533d044', 'Prison Healer - Die Schattenrebellin', 'The Gilded Cage', '9783743212053', 'Endlich ist Kiva frei. Zusammen mit Jaren hat sie es aus dem brutalen Gefängnis Zalindov nach Vallenia geschafft. Doch keiner ahnt, wer Kiva wirklich ist. Und dass sie als Spionin die Königsfamilie im Auge behalten soll. Auf ihrer Mission gerät Kiva allerdings zunehmend zwischen die Fronten. Schließlich muss sie sich entscheiden, auf welcher Seite sie wirklich steht …', '14.09.2022', 'Loewe', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, 'Zalindov', '{}', ARRAY['Kiva']::text[], '{}', '{}', '03ba6ef7-92fe-52b4-a3b6-676df20f238f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
