insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9c36c4aa-48f8-53a1-af60-b0a8ee21963f', 'Prison Healer - Die Schattenerbin', 'The Blood Traitor', '9783743213517', 'Kivas Leben liegt in Schutt und Asche. Nach jener verhängnisvollen Nacht im Palast ist sie zurück in Zalindov. Viel schlimmer jedoch: Jaren weiß nun, wer sie wirklich ist – und dass sie ihn hintergangen hat. Wozu also noch kämpfen? Doch ehe Kiva aufgeben kann, befindet sie sich wieder in einem gefährlichen Strudel aus Intrigen. Und ausgerechnet sie soll Evalons einzige Chance auf Rettung sein …', '08.03.2023', 'Loewe', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, 'Zalindov', '{}', ARRAY['Kiva']::text[], '{}', '{}', '03ba6ef7-92fe-52b4-a3b6-676df20f238f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
