insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6ceb3ab4-02ee-57b3-aa77-7018c46839d3', 'Project Jane - Ein Wort verändert die Welt', 'Whisper - One Word Could Change the World', '9783841505972', 'Ein Wort ist der Anfang. Oder das Ende. Sie nennen sie Jane Doe, und sie spricht nicht. Egal, was sie mit ihr anstellen, dort in der geheimen Forschungsanstalt Lengard. Denn ein Wort von Jane kann den Lauf der Welt verändern. Und so schweigt sie. Bis der geheimnisvolle Landon Ward ihr Vertrauen gewinnt. Vorsichtig öffnet sich Jane, doch sie muss schnell erkennen, dass ihre Fähigkeiten der Schlüssel zu einem finsteren Plan sind. „Project Jane“ ist Sci-Fi, Romance und Suspense: fesselnd, mystisch und spannend bis zum Schluss.', '22.07.2019', 'Oetinger', ARRAY['Deutsch']::text[], 346, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Dystopie']::text[], NULL, NULL, 'Forschungsanstalt Lengard', ARRAY['Single POV','1P']::text[], ARRAY['Jane Doe']::text[], '{}', '{}', '0de3027f-055b-5208-8779-c3ea50b40700', '1', '{}', 'sheet', :'owner') on conflict do nothing;
