insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('52d5aa31-b95b-5116-834d-886e039cad92', 'Alle unsere Freunde', NULL, '9783880102705', 'Die beiden Freunde Elefant und Maus haben schon alle Geräte auf dem Spielplatz ausprobiert, aber am liebsten würden sie einmal zusammen wippen. Doch das ist gar nicht so leicht, denn so sehr Maus sich auch anstrengt, Elefant bleibt am Boden. Aber zum Glück haben die beiden ja viele Freunde. Girfaffe, Krokodidl, Bär und Käfer - alle wollen ihnen helfen. Ob sie es wohl gemeinsam schaffen?', '01.01.1998', 'Bertelsmann Club', ARRAY['Deutsch']::text[], 29, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Gegenwart'::time_period, 'Spielplatz', ARRAY['3P Objective']::text[], ARRAY['Maus','Elefant']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
