insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c8b3da5d-6506-5998-ab96-0b7c29b9732f', 'Im siebten Himmel mit einem Vampir', 'The Rogue Hunter', '9783802583742', 'Samantha Willan ist Rechtsanwältin und liebt ihren Job über alles. Dennoch ist sie froh, sich im Cottage ihrer Familie einmal eine kleine Auszeit zu gönnen. Nachdem sie gerade erst eine schmerzhafte Trennung hinter sich hat, steht ihr eigentlich nicht der Sinn danach, einen neuen Mann kennenzulernen. Doch als sie die Bekanntschaft ihres gut aussehenden Nachbarn Garrett macht, gerät ihr Entschluss ins Wanken. Was Samantha nicht weiß: Garrett ist ein Vampirjäger. Er sucht nach einem abtrünnigen Vampir, der Menschen angefallen haben soll. Auch Garrett fühlt sich von der hübschen Samantha angezogen. Aber ist er nach achthundert Jahren als Junggeselle bereit für eine ernste Beziehung?', '14.01.2011', 'LYX', ARRAY['Deutsch']::text[], 363, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Samantha Willan']::text[], '{}', '{}', '252a7f72-ba27-53d9-8e94-09d6aa5a29cb', '10', '{}', 'sheet', :'owner') on conflict do nothing;
