insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c5554497-ccbc-5008-8ba0-6c7087b95702', 'Vampire und andere Katastrophen', 'The Immortal Hunter', '9783802584671', 'Auch Vampire müssen mal Urlaub machen. Doch der Polizist Decker Argeneau wird abrupt von seinem Job wieder eingeholt, als eine Gruppe abtrünniger Vampire auftaucht, die Menschen umbringt. Die Vampire halten zwei junge Frauen gefangen, um ihr Blut zu trinken. Decker und seinem Partner gelingt es, die hübsche Dr. Danielle McGill zu befreien. Doch dann wird Danielles Schwester jedoch von einem der Vampire entführt. Decker verspricht Danielle, ihre Schwester zurückzuholen. Aber die Spur des Entführers ist nicht leicht zu finden. Und auch Danielles Leben ist schon bald erneut in Gefahr ...', '04.08.2011', 'LYX', ARRAY['Deutsch']::text[], 361, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Decker Argeneau']::text[], '{}', '{}', '252a7f72-ba27-53d9-8e94-09d6aa5a29cb', '11', '{}', 'sheet', :'owner') on conflict do nothing;
