insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9c26225b-4d74-57a2-96e6-95f1ebd2b115', 'Maangchi‘s big Book of Korean Cooking', NULL, '9781328988126', 'The book contains the favorite dishes Maangchi has perfected over the years, from Korean barbecue and fried chicken to bulgogi and bibimbap. It explores topics not covered in other Korean cookbooks, from the vegan fare of Buddhist mountain temples to the inventive snacks of street vendors to the healthful, beautiful lunch boxes Korean mothers make for their kids. Maangchi has updated and improved the traditional dishes, without losing their authentic spirit.', '29.10.2019', '‎Rux Martin / Houghton Mifflin Harcourt', ARRAY['Englisch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kochen & Ernährung', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
