insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e3a665ba-daf3-552b-9bf1-74287e092841', 'Maangchi’s Real Korean Cooking', NULL, '9780544129894', 'An Internet sensation, Maangchi has won the admiration of home cooks and chefs alike with her trademark combination of good technique and good cheer as she demonstrates the vast and delicious cuisine of Korea. In Maangchi''s Real Korean Cooking, she shows how to cook all the country''s best dishes, from few-ingredient dishes (Spicy Napa Cabbage) to those made familiar by Korean restaurants (L.A. Galbi, Bulgogi, Korean Fried Chicken) to homey one-pots like Bibimbap.', '19.05.2015', '‎Rux Martin / Houghton Mifflin Harcourt', ARRAY['Englisch']::text[], 325, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kochen & Ernährung', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
