insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b1c1890-3cf9-5a1a-9443-3627842e301c', 'Ich bin Circe', 'Circe', '9783961610747', 'Circe ist Tochter des mächtigen Sonnengotts Helios und der Nymphe Perse, doch sie ist ganz anders als ihre göttlichen Geschwister. Ihre Stimme klingt wie die einer Sterblichen, sie hat einen schwierigen Charakter und ein unabhängiges Temperament; sie ist empfänglich für das Leid der Menschen und fühlt sich in deren Gesellschaft wohler als bei den Göttern. Als sie wegen dieser Eigenschaften auf eine einsame Insel verbannt wird, kämpft sie alleine weiter. Sie studiert die Magie der Pflanzen, lernt wilde Tiere zu zähmen und wird zu einer mächtigen Zauberin. Vor allem aber ist Circe eine leidenschaftliche Frau: Liebe, Freundschaft, Rivalität, Angst, Zorn und Sehnsucht begleiten sie, als sie Daidalos, dem Minotauros, dem Ungeheuer Scylla, der tragischen Medea, dem klugen Odysseus und schließlich auch der geheimnisvollen Penelope begegnet. Am Ende muss sie sich als Magierin, liebende Frau und Mutter ein für alle Mal entscheiden, ob sie zu den Göttern gehören will, von denen sie abstammt, oder zu den Menschen – die sie lieben gelernt hat.', '30.08.2019', 'Eisele', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', ARRAY['High Fantasy']::text[], NULL, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Circe']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
