insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e8ae695-3d04-526a-b43d-32df8d2f99f6', 'Devils and Realist (Vol.1)', NULL, '9783551761224', 'William Twining ist ein junger Mann aus noblem Hause - gebildet und gut betucht. Natürlich liegt da die Erwartung nicht fern, dass er eines Tages eine glänzende Karriere machen wird... So lebt er mit seinen Wünschen und Träumen, bis er erfährt, dass sein Onkel und Vormund das Familienvermögen durchgebracht hat! William hat jetzt nur noch eines in dieser Welt: eine alte, marode Villa und ein Butler, der sich weigert, ihn allein zu lassen. Der finanziell angeschlagene William nimmt die Sache aber sportlich und durchsucht das Familienheim nach Schätzen, die er veräußern kann. Dabei findet er ein geheimes Zimmer und aktiviert ein magisches Siegel, welches einen Dämonen beschwört... Ein magisches Abenteuer beginnt für William, der solchem Humbug höchst skeptisch gegenübersteht!', '29.01.2013', 'Carlsen', ARRAY['Deutsch']::text[], 194, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['William Twining']::text[], '{}', '{}', 'eb24e832-fed1-5736-b174-9c54d7806155', '1', '{}', 'sheet', :'owner') on conflict do nothing;
