insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b71e219a-4d25-58da-b9ca-8e2fafc2334d', 'Wie Eulen in der Nacht', 'All the Crooked Saints', NULL, 'Jeder träumt von einem Wunder, aber nicht jeder ist bereit dafür. Wem nur noch ein Wunder helfen kann, der findet stets seinen Weg in die Wüste Colorados und zur außergewöhnlichen Familie Soria. Doch die Wunder der Sorias sind unberechenbar und wer sie aus eigener Kraft nicht vollenden kann, zahlt einen hohen Preis. Auch Daniel Soria bewirkt diese Wunder mit der Ernsthaftigkeit und Hingabe, die es braucht. Doch dann bricht er die wichtigste Regel seiner Familie: Er mischt sich in ein Wunder ein. Dadurch entfesselt er eine Magie, die seinen Tod bedeuten könnte.', '02.11.2018', 'Script5', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Colorados', '{}', ARRAY['Daniel Soria']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
