insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f7ed22ed-e73c-5839-932f-3a1d4023c155', 'Wen der Rabe ruft', 'The Raven Boys', NULL, 'Jedes Jahr im April empfängt Blue die Seelen derer, die bald sterben werden, auf dem verwitterten Kirchhof außerhalb ihrer Stadt. Bisher konnte sie sie nur spüren, nie sehen - bis in diesem Jahr plötzlich der Geist eines Jungen aus dem Dunkel auftaucht. Sein Name lautet Gansey, und dass Blue ihn sieht, bedeutet, dass sie der Grund für seinen nahen Tod sein wird. Seit Blue sich erinnern kann, lebt sie mit der Weissagung, dass sie ihre wahre Liebe durch einen Kuss töten wird. Ist damit etwa Gansey gemeint?', '09.10.2013', 'Script5', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Henrietta', '{}', ARRAY['Blue','Gansey']::text[], '{}', '{}', 'ac8f7001-768f-53d4-a0a7-5e1fc63e3a0e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
