insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6114542c-be79-58c2-a7fb-52b5ec719765', 'Ballade - Der Tanz der Feen', 'Ballade: A Gathering of Faeries', NULL, 'Auf den ersten Blick könnte man James für einen typischen Teenager halten: Er ist cool und hat stets einen lockeren Spruch auf den Lippen. Aber hinter dieser Fassade verbirgt sich ein sensibler Junge und begnadeter Musiker, der auf der Suche nach der großen Liebe ist. Als James der ebenso schönen wie geheimnisvollen Nuala begegnet, schlägt sein Herz schneller – hat er seine Traumfrau gefunden? Doch Nuala ist kein Mensch, sondern eine Fee, die nur zu James gekommen ist, um ihm ein Angebot zu unterbreiten: Sie kann aus ihm einen berühmten Künstler machen. Natürlich hat der Musenkuss seinen Preis: ein paar Jahre von James’ Leben. Schweren Herzens lehnt er ab, obwohl er sich magisch zu Nuala hingezogen fühlt. Und auch die Fee merkt, dass sie zum ersten Mal verbotene Gefühle für einen Sterblichen hegt …', '01.06.2012', 'Script5', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['James','Nuala']::text[], '{}', '{}', '10994e03-7cea-592e-8669-43318a1a6126', '2', '{}', 'sheet', :'owner') on conflict do nothing;
