insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d9e3af2b-9eb7-5139-bd3b-8bf2797305ee', 'Wer die Lilie träumt', 'The Dream Thieves', NULL, 'Mit jedem Tag, den Blue mit Gansey verbringt, fällt es ihr schwerer, sich nicht in ihn zu verlieben - obwohl sie weiß, dass ein Kuss von ihr der Grund für seinen nahen Tod sein könnte. Sie ist fasziniert von seiner leidenschaftlichen Suche nach dem verschwundenen König Glendower, und in der knisternden Hitze des Sommers kommen Blue, Gansey und die Raven Boys diesem Ziel immer näher. Vor allem Ronans Fähigkeit, Gegenstände aus seinen Träumen in die reale Welt zu bringen, lässt die Lösung greifbar werden. Doch das Spiel mit der Traumwelt ist gefährlich und Blue und ihre Freunde sind nicht die Einzigen, die sich ihre Wünsche herbeiträumen wollen … Albträume, die zum Leben erwachen, charmante Auftragskiller und eine verbotene Liebe: Meisterhaft kombiniert Spiegel-Bestsellerautorin Maggie Stiefvater die lebendige Schilderung der Realität mit übernatürlichen Elementen und schafft so eine fesselnde Geschichte, die ihre Leser von der ersten Seite an begeistern wird.', '15.09.2014', 'Script5', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Henrietta', '{}', ARRAY['Blue','Gansey']::text[], '{}', '{}', 'ac8f7001-768f-53d4-a0a7-5e1fc63e3a0e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('e158cba6-a688-561b-9100-d8cd5ec50dd0', :'owner', 'd9e3af2b-9eb7-5139-bd3b-8bf2797305ee', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fd9f3cb0-a322-5559-98aa-74510d4c457e', 'Was die Spiegel wissen', 'Blue Lily, Lily Blue', NULL, 'Es wird Hebst in Henrietta. Blue und die vier Raven Boys suchen noch immer nach dem Grab des walisischen Königs Glendower. Fast glauben sie sich am Ziel, als Adam eine beunruhigende Vision hat: Im magischen Wald Cabeswater gibt es drei Schlafende. Einer von ihnen darf unter gar keinen Umständen geweckt werden. Die Frage ist allerdings, welcher es ist und was geschieht, wenn er trotz aller Vorsicht aufwachen sollte. Währenddessen hat Blue ganz andere Sorgen: Ihre Mutter ist verschwunden und außer einer mysteriösen Nachricht gibt es keine Spur von ihr. Und dann sind da noch Blues Gefühle für Gansey, gegen die sie vergeblich anzukämpfen versucht. Denn ein Kuss von ihr könnte seinen Tod bedeuten ... Eine mysteriöse Prophezeiung, uralte Geheimnisse und eine Liebe, die gefährlich ist: Maggie Stiefvater zieht auch im dritten Band der fantastischen Buchreihe um Blue und die Raven Boys alle Register ihrer Erzählkunst und hinterlässt den Leser in atemlosem Warten auf das große Finale.', '21.09.2015', 'Script5', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Henrietta', '{}', ARRAY['Blue','Gansey']::text[], '{}', '{}', 'ac8f7001-768f-53d4-a0a7-5e1fc63e3a0e', '3', '{}', 'sheet', :'owner') on conflict do nothing;
