insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('294bb752-ade5-5f47-9ddc-aafe8168f11f', 'Schimmert die Nacht', 'Sinner', NULL, 'Nach einer längeren Zeit der Trennung hat Isabel den Schmerz über die gescheiterte Liebe zu dem unberechenbaren Ex-Rockstar Cole endlich überwunden und konzentriert sich auf ihr neues Leben in L.A. An Cole denkt sie selten. Als er plötzlich vor ihr steht, beginnt ein nerven- und gefühlsaufreibendes Spiel aus unwiderstehlicher Anziehung und abgrundtiefer Abneigung. Cole ist hinreißend und verführerisch wie immer, und Isabel kann seinem Charme nur schwer standhalten. Doch zugleich fürchtet sie, dass seine dunkle Vergangenheit wieder Macht über ihn erlangt. Deshalb hat sie sich geschworen, sich nicht noch einmal in ihn zu verlieben, und kämpft verzweifelt gegen ihre Gefühle an. Cole hingegen tut alles, um Isabel von der Aufrichtigkeit seiner Liebe zu überzeugen. Aber eine Frage bleibt: Weshalb ist er wirklich zurückgekommen?', '09.03.2015', 'Script5', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, 'Los Angeles', '{}', ARRAY['Isabel','Cole']::text[], '{}', '{}', 'ddbc2d48-10be-57e5-af04-88da59959431', '4', '{}', 'sheet', :'owner') on conflict do nothing;
