insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e7d1bb0-def9-5ee9-a433-3ac875af1071', 'Wo das Dunkel schläft', 'The Raven King', NULL, 'Eine beängstigende Dunkelheit hat sich über die Ley-Linien gelegt und droht, den magischen Wald Cabeswater für immer zu zerstören. Für Blue und die Raven Boys beginnt damit ein Wettlauf gegen die Zeit auf der Suche nach dem Grab des sagenumwobenen Königs Glendower. Denn wenn sie es nicht finden, wird Blues Kuss für Gansey tödlich sein. Und dieser Kuss wird für beide immer unausweichlicher ...', '13.03.2017', 'Script5', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, NULL, 'Henrietta', '{}', ARRAY['Blue','Gansey']::text[], '{}', '{}', 'ac8f7001-768f-53d4-a0a7-5e1fc63e3a0e', '4', '{}', 'sheet', :'owner') on conflict do nothing;
