insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6cb945c8-30f4-579d-97f7-4340fc0ad7db', 'Lamento - Im Bann der Feenkönigin', 'Lament: The Faerie Queen’s Deception', '9783426283714', 'Eigentlich ist Deirdre eine ganz normale Sechzehnjährige – und ganz ehrlich: Sie findet ihr Leben gerade ein bisschen langweilig. Doch dann hat sie immer öfter seltsame Träume. Immer wieder taucht darin ein faszinierender Junge auf, dessen geheimnisvolle Augen Deirdre verzaubern. Als ihr Luke eines Tages leibhaftig gegenübersteht, wird Deirdres Leben ausgesprochen aufregend … aber gleichzeitig schwebt sie nun in großer Gefahr. Sind ihre Gefühle für Luke stark genug, um einen uralten Fluch zu brechen?', '01.06.2012', 'Script5', ARRAY['Deutsch']::text[], 348, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Deirdre']::text[], '{}', '{}', '10994e03-7cea-592e-8669-43318a1a6126', '1', '{}', 'sheet', :'owner') on conflict do nothing;
