insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8797f3fd-1f2d-5ff4-8995-f337a126d3b9', 'Nach dem Sommer', 'Shiver', '9783839001080', 'Jeden Winter wartet Grace darauf, dass die Wölfe nach Mercy Falls zurückkehren - und mit ihnen der Wolf mit den goldenen Augen. Ihr Wolf.Ganz in der Nähe und doch unerreichbar, lebt Sam ein zerrissenes Leben: In der Geborgenheit seines Wolfsrudels trotzt er Eis, Kälte und Schnee, bis die Wärme des Sommers ihn von seiner Wolfsgestalt befreit. Es ist September, als Grace und Sam sich verlieben. Doch jeder Tag, der vergeht, bringt den Winter näher - und mit ihm den endgültigen Abschied.', '01.09.2010', 'Script5', ARRAY['Deutsch']::text[], 421, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Mercy Falls', '{}', ARRAY['Grace','Sam']::text[], '{}', '{}', 'ddbc2d48-10be-57e5-af04-88da59959431', '1', '{}', 'sheet', :'owner') on conflict do nothing;
