insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('adc065bc-bba0-53ea-95ed-20da0eb69e63', 'Ruht das Licht', 'Linger', '9783839001189', 'Sam hat den Wolf in sich besiegt und ist zu Grace zurückgekehrt. Doch nun ist sie es, die nachts die Stimmen der Wölfe hört und weiß: Sie rufen nach ihr. Sam ahnt, dass sie der Aufforderung eines Tages folgen wird ... Wogegen Grace sich mit aller Macht wehrt, wäre Cole hochwillkommen. Die Wolfsgestalt ist seine Zuflucht, denn Cole wünscht sich nur eines: vergessen. Als Coles Vergangenheit ihn einholt und sich immer mehr neugierige Augen auf die Wölfe richten, schwebt das Rudel in größter Gefahr.', '01.09.2011', 'Script5', ARRAY['Deutsch']::text[], 398, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Mercy Falls', '{}', ARRAY['Grace','Sam']::text[], '{}', '{}', 'ddbc2d48-10be-57e5-af04-88da59959431', '2', '{}', 'sheet', :'owner') on conflict do nothing;
