insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a2a9a825-85b8-537e-b631-2388d84f3a6c', 'In deinen Augen', 'Forever', '9783839001264', 'Der Frühling kehrt zurück nach Mercy Falls und mit dem Winter streifen die Wölfe ihre Pelze ab. Sam, nun fest in seiner menschlichen Haut verankert, hat die vergangenen Monate nur auf diesen Moment gewartet: Grace'' Rückkehr aus dem Wald. Doch ihr Glück währt kurz. Als man ein Mädchen findet, das von Wölfen getötet wurde, verfällt Mercy Falls in Hysterie. Auf einer Treibjagd sollen die Wölfe ein für alle Mal ausgerottet werden. Nun ist es an Sam, sein Rudel - seine Familie - zu retten. Zusammen mit Grace, Cole und Isabel fasst er einen verzweifelten Plan: Sie wollen die Wölfe umsiedeln, in ein Waldgebiet weit entfernt von menschlichen Siedlungen. Sam weiß, dass er dafür einen hohen Preis zahlen wird. Denn damit das Rudel ihm folgt, muss er seine menschliche Gestalt aufgeben.', '15.08.2012', 'Script5', ARRAY['Deutsch']::text[], 490, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, NULL, 'Mercy Falls', '{}', ARRAY['Grace','Sam']::text[], '{}', '{}', 'ddbc2d48-10be-57e5-af04-88da59959431', '3', '{}', 'sheet', :'owner') on conflict do nothing;
