insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d3f19cb-5fb4-5e2e-897a-cea304968d42', 'The Villainess is a Marionette (Vol.1)', '악녀는 마리오네트', '9783910530959', 'Schönheit ist Macht - das denkt die naive Kayena Hill zumindest, bis ihr Bruder, der tyrannische Prinz Regef, ihr offenbart, dass er sie nur für seine Zwecke benutzt hat, und sie eines elenden Todes stirbt. Ohne Erinnerungen an ihr früheres Leben wird sie in Korea wiedergeboren, wo sie in einem Fantasy-Roman von einer gewissen Kayena liest, mit der sie sich sehr verbunden fühlt. Denn diese führt ein fremdbestimmtes Leben als Marionette anderer ... und wird letztlich ermordet. Als Kayena ein weiteres Mal plötzlich aufwacht und sich wieder in ihrem alten Leben befindet beschließt sie, ihr Wissen über die Zukunft aus dem Roman zu nützen und die Fäden selbst in die Hand zu nehmen ...', '15.04.2024', 'Papertoons', ARRAY['Deutsch']::text[], 272, NULL, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Kayena Hill']::text[], '{}', '{}', 'a94102e4-1eca-53cd-ada2-9d6cf6119ee8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
