insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3dd2a4a8-eb44-531e-a4eb-c3d31e84e88a', 'Götterfunke - Liebe mich nicht', NULL, NULL, 'Eigentlich wünscht Jess sich für diesen Sommer nur ein paar entspannte Wochen in den Rockys. Doch dann trifft sie Cayden, den Jungen mit den smaragdgrünen Augen, und er stiehlt ihr Herz. Aber Cayden verfolgt seine eigenen Ziele. Der Göttersohn hat eine Vereinbarung mit Zeus. Nur wenn er ein Mädchen findet, das ihm widersteht, gewährt Zeus ihm seinen sehnlichsten Wunsch: endlich sterblich zu sein. Wird Cayden im Spiel der Götter auf Sieg setzen, auch wenn es Jess das Herz kostet?', '20.02.2017', 'Dressler', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Jess','Cayden']::text[], '{}', '{}', '8f726c3d-0f8c-5550-8235-491ca7f942a5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
