insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2143d9f6-76a3-53be-a7a1-1c74400e16a1', 'Black Out', NULL, '9781784161880', 'Tomorrow will be too late. A cold night in Milan, Piero Manzano wants to get home. Then the traffic lights fail. Manzano is thrown from his Alfa as cars pile up. And not just on this street – every light in the city is dead. Across Europe, controllers watch in disbelief as electricity grids collapse. Plunged into darkness, people are freezing. Food and water supplies dry up. The death toll soars. Former hacker and activist Manzano becomes a prime suspect. But he is also the only man capable of finding the real attackers. Can he bring down a major terrorist network before it’s too late?', '15.04.2013', 'Black Swan', ARRAY['Englisch']::text[], 431, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', '{}', NULL, 'Gegenwart'::time_period, 'Europa', '{}', ARRAY['Piero Manzano']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('8a6e250d-d29f-59f0-af2e-2ac4e5fa7546', :'owner', '2143d9f6-76a3-53be-a7a1-1c74400e16a1', 'tbr'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1000, NULL, NULL, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2decbf69-d1e8-5ffd-b6dc-605b28875a74', 'Heart & Shadow', NULL, '9783751761352', 'Mordfälle erschüttern die Hauptstadt Sartins, gefährliche Tierwesen greifen Menschen an. Die 24-jährige Wächterin Rah soll helfen, den mysteriösen Vorfällen ein Ende zu setzen. Denn sie kann Lebewesen von der chaotischen Energie befreien, die sie aggressiv werden lässt. Während ihrer Ermittlungen trifft sie Irin, der sie um Hilfe bei der Aufklärung des Mordes an seinem besten Freund bittet. Doch Rah bemerkt sofort die seltsame Energie, die von Irin ausgeht. Und obwohl sie unsicher ist, ob sie ihm trauen kann, kann sie sich nicht gegen seine Anziehungskraft wehren... Währenddessen verzweifelt Shina, Studentin an einer staatlichen Akademie, an der Veränderung ihrer besten Freundin. Seit dem Tod ihrer Mutter verschwindet Mae Nacht für Nacht und taucht mit unerklärlichen Malen auf der Haut wieder auf. Legt Mae dieses Verhalten nicht ab, könnte das für sie beide den Rauswurf bedeuten. Als Shina eines Nachts Maes Geheimnis enthüllt, wird ihr Verständnis von richtig und falsch zerrüttet. Und sie muss sich fragen: Wie weit will sie für ihre Freundin gehen?', '25.10.2025', 'Lübbe', ARRAY['Deutsch']::text[], 621, 84, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, NULL, 'Sartin', '{}', ARRAY['Rah','Shina']::text[], '{}', '{}', 'a5356f9f-0e00-51aa-90d7-ce1d9326ddac', '1', '{}', 'sheet', :'owner') on conflict do nothing;
