insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e8cd6e0b-54de-559d-b7be-9ee0fbd3d41a', 'Legend - Fallender Himmel', 'Legend', '9783732000098', 'Eine Welt voller Unterdrückung. Rachegefühle, die durch falsche Anschuldigungen immer weiter genährt werden. Und eine grenzenlose Liebe, die dem Hass entgegentritt. Das ist die Geschichte von Day und June. Getrennt sind sie erbitterte Gegner, aber zusammen sind sie eine Legende!', '01.06.2013', 'Loewe', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Dystopie']::text[], NULL, 'Zukunft'::time_period, NULL, '{}', ARRAY['Day','June']::text[], '{}', '{}', '5aa51d23-99fa-5a00-9e9b-52ed754006c1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
