insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2996fd68-1e35-5738-b99d-6b10bd5b9cf9', 'Legend - Schwelender Sturm', 'Prodigy', '9783732000111', 'Der Zweck heiligt die Mittel, oder? Den einen Menschen loszuwerden, der die Verantwortung für dieses ganze verfluchte System trägt, scheint mir ein ziemlich kleiner Preis dafür zu sein, eine Revolution in Gang zu setzen. Auf der Flucht vor der Republik schließen sich June und Day den Patrioten an, um Days Bruder zu retten und in die Kolonien zu entkommen. Doch die Patrioten fordern eine Gegenleistung: June und Day sollen Anden, den neuen Elektor, töten. Eine Tat, die all dem Unrecht und der brutalen Unterdrückung ein Ende bereiten könnte. Als June jedoch begreift, dass der neue Elektor ganz anders ist als sein Vorgänger, beginnt sie zu zweifeln: Was, wenn Anden einen neuen Anfang darstellt? Was, wenn politische Veränderung nicht unbedingt Tod, Vergeltung und Gewalt bedeuten muss? Was, wenn die Patrioten falsch liegen?', '16.09.2013', 'Loewe', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Dystopie']::text[], NULL, 'Zukunft'::time_period, NULL, '{}', ARRAY['Day','June']::text[], '{}', '{}', '5aa51d23-99fa-5a00-9e9b-52ed754006c1', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('441dceb2-dbbb-5dd1-a5b5-a49e9cb3cd3d', :'owner', '2996fd68-1e35-5738-b99d-6b10bd5b9cf9', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d2d969a3-e696-55c1-99fc-565be8b5a944', 'Legend - Berstende Sterne', 'Champion', '9783732001873', 'Machen sie ihre Drohungen wahr, wird das zahllose unschuldige Menschen das Leben kosten. Und das könnten wir verhindern, indem wir ein einziges Leben aufs Spiel setzen. Day und June haben so viel geopfert für die Republik und füreinander. Nun scheint das Land endlich vor einem Neubeginn zu stehen. June arbeitet mit dem Elektor und führenden Politikern zusammen, während Day einen hohen Rang beim Militär bekleidet. Keiner der beiden hätte die Umstände vorhersehen können, unter denen sie wieder zusammenfinden. Gerade als ein Friedensabkommen unmittelbar bevorsteht, drohen Anschuldigungen einen erneuten Krieg heraufzubeschwören. Um das Leben tausender Menschen zu retten, soll June nun Day darum bitten, das zu opfern, was ihm am meisten bedeutet ...', '21.07.2014', 'Loewe', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Dystopie']::text[], NULL, 'Zukunft'::time_period, NULL, '{}', ARRAY['Day','June']::text[], '{}', '{}', '5aa51d23-99fa-5a00-9e9b-52ed754006c1', '3', '{}', 'sheet', :'owner') on conflict do nothing;
