insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fbe25321-08e9-56c2-8add-9b03e5688436', 'Spiel der Macht', 'The Winner''s Curse', '9783646928099', 'Als Tochter des ranghöchsten Generals von Valoria hat die siebzehnjährige Kestrel nur zwei Möglichkeiten: der Armee beizutreten oder jung zu heiraten. Aber Kestrel hat fürs Kämpfen wenig übrig; für sie ist die Musik das kostbarste Gut. Einem plötzlichen Impuls folgend ersteigert sie den Sklaven Arin, der sie auf unerklärliche Weise fasziniert. Schon bald muss sie sich eingestehen, dass sie mehr für ihn empfindet, als sie sollte. Doch er hat ein Geheimnis – und der Preis, den sie schließlich für ihn zahlt, wird ihr Herz sein …', '28.09.2018', 'Carlsen', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, 'Valoria', '{}', ARRAY['Kestrel','Arin']::text[], '{}', '{}', 'c1df94c1-ea50-5925-95ba-ee972e2410d7', '1', '{}', 'sheet', :'owner') on conflict do nothing;
