insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('699b5c55-d527-5df0-96a4-5eea2e9ea159', 'Die Nebel von Avalon', 'The Mists of Avalon', '9783810526045', 'Morgaine, die Hohepriesterin des Nebelreichs Avalon und Schwester von Artus, erzählt die wahre Geschichte ihres königlichen Bruders und der Ritter der Tafelrunde. Zum ersten Mal schildert eine Frau diese Geschichte, zeigt die Heldengestalten in einem neuen Licht und erinnert daran, dass einst Frauen die Macht in den Händen hielten: Sie lenken im Verborgenen das Geschick ihrer Zeit und setzen den König der Legenden auf den Thron, geben ihm das heilige Schwert Excalibur.', '1982', 'Krüger', ARRAY['Deutsch']::text[], 1116, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Avalon', '{}', ARRAY['Morgaine']::text[], '{}', '{}', '766eadfd-a434-5610-9491-e85bcee03ccf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
