insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('90c10515-498c-5d35-bf7e-a75d91b90b40', 'Wie Monde so silbern', 'Cinder', NULL, 'Cinder lebt mit ihren Stiefschwestern bei ihrer schrecklichen Stiefmutter und versucht verzweifelt, sich nicht unterkriegen zu lassen. Doch als eines Tages niemand anderes als Prinz Kai in ihrer Werkstatt auftaucht, steht Cinders Welt Kopf: Warum braucht der Prinz ihre Hilfe? Und was hat es mit dem plötzlichen Besuch der Königin von Luna auf sich? Die Ereignisse überschlagen sich, bis sie auf dem großen Schlossball ihren Höhepunkt finden. Cinder schmuggelt sich dort ein und verliert mehr als nur ihren Schuh …', '20.12.2013', 'Carlsen', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', ARRAY['Cinder','Kai']::text[], '{}', '{}', 'f50f8a83-c3d1-5d06-83dd-66b6aa4a6446', '1', '{}', 'sheet', :'owner') on conflict do nothing;
