insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ccc3c3da-b51d-5ae6-839b-618bdb95b7d7', 'Wie Blut so rot', 'Scarlet', NULL, 'Zwei ganze Wochen ist Scarlets Großmutter nun schon verschwunden. Entführt? Tot? Die Leute im Dorf sagen, sie sei sicher abgehauen. Sie sei ja sowieso verrückt. Aber für Scarlet ist Grandmère alles – von ihr hat sie gelernt, wie man ein Raumschiff fliegt, Bio-Tomaten anbaut und seinen Willen durchsetzt. Dann trifft Scarlet einen mysteriösen Straßenkämpfer – Wolf. Er fasziniert sie; doch kann sie ihm trauen? Immerhin: Die reißerischen Berichte über Cinder und das Attentat auf Prinz Kai hält Wolf ebenso wie sie für Quatsch. Aber irgendein Geheimnis verbirgt der Fremde …', '24.01.2014', 'Carlsen', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', ARRAY['Scarlets','Wolf']::text[], '{}', '{}', 'f50f8a83-c3d1-5d06-83dd-66b6aa4a6446', '2', '{}', 'sheet', :'owner') on conflict do nothing;
