insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3400c47e-d03d-5da4-a874-b71257b553d4', 'Das Buch der gelöschten Wörter - Der erste Federstrich', NULL, '9783404179800', 'Nichts tut die Londonerin Hope Turner lieber, als sich in die Welten ihrer Lieblingsautorin Jane Austen zu träumen. Denn ihr eigenes Leben ist alles andere als spannend und romantisch. Das ändert sich, als sie eines Tages in einer Buchhandlung einen mysteriösen Fremden kennenlernt, der ihr Unglaubliches offenbart: Es gibt eine Welt der Bücher, in der die Romanfiguren ein Eigenleben führen. Doch sie ist in Gefahr, und nur Hope kann sie retten!', '30.04.2020', 'Lübbe', ARRAY['Deutsch']::text[], 414, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Hope Turner']::text[], '{}', '{}', '064505cd-4a75-5779-acce-4af89c2eece8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
