insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8ec56fe1-65ce-5c11-8edb-34516a752916', 'Das Buch der gelöschten Wörter - Zwischen den Seiten', NULL, '9783404180073', 'Die Welt der Londonerin Hope Turner steht Kopf, seit sie mit Hilfe des grimmigen Rufus Walker in die Welt ihrer Lieblingsbücher reisen kann! Doch auch Hope besitzt ein rares Talent: Sie kann das Buch der gelöschten Wörter, in dem sich alle jemals gelöschten hasserfüllten Textfragmente sammeln, von den negativen Energien bereinigen. Geschieht dies nicht und quillt das Buch über, können die Wörter reale Katastrophen auslösen. Doch eine finstere Macht hat es auf das Buch abgesehen ...', '29.06.2020', 'Lübbe', ARRAY['Deutsch']::text[], 414, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Hope Turner']::text[], '{}', '{}', '064505cd-4a75-5779-acce-4af89c2eece8', '2', '{}', 'sheet', :'owner') on conflict do nothing;
