insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ab916b20-ff94-59ff-aae3-c5a6096827c2', 'Das Buch der gelöschten Wörter - Die letzten Zeilen', NULL, '9783404180714', 'Die magische Buchwelt, in der Romanfiguren ihr eigenes Leben führen, ist für die Londonerin Hope Turner zur zweiten Heimat geworden. Doch das Geheimnis um die Buchwelt ist bedroht, und Hope hat sich dem Bund aus Menschen und Romanfiguren angeschlossen, um es zu schützen. Ihr Gegenspieler Quan Surt hat es vollbracht, die Barriere zwischen den beiden Welten zu durchbrechen. Seitdem ist es auch Buchgestalten möglich, in die reale Welt zu reisen, selbst den übelsten Bösewichten ...', '28.08.2020', 'Lübbe', ARRAY['Deutsch']::text[], 414, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Hope Turner']::text[], '{}', '{}', '064505cd-4a75-5779-acce-4af89c2eece8', '3', '{}', 'sheet', :'owner') on conflict do nothing;
