insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4aaedd66-354b-5c7b-9daf-e3a9c1773279', 'Der Kuss der Lüge', 'Kiss of Deception', '9783846602423', 'Sie befahl, und das Licht gehorchte. Auf einen Wink von ihr fielen Sonne, Mond und Sterne auf die Knie und erhoben sich wieder. Es war einmal eine Prinzessin, mein Kind, und die ganze Welt lag ihr zu Füßen... Blonde Locken, ein warmer Blick, freundlich - der eine. Dunkle Augen, braungebrannt, ein beunruhigendes Lächeln - der andere. Gleich zwei Männer sind es, die Lias Aufmerksamkeit auf sich ziehen. Es ist der erste Abend, an dem Lia als Schankmädchen in der Taverne arbeitet. Dabei ist sie eigentlich eine Prinzessin. Doch sie ist auf der Flucht, weggelaufen von zu Hause, weil sie sich nicht auf die Ehe mit einem Prinzen einlassen wollte, den sie noch nie in ihrem Leben gesehen hat. Was sie nicht ahnt: Einer der beiden Männer ist der Prinz, gegen den sie sich entschieden hat. Und der andere ein Mörder, losgeschickt, um Lia zu töten. Während Lia sich zu beiden hingezogen fühlt, ahnt sie nicht, dass sie längst in größter Gefahr schwebt ...', '30.08.2024', 'One', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Lia','Rafe']::text[], '{}', '{}', '1cb92b8b-d9af-5eb0-a839-7d90aefb18b9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7c83730e-f354-5969-996e-108868592bae', :'owner', '4aaedd66-354b-5c7b-9daf-e3a9c1773279', 'ungelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Hardcover']::text[], NULL, '{}', 2400, true, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1b31eab6-d8dd-5173-86c6-a04e1f3174c8', 'The Courting of Bristol Keats', NULL, '9783736324176', 'Nach dem Tod ihrer Eltern schafft es Bristol Keats nur mit Mühe, sich und ihre Schwestern über Wasser zu halten. Als eine angebliche Tante überraschend Hilfe verspricht, erfährt sie, dass alles, was sie über ihre Familie zu wissen glaubte, eine Lüge war, und dass ihr Vater womöglich noch am Leben ist. Um ihn zu finden, muss Bristol ins Land des Elfenkönigs Tyghan reisen. Dieser braucht ihre verborgene magische Gabe, um eine finstere Bedrohung von den Reichen Elfheims abzuwenden. Bristol taucht in eine Welt der Magie, Intrigen und Verführung am Hof der Tuatha De Danann ein und kann sich schon bald der Anziehungskraft des geheimnisvollen Elfenkönigs nicht mehr entziehen. Was Bristol nicht weiß: Tyghan ist ebenso entschlossen wie sie, ihren Vater zu finden - sei es tot oder lebendig ...', '06.12.2024', 'LYX', ARRAY['Deutsch']::text[], 720, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Elfheim', '{}', ARRAY['Bristol Keats']::text[], '{}', '{}', '5fe1c718-0203-5f43-9b24-4bcd469f458d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
