insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a5e043b2-d0c9-52e1-9f22-30e75bdc861c', 'Das Herz des Verräters', 'Heart of Betrayal', '9783846602416', 'Lia wird in den Palast von Venda verschleppt und muss um ihr Leben fürchten. Eine Flucht wäre der einzige Ausweg, scheint jedoch unmöglich. Stattdessen setzt sie alles daran, sich im Palastleben zurechtzufinden. Sie hat längst ihr Herz an einen der Männer aus der Taverne verloren, und auch erfahren, wer er wirklich ist. Doch Gut und Böse sind nicht eindeutig verteilt. Denn auch der Mann, der eigentlich ihr Feind sein müsste, stellt sich plötzlich ein ums andere Mal auf ihre Seite. Warum? Während Lia am Palast nach neuen Verbündeten sucht, wird sie immer häufiger von der Gabe der Vorsehung heimgesucht. Galt sie lange als diejenige Erstgeborene, die ohne dieses wichtige Talent geboren wurde, so zeigt sich ihr die Zukunft nun immer häufiger. Doch dieser Blick offenbar Dinge, die nicht nur ihr Schicksal, sondern auch das Schicksal eines ganzen Volkes beeinflußen könnten …', '27.09.2024', 'One', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Lia','Rafe']::text[], '{}', '{}', '1cb92b8b-d9af-5eb0-a839-7d90aefb18b9', '2', '{}', 'sheet', :'owner') on conflict do nothing;
