insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dcb3eecf-7be9-547b-bd38-24110f1936cf', 'Der Glanz der Dunkelheit', 'The Beauty of Darkness', '9783846602409', 'Lia und Rafe konnten aus Venda fliehen und reiten nun in Rafes Heimat, nach Dalbreck. Doch Lia spürt, dass sie schon viel zu lang weit weg ist von ihrem Zuhause Morrighan. Und obwohl Rafe ihr eine Zukunft als Königin an seiner Seite verspricht, entscheidet sich Lia, ihrer Bestimmung zu folgen und kehrt schweren Herzens nach Morrighan zurück. Auch wenn sie weiß, dass die Entscheidung richtig ist, ihrem Volk zur Seite zu stehen und für ihr Land zu kämpfen, quälen sie doch viele Fragen. Wird sie den verfeindeten Königreichen Frieden bringen? Wie soll sie in den Schlachten bestehen? Und kann es für sie und Rafe vielleicht doch eine gemeinsame Zukunft geben?', '25.10.2024', 'One', ARRAY['Deutsch']::text[], 784, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Lia','Rafe']::text[], '{}', '{}', '1cb92b8b-d9af-5eb0-a839-7d90aefb18b9', '3', '{}', 'sheet', :'owner') on conflict do nothing;
