insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c5d84caa-1c87-586c-a695-063812778db7', 'The last Wish of Bristol Keats', NULL, '9783736325623', 'Fast hätte Bristol ihren Geliebten, den Feenkönig Tyghan, an die Monster verloren, die ihre Mutter auf ihn losgelassen hat. Doch ihre Liebe wurde durch die überstandenen Gefahren nur noch stärker. Gemeinsam setzen sie alles daran, die Bedrohung für Elfheim abzuwenden. Als eine Rettungsmission scheitert und das Leben eines Gefährten kostet, wird Bristol klar, wie gefährlich ihre Mutter wirklich ist. Sie und Tyghan stehen vor einem Scheideweg: Der Feenkönig muss sich endlich Bristols Vater stellen, der einst sein bester Freund war und ihn in seiner dunkelsten Stunde verraten hatte, und Bristol kämpft mit der Erkenntnis, dass die Magie, die in ihr schlummert, sie in ein Monster verwandeln könnte. Beide müssen eine Wahl treffen, die sie alles kosten könnte, was ihnen lieb und teuer ist.', '19.12.2025', 'LYX', ARRAY['Deutsch']::text[], 565, 90, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Elfheim', ARRAY['Single POV','3P Limited']::text[], ARRAY['Bristol Keats']::text[], ARRAY['Found Family','Forbidden Love','The Chosen One']::text[], ARRAY['Tod von Familienangehörigen']::text[], '5fe1c718-0203-5f43-9b24-4bcd469f458d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
