insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5850e366-d173-59a9-8364-2a7401c87c97', 'Dunkle Wasser', 'The River', '9783815750940', 'Am Ende der Welt, so fühlt sich Veronica, als sie mit ihren Eltern von Portland ins ländliche Oregon zieht. Das Gefühl der Einsamkeit verstärkt sich durch die Geräuschkulisse des Santiam, des reißenden, wilden Flusses, der direkt hinter ihrem Haus entlangfließt und der zu einem düsteren Soundtrack in Veronicas neuem Leben wird. Zum Glück ist da Karen, das kleine Mädchen aus der Nachbarschaft, auf das Veronica manchmal aufpasst und die für sie immer mehr zu einer Schwester wird. Doch dann findet sie eines Tages Karens leblosen Körper am Ufer des Santiam und nichts ist mehr, wie es war. Veronica kann nicht glauben, dass das Mädchen einem Unfall zum Opfer gefallen ist, und fühlt sich verpflichtet, die Wahrheit ans Licht zu bringen. Besessen davon, Karens Tod aufzuklären, dringt sie immer tiefer in die Wälder rund um den wilden Fluss vor. Sie ahnt nicht, welch dunkles Geheimnis sich in seinen Tiefen verbirgt. Und schon bald schwebt Veronica selbst in höchster Gefahr …', '01.02.2011', 'Coppenrath', ARRAY['Deutsch']::text[], 263, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', '{}', 'NA'::audience_kind, 'Gegenwart'::time_period, 'Portland, Oregon', '{}', ARRAY['Veronica']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
