insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a9046143-67d3-5086-8381-f89c960e108f', 'Der bittere Kuss der Liebe', 'Uso To Kiss', NULL, 'In einer Bar fällt Tatsuyas Blick auf einen jungen Kellner. Fasziniert von Haru nimmt Tatsuya ihn mit zu sich nach Hause und eine zärtliche Romanze entspinnt sich. Doch als Tatsuya in dem Geliebten seinen vor Jahren verschwundenen kleinen Halbbruder zu erkennen meint, bricht er verstört den Kontakt ab. Familiengeheimnisse beginnen sich zu entwirren, ein zweiter Bruder taucht unvermittelt auf und plötzlich ist auch gar nicht mehr so sicher, ob die beiden wirklich miteinander verwandt sind. Gelingt es den beiden ihre Liebe zu retten...?', '01.12.2010', 'Carlsen', ARRAY['Deutsch']::text[], 196, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], NULL, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Tatsuya','Haru']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
