insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d612183f-abfa-5c5c-8628-420d7dfd3780', 'Naruto (Vol.1)', NULL, '9783551762511', 'Vor zwölf Jahren wurde das Dorf Konoha von einer furchterregenden Bedrohung angegriffen. Ein neunschwänziges Fuchsungeheuer forderte das Leben des Dorfvorstehers, des Hokage, und vieler anderer. Heute herrscht im Dorf Frieden und ein Tunichtgut namens Naruto wirbelt durch die Straßen! Narutos großer Traum ist es, den heldenhaften Namen Hokage zu erben und all seine Vorgänger zu übertreffen. Aber Naruto hat ein großes Geheimnis...', '15.02.2001', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Abenteuer', ARRAY['Shōnen']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Ninja Academy', ARRAY['3P Objective']::text[], ARRAY['Naruto']::text[], '{}', '{}', '0802c342-fbcd-5e54-9abd-91205a80b912', '1', '{}', 'sheet', :'owner') on conflict do nothing;
