insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('073eac1a-c279-5a68-b7fa-684d188f9bf0', 'Naruto Massiv (Vol.1)', NULL, '9783551795274', 'Naruto ist ein berüchtigter Tunichtgut in seinem Dorf, das fast ausschließlich aus Ninja besteht. Er liebt Nudelsuppe und spielt anderen gern Streiche. So ist es kein Wunder, dass er nicht gerade beliebt ist. Doch gerade deshalb will er der beste Ninja seines Dorfes werden. Zu diesem Zweck gehen er und seine Mitschüler Sasuke und Sakura beim großen Meister Kakashi in die Lehre...', '03.10.2017', 'Carlsen', ARRAY['Deutsch']::text[], 704, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Abenteuer', ARRAY['Shōnen']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Ninja Academy', ARRAY['3P Objective']::text[], ARRAY['Naruto']::text[], '{}', '{}', '0802c342-fbcd-5e54-9abd-91205a80b912', '1', '{}', 'sheet', :'owner') on conflict do nothing;
