insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('41e1b898-4cf8-50a0-abe3-18d16c94cb8b', 'Vampire Knight (Vol.1)', 'Vampaia Naito', '9783551751515', 'Die "Cross Academy" wurde gegründet, um zu beweisen, dass Menschen und Vampire in friedlicher Koexistenz leben können. Tagsüber gehen "normale" Schüler in die "Day Class" und nach Sonnenuntergang besuchen die "Eliteschüler" die "Night Class". Beim Klassenwechsel treffen die Schüler allabendlich aufeinander - ein ganz schön heikler Moment, denn die Schülerinnen der Day Class schwärmen für die heißen Jungs der Night Class, ohne von deren dunklem Geheimnis zu wissen. Oder ist es gerade der Hauch des Mysteriösen, der die Jungs so attraktiv scheinen lässt...?', '22.03.2007', 'Carlsen', ARRAY['Deutsch']::text[], 190, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
