insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('46a0695b-94a9-5374-a5bf-8ef611fbcfb2', 'Vampire Knight (Vol.2)', 'Vampaia Naito', '9783551751522', 'Zero kann sich seinen Instinkten nicht länger widersetzen, der Vampir in ihm ist erwacht. Obwohl er Yuki angegriffen hat, ist sie fest entschlossen, alles zu tun um ihm zu helfen. Doch von den Schülern der Night Class erfährt sie Beunruhigendes über Vampire, die vorher Menschen waren. Als auch noch der berühmte Vampire Hunter Toga Yagari auftaucht, der Zero schon seit seiner Jugend kennt, überstürzen sich die Ereignisse…', '28.09.2007', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
