insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('40f925b6-581a-53ad-b20e-f0f10856c3bb', 'Vampire Knight (Vol.3)', 'Vampaia Naito', '9783551751539', 'Was empfindet Yuki wirklich für Kaname Kuran? In einer Rückblende erfahren wir, wie sie, Kaname und Zero sich zum ersten Mal begegnet sind. Zero erhält von einer geheimen Regierungsorganisation den Auftrag, einen gemeingefährlichen »Level E«-Vampir auszuschalten, wobei ihm Yuki beinahe versehentlich in die Quere kommt. Bald darauf sorgt ein verspäteter Neuzugang in der Night Class für Aufregung...', '29.02.2008', 'Carlsen', ARRAY['Deutsch']::text[], 383, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
