insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9638e70f-1dee-5ea0-9122-724197144f13', 'Vampire Knight (Vol.4)', 'Vampaia Naito', '9783551751546', 'Die "Night Class" der Cross Academy besteht aus lauter gut aussehenden Schülern, die ein grauenhaftes Geheimnis verbergen: Sie sind alle Vampire! Die Schülerinnen der "Day Class" ahnen davon jedoch nichts und befinden sich gedanklich bereits bei den bevorstehenden Examensprüfungen und dem darauffolgenden Schulball. Yuki lernt währenddessen das wahre Gesicht ihrer neuen Mitschülerin Maria kennen, die ihr einen ungewöhnlichen Handel anbietet...', '01.08.2008', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '4', '{}', 'sheet', :'owner') on conflict do nothing;
