insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7fec456c-f4e9-518d-a09c-4328ecbe4047', 'Vampire Knight (Vol.6)', 'Vampaia Naito', '9783551751560', 'Zero scheint seinem Schicksal, zu einem blutrünstigen Vampir zu degenerieren, nicht entfliehen zu können. In seiner Verzweiflung gesteht er sich seine Gefühle für Yuki ein, die jedoch mit eigenen Problemen zu kämpfen hat: dem unmoralischen Angebot, das Kaname ihr gemacht hat, und ihrer dunklen Vergangenheit, in die sie endlich Licht bringen will...', '22.04.2009', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '6', '{}', 'sheet', :'owner') on conflict do nothing;
