insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eece90fe-14f1-5948-bfb2-3fcfb87a0fb3', 'Vampire Knight (Vol.7)', 'Vampaia Naito', '9783551751577', 'Die "Cross Academy" wurde gegründet, um zu beweisen, dass Menschen und Vampire in friedlicher Koexistenz leben können. Tagsüber gehen "normale" Schüler in die "Day Class" und nach Sonnenuntergang besuchen die "Eliteschüler" die "Night Class". Beim Klassenwechsel treffen die Schüler allabendlich aufeinander - ein ganz schön heikler Moment, denn die Schülerinnen der Day Class schwärmen für die heißen Jungs der Night Class, ohne von deren dunklen Geheimnis zu wissen. Oder ist es gerade der Hauch des Mysteriösen, der die Jungs so attraktiv scheinen lässt...?', '24.09.2009', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '7', '{}', 'sheet', :'owner') on conflict do nothing;
