insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8d2a3c1e-5539-5670-b83a-dbb2f1fc840f', 'Vampire Knight (Vol.8)', 'Vampaia Naito', '9783551751584', 'Kaname Kuran hielt jahrelang den Schlüssel zu Yukis Vergangenheit in der Hand. Jetzt ist es an der Zeit, Yukis Erinnerungen wiederzuerwecken und ihr Leben in völlig neue Bahnen zu lenken - denn auch Yuki gehört zum Clan der Vampire...', '17.03.2010', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '8', '{}', 'sheet', :'owner') on conflict do nothing;
