insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('232a95d7-21c7-5965-83a2-6c6c2ad367bc', 'Vampire Knight (Vol.9)', 'Vampaia Naito', '9783551751591', 'In der Cross Academy herrscht Ausnahmezustand! Nachdem das einstige Clan-Oberhaupt Rido Kuran wiederauferstanden ist, ziehen seine Untergebenen zur Academy, um ihrem Herren erneut die Ehre zu erweisen. Und was eignet sich besser als Willkommensgeschenk als ein paar süße Day-Class-Schülerinnen...? Die Eliteschule wird zum Schauplatz eines blutrünstigen Krieges - doch auf welcher Seite stehen Yuki und Zero?', '26.08.2010', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '9', '{}', 'sheet', :'owner') on conflict do nothing;
