insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f3da71ef-3509-5c6a-991e-139ecf8355a5', 'Vampire Knight (Vol.10)', 'Vampaia Naito', '9783551751607', 'Auf dem Gelände der Cross Academy spielt sich ein Bild des Grauens ab: Zwischen dem Hunter-Verband und dem Senat bricht ein Krieg aus, der nicht nur die Schülerinnen der Day Class gefährdet, sondern auch die Vampire untereinander zu Feinden macht. Ein blutrünstiger Kampf, nach dem nichts mehr so ist, wie es einmal war - und der Yuki zwingt, sich für eine Seite zu entscheiden: Kaname oder Zero?', '27.01.2011', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '10', '{}', 'sheet', :'owner') on conflict do nothing;
