insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('edcace92-2646-5e5a-bd27-40462fa1eca2', 'Vampire Knight (Vol.11)', 'Vampaia Naito', '9783551753229', 'Endlich sind Yuki und Kaname ein offizielles Liebespaar, doch schon ein Jahr nach den verheerenden Ausschreitungen an der Cross Academy bekommt ihre Beziehung Risse. Kaname beichtet Yuki seine Sünden und zweifelt, ob seine Verlobte die Berührungen derart befleckter Hände wird ertragen können. Auch Yuki muss sich selbst und ihrem geliebten Kaname endlich eingestehen, wer noch immer einen wichtigen Platz in ihrem Herzen einnimmt...', '24.06.2011', 'Carlsen', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Cross Academy', ARRAY['3P Objective']::text[], ARRAY['Yuki','Zero','Kaname']::text[], ARRAY['Forbidden Love','Family Drama','High School','Dark Secrets']::text[], '{}', 'bb26670f-6173-57fb-99ff-459538189a5b', '11', '{}', 'sheet', :'owner') on conflict do nothing;
