insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d5fdbc87-3752-54f9-9e52-bfeb0f92ae72', 'The Gate of the Feral Gods', NULL, NULL, 'Surviving in a multilevel dungeon that also happens to be the set of the galaxy’s most watched game show has taught Carl and his ex-girlfriend’s cat, Princess Donut, that there’s only one thing they can count on apart from each other: they never know what’s coming next. And this floor is no exception. A floating fortress occupied by warrior gnomes. A castle made of sand. A derelict submarine guarded by malfunctioning machines. A haunted crypt surrounded by lethal traps. It was supposed to be straightforward. One bubble. Four castles. Fifteen days. Capture each one, and the stairwell is unlocked. Going it alone is not an option this time, so Carl and his team must rely on the help of the low-level, I-can’t-believe-these-idiots-are-still-alive crawlers trapped in the bubble with them.', '01.07.2021', 'Dandy House', ARRAY['Englisch']::text[], 586, 34, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['LitRPG']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Dungeon', ARRAY['Single POV','1P']::text[], ARRAY['Carl']::text[], ARRAY['Post-Apocalypse','Alien Encounter']::text[], ARRAY['Physische Gewalt','Gore','Tod','Body Horror']::text[], '18d2b2a9-5bc9-5f41-bf79-5a01a86bf104', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7c252554-192a-5d41-a804-ecafee517d52', :'owner', 'd5fdbc87-3752-54f9-9e52-bfeb0f92ae72', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['Map']::text[], 499, true, false, ARRAY['Audible']::text[], ARRAY['Jeff Hays']::text[], 1083, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Ich finde es immer noch super witzig und das Ende hat mir den nächsten Band wirklich noch mal schmackhafter gemacht. Ansosnten ist es mir ein wenig zu widerholend. Es passiert immer wieder dasselbe und so langsam hätte ich gerne ein wenig Abwechslung.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('55c5926f-97f9-584e-a701-2ba794821324', '7c252554-192a-5d41-a804-ecafee517d52', :'owner', 1, '2026-08-27', '2026-09-03', NULL, NULL, 8, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c21bda47-3119-587a-9513-a843941894d0', 'Carl''s Doomsday Scenario', NULL, NULL, 'Now on the third floor of the dungeon, Carl and Princess Donut must fight harder than ever. They''ve already proven that a Coast Guard vet and once-and-forever feline royalty are an almost unstoppable team. Their ratings are off the chart and the watchers can''t get enough. But the dungeon gets more dangerous each day, and now there''s a whole new problem to deal with . . . Side quests. They call this level the Over City. A sprawling, once-thriving metropolis devastated by a mysterious calamity. But these streets are far from abandoned. An undead circus trawls the ruins. Murdered women rain from the sky. And an ancient spell is finally ready to reveal its dark purpose. Can Carl and Donut survive this level in time? And can Carl finally find some pants?', '06.01.2026', 'Dandy House', ARRAY['Englisch']::text[], 356, 25, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['LitRPG']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Dungeon', ARRAY['Single POV','1P']::text[], ARRAY['Carl']::text[], ARRAY['Post-Apocalypse','Alien Encounter']::text[], ARRAY['Physische Gewalt','Gore','Tod','Body Horror']::text[], '18d2b2a9-5bc9-5f41-bf79-5a01a86bf104', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('b9fdfadf-bd28-59a4-bf92-8e4dfc69eac5', :'owner', 'c21bda47-3119-587a-9513-a843941894d0', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 390, true, false, ARRAY['Audible']::text[], ARRAY['Jeff Hays']::text[], 688, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Es geht genauso gut weiter. Am meisten gefallen haben mir die herzerwärmenden Momente zwischen Carl und Donut.') on conflict do nothing;
