insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6545f7c6-4b9d-506f-9b73-0d868ed0fc62', 'The Dungeon Anarchist''s Cookbook', NULL, NULL, 'Earth has been transformed into the set of the galaxy’s most watched game show: Dungeon Crawler World, a nightmarish, multilevel, video game–like dungeon filled with traps, monsters, and mind-bending puzzles. Carl and Donut have survived so far, but this fourth level is unlike anything they could imagine. The Iron Tangle: an impossibly complicated subway system tied together into a knot of trains of all kinds, from classic steam engines to sleek modern cars. Up is down. Down is up. Close is far. The cars are filled with monsters, the railway stations aren’t always what they seem, and the exit is perpetually just a few stops away. The top ten list is populated, and Carl and Donut have made it. But that popularity comes with a price. They each now have a bounty on their head. They must work with other crawlers to solve the puzzle of the floor, but how can they do that when they don’t know who to trust? The secret to unraveling it all may be hidden in the pages of a seemingly useless book.', '02.04.2021', 'Dandy House', ARRAY['Englisch']::text[], 526, 34, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['LitRPG']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Dungeon', ARRAY['Single POV','1P']::text[], ARRAY['Carl']::text[], ARRAY['Post-Apocalypse','Alien Encounter']::text[], ARRAY['Physische Gewalt','Gore','Tod','Body Horror']::text[], '18d2b2a9-5bc9-5f41-bf79-5a01a86bf104', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('692618d1-bee4-52e7-a023-b3298e22cacb', :'owner', '6545f7c6-4b9d-506f-9b73-0d868ed0fc62', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 383, true, false, ARRAY['Audible']::text[], ARRAY['Jeff Hays','The Critical Drinker']::text[], 1014, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Für mich bisher der schlechteste Band. Trotzdem noch sehr gut. Die Location war mir nur etwas zu verwirrend und es war alles etwas zu widerholend. Trotzdem gab es wirklich spannende Twists und es war immer noch extrem witzig.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('5868a44b-7e5b-5b43-a808-d00e52ecc31f', '692618d1-bee4-52e7-a023-b3298e22cacb', :'owner', 1, '2026-08-12', '2026-08-25', NULL, NULL, 14, false, 'audio'::read_mode) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f84f4950-72e1-5019-b798-5b8e0064031f', 'Dungeon Crawler Carl', NULL, '9780593820254', 'You know what’s worse than breaking up with your girlfriend? Being stuck with her prize-winning show cat. And you know what’s worse than that? An alien invasion, the destruction of all man-made structures on Earth, and the systematic exploitation of all the survivors for a sadistic intergalactic game show. That’s what. Join Coast Guard vet Carl and his ex-girlfriend’s cat, Princess Donut, as they try to survive the end of the world—or just get to the next level—in a video game–like, trap-filled fantasy dungeon. A dungeon that’s actually the set of a reality television show with countless viewers across the galaxy. Exploding goblins. Magical potions. Deadly, drug-dealing llamas. This ain’t your ordinary game show.', '02.10.2020', 'Dandy House', ARRAY['Englisch']::text[], 427, 47, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['LitRPG']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Dungeon', ARRAY['Single POV','1P']::text[], ARRAY['Carl']::text[], ARRAY['Post-Apocalypse','Alien Encounter']::text[], ARRAY['Physische Gewalt','Gore','Tod','Body Horror']::text[], '18d2b2a9-5bc9-5f41-bf79-5a01a86bf104', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ddb35074-dccd-532a-9969-895260c6a4ad', :'owner', 'f84f4950-72e1-5019-b798-5b8e0064031f', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook','Print']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', '{}', 499, true, false, ARRAY['Audible']::text[], ARRAY['Jeff Hays']::text[], 811, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 0, 'no'::burn_kind, 'Wow, wow, wow. Ich bin kein Gamer und trotzdem hat mich dieses Buch so sehr begeistert. Es ist mal was ganz anderes und ich liebe die Charaktere, die Idee und den Humor. Ich bin sehr gespannt, wie es weiter geht.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('3388f528-5420-54da-91db-7e454311b565', 'ddb35074-dccd-532a-9969-895260c6a4ad', :'owner', 1, '2026-08-06', '2026-08-10', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('53070be2-a331-5712-b3cc-33172e3a825d', 'The Butcher''s Masquerade', NULL, NULL, 'A lush jungle teeming with danger. Savage dinosaurs seeking blood. A fallen princess intent on vengeance. A mysterious, end-of-floor celebration for the top crawlers, dubbed “The Butcher’s Masquerade.” The sixth floor. The Hunting Grounds. As the remaining crawlers battle for their lives, a new, terrible threat looms. Outside tourists are finally allowed to enter the game, and they are here and ready to hunt. Among them is Vrah, a famed and veteran hunter, intent on collecting the biggest trophy of her career. But their prey is far from harmless, and this season they are fighting back.', '28.02.2022', 'Dandy House', ARRAY['Englisch']::text[], 726, 77, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['LitRPG']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'Dungeon', ARRAY['Single POV','1P']::text[], ARRAY['Carl']::text[], ARRAY['Post-Apocalypse','Alien Encounter']::text[], ARRAY['Physische Gewalt','Gore','Tod','Body Horror']::text[], '18d2b2a9-5bc9-5f41-bf79-5a01a86bf104', '5', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('747b7a1d-6aed-5c82-8af7-70d0a0141570', :'owner', '53070be2-a331-5712-b3cc-33172e3a825d', 'gelesen'::reading_status, true, true, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', ARRAY['In-Book Illustrationen']::text[], 399, true, false, ARRAY['Audible']::text[], ARRAY['Jeff Hays']::text[], 1413, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Dieser Teil hat mir noch mal um einiges besser gefallen, als die zwei davor. Wahrscheinlich weil es ein paar sehr emotionale und deepe Szenen gab.') on conflict do nothing;
