insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9172422e-c884-55d4-aea0-fa0342bccf6a', 'Echo Boy', NULL, NULL, '»Vor zwei Wochen wurden meine Eltern getötet. Seitdem hat sich alles verändert. Absolut alles. Das Einzige, was immer noch wahr ist: Ich bin immer noch ich. Ein Mensch namens Audrey Castle.« Audrey lebt in einer Welt, die von moderner Technik bestimmt wird und in der künstliche Menschen, die sogenannten »Echos« , darauf programmiert sind, jeden Befehl ihres Besitzers auszuführen. Eines Tages passiert das Unfassbare: Ein scheinbar defekter Echo tötet Audreys Eltern. Mit knapper Not kann sie entkommen und findet Unterschlupf bei ihrem Onkel. Dort trifft sie auf Daniel. Daniel ist ein Echo – und er fühlt sich zu Audrey hingezogen, etwas, das eigentlich nicht sein kann. Doch er will sie beschützen. Denn Audrey schwebt noch immer in Lebensgefahr...', '09.12.2016', 'dtv', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', '{}', 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Audrey','Daniel']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
