insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('91ef387e-08f0-5bc4-8540-0051981ddb5e', 'Friends, Lovers and the Big Terrible Thing', NULL, '9783431050387', 'Durch sein Mitwirken in der US-Kultserie FRIENDS erreichte der Schauspieler Matthew Perry Weltruhm. Erstmals erzählt er nun seine eigene außergewöhnliche Geschichte und spricht offen über private Suchtkämpfe und darüber, was sich tatsächlich hinter den Kulissen der erfolgreichsten Sitcom aller Zeiten abspielte. Der TV-Star gewährt tiefe Einblicke in seine langjährige Erkrankung und reflektiert gewohnt humorvoll und selbstkritisch, was die Süchte eines Mannes befeuert hat, dem es an nichts zu mangeln schien. Unerschrocken ehrlich, zutiefst bewegend und urkomisch.', '01.11.2022', 'Lübbe', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Biografie & Autobiografie', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Matthew Perry']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
