insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6aa69513-0aaf-533b-b393-0eb64bf6cb06', 'Sugar Soldier (Vol.1)', 'Shugā Sorujā', '9783842007161', 'Ihr Leben lang hat Makoto im Schatten ihrer wunderschönen Schwester gefristet, die als Model arbeitet. Mit dem Wechsel auf die Highschool soll damit endlich Schluss sein! Um ihre Komplexe loszuwerden und genauso schön und selbstbewusst zu werden ihre Schwester, will sich Makoto richtig reinhängen. Als jedoch zunächst alles schiefläuft, eilt ihr Shun zu Hilfe, der noch cooler werden will, als er eh schon ist. Und so schließen die beiden eine Wette darüber ab, wer sein Ziel als Erstes erreicht ...', '12.03.2013', 'TokyoPop', ARRAY['Deutsch']::text[], 196, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Shōjo']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Makoto','Shun']::text[], '{}', '{}', 'b054a43f-396e-5676-8a3f-4077921edf97', '1', '{}', 'sheet', :'owner') on conflict do nothing;
