insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('768a483a-fc3f-58ff-b854-2033cc4fa4f4', 'Love Chains (Vol.1)', NULL, '9783770475001', 'Shota und Miono verbindet seit Kindertagen eine enge Freundschaft und vor allem Shotas Gefühle gehen noch viel tiefer. Als plötzlich ein Dämon Besitz von Shota ergreift, droht das Rad des Schicksals, bereits vor Jahrhunderten in Gang gesetzt, die beiden mit sich zu reißen. Die Mischung aus packender Fantasy, gefühlvoller Romantik und Mayu Shinjos schickem Zeichenstil sind einfach faszinierend und zeigen die Vielseitigkeit der Starautorin! Echtes Lesevergnügen in einer zweibändigen Reihe.', '07.07.2011', 'Egmont Manga', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Shōjo']::text[], NULL, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Shota','Miono']::text[], '{}', '{}', 'bc6ad597-6c4d-5949-8d5a-af397df327e5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
