insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('46fab092-da95-5185-bd25-171ccddc2658', 'Little Lies - Wer einmal lügt, dem glaubt man nicht', 'The Perfect Stranger', '9783328102441', 'Die Journalistin Leah flieht vor ihrem alten Leben: Sie lässt ihre Heimat und ihren Job hinter sich und zieht mit ihrer besten Freundin Emmy in ein altes Haus auf dem Land. Das Zusammenleben klappt gut. Leah arbeitet tagsüber in der Schule, Emmy nachts an einer Rezeption. Doch dann stellt Leah eines Nachts fest, dass sie ihre Freundin seit Tagen nicht gesehen hat. Noch bevor sie Emmy als vermisst melden kann, wird in der Nähe eine brutal misshandelte junge Frau gefunden. Doch die Frau ist nicht Emmy – stattdessen sieht sie Leah zum Verwechseln ähnlich … Muss Leah nicht nur um Emmys, sondern auch um ihr eigenes Leben fürchten?', '20.01.2020', 'Penguin', ARRAY['Deutsch']::text[], 364, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Leah']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
