insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9df09bf7-0b44-5ae7-a1bf-f5eb72c1d319', 'Girl, Serpent, Thorn', NULL, '9781250764942', 'There was and there was not, as all stories begin, a princess cursed to be poisonous to the touch. But for Soraya, who has lived her life hidden away from everyone, apart from her family, safe only in her gardens, it''s not just a story. As the day of her twin brother''s wedding approaches, Soraya must decide if she''s willing to step outside of the shadows for the first time. Below in the dungeon is a demon who holds knowledge that she craves, the answer to her freedom. And above is a young man who isn''t afraid of her, whose eyes linger not with fear, but with an understanding of who she is beneath the poison.Soraya thought she knew her place in the world, but when her choices lead to consequences she never imagined, she begins to question who she is and who she is becoming . . . human or demon.', '07.07.2020', 'Macmillan', ARRAY['Englisch']::text[], 336, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Soraya']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
