insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e965362-6fbc-5bc0-8f55-cf80c52ff8b7', 'A Broken Blade', NULL, '9781454949985', 'Keera is a killer. As the King''s Blade, she is the most talented spy in the kingdom. And the king''s favoured assassin. When a mysterious figure moves against the Crown, Keera is called upon to hunt down the so-called Shadow. She tracks her target into the magical lands of the Fae, but Faeland is not what it seems . . . and neither is the Shadow. Keera is shocked by what she learns, and can''t help but wonder who her enemy truly is: the King that destroyed her people or the Shadow that threatens the peace?', '15.12.2021', 'Union Sqaure & Co', ARRAY['Englisch']::text[], 433, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Keera']::text[], '{}', '{}', 'ed114f9d-d587-535f-9481-025686a005d4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
