insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('54807169-9363-5e88-b488-4898be07ec76', 'No Longer Yours', NULL, '9783736317871', 'Avery kann ihr Glück kaum fassen: Sie hat tatsächlich eins der begehrten Zimmer der Mulberry Mansion ergattert! In einem Wohnprojekt der Universität sollen Studierende die alte englische Villa wieder instand setzen. Aber Averys Freude wird jäh gedämpft, als sie feststellen muss, dass einer ihrer Mitbewohner kein anderer ist als ihr Ex-Freund Eden, der ihr vor zwei Jahren beim Abschlussball das Herz brach. Aus dem warmherzigen Jungen von damals ist ein verschlossener junger Mann geworden, der alle auf Abstand hält. Doch während sie gemeinsam die Mulberry Mansion renovieren, kommen plötzlich Gefühle hoch, über die Avery eigentlich längst hinweg war, oder etwa nicht?', '26.08.2022', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Mulberry Mansion', '{}', ARRAY['Avery','Eden']::text[], '{}', '{}', '5dd62ff5-22c4-58c4-9978-dabb8c184dea', '1', '{}', 'sheet', :'owner') on conflict do nothing;
