insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('64580b0d-97bb-56a1-b4dd-7c8b5f719650', 'No Longer Lost', NULL, '9783736318113', 'Die Fördergelder für die Mulberry Mansion werden gekürzt! Psychologiestudentin May würde alles tun, um ihr Zuhause zu retten, selbst den einen Menschen um Hilfe bitten, den sie absolut nicht ausstehen kann - Wesley Hastings, "König" der Windsbury University und Sohn der Vizekanzlerin. Völlig überraschend willigt Wes ein, bei seiner Mutter ein gutes Wort für die Villa einzulegen - einziger Haken: May soll an seinem Psychologieexperiment teilnehmen mit der These: Kann man jeden Menschen lieben? Sie stimmt dem Deal zu, denn sie kann sich nicht vorstellen, sich in jemanden wie Wes zu verlieben. Doch durch das Projekt erkennt sie, dass hinter der Fassade des reichen Jungen so viel mehr steckt. Dennoch darf May ihre Gefühle für Wes niemals zulassen ...', '27.01.2023', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Mulberry Mansion', '{}', ARRAY['May','Wesley Hastings']::text[], '{}', '{}', '5dd62ff5-22c4-58c4-9978-dabb8c184dea', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
