insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('76cae4cc-5ddd-55a7-b199-ee1186e0c71d', 'No Longer Alone', NULL, '9783736318120', 'Willow und Maxton könnten unterschiedlicher nicht sein. Während die lebensfrohe Willow auf jede Party geht, verbringt der ruhige Maxton lieber Zeit im Garten der Mulberry Mansion. Und doch verbindet die beiden eine tiefe Freundschaft. Für Willow ist es daher selbstverständlich, dass sie Maxton dabei hilft, als er versucht, in die berüchtigte Studentenverbindung der Windsbury University aufgenommen zu werden. Dafür muss er sechs Prüfungen bestehen. Sechs Aufgaben in sechs Nächten, in denen Willow ganz neue Seiten an ihrem besten Freund entdeckt, die ihr Herz unerwartet schneller schlagen lassen. Doch auch Willow hat ein Geheimnis, von dem Maxton auf keinen Fall erfahren soll, und genau aus diesem Grund können sie niemals mehr als Freunde sein ...', '30.06.2023', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Mulberry Mansion', '{}', ARRAY['Willow','Maxton']::text[], '{}', '{}', '5dd62ff5-22c4-58c4-9978-dabb8c184dea', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
