insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a480755d-645d-5030-9272-a9cfe41a2279', 'Archers''s Voice', NULL, '9781538727379', 'I wanted to lose myself in the small town of Pelion, Maine. To forget everything I had left behind. The sound of rain. The blood. The coldness of a gun against my skin. For six months, each breath has been a reminder that I survived--and my dad didn''t. I''m almost safe again. But the moment I meet Archer Hale, my entire world tilts on its axis . . . and never rights itself again. Until I trespass into his strange, silent, and isolated world, Archer communicates with no one. Yet in his whiskey-colored eyes, something intangible happens between us. There''s so much more to him than just his beauty, his presence, or the ways his hands communicate with me. On me. But this town is mired in secrets and betrayals, and Archer is the explosive center of it all. So much passion. And so much hurt. But it''s only in Archer''s silence that we might just find what we need to heal . . . and live.', '13.02.2018', 'Forever', ARRAY['Englisch']::text[], 388, 35, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Pelion, Maine', ARRAY['Double POV','1P']::text[], ARRAY['Archer Hale','Bree Prescott']::text[], ARRAY['Family Drama','First Love','Found Family','Isolation','Mental Issues']::text[], '{}', '2e99e9da-3ec6-5e62-95f7-2c12c1d60346', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('fa4202ac-23b6-5655-8e35-4e4170a4f74a', :'owner', 'a480755d-645d-5030-9272-a9cfe41a2279', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, false, false, '{}', '{}', NULL, NULL, false, 'group'::company_kind, 'middle'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Das war eine emotional Achterbahn dieses Buch. Es hat mich gleichzeitig sehr mitfühlen lassen, aber auch so gelangweilt. Ich liebe Archer, aber ich hasse Bree. Archer war so emotional Intelligent und gleichzeitig sind oft so dumme Sachen passiert.... Das war definitiv kein sehr gutes Buch für mich. Ich fand zwar Archers Geschichte sehr mitreißend, aber alles andere hat mich richtig oft genervt. Vor allem Bree.') on conflict do nothing;
