insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('33b5946a-2085-5f3e-abb0-00f38bba00a9', 'Nox - Das Erbe der Nacht', NULL, '9783522201155', 'Unsere Welt wird bewohnt von Menschen und den Kindern der Nacht - Hexen, Werwölfen und Vampiren. Der Rat der Nox wacht über das empfindliche Gleichgewicht zwischen Gut und Böse. Und Tara stellt eine Bedrohung für dieses Gleichgewicht dar, denn in ihr vereinen sich zwei der drei Blutlinien der Nacht. Als der Halbdämon Sky ihr einen Weg anbietet, sich aus dem Schatten der Prophezeiung, der über ihr liegt, zu lösen, greift Tara mutig zu. Sie hat nichts mehr zu verlieren. Und der Weltuntergang muss verhindert werden - koste es, was es wolle.', '14.07.2010', 'Thienemann', ARRAY['Deutsch']::text[], 474, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
