insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('76303181-6318-53ae-b0f6-4d84206eded0', 'The Lost World - Die vergessene Welt', 'The Lost World', NULL, 'Der junge kalifornische Paläontologe Levine ist von der Idee besessen, dass die Dinosaurier gar nicht ausgestorben sind. Und als aus Costa Rica das Auftauchen von ungewöhnlichen Echsen gemeldet wird, besteigt er sofort das nächste Flugzeug, um die Tiere vor Ort zu studieren. Noch ahnt er nicht, dass es sich bei diesen Sauriern nicht um Wesen aus der Kreidezeit handelt, sondern um Überbleibsel einer gezielten Genmanipulation, die ein geldgieriger Unternehmer in Auftrag gab, um die Tiere zur Attraktion eines Vergnügungsparks zu machen …', '1995', 'Droemer Knaur', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Adventure']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Jurassic Park, Costa Rica', '{}', ARRAY['Dr. Richard Levine','Ian Malcom','Dr. Sarah Harding','Doc Thorne','Arby','Kelly']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
