insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('73b5e976-4e7e-57bf-b65d-7b361f69b08d', 'Blutherz', NULL, '9783570160466', 'Sie will den Untoten, sein Bruder ihr Leben. Die sechzehnjährige Samantha Halbrook verliebt sich in Taddeusz Kóranyi, den ältesten Sohn einer steinreichen Londoner Familie. Sie ahnt nicht, dass Taddeusz einem jahrhundertealten Vampirgeschlecht entstammt. Vergeblich versucht sein Bruder Richard, Samantha vor Taddeusz’ gefährlichem Einfluss zu schützen, aber als sie dem dunklen Geheimnis der Kóranyis auf die Spur kommt, ist es bereits zu spät. Doch Samantha ist nicht bereit, sich in die Klauen des mächtigen Vampirclans zu begeben. Sie beschließt, den Kampf gegen Taddeusz und seine Familie aufzunehmen. Dazu bedarf es jedoch der Kraft des kostbaren Bariactar-Elixiers – und das findet man nur an einem Ort: in Transsylvanien, der Heimat aller Vampire. Verfolgt von Taddeusz, begeben sich Samantha und Richard auf eine gefährliche Reise …', '17.08.2009', 'cbt', ARRAY['Deutsch']::text[], 317, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Thriller (K)']::text[], NULL, NULL, 'London', '{}', ARRAY['Samantha Halbrook','Richard Kóranyi','Taddeusz Kóranyi']::text[], '{}', '{}', '53f23c8e-5f34-561c-a543-f0ca8b977cf5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
