insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f1f55d08-6da8-51cc-83b0-a196ad89608a', 'Blutjäger', NULL, '9783570160725', 'Eine neue Mission für Samantha: Gegen den Willen des mächtigen Vampirs Taddeusz Kóranyi, den sie zugleich liebt und hasst, fliegt sie mit ihrem Sohn John nach Mexico, um dort die geknechteten »Jünger Fortrius« zu befreien. Doch die Reise erweist sich als Falle: Dunoon, ein Handlanger Taddeusz’, der über die »Jünger Fortrius« befehligt, hat Sam nach Mexico gelockt. Mit Hilfe des Bluts von Halbvampir John will er ein Serum entwickeln, das ihm Unsterblichkeit verleihen soll. Als Taddeusz aufbricht, um Samantha aus den Fängen Dunoons zu befreien, kommt es zu einem gefährlichen Machtkampf zwischen den beiden Untoten …', '27.09.2010', 'cbt', ARRAY['Deutsch']::text[], 329, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Thriller (K)']::text[], NULL, NULL, 'London', '{}', ARRAY['Samantha Halbrook','Taddeusz Kóranyi']::text[], '{}', '{}', '53f23c8e-5f34-561c-a543-f0ca8b977cf5', '2', '{}', 'sheet', :'owner') on conflict do nothing;
