insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('29b663de-e7b4-5e5d-8a17-2ab9dd7ea33d', 'Schlaf nicht ein', 'Unrest', NULL, 'u siehst nachts die Geister von Toten. Du bist ihnen hilflos ausgeliefert. Und einer der Toten will deine große Liebe für sich. Du siehst nachts die Geister von Toten. Du musst etwas tun - und du bist ganz allein. Seit Monaten versucht Elliot, sich mit allen Mitteln wachzuhalten. Denn nachdem er bei einem Unfall für einige Minuten klinisch tot war, passieren schaurige Dinge mit ihm, während er schläft: Er kann sich nicht rühren, spürt Schatten, die sich um ihn herum bewegen, oder er wandelt durchs Haus, während sein Körper schlafend im Bett liegt. Als er sich in Ophelia verliebt, wird es noch unheimlicher: Offenbar versucht ein Toter, Besitz von Elliots Körper zu ergreifen …', '10.03.2014', 'Loewe', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Elliot']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
