insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5c6ee5be-9ce9-5b0e-9093-1409e3193d46', 'Elfenseele - Hinter dem Augenblick', 'Thirteen Treasures', '9783785573648', 'Der Sommer auf Elvesden Manor wird ein Alptraum, da ist sich Tanya sicher. Niemand will sie dort haben, nicht ihre Großmutter und nicht die Elfen, die zu Hunderten und Tausenden die Wälder um das alte Herrenhaus bevölkern. Während sie versucht, ihrer Großmutter aus dem Weg zu gehen, stößt sie auf ein Geheimnis: Vor fünfzig Jahren ist ein Mädchen im Wald von Elvesden verschwunden und seitdem hat niemand etwas von ihr gehört. Tanya ahnt, dass sie die Einzige ist, die das Rätsel lösen kann. Denn die Elfen scheinen darin eine unheimliche Rolle zu spielen …', '06.06.2011', 'Loewe', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, NULL, 'Elvesden Manor', '{}', ARRAY['Tanya']::text[], '{}', '{}', 'e3151a62-93e7-5c85-9c78-4e1daf0aad2e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
