insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d85ca62-e454-537d-adb1-4577935f9860', 'Elfenseele - Zwischen den Nebeln', 'Thirteen Curses', '9783785567302', 'Endlich ist es Red gelungen, einen Weg ins Elfenreich zu finden. Sie will ihren Bruder James befreien, der als Baby von Feen entführt wurde. Auf ihrem Weg zum Königshof der Elfen begegnen ihr Gefahren, wie sie sie in ihren schlimmsten Albträumen nicht gesehen hat, doch sie findet auch Verbündete, wo sie sie am wenigsten vermutet. Aber James'' Freiheit hat ihren Preis: Red lässt sich auf einen Handel mit dem König der Elfen ein, der sie das Leben kosten könnte. Gemeinsam mit ihren Freunden Tanya und Fabian macht sie sich in der Menschenwelt auf eine gefährliche Suche. Sie ahnt nicht, dass der König ihr eine Falle gestellt hat, der sie nicht entrinnen kann.', '01.03.2010', 'Loewe', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, NULL, 'Elvesden Manor', '{}', ARRAY['Tanya']::text[], '{}', '{}', 'e3151a62-93e7-5c85-9c78-4e1daf0aad2e', '2', '{}', 'sheet', :'owner') on conflict do nothing;
