insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('da14c76f-55a1-5610-97b2-3ec1a513de0f', 'Vielleicht an einem anderen Tag', NULL, '9781090465818', 'Lea und Sam kennen sich seit vielen Jahren. Eigentlich sind sie nur beste Freunde – oder vielleicht doch mehr? Klar ist, sie haben sich im Leben immer wieder verloren. Nie schien der Zeitpunkt für die beiden richtig zu sein. Eines Abends verpasst jeder von ihnen unfreiwillig seinen Zug, und so stehen sie sich nach mehreren Jahren Funkstille ganz unerwartet am Bahnhof in Nürnberg gegenüber. Natürlich wirbelt dies ihre Gefühle gehörig durcheinander. Ist ihre Begegnung wirklich nur zufällig? Oder hat das Schicksal seine Finger im Spiel? Wohin geht die Reise für Lea und Sam diesmal? Heißt es für die beiden am Ende „für immer“ oder wieder nur „vielleicht an einem anderen Tag“?', '19.03.2019', 'Canim', ARRAY['Deutsch']::text[], 68, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Nürnberg', '{}', ARRAY['Lea','Sam']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
