insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9aa7b026-7446-5984-83d3-9e8031c4a7dd', 'Als ob du mich siehst', NULL, '9783947738106', 'Elisa Lohmann will einen Neuanfang. Das Leben hat sie oft verletzt, doch diesmal hat sie eine Regel: Niemand soll ihr Herz brechen. Ihr Plan: Jeden schlechten Moment in einen guten verwandeln. Einfach – bis Joan in ihrem Leben auftaucht. Mit seinen grünblauen Augen, seiner lockeren Art und einem Lächeln, das alles durcheinanderbringt, weckt er Gefühle, die sie längst begraben hatte. Gefühle, die gefährlich sind. Doch Joan lässt sich nicht abweisen und sieht mehr in Elisa, als sie selbst wahrnimmt. Als sie erfährt, dass auch er ein bewegendes Geheimnis verbirgt, erkennt sie: Nichts ist, wie es scheint – und jeder Moment zählt.', '30.04.2020', 'Kampenwand', ARRAY['Deutsch']::text[], 361, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Coming of Age']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Elisa Lohmann','Joan']::text[], '{}', '{}', '2c12b78a-3007-5ef0-844f-44b84f18af73', '2', '{}', 'sheet', :'owner') on conflict do nothing;
