insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b88bd944-cbaf-5563-8f8d-6844c998e837', 'Gothic Love (Vol.1)', NULL, '9783770474288', 'Marika sollte das glücklichste Mädchen der Welt sein: sie ist hübsch, reich und ihr Elite-Internat verspricht eine tolle Zukunft. Aber sie fühlt sich wie ein Vogel im goldenen Käfig. Doch dann trifft sie den „Schulrebellen“ Kanzaki in der schuleigenen Kapelle …', '09.06.2011', 'Egmont Manga', ARRAY['Deutsch']::text[], 187, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Marika','Kanzaki']::text[], '{}', '{}', 'adaf4972-5d1f-590b-b6dc-c4ddcc6aa448', '1', '{}', 'sheet', :'owner') on conflict do nothing;
