insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9ba53d69-8fb8-5bc8-a2e6-55e706f9094a', 'Das Geheimnis der Talente', NULL, NULL, 'Melek ist alles andere als ungewöhnlich. Sie lebt in einer Kleinstadt Nordhessens, spielt wenig begeistert Basketball, schreibt mittelmäßige Noten und hat nur einen einzigen Freund. Oder auch gar keinen, wenn man bedenkt, dass er eher die Rolle eines nicht unattraktiven Stalkers annimmt. Sie ist ein Niemand. Bis sie von den Talenten entdeckt wird …', '18.03.2016', 'Bittersweet', ARRAY['Deutsch']::text[], 504, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nordhessen', '{}', ARRAY['Melek']::text[], '{}', '{}', '438d5224-1d5b-5aef-a4eb-c52e24709a86', '1', '{}', 'sheet', :'owner') on conflict do nothing;
