insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('102d7953-c142-5098-a66d-cca63ab53fe4', 'Das Bündnis der Talente', NULL, NULL, 'Melek ist schon lange kein gewöhnliches Mädchen mehr. Bis eben noch eine Außenseiterin, steckt sie nun mitten in einer Armee, deren Bündnis die Menschheit zusammenhält. Jede ihrer Entscheidungen beeinflusst den Lauf der Welt. Und jedes ihrer Gefühle kann sie zerrütten. Im Herzen ist sie ein Volltreffer. Aber wem gehört ihre Seele? ** Dies ist der Folgeband von "Das Geheimnis der Talente". Die Talente-Reihe erscheint in neun E-Book-Teilen, die in drei Taschenbuch-Bänden zusammengefasst werden und ist die erste eigene BitterSweets-Serie von Carlsen.', '01.07.2016', 'Bittersweet', ARRAY['Deutsch']::text[], 476, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nordhessen', '{}', ARRAY['Melek']::text[], '{}', '{}', '438d5224-1d5b-5aef-a4eb-c52e24709a86', '2', '{}', 'sheet', :'owner') on conflict do nothing;
