insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('efaf8e15-398e-5f87-af60-a2b606b94a6f', 'Der Krieg der Talente', NULL, NULL, 'Melek hat die Menschenwelt hinter sich gelassen und ist zu einer der Anderen geworden. Endlich ist es ihr erlaubt, ihrer Sehnsucht nach einem der verführerischsten Wesen auf Erden zu folgen und vollends in ihrer Leidenschaft für ihn aufzugehen. Frei wie ein Pegasus. Jedoch seelenlos.', '29.09.2016', 'Bittersweet', ARRAY['Deutsch']::text[], 552, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Nordhessen', '{}', ARRAY['Melek']::text[], '{}', '{}', '438d5224-1d5b-5aef-a4eb-c52e24709a86', '3', '{}', 'sheet', :'owner') on conflict do nothing;
