insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b9bb67a3-ff5c-5d39-9ec9-da115f1c090e', 'Tuesdays with Morrie', NULL, '9780385496490', 'Maybe it was a grandparent, or a teacher or a colleague? Someone older, patient and wise, who understood you when you were young and searching, and gave you sound advice to help you make your way through it? For Mitch Albom, that person was Morrie Schwartz, his college professor from nearly twenty years ago. Maybe, like Mitch, you lost track of this mentor as you made your way, and the insights faded. Wouldn''t you like to see that person again, ask the bigger questions that still haunt you? Mitch Albom had that second chance. He rediscovered Morrie in the last months of the older man''s life. Knowing he was dying of ALS - or motor neurone disease - Mitch visited Morrie in his study every Tuesday, just as they used to back in college. Their rekindled relationship turned into one final ''class'': lessons in how to live.', '29.12.1998', 'Anchor', ARRAY['Englisch']::text[], 192, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Mitch Albom','Morrie Schwartz']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
