insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ba62c8c-3510-5c90-a6b9-d1a874bfbb47', 'Save Me', NULL, '9783736306431', 'Geld, Glamour, Luxus, Macht - all das könnte Ruby Bell nicht weniger interessieren. Seit sie ein Stipendium für das renommierte Maxton Hall College erhalten hat, versucht sie in erster Linie eins: ihren Mitschülern so wenig wie möglich aufzufallen. Vor allem von James Beaufort, dem heimlichen Anführer des Colleges, hält sie sich fern. Er ist zu arrogant, zu reich, zu attraktiv. Während Rubys größter Traum ein Studium in Oxford ist, scheint er nur für die nächste Party zu leben. Doch dann findet Ruby etwas heraus, was sonst niemand weiß - etwas, was den Ruf von James‘ Familie zerstören würde, sollte es an die Öffentlichkeit geraten. Plötzlich weiß James genau, wer sie ist. Und obwohl sie niemals Teil seiner Welt sein wollte, lassen ihr James - und ihr Herz - schon bald keine andere Wahl ...', '23.02.2018', 'LYX', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Maxton Hall College', '{}', ARRAY['Ruby Bell','James Beaufort']::text[], '{}', '{}', '3030bb99-37e2-5363-b13c-a694a82b4d05', '1', '{}', 'sheet', :'owner') on conflict do nothing;
