insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4609b039-f1df-563c-ac0c-8f6e4aadf850', 'Save Us', NULL, '9783736306752', 'Ruby steht unter Schock: Sie wurde vom Maxton-Hall-College suspendiert. Und das Schlimmste: Alles deutet darauf hin, dass niemand anders als James dafür verantwortlich ist. Ruby kann es nicht glauben - nicht nach allem, was sie gemeinsam durchgestanden haben. Sie dachte, dass sie den wahren James kennengelernt hat: den, der Träume hat, den, der sie zum Lachen bringt und ihr Herz mit einem einzigen Blick schneller schlagen lässt. Doch während Ruby dafür kämpft, trotz allem ihren Abschluss machen zu können, droht James einmal mehr unter den Verpflichtungen gegenüber seiner Familie zu zerbrechen. Und die beiden müssen sich fragen, ob die Welten, in denen sie leben, nicht vielleicht doch zu verschieden sind ...', '31.08.2018', 'LYX', ARRAY['Deutsch']::text[], 374, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Maxton Hall College', '{}', ARRAY['Ruby Bell','James Beaufort']::text[], '{}', '{}', '3030bb99-37e2-5363-b13c-a694a82b4d05', '3', '{}', 'sheet', :'owner') on conflict do nothing;
