insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('864ce2b1-10da-5aac-9aba-ebe9fbb86b6c', 'Begin Again', NULL, '9783736302471', 'Noch einmal ganz von vorne beginnen - das ist Allie Harpers sehnlichster Wunsch, als sie für ihr Studium nach Woodshill zieht. Dass sie ausgerechnet in einer WG mit einem überheblichen Bad Boy landet, passt ihr daher gar nicht in den Plan. Kaden White ist zwar unfassbar attraktiv - mit seinen Tattoos und seiner unverschämten Art aber so ziemlich der Letzte, mit dem Allie sich eine Wohnung teilen möchte. Zumal er als allererstes eine Liste von Regeln aufstellt. Die wichtigste: Wir fangen niemals etwas miteinander an! Doch Allie merkt schnell, dass sich hinter Kadens Fassade viel mehr verbirgt als zunächst angenommen. Und je besser sie ihn kennenlernt, desto unmöglicher wird es ihr, das heftige Prickeln zwischen ihnen zu ignorieren ...', '14.10.2016', 'LYX', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Woodshill', '{}', ARRAY['Allie Harper','Kaden White']::text[], '{}', '{}', 'c9aacbda-abb2-5fe0-aa72-d6c52b721b86', '1', '{}', 'sheet', :'owner') on conflict do nothing;
