insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1e338ebf-d502-5aa8-92ec-92ebeabdc734', 'Fallen Princess - So Betörend wie tödlich', NULL, '9783736321489', 'Als die siebzehnjährige Zoey King den Tod eines Mitschülers voraussieht, wird ihr Leben völlig auf den Kopf gestellt. Denn statt der Gabe des Heilens, die sie eigentlich von ihrer ruhmreichen Mutter erben sollte, ist sie eine Banshee, die Todesmagie besitzt. Von dieser Erkenntnis erschüttert, muss sie an der Everfall Academy den Zweig wechseln und bekommt Dylan Dae Park als Mentor an die Seite gestellt, einen Reaper, der anderen mit einer bloßen Berührung die Seele entreißen kann und Zoey nun dabei helfen soll, mit ihrer neu erweckten Magie umzugehen. Doch der Tod ihres Mitschülers lässt ihr keine Ruhe. Als sie beschließt, den Fall genauer unter die Lupe zu nehmen, findet sie nach und nach heraus, dass mehrere Leute an der Akademie dunkle Geheimnisse hüten. Allen voran Dylan, bei dessen Anblick ihr Herz immer schneller schlägt ...', '07.11.2023', 'LYX', ARRAY['Deutsch']::text[], 426, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Everfall Academy', '{}', ARRAY['Zoey King','Dylan Dae Park']::text[], '{}', '{}', '5b9ee62d-fb2b-5054-8f4f-30e898d956c3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
