insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('65e7a3dd-7498-5928-9440-df13f325d47b', 'Lonely Heart', NULL, '9783736319004', 'Rosie kann nicht glauben, dass sie Scarlet Luck für ihre Webradio-Show interviewen darf. Nicht nur verfolgt sie die Band seit Jahren, ihre Lieder haben sie auch durch die schwerste Zeit ihres Lebens gebracht. Vor allem Adam, der Schlagzeuger, fasziniert sie, nicht zuletzt deshalb, weil über ihn nur bekannt ist, dass er seit Jahren keine Berührungen duldet - von niemandem. Aber dann steht die Band schließlich in Rosies kleinem Studio, und alles geht schief. Das Interview muss abgebrochen werden, und Wellen aus Hass prasseln online auf Rosie nieder. Als sie sogar auf der Straße von Fans angegriffen wird, laden Scarlet Luck sie kurzerhand auf ein Konzert ein, als Zeichen, dass sie die Sache hinter sich lassen wollen. Plötzlich steht Rosie ein zweites Mal vor Adam. Adam, in dessen Augen sie einen unfassbaren Schmerz erkennt - und dem sie niemals näherkommen darf ...', '27.04.2022', 'LYX', ARRAY['Deutsch']::text[], 406, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Rosie','Adam']::text[], ARRAY['Famous Person']::text[], '{}', '23292cf4-457d-5ca5-a3ff-676c6e6b762f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
