insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0f01ce38-d4cd-55a6-9706-410b532ce873', 'Trust Again', NULL, '9783736302495', 'In dem Moment, in dem sie Spencer Cosgrove zum ersten Mal gegenübersteht, weiß Dawn, dass sie ein Problem hat. Ein großes Problem. Spencer ist sexy, charmant und lustig, genau ihr Typ - und er beginnt augenblicklich mit ihr zu flirten. Doch Dawn hat sich geschworen, die Finger von Männern zu lassen. Zu tief sitzt der Schmerz, den sie empfindet, weil sie der falschen Person vertraut hat, zu groß ist die Wunde, die sein Verrat hinterlassen hat. Aber Spencer gibt nicht auf. Und als Dawn herausfindet, dass auch er ein herzzerreißendes Geheimnis verbirgt, wird ihr klar, dass sie keine Chance hat gegen die Art und Weise, wie er ihre Welt auf den Kopf stellt ...', '13.01.2017', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Woodshill', '{}', ARRAY['Dawn','Spencer Cosgrove']::text[], '{}', '{}', 'c9aacbda-abb2-5fe0-aa72-d6c52b721b86', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
