insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d489071c-9023-58ec-8c7c-8b7394039420', 'Save You', NULL, '9783736306240', 'Ruby ist am Boden zerstört. Noch nie hatte sie für jemanden so tiefe Gefühle wie für James. Und noch nie wurde sie so verletzt. Sie wünscht sich ihr altes Leben zurück ― als sie auf dem Maxton Hall College niemand kannte und sie kein Teil der elitären und verdorbenen Welt ihrer Mitschüler war. Doch sie kann James nicht vergessen. Vor allem nicht, als dieser alles daransetzt, sie zurückzugewinnen ...', '25.05.2018', 'LYX', ARRAY['Deutsch']::text[], 369, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Maxton Hall College', '{}', ARRAY['Ruby Bell','James Beaufort']::text[], '{}', '{}', '3030bb99-37e2-5363-b13c-a694a82b4d05', '2', '{}', 'sheet', :'owner') on conflict do nothing;
