insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('79e9ee39-54a6-58f8-82c4-d85e6b77be09', '522daf5b-6f76-541c-be2e-fca9cc2350bb', :'owner', 1, '2020-11-27', '2020-12-08', NULL, NULL, 12, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0223964c-1c96-5740-a571-2e6ecc8241af', 'Fragile Heart', NULL, '9783736319608', 'Drei Monate ist es her, dass Adam jeglichen Kontakt zu Rosie abgebrochen hat. Noch immer jagen die Worte aus seinem Abschiedsbrief durch ihren Kopf, noch immer schmerzt ihr Herz genauso heftig wie am ersten Tag. Sie sehnt sich nach den tiefgründigen Gesprächen mit ihm und der Nähe, die sie zu ihm empfunden hat, selbst als er Tausende von Kilometern von ihr entfernt war. Ihre Webradio-Show bietet Rosie wenigstens ein bisschen Ablenkung, und sie arbeitet unermüdlich daran, diese nach dem misslungenen Scarlet-Luck-Interview wieder auf einen guten Weg zu bringen. Doch gerade als sie zu glauben beginnt, sie könnte irgendwann über Adam hinwegkommen, meldet sich dieser wieder bei Rosie - und mit einem Schlag sind all die Gefühle, Hoffnungen und Träume zurück, die sie so sehr versucht hat zu verdrängen. Aber wie soll es für sie beide eine Chance geben, wenn sie nach wie vor eine ganze Welt zu trennen scheint?', '22.11.2022', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Rosie','Adam']::text[], ARRAY['Famous Person']::text[], '{}', '23292cf4-457d-5ca5-a3ff-676c6e6b762f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
