insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1107db1c-f315-51d4-acdb-276e450b7281', 'Feel Again', NULL, '9783736304451', 'Sawyer Dixon ist jung, tough - und eine Außenseiterin. Seit dem Tod ihrer Eltern lässt sie niemanden an sich heran. Das ändert sich, als sie Isaac Grant kennenlernt. Mit seiner Nerd-Brille und den seltsamen Klamotten ist er eigentlich das genaue Gegenteil von Sawyers üblichem Beuteschema. Doch als Isaac, der es satthat, single zu sein, sie um Hilfe bittet, schließen die beiden einen Deal: Sawyer macht aus Isaac einen Bad Boy und darf dafür seine Entwicklung als Fotoprojekt für ihr Studium festhalten. Aber Sawyer hat nicht mit den intensiven Gefühlen gerechnet, die zwischen ihr und Isaac hochkochen ...', '26.05.2017', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Woodshill', '{}', ARRAY['Sawyer Dixon','Isaac Grant']::text[], '{}', '{}', 'c9aacbda-abb2-5fe0-aa72-d6c52b721b86', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
