insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8faeeac-b636-5911-b3f8-f0b3456f03b2', 'Dream Again', NULL, '9783736311879', 'Jude Livingston ist am Boden zerstört: Ihr großer Traum, als erfolgreiche Schauspielerin in L.A. durchzustarten, ist geplatzt. Ohne Job und ohne Geld bleibt ihr keine andere Wahl, als zu ihrem Bruder nach Woodshill zu ziehen - und damit auch in die WG ihres Ex-Freundes Blake Andrews. Schnell merkt Jude, dass aus dem humorvollen Jungen von damals ein gebrochener Mann geworden ist, der ihr die Trennung nie verziehen hat. Doch die Anziehungskraft zwischen ihnen ist heftiger als je zuvor. Und schon bald müssen sich Jude und Blake fragen, ob sie bereit sind, ihre Herzen erneut zu riskieren ...', '23.03.2020', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Woodshill', '{}', ARRAY['Jude Livingston','Blake Andrews']::text[], '{}', '{}', 'c9aacbda-abb2-5fe0-aa72-d6c52b721b86', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
