insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('17085d25-fce6-5e31-8951-b4dde9b8b94c', 'Haunted Reign - So verlockend wie bedrohlich', NULL, '9783736323353', 'Zoey King versucht mit aller Macht, zu vergessen. Zu vergessen, dass sie ihre beste Freundin verloren hat. Dass ihr Leben auf dem Kopf steht, seit sie erfahren hat, dass sie eine Banshee ist und Todesmagie in sich trägt. Dass der Junge, den sie mag, in ihr nichts weiter sieht als ein Nachhilfeprojekt und sich nicht einmal mehr an den Kuss zu erinnern scheint, den sie geteilt haben. Als wäre das noch nicht schlimm genug, lassen Zoeys Noten seit dem Wechsel an den Zweig der Silver Ravens zu wünschen übrig. Doch zumindest dafür gibt es eine Lösung: Das Jahresabschluss-Turnier an der Everfall Academy steht an, eine Möglichkeit, Zusatzpunkte für ihr Zeugnis zu sammeln. Allerdings stellt sich schon die erste Prüfung als gefährlicher heraus, als Zoey jemals hätte ahnen können. Und bald steht nicht nur ihr eigenes Leben auf dem Spiel, sondern auch das der Menschen, die ihr alles bedeuten ...', '17.09.2024', 'LYX', ARRAY['Deutsch']::text[], 374, 27, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Everfall Academy', '{}', ARRAY['Zoey King','Dylan Dae Park']::text[], '{}', '{}', '5b9ee62d-fb2b-5054-8f4f-30e898d956c3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
