insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dc01d125-6927-5ac7-829b-7dac31358c0e', 'Gentle Heart', NULL, '9783736327009', 'Nach einer Beziehung, die sie fast zerstört hätte, und einer Trennung, die zu einem öffentlichen Skandal wurde, hat sich Popstar Ashley Cruz endlich zurückgekämpft. Ihre neue Musik soll zeigen, dass sie niemanden mehr braucht. Kein Drama, kein Gerede über ihre Vergangenheit - und schon gar keine Schlagzeilen über Männer an ihrer Seite. Doch dann begegnet sie Logan Buckley, gefeierter Gitarrist von Scarlet Luck, der angesagtesten Band der Welt. Ein harmloser Moment wird zu mehr - eine Freundschaft mit gewissen Vorzügen, ohne Verpflichtungen, und vor allem ohne Öffentlichkeit. Doch je näher sie sich kommen und je mehr sie übereinander erfahren, desto mehr verschwimmen ihre Regeln. Und bald schon muss sich Ashley fragen, ob sie nicht doch bereit ist, Logan in ihr Herz zu lassen ...', '02.09.2025', 'LYX', ARRAY['Deutsch']::text[], 432, 39, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['Double POV','1P']::text[], ARRAY['Ashley Cruz','Logan Buckley']::text[], ARRAY['Famous Person','Tragic Backstory','Mental Issues']::text[], '{}', '23292cf4-457d-5ca5-a3ff-676c6e6b762f', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ab87f810-4252-5b83-a484-290e582cb355', :'owner', 'dc01d125-6927-5ac7-829b-7dac31358c0e', 'gelesen'::reading_status, true, false, ARRAY['Digital','Print']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', ARRAY['Sprayed Edges','Playlist']::text[], 2200, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 2, 'slow'::burn_kind, 'Boah ich hasse wenig mehr in Bücher, als all die Charaktere, die ein Drama daraus machen, dass Leute ihnen Mitgefühl zeigen. Immer dieses "Ich will dein Mitleid nicht." JUNGE, es ist normal, dass man mit jemaden mitfühlt, dem es schlecht geht. Das heißt nicht, dass ich schlechter von dir denke. Das ist so dumm. Ein süßes Buch. Es hat mich nicht vom Hocker gehauen, aber gerade der Anfang hat mir gut gefallen. Ich fand nur leider, dass auf alle "tiefgehenden" Themen nicht genug eingegangen wurde. Irgendwie wurde immer nur darüber gesprochen, aber nie genau erkllärt was eigentlich los ist. Das hat das Buch für mich etwas oberflächlich gemacht.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('a4cf72b7-62e9-58c5-b4bf-4bd76745ce8a', 'ab87f810-4252-5b83-a484-290e582cb355', :'owner', 1, '2025-12-11', '2025-12-20', NULL, NULL, 10, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('378afc64-9b50-5391-bcd8-bef7249e369f', 'Der Erdbeerpflücker', NULL, NULL, 'Jettes Freundin Caro fällt in die Hände eines Serienmörders, der seinen Opfern die Haare abschneidet. Auf der Beerdigung schwört Jette, Caros Mörder zu finden. Damit weckt sie dessen Neugier und er sucht ihre Nähe. Jette verliebt sich in ihn. Zu spät erkennt sie, mit wem sie es zu tun hat.', '01.12.2003', 'cbt', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Krimi', ARRAY['Mystery']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jette']::text[], '{}', '{}', '419e1651-d355-5bff-85a6-08d4458fa4ff', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a8c14090-0c41-5fda-9b51-bd4dc17c29b1', :'owner', '378afc64-9b50-5391-bcd8-bef7249e369f', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 899, false, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5464b3fa-5931-5b6d-8c01-b13059d137b1', 'A Spring to Hope', 'Un printemps pour te succomber', '9783736321397', 'Mit ihrem eigenen Blumenladen hat sich Magnolia ihren großen Traum erfüllt. Doch als das Geld knapp wird, wendet sie sich an ihre Familie. Diese hat für ihre Hilfe allerdings eine Bedingung: Sie soll ihren Ex-Freund heiraten! Für Nolia kommt das nicht infrage, aber das Ultimatum bringt sie auf eine Idee: eine Fake-Ehe - und der Partner ist schnell gefunden. Camille Levesque ist Gründer einer Escort-App und Milliardär, doch der attraktive Playboy sorgt regelmäßig für Skandale in der Presse und benötigt eine Frau an seiner Seite, um seinen Ruf zu bereinigen. Der Plan scheint perfekt, aber können sie ihr Versprechen halten, sich auf keinen Fall ineinander zu verlieben?', '29.11.2024', 'LYX', ARRAY['Deutsch']::text[], 509, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Magnolia','Camille Levesque']::text[], ARRAY['Fake Dating']::text[], '{}', '9942c0e2-cd14-5f69-a753-042542a1be1f', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
