insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7bb1e15b-3eff-533c-b446-11a3291ff270', 'Never Too Close', 'Viens, on s''aime', '9783736311220', 'Seit sie gemeinsam in einem Aufzug eingeschlossen waren, sind Loan und Violette beste Freunde. Das zwischen ihnen ist vollkommen platonisch - zumindest bis jetzt. Denn als Violette beschließt, dass sie nicht länger Jungfrau sein will, ist es Loan, den sie bittet, ihr auszuhelfen. Schließlich vertraut sie niemandem so sehr wie ihrem besten Freund. Loan ist von der Idee zunächst alles andere als begeistert, doch schließlich willigt er ein. Es ist ja nur dieses eine Mal ... oder?', '30.09.2019', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Loan','Violette']::text[], '{}', '{}', 'fd5f09ef-df41-541a-b176-fce76d697a9a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
