insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('a4d4ab38-3ab4-5265-9ef1-6cd1845ebeb2', 'd4c34c8f-0b75-5e7e-8098-ad78b6ecdc77', :'owner', 1, '2021-01-13', '2021-01-16', NULL, NULL, 4, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('619f2427-202f-5550-aeac-e4b8721dcd2b', 'Count On You', 'L’As de pique', '9783736318816', 'Sängerin, Schauspielerin und Model - Daisy Coleman hat sich all ihre Träume erfüllt. Eigentlich hat der Weltstar alles, nur nicht das, was sie sich am sehnlichsten wünscht: Thomas Kalberg, den besten Freund ihres Bruders. Aber Thomas lässt keinerlei Gefühle zu und behandelte Daisy stets wie eine kleine Schwester. Doch plötzlich ändert sich alles zwischen ihnen, denn Thomas wird Daisys neuer Bodyguard. Obwohl die beiden sich so nah sind wie noch nie, erscheint Thomas unerreichbarer als jemals zuvor. Denn um Daisy zu beschützen, will er ihre Beziehung rein professionell halten. Daisy hingegen hat sich in den Kopf gesetzt, das eiskalte Herz ihres Bodyguards zu erobern.', '31.03.2023', 'LYX', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Los Angeles', ARRAY['Double POV','1P']::text[], ARRAY['Daisy Coleman','Thomas Kalberg']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
