insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('88e34dc5-6514-56bc-98e2-303d5daf4d61', 'bb9a243f-1a95-5260-b1ee-410868dc58a7', :'owner', 1, '2023-04-18', '2023-04-23', NULL, NULL, 6, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1726f925-9c2a-542a-a421-20a433ac6c65', 'Never Too Late', 'Aime-moi, je te fuis', '9783736311671', 'Die Nacht mit Jason sollte eine einmalige Sache sein. Zoé führt keine Beziehungen, und sie verliebt sich nicht - niemals! Doch dann stehen sich die beiden wenige Tage später plötzlich erneut gegenüber, als sie feststellen, dass ihre besten Freunde in dieselbe Wohnung gezogen sind. Und obwohl Zoé den One-Night-Stand am liebsten vergessen würde, kann sie sich nicht gegen das Kribbeln wehren, das Jasons Nähe in ihr hervorruft. Aber ihr Herz wurde schon einmal gebrochen - kann sie es wirklich ein weiteres Mal aufs Spiel setzen?', '27.03.2020', 'LYX', ARRAY['Deutsch']::text[], 475, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jason','Zoé']::text[], '{}', '{}', 'fd5f09ef-df41-541a-b176-fce76d697a9a', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
