insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bcf82749-8cb4-5adf-8e13-ee496175d37c', 'A Fall to Forgive', 'Un automne pour te pardonner', '9783736320888', 'Nach einer schweren Zeit an der Highschool wollte Camelia endlich einen Neustart an der Universität von Edinburgh wagen. Bis Lou plötzlich wieder in ihr Leben tritt. Ausgerechnet er soll Rory Cavendish getötet haben - seinen besten Freund und Camelias ehemaligen Peiniger. Obwohl auch Lou zu der Gruppe gehört, die Camelias Schulzeit zur Hölle gemacht hat, ist da dennoch diese unerklärliche Anziehung, die schon immer zwischen ihnen war. Deshalb stimmt die Jurastudentin zu, ihm zu helfen, seine Unschuld zu beweisen. Doch Camelia weiß nicht, ob sie ihm wirklich vertrauen kann - zu groß ist die Angst, dass er sie erneut hintergeht und damit ihr Herz bricht ...', '28.03.2024', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Edinburgh', '{}', ARRAY['Camelia','Lou']::text[], '{}', '{}', '9942c0e2-cd14-5f69-a753-042542a1be1f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
