insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('06c9c9ee-a55f-51a5-89a7-b1b2689a915f', 'Back to Us', 'Falling Again', '9783736314474', 'Als Kinder haben sich Aaron und Fleur geschworen, einander ewig zu lieben - bis ihnen das Leben einen grausamen Strich durch die Rechnung machte und sie von einem Tag auf den anderen trennte. Nun, sechzehn Jahre später, stehen sie sich erneut gegenüber - und Fleur erkennt den Jungen, der ihr an seinem achten Geburtstag ihren ersten Kuss gab, nicht wieder. Aaron ist kühl und abweisend, in seinem Leben zählt nichts anderes als sein Job. Für Fleur, die jegliches Vertrauen in sich selbst und ihre Fähigkeiten als Autorin verloren hat, fühlt es sich an, als hätten sie die Rollen getauscht. Und doch stürmen die Gefühle von damals augenblicklich wieder auf sie ein. Nur dass Aaron sich an keines der Versprechen, die sie sich einst gegeben haben, zu erinnern scheint ...', '26.03.2021', 'LYX', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Aaron','Fleur']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
