insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d005aee0-1600-5ee0-84d8-2410e28e7324', 'A Winter to Resist', 'Un hiver pour te résister', '9783736321335', 'Lily hat nur ein Ziel: bei der Weltmeisterschaft die Goldmedaille im Eiskunstlauf zu gewinnen. Um das zu erreichen, wird ihr ein neuer Partner zugewiesen - ausgerechnet Orion Williams, einstiger Champion, Lilys großes Vorbild und heimlicher Schwarm. Doch bei ihrem ersten Kennenlernen verhält Orion sich ihr gegenüber kühl und abweisend. Dennoch müssen die beiden sich nun zusammenraufen und zu einem Team werden. Dass sie Orion bei den langen Trainingsstunden immer besser kennenlernt und ihr Herz bei jeder Hebefigur auf einmal schneller schlägt, kann Lily gar nicht gebrauchen, will sie sich doch eigentlich voll und ganz auf den Sieg konzentrieren ...', '26.07.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lily','Orion Williams']::text[], '{}', '{}', '9942c0e2-cd14-5f69-a753-042542a1be1f', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
