insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0f297aa1-90e4-52dc-80b9-e723268b72c4', 'Die Welle', NULL, NULL, 'Als es im Geschichtsunterricht um Nationalsozialismus und Rechtsextremismus geht, beschließt ein junger Lehrer, ein ungewöhnliches Experiment durchzuführen. Er möchte seinen Schülern beweisen, dass Anfälligkeit für faschistoides Handeln und Denken nicht etwas ist, das nur andere Menschen betrifft – Faschismus ist hier mitten unter uns und in jedem von uns. Doch die Bewegung, die er auslöst, droht ihn und sein Vorhaben zu überrollen: Das Experiment gerät außer Kontrolle.', '1981', 'Ravensburger', ARRAY['Deutsch']::text[], 129, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Drama']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Gordon High School', '{}', ARRAY['Ben Ross']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
