insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cb14013f-07e6-5132-b759-0b587543ebc5', 'Nightsky full of Promise', NULL, '9783736316386', 'In einer Berliner Sommernacht verbringen Sydney und Luke ein paar viel zu kurze Stunden miteinander. Ihr Treffen ist ein magischer Moment, der sie für immer verändert zurücklässt. Sie sind sich sicher, dass das zwischen ihnen etwas ganz Großes werden kann - doch Luke will für ein Jahr ins Ausland gehen. Um ihren Gefühlen trotzdem eine Chance zu geben, vereinbaren sie, sich nach Lukes Rückkehr am selben Ort zu treffen. Natürlich ist Sydney zur Stelle - Luke jedoch nicht. Auch fünf Jahre später kann Sydney ihn nicht vergessen. Und dann steht Luke ihr plötzlich wieder gegenüber. Nur erinnert er sich weder an sie noch an ihr Versprechen ...', '29.10.2021', 'LYX', ARRAY['Deutsch']::text[], 479, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'Berlin', '{}', ARRAY['Sydney','Luke']::text[], '{}', '{}', '817d2273-7c73-5bac-837f-5d18ec83b947', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
