insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eb22e9dd-46ce-53b2-b9d6-652259f8f6f5', 'Purple Clouds - Honeymoon', NULL, '9783736323650', 'Debbie White hat eine Stelle in der Redaktion des angesagten Purple Clouds Magazin in New York ergattert. Aber schon in der ersten Woche wird ihr klar, dass sie sich dort beweisen muss, denn ihre Chefredakteurin hat von Debs größtem Geheimnis erfahren: Sie ist seit vier Jahren verheiratet. Und nun soll sie einen Artikel darüber schreiben, wie es ist, als moderne Frau so früh den Bund der Ehe einzugehen. Kein Problem - hätte Deb nicht seit der Hochzeit keinen Kontakt mehr zu ihrem Mann Emory. Doch wenn sie an die Nacht voller Glücksgefühle zurückdenkt, in der sie spontan geheiratet haben, fragt Deb sich, ob es nicht mehr als einen Grund gibt, der Sache mit Emory noch eine Chance zu geben ...', '28.02.2025', 'LYX', ARRAY['Deutsch']::text[], 480, 46, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Debbie White','Emory']::text[], '{}', '{}', '9224be34-bf12-536a-af1c-702c4a3a8adc', '1', '{}', 'sheet', :'owner') on conflict do nothing;
