insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6cb3918e-fc96-5d44-ae79-c134f97c4bff', 'Purple Clouds - Meet Cute', NULL, '9783736324954', 'Riley Wang arbeitet erst kurze Zeit beim Purple Clouds Magazine, als sie dort über den Schauspieler Louis Thorne stolpert, der einem Interview entgehen will. Der Hollywood-Schwarm macht eine schwere Zeit durch und hat keine Lust auf die Kampagne, die sein Management geplant hat. Da Riley Mitleid mit ihm hat, hilft sie ihm, das Gebäude ungesehen zu verlassen - und versteckt ihn sogar in ihrer WG, als er nicht weiß, wohin. In der Abgeschiedenheit von Rileys Zimmer merken die beiden, dass sie trotz ihrer verschiedenen Lebensrealitäten einiges gemeinsam haben, und während heimlicher Ausflüge ins nächtliche New York schlagen ihre Herzen schneller, als sie jemals erwartet hätten. Doch was wird passieren, wenn Louis in seine Welt zurückkehren muss?', '25.07.2025', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Riley Wang','Louis Thorne']::text[], ARRAY['Famous Person']::text[], '{}', '9224be34-bf12-536a-af1c-702c4a3a8adc', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
