insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d244796a-c741-56d4-a0d3-e22d8d4ff4d9', 'Sun Rise full of Wonder', NULL, '9783736316751', 'Auf eines kann sich Maya verlassen: dass ihr bester Freund Lenny immer an ihrer Seite ist. Schließlich teilen sie schon seit Jahren alles miteinander, trösten sich über jeden Liebeskummer hinweg und fangen sich gegenseitig auf, wenn der andere mal wieder in die Friendzone verbannt wurde. Doch als Lennart seine Wohnung verliert und kurzfristig bei Maya einzieht, verändert sich alles. Plötzlich weckt die Nähe zu Lenny vollkommen neue Gefühle in Maya, und sie muss sich fragen, ob die große Liebe vielleicht die ganze Zeit über schon ganz nah war. Aber kann sie sicher sein, dass Lenny ihre Gefühle auch erwidert? Oder läuft sie Gefahr, den wichtigsten Menschen in ihrem Leben zu verlieren?', '26.08.2022', 'LYX', ARRAY['Deutsch']::text[], 445, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Berlin', '{}', ARRAY['Maya','Lenny']::text[], '{}', '{}', '817d2273-7c73-5bac-837f-5d18ec83b947', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
