insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38ae6340-4122-5d9b-a30b-373fbc68c1ea', 'Purple Clouds - Bittersweet', NULL, '9783736324961', 'Ein plötzliches Flirren liegt in der Luft, die Spannung zwischen uns schwer und grollend, wie Sturmwolken kurz vor dem Unwetter. Ein Traumjob beim Kultmagazin Purple Clouds - für Linh Nguyen die Chance auf einen Neuanfang in New York. Wäre da nur nicht Xander Aberdeen: talentiert, unverschämt attraktiv und der Mann, dessen Arbeit als Illustrator sie seit Monaten kritisiert hat. Noch bevor Linhs erster Arbeitstag richtig beginnt, geraten sie und Xander schon aneinander. Bissige Sprüche, hitzige Blicke und emotional aufwühlende Meetings prägen ihre Zusammenarbeit. Doch je näher Linh Xander kennenlernt, desto deutlicher merkt sie, dass sich hinter seiner schroffen Fassade eine Seite verbirgt, die sie niemals erwartet hätte. Und schließlich hegt sie einen Verdacht, der ein gut gehütetes Geheimnis lüften könnte ...', '02.02.2026', 'LYX', ARRAY['Deutsch']::text[], 459, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Linh Nguyen','Xander Aberdeen']::text[], ARRAY['Enemies to Lovers','Work Adversaries','Secred Identity']::text[], '{}', '9224be34-bf12-536a-af1c-702c4a3a8adc', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
