insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e70f196b-714e-580d-9221-08b4ac7e229d', 'Jigsaw Man - Im Zeichen des Killers', 'Jigsaw Man', '9783404180578', 'Der menschliche Körper ist ein wunderbares Puzzle, einzigartig in seiner Präzision und seiner aufeinander abgestimmten Perfektion! Der Jigsaw Man liebt Puzzles über alles. Doch ein perfektes Puzzle ist nur eines, das in seine Einzelteile zerlegt ist. Nur so kann er die wahre Schönheit erkennen - indem er jedes Teil für sich betrachtet. Hände, Füße, Beine, Arme, Köpfe. Welche Freude! Und wahre Freude muss man teilen, nicht wahr? In der ganzen Stadt ... Wirst du sein nächstes Opfer sein?', '28.08.2020', 'Lübbe', ARRAY['Deutsch']::text[], 478, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
