insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d3e8527b-0748-5fb2-bc0a-c898a9a9ab14', 'Fundbüro der Liebe', NULL, '9783842006317', 'Immer wieder fällt Ashihara auf, dass sein jüngerer Kollege Sano mal seinen Füller, mal sein Portemonnaie einfach liegen lässt. Ashihara trägt sie ihm natürlich nach, kann sich aber kaum erklären, wie Sano so nachlässig sein kann. Könnte es am Ende sein, dass Sano es mit Absicht macht, um Ashihara näherzukommen …?', '2012', 'TokyoPop', ARRAY['Deutsch']::text[], 164, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Ashihara','Sano']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
