insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8cdbb694-7080-580a-aaea-63051618e158', 'Limit Honey (Vol.1)', NULL, '9783770458219', 'Der völlig überarbeitete Büroangestellte Yoichi wacht eines morgens völlig verkatert in einem Hotel auf - und findet neben seinem Kissen die Visitenkarte einer männlichen Hostess! Yoichi erinnert sich an nichts, muss aber seinen Liebhaber aufs neue kontaktieren, schließlich hat der Unbekannte seinen Führerschein ...', '02.05.2019', 'Egmont Manga', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Yoichi']::text[], ARRAY['Queer']::text[], '{}', '5f3535c2-9118-5d5a-9988-d32a011c794d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
