insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9a1cf46a-a92f-59f0-8cec-7ac1160497a4', 'The Rainshadow Orphans', NULL, '9783847902331', 'Das Leben ist nicht leicht in Rainshadow City. Jenseits des prunkvollen Palastes herrschen Armut und Ungerechtigkeit. Die kriminelle Untergrundorganisation Lucky Crows verbreitet Angst und Schrecken. In der düsteren Metropole kämpfen die Wahlgeschwister Toshiko, Jun und Mei ums Überleben - und um Gerechtigkeit. Derweil freundet sich Haru, der Sohn der skrupellosen Kaiserin, mit magischen Sonnengeistern an. Und Theo, der wie so viele andere auf illegalem Weg nach Rainshadow City gelangt ist, wird versehentlich in kriminelle Machenschaften verstrickt.Ihre aller Schicksale werden verwoben, als Toshiko dem Anführer der Lucky Crows eine geheimnisvolle Drachenperle stiehlt und dadurch eine Reihe von Ereignissen ins Rollen bringt, die nicht nur das Leben der drei Geschwister gefährden, sondern das Schicksal von ganz Rainshadow City für immer verändern könnten.', '01.06.2026', 'eichborn', ARRAY['Deutsch']::text[], 633, 22, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Cyberpunk']::text[], 'Adult'::audience_kind, NULL, 'Rainshadow City', '{}', ARRAY['Toshiko','Jun','Mei']::text[], '{}', '{}', 'c9b39ab1-b487-5034-86e8-0ea3bd02d01c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
