insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b0961599-f584-5210-8cb1-e8cd0669547c', 'Awaking Lust - Secret Pleasures of London', NULL, NULL, 'Samanthas Liebesleben war nie sonderlich aufregend. Aktuell ist es geradezu nicht-existent. Aber Sex wird ohnehin überbewertet. Glühendes Verlangen? Augenöffnende Orgasmen? Gibt es doch gar nicht. Nicht unbedingt die besten Voraussetzungen, wenn man Liebesroman-Autorin ist und die Schreibblockade seines Lebens hat. Wenn es doch nur jemanden gäbe, der ihr zu Inspiration verhelfen könnte ... Ganz London spricht über Noahs exklusiven Club, das Lust, und die erotischen Theaterstücke, die er aufführen lässt. Er hat alle Hände voll zu tun. Auch ohne seinen größten Konkurrenten, der seit Kurzem droht, alle erfolgreichen Nachtclubs in London aus dem Markt zu drängen … und die lästige Autorin, die ausgerechnet im Lust Recherche betreibt. Mauerblümchen, die beim bloßen Gedanken an eine heiße Nacht knallrot anlaufen, haben nichts in seiner Welt verloren. Und erst recht nichts in seinen dreckigen Träumen …', '14.10.2022', NULL, ARRAY['Deutsch']::text[], 290, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Erotik']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'London', '{}', ARRAY['Samantha','Noah']::text[], '{}', '{}', 'e9eef084-1e3d-527b-9e86-45e218d61420', '1', '{}', 'sheet', :'owner') on conflict do nothing;
