insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25e40303-7978-5c9f-8a4f-291345aecd10', 'Liebe braucht keine Worte (Vol.1)', NULL, '9783862012510', 'Der schweigsame Restaurantbesitzer Hatakeyama verliebt sich ausgerechnet in den hübschen und coolen Koch Yamasaki, der bei seinem größten Konkurrenten angestellt ist. Trotz einer niederschmetternden Absage gibt es nicht auf, und findet einen anderen Weg in sein Herz – als Freund! Seine Geduld wird durch die zahlreichen ergebnislosen Treffen überstrapaziert, und als auch noch Yamasakis gutaussehender Mitbewohner auf den Plan tritt, fühlt sich Hatakeyama sich zum Handeln gezwungen… Wird er Yamasaki doch noch für sich gewinnen? Boys Love vom Feinsten!', '08.02.2012', 'Panini', ARRAY['Deutsch']::text[], 182, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Hatakeyama','Yamasaki']::text[], ARRAY['Queer']::text[], '{}', '052a645e-faaa-55f8-b79a-eb58cdfb8610', '1', '{}', 'sheet', :'owner') on conflict do nothing;
