insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b3328e1-cc44-5e5d-bda7-df67dfc3418f', 'Ein Lehrer zum Verlieben (Vol.2)', NULL, '9783862011186', 'Auch im neuen Schuljahr schafft es Herr Komori nicht so richtig, seine Schüler unter Kontrolle zu bekommen. Sein Freund und Liebhaber, Herr Takigawa, verwöhnt ihn jeden Tag mehr. Dies führt dazu, dass Herr Komori sich noch hilfloser fühlt. Doch der neue Lehrer, Herr Ibuki, der sehr streng und doch gerecht ist, motiviert ihn, sodass er neuen Mut schöpft. Komischerweise macht dies Herrn Takigawa sehr wütend …!', '25.02.2011', 'Panini', ARRAY['Deutsch']::text[], 204, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Koki Fujita','Herr Ibuki']::text[], ARRAY['Queer']::text[], '{}', '3e5252d8-c48f-5703-94c9-c93e714c2133', '2', '{}', 'sheet', :'owner') on conflict do nothing;
