insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('50422b28-afc3-5143-83c3-4e5710ac449e', 'Liebe braucht keine Worte (Vol.2)', NULL, '9783862012527', 'Der Restaurantmanager Hatakeyama hat Yamasaki, den erfolgreichen Koch einer Konkurrenzkette, endlich für sich gewonnen. Sie verlieben sich, doch offenbar ist Yamasaki so abgelenkt durch die neuen Erfahrungen, dass er am Herd einen Fehler nach dem anderen begeht …', '17.09.2012', 'Panini', ARRAY['Deutsch']::text[], 182, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Hatakeyama','Yamasaki']::text[], ARRAY['Queer']::text[], '{}', '052a645e-faaa-55f8-b79a-eb58cdfb8610', '2', '{}', 'sheet', :'owner') on conflict do nothing;
