insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('834674b1-b8cf-5128-8b39-9b3fcc9e49b9', 'Sieh mich an', 'My Life in Black and White', NULL, 'Lexi war immer stolz auf ihre Schönheit – doch dann wacht sie eines Tages im Krankenhaus auf, das Gesicht von einem Autounfall entstellt. Wenn Ryan sie nicht mit ihrer besten Freundin betrogen hätte, wäre sie nie in dieses Auto gestiegen und würde jetzt nicht vor jedem Spiegel fliehen. Lexi muss sich und ihr Leben komplett neu definieren. Unerwartete Hilfe kommt von ihrer Schwester Ruth. Durch sie lernt Lexi auch Theo kennen, der ihr zeigt, dass es im Leben nicht auf Äußerlichkeiten ankommt.', '21.02.2014', 'Carlsen', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Young Adult', ARRAY['Coming of Age']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Lexi','Theo']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
