insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('e7bb51bd-812a-5362-ae78-49789f330b42', '52d47e8c-4d48-5ab0-824a-cd2c2fb120b8', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d9b1427-55e9-557c-b666-6a0ccf653c99', 'Caught Up', NULL, '9781529442427', 'I want this woman, and I''m a man who always gets what he wants. Nico ''Junior'' Trocci knows Lauren Marchetti is off limits. Men like him don''t get to have women like her. It''s why he pushed her away in high school and still keeps his distance. But Junior follows Lauren online, and now that the shy, bookish girl he remembers is gone, he can''t stop obsessing over the strikingly beautiful woman who has taken her place. He''s ruthless; a walking red flag. Good thing red is my favorite color. Lauren ''Lo'' Marchetti knows Junior is dangerous. He broke her heart once and she won''t let him do it again. But as their flirtatious encounters escalate, Lauren starts to remember why she fell for the brooding antihero all those years ago. As old obstacles resurface, Junior and Lauren are forced to face their true feelings for each other and decide just how far they''re willing to go for a second chance at love.', '10.06.2025', 'Quercus', ARRAY['Englisch']::text[], 334, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Chicago', '{}', ARRAY['Nico ''Junior'' Trocci','Lauren ''Lo'' Marchetti']::text[], ARRAY['Second Chance']::text[], ARRAY['Stalking','Physische Gewalt','Mobbing','Toxische Beziehungsdynamiken']::text[], '0020004f-b07b-53c9-b252-6e6c7995e881', '2', '{}', 'sheet', :'owner') on conflict do nothing;
