insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('837ba5ff-1939-552b-a04c-897cf148e3f5', 'Lights Out', NULL, '9781529442397', 'Trauma nurse Aly escapes her hard-working days by thirsting after masked men online. To her, nothing could top the fantasy of her favorite tattooed and masked man hunting her down. But she never could have guessed that one drunken text would turn those dreams into reality... I want things most people don''t, craving darkness and depravity instead of light and love. Josh has spent his life avoiding the limelight, but his online persona is another story. At night, he posts masked thirst traps for his millions of fans, until one follower catches his eye: Aly. Together, Aly and Josh live out their darkest fantasies, unaware that Aly has captured the attention of someone with far more sinister intentions. As Josh turns from predator to protector, he must ask himself how far he''ll go for the woman he can''t live without.', '06.08.2025', 'Quercus', ARRAY['Englisch']::text[], 397, 26, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Chicago', ARRAY['Double POV','1P']::text[], ARRAY['Aly','Josh']::text[], ARRAY['Dark Secrets','Disguised Identity','Mental Issues','Secred Identity','He falls first','Strong FMC']::text[], ARRAY['Sexuelle Gewalt','Dub-Con/Non-Con','Physische Gewalt','Tod von Familienangehörigen','Stalking','Rape','Depiction of Trauma','Tod','Mord','Belästigung']::text[], '0020004f-b07b-53c9-b252-6e6c7995e881', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('b4af64f8-2490-55ba-8d35-e81d2374a1b7', :'owner', '837ba5ff-1939-552b-a04c-897cf148e3f5', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1269, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Ich musste so oft über Josh lachen, dass ich daran gezweifelt habe, ob dieses Buch wirklich eine "Dark" Romance ist. Ich habe zwar etwas ganz anderes erwartet, doch das Buch hat mir überraschend gut gefallen. Die Charaktere waren klasse, mit sehr viel Tiefe. Ich mochte es, wie sie beide so gegensätzliche Eigenschaften hatten. Gleichzeitig moralisch sehr korrekt und auf der anderen Seite sehr unkorrekt.') on conflict do nothing;
