insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('175e54f6-cbf9-5f4b-91c0-97c9b6d9b860', 'Vollendet - Die Flucht', 'Unwind', '9783733504434', 'Sie sagen, dass du weiterlebst. Sie lügen. Connor, 16 Jahre alt und ständiger Unruhestifter, hat es längst geahnt, doch nun steht es fest: Er soll umgewandelt werden. Seine Eltern haben seinen Körper vollständig zur Organspende freigegeben. Und zwar nicht erst nach seinem Tod. Sondern sofort. Risa ist in einem Waisenhaus aufgewachsen und darf nicht länger auf Kosten des Staates leben. Auch sie soll umgewandelt werden. Als ihre Wege sich unerwartet treffen, müssen Connor und Risa sich blitzschnell entscheiden - Flucht oder Umwandlung? Können sie dem System entkommen, das Jagd auf Menschen wie sie macht?', '22.08.2018', 'Fischer', ARRAY['Deutsch']::text[], 429, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Connor','Risa']::text[], '{}', '{}', '1f0c3b62-0496-5f85-95d0-2436c3d7a61d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
