insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('64b632aa-2d51-5ae9-94b3-54bc3610ab50', 'Der Ozean am Ende der Straße', 'The Ocean at the End of the Lane', '9783847905790', 'Es war nur ein Ententeich, ein Stück weit unterhalb des Bauernhofs. Und er war nicht besonders groß. Lettie Hempstock behauptete, es sei ein Ozean, aber ich wusste, das war Quatsch. Sie behauptete, man könne durch ihn in eine andere Welt gelangen. Und was dann geschah, hätte sich eigentlich niemals ereignen dürfen ... Weise, wundersam und hochpoetisch erzählt Gaiman in seinem neuen Roman von der übergroßen Macht von Freundschaft und Vertrauen in einer Welt, in der nichts ist, wie es auf den ersten Blick scheint.', '08.10.2014', 'Eichborn', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Lettie Hempstock']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
