insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('72a45083-e4d1-5953-9908-dbc3c2cb55e4', 'Wenn du mich siehst', 'See me', '9783453421936', 'Mitten auf einer einsamen nächtlichen Landstraße bleibt Marias Auto liegen. Ein Wagen hält, ein bedrohlich aussehender, muskelbepackter Mann steigt aus – und wechselt ihr freundlich den Reifen. Colin Hancock hat schon viele dumme Entscheidungen in seinem Leben getroffen und bitter dafür büßen müssen, eine Beziehung ist das Letzte, was er sucht. Doch so wenig Maria und Colin zusammenzupassen scheinen und so sehr sie sich auch dagegen wehren: Sie verlieben sich rettungslos ineinander. Aber ihnen droht größte Gefahr, denn ein finsteres Kapitel aus ihrer Vergangenheit holt Maria ein und lässt sie um ihr Leben fürchten. Werden die alten Dämonen alles zerstören, oder kann ihre Liebe Colin und Maria in der dunkelsten Stunde retten?', '10.07.2017', 'Heyne', ARRAY['Deutsch']::text[], 569, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Maria','Colin Hancock']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
