insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e770bec8-6693-57c7-9b81-4bd0006c1a50', 'Rising Sparks', NULL, '9783744810128', 'An ihrem siebzehnten Geburtstag ändert sich Skyes komplettes Leben. Ihr wird ein Beruf zugeteilt, den sie bis an ihr Lebensende ausführen soll - und es kommt noch schlimmer: Das System bestimmt nicht nur, was Skye zu tun hat und wo sie leben soll, sondern auch über alles andere, was im Leben zählt. Doch als Skye etwas erfährt, was nicht führ ihre Ohren bestimmt ist, ist nichts mehr so, wie es vorher war.', '27.12.2017', 'BoD', ARRAY['Englisch']::text[], 356, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Skye','Kiran']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
