insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b1ed5bbf-8cdb-5843-a107-86193b3f4a18', 'Their Girl - Deine Unschuld gehört uns', NULL, '9783757808921', 'Ich bin Virginie und so weit ich zurückdenken kann, lebe ich schon hinter diesen gefühlt unüberwindbaren Mauern. Fiktive Figuren sind meine einzigen Wegbegleiter. Ja, in meinem Kopf wohnt eine ganze Schar heißer Bad Boys und in meiner Brust schlägt das Herz einer Schriftstellerin. Allerdings habe ich keine Ahnung von der Liebe, geschweige denn von der schönsten Nebensache der Welt. Wie soll ich unter diesen Voraussetzungen ein Buch über eine Frau schreiben, die einen Männer-Harem um sich schart?', '19.05.2023', NULL, ARRAY['Deutsch']::text[], 319, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Dark Romance']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Virginie']::text[], '{}', '{}', '41aab241-2feb-55ef-9dae-022d3731157f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
