insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7d1c8fa9-f061-54f2-9c0c-92fb040cab8b', 'Skyn', NULL, NULL, 'When Fawl’s ex dumps her for her stepsister, she takes the messiest deal imaginable: dig up dirt on an Elite family for a golden ticket out of the Underground. Simple, right? No. Now she’s somehow *Checks Notes* married to an emotionless machine who’s weirdly obsessed with her skin.', '07.10.2025', NULL, ARRAY['Englisch']::text[], 165, NULL, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Fawl']::text[], ARRAY['Fake Marriage','Revenge Plot']::text[], ARRAY['Body Horror']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '3', '{}', 'sheet', :'owner') on conflict do nothing;
