insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e846c20b-f52a-53b5-b486-41246590d91d', 'Faunblut', NULL, '9783570160091', 'Faun ist ein Jäger des Zwielichts, wild und verstörend schön. Seine Beute sind die Echos, geheimnisvolle Wesen, die nachts aus den Flüssen steigen. Als Faun angeheuert wird, die Metropole am Rande der Zeit von den Echos zu befreien, begegnet er Jade, dem Mädchen mit den flussgrünen Augen. Eine gefährliche Liebe beginnt, die für Jade den Tod bedeuten kann. Denn Faun hat Jades wahre Natur erkannt, von der sie selbst nichts weiß: Sie ist aus der Verbindung zwischen einem Menschen und einem Echo hervorgegangen, in ihren Adern fließt das Blut der geheimnisvollen Wesen. Als Jade ihr Erbe erkennt und darum kämpft, die Echos zu retten, muss sich Faun entscheiden: zwischen seiner Liebe zu Jade und seinem Verlangen, sie zu töten …', '01.12.2008', 'cbt', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Faun','Jade']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
