insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('91772e87-4963-55b7-a9b9-ba098a596b52', 'Zweilicht', NULL, NULL, 'Der 17-jährige Jay ist in der Stadt seiner Träume angelangt – ein Jahr wird er als Austauschschüler in New York, der Heimat seines verstorbenen Vaters, verbringen. Gleich zu Beginn verliebt er sich in die geheimnisvolle Madison mit den Indianeraugen. Doch was er keinem zu erzählen wagt: Hin und wieder taucht ein anderes Mädchen auf, das außer ihm niemand zu sehen scheint. Sie nennt sich Ivy und er kann nicht aufhören, an sie zu denken. Bis sie ihn schließlich in eine verwunschene Welt entführt, die seit Jahrhunderten kein lebender Mensch betreten hat. Als auch im New York der Gegenwart die Geister und Dämonen erwachen, beginnt für Jay ein Kampf auf Leben und Tod. Der Dämon mit dem Herzen aus Eis ist ihm auf der Spur und giert nach menschlichen Seelen. Und Jay muss sich entscheiden – zwischen zwei Mädchen, zwei Leben, zwei Wirklichkeiten …', '29.08.2011', 'cbt', ARRAY['Deutsch']::text[], 420, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'Teen'::audience_kind, NULL, 'New York', '{}', ARRAY['Jay','Ivy']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
