insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('212b1812-d287-5d37-8476-df68398de2d7', 'Ascheherz', NULL, '9783570160657', 'Seit einem Unfall ist Summers Gedächtnis wie ausgelöscht. Doch sie weiß, dass ihr jemand nach dem Leben trachtet. Als sie mit dem geheimnisvollen, engelhaft schönen Anzej in das ferne Nordland flüchtet, muss Summer erkennen, welchen Verrat sie vor Jahrhunderten begangen hat: Einst gehörte sie zu den Zorya, deren Kuss den Sterblichen den Tod bringt. Doch einem Mann mit sanften Augen, der in ihren Armen sterben sollte, schenkte sie die Ewigkeit. Nun fordert Lady Mar, die Herrin des Todes, das Leben zurück, um das sie betrogen wurde ...', '10.01.2011', 'cbt', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, 'Nordland', '{}', ARRAY['Summer','Anzej']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
