insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('83db40e0-8937-5caf-ac91-33505c9a77c1', 'Ich werde immer da sein, wo du auch bist', 'Hold Still', NULL, 'Das Tagebuch der besten Freundin ist tabu. Es sei denn, die Freundin hat sich das Leben genommen und das Buch unter deinem Bett versteckt. Dann musst du es lesen. Als ihre beste Freundin sich das Leben nimmt, bricht Caitlins Welt auseinander und ihr Herz gleich mit. Warum hat sie das getan? Warum hat sie nichts gesagt? Hätte Caitlin ihr nicht helfen können? So viele Fragen, die unbeantwortet bleiben. Doch dann macht Caitlin eine Entdeckung und erfährt Dinge über ihrer Freundin, von denen sie nicht einmal geahnt hat. Fast mehr, als sie ertragen kann. Und dann kann sie endlich Abschied nehmen.', '10.03.2011', 'Fischer', ARRAY['Deutsch']::text[], 320, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Coming of Age']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Caitlin']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
