insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('77be705d-5fac-5fa3-8f4b-8d40fed3c075', 'M.A.Y.A', NULL, NULL, 'In an effort to escape a war-torn dystopian planet where she would be used as a weapon to hurt innocent people, MAYA searches for a way to stop her captors by fleeing through one of six dimensions in a hidden bunker. There, she meets a pack of shifters and an alpha determined to claim her as his fated mate.', '07.10.2025', NULL, ARRAY['Englisch']::text[], 163, 18, 'Kurzgeschichte'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Erotik']::text[], 'NA'::audience_kind, 'Zukunft'::time_period, 'Earth, 2040, Dimension 6: United States of America', ARRAY['Double POV','3P Limited']::text[], ARRAY['Maya']::text[], ARRAY['Shapeshifters','War Romance','Soul Mates','Forced Proximity']::text[], ARRAY['Folter','Psychische Erkrankung/Belastung','Body Horror','Kidnapping']::text[], '1e483446-8299-5f6e-b954-d90d07cd9b01', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7fa16dfc-bcbe-598f-a874-10d6691c99f2', :'owner', '77be705d-5fac-5fa3-8f4b-8d40fed3c075', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Collector''s', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'dislike'::verdict_kind, 1.5, 'untertroffen'::expectation_kind, 5, 'slow'::burn_kind, 'Leider war diese Story nichts für mich. Ich hab wirklich versucht Maya zu mögen aber Isajah fand ich leider durchgehend unerträglich. Er behauptet die ganze Zeit das beste für sie  zu wollen, während er eigentlich die ganze Zeit nur dafür kämpft, seinen Willen durchzusetzen.  Ich fand die ganze Beziehung zwischen den beiden einfach nur unangenehm. Außerdem schien es auch keine ordentliche Hanldung zu geben, bzw keinen Plan für irgendwas. Da es eine Kurzgeschichte war, war außerdem vieles viel zu gerushed.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('37f30987-0db2-5b72-a02d-1b2fede0cd38', '7fa16dfc-bcbe-598f-a874-10d6691c99f2', :'owner', 1, '2026-03-31', '2026-04-02', NULL, NULL, 3, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b41d62a9-93a5-56ab-a094-5486d490aa59', 'Schattenblüte - Die Verborgenen', NULL, '9783862520008', 'Seit dem Tod ihres Bruders ist für Luisa nichts mehr, wie es war. Sie beschließt zu sterben. Aber kurz vor dem letzten Schritt hält jemand sie auf: Thursen nennt sich der Junge mit den ­geheimnisvollen Schattenaugen. Mit einer Gruppe ­Jugendlicher lebt er im Wald, und er spürt Luisas Schmerz. Die «Verborgenen» können ihre Gestalt ändern: Sie sind ­Werwölfe. Mit jeder Verwandlung wird Thursen mehr zum Tier – und die Erinnerungen an sein vorheriges Leben verblassen. Bald wird er ganz Wolf sein. Dann hat Luisa auch ihn verloren. Für ihre große Liebe ­würde sie alles tun. Doch reicht das, um Thursen zu retten?', '01.11.2010', 'Rowohlt', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Luisa','Thursen']::text[], '{}', '{}', '55006163-584a-5c01-ad80-9da5635ce0c3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
