insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e870a0a5-0bae-57cb-8ca2-e775c77d0cfc', 'Das Bildnis des Dorian Gray', 'The Picture of Dorian Gray', NULL, 'Oscar Wildes Dorian Gray ist eine der berühmtesten Figuren der Weltliteratur: So stauneswert schön er ist, so unverdorben und naiv ist sein Blick auf die Welt. Verführt durch den geistreichen Zyniker Lord Wotton, stürzt Dorian sich haltlos ins lüsterne Londoner Nachtleben. Ausschweifung und Genuss wecken in ihm den innigen Wunsch nach unvergänglicher Jugend - und auf wundersame Weise altert fortan nicht mehr er selbst, sondern ein Porträt von ihm. Doch Dorians unbedachter Pakt mit dunklen Mächten hat grausame Folgen...', '1890', NULL, ARRAY['Deutsch']::text[], 294, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Gothic']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Dorian Gray']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
