insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b075368f-4d83-5c91-99bf-769808f8f1c7', 'Hate Me or Date Me', 'Omoichigai ga Koi no Tane', '9783770459681', 'Arzt Reiji verabscheut nichts mehr als Pharmareferenten, die er allesamt für gewissenlose Verbrecher hält. Als der quirlige Vertreter Shingo auf Reiji angesetzt wird, sieht es zunächst nicht so aus, als könnte er dessen harte Schale knacken. Doch als es Reiji und Shingo zu einer Konferenz in einem abgeschiedenen Landhotel verschlägt, müssen sich die beiden plötzlich auf engstem Raum miteinander arrangieren...', '05.03.2020', 'Egmont Manga', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Reiji','Shingo']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
