insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3704c303-cd3d-5de3-954d-f3acc8200770', 'House of Night - Gezeichnet', 'House of Night - Marked', '9783596860036', 'Als auf der Stirn der 16jährigen Zoey Redbird eine saphirblaue Mondsichel aufscheint, weiß sie, dass ihr nicht viel Zeit bleibt, um ins House of Night, das Internat für Vampyre, zu kommen. Denn jetzt ist sie gezeichnet. Im House of Night soll sie zu einem richtigen Vampyr ausgebildet werden – vorausgesetzt, dass sie die Wandlung überlebt. Zoey ist absolut nicht begeistert davon, ein neues Leben anfangen zu müssen, so ganz ohne ihre Freunde – das einzig Gute ist, dass ihr unerträglicher Stiefvater sie dort nicht mehr nerven kann. Aber Zoey ist kein gewöhnlicher Vampyr – sie ist eine Auserwählte der Vampyrgöttin Nyx. Und sie ist nicht die Einzige im House of Night mit besonderen Fähigkeiten...', '29.12.2009', 'Fischer', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '1', '{}', 'sheet', :'owner') on conflict do nothing;
