insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bfb286ae-2e2f-514e-a15d-a722a32b39ed', 'House of Night - Betrogen', 'House of Night - Betrayed', '9783841420022', 'Zoey hat sich im House of Night eingelebt und gewöhnt sich an die enormen Kräfte, die ihr die Göttin Nyx verliehen hat. Endlich fühlt sie sich sicher und zu Hause, da passiert das Unfassbare: Menschliche Teenager werden getötet und alle Spuren führen zum House of Night. Als die Freunde aus ihrem alten Leben in höchster Gefahr schweben, ahnt Zoey, dass die Kräfte, die sie so einzigartig machen, eine Bedrohung sein können: für alle, die sie liebt.', '26.03.2010', 'Fischer', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '2', '{}', 'sheet', :'owner') on conflict do nothing;
