insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2eb8fa58-646d-5184-964a-78c0857d85f8', 'House of Night - Erwählt', 'House of Night - Chosen', '9783841420039', 'Dunkle Mächte sind im House of Night am Werk und Zoeys Erlebnisse im Internat nehmen eine rätselhafte Wendung. Zoeys beste Freundin Stevie Rae ist untot und versucht mit aller Macht, ihre Menschlichkeit nicht vollends zu verlieren. Und Zoey hat keine Ahnung, wie sie ihr dabei helfen kann, aber sie spürt, dass alles, was sie und Stevie Rae herausfinden vor den anderen im House of Night geheim gehalten werden muss. Denn plötzlich scheint es keinen mehr zu geben, dem sie wirklich vertrauen können. Als es kaum noch schlimmer kommen kann, werden Leichen gefunden: ermordete Vampyre! Aber Zoey findet heraus, dass nichts so ist wie es scheint…', '03.08.2010', 'Fischer', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '3', '{}', 'sheet', :'owner') on conflict do nothing;
