insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ab2d9c0d-0cab-5ddb-81d2-690c227255b8', 'House of Night - Ungezähmt', 'House of Night - Untamed', '9783841420046', 'Das Leben ist total ätzend, wenn deine Freunde so richtig sauer auf dich sind. Zoey weiß, wovon sie spricht. In nur einer Woche wenden sich alle Ihre Freunde von ihr ab und sie wird zur absoluten Außenseiterin. Jetzt bleiben ihr nur noch zwei wirkliche Freunde, allerdings ist die eine untot und der andere nicht mal Gezeichnet. Außerdem hat die Hohepriesterin Neferet den Menschen den Krieg erklärt und Zoey weiß tief in ihrem Herzen, dass das falsch ist. Aber wird irgendjemand auf sie hören? Zoeys Abenteuer auf dem Vampyr-Internat nehmen eine gefährliche Wendung: Ihr Vertrauen wird auf eine harte Probe gestellt, schreckliche Pläne kommen ans Licht, und eine uralte, böse Macht erhebt sich.', '11.11.2010', 'Fischer', ARRAY['Deutsch']::text[], 544, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '4', '{}', 'sheet', :'owner') on conflict do nothing;
