insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fcd536f5-943b-55f4-ae80-6677cb97ecb5', 'House of Night - Gejagt', 'House of Night - Hunted', '9783841420053', 'Zoey ist wieder mit ihren Freunden vereint und Stevie Rae und die roten Jungvampyre sind nicht länger Neferets Geheimnis. Aber eine dunkle Gefahr bedroht die neue Ruhe. Kalona, Neferets neuer Liebhaber, sieht umwerfend aus und hat das gesamte House of Night in seinen Bann gezogen. Und niemand scheint zu bemerken, welche Bedrohung von ihm ausgeht. Der Schlüssel, den es braucht, um seinen immer stärker werdenden Einfluss zu brechen, liegt in der Vergangenheit. Aber was, wenn diese Vergangenheit Geheimnisse offenbart, die Zoey nicht wissen will, und Wahrheiten, denen sie sich nicht zu stellen traut?', '11.02.2011', 'Fischer', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '5', '{}', 'sheet', :'owner') on conflict do nothing;
