insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('cfb9fc0d-f182-5270-9c72-581f79e570e8', 'b4c605ef-8ab5-5485-97c7-474a1203dffd', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('64756ded-4fb2-5ca3-9e24-84f7938eb36d', 'House of Night - Versucht', 'House of Night - Tempted', '9783841420060', 'Nachdem Zoey und ihre Freunde Kalona und Neferet aus Tulsa vertrieben haben, hätten sie eigentlich eine Pause verdient. Aber obwohl Zoey und ihr sexy Krieger Stark sich erst einmal von ihrer Begegnung mit dem Tod erholen müssten und auch die Jungvampyre die Nachwirkungen von Neferets Terrorherrschaft zu verarbeiten hätten, ist ihnen allen keine Ruhe vergönnt. Stevie Rae glaubt mit ihren außergewöhnlichen Kräften gut allein all das regeln zu können, was sie vor ihren Freunden verheimlicht. Doch eine mysteriöse und beängstigende Macht breitet sich in den Tunneln unter Tulsa aus. Aber Stevie Rae will nicht sagen, was dort vor sich geht und was sie dort gemacht hat. Allmählich beginnt Zoey sich zu fragen, ob sie ihr überhaupt noch vertrauen kann. Werden sie die richtigen Entscheidungen treffen oder werden dunkle Mächte das House of Night zerstören?', '12.05.2011', 'Fischer', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '6', '{}', 'sheet', :'owner') on conflict do nothing;
