insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bbabbdbe-dfe7-5bb7-88c5-e139d347859d', 'House of Night - Verbrannt', 'House of Night - Burned', '9783841420077', 'Wenn Freunde sich nicht mehr vertrauen können, gewinnt das Böse die Oberhand. Die Dinge stehen schlecht im House of Night. Zoeys Seele ist zerschmettert. Um sie herum ist alles zerstört, wofür sie je gekämpft hat. Und mit einem gebrochenen Herzen will sie lieber in der Schattenwelt bleiben. Stark scheint der Einzige zu sein, der zu ihr durchdringen könnte, doch dafür müsste er sterben. Und das würde Zoey umbringen. Doch auch Stevie Rae und Aphrodite könnten helfen, wenn sie nur wollten. Warum zögern sie? Ein Spiel mit dem Feuer, das alle verbrennen könnte…', '12.08.2011', 'Fischer', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '7', '{}', 'sheet', :'owner') on conflict do nothing;
