insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b345ada4-7bd4-55fb-b1eb-35ccb02a0e86', 'House of Night - Geweckt', 'House of Night - Awakened', '9783841420084', 'Was ist stärker: Die Bande der Freundschaft oder die Fesseln der Liebe? Neferet, die Hohepriesterin des House of Night in Tulsa, hat Rache geschworen an Zoey. Dabei ist der unsterbliche Kalona nur eine der Waffen, die sie einsetzen will. Doch Zoey hat Zuflucht bei Königin Sgiach auf der Isle of Skye vor der Küste Schottlands gefunden. Dort müssen sie und ihr Krieger Stark erst einmal wieder zu Kräften kommen. Außerdem möchte Sgiach sie zu ihrer Nachfolgerin ernennen. Warum soll sie also wieder nach Tulsa und zum House of Night zurückkehren? Nach dem Tod von Heath ist sowieso nichts mehr so wie früher. Und auch die Beziehung zu Stark könnte nicht mehr das sein, was sie einmal war.', '11.11.2011', 'Fischer', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '8', '{}', 'sheet', :'owner') on conflict do nothing;
