insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('610a9d2b-a193-5c3f-8ca3-2c1762698610', '45fabde5-9e54-5597-80ae-045b54c0d474', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8ba1f10-9ad2-5982-88c4-890533fb8f1e', 'House of Night - Bestimmt', 'House of Night - Destined', '9783841420091', 'Zoey ist wieder zurück im House of Night in Tulsa, gemeinsam mit ihrem Krieger Stark, der sie beschützt. Doch nun wird ein Treffen mit der nach Rache dürstenden Hohepriesterin Neferet unausweichlich. Neferet ist noch immer mit den Mächten der Finsternis im Bunde, ihre Macht größer denn je. Ist Zoey wirklich sicher in diesem Haus? Und weiß sie, wer ihre wahren Freunde sind? Auch für Rephaim, der Stevie Rae nicht mehr aus den Augen lässt, entscheidet sich jetzt alles: Durch eine Gabe der Göttin Nyx hat er menschliche Gestalt angenommen und kann auf diese Weise endlich mit ihr zusammen sein.Doch wird er den Weg des Guten auch weiterhin gehen? Kann die Liebe siegen, wenn sie von den Mächten der Finsternis auf den Prüfstand gestellt wird?', '23.05.2012', 'Fischer', ARRAY['Deutsch']::text[], 560, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '9', '{}', 'sheet', :'owner') on conflict do nothing;
