insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('38cd1d0d-d07a-5a19-8558-17346b434392', 'House of Night - Verloren', 'House of Night - Hidden', '9783841422170', 'Das Chaos regiert im House of Night. Die Mächte der Finsternis gehorchen jetzt Neferet. Aber sie fordern einen hohen Preis aus Blut, Schmerz und Tod. Das Böse ist eben unersättlich. Neferet ist nicht mehr länger Hohepriesterin im House of Night in Tulsa. Nachdem sie sich ganz dem Bösen verschrieben hat, muss sie die Schule verlassen. Doch sie geht nicht, ohne eine Schneise der Verwüstung zu hinterlassen. Zoey und ihre Freunde wissen, dass die Schule nur dann weiterbestehen kann, wenn jetzt alle zusammenhalten. Denn Neferet wird mit allen Mitteln ihr Ziel weiter verfolgen: Sie will Zoey töten. Und mit Hilfe von Aurox könnte ihr das auch gelingen. Doch Zoey glaubt, in Aurox ihren Menschenfreund Heath entdeckt zu haben. Kann das sein? Er ist doch Neferets Werkzeug. Oder etwa nicht? Zoeys Grandma scheint ihm zu vertrauen…', '28.11.2012', 'Fischer', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'House of Night', '{}', ARRAY['Zoey']::text[], '{}', '{}', 'ed595fe0-13da-5d0a-95de-39346e210bce', '10', '{}', 'sheet', :'owner') on conflict do nothing;
