insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('97669681-7842-59cd-854f-478ec0214e84', 'You deserve this: Simple & Natural Recipes for a Healthy Lifestyle', NULL, '9783960961086', 'Gesunde und natürliche Ernährung ist das, was Körper und Seele täglich verdienen. Und das hat rein gar nichts mit Verzicht zu tun! Sich langfristig großartig zu fühlen, vor Energie zu sprühen und der Gesundheit etwas Gutes zu tun, ist auch im Alltag möglich - mit Bowls! Dabei werden einfache, natürliche und vollwertige Gerichte ohne stundenlange Küchenarbeit in schönen Schalen angerichtet und serviert. Hierfür hat Pamela Reif ihre liebsten Rezepte fotografiert und niedergeschrieben. Ergänzt wird das Bowl-Kochbuch durch eine grundlegende Lebensmittelkunde, die den Sinn und die Vorteile dieser ausgewogenen Ernährung leicht verständlich erläutert. Die ultimative Ernährungsformel ist nicht zwangsläufig "low carb" oder "low fat" - es kommt darauf an, dass die Nahrung "echt" und natürlich ist.', '10.06.2020', 'Community Editions', ARRAY['Deutsch']::text[], 224, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Kochen & Ernährung', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
