insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d76e034-8bc1-5615-a8ce-fc3f6be1a40e', 'The Perfect', NULL, NULL, 'Adam C. Oulay sucht DICH! ''Teile deine Kreativität, dein Trendgefühl und deinen Geschäftssinn mit mir – und vielleicht sogar noch mehr … BEWIRB DICH JETZT!'' Wie weit würdest du für deinen Erfolg gehen? Wärest du bereit, ALLES zu tun, um dieses Casting zu gewinnen? Auch wenn du niemandem trauen kannst, außer deiner besten Freundin? Selbst dann, wenn euer beider Leben in Gefahr wäre? Es könnte DIE Chance sein – für eine von euch. Oder aber der Weg in die Hölle …', '11.01.2016', 'Coppenrath', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Coming of Age']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Jazz']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
