insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e635689a-3c58-597f-800b-72a94ee3bcbe', 'Meeresflüstern', NULL, NULL, 'Nach dem Tod ihres Vaters verlässt die siebzehnjährige Elodie ihre Heimatstadt Lübeck, um bei ihrer Großtante auf Guernsey zu leben. Als wenig später auf der Nachbarinsel ein Mädchen ermordet aufgefunden wird, glaubt sie, dass ihre Ankunft auf der Kanalinsel in irgendeinem Zusammenhang mit dem schrecklichen Vorfall steht. Aber wie ist das möglich? Und wer ist der wunderschöne Junge, dem Elodie in ihren Träumen begegnet? Dann, eines Tages, taucht dieser Junge plötzlich wie ein Geschöpf aus dem Meer vor ihr auf. Geheimnisvoll. Magisch. Betörend. Elodie kann nicht aufhören, an ihn zu denken. Und sie beginnt zu ahnen, welche Geheimnisse der Ozean tatsächlich verbirgt und wie sehr ihr eigenes Schicksal mit den dunklen Legenden der Kanalinseln verknüpft ist. Eine berauschende Liebessaga vor der atemberaubenden Küste Guernseys!', '01.01.2012', 'Coppenrath', ARRAY['Deutsch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, 'Guernsey', '{}', ARRAY['Elodie']::text[], '{}', '{}', 'dbeb8c9a-83c2-5056-a855-cd0842d620e4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
