insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6fc456e7-7f37-508e-b47e-6ec0a2aa1cb5', 'Spark of the Everflame', NULL, '9781035428939', 'In a mortal world colonized by the gods and ruled over by their cruel, magical offspring called the Descended, healer Diem Bellator yearns to escape her poor village. Her mother’s sudden disappearance—and the discovery of a dangerous secret about her past—offer Diem an unexpected opportunity to enter the dark world of Descended royalty and unlock a web of mysteries left behind by her mother. With the dying King’s handsome yet enigmatic heir watching her every move and a ruthless rebel alliance recruiting her to join the growing civil war, Diem must navigate the unwritten rules of love, power, and politics in order to save her family—and all of mortalkind.', '07.11.2024', 'Headline', ARRAY['Englisch']::text[], 405, 32, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Diem Bellator']::text[], '{}', '{}', 'cb1b6481-01c9-5706-b071-6cfac9c34274', '1', '{}', 'sheet', :'owner') on conflict do nothing;
