insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1420c793-4a85-52a1-8fb0-645e5ebf97d1', 'I Do Hate You', 'The Worst Wedding Date', '9783736323209', 'Delaney Kingston würde alles tun, damit die Hochzeit ihrer besten Freundin reibungslos über die Bühne geht. Auch Aufpasserin für Emmas älteren Bruder Theo spielen und sich zu allem Überfluss auch noch ein Zimmer mit ihm teilen, obwohl dieser ihr Erzfeind seit der dritten Klasse ist. Die beiden könnten unterschiedlicher nicht sein, doch schnell erkennt Laney, dass sich hinter Theos Fassade des charmanten Troublemakers so viel mehr verbirgt. Und plötzlich erwischt sie sich dabei, dass ihr Herz jedes Mal ein bisschen schneller schlägt, wenn sie mit Theo zusammen ist ...', '23.12.2024', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Delaney Kingston','Theo']::text[], '{}', '{}', '24ea940d-5318-57d4-92d5-33ae16dd1235', '1', '{}', 'sheet', :'owner') on conflict do nothing;
