insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8a21030d-124f-5860-97b0-94d16f3560d8', 'I Do Regret You', 'The Gossip and the Grump', '9783736324305', 'Als Sabrina Sullivan dem charmanten, gut aussehenden Greyson Cartwright ihr Herz ausschüttet und mit ihm die Nacht ihres Lebens verbringt, ahnt sie noch nicht, dass sie ihn eine Woche später im Sullivan-Familiencafé in den Bergen wiedersehen wird - als neuen Besitzer! Die Zukunft des Cafés und Sabrinas ganze Welt stehen auf dem Spiel, denn Greyson will dort aus Rache an ihrer Familie alles umkrempeln. Doch Sabrina schmiedet einen Plan: sein Vertrauen gewinnen und seine tiefsten Geheimnisse in Erfahrung bringen. Denn so attraktiv er auch sein mag, einer von ihnen muss verschwinden, und das wird nicht Sabrina sein ...', '25.04.2025', 'LYX', ARRAY['Deutsch']::text[], 471, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Sabrina Sullivan','Greyson Cartwright']::text[], ARRAY['Enemies to Lovers','Forced Proximity']::text[], '{}', '24ea940d-5318-57d4-92d5-33ae16dd1235', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
