insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f2bce463-f641-5cc6-9b6b-291ed6d3dba6', 'I Do Resist You', 'The Bride''s Runaway Billionaire', '9783736325142', 'Nach ihrer katastrophalen Fast-Hochzeit fliegt Emma Monroe allein in die Flitterwochen. Dass sie hier eines Morgens ihren Nummer-1-Celebrity-Crush Jonas Rutherford, Filmstar und Erbe eines milliardenschweren Entertainment-Konzerns, schlafend auf der Veranda ihres Bungalows vorfindet, hat sie nicht erwartet. Dass er sie drei Tage später nach einer gemeinsamen Nacht direkt ghosten würde, auch nicht. Zwei Jahre danach crasht Jonas die Hochzeit von Emmas Bruder und staunt nicht schlecht, dass der kleine Junge dort nicht bloß der Ringträger, sondern ihm auch wie aus dem Gesicht geschnitten ist ...', '29.08.2025', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Emma Monroe','Jonas Rutherford']::text[], ARRAY['Pregnancy','Royalty','Famous Person']::text[], '{}', '24ea940d-5318-57d4-92d5-33ae16dd1235', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
