insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4bd9a5c0-08a9-5765-bf67-f615af639053', 'Dear.Door (Vol.1)', '디어 도어', '9783551803498', 'Nach dem Tod seiner Freundin möchte der Polizist Kyungjoon einfach nur in Ruhe seine Zimmerpflanzen gießen und Verbrecher jagen. Doch als diepolizeilichen Ermittlungen gegen eine mysteriöse Sekte übernatürliche Ausmaße annehmen, findet sich Kyungjoon unversehens in einer Welt voller Dämonen und Monster wieder. Der Schlimmste von ihnen ist der Dämonenkönig, der sich selbst Lord Cain nennt. Wie sich herausstellt, ist Cain zum Überleben auf Mana angewiesen, das nur durch ein »Portal« in Kyungjoon zugänglich ist. Doch wie öffnet er dieses Portal?', '26.03.2024', 'Lines', ARRAY['Deutsch']::text[], 288, 11, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Yaoi']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Kyungjoon','Lord Cain']::text[], ARRAY['Good vs. Evil','Magical Creatures','Monster Love','Queer']::text[], '{}', '6fecbcab-f20c-53e8-8250-07e238d6a09e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
