insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eb57d794-2573-58c7-86e8-7efe09aa013b', 'Die geheime Sammlung', NULL, '9783426283318', 'Es ist nicht leicht, eine Außenseiterin zu sein. Doch dann bekommt Elizabeth einen Aushilfsjob in einem ganz besonderen Museum, dem New Yorker Repositorium der verleihbaren Schätze, in dem man Kunst und Krempel, Wertvolles und Verrücktes ausleihen kann: alte Möbel, schönen Schmuck, eine Perücke, mit der Marie Antoinette einst durch ihr Schloss stolzierte. In den geheimnisvollen Lagerhallen fi ndet Elizabeth aber auch endlich echte Freunde, die bereit sind, mit ihr durch Dick und Dünn zu gehen. Und die braucht sie dringender, als sie geahnt hat – denn verborgen im Keller gibt es noch eine ganz besondere Sammlung, deren Schätze allesamt magische Kräfte haben. Nun beginnt jemand, ihnen den Zauber zu rauben. Nur Elizabeth kann dies verhindern, aber damit bringt sie sich selbst in große Gefahr …', '05.05.2010', 'Pan', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'New Yorker Repositorium', '{}', ARRAY['Elizabeth']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
