insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fd15d3fd-7282-5779-a4db-255a9cd2d9f9', 'Wonderful Wonder World (Vol.1)', 'Soumei Hoshino', '9783867199131', 'Als Alice im Garten ihres Hauses plötzlich einschläft, erscheint vor ihren Augen ein junger Mann mit Hasenohren. Er entführt sie in eine Märchenwelt, die sich alsbald als gefährlicher Ort entpuppt, wo die Bewohner ihre Streitigkeiten mit der Waffe austragen!', '12.03.2010', 'TokyoPop', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, NULL, 'Wunderland', ARRAY['3P Objective']::text[], ARRAY['Alice']::text[], '{}', '{}', 'a96d752d-8f25-5499-ba28-3bd8f5043811', '1', '{}', 'sheet', :'owner') on conflict do nothing;
