insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6f6c0551-5d8d-533e-85c7-683c8b98f4bf', 'Fear Street: Bad Dreams', NULL, '9780671785697', 'Every night Maggie Travers has the same horrible dream. Every night she is forced to watch the same murder. And every night the girl in her dream cries out for help. Maggie is afraid to go to sleep again. But when the terrifying dream starts to come true and the gruesome accidents begin, staying awake is the real nightmare!', '01.03.1994', 'Simon Pulse', ARRAY['Englisch']::text[], 148, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Maggie Travers']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
