insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4670e4fa-98f3-5444-b5e8-601d0d3c57e7', 'Fear Street: Ausgelöscht - Denn Erinnerung kann töten…', 'Fear Street - The Face', '9783785559963', 'Wie ausgelöscht ist Marthas Erinnerung an den kalten Novembertag vor einem Jahr. Etwas Schreckliches muss damals passiert sein. Denn seit diesem Tag hat sich alles geändert. Ihre Freunde haben sich von ihr zurückgezogen. Und Martha zeichnet wieder und wieder das Gesicht eines Jungen – eines toten Jungen ...', '01.06.2007', 'Loewe', ARRAY['Deutsch']::text[], 150, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Martha']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
