insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('66757f6a-8890-5348-ace9-5d8b0e33ef49', 'Fear Street: Eiskalter Hass - Er kommt dich holen', 'Fear Street - Haunted', '9783785566923', '"Ich bin nicht verrückt", denkt Melissa. Doch sie ist die Einzige, die den Einbrecher sehen kann. Und der macht ihr das Leben zur Hölle: Er manipuliert ihre Bremsen und stößt sie beinahe aus dem Fenster. Wer ist er? Und was will er von ihr? Melissa weiß nur eins: Sie muss ganz schnell sein Geheimnis lüften – bevor sie tot ist!', '15.06.2009', 'Loewe', ARRAY['Deutsch']::text[], 150, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Melissa']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
