insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d8f5643d-1412-5ab1-a128-a1b49c472cf6', 'Fear Street: Erbe der Hölle', 'The Trhill Climb & The Dare', '9783785564592', 'Tanjas Gesicht ist angstverzerrt. Ihre Freundin Sandra ist ermordet worden. Panisch wird Tanja bewusst, dass sie sich nicht daran erinnern kann, was sie die letzten zwanzig Minuten getan hat und dass ihr Sweatshirt voller Blut ist. Hat sie selbst etwa ihre Freundin umgebracht? Könnte sie wirklich einen Mord begehen? Diese Frage hat sich auch in Johannas Kopf gebrannt. Warum hat es ihr Geschichtslehrer auch immer auf Dennis'' Clique abgesehen? Sie schmieden einen gefährlichen Racheplan: Wäre es nicht die beste Lösung, den Lehrer einfach umzubringen? Wer wird es tun? Enthält die beiden Einzelbände "Die Mutprobe" und "Die Wette".', '15.09.2010', 'Loewe', ARRAY['Deutsch']::text[], 300, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Tanja']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
