insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2d1668f4-b8a1-59e7-8a8b-6d45c4a8ee84', 'Fear Street: Opfer der Nacht', 'All-Night Party & Ski Weekend', '9783785562130', 'Hohe Wellen peitschen wild ans Ufer. Trotzdem rudern Donna und ihre Freunde zur einsamen Hütte auf Fear-Street-Island, um dort eine Party zu feiern. Nur kurze Zeit später findet Donna einen der Freunde tot auf. Ist ein Mörder unter ihnen? Auch Ally und ihre Freunde verschlägt es an einen abgelegenen Ort. Ein Schneesturm zwingt sie dazu, in einer abgeschiedenen Waldhütte Zuflucht zu suchen. Doch was zunächst als sichere Herberge erscheint, stellt sich schnell als lebensgefährliche Falle heraus.', '01.01.2008', 'Loewe', ARRAY['Deutsch']::text[], 301, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Donna']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
