insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d1032773-521f-50b9-a073-522aba48868b', 'Fear Street: Rache ist tödlich', 'Fear Street - The Best Friend', '9783785567609', 'Honey taucht wie aus dem Nichts auf und drängt sich mit voller Wucht in Beckas Leben. Sie will um jeden Preis die neue beste Freundin sein! Was anfangs nur nervt, wird schon bald zur tödlichen Bedrohung. Denn Honey duldet keine Konkurrenten... Gefährlich leben auch Janie und ihre Freundinnen. Sie wetten darum, wer als erste ein Date mit Ross hat – diesem Traumtyp mit den dunklen, geheimnisvollen Augen. Die glückliche Gewinnerin ist Eve ... bis sie am Tag danach tot aufgefunden wird.', '01.01.2010', 'Loewe', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Becka','Janie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
