insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d275f9b-0643-578d-b451-bdb9aa8c4afd', 'Fear Street: Straße der Albträume', 'The Sleepwalker & The Mind Reader', '9783785557808', 'Nein, Shadyside ist keine friedliche Kleinstadt. Hier kann sich schon lange niemand mehr sicher fühlen. Denn über der Stadt lastet ein alter Fluch - der Fluch der Fear Street. Jede Nacht versetzt er die Bewohner in Angst und Schrecken. Schlaflos wälzen sie sich hin und her, werden von düsteren Visionen heimgesucht oder schrecken aus entsetzlichen Albträumen hoch. Und manchmal hält das Grauen sie so fest in seinem Griff, dass sie dem Ruf des Bösen folgen. Dann fängt der wahre Albtraum an ...', '01.01.2006', 'Loewe', ARRAY['Deutsch']::text[], 298, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
