insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ee478fc-7eae-582a-b0ac-8c958ed93261', 'Fear Street: Straße des Schreckens', 'The Fire Game & What Holly Heard', NULL, 'Eigentlich sieht die Fear Street aus wie eine ganz normale Straße. Doch die Bewohner von Shadyside wissen es besser. Denn die Fear Street ist die Straße des Schreckens. Seit Jahren passieren dort die unheimlichsten Dinge Menschen verschwinden, Häuser stehen urplötzlich in Flammen, das Böse lauert zwischen harmlos aussehenden Vorgärten. Die Jugendlichen der Shadyside High School tun alles, um diese Straße zu meiden. Doch manchmal gibt es kein Entkommen ...', '01.01.2006', 'Loewe', ARRAY['Deutsch']::text[], 300, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
