insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2ccc3500-ff4d-5628-8e29-4f96e48ad1d6', 'Fear Street: The Perfect Date', NULL, '9783125354104', 'Brady Karlin is getting on with his life. The memory of his girlfriend -- killed in a gruesome sledding accident last year -- is beginning to fade. Now he''s met Rosha Nelson, the girl of his dreams. And he''s never been happier. Until Brady starts to see a strange figure -- with a terribly scarred face -- following him everywhere. Until the horrible accidents start happening -- every time Rosha''s around. Has dating Rosha made Brady''s dreams come true? Or brought his worst nightmares back to life?', '08.06.2006', NULL, ARRAY['Englisch']::text[], 147, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Brady Karlin']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
