insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57d8afcc-bec0-5f1c-a13b-e883c05cb40f', 'Schattenwelt - Das magische Amulett', 'Night of Werecat', NULL, 'Was soll schon an einem Amulett gefährlich sein? Wendy schlägt alle Warnungen in den Wind. Das grünlich schimmernde Amulett mit dem Katzenkopf zieht sie einfach magisch an. Doch dann lässt es sich nicht wieder von ihrem Hals lösen. Und noch in derselben Nacht nimmt eine unheimliche Verwandlung ihren Lauf: Wendys Fingernägel verformen sich zu langen, gebogenen Krallen, und ihre Zähne fühlen sich seltsam spitz an.', '2001', 'Loewe', ARRAY['Deutsch']::text[], 130, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Wendy']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
