insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c7b8b723-71f1-5d52-b805-f4e8b56edf0f', 'Fear Street: Teuflischer Hass', 'Bad Dreams & Silent Night 3', '9783785573655', 'Jede Nacht hat Maggie denselben Albtraum: Ein Mädchen wird mit einem Messer bedroht. Als das Messer eines Tages in ihrem eigenen Kopfkissen steckt, weiß Maggie, dass es jemand auf sie abgesehen hat. Aber niemand glaubt ihr - bis ein schreckliches Unglück passiert. Auch Reva hat einen mörderischen Verfolger. Sie soll im Kaufhaus ihres Vaters eine Modenschau organisieren. Reva wittert ihre große Chance, im Rampenlicht zu stehen und von allen bewundert zu werden. Doch dann wird ein Models nach dem anderen auf brutale Weise ermordet!', '06.06.2011', 'Loewe', ARRAY['Deutsch']::text[], 300, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Shadyside', '{}', ARRAY['Maggie','Reva']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
