insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a4f27a60-2a0e-5966-9a3e-fb1c3219c42e', 'One Good Dragon Deserves Another', NULL, '9781952367380', 'After barely escaping the machinations of his terrifying mother, two all knowing seers, and countless bloodthirsty siblings, the last thing Julius wants to see is another dragon. Unfortunately for him, the only thing more dangerous than being a useless Heartstriker is being a useful one, and now that he’s got an in with the Three Sisters, Julius has become a key pawn in Bethesda the Heartstriker’s gamble to put her clan on top. Refusal to play along with his mother’s plans means death, but there’s more going on than even Bethesda knows, and with Estella back in the game with a vengeance, Heartstriker futures disappearing, and Algonquin’s dragon hunter closing in, the stakes are higher than even a seer can calculate. But when his most powerful family members start dropping like flies, it falls to Julius to defend the clan that never respected him and prove that, sometimes, the world’s worst dragon is the best one to have on your side.', '01.08.2025', NULL, ARRAY['Englisch']::text[], 487, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Julius Heartstriker']::text[], ARRAY['Epic Quest','Family Drama','Magical Creatures','Outsider Hero']::text[], '{}', '394b5ca1-e7d2-54a4-a561-a5d7415d4736', '2', '{}', 'sheet', :'owner') on conflict do nothing;
