insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5a4c8eed-4534-518b-a68f-20cc64d946f6', 'No Good Dragon Goes Unpunished', NULL, NULL, 'When Julius overthrew his mother and took control of his clan, he thought he was doing right by everyone. But sharing power isn’t part of any proper dragon’s vocabulary, and with one seat still open on the new ruling Council, all of Heartstriker is ready to do whatever it takes to get their claws on it, including killing the Nice Dragon who got them into this mess in the first place. To keep his clan together and his skin intact, Julius is going to have to find a way to make his bloodthirsty siblings play fair. But there’s more going on in Heartstriker Mountain than politics. Every family has its secrets, but the skeletons in Bethesda’s closet are dragon sized, and with Algonquin’s war looming over them all, breaking his clan wide open might just be the only hope Julius has of saving it.', '05.08.2016', NULL, ARRAY['Englisch']::text[], 517, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Julius Heartstriker']::text[], ARRAY['Epic Quest','Family Drama','Magical Creatures','Outsider Hero']::text[], '{}', '394b5ca1-e7d2-54a4-a561-a5d7415d4736', '3', '{}', 'sheet', :'owner') on conflict do nothing;
