insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ffa42c4f-7f0c-58a2-ae69-88aa4cf32eaa', 'A Dragon of a Differen Color', NULL, '9781952367403', 'To save his family from his tyrannical mother, Julius had to step on a lot of tails. That doesn’t win a Nice Dragon many friends, but just when he thinks he’s starting to make progress, a new threat arrives. Turns out, things can get worse. Heartstriker hasn’t begun to pay for its secrets, and the dragons of China are here to collect. When the Golden Emperor demands his surrender, Julius will have to choose between loyalty to the sister who’s always watched over him and preserving the clan he gave everything to protect.', '28.07.2017', NULL, ARRAY['Englisch']::text[], 525, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Julius Heartstriker']::text[], ARRAY['Epic Quest','Family Drama','Magical Creatures','Outsider Hero']::text[], '{}', '394b5ca1-e7d2-54a4-a561-a5d7415d4736', '4', '{}', 'sheet', :'owner') on conflict do nothing;
