insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d6a6fe2e-c455-57f2-96cd-26629d2a64f9', 'Last Dragon Standing', NULL, '9781952367410', 'Dear Reader, There is no way to write a blurb for this final book without spoiling all of the others. Suffice it to say, mysteries resolve, dragons war, pigeons abound, and Julius must risk himself in ways he never dreamed possible as Bob’s grand plan finally comes to fruition. But the Great Seer of the Heartstrikers isn’t the only one whose schemes are nearing completion. The Nameless End is coming, and even the machinations of the world’s most brilliant dragon seer might not be enough to stop it. As the world comes crashing down, it’s up Julius to prove what he’s always known: that seers can be wrong, and Nice Dragons don’t always finish last.', '01.03.2018', NULL, ARRAY['Englisch']::text[], 319, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, NULL, ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Julius Heartstriker']::text[], ARRAY['Epic Quest','Family Drama','Magical Creatures','Outsider Hero']::text[], '{}', '394b5ca1-e7d2-54a4-a561-a5d7415d4736', '5', '{}', 'sheet', :'owner') on conflict do nothing;
