insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0ba7c7a7-5b84-516b-b4db-21e12b20d02e', 'Nice Dragons Finish Last', NULL, '9781500506339', 'As the smallest dragon in the Heartstriker clan, Julius survives by a simple code: keep quiet, don’t cause trouble, and stay out of the way of bigger dragons. But this meek behavior doesn''t fly in a family of ambitious magical predators, and his mother, Bethesda the Heartstriker, has finally reached the end of her patience. Now, sealed in his human form and banished to the DFZ--a vertical metropolis built on the ruins of Old Detroit--Julius has one month to prove he can be a ruthless dragon or kiss his true shape goodbye forever. But in a city of modern mages and vengeful spirits where dragons are considered monsters to be exterminated, he’s going to need some serious help to survive this test. He only hopes humans are more trustworthy than dragons...', '11.07.2014', 'CreateSpace', ARRAY['Englisch']::text[], 286, 18, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Zukunft'::time_period, 'DFZ', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Julius Heartstriker']::text[], ARRAY['Epic Quest','Family Drama','Magical Creatures','Outsider Hero']::text[], '{}', '394b5ca1-e7d2-54a4-a561-a5d7415d4736', '1', '{}', 'sheet', :'owner') on conflict do nothing;
