insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4de32525-9088-536a-9c72-5953b3cdd370', 'Beta', NULL, '9781423173359', 'Elysia was born without a soul, her only purpose to serve the wealthy inhabitants of Io, an island paradise. But sensations are clouding her mind...anger...loneliness???love. Before long, Elysia learns that she is a Defect. And If any human on the island discovers the truth, it will cost her her life.', '25.02.2013', 'Little, Brown Books', ARRAY['Englisch']::text[], 416, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Denesme', '{}', ARRAY['Elysia']::text[], '{}', '{}', '95ad1650-f7a4-555b-b032-fef6d85d2389', '1', '{}', 'sheet', :'owner') on conflict do nothing;
