insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6e450604-89e7-5969-956b-3e3980cedeaf', 'One Dark Window', NULL, '9783736321861', 'Wer von der Magie befallen ist, die im Nebel von Blunder lauert, wird von der Königsgarde vernichtet. Doch Elspeth Spindle hat überlebt, dank des düsteren Wesens, das in ihrem Geist gefangen ist und ihr enorme Kräfte verleiht. Eines Nachts begegnet sie im Wald einem geheimnisvollen Mann. Ravyn Yew, Hauptmann der königlichen Streiter, will den Fluch des Nebels brechen. Dazu benötigt er zwölf magische Karten, die nur Elspeth finden kann. Und so muss sie nicht nur dem Mann vertrauen lernen, den sie immer als ihren größten Feind sah, sondern sich auch der Anziehung zwischen Ravyn und ihr stellen. Und es gibt noch eine Wahrheit, der sie nicht entrinnen kann: Das Wesen in ihr droht alsbald ihren Geist zu verschlingen ...', '28.06.2024', 'LYX', ARRAY['Deutsch']::text[], 490, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Elspeth Spindle']::text[], '{}', '{}', 'cc97ee39-afcc-548a-b00c-3e7296740012', '1', '{}', 'sheet', :'owner') on conflict do nothing;
