insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4a6c3314-23cd-5b6c-85b2-c481ef549a90', 'The Knight and the Moth', NULL, '9783736324558', 'Schon seit neun Jahren dient Sybil Delling zusammen mit ihren Schwestern in der Kathedrale von Aisling als Weissagerin. Doch als eines Tages der geheimnisvolle Ritter Rodrick Myndacious nach Aisling kommt, ändert sich ihr Leben schlagartig. Obwohl der attraktive Rory ihr bei jeder Begegnung zeigt, dass er nicht an Sybils Visionen glaubt, sagt sie auch sein Schicksal vorher - und sieht dort ein mysteriöses Omen, das sie nicht zu deuten weiß. Sybils düstere Vorahnung scheint sich zu bewahrheiten, als ihre Schwestern nach und nach verschwinden. In ihrer Verzweiflung kann sie sich nur an Rory wenden, denn Sybil spürt, dass sie allein mithilfe dieses unverschämten Ketzers die Götter herausfordern kann, die ihr eigenes Schicksal so lange bestimmt haben.', '29.08.2025', 'LYX', ARRAY['Deutsch']::text[], 496, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], NULL, 'Vergangenheit'::time_period, 'Aisling', '{}', ARRAY['Sybil Delling','Rodrick Myndacious']::text[], '{}', '{}', 'eecd71bc-5955-52c8-ab7b-804f20d5fa42', '1', '{}', 'sheet', :'owner') on conflict do nothing;
