insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('65629bc3-b78a-5d80-ad73-a68fc62e88c5', 'Two Twisted Crowns', NULL, '9783736322646', 'Elspeth und Ravyn haben fast alle der magischen Vorsehungskarten zusammengetragen - doch die eine, wichtigste bleibt verborgen: »Die Zwei Erlen«, der Schlüssel zur Rettung von Blunder. Bis zur Nacht der Sonnenwende müssen sie die Karte finden, denn nur dann kann der Fluch des Nebels gebrochen werden, der das Reich verschlingt. Sie müssen tief ins Herz des magischen Waldes vordringen, und der Einzige, der weiß, wo sich die Zwei-Erlen-Karte befindet, ist der Nachtmahr, der seit Jahren in Elspeths Geist lebt. Und der ist nicht länger bereit, nur zuzuschauen ...', '25.10.2024', 'LYX', ARRAY['Deutsch']::text[], 496, 51, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Elspeth Spindle']::text[], '{}', '{}', 'cc97ee39-afcc-548a-b00c-3e7296740012', '2', '{}', 'sheet', :'owner') on conflict do nothing;
