insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7711f435-aa38-5768-b118-54ca155732c4', :'owner', '89ba4351-8cfe-5907-a3ef-12242198de70', 'gelesen'::reading_status, true, false, ARRAY['Digital','Print']::text[], ARRAY['eBook','Taschenbuch']::text[], 'Normal', ARRAY['Floppy']::text[], 1700, false, false, '{}', '{}', NULL, NULL, true, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'erfuellt'::expectation_kind, 5, 'fast'::burn_kind, 'Gegen Ende gab es so viele Zucker süße Momente, in denen ich einfach nur quietschen wollte und die zwei in den Arm nehmen wollte.Der Anfang des Buches hat sich leider viel zu sehr gezogen und es hat sich einfach alles zu sehr widerholt. Doch als die beiden dann endlich mal an den Punkt kamen, dass sie auch miteinander gesprochen haben, wurde das Buch so viel besser.') on conflict do nothing;
