insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('18b32eb1-d134-59ac-bba3-8a976e5ac18d', 'a05452b3-c17f-50ae-ba85-0d9321277894', :'owner', 1, '2024-10-03', '2024-10-04', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('05bae5d5-1836-54d7-a5a2-252bf6db78fe', 'Lore Olympus (Vol.2)', NULL, '9783736319097', 'Ich wünschte ich könnte dir einen Platz in meinem Leben geben und dich in mein Herz lassen, das längst dir gehört. Aber das größte Geschenk, das ich dir machen kann, ist mich von dir fernzuhalten. Persephone, die Göttin des Frühlings, konnte es kaum erwarten, das Reich der Sterblichen hinter sich zu lassen und in Olympus ein neues Leben zu beginnen. Doch schneller, als ihr lieb ist, lernt sie die dunklen Seiten ihres neuen Zuhauses kennen und kämpft mehr denn je darum, ihren Platz in der glamourösen Welt der Götter zu finden. Hades will Persephone vor den Skandalen und Versuchungen in Olympus beschützen - hat aber selbst mit seinen immer stärker werdenden Gefühlen für die junge Göttin zu kämpfen. Um den Gerüchten um sie beide ein Ende zu bereiten, schwört er, sich ab sofort von Persephone fernzuhalten. Aber als diese ein Praktikum in seiner Firma Underworld Corp beginnt und Tag für Tag in seiner Nähe ist, weiß er, dass es Zeit wird, sich seinen Emotionen zu stellen ...', '28.10.2022', 'LYX', ARRAY['Deutsch']::text[], 368, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '4ce8268d-83fc-54cd-8506-2720ea131807', '2', '{}', 'sheet', :'owner') on conflict do nothing;
