insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e24ecd5d-1f40-514b-90d4-cb5ac4817f8b', 'Lore Olympus (Vol.3)', NULL, '9783736319721', 'Ich mag ein mächtiger König sein, doch das bedeutet nicht, dass ich immer bekomme, wonach mein Herz verlangt. In Olympus und der gesamten Unterwelt gibt es nur noch ein Thema: Hades und Persephone. Und dass die junge Göttin des Frühlings im Rahmen ihres Stipendiums ein Praktikum bei Underworld Corp antritt und dabei mehr Zeit denn je mit dem König der Unterwelt verbringt, macht die Sache nicht besser! Um nicht noch mehr Aufmerksamkeit zu erregen, schwören die beiden sich, ihre Gefühle füreinander zu ignorieren sowie Berufliches und Privatleben strikt zu trennen - doch die Anziehungskraft zwischen ihnen ist stärker als ihr selbst auferlegtes Verbot. Weil das Schicksal seine ganz eigenen Pläne mit ihnen hat ..', '28.04.2023', 'LYX', ARRAY['Deutsch']::text[], 384, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '4ce8268d-83fc-54cd-8506-2720ea131807', '3', '{}', 'sheet', :'owner') on conflict do nothing;
