insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('232eabd4-4df4-5c93-b779-64941545414d', 'Lore Olympus (Vol.4)', NULL, '9783736322882', 'Je stärker Hades und Persephone sich zueinander hingezogen fühlen, desto klarer wird ihnen, dass sie sich vor allem erst einmal um ihre eigenen Probleme kümmern müssen, bevor die Welt (und die Unterwelt!) von ihren wahren Gefühlen füreinander erfahren darf! Doch das ist leichter gesagt als getan: Die Gerüchteküche brodelt und plötzlich taucht auch noch Kriegsgott Ares in Olympus auf - und mit ihm ein dunkles Geheimnis aus Persephones Vergangenheit, das ihr Leben unter den Göttern schneller zerstören könnte, als sie es sich aufgebaut hat ...', '26.01.2024', 'LYX', ARRAY['Deutsch']::text[], 416, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '4ce8268d-83fc-54cd-8506-2720ea131807', '4', '{}', 'sheet', :'owner') on conflict do nothing;
