insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('da628433-8822-5945-b7ef-2b7d7f29168e', 'Lore Olympus (Vol.5)', NULL, '9783736322578', 'Zu ihrem Geburtstag könnte sich Persephone, die Göttin des Frühlings, nichts Schöneres wünschen, als ihren Gefühlen für Hades endlich nachgeben und ihre Liebe öffentlich machen zu können. Doch Hades'' Trennung vom Minthe schlägt große Wellen, und auch ihre eigene Vergangenheit droht Persephone endgültig einzuholen. Als Zeus von ihrem schrecklichen Geheimnis erfährt, flieht sie in die Unterwelt. Aber kann Hades dem König der Götter wirklich Einhalt gebieten, oder ist es für Persephone letztendlich an der Zeit, sich den Konsequenzen ihres Handelns zu stellen, auch wenn dies ihr Glück mit Hades für immer zerstören könnte?', '31.05.2024', 'LYX', ARRAY['Deutsch']::text[], 400, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '4ce8268d-83fc-54cd-8506-2720ea131807', '5', '{}', 'sheet', :'owner') on conflict do nothing;
