insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('83e3904d-9e68-5e34-ab9c-3b0bb710a4c5', 'd692cd56-cdef-5eb1-b756-2f0c46153aa7', :'owner', 1, '2026-01-07', '2026-01-07', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a20e940a-3bb9-512d-84ce-e2ebcc59bba0', 'Lore Olympus (Vol.8)', NULL, '9780593871980', 'Revelations rock Olympus as Persephone’s trial ends, threatening to throw the gods into a new war. Though Persephone and Hades become closer than ever after she opens up to him about all she has endured, their peace is shattered when another truth is revealed: Apollo is Zeus’s son. The announcement shocks the pantheon, and the king of the gods realizes that the would-be usurper wants Persephone’s power to take the throne. Zeus banishes Persephone to the Mortal Realm and, out of fear, cuts it off entirely from the rest of the gods. This decree succeeds in undercutting Apollo’s plan, but also inadvertently begins a decade-long divine cold war when Hades strikes back by shuttering the Underworld. With the gods scattered and weakened, Kronos uses the ensuing bedlam to finally escape his imprisonment and begin staging his own coup. Persephone has only one choice when she discovers all the realms on the verge of collapse: Descend into the Underworld to try to defeat the power-hungry Titan, claim her rightful place as queen, and reunite with her one true love. This edition of Smythe’s original Eisner Award–winning webcomic Lore Olympus features a brand-new, exclusive short story from creator Rachel Smythe and brings the Greek pantheon into the modern age in a sharply perceptive and romantic graphic novel.', '06.05.2025', 'Inklore', ARRAY['Englisch']::text[], 416, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '4ce8268d-83fc-54cd-8506-2720ea131807', '8', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c4ea6085-adca-56db-a868-5c9468b89fe8', :'owner', 'a20e940a-3bb9-512d-84ce-e2ebcc59bba0', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Hardcover']::text[], 'Normal', '{}', 2599, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Zeus geht mir wirklich maximal auf den Sack. So ein egoistischer Depp. Endlich haben sie sich gesagt, dass sie sich ieben. Ich bin echt begeistert von dem Ende dieses Bandes. Ich fands nur schade, dass Persephone und Hades in diesem Band so wenig Zeit miteinander verbringen konnten.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('2d71769b-5b1b-5bce-bf9f-50ae6bbef52e', 'c4ea6085-adca-56db-a868-5c9468b89fe8', :'owner', 1, '2026-03-15', '2026-03-16', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bdf0cb86-7c50-5144-8f7f-0fbe88fffbcf', 'Lore Olympus (Vol.9)', NULL, '9781911720928', 'Persephone and Hades are finally reunited when the banished goddess of spring returns to the Underworld to claim her rightful place as queen. Now that Hades and Persephone have defeated and imprisoned the power-hungry Kronos once more, nothing can keep them apart, and years of being separated have only made their desire for each other grow. But the other Olympians can''t help but meddle, pushing the pair to make things official with a coronation - and a wedding. Ignoring the others who try to define their relationship, Hades and Persephone choose to take things at their own pace and focus on rebuilding the Underworld. They begin by investigating how Kronos was first able to escape, and they learn the horrifying truth that he has captured a powerful young god whose abilities help Kronos project his thoughts outside of Tartarus - thoughts he uses to plague Hera''s every waking moment. Though Kronos'' physical form is locked away, Olympus will never be free until they can rescue the child from the furious Titan''s grasp. To save the realms, Persephone must figure out her fertility goddess powers and embrace her role as Queen of the Underworld - even as it takes her further from her mother''s expectations and her former place in the Mortal Realm.', '07.10.2025', 'Vermilion', ARRAY['Englisch']::text[], 432, NULL, 'Graphic Novel'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Olympus', ARRAY['3P Objective']::text[], ARRAY['Persephone','Hades']::text[], ARRAY['Greek/Rome Mythology']::text[], ARRAY['Sexuelle Gewalt','Psychische Erkrankung/Belastung']::text[], '4ce8268d-83fc-54cd-8506-2720ea131807', '9', '{}', 'sheet', :'owner') on conflict do nothing;
