insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f743991f-801c-5838-a0ae-6de920066771', '6e393803-fee4-54e8-9647-cd152b92fb83', :'owner', 1, '2026-10-09', '2026-10-10', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eb54f8da-53b0-5bb8-95bb-560ba0a9600f', 'Annie Knows Everything', NULL, '9783751791847', 'Annie glaubt immer zu wissen, was für alle das Beste ist. Doch als ihr eigenes Leben aus den Fugen gerät, merkt sie, dass sie nicht einmal versteht, was in ihrem eigenen Herzen vor sich geht. Annie weiß alles - oder tut zumindest so. Nachdem sie erfährt, dass sie ihren Job bei einem hippen Tech-Start-up in New York verliert, beschafft ihr ihre beste Freundin eine neue Stelle - in einem Bereich, von dem Annie keine Ahnung hat: Datenstrategie. Was macht es schon, dass sie noch nie programmiert hat - wie schwer kann das schon sein? Abteilungsleiter Connor ist skeptisch, doch Annie weiß, dass seinem fröhlichen Nerd-Team eine sozial kompetente Person fehlt. Und sie ist die ideale Besetzung, davon muss sie ihn nur überzeugen. Sie muss dabei nur ausblenden, dass er eine äußerst ungünstige Mischung aus nervtötend und attraktiv ist. Und als wäre das nicht genug, steht auch noch die zweite Verlobungsfeier ihrer Schwester mit dem schlimmsten Mann der Welt an - eine Feier, die Annie beim ersten Mal gründlich ruiniert hat. Also muss Annie einen Job meistern, für den sie eigentlich nicht qualifiziert ist, die aufkeimende Spannung zwischen ihr und ihrem neuen Chef im Griff behalten und gleichzeitig ihre Schwester vor der schlechtesten Entscheidung ihres Lebens bewahren. Doch Annie macht sich keine Sorgen. Wenn sie eines kann, dann ist es, sich in das Leben anderer einzumischen. Aber was, wenn sie diesmal gerade damit alles aufs Spiel setzt, was ihr am meisten bedeutet?', '27.04.2026', 'Lübbe', ARRAY['Deutsch']::text[], 384, 35, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, 'New York', '{}', ARRAY['Annie']::text[], ARRAY['Work Adversaries','Grumpy x Sunshine','Forced Proximity']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
