insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25a583ad-e9a0-5c8c-8b1d-0116f6f1f5d4', 'Carry on', NULL, '9781529013009', 'Simon Snow is eager to enjoy his final year at the Watford School of Magicks, but fate has other plans. Amidst a breakup with his girlfriend, a pesky best friend, and a mentor intent on hiding him away, Simon finds himself preoccupied with the disappearance of his longtime nemesis and roommate. As if that weren''t enough, ghosts, vampires, and sinister forces are determined to thwart Simon at every turn. Being the world''s most powerful magician offers little respite when the weight of the world rests upon your shoulders. Carry On seamlessly weaves together elements of fantasy, romance, and mystery, creating an enchanting and inclusive story that will resonate with fans of the genre. Rainbow Rowell''s signature wit and heart are on full display, ensuring a perfect balance of humour, heart, and heroism.', '11.07.2019', 'MacMillan', ARRAY['Englisch']::text[], 517, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, NULL, 'Watford School of Magicks', '{}', ARRAY['Simon Snow']::text[], '{}', '{}', 'a685b13e-3a57-554b-b403-d25b7334fec9', '1', '{}', 'sheet', :'owner') on conflict do nothing;
