insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('61e52311-148e-5f02-b230-62ebba90141d', 'Tage der Finsternis', NULL, '9783401062044', 'Himmerod, ein uraltes Kloster im einsamen Salmtal. Ein Ort der Stille und des Friedens. Doch hinter den dicken Mauern geht Entsetzliches vor sich. Warum hat sich Bruder Paulinus von der Orgelempore in den sicheren Tod gestürzt? Und was steckt wirklich hinter der Schändung des Klosteraltars? Der junge Bruder Thomasius macht sich an die Ermittlungen: Je tiefer er gräbt, desto rätselhafter wird das Geheimnis.', '15.07.2009', 'Arena', ARRAY['Deutsch']::text[], 113, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, NULL, 'Himmerod', '{}', ARRAY['Bruder Thomasius']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
