insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('94ac606d-9bc6-5c29-83f6-bf145fb21140', 'The Lost Siren', NULL, NULL, 'A human female born into a breeding manor never has a choice…I am a slave, but at least I am alive. When the man with wings and scales gave me a second choice—I took it. The others of his kind pin me with hungry eyes, but I’ll do what I must to survive. I''ll preside over their Draken Games—and choose a winner every night to share my bed. The alternative is death. Traded from one prison to the next I have but one hope left—the Lost Siren. I must find her before the demon hordes come if these men—Drakens—have any chance of escaping their mountainous prison, and me along with them. Perfect for fans of Jennifer L. Armentrout, The Lost Siren is the exhilarating introduction to the Rise of the Drakens series.', '12.04.2022', NULL, ARRAY['Englisch']::text[], 221, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], NULL, NULL, NULL, '{}', '{}', ARRAY['Reverse Harem']::text[], '{}', '22fae59d-5d67-5b39-b480-c639bb4bbd63', '1', '{}', 'sheet', :'owner') on conflict do nothing;
