insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c32de99d-a2be-55b9-9cf4-1a0d7a5f73cf', 'Yellowface', NULL, '9783847901624', 'June Hayward und Athena Liu könnten beide aufstrebende Stars der Literaturszene sein. Doch während die chinesisch-amerikanische Autorin Athena für ihre Romane gefeiert wird, fristet June ein Dasein im Abseits. Niemand interessiert sich für Geschichten "ganz normaler" weißer Mädchen, so sieht es June zumindest. Als June Zeugin wird, wie Athena bei einem Unfall stirbt, stiehlt sie im Affekt Athenas neuestes, gerade vollendetes Manuskript, einen Roman über die Heldentaten chinesischer Arbeiter während des Ersten Weltkriegs. June überarbeitet das Werk und veröffentlicht es unter ihrem neuen Künstlernamen Juniper Song. Denn verdient es dieses Stück Geschichte nicht, erzählt zu werden, und zwar egal von wem? Aber nun muss June ihr Geheimnis hüten. Und herausfinden, wie weit sie dafür gehen will.', '29.02.2024', 'eichborn', ARRAY['Deutsch']::text[], 381, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['June Hayward']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
