insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ab29b9c4-986b-5713-8f32-a093498fb5b4', 'Himmelwärts', NULL, '9783453266889', 'Ein Engel, dem sein zu großes Interesse an menschlichen Gefühlen zum Verhängnis wird. Eine junge Vampirin, die sich eigentlich nur Ruhe und frisches Blut wünscht. Und ein Prophet, der stirbt, bevor er seine Aufgabe erfüllen konnte, und fortan das Gefüge zwischen oben und unten gehörig durcheinanderbringt ... Rebecca Hohlbein gibt den Vampir-Megaerfolgen der letzten Jahre in ihrer himmlisch-höllischen Geschichte ein ganz neues Gesicht.', '13.09.2010', 'Heyne', ARRAY['Deutsch']::text[], 623, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Tabea','Alvaro']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
