insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f1376807-89af-5b98-95ad-c1b5507ab9df', 'Divine Rivals', NULL, '9780008600662', 'Eighteen-year-old Iris dreams that one day her writing will make a difference. A war between gods is raging, and she’s landed a prestigious job at the Oath Gazette. But at home, she’s barely holding it together. Her brother is missing on the frontline. Her mother is lost in a haze of addiction. And each night Iris pours her heart out in letters to her brother. Letters that will never be answered. Or so she thinks…', '13.04.2023', 'Magpie', ARRAY['Englisch']::text[], 357, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Iris Winnow','Roman Kitt']::text[], '{}', '{}', 'fec37fc1-07c7-5757-9136-deccfd420580', '1', '{}', 'sheet', :'owner') on conflict do nothing;
