insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('52a69eb3-4750-58ce-b4c9-c1457408ce61', 'Dreams Lie Beneath', NULL, '9783736324640', 'Das Reich Azenor steht seit Jahrzehnten unter einem schrecklichen Fluch. In jeder Neumondnacht werden die schlimmsten Albträume der Einwohner lebendig. Als angehende Hüterin ist es die Aufgabe von Clementine und ihrem Vater, ihre Stadt davor zu beschützen. Doch als eines Tages zwei junge Magier auftauchen und ihnen dieses Amt streitig machen, ändert sich alles. In einem Wettkampf verliert Clementine nicht nur ihre Position, sondern auch ihr Zuhause. Sie schwört Rache, vor allem an dem geheimnisvollen Phelan, der sie bezwungen hat und sie trotz allem fasziniert. Aber um den Neumondfluch ein für allemal zu brechen, muss sie mit ihrem Rivalen zusammenarbeiten ...', '30.05.2025', 'LYX', ARRAY['Deutsch']::text[], 502, 44, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Azenor', '{}', ARRAY['Clementine','Phelan']::text[], ARRAY['Enemies to Lovers','The Chosen One']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
