insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('ddcc56e5-35b1-5d5b-939f-18d1f43232ce', '5a9736bb-cb12-581d-837d-97cb0526d690', :'owner', 1, '2023-07-06', '2023-07-10', NULL, NULL, 5, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3481d46b-632e-50fe-89e0-d2be771bb717', 'Iron Flame', NULL, '9780349437026', 'SECRETS. SACRIFICE. SURVIVAL. Against all odds, Violet Sorrengail made it through her first year at Basgiath War College, but now, the real training begins. The stakes are higher than ever, and a determination to survive won''t be enough this time. When a powerful new enemy threatens everything she cares about, including the man she loves, Violet must do whatever it takes to keep their secrets safe. One wrong move could have horrifying consequences - and as the web of lies spun by those in charge starts to unravel, nothing, not even dragon fire, may be enough to save them in the end. THE DEADLY SECOND YEAR AT BASGIATH AWAITS.', '07.11.2023', 'Little, Brown Book Group', ARRAY['Englisch']::text[], 622, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Basgiath War College', '{}', ARRAY['Violet Sorrengail','Xaden Riorson']::text[], ARRAY['Academy','Magical Creatures']::text[], '{}', 'a4bf6331-36df-5600-952f-9c0ec938421d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
