insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('840f919c-5ef6-59b3-9062-452bf97e7407', 'Onyx Storm', NULL, '9780349437064', 'After nearly eighteen months at Basgiath War College, Violet Sorrengail knows there''s no more time for lessons. No more time for uncertainty. Because the battle has truly begun, and with enemies closing in from outside their walls and within their ranks, it''s impossible to know who to trust. Now Violet must journey beyond the failing Aretian wards to seek allies from unfamiliar lands to stand with Navarre. The trip will test every bit of her wit, luck, and strength, but she will do anything to save what she loves - her dragons, her family, her home, and him. Even if it means keeping a secret so big, it could destroy everything. They need an army. They need power. They need magic. And they need the one thing only Violet can find - the truth. But a storm is coming... and not everyone can survive its wrath.', '21.01.2025', 'Little, Brown Book Group', ARRAY['Englisch']::text[], 527, 66, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Basgiath War College', ARRAY['Single POV','1P']::text[], ARRAY['Violet Sorrengail','Xaden Riorson']::text[], ARRAY['Academy','Dark Secrets','Epic Quest','Magical Creatures','The Monster Within']::text[], '{}', 'a4bf6331-36df-5600-952f-9c0ec938421d', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c1cf607d-c824-5a52-b0c7-8dafe5477448', :'owner', '840f919c-5ef6-59b3-9062-452bf97e7407', 'gelesen'::reading_status, true, true, ARRAY['Print','Digital','Audiobook']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', ARRAY['Map']::text[], 2299, true, false, ARRAY['Audible']::text[], ARRAY['Rebecca Soler']::text[], 1432, '👍🏻', false, 'solo'::company_kind, 'middle'::verdict_kind, 3.0, 'untertroffen'::expectation_kind, 4, 'slow'::burn_kind, 'Irgendwie langweilt und nervt mich das Buch ein wenig. Es braucht zu lange, bis endlich etwas passiert. Wie der zweite Band... die ganze Zeit passiert nichts relevantes bis zum Ende. Sehr nervig. Nichts führt zu etwas. Man wartet 90% Des Buches darauf, dass endlich mal was sinnvolles passiert.') on conflict do nothing;
