insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('227ffd8d-5be5-5d72-a4a2-1b13ee0eea4d', 'Treshing Day', NULL, '9780349450735', 'Welcome to Threshing Day, the brutal, high-stakes trial where would-be riders at Basgiath War College fight to earn the bond of a dragon or die trying. Amid ruthless competition and dragon fire, these thirteen cadets must survive a battlefield where desperate rivals will do anything to gain an advantage and dragons decide one''s ultimate fate-and where a single choice can forge a rider...or destroy them. Xaden Riorson, the powerful leader. Rhiannon Matthias, the clever friend. Dain Aetos, the dutiful rule-follower. Liam Mairi, the kindhearted protector. Ridoc Gamlyn, the jokester. Sawyer Henrick, the underdog. Bodhi Durran, the second-in-command. Mira Sorrengail, the fearless rider. Brennan Sorrengail second-in-command. Mira Sorrengail, the fearless rider. Brennan Sorrengail, the brilliant tactician. Aaric Graycastle, the restless royal. Sloane Mairi, the determined sister.', '29.09.2026', 'Little, Brown Book Group', ARRAY['Englisch']::text[], 224, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Basgiath War College', ARRAY['Multiple POV']::text[], ARRAY['Xaden Riorson','Rhiannon Matthias','Dain Aetos','Liam Mairi','Ridoc Gamlyn','Sawyer Henrick','Garrick Tavis','Imogen Cardulo','Bodhi Durran','Mira Sorrengail','Brennan Sorrengail','Aaric Graycastle','Sloane Mairi']::text[], ARRAY['Academy','Dark Secrets','Epic Quest','Magical Creatures','The Monster Within']::text[], '{}', 'a4bf6331-36df-5600-952f-9c0ec938421d', '4', ARRAY['Midquel']::text[], 'sheet', :'owner') on conflict do nothing;
