insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fa6864a0-47a0-54a9-866c-f21c47066f0b', 'Boyfriends (Vol.1)', NULL, '9783551631459', 'Jock, Goth, Nerd und Prep sind alle im dritten Unijahr. Aber ans Lernen ist nicht zu denken, da sie vor allem eins suchen: einen Partner - oder gleich mehrere. Gemeinsam wagen sie sich daran, das Abenteuer Viererbeziehung auf ihre eigene charmante Art zu meistern. Auf ihrem Weg durch die Höhen und Tiefen des Dating-Lebens verstehen sie nicht nur einander besser, sondern auch sich selbst.', '29.07.2025', 'Carlsen', ARRAY['Deutsch']::text[], 336, 15, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'University', ARRAY['3P Objective']::text[], ARRAY['Jock','Goth','Nerd','Prep']::text[], ARRAY['Universicy/College','Queer','Opposites Attract']::text[], '{}', '0157ced7-c325-52e9-a0cc-98ad99f13c39', '1', '{}', 'sheet', :'owner') on conflict do nothing;
