insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c0fd9786-6910-5d08-95bc-64708d8d8845', 'Boyfriends (Vol.2)', NULL, '9783551631466', 'Das letzte College-Jahr bricht an – und Jock, Goth, Nerd und Prep sind als Polykül offiziell zusammen! Zwischen Footballspielen, Fanfiction-Abenteuern und geliehenen Outfits wächst ihre Liebeweiter. Doch der Alltag stellt sie vor neue Herausforderungen: Wie koordiniert man vier Leben, stoppt Preps Cozy-Games-Sucht und erklärt Goth, was ein Credit ist? Zum Glück gibt es neue queere Freundschaften, ein weiteres Polykül auf dem Campus, reichlich Chaos – und vielleicht sogar den perfekten Viererkuss.', '30.09.2025', 'Carlsen', ARRAY['Deutsch']::text[], 320, 16, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'University', ARRAY['3P Objective']::text[], ARRAY['Jock','Goth','Nerd','Prep']::text[], ARRAY['Universicy/College','Queer','Opposites Attract']::text[], '{}', '0157ced7-c325-52e9-a0cc-98ad99f13c39', '2', '{}', 'sheet', :'owner') on conflict do nothing;
