insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('68b92427-f261-51f3-a56c-c1de5bd897b8', 'Hasenwaldgeschichten - Abenteuer auf der Brombeerinsel', NULL, '9783625205333', '"Kommt, Freunde, wir haben genug Brommbeeren gesammelt. Wir rudern zurück nach Hause", sagte Benji Eichhörnchen. Doch wo war das Boot? "Oje, Es treibt auf dem Fluss! Was sollen wir jetzt tun?", jammert Kitti, das Kätzchen. "Benji wird zum Boot schwimmen", grunzte voller Zuversicht Dicki, das Ferkel. "Ich kann aber nicht schwimmen", gestand Benji kleinlaut. Wi soltlen di drei Freunde jemals wieder nach Hause gelangen?', '02.01.2000', NULL, ARRAY['Deutsch']::text[], 24, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, 'Brombeerinsel', ARRAY['3P Objective']::text[], ARRAY['Benji','Dicki','Kitti']::text[], '{}', '{}', 'cf905726-b999-52cc-9f3e-f7f2c4b1a963', '1', '{}', 'sheet', :'owner') on conflict do nothing;
