insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9a7117ed-fc52-5a27-94d1-5d0a1bd93ff3', 'Wichtelwaldgeschichten - Das geheimnisvolle Flugzeug', NULL, '9783625205302', 'Niemand im Wichtelwald glaubte, dass Flori Frosch besonders klug sei. Alle lachten, wenn er behauptete, dass er sich ein Flugzeug bauen würde. "Er kann vielleicht ein Flugzeug bauen, aber fliegen wird er nicht", spottete Benji Eichhörnchen, "dazu hat er ein viel zu kleines Köpfchen." Wer hätte gedacht, dass Flori am Ende schafft, was niemand ihm glaubt, und er in einem knallroten Flugzeug über dem wichtelwald kreist?', '01.01.2000', 'Naumann  & Göbel', ARRAY['Deutsch']::text[], 24, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, 'Wichtelwald', ARRAY['3P Objective']::text[], ARRAY['Flori Frosch']::text[], '{}', '{}', '73ac1089-d492-5ff1-84f3-1db09f6169a6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
