insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cbf7da3d-6384-5d2f-aaca-cdb31665f969', 'Wichtelwaldgeschichten - Das Picknick am Flussufer', NULL, '9783625205272', 'In der Wurzel eines Baumes, der am Rande des Wichtelwaldes stand, hatte sich Meister Stichel eine gemütliche Wohnung eingerichtet. "Es ist ein schöner Tag", sagte er, als er eines Morgens aus der Tür trat. "Ich werde ein Picknick am Fluss machen." Er pakcte etwas Brot und Käse, einige Kekse und iene Orange ein - so als würde er ahnen, welche Abenteuer ihm an diesem Tag noch bevorstehen.', '01.01.2000', 'Naumann  & Göbel', ARRAY['Deutsch']::text[], 24, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, 'Wichtelwald', ARRAY['3P Objective']::text[], ARRAY['Meister Stichel']::text[], '{}', '{}', '73ac1089-d492-5ff1-84f3-1db09f6169a6', '2', '{}', 'sheet', :'owner') on conflict do nothing;
