insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('66ea0b80-f997-57a4-aa3c-79360d3c4aaf', 'Wichtelwaldgeschichten - Sturm überm Wichtelwald', NULL, '9783625205296', 'Im Wichtelwald lebte eine Waldmaus. Sie war sehr stolz auf ihr neues Kleid und ihren hübschen Hut. "Das werde ich tragen, wenn ich am Freitag zu meiner Freundin Gundi gehe. Hoffentlich wird es ein schöner, sonniger Tag", wünschte sie sich. Aber Freitag war kein sonniger Tag. Es regnete heftig und der Sturm ließ die Äste der Bäume hin und her schwanken. Trotzdem zog Mausi ihr neues Kleid an und setzte den neuen Hut auf. Sie sah sehr hübsch aus, als sie mit ihrem großen Regenschirm das Haus verließ...', '01.01.2000', 'Naumann  & Göbel', ARRAY['Deutsch']::text[], 24, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, 'Wichtelwald', ARRAY['3P Objective']::text[], ARRAY['Mausi']::text[], '{}', '{}', '73ac1089-d492-5ff1-84f3-1db09f6169a6', '3', '{}', 'sheet', :'owner') on conflict do nothing;
