insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ce4892d1-7da0-5b70-a83f-532b3f1648ec', 'Graineliers (Vol.1)', 'Gurainerie', '9783770499465', 'In a world where the seeds of plants are imbued with various powers both great and small, young Luca makes ends meet by illegally cultivating and selling rare specimens. But anyone caught engaging in this activity without the qualifications of a government-sanctioned Grainelier does so at the price of their freedom. So when the security forces come calling, Luca assumes they''re onto him...but it''s actually his shut-in father, Christophe, they''re after! Sent running to safety by Christophe, Luca escapes with a few rare and powerful seeds pressed into his hand...but will they do anything but make Luca''s path a thorny one?', '02.11.2018', 'Egmont Manga', ARRAY['Deutsch']::text[], 194, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], NULL, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Luca']::text[], ARRAY['Queer']::text[], '{}', 'c70a6f32-9093-501e-9b8a-5031fdcfd0f8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
