insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7f329d76-6371-5e90-93fe-709706f062c1', 'Das Buch aus Blut und Schatten', 'The Book of Blood and Shadow', NULL, 'Vor der Mordnacht hatte Nora zwei beste Freunde, Chris und Adriane. Und Max, den sie liebte. Nach jener Nacht hat sie Chris’ Blut an den Händen, Adriane steht unter Schock - und Max ist verschwunden. Was bleibt, ist ein okkultes Buch, das in jener Nacht seine grausige Botschaft offenbarte: Blut und Tod. Was bleibt, ist das mysteriöse Signum von Chris’ Mördern - einer jahrhundertealten Geheimgesellschaft. Gefangen zwischen Lüge und Schatten, behält Nora nur eine Gewissheit: Chris’ Blut war erst der Anfang - und sie selbst wird das Ende sein.', '01.06.2013', 'Arena', ARRAY['Deutsch']::text[], 552, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], NULL, NULL, NULL, '{}', ARRAY['Nora']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
