insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('957cdfa2-a6ca-50be-ad17-c28bc5ec6ebd', 'Wired', NULL, NULL, 'One year ago Lia Kahn died. A few days later she woke up She had a new body which was mechanical, unfeeling and inhuman. She had a new family ~ other ''mechs'' like her, who didn''t judge her for what she could no longer be. She had a new life, one that would last forever. At least it was supposed to But now everything Lia thought she knew has turned out to be a lie; everyone she thought she loved has been stolen away. And someone is trying to get rid of the mechs, once and for all. Lia will risk everything to save herself and the people she can''t live without. But not before facing one final truth: she can''t save everyone. In the tradition of Scott Westerfeld comes the third and final book in this riveting and edgy science fiction novel which raises questions of mortality, technology and morality.', '01.09.2011', 'Simon Pulse', ARRAY['Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lia Kahn']::text[], '{}', '{}', 'f10472be-f902-5d8c-bbc1-bdfd2601f59b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
