insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('37ec6dad-1d44-5188-8d81-45f220c3fde8', 'd2ae6048-dec2-576d-8025-347c7bfc7835', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('090b549d-6b55-5082-9764-42c4cfaf07ff', 'Skinned', NULL, '9783839001066', 'Lia Kahn ist reich, schön und beliebt – bis ein Unfall sie beinahe tötet. Im Krankenhaus wacht sie in einem perfekten, künstlichen Körper auf. Lia wird nie wieder Schmerz empfinden, sie wird nicht altern und nicht sterben. Doch der Preis dafür ist hoch: Ihre Freunde misstrauen ihr, ihr Freund betrügt sie und alles, was ihr wichtig war, wandelt sich in einen Albtraum. Hin- und hergerissen zwischen dem Leben, das sie einmal kannte, und einer neuen, aufregenden Existenz, lernt Lia bald die bitterste Lektion: Niemand kann ihr die Entscheidung abnehmen, die sie treffen muss, um ihre Liebsten zu schützen.', '01.01.2010', 'Simon Pulse', ARRAY['Englisch','Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lia Kahn']::text[], '{}', '{}', 'f10472be-f902-5d8c-bbc1-bdfd2601f59b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
