insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('28658e14-cdca-57f4-b1a2-6904ee9cf6cc', 'c3e732b5-2837-59ad-9456-9e4f5574d795', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('89452c8f-d3a8-5be9-9255-2feeffc83f4a', 'Crashed', NULL, '9783839001141', 'Sechs Monate sind vergangen, seit Lias Wirklichkeit auf den Kopf gestellt wurde. Sechs Monate voller Zweifel, Angst und Auflehnung gegen die Tatsache, dass ihr Körper tot ist und Lia Kahn nur in einer menschenähnlichen Maschine weiterexistieren wird. Jetzt ist Lia bereit, ihr neues Dasein zu akzeptieren: Sie ist ein Mech und sie gehört zu ihresgleichen. Es ist eine wilde, sorglose Existenz, die sie führen, ohne Regeln, ohne Angst. Denn es gibt nichts zu fürchten, wenn man nichts mehr zu verlieren hat. Doch dann wird Lia von ihrer Vergangenheit eingeholt. Sie muss eine Wahl treffen zwischen ihrem alten Leben und ihrer neuen Freiheit, zwischen den Menschen und den Mechs. Sie muss sich entscheiden zwischen dem Mädchen, das sie war, und dem Jungen, den sie einmal geliebt hat.', '01.09.2010', 'Simon Pulse', ARRAY['Englisch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Lia Kahn']::text[], '{}', '{}', 'f10472be-f902-5d8c-bbc1-bdfd2601f59b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
