insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('b0057e41-8950-550d-9a44-5cc43a470087', '64440fcc-ecab-5600-931e-4fedc5a87998', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('847c3804-80cd-5da1-b9a9-99ff3804e6cb', 'The Idea of You', NULL, '9783757700928', 'Solène Marchand, Ende dreißig, ist eine liebevolle Mutter, gute Kollegin und rücksichtsvolle Ex-Frau. Aber es ist lange her, dass sie einfach nur sie selbst war. Als es plötzlich jemanden gibt, der nur sie sieht, der nur sie will, fühlt sie sich sofort unwiderstehlich zu ihm hingezogen. So beginnt eine leidenschaftliche Affäre, die anders ist als alles, was sie bisher kannte. Und die geheim bleiben muss. Denn dieser jemand ist Hayes Campbell, der Frontmann von August Moon, der angesagtesten Boyband der Welt. Charmant, geistreich, sehr attraktiv ... und jung. Sein Gesicht ist überall in den Medien. Und es prangt nicht nur an Hauswänden, auf Bussen und U-Bahnstationen, sondern auch an der Wand des Zimmers von Solènes Teenagertochter. Darf Solène sich wirklich in den Mann verlieben, den die ganze Welt begehrt? Oder muss sie die schwerste Entscheidung ihres Lebens treffen?', '28.03.2024', 'Lübbe', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Los Angeles', '{}', ARRAY['Solène Marchand','Hayes Campbell']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
