insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d9ba15e-8e38-58ab-b9a8-0b3499367df5', 'I Can’t Write About This Kiss', 'Kono Kisu Wa Kiji Ni Dekinai', '9783551622389', 'Manato ist ein ambitionierter Papparazzo und immer auf der Suche nach einem gewinnbringenden Skandal, den er mit seiner Kamera einfrieren kann. Eines Tages fotografiert er den berühmten Schauspieler Ryu Honda in einer besonders pikanten Situation – und wird erwischt! Der selbstbewusste Ryu stellt den jungen Fotografen zur Rede…', '28.02.2023', 'Hayabusa', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Manato','Ryu Honda']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
