insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a8fe2e3b-7b68-5253-8adf-3dbb3cf2b3f4', 'Inu Yasha (Vol.1)', NULL, NULL, 'Als Kagome in den alten Brunnen fällt, landet sie im mittelalterlichen Japan. Zusammen mit dem Hundedämon Inu Yasha macht sie sich auf die Suche nach einem ganz besonderen Zauberjuwel. Der verleiht seinem Besitzer große Macht. Klar, dass auch allerlei böse Geister an der Suche interessiert sind...', '19.01.2002', 'Egmont Manga', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'Japan', ARRAY['3P Objective']::text[], ARRAY['Kagome','Inuyasha']::text[], '{}', '{}', '95c32a14-fd8e-522f-94c0-46d04e6bd04a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
