insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('33443dd7-9761-59a8-9dbd-89dd4dfb6d0d', 'Behind You', NULL, NULL, 'Despite being a rising star in the BAU unit, FBI Special Agent Hailey Rock still lives in the shadow of her older sister, who remained in their small Midwestern town to become a police sheriff, and who remains the favorite in their parents’ eyes. Hailey has not thought of her estranged family in ages, but when young women turn up dead in her hometown, the FBI dispatches Hailey to solve the case her sister cannot—and forces her to face demons, including that of her kidnapped sister, that Hailey wished she would never face again.', '25.01.2023', NULL, ARRAY['Englisch']::text[], 204, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Romantic Suspense']::text[], NULL, NULL, NULL, '{}', ARRAY['Hailey']::text[], '{}', '{}', '412e8188-5e08-5cdc-a283-06f4cd673638', '1', '{}', 'sheet', :'owner') on conflict do nothing;
