insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('8c4fc56b-b07b-548c-aa19-655bbf0aa9ff', 'Moriarty The Patriot (Vol.1)', 'Yuukoku no Moriarty', '9783551746467', 'Der junge James Moriarty ist Professor für Mathematik im London der 1870er-Jahre und mit den gesellschaftlichen Unterschieden dieser Zeit ganz und gar nicht zufrieden. Aus dieser Unzufriedenheit entsteht die Idee einer Bürgerwehr – eine Art private Armee zum Kampf gegen Diskriminierung, die allerdings nicht immer legale Mittel zum Erreichen ihrer Ziele einsetzt.', '02.10.2018', 'Carlsen', ARRAY['Deutsch']::text[], 210, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Mystery', ARRAY['Detektivroman']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Moriarty']::text[], '{}', '{}', 'cc083007-1984-53db-b6d5-00b3c3000f21', '1', '{}', 'sheet', :'owner') on conflict do nothing;
