insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1a1703b0-df9b-539a-ae8c-c8a6f32bf16d', 'Diabolic - Vom Zorn geküsst', 'The Diabolic', NULL, 'Eine Diabolic ist erbarmungslos, stark, kaltblütig und tötet für die, die sie beschützen muss. Eine andere Art zu leben kennen Diabolics nicht. Das ist ihr Platz im Universum. Als Nemesis, eine junge Diabolic, erfährt, dass ihre Schutzbefohlene als Geisel an den Imperialen Hof berufen wird, zögert sie keine Sekunde, sich an ihrer Stelle in die Hände der Feinde zu begeben. Getarnt als zarte Senatorentochter reist sie an den Hof - ein Ort der Intrigen, der Dekadenz und der Gefahr. Doch während Nemesis immer tiefer in tödliche Machtspiele verwickelt wird, regt sich in ihr etwas, das nicht sein darf: ein Funke von Menschlichkeit - und von Liebe …', '03.01.2017', 'Arena', ARRAY['Deutsch']::text[], 488, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Space Opera']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Nemesis']::text[], '{}', '{}', '401172b2-8493-5ce9-b9de-00396a9839cf', '1', '{}', 'sheet', :'owner') on conflict do nothing;
