insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('71ed936f-7e1f-5c2b-bc96-a0121b0e9a9f', 'Yay!There', NULL, NULL, 'Nicht nur, dass der 16-jährige Jay um seine Mutter trauert, nach einem Vorfall im Internat wird er ohne weitere Diskussion rausgeworfen und nun hat sein Vater ihn an der Backe. Ein Mann, den Jay kaum kennt, weil er beruflich für die Sicherheit anderer zuständig ist und sich andauernd auf Reisen befindet – aktuell mit der K-Pop-Gruppe Yay!There, die auf ihrer Welttournee jeden Schutz gebrauchen kann. Jay hat keine Ahnung von K-Pop und die sechs Jungs dieser Band sind ihm auch herzlich egal. Sein Plan ist es, bis Paris durchzuhalten, dann abzutauchen und ein ganz neues Leben zu beginnen, weit weg vom Mobbing und den aktuellen Entwicklungen in den USA. Dafür muss er nur die Füße stillhalten. Leider hat er diese Rechnung ohne Yi-jun gemacht. Der Superstar nervt ihn mit seiner penetranten Art, doch schon bald begreift Jay, dass weit aus mehr dahintersteckt.', '09.02.2025', 'Briefgestöber', ARRAY['Deutsch']::text[], 278, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jay','Yi-jun']::text[], ARRAY['Queer','Famous Person']::text[], '{}', '7ef86b3d-ef73-5587-ae4b-c83cf351add0', '1', '{}', 'sheet', :'owner') on conflict do nothing;
