insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('01a2c0b9-79eb-50ba-9ebc-adeca8346c55', 'Flame & Arrow - Drachenprinz', NULL, '9783473402069', 'Kailey ist neu am Trinity College in Dublin. Was keiner weiß: Sie hat ein Geheimnis. Denn sie ist eine Fae, eine Elfenkriegerin, die von ihrer Königin ausgesandt wurde, um das Vertrauen des Drachenprinzen Aiden zu gewinnen. Dadurch erhoffen sich die Fae einen Vorteil im drohenden Krieg zwischen Elfen und Drachen. Doch Kailey ahnt nicht, dass Aiden einen ganz ähnlichen Auftrag hat! Die beiden spielen ihr falsches Spiel mit Bravour – und entwickeln dabei wahre Gefühle füreinander …', '15.09.2021', 'Ravensburger', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Gegenwart'::time_period, 'Trinity College, Dublin', '{}', ARRAY['Kailey','Aiden']::text[], '{}', '{}', '2ece1e2d-c1f6-51a8-a2cf-5179cf55f33b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
