insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6709b5e-660a-544f-bd4e-f9053fcd84e3', 'The Ballad of Falling Dragons', NULL, '9780063449725', 'Raeve’s thirst for vengeance continues to burn, as does her love for Kaan Vaegor—a staunch beacon from a past she’s yet to face. With Rekk’s blood still fresh on her hands, she learns the world will face its most devastating moonfall yet, forcing her to pick a path: Chase death. Or life. Desperate to save his kingdom from ruin, Kaan’s crown has never felt so heavy. His many larks to scattered friends and family remain unanswered, and time is running out. As allies merge and enemies surge with bloodlusting agendas of their own, secrets brew hot enough to burn, but none so mighty as the truth nesting within the icy depths of Raeve’s long forgotten past. Something … Other. Something with the knowledge to change it all.', '19.05.2026', 'Harper Collins', ARRAY['Englisch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Raeve','Kaan']::text[], ARRAY['Soul Mates']::text[], '{}', '0836a636-f03c-5b6c-b4ac-6a1e20b7002d', '2', '{}', 'sheet', :'owner') on conflict do nothing;
