insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9da3166e-374c-571c-9f07-8208998cd11d', 'When The Moon Hatched', NULL, '9783641326449', 'As an assassin for the rebellion group Fíur du Ath, Raeve’s job is to complete orders and never get caught. When a rival bounty hunter turns her world upside down, blood spills, hearts break, and Raeve finds herself imprisoned by the Guild of Nobles—a group of powerful fae who turn her into a political statement. Crushed by the loss of his great love, Kaan Vaegor took the head of a king and donned his melted crown. Now on a tireless quest to quell the never-ebbing ache in his chest, he is lured by a clue into the capitol’s high-security prison where he stumbles upon the imprisoned Raeve … Echoes of the past race between them. There’s more to their story than meets the eye, but some truths are too poisonous to swallow.', '10.07.2024', 'Penguin Random House', ARRAY['Englisch']::text[], 600, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Raeve','Kaan']::text[], '{}', '{}', '0836a636-f03c-5b6c-b4ac-6a1e20b7002d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
