insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3d6a1d6e-85dc-592f-b28a-bc335e0b5a44', 'Zwischen jetzt und immer', 'The Truth about Forever', NULL, 'Macy weiß, was sie keinesfalls will: Chaos. Denn Chaos macht ihr Angst, macht sie hilflos. Also trägt sie nach außen eine perfekte Fassade zur Schau und sucht sich einen hyperintelligenten Freund, der auf alles eine Antwort zu haben scheint: Jason. Was er ihr nicht geben kann, ist Wärme. Trotzdem ist Macy, als Jason eine Beziehungspause vorschlägt, am Boden zerstört. Und obwohl sie es so gründlich aus ihrem Leben verbannt hat, scheint jetzt eine gute Portion Chaos ihre einzige Rettung. Die kann sie haben – indem sie einen Job bei Wish Catering annimmt. Denn die Menschen, denen sie dort begegnet, bringen ihr Leben ins Rollen. Allen voran Wes …', '01.06.2012', 'dtv', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Coming of Age']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Macy','Jason']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
