insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('10532dfe-54a7-5d1f-9ead-68f4d7f168f5', 'House of Earth and Blood', NULL, '9781408884416', 'Bryce Quinlan loves her life. Every night is a party, and Bryce is going to savour all the pleasures Lunathion - also known as Crescent City - has to offer. But when a brutal murder shakes the very foundations of the city, Bryce''s world comes crashing down. Two years later, Bryce still haunts the city''s most notorious nightclubs - but seeking only oblivion now. Then the murderer attacks again. And when an infamous Fallen angel, Hunt Athalar, is assigned to watch her every footstep, Bryce knows she can''t forget any longer. As Bryce and Hunt fight to unravel the mystery and their own dark pasts, the threads they tug ripple through the underbelly of the city, across warring continents and down to the deepest levels of Hel, where things that have been sleeping for millennia are beginning to stir ...', '03.03.2020', 'Bloomsbury', ARRAY['Englisch']::text[], 799, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Lunation', '{}', ARRAY['Bryce Quinlan']::text[], '{}', '{}', '93a6415f-08e0-5ea0-8ac0-3dfe05a20867', '1', '{}', 'sheet', :'owner') on conflict do nothing;
