insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9de9df2f-d608-51d3-9d26-5b768d8e14dc', 'Crown of Midnight', NULL, NULL, 'Celaena Sardothien won a brutal contest to become the King''s Champion. But she is far from loyal to the crown. Though she goes to great lengths to hide her secret, her deadly charade becomes more difficult when she realises she is not the only one seeking justice. Her search for answers ensnares those closest to her, and no one is safe from suspicion - not the Crown Prince Dorian; not Chaol, the Captain of the Guard; not even her best friend, Nehemia, a princess with a rebel heart. Then, one terrible night, the secrets they have all been keeping lead to an unspeakable tragedy. As Celaena''s world shatters, she will be forced to decide once and for all where her true loyalties lie ... and what she is willing to fight for.', '15.08.2013', 'Bloomsbury', ARRAY['Englisch']::text[], 418, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Eriliea', '{}', ARRAY['Aelin Galathynius']::text[], '{}', '{}', '8cdbb812-13c0-5dfa-be6b-8db403669ae6', '3', '{}', 'sheet', :'owner') on conflict do nothing;
