insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d2d448e-4bdb-532b-803c-d8c5cd693fee', 'A Court of Silver Flames', NULL, '9781681196282', 'Nesta Archeron has always been prickly - proud, swift to anger and slow to forgive. And since the war - since being made High Fae against her will - she''s struggled to forget the horrors she endured and find a place for herself within the strange and deadly Night Court. The person who ignites her temper more than any other is Cassian, the battle-scarred, winged warrior who is there at Nesta''s every turn. But her temper isn''t the only thing Cassian ignites. And when they are forced to train in battle together, sparks become flame. As the threat of war casts its shadow over them once again, Nesta and Cassian must fight monsters from within and without if they are to stand a chance of halting the enemies of their court. But the ultimate risk will be searching for acceptance - and healing - in each other''s arms.', '16.02.2021', 'Bloomsbury', ARRAY['Englisch']::text[], 768, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Prythian', ARRAY['Double POV','1P']::text[], ARRAY['Nesta Archeron','Cassian']::text[], '{}', '{}', '302b8324-da8c-51be-93b6-b1051fc28d1a', '5', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
