insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('866896c1-42ef-523b-885e-8fe07f3ecbdb', 'Queen of Shadows', NULL, NULL, 'Celaena Sardothien has embraced her identity as Aelin Galathynius, Queen of Terrasen. But before she can reclaim her throne, she must fight. She will fight for her cousin, a warrior prepared to die for her. She will fight for her friend, a young man trapped in an unspeakable prison. And she will fight for her people, enslaved to a brutal king and awaiting their lost queen''s triumphant return. Everyone Aelin loves has been taken from her. Everything she holds dear is in danger. But she has the heart of a queen - and that heart beats for vengeance.', '01.09.2015', 'Bloomsbury', ARRAY['Englisch']::text[], 784, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Eriliea', '{}', ARRAY['Aelin Galathynius']::text[], '{}', '{}', '8cdbb812-13c0-5dfa-be6b-8db403669ae6', '5', '{}', 'sheet', :'owner') on conflict do nothing;
