insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('229152cb-b179-58d0-915f-734d481e16a3', 'Empire of Storms', NULL, NULL, 'The long path to the throne has only just begun for Aelin Galathynius as war looms on the horizon. Loyalties have been broken and bought, friends have been lost and gained, and those who possess magic find themselves increasingly at odds with those who don''t. With her heart sworn to the warrior-prince by her side and her fealty pledged to the people she is determined to save, Aelin will delve into the depths of her power to protect those she loves. But as monsters emerge from the horrors of the past, dark forces stand poised to claim her world. The only chance for salvation lies in a desperate quest that may take more from Aelin than she has to give, a quest that forces her to choose what - and who -she''s willing to sacrifice for the sake of peace.', '06.09.2016', 'Bloomsbury', ARRAY['Englisch']::text[], 848, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Eriliea', '{}', ARRAY['Aelin Galathynius']::text[], '{}', '{}', '8cdbb812-13c0-5dfa-be6b-8db403669ae6', '6', '{}', 'sheet', :'owner') on conflict do nothing;
