insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7a14f03f-a248-5b74-a03c-3fd0cd8a66b4', 'A Court of Forgotten Melody', NULL, '9781037205682', 'What was broken will be reclaimed. Prythian might never be the same again. Traditional alliances are crumbling, and no amount of diplomacy seems sufficient to repair them. With the continued threat of Koschei the Deathless on the horizon, a united front is crucial - and farther out of reach than it has ever been before. Bonds will be tested, Power will shift. And old enemies will emerge from nightmares of the past. As the Night Court''s Inner Circle disperses far and wide, desperate for any advantage against Koschei and his mighty allies, peace hangs by a fragile thread. But Hope can be spun from the darkest shadows, and the Night Court has its own part to play in the looming crescendo.', '12.01.2027', 'Bloomsbury', ARRAY['Englisch']::text[], 928, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Prythian', '{}', '{}', '{}', '{}', '302b8324-da8c-51be-93b6-b1051fc28d1a', '7', '{}', 'sheet', :'owner') on conflict do nothing;
