insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ff94b74-13fd-5cf7-a378-3204b4bfa3b5', 'Kingdom of Ash', NULL, NULL, 'Aelin Galathynius has vowed to save her people - but at a tremendous cost. Locked in an iron coffin by the Queen of the Fae, Aelin must draw upon her fiery will as she endures months of torture. The knowledge that yielding to Maeve will doom those she loves keeps her from breaking, but her resolve unravels with each passing day. With Aelin captured, her friends and allies have scattered. Some bonds will grow even deeper, while others will be severed forever. But as destinies weave together at last, all must stand together if Erilea is to have any hope of salvation.', '23.10.2018', 'Bloomsbury', ARRAY['Englisch']::text[], 992, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['High Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Eriliea', '{}', ARRAY['Aelin Galathynius']::text[], '{}', '{}', '8cdbb812-13c0-5dfa-be6b-8db403669ae6', '8', '{}', 'sheet', :'owner') on conflict do nothing;
