insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('eaf90114-7e54-5f05-84b9-65a911059a12', 'House of Flame and Shadow', NULL, '9781408884447', 'Bryce Quinlan is stranded in a strange new world. She''s going to need all her wits about her to get home again and return to everything she loves. But that''s no easy feat when she has no idea who to trust. Meanwhile, Hunt Athalar is back in the Asteri''s dungeons. Stripped of his freedom and the happiness he''d fought so hard for, he''s without a clue as to Bryce''s fate. Hunt is desperate to help his mate, but until he can escape the Asteri''s chains, his hands are quite literally tied.', '30.01.2024', 'Bloomsbury', ARRAY['Englisch']::text[], 848, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Lunation', '{}', ARRAY['Bryce Quinlan']::text[], '{}', '{}', '93a6415f-08e0-5ea0-8ac0-3dfe05a20867', '3', '{}', 'sheet', :'owner') on conflict do nothing;
