insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('af9d37e3-fb08-5667-b3bc-aa955486147c', 'Infinity Falling - Mess Me Up', NULL, '9783736319738', 'Nur wenn sie in fremde Rollen schlüpft, fühlt sich Schauspielerin Aven Amenta wie sie selbst. Doch seit eine Stalkerin in ihre Privatsphäre vorgedrungen ist, würde sich die Zwanzigjährige am liebsten verstecken. Der Umzug nach Vancouver für die Dreharbeiten des Kinoblockbusters INFINITY FALLING kommt Aven daher gerade recht. Womit sie nicht gerechnet hat: Die männliche Hauptrolle wird kurzfristig mit Hayes Chamberlain besetzt. Statt Schauspielerfahrung bringt der Ex-Boyband-Star nur einen Haufen Fans und Medienrummel mit, den Aven eigentlich meiden wollte. Doch mit jedem Tag fällt es ihr schwerer, sich von ihm fernzuhalten. Bis Hayes begreift, dass er nicht mit Aven zusammen sein kann, ohne sie in Gefahr zu bringen.', '22.08.2023', 'LYX', ARRAY['Deutsch']::text[], 526, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Set von Infinity Falling, Vancouver', '{}', ARRAY['Aven Amenta','Hayes Chamberlain']::text[], ARRAY['Famous Person']::text[], '{}', 'd866c006-66bc-5fa2-8315-03c979a84b51', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('410a48d7-7765-500a-b35f-05289635d152', :'owner', 'af9d37e3-fb08-5667-b3bc-aa955486147c', 'abgebrochen'::reading_status, true, false, ARRAY['Print','Audiobook']::text[], ARRAY['Paperback']::text[], 'Normal', '{}', 1400, true, true, ARRAY['BookBeat']::text[], ARRAY['Julian Tennstedt','Alexander Schwarz','Janin Stenzel']::text[], 1003, NULL, false, 'solo'::company_kind, 'hate'::verdict_kind, 1.0, 'untertroffen'::expectation_kind, 2, 'slow'::burn_kind, 'Hat mich leider so wenig gecatched, dass ich es abbrechen musste. Eine Story die man schon 100x gelesen hat. Nix besonderes.') on conflict do nothing;
