insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('72676714-83a1-547b-b5a2-f456b43c2583', 'Infinity Falling - Change My Mind', NULL, '9783736319745', 'Nicht nur am Set des Blockbusters Infinity Falling fliegen zwischen Holly Triano und Ruben Belton die Fetzen. Auch bei allen anderen Anlässen, zu denen die Manager ihre Schützlinge Aven Amenta und Hayes Chamberlain begleiten, kriegen sie sich in die Haare. Schließlich sind sie erbitterte Rivalen in einer Welt, in der man nichts geschenkt bekommt. Davon kann Holly als junge Inhaberin einer Agentur in einer männerdominierten Branche ein Lied singen - anders als Ruben, Sohn eines einflussreichen Medienunternehmers, dem allein sein Nachname alle Türen in der Branche geöffnet hat. Doch zwischen Dreharbeiten, Events und Networking merken die beiden bald, dass sie gar nicht so verschieden sind wie gedacht. Aber als Konkurrenten ist eine Beziehung zwischen ihnen undenkbar - oder?', '20.02.2024', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Set von Infinity Falling, Vancouver', '{}', ARRAY['Holly Triano','Ruben Belton']::text[], '{}', '{}', 'd866c006-66bc-5fa2-8315-03c979a84b51', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
