insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6590ab77-8900-57ab-b283-599ae96115d5', 'King of Battle and Blood', NULL, '9783736319769', 'Um das Königreich ihres Vaters zu retten, soll Prinzessin Isolde von Lara den mächtigen Vampirkönig Adrian Aleksandr Vasiliev heiraten - und töten. Doch in ihrer neuen Heimat angekommen merkt sie schnell, dass nichts, was sie über Adrian und sein Volk zu wissen glaubt, wahr ist. So sehr sie sich auch dagegen wehrt, die Anziehungskraft zu Adrian ist unabwendbar, die Gefühle, die er in ihr auslöst, hat sie noch nie für jemanden empfunden. Aber sie darf sich auf keinen Fall in ihn verlieben und so ihre Mission aus den Augen verlieren: Sie muss ihn töten und sein gesamtes Reich in die Knie zwingen ...', '23.05.2023', 'LYX', ARRAY['Deutsch']::text[], 427, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Isolde von Lara','Adrian Aleksandr Vasiliev']::text[], '{}', '{}', '69534318-cd18-5c21-9db2-4e10135846b3', '1', '{}', 'sheet', :'owner') on conflict do nothing;
