insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dc644ee1-2a1a-5597-af71-5f556baafa17', 'A Game of Fate', NULL, '9783736319653', 'Hades, der König der Unterwelt, regiert sein Reich mit eiserner Faust. Er ist es gewohnt, die vollkommene Kontrolle zu haben. Umso wütender ist er, als er erfährt, dass die Schicksalsgöttinnen seine zukünftige Braut und somit Königin der Unterwelt auserkoren haben: Persephone, die Göttin des Frühlings. Ein einziger Blick in ihre unvergleichlich grünen Augen jedoch genügt und Hades kann die intensiven Gefühle, die sie in ihm auslöst, nicht mehr leugnen. Doch die Tatsache, dass eine missglückte Wette nicht gerade den besten ersten Eindruck bei Persephone hinterlassen hat, stellt Hades vor die wohl größte Herausforderung seines bisherigen unsterblichen Lebens: Persephone davon zu überzeugen, dass er nicht der eiskalte Geschäftsmann ist, für den sie ihn hält, und sie für sich zu gewinnen ...', '05.08.2023', 'LYX', ARRAY['Deutsch']::text[], 438, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', ARRAY['Single POV','1P']::text[], ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '12eccea1-9a3e-5f36-92c6-4c2ddae21d68', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
