insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('1e15c2c7-6eb7-5d56-9274-f73b4b710cb2', 'db9ed054-6f85-5461-a0a0-128744bc98fc', :'owner', 1, '2024-03-05', '2024-03-21', NULL, NULL, 17, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0c501e8c-ea99-5064-b5dc-8760548ff67b', 'A Touch of Darkness', NULL, '9783736317758', 'Persephone ist die Göttin des Frühlings, doch ihre Magie hat sich bis heute nicht gezeigt. Sie wählt daher den Weg einer Sterblichen, zieht für ihr Studium nach New Athens und hat endlich das Gefühl, in ihrem neuen Leben angekommen zu sein. Aber auf einer Party im Nevernight, dem angesagtesten Club der Stadt, begegnet sie dem geheimnisvollen Hades und verliert eine Wette gegen ihn. Ohne es zu wissen, hat sie einen schier unerfüllbaren Vertrag mit dem Gott der Unterwelt geschlossen: Sie muss Leben in seinem Reich erschaffen oder sie verliert ihre Freiheit für immer! Dabei steht sogar noch weit mehr auf dem Spiel, denn Hades hat längst auch von ihrem Herz Besitz ergriffen ...', '27.05.2022', 'LYX', ARRAY['Deutsch']::text[], 436, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', ARRAY['Single POV','1P']::text[], ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '3165e151-b62e-52a5-a283-2a48c0d1ce35', '1', '{}', 'sheet', :'owner') on conflict do nothing;
