insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('628387d5-8b67-5aa0-9d48-9ef3932a213f', 'Queen of Myth and Monsters', NULL, '9783736320185', 'Seit Prinzessin Isolde von Lara Vampirkönig Adrian Aleksandr Vasiliev heiraten musste und ihre Heimat verlassen hat, ist in ihrem Leben nichts mehr, wie es einmal war. Menschen, die sie einst geliebt hatte, sind nun ihre Feinde, und ausgerechnet mit dem Mann, den sie geschworen hatte, zu hassen und zu töten, verbinden sie tiefe Gefühle, die sie noch nie zuvor für jemanden empfunden hat. Doch Isoldes Liebe zu Adrian hat einen hohen Preis: Tödliche Bedrohungen folgen ihr auf jedem Schritt, und in einer fremden Welt voller Rache und Intrigen ist der Blutkönig plötzlich der Einzige, dem sie noch vertrauen kann ...', '21.11.2023', 'LYX', ARRAY['Deutsch']::text[], 399, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Isolde von Lara','Adrian Aleksandr Vasiliev']::text[], '{}', '{}', '69534318-cd18-5c21-9db2-4e10135846b3', '2', '{}', 'sheet', :'owner') on conflict do nothing;
