insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57a946d1-0a84-5d2a-bd85-cf1d295d45ce', 'A Game of Retribution', NULL, '9783736319684', 'Als Hera, die Göttin der Frauen, offenbart, dass sie plant Zeus zu stürzen, pocht sie auf Hades’ Unterstützung - doch der Gott der Unterwelt bricht keine Regeln. Nur hat Hades nicht damit gerechnet, dass Hera sich rächt: Sie zwingt ihn eine Reihe von Aufgaben zu bewältigen, die mit jedem Mal schwerer und unglaublicher werden und Hades gesamte Aufmerksamkeit verlangen. Sogar seine geliebte Persephone verliert er aus den Augen - und erkennt erst viel zu spät, dass die angehende Königin der Unterwelt mit ihren eigenen Tragödien zu kämpfen hat ...', '29.02.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', ARRAY['Single POV','1P']::text[], ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '12eccea1-9a3e-5f36-92c6-4c2ddae21d68', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
