insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a4e08ca0-4ac9-5244-acb8-11a533557692', 'A Touch of Ruin', NULL, '9783736317765', 'Als Persephones Beziehung mit Hades an die Öffentlichkeit gelangt, ist nichts mehr, wie es war. Eigentlich hat die junge Studentin schon genug damit zu tun, ihre Gefühle für den mächtigen König der Unterwelt zu ergründen. Doch jetzt droht auch ihre Identität als Göttin des Frühlings aufzufliegen, was ihrem Leben unter den Sterblichen für immer ein Ende bereiten würde. Und weil Hades mit seinen ganz eigenen Dämonen zu kämpfen hat, ist plötzlich nicht einmal mehr sicher, ob die Unterwelt noch länger Persephones Zuflucht sein kann ...', '30.09.2022', 'LYX', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', '{}', ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '3165e151-b62e-52a5-a283-2a48c0d1ce35', '2', '{}', 'sheet', :'owner') on conflict do nothing;
