insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cf12c01e-fb74-540b-baa0-ed9a8375515a', 'A Touch of Malice', NULL, '9783736318076', 'Seit ihrer Verlobung mit Hades könnte Persephone eigentlich nicht glücklicher sein. Doch ihre Mutter setzt weiterhin alles daran, ihr gemeinsames Glück zu zerstören. Sie lässt einen Schneesturm über New Athens hereinbrechen und will die Oberwelt so lange in Kälte und Eis versinken lassen, bis Persephone die Verlobung löst. Doch das ruft die Götter auf den Plan, und Persephones Schicksal liegt plötzlich in den Händen derer, von denen sie sich eigentlich abgewandt hatte. Werden die Götter für sie in den Krieg gegen Demeter ziehen? Oder werden sie ihre gefährliche Allianz letztendlich doch gegen den ungeliebten König der Unterwelt richten?', '27.01.2023', 'LYX', ARRAY['Deutsch']::text[], 560, 38, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', ARRAY['Single POV','3P Limited']::text[], ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '3165e151-b62e-52a5-a283-2a48c0d1ce35', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ef87485a-f900-50d5-9a6a-4c537884c3ac', :'owner', 'cf12c01e-fb74-540b-baa0-ed9a8375515a', 'abgebrochen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Paperback']::text[], 'Normal', '{}', 1600, true, true, ARRAY['Audible']::text[], ARRAY['Meg Sylvan']::text[], 846, NULL, false, 'solo'::company_kind, 'hate'::verdict_kind, 1.0, 'untertroffen'::expectation_kind, 4, 'fast'::burn_kind, 'Genervt! Vor allem von den ganzen unnötigen Sexszenen, die alle gleich geschrieben sind. Ich wollte der Reihe noch eine Chance geben, aber das Buch hat mich maßlos enttäucht. Ständig unnötige Sexszenen und Charaktere die einfach nur toxisch sind und nicht wissen was sie wollen.') on conflict do nothing;
