insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fdcb7e45-eb86-5b95-9ff7-0820fc055917', 'A Game of Gods', NULL, '9783736319622', 'Hades, der König der Unterwelt, will Persephone endlich offiziell zu seiner Braut machen. Doch ihre Mutter Demeter stellt sich ihnen in den Weg und straft New Greece mit zerstörerischen Schneestürmen, solange sie ihre Hochzeitspläne nicht aufgeben. Und nicht nur sie gefährdet das zukünftige Bündnis, denn auch der Halbgott Theseus verfolgt mithilfe der Triade, einer Gruppe, die unter dem Vorwand der Rebellion für Chaos sorgt, seine ganz eigene Agenda. Kann Hades das undurchschaubare Spiel der Götter gewinnen? Oder wird er sein Reich und Persephone für immer verlieren?', '31.05.2024', 'LYX', ARRAY['Deutsch']::text[], 608, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', '{}', ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '12eccea1-9a3e-5f36-92c6-4c2ddae21d68', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('474b1fbc-5d6d-5b23-82e9-fac7cee8d53f', :'owner', 'fdcb7e45-eb86-5b95-9ff7-0820fc055917', 'ungelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Paperback']::text[], 'Normal', '{}', 1600, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0edc7698-eab1-5066-bd71-318273d82471', 'A Touch of Chaos', NULL, '9783736322493', 'Persephone, die Göttin des Frühlings, hätte nie gedacht, dass ihre kurze Begegnung mit Hades im Nevernight ihr Leben für immer verändern würde. Sie will ihren geliebten König der Unterwelt endlich heiraten, doch die Götterwelt befindet sich in einem erbitterten Krieg. Der Halbgott Theseus plant, die Olympier zu stürzen - und das Leben, das Persephone kannte, droht im tödlichen Chaos zu versinken. Ihr bleibt keine andere Wahl: Sie muss die Dunkelheit annehmen, die schon längst von ihrem Herzen Besitz ergriffen hat, oder sie riskiert, ihre gemeinsame Zukunft mit Hades für immer zu verlieren ...', '30.08.2024', 'LYX', ARRAY['Deutsch']::text[], 592, 42, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Götterwelt, Unterwelt, Olymp', '{}', ARRAY['Hade','Persephone']::text[], ARRAY['Greek/Rome Mythology']::text[], '{}', '3165e151-b62e-52a5-a283-2a48c0d1ce35', '4', '{}', 'sheet', :'owner') on conflict do nothing;
