insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d78b4b0-70c3-52e9-acaa-0b4e2cace10b', 'Pretty - Erkenne dein Gesicht', 'Pretties', NULL, 'Zu schön, um wahr zu sein. Tally ist eine Pretty geworden. Sie sieht umwerfend aus, trägt coole Klamotten, hat einen tollen Freund und ist ungeheuer beliebt. Sie ist so, wie sie es sich immer gewünscht hat. Aber trotz all dem Spaß – den Dauerpartys, dem Hightech-Luxus, den vielen Freiheiten – wird Tally von dem unbestimmten Gefühl geplagt, dass etwas nicht in Ordnung ist. Etwas Wichtiges. Dann erhält sie eine Botschaft aus ihrer Ugly-Vergangenheit. Und plötzlich weiß sie wieder, was mit den Pretties nicht stimmt. Damit hört der Spaß auf und Tally muss kämpfen – um ihre Erinnerungen und um ihr Leben. Denn die Behörden haben nicht vor, jemanden mit diesem Wissen davonkommen zu lassen.', '01.09.2007', 'Simon Pulse', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tally']::text[], '{}', '{}', '4fa928f4-b584-50d5-94e8-deb2e75eb3c5', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('7f462888-a965-5705-95b1-79844da18a2d', '1d78b4b0-70c3-52e9-acaa-0b4e2cace10b', 'Film') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ed32a5c3-0e75-5e96-a5f6-7618c1c72dc9', :'owner', '1d78b4b0-70c3-52e9-acaa-0b4e2cace10b', 'tbr'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a02e6f49-05b6-5ee1-90fd-24a614c27095', 'Special - Zeig dein wahres Gesicht', 'Specials', NULL, 'Eine weitere Operation hat Tally innerlich und äußerlich verwandelt: Sie ist jetzt eine `Special´, eine Waffe in menschlicher Gestalt - grausam-schön und voller Verachtung für alle Uglies und Pretties. Die neue Tally genießt das Special-Dasein, nur manchmal wird sie von leisen Zweifeln geplagt. Umso ernster nimmt sie ihren Auftrag, die Rebellen zu jagen, die heimlich das Heilmittel in der Stadt verteilen. Tally beschließt, das Übel bei der Wurzel zu packen, indem sie das Rebellendorf aufspürt. Dazu ermöglicht sie ihrem Freund Zane unter Vorspiegelung falscher Motive die Flucht aus der Stadt. Zane nimmt Kontakt zu den Rebellen auf, nicht ahnend, dass Tally ihm folgt. Aber unterwegs in der Wildnis wird Tally von Erinnerungen an ihre eigene Zeit als Rebellin geplagt und ist sich ihrer Sache plötzlich nicht mehr so sicher.', '01.05.2008', 'Simon Pulse', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tally']::text[], '{}', '{}', '4fa928f4-b584-50d5-94e8-deb2e75eb3c5', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('d8466bf4-eeda-5bd7-854d-7543c508de2a', 'a02e6f49-05b6-5ee1-90fd-24a614c27095', 'Film') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('655078ee-7478-56cd-8d1a-004d8320b452', :'owner', 'a02e6f49-05b6-5ee1-90fd-24a614c27095', 'tbr'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a76a71c5-8bed-5343-becb-6b55f29fab74', 'Extra - Wer kennt dein Gesicht', 'Extras', NULL, 'Keine Extra mehr sein! Das ist es, was sich Aya am meisten wünscht. Endlich zu denen gehören, die jeder kennt. Denn in Ayas Welt bedeutet Bekanntheit alles. Schließlich gibt es, seit die Rebellin Tally das Special-Regime gestürzt hat, eine neue Ordnung: Nicht mehr Schönheit entscheidet über ein glückliches, unbeschwertes Leben, sondern Ruhm. Als Aya zufällig eine Clique aufspürt, die nachts verbotene Aktionen durchzieht, glaubt sie einen Weg ins Rampenlicht gefunden zu haben. Aber die "Schlauen Mädchen" misstrauen ihr. Und sie verbergen etwas, eine Entdeckung, die die schöne neue Welt – und Ayas Leben – für immer verändern könnte!', '18.02.2010', 'Simon Pulse', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tally']::text[], '{}', '{}', '4fa928f4-b584-50d5-94e8-deb2e75eb3c5', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('b7ff24cb-6404-518f-a5aa-fed0e6185cc8', 'a76a71c5-8bed-5343-becb-6b55f29fab74', 'Film') on conflict do nothing;
