insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4b871d6c-ae77-5f8d-a827-e2cc5a8d8862', 'Ugly - Verlier nicht dein Gesicht', 'Uglies', '9783551355812', 'Tally kann ihren 16. Geburtstag kaum erwarten - denn mit 16 wird sie endlich hübsch! Sie bekommt dann die übliche Schönheitsoperation, die physische Unterschiede und Makel ausgleicht und somit allen die gleiche Chance gibt. Statt einer langweiligen "Ugly" wird Tally eine glückliche "Pretty" sein und im schönen Teil der Stadt leben. Doch vor ihrer Umwandlung zweifelt sie, ob sie wirklich das bequeme, vorbestimmte Leben einer Pretty führen möchte ...', '01.04.2007', 'Simon Pulse', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tally']::text[], '{}', '{}', '4fa928f4-b584-50d5-94e8-deb2e75eb3c5', '1', '{}', 'sheet', :'owner') on conflict do nothing;
