insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('889fca0c-af3d-5b1a-8375-074188b92d34', 'Das Geschenk', NULL, '9783426439821', 'Milan Berg schlägt sich geschickt durchs Leben, auch wenn er ein wohlgehütetes Geheimnis hat: Er ist Analphabet. Nicht einmal seine Freundin ahnt, dass er nicht lesen kann. Doch genau das wird ihm zum Verhängnis: Als er an einer Ampel steht, hält ein Wagen neben ihm – auf dem Rücksitz sieht er ein völlig verängstigtes Mädchen, das einen Zettel gegen die Schreibe presst. Handelt es sich um einen Hilferuf? Zwar kann Milan die Botschaft nicht lesen, aber er spürt ganz genau: Das Kind ist in tödlicher Gefahr!', '23.10.2019', 'Knaur', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Milan Berg']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
