insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('029be296-945a-579b-8a3d-f19a1fc31d7e', 'Der Insasse', NULL, '9783426439814', 'Zwei entsetzliche Kindermorde hat er bereits gestanden und die Berliner Polizei zu den grausam entstellten Leichen geführt. Doch jetzt schweigt Guido T., der im Hochsicherheitstrakt der Psychiatrie einsitzt, auf Anraten seiner Anwältin. Die Polizei ist sicher: Er ist auch der Entführer des sechsjährigen Max, der seit einem Jahr spurlos verschwunden ist. Die Ermittler haben jedoch keine belastbaren Beweise, nur Indizien. Und ohne die Aussage des Häftlings werden Max'' Eltern keine Gewissheit haben und niemals Abschied von ihrem Sohn nehmen können. Monate nach dem Verschwinden von Max macht ein Ermittler der Mord-Kommission dem verzweifelten Vater ein unglaubliches Angebot: Er schleust ihn in das psychiatrische Gefängnis-Krankenhaus ein, in dessen Hochsicherheitstrakt Guido T. eingesperrt ist. Als falscher Patient, ausgestattet mit einer fingierten Krankenakte. Damit er dem Kindermörder so nahe wie nur irgend möglich ist und ihn zu einem Geständnis zwingen kann. Denn nichts ist schlimmer als die Ungewissheit. Dachte er. Bis er als Insasse die grausame Wahrheit erfährt ...', '24.10.2018', 'Knaur', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Berlin', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
