insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7b4f28dc-3754-52bb-833b-ffc7e0c5927a', 'Die Einladung', NULL, '9783426439869', 'In Vorfreude auf ein verlängertes Wochenende in den Alpen folgt Marla Lindberg der Einladung zu einem Klassentreffen. Doch schon kurz nach der Ankunft wird ihr klar: Es gibt nur eins, was tödlicher ist, als das abgeschiedene Berghotel nachts im eisigen Schneetreiben wieder zu verlassen. Es nicht zu tun … Die Einladung: Wehe dem, der sie erhält… Marla Lindbergs Erinnerungen sind glasklar: An die seltsame Nachricht, die sie in eine stillgelegte Geburtsklinik lockte. An die Gestalt, die versuchte, sie zu töten. Das seltsam pfeifende Husten des Psychopathen beim Kampf auf Leben und Tod. Nach Jahren der Psychotherapie hat die hochintelligente junge Frau gelernt: Das alles sind falsche Erinnerungen. Marla leidet unter Gesichtsblindheit. Ihr Gehirn spielt ihr in Extremsituationen Streiche, wenn es vergeblich versucht, Menschen an ihrem Gesicht zu erkennen. Als Marla die Einladung zum Klassentreffen in den Alpen bekommt, hofft sie darauf, mit ihren ehemaligen Mitschülern in schönen und echten Erinnerungen schwelgen zu können. Bei ihrer Ankunft in dem verschneiten Berghotel sind alle Zimmer bereits bezogen. Benutztes Geschirr steht auf dem Esstisch, der Kamin flackert, doch es ist niemand da. Marla beginnt die anderen zu suchen. Und dann hört sie es wieder. Wie jemand pfeifend hustet, draußen, in der eisigen Dunkelheit …', '25.10.2023', 'Knaur', ARRAY['Deutsch']::text[], 309, 84, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Berghotel', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Marla Lindberg']::text[], ARRAY['Isolation','Unreliable Narrator']::text[], ARRAY['Mord','Suizidalität','Physische Gewalt','Depiction of Trauma','Tod','Sexuelle Gewalt']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('d6ca3ee4-a786-5fad-b6e6-aa9aeb76bf63', :'owner', '7b4f28dc-3754-52bb-833b-ffc7e0c5927a', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Limited', '{}', 1999, NULL, NULL, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'like'::verdict_kind, 3.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Das Buch hat mich wirklich gut unterhalten und hat Spaß gemacht. Leider habe ich bei dem zweiten Buch, das ich von Fitzek lese, schon das Gefühl ihn durchschaut zu haben, weshalb ich leider die meisten Wendungen erwartet habe. Trotzdem ein gutes Buch.') on conflict do nothing;
