insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c34ea720-61a6-5eaa-91f1-6772183159be', 'Der Heimweg', NULL, '9783426439838', 'Es ist Samstag, kurz nach 22.00 Uhr. Jules Tannberg sitzt am Begleit-Telefon. Ein ehrenamtlicher Telefon-Service für Frauen, die zu später Stunde auf ihrem Heimweg Angst bekommen und sich einen telefonischen Begleiter wünschen, dessen beruhigende Stimme sie sicher durch die Berliner Nacht nach Hause führt - oder im Notfall Hilfe ruft. Noch nie gab es eine wirklich lebensgefährliche Situation. Bis heute, als Jules mit Klara spricht. Die junge Frau hat entsetzliche Angst. Sie glaubt, von einem Mann verfolgt zu werden, der sie schon einmal überfallen hat und der mit Blut ein Datum auf ihre Schlafzimmerwand malte: Klaras Todestag!Und dieser Tag bricht in nicht einmal zwei Stunden an ..', '21.10.2020', 'Knaur', ARRAY['Deutsch']::text[], 330, 69, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Berlin', ARRAY['Multiple POV','3P Limited']::text[], ARRAY['Jules Tannberg']::text[], ARRAY['Unreliable Narrator']::text[], ARRAY['Sexuelle Gewalt','Physische Gewalt','Suizidalität','Kidnapping','Folter','Mord','Tod','Depiction of Trauma','Rape','Toxische Beziehungsdynamiken','Psychische Erkrankung/Belastung','Tod von Familienangehörigen','Kindstod/Fehlgeburten']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
