insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('2fbcd680-8a27-5c1b-a5cb-482f0c81e59a', :'owner', 'c34ea720-61a6-5eaa-91f1-6772183159be', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, NULL, NULL, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Bisher mein liebstes Buch von Fitzek. Es war richtig spannend und ich hab immer wieder gedacht: WTF!? Ich hatte wirklich etwas ganz anderes erwartet, als das, was es letztendlich war. Sehr gut aber. Krasse Themen die behandelt werden und sehr bildlich dargestellt werden.') on conflict do nothing;
