insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bfdfdd2c-6ab5-5b67-84c0-4dc8b28561ef', 'Flugangst 7A', NULL, '9783426444672', 'Wir haben für Sie reserviert: 7A. Der gefährlichste Platz in einem Flugzeug...: Mats Krüger, ein erfahrener und erfolgreicher Psychiater, muss seine panische Flugangst überwinden, als seine hochschwangere Tochter Nele nach jahrelanger Funkstille wieder Kontakt zu ihm aufnimmt. Mats, der nach dem Tod seiner Frau per Schiff nach Argentinien ausgewandert ist, hatte nie wieder vor zurückzukehren. Doch jetzt bittet Nele ihren Vater kurzfristig, ihr nach der Geburt des Babys Beistand zu leisten. Nach der Teilnahme an einem Flugangst-Seminar geht Mats an Bord des Langstreckenflugs Buenos Aires - Berlin. Schon kurz nachdem er seinen Platz eingenommen hat, muss er feststellen, dass er sich auf die falschen Ängste vorbereitet hat: Es ist keine Turbulenz, kein Druckabfall und keine Terrorwarnung, die ihn in einen entsetzlichen seelischen Ausnahmezustand treiben.', '25.10.2017', 'Knaur', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Flugzeug', '{}', ARRAY['Mats Krüger']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
