insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba039399-07b6-536e-9b8a-5b95fc0a7005', 'Das Paket', NULL, '9783426440087', 'Aus dem harmlosen Alltag wird ein gefährlicher Alptraum: Seit die junge Psychiaterin Emma Stein in einem Hotelzimmer vergewaltigt wurde, verlässt sie das Haus nicht mehr. Sie war das dritte Opfer eines Psychopathen und Serienmörders, den die Presse den »Friseur« nennt – weil er den misshandelten Frauen die Haare vom Kopf schert, bevor er sie ermordet. Emma, die als Einzige mit dem Leben davonkam, hat große Angst, der »Friseur« könnte sie erneut heimsuchen, um seine grauenhafte Tat zu vollenden. In ihrer Paranoia glaubt sie in jedem Mann ihren Peiniger wiederzuerkennen, dabei hat sie den Täter nie zu Gesicht bekommen. Nur in ihrem kleinen Haus am Rande des Berliner Grunewalds fühlt sie sich noch sicher – bis der Postbote sie eines Tages bittet, ein Paket für ihren Nachbarn anzunehmen. Einen Mann, dessen Namen sie nicht kennt und den sie noch nie gesehen hat, obwohl sie schon seit Jahren in ihrer Straße lebt ...', '26.10.2016', 'Knaur', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Berlin', '{}', ARRAY['Emma Stein']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('95b54f15-013b-5d34-b90b-62b63953aca0', :'owner', 'ba039399-07b6-536e-9b8a-5b95fc0a7005', 'gelesen'::reading_status, true, false, ARRAY['Digital','Audiobook']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, NULL, NULL, ARRAY['Audible']::text[], ARRAY['Simon Jäger']::text[], 449, '👍🏻', false, 'solo'::company_kind, 'love'::verdict_kind, 4.5, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Unheimlich spannend, aber hat mich auch so wütend gemacht wie der Main behandelt wird. Die Tatsache, dass man die ganze Zeit nicht weiß, wie reliabel der MC ist hat es so spannend gemacht!') on conflict do nothing;
