insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e0ecfa6f-5f9d-5040-b228-579a703840b5', 'Noah', NULL, '9783838744964', 'Er weiß nicht, wie er heißt. Er hat keine Ahnung, wo er herkommt. Er kann sich nicht erinnern, wie er nach Berlin kam, und seit wann er hier auf der Straße lebt. Die Obdachlosen, mit denen er umherzieht, nennen ihn Noah, weil dieser Name tätowiert auf der Innenseite seiner Handfläche steht. Die Suche nach seiner Identität wird zu einem Alptraum, für Noah und die gesamte Menschheit. Ist er das wesentliche Element in einer Verschwörung, die das Leben aller Menschen auf dem Planeten gefährdet und schon zehntausende Opfer gefunden hat?', '19.12.2013', 'Lübbe', ARRAY['Deutsch']::text[], 559, 28, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Berlin', '{}', ARRAY['Noah']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
