insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('131b73d3-55a0-5e0c-9c1b-b33d16d54475', 'Die Blutschule', NULL, '9783732515233', 'Eine unbewohnte Insel im Storkower See. Eine Holzhütte, eingerichtet wie ein Klassenzimmer. Eine Schule mit den Fächern: Fallen stellen. Opfer jagen. Menschen töten. Die Teenager Simon und Mark können sich keinen größeren Horror vorstellen, als aus der Metropole Berlin in die Einöde Brandenburgs zu ziehen. Das Einzige, worauf sie sich freuen, sind sechs Wochen Sommerferien, doch auch hier macht ihnen ihr Vater einen Strich durch die Rechnung. Er nimmt sie mit auf einen Ausflug zu einer ganz besonderen Schule. Gelegen mitten im Wald auf einer einsamen Insel. Mit einem grausamen Lehrplan, nach dem sonst nur in der Hölle unterrichtet wird ...', '08.10.2015', 'Lübbe', ARRAY['Deutsch']::text[], 255, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], NULL, 'Gegenwart'::time_period, 'Brandenburg', '{}', ARRAY['Simon','Mark']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
