insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1364d1e2-4006-5ff8-a434-9d95635abd7a', 'Schreib oder stirb', NULL, NULL, 'Carl Vorlau, mysteriöser Patient einer psychiatrischen Privatklinik, behauptet, vor Monaten die siebenjährige Pia entführt und an einen geheimen Ort verschleppt zu haben. Über seine Tat will Vorlau nur mit einem einzigen Menschen reden - dem ebenso humorvollen wie unkonventionell arbeitenden Literaturagenten David Dolla, dem Vorlau ein diabolisches Angebot macht: Der Agent soll ihm einen Verlagsvorschuss von einer Million Euro verschaffen, für einen Thriller mit dem Titel "Ich töte was, was du nicht siehst". Ein Geständnis in Form eines True-Crime-Romans über das Schicksal der kleinen Pia! Als Belohnung verspricht Vorlau, Dolla zu einem Helden zu machen, der das Mädchen in letzter Sekunde vor dem sicheren Tod rettet. Sollte Dolla den Auftrag jedoch ablehnen, will Vorlau nicht nur Pia sterben lassen, sondern auch das Leben des Agenten für immer zerstören …', '30.03.2022', 'Droemer', ARRAY['Deutsch']::text[], 336, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['David Dolla']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
