insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('47906981-c42e-5d27-9c82-d801b6c115b3', 'Lessons in Faking', NULL, '9783736323728', 'There’s one thing Athalia Pressley wants more than anything: her twin brother’s affection. Since their parents’ death, Henry hasn’t given her much of it - until a halfway-to-failed class and the need for a tutor land Athalia in his enemy’s lap. Suddenly she’s awarded Henry’s undivided attention, and if she wants to keep it that way, she needs Dylan McCarthy Williams. She’s not fond of her brother’s rival, his slick comments, or that know-it-all attitude. Not even the fluffy hair, dreamy eyes or body of a college soccer player help. But through forced laughs and fake dates, it seems the two can leave their bickering behind to chase one common goal: a Pressley’s attention.', '25.10.2024', 'LYX', ARRAY['Englisch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Hall Beck University', '{}', ARRAY['Athalia Pressley','Dylan McCarthy Williams']::text[], ARRAY['Sport']::text[], '{}', '2b0e9e5f-754c-52f0-b3ee-c8dde0918334', '1', '{}', 'sheet', :'owner') on conflict do nothing;
