insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5cc08fb2-9b90-5a3d-92ca-9f6552384464', 'Alchemised', NULL, '9780241714331', 'In a world ruled by necromancers, a woman with missing memories threatens the dark order that keeps her captive - and the man sent to break her. Gothic in tone, epic in scope - this debut is destined to become a modern classic. Once a promising alchemist, Helena Marino is now a prisoner - of war and of her own fractured mind. The Resistance is crushed, her allies dead, her abilities suppressed. The world she knew is gone. Paladia''s corrupt guild families and their necromancer overlords, aided by vile undead creatures now rule - and hold Helena captive. Resistance records claim she was a healer of little importance. Yet, Helena''s inexplicable memory loss makes her enemies wonder: Is she truly insignificant, or do her missing memories conceal the Resistance''s final secret? To uncover the truth, Helena is delivered into the hands of the High Reeve - Paladia''s most feared and merciless necromancer. Trapped on his crumbling estate, she must fight to protect what remains of herself and unearth the secrets buried in her mind, her prison, and her captor . . . whatever the cost.', '23.09.2025', 'Penguin Books Ltd', ARRAY['Englisch']::text[], 1048, 78, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dark Fantasy']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Paladia', ARRAY['Single POV','3P Limited']::text[], ARRAY['Helena Marino']::text[], ARRAY['Dark Secrets','Enemies to Lovers','War Romance','Academy','Anti-Hero','Body Horror','Good vs. Evil','Outsider Hero']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('1c6cf56c-765c-5229-89d5-2d280c32a799', :'owner', '5cc08fb2-9b90-5a3d-92ca-9f6552384464', 'gelesen'::reading_status, true, true, ARRAY['Digital','Print']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', '{}', 2999, NULL, NULL, '{}', '{}', NULL, NULL, false, 'buddy'::company_kind, 'love'::verdict_kind, 5.0, 'uebertroffen'::expectation_kind, 1, 'slow'::burn_kind, 'Dieses Buch hat so komplexe Gefühle in mir ausgelöst, dass ich sie nicht mal richtig beschreiben kann. Ich habe noch nie ein Buch gelesen, dass so grausam, tragisch und traurig ist. Ein Meisterewerk. Die Welt, das System und die Charaktere sind so ausgeklügelt und komplex, wie ich es selten erlebt habe. Noch nie konnte ich mir einen Krieg so graphisch vorstellen.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('687f3f34-cbce-536c-ae03-145dcb331460', '1c6cf56c-765c-5229-89d5-2d280c32a799', :'owner', 1, '2025-10-14', '2025-11-09', NULL, NULL, 27, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('77f9ce44-c49f-5ae8-b330-0761304c4239', 'A Stage Set for Villains', NULL, '9781911753155', 'The performers of the Playhouse are as worshipped as they are feared, their enchanting shows bending hearts, minds, and even reality itself. Vicious, godlike, lethal. Eighteen-year-old Riven Hesper knows the dangers better than anyone, after her own encounter with a Player resulted in a curse that is slowly killing her. When the Playhouse announces the spectacle of a lifetime – a chance for one mortal to steal a Player’s immortality – Riven sees her last chance to live. Desperate for answers, she infiltrates the competition. There, she finds Jude, the Playhouse’s brilliant, merciless Lead Player, whose charm is as dangerous as his Craft, and strikes a deadly bargain to save her life. But with time running out and the Playhouse’s secrets unraveling into a disturbing picture, Riven faces a grim possibility: she might not be the hero of her story after all. In fact, she may be the villain. Because the Playhouse doesn’t just tell stories. It rewrites them. And Riven’s might end in blood.', '03.02.2026', 'Mayhem Books', ARRAY['Englisch']::text[], 513, 99, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Playhouse', ARRAY['Single POV','1P']::text[], ARRAY['Riven Hesper','Jude']::text[], ARRAY['Enemies to Lovers','Found Family','Anti-Hero']::text[], ARRAY['Tod von Familienangehörigen','Physische Gewalt','Krankheit']::text[], NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
