insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('511274b0-5009-5a72-8e38-6484325ad87c', 'Sky Link', NULL, '9783842005143', 'Der Student Ritsuki ist genervt von seinem Dozenten Takagi, der keine Gelegenheit auslässt, sich an ihn ranzumachen, und ihm auch unverblümt mitteilt, dass er Ritsuki toll findet. Doch als er Takagi eines Tages dabei beobachtet, wie dieser traurig und gedankenverloren in den Himmel starrt, wird Ritsukis Interesse geweckt, da er dies selbst gern macht. Nach und nach wird aus diesem Interesse Zuneigung und Liebe, doch trotz vieler Gemeinsamkeiten scheint eine Beziehung zwischen Student und Dozent unmöglich …', '09.05.2012', 'Taifu Comics', ARRAY['Deutsch']::text[], 208, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, NULL, NULL, ARRAY['3P Objective']::text[], ARRAY['Ritsuki Ban','Takagi']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
