insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0a840360-ac83-5676-a21a-c5859e5ad119', 'JunJo Romantica (Vol.1)', 'Junjō Romanchika', '9783551751317', 'Der reiche, aber einsame Akihiko ist Bestsellerautor und heimlicher Erotikromanschreiber zugleich. Aus Gefälligkeit gibt er einem Jungen aus der Unterschicht, Misaki, Nachhilfeunterricht. Recht schnell findet er aber mehr als nur Gefallen an seinem Schüler. Auch Akihikos Freund Hiroki hat mit der Liebe zu kämpfen. Erst kann er seine letzte Liebschaft nicht vergessen, und dann tritt der attraktive Nowaki in sein Leben. Er setzt alles daran, dass Nowaki bleibt, aber ihm seine Liebe gestehen – ob er das schafft?', '22.12.2006', 'Carlsen', ARRAY['Deutsch']::text[], 194, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Akihiko','Misaki']::text[], ARRAY['Queer']::text[], '{}', '6debac16-dd65-5f2d-b8a9-36e8afcee7c6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
