insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bbe3c430-d42d-566f-9561-859f522bd13c', 'Star Daughter', NULL, NULL, 'The daughter of a star and a mortal, Sheetal is used to keeping secrets. Pretending to be “normal.” But when an accidental flare of her starfire puts her human father in the hospital, Sheetal needs a full star’s help to heal him. A star like her mother, who returned to the sky long ago. Sheetal’s quest to save her father will take her to a celestial court of shining wonders and dark shadows, where she must take the stage as her family’s champion in a competition to decide the next ruling house of the heavens—and win, or risk never returning to Earth at all.', '11.08.2020', 'HarperCollins', ARRAY['Englisch']::text[], 435, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', NULL, NULL, NULL, '{}', ARRAY['Sheetal']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
