insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a08a5593-79cf-5635-9937-3cc9d1b20122', 'Die ewigen Toten', 'The Scent of Death', NULL, 'Das stillgelegte Krankenhaus St. Jude im Norden Londons soll in Kürze abgerissen werden. Doch dann wird auf dem staubigen Dachboden eine mumifizierte Leiche gefunden, eingewickelt in eine Plastikhülle. Dr. David Hunter erkennt sofort, dass sie schon lange hier liegt. Durch das trockene und stickige Klima ist der Körper teilweise mumifiziert. Als der forensische Anthropologe die Leiche näher untersucht, stellt er fest, dass es sich um eine Frau handelt. Bei der Bergung der Toten entdeckt die Polizei ein fensterloses Krankenzimmer, das auf keinem Plan verzeichnet ist. Warum wurde der Eingang zugemauert, obwohl dort nach wie vor Krankenbetten stehen? Betten, in denen noch jemand liegt...', '20.07.2021', 'Rowohlt', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Psychothriller']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'St. Jude Krankenhaus', '{}', ARRAY['David Hunter']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
