insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5ec53325-ad99-5cb4-a44b-1ee9f87a05f3', 'Amber Eyes - Mit Dir Für Immer', NULL, NULL, 'Für Sam, den gefeierten Star einer Boy-Group, ist es Zeit für Veränderungen und er beschließt, endlich solo durchzustarten. Er möchte ehrliche Songs machen, von seinem eigenen Leben erzählen. Aber hat er das überhaupt noch? Ein eigenes Leben? Um das herauszufinden, begibt er sich auf die Suche nach Paul, seinem besten Freund aus Jugendjahren. Als ihm ausgerechnet Alice die Nachricht überbringt, dass ihr Zwillingsbruder Paul gestorben ist, bricht der hochsensible Musiker förmlich zusammen. Denn Alice ist seine große Jugendliebe, die er nie ganz vergessen konnte. Gemeinsam lassen sie Erinnerungen an Paul aufleben - und merken, dass sie einander immer noch viel bedeuten. Dass sie sich brauchen und einander Halt geben. Doch kann Alice vergessen, dass Sam ihr das Herz gebrochen und ihren Bruder im Stich gelassen hat? Und wo ist in Sams Rockstarleben Platz für die tiefe ehrliche Liebe, nach der sich Alice so sehr sehnt?', '30.09.2020', 'Beheartbeat', ARRAY['Deutsch']::text[], 318, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Alice','Sam']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('0699ec93-3ca2-55f5-869b-2139007026ba', :'owner', '5ec53325-ad99-5cb4-a44b-1ee9f87a05f3', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 499, NULL, NULL, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('29e60a63-ad5a-55a0-ae12-b49ee0898341', 'Und Wir Tanzen Über Den Flüssen - love is love', NULL, '9783453425323', 'June ist voller Lebenslust und steht am Anfang ihrer Arbeit am Theater. Nichts macht ihr Angst, mit Ausnahme des fragenden Ausdrucks in Kians Augen, den sie für ihren großen Traum, Musicaldarstellerin zu werden, nach nur wenigen gemeinsamen Monaten verlassen hat. Doch mindestens genau so sehr fürchtet sie Ashs hasserfüllte Blicke. Ash, Kians bester Freund, der sie schon immer auf unerklärliche Art und Weise faszinierte. Die drei begegnen sich immer wieder in Londons Straßen, und mit jedem Treffen wird ihnen klar, dass die Gefühle zwischen ihnen noch komplizierter sind, als sie bisher geahnt haben.', '13.12.2021', 'Heyne', ARRAY['Deutsch']::text[], 458, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], NULL, 'Gegenwart'::time_period, NULL, '{}', ARRAY['June','Kian','Ash']::text[], '{}', '{}', 'ee73467c-088c-5b5d-b042-bace88e6cf01', '3', '{}', 'sheet', :'owner') on conflict do nothing;
