insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('274597ed-c96b-53fd-9a8a-a9add1c75091', 'Cruel is the Light', NULL, '9780241730515', 'A brutal war between demons and humanity has raged across Europe for over a century. At its heart are two elite soldiers: Selene Alleva, a powerful exorcist trained at the prestigious Vatican Academy, and foot soldier, Jules Lacroix, unrivalled in battle. When their paths cross, despite initial distrust – then unwelcome attraction – Jules and Selene discover a terrible secret at the heart of the holy Vatican City. . . Soon Jules is forced to question everything he’s ever known – including himself. And Selene, unable to ignore her growing feelings for Jules, must make an impossible choice between love and duty.', '23.01.2025', 'Fairyloot', ARRAY['Englisch']::text[], 491, 43, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, 'Vatican City', '{}', ARRAY['Selene Alleva','Jules Lacroix']::text[], ARRAY['Enemies to Lovers']::text[], '{}', 'ac1572c9-235e-5446-b468-e5031082268c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
