insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f6caea19-a91d-53b6-9ae7-015fca2e3f1d', 'Infernale', 'Uninvited', NULL, 'Der erste Band der neuen Jugendbuch-Reihe von Firelight-Autorin Sophie Jordan konfrontiert Leser mit der Frage, inwiefern unsere DNA unser Schicksal bestimmt. Der Auftakt zu einer spannenden Reihe überzeugt mit packender Action, gefühlvoller Romantik und der schwierigen Suche nach der eigenen Identität. Von klein auf hörte ich Wörter wie begabt. Überdurchschnittlich. Begnadet. Ich hatte all diese Wünsche, wollte etwas werden. Jemand. Niemand sagte: Das geht nicht. Niemand sagte: Mörderin. Als Davy in einem DNA-Test positiv auf das Mördergen Homicidal Tendency Syndrome (HTS) getestet wird, bricht ihre heile Welt zusammen. Sie muss die Schule wechseln, ihre Beziehung scheitert, ihre Freunde fürchten sich vor ihr und ihre Eltern meiden sie. Aber sie kann nicht glauben, dass sie imstande sein soll, einen Menschen zu töten. Doch Verrat und Verstoß zwingen Davy zum Äußersten. Wird sie das werden, für das alle Welt sie hält und vor dem sie sich am meisten fürchtet - eine Mörderin?', '15.02.2016', 'Loewe', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Davy']::text[], '{}', '{}', '26e230e9-6ea1-5468-af9d-53b36f10962b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
