insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('68cbd664-bd2c-54f3-baa0-2c21a1b98781', 'Infernale - Rhapsodie in Schwarz', NULL, NULL, 'Das packende Finale des spannenden Jugendbuch-Zweiteilers! Abermals liefert Firelight-Autorin Sophie Jordan eine fesselnde Geschichte, die sich kritisch mit Moral und Vorurteilen in der heutigen Gesellschaft auseinandersetzt. Natürlich kommen auch Romantik und Action nicht zu kurz – ein außergewöhnliches Lesevergnügen! Ich hatte geglaubt, Mörderin genannt zu werden und alles zu verlieren – meine Zukunft, meinen Freund, meine Freunde – wäre das Schlimmste, was mir passieren konnte. Aber ich habe mich getäuscht. Herauszufinden, dass sie recht haben? Herauszufinden, dass ich genau das bin? Das ist noch viel schlimmer. Seit Davy positiv auf das Mördergen (HTS) getestet wurde, hat sie alles verloren: ihre Familie, ihre Freunde, ihre Zukunft – und was am schlimmsten ist, sich selbst. Denn obwohl sie verzweifelt dagegen angekämpft hat, ist sie doch zu dem geworden, was sie nie sein wollte: eine Mörderin. Eine Widerstandsgruppe und ihr Anführer Caden geben ihr ein neues Ziel. Und Caden weckt Gefühle in ihr, zu denen sie glaubte, nie mehr fähig zu sein. Aber die Schuldgefühle lassen Davy einfach nicht los ...', '13.03.2017', 'Loewe', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Davy']::text[], '{}', '{}', '26e230e9-6ea1-5468-af9d-53b36f10962b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('9be12510-c922-533a-a5c4-c19b71910968', :'owner', '68cbd664-bd2c-54f3-baa0-2c21a1b98781', 'ungelesen'::reading_status, true, true, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 699, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, 0, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cbad8bce-a3c0-5703-ba48-33f832f1ff0d', 'Firelight - Brennender Kuss', NULL, '9783785570456', 'Als sie Will zum ersten Mal sieht, flieht Jacinda vor dem Jungen mit den haselnussbraunen Augen. Denn sie hat ein Geheimnis: Sie ist eine Draki, ein Mädchen, das sich in einen Drachen verwandeln kann. Nur in ihrem Rudel, hoch oben in den Bergen, glaubt sich Jacinda sicher. Sicher vor den Drachenjägern, die es auf ihre schillernde Haut und ihr purpurfarbenes Blut abgesehen haben. Doch im Rudel braut sich Unheil zusammen. Hat es damit zu tun, dass Jacinda den gut aussehenden Cassian, den zukünftigen Leitdrachen, heiraten soll? Ihre Mutter verschweigt ihr etwas, als sie bei Nacht und Nebel das Dorf verlassen. Todunglücklich beginnt Jacinda ein neues Leben. Da trifft sie Will wieder und Hals über Kopf verliebt sie sich in ihn. Aber ihre Liebe darf nicht sein – denn Will ist ein Drachenjäger.', '01.08.2011', 'Loewe', ARRAY['Deutsch']::text[], 373, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Will','Jacinda']::text[], '{}', '{}', '0aa6242e-e1fb-511c-8866-1d3029f05414', '1', '{}', 'sheet', :'owner') on conflict do nothing;
