insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('15dbf903-35a1-5d37-9df4-0b2ca25709d2', 'Firelight - Flammende Träne', NULL, '9783785570463', 'Um den Jungen, den sie liebt, zu retten, offenbart Jacinda ihre wahre Natur und verwandelt sich vor Menschen in einen Draki. Wenn sie ihre Art vor den Drachenjägern schützen will, darf sie Will nie wieder sehen und muss zu ihrem Stamm zurückkehren. Als die Gelegenheit kommt, ihrem Herzen zu folgen, muss sie eine schwere Entscheidung treffen. Wird sie ihre Familie für die Liebe aufgeben? Verbotene Liebe brennt heißer denn je. Der mitreißende zweite Band der Trilogie – feurig gelesen von Stephanie Kellner.', '12.11.2012', 'Loewe', ARRAY['Deutsch']::text[], 335, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Will','Jacinda']::text[], '{}', '{}', '0aa6242e-e1fb-511c-8866-1d3029f05414', '2', '{}', 'sheet', :'owner') on conflict do nothing;
