insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('bfb06704-c6fb-5ace-96a1-5bbb16116470', '0747de1c-c0f7-5d55-8d1b-f354ee06705a', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('207f6fcc-f386-5ec1-b853-b69d552fea24', 'Firelight - Leuchtendes Herz', NULL, '9783785570470', 'Miram wurde gefangen genommen, und das ist ganz allein Jacindas Schuld. Zwar gelingt es ihr in einer wahnwitzigen Aktion, Miram zu befreien, doch damit ist das Rudel der Draki längst nicht sicher. Denn die Drachenjäger sind ihnen dicht auf der Spur. Zugleich drohen die Gefühle des Drakiprinzen Cassian zur Gefahr für die Liebe zwischen Jacinda und Will zu werden. Wenn er nicht bereit ist, Jacinda gehen zu lassen, wird sie für immer an das Rudel gefesselt sein. Und das Leben mit Will, nach dem sie sich schon so lange sehnt, wird niemals möglich sein.', '15.11.2013', 'Loewe', ARRAY['Deutsch']::text[], 317, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Will','Jacinda']::text[], '{}', '{}', '0aa6242e-e1fb-511c-8866-1d3029f05414', '3', '{}', 'sheet', :'owner') on conflict do nothing;
