insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3c31c760-61b5-5f91-8968-6294422368f7', 'How to win my Husband over (Vol.1)', '남편을 내 편으로 만드는 방법', '9783989501102', 'Rudbeckia de Borgia ist die ungeliebte, uneheliche Tochter des Papstes in einem historischen Roman. Von ihrem Vater als politische Schachfigur eingesetzt, soll sie den Ritter eines verfeindeten Reiches heiraten - und dessen Schwester töten.\nDoch Ruby weiß, dass sie durch die Hand ihres zukünftigen Ehemanns sterben wird, wenn sie den Wünschen ihrer dysfunktionalen Familie folgt. Ihr einziger Weg aus dem Verderben ist nun, ihren zukünftigen Ehemann auf ihre Seite zu ziehen und das Attentat zu verhindern …', '14.04.2025', 'Papertoons', ARRAY['Deutsch']::text[], 288, 15, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Historischer Liebesroman']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rudbeckia']::text[], ARRAY['Enemies to Lovers','Family Drama']::text[], ARRAY['Essstörung','Häusliche Gewalt','Depiction of Trauma']::text[], '7854ac30-d541-55e7-ad96-5b4467b7a135', '1', '{}', 'sheet', :'owner') on conflict do nothing;
