insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('fb263f49-db8d-56c5-8877-6de186fe614f', '550b4b98-bcc1-5556-a200-f6ddccb5e8fe', :'owner', 1, '2026-02-09', '2026-02-09', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('069bf770-3831-50d6-949a-1030606b3734', 'How to win my Husband over (Vol.2)', '남편을 내 편으로 만드는 방법', '9783989501119', 'Um das Vertrauen ihres Ehemannes Iske zu gewinnen, tritt Ruby nach ihrer Ankunft im Norden als ahnungsloses, verliebtes Mädchen auf. Doch während sie die Freundschaft seiner Schwester schnell gewinnen kann, trachten ihr andere Bewohner ihrer neuen Heimat weiterhin nach dem Leben.\nUnd so sehr sich Ruby bemüht – vor Iske bröckelt ihre Fassade und zeigt die tiefen Wunden, die ihre Familie hinterlassen hat. Doch sie muss Acht geben! Denn wenn ihr Mann sie zurück zu ihrer Familie schickt, wer wird dann das Attentat auf seine Schwester verhindern …?', '14.07.2025', 'Papertoons', ARRAY['Deutsch']::text[], 288, 16, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Historischer Liebesroman']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rudbeckia']::text[], ARRAY['Enemies to Lovers','Family Drama']::text[], ARRAY['Essstörung','Häusliche Gewalt','Depiction of Trauma']::text[], '7854ac30-d541-55e7-ad96-5b4467b7a135', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('cc683537-2616-509f-a371-7d1aa439425f', :'owner', '069bf770-3831-50d6-949a-1030606b3734', 'gelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1600, true, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Es bleibt auf jeden fall sehr spannend. Ich bin neugierig wie es weiter geht und ob Ruby es schafft, ihr Schicksal zu ändern. Ich hoffe, dass Ruby bald ehlicher zu sich stehen wird. Ich glaube, Izke steht viel mehr auf ihrere Seite als sie erwarten würde.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('2bfe198c-c842-5e4b-83d6-4196569821e7', 'cc683537-2616-509f-a371-7d1aa439425f', :'owner', 1, '2026-02-18', '2026-02-18', NULL, NULL, 1, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aaffe239-ae5c-5362-ad07-81984a78414f', 'How to win my Husband over (Vol.3)', '남편을 내 편으로 만드는 방법', '9783989501126', 'Freya wurde vergiftet, und Rudbeckia weiß sofort, wer im Zentrum der Anschuldigungen stehen wird – schließlich \nist die Familie des Papstes bekannt für ihre skrupellosen Attentate. Ruby ist verzweifelt. Sie weiß nicht, wie sie den \nVerdacht von sich lösen soll … und der eiskalte Blick in Iskes Gesicht, als er Freya zur Hilfe eilte, geht ihr nicht aus \ndem Sinn. Es scheint, als wäre all die Wärme, die er Ruby bisher entgegengebracht hat, verloren.\nVielleicht wäre es besser, wenn sie einfach verschwinden würde. Wenn ihr sowieso niemand glaubt, wird sie dann \nüberhaupt jemand suchen kommen?', '13.10.2025', 'Papertoons', ARRAY['Deutsch']::text[], 288, 15, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Historischer Liebesroman']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rudbeckia']::text[], ARRAY['Enemies to Lovers','Family Drama']::text[], ARRAY['Essstörung','Häusliche Gewalt','Depiction of Trauma']::text[], '7854ac30-d541-55e7-ad96-5b4467b7a135', '3', '{}', 'sheet', :'owner') on conflict do nothing;
