insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4c962795-67eb-5562-a029-3d92a94b8d05', 'How to win my Husband over (Vol.4)', '남편을 내 편으로 만드는 방법', '9783989501133', 'Iske hat Ruby nach ihrer Flucht inmitten der Wildnis gefunden und nach Hause gebracht. Zu ihrer Überraschung erwarten sie weder Argwohn noch Verachtung, sondern ein herzliches und warmes Willkommen. \n\nDoch der Verantwortliche für das Attentat auf Freya wurde noch immer nicht gefasst. Hinter den Kulissen braut sich eine Verschwörung zusammen. Und als Iskes Familie ein Bankett zu Rubys Ehren plant, wird Ruby erneut angegriffen …', '19.01.2026', 'Papertoons', ARRAY['Deutsch']::text[], 280, 16, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Historischer Liebesroman']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Rudbeckia']::text[], ARRAY['Enemies to Lovers','Family Drama']::text[], ARRAY['Essstörung','Häusliche Gewalt','Depiction of Trauma']::text[], '7854ac30-d541-55e7-ad96-5b4467b7a135', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('1d54f019-8be7-596b-aa6d-d781980286f5', :'owner', '4c962795-67eb-5562-a029-3d92a94b8d05', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1600, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'love'::verdict_kind, 4.0, 'uebertroffen'::expectation_kind, 0, 'slow'::burn_kind, 'Es war so schön zu sehen, wie Iske und Ruby sich endlich näher kommen und wie sie sich langsam aber sicher verfallen. Ich habe richtig Angst davor, dass alles kaputt geht. Das einzige was mich ein wenig nervt ist, dass Ruby sich noch immer so sehr hinter ihrer Maske versteckt. Ich wünschte, sie würde Anfangen Iske und Ellen mehr zu vertrauen. Sie müssen die Wahrheit erfahren.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('f26f3b8a-1098-57d2-ad84-e31a51d84753', '1d54f019-8be7-596b-aa6d-d781980286f5', :'owner', 1, '2026-03-10', '2026-03-11', NULL, NULL, 2, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('39127cca-fce8-5ddd-a3da-864eeb0493f0', 'Once Upon a Broken Heart', NULL, '9781399711678', 'For as long as she can remember, Evangeline Fox has believed in true love and happy endings . . . until she learns that the love of her life will marry another. Desperate to stop the wedding and to heal her wounded heart, Evangeline strikes a deal with the charismatic, but wicked, Prince of Hearts. In exchange for his help, he asks for three kisses, to be given at the time and place of his choosing. But after Evangeline’s first promised kiss, she learns that bargaining with an immortal is a dangerous game — and that the Prince of Hearts wants far more from her than she’d pledged. He has plans for Evangeline, plans that will either end in the greatest happily ever after, or the most exquisite tragedy.', '28.9.2021', 'Hodder', ARRAY['Englisch']::text[], 403, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Magnificent North', '{}', ARRAY['Evangeline Fox','Jacks']::text[], '{}', '{}', '7dce3d92-d28d-5184-8080-c44e785d8b69', '1', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
