insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('714b3b65-1039-544e-a7eb-3d2617bf9bca', 'Caraval', NULL, NULL, 'Scarlett has never left the tiny isle of Trisda, pining from afar for the wonder of Caraval, a once-a-year week-long performance where the audience participates in the show. Caraval is Magic. Mystery. Adventure. And for Scarlett and her beloved sister, Tella, it represents freedom and an escape from their ruthless, abusive father. When the sisters'' long-awaited invitations to Caraval finally arrive, it seems their dreams have come true. But no sooner have they arrived than Tella vanishes, kidnapped by the show''s mastermind organiser, Legend. Scarlett has been told that everything that happens during Caraval is only an elaborate performance. But nonetheless she quickly becomes enmeshed in a dangerous game of love, magic, and heartbreak. And real or not, she must find Tella before the game is over, and her sister disappears forever.', '20.03.2017', 'MacMillan', ARRAY['Englisch']::text[], 300, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], NULL, 'Vergangenheit'::time_period, 'Trisda', '{}', ARRAY['Scarlett','Tella']::text[], '{}', '{}', '03860869-7de9-5e2f-ba6b-7ccc688d9b1e', '1', '{}', 'sheet', :'owner') on conflict do nothing;
