insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ccede0e0-1652-5345-86f6-f93550e0bf9e', 'A Curse for True Love', NULL, '9781250324061', 'Evangeline Fox ventured to the Magnificent North in search of her happy ending, and it seems as if she has it. She’s married to a handsome prince and lives in a legendary castle. But Evangeline has no idea of the devastating price she’s paid for this fairytale. She doesn’t know what she has lost, and her husband is determined to make sure she never finds out. . . . but first he must kill Jacks, the Prince of Hearts.', '24.10.2023', 'Flatiron Books', ARRAY['Englisch']::text[], 381, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Magnificent North', '{}', ARRAY['Evangeline Fox','Jacks']::text[], '{}', '{}', '7dce3d92-d28d-5184-8080-c44e785d8b69', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
