insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6d4824f2-6184-595c-95e3-f729addf0031', 'Eine wunderbare Zeit zu leben', 'My Brief History. Black Holes and Baby Universes and Other Essays. The Grand Design. Information Preservation and Weather Forecasting for Black Holes', NULL, 'Stephen Hawking ist der berühmteste Wissenschaftler unserer Zeit. Ein Meister der eleganten Vereinfachung, der Mann, der Astrophysik und Kosmologie weltweit populär gemacht hat. Dieses kleine Lesebuch, zusammengestellt aus Anlass des 75. Geburtstages, präsentiert in Selbstzeugnissen den privaten Stephen Hawking — Kindheit, Studium, Karrierebeginn und das Leben mit ALS – und sein wissenschaftliches Credo in ausgewählten Texten. Es ist für alle gedacht, die sich wichtige Stationen in Leben und Werk des großen Physikers noch einmal vor Augen führen oder anhand von einigen seiner Texte Zugang finden möchten zu Stephen Hawkings Universum. Woher kommen wir? Wer sind wir? Wohin gehen wir? – Menschheitsfragen, die uns alle beschäftigen, Fragen nach dem Sinn und dem Ziel des Lebens. Für die Welt der Physik, der Kosmologie, hat Stephen Hawking sein eigenes Bild dazu entworfen.', '16.12.2016', 'Rowohlt', ARRAY['Deutsch']::text[], 144, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Wissenschaft', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
