insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a0b4f549-0d3d-5fbf-8941-885812ebda5c', 'Eine kurze Geschichte der Zeit', 'A Brief History of Time: From the Big Bang to Black Holes', NULL, 'Seit Stephen Hawking ist das Universum ein anderes: Es gibt eine Zeit vor ihm und nach ihm, denn er hat die Astronomie und unser Verständnis für das Rätsel des Universums revolutioniert. Mit »Eine kurze Geschichte der Zeit« gelang Stephen Hawking ein Meilenstein des Sachbuchs und ein weltweites Phänomen: Es wurde in vierzig Sprachen übersetzt und über elf Millionen Mal verkauft. Wenn wir nachts den Sternenhimmel beobachten, tun wir etwas, was die Menschheit von Anfang an erstaunt und begeistert hat. Nachgelassen hat diese Faszination nie. Niemand dürfte unser Wissen über das Weltall, die Schwerkraft und über Raum und Zeit so umfassend erweitert, so sehr vertieft haben wie Stephen Hawking. Sein ganzes Leben war er auf der Suche danach, das Rätsel des Universums zu lösen: Dieses Geheimnis aufzuheben, gelingt ihm mit seinem epochemachenden Buch »Eine kurze Geschichte der Zeit«. Das weltweit bestverkaufteste Sachbuch der letzten Jahrzehnte macht anspruchsvolle physikalische und astronomische Zusammenhänge anschaulich und eröffnet ein völlig neues Verständnis unseres Universums. Er reist mit uns an den Rand des Kosmos, in die unendlichen Weiten, an die Ereignishorizonte der Schwarzen Löcher und darüber hinaus in das immer weiter expandierende Weltall – ein einmaliges, ein unvergessliches Leseerlebnis.', '04.11.2023', 'Rowohlt', ARRAY['Deutsch']::text[], 272, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Wissenschaft', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('01511712-8d68-523d-9362-fc0a0a730fdf', :'owner', 'a0b4f549-0d3d-5fbf-8941-885812ebda5c', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1299, NULL, NULL, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0351c708-6679-5bc6-b75e-3e8228844e56', 'Erhebung', 'Elevation', NULL, 'Scott nimmt rasend schnell ab. Sein korpulentes Aussehen ändert sich trotzdem nicht. Und noch unheimlicher: Wenn er auf die Waage steigt, zeigt sie jeweils das gleiche Gewicht an, egal wie viel er momentan trägt, ob Kleidung oder gar Hanteln. Scott hat Angst, dass man ihn zum medizinischen Versuchskaninchen macht. Aber er muss es jemand erzählen. Zu Dr. Ellis hat er Vertrauen, aber auch der weiß keinen Rat. In seiner netten Wohngegend in der Kleinstadt Castle Rock gerät Scott in einen eskalierenden Kleinkrieg. Der Hund der neuen Nachbarn - zwei Lesben - verrichtet sein Geschäft ständig bei ihm im Vorgarten. Die eine Frau ist eigentlich recht freundlich, die andere aber eiskalt. Die beiden haben gerade ein Restaurant eröffnet, von dem sie sich viel erhoffen. Die Einwohner von Castle Rock wollen aber nichts mit Homopaaren zu tun haben, da ist großer Ärger vorprogrammiert. Als Scott endlich kapiert, was Vorurteile in einer Gemeinschaft anrichten, überwindet er den eigenen Groll und tut sich mit den beiden zusammen. Merkwürdige Allianzen, der jährliche Stadtlauf und Scotts mysteriöses Leiden fördern bei sich und anderen eine Menschlichkeit zutage, die zuvor unter einer herzlosen Bequemlichkeit vergraben lag.', '12.11.2018', 'Heyne', ARRAY['Deutsch']::text[], 144, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, NULL, 'Castle Rock', '{}', ARRAY['Scott']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
