insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('618d4670-7f8a-58ca-b404-605c4bfb88c6', 'Das Institut', 'The Institute', NULL, 'In einer ruhigen Vorortsiedlung von Minneapolis ermorden zwielichtige Eindringlinge lautlos die Eltern von Luke Ellis und verfrachten den betäubten Zwölfjährigen in einen schwarzen SUV. Die ganze Operation dauert keine zwei Minuten. Luke wacht weit entfernt im Institut wieder auf, in einem Zimmer, das wie seines aussieht, nur dass es keine Fenster hat. Und das Institut in Maine beherbergt weitere Kinder, die wie Luke paranormal veranlagt sind: Kalisha, Nick, George, Iris und den zehnjährigen Avery. Sie befinden sich im Vorderbau des Instituts. Luke erfährt, dass andere vor ihnen nach einer Testreihe im »Hinterbau« verschwanden. Und nie zurückkehrten. Je mehr von Lukes neuen Freunden ausquartiert werden, desto verzweifelter wird sein Gedanke an Flucht, damit er Hilfe holen kann. Noch nie zuvor ist jemand aus dem streng abgeschirmten Institut entkommen.', '09.09.2019', 'Heyne', ARRAY['Deutsch']::text[], 768, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Minneapolis, Institut', '{}', ARRAY['Luke Ellis']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
