insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3633a7f5-5bc2-507a-a6ab-689dfc38b7f8', 'Das Mädchen', 'The Girl Who Loved Tom Gordon', '9783426283561', 'Ein Mädchen irrt durch die Wälder, allein, vom Weg abgekommen. Noch hat niemand bemerkt, dass sie verschwunden ist. Nur sie weiß, dass niemand sie hier beschützen kann – vor Hunger und Durst, vor Mücken und wilden Tieren, vor Einsamkeit und Dunkelheit. Vor allem nicht vor dem, was sich in den Wäldern aufgemacht hat, die Neunjährige heimzusuchen …', '14.02.2011', 'Pan', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Apalache-Trail', '{}', ARRAY['Trisha']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
