insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('283ebf85-d174-52e1-ab58-99f9718c0cc7', 'Holly', NULL, '9783453429680', 'Privatermittlerin Holly Gibney steckt in einer Lebenskrise, da erhält sie einen Anruf: »Meine Tochter Bonnie ist vor drei Wochen verschwunden, und die Polizei unternimmt nichts.« Ihre Nachforschungen führen Holly zu einer weit zurückreichenden Liste ungelöster Vermisstenfälle. Alle spielen im Umfeld eines inzwischen emeritierten Ernährungswissenschaftlers mit dem Spitznamen »Mr. Meat«. Holly hat schon gegen grausame Gegner bestanden, aber hier begegnet sie dem schlimmsten aller Ungeheuer: dem Menschen in seinem Wahn.', '13.11.2024', 'Heyne', ARRAY['Deutsch']::text[], 656, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Thriller', ARRAY['Mystery']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Holly Gibney']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
