insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('bc665cde-aadf-50cf-aabd-d31cebfd19de', 'Carrie', NULL, '9783404180066', 'Als 3-jährige lässt sie einen Steinregen auf ihr Elternhaus niederregnen, weil ihre Mutter ihr in einem Anfall religiösem Wahns nach dem Leben trachtet. Als 16-jährige erlebt sie einen Augenblick tiefster Demütigung. Dann, auf dem Abschlussball der Schule, wird sie das Opfer eines bösen Streichs. Schmerz, Enttäuschung, Wut treiben sie zum Äußersten: Mit der schieren Kraft ihres Willens entfesselt sie ein Inferno, gegen das die Hölle der Garten Eden ist.', '1974', 'Lübbe', ARRAY['Deutsch']::text[], 304, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Psycho Horror']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Carrie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
