insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5512926a-0061-5052-87bd-eef0061eb0ea', 'Different Seasons', NULL, NULL, 'Rita Hayworth and Shawshank Redemption is the story of two men convicted of murder - one guilty, one innocent - who form the perfect partnership as they dream up a scheme to escape from prison. In Apt Pupil a golden schoolboy entices an old man with a past to join in a dreadful union. The Body sees four young boys venture into the woods and find life, death . . . and the end of innocence. The Breathing Method is the tale of a doctor who goes to his club and discovers a woman determined to give birth - no matter what.', '07.06.2012', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 668, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
