insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f2416918-05b0-507c-b808-243df3183868', 'Ihr wollt es dunkler', 'You Like it Darker', '9783453442191', 'Nach einer außerweltlichen Begegnung in den Wäldern von Maine machen zwei Freunde urplötzlich große Karriere; ihr Geheimnis nehmen sie mit in den Tod. Danny träumt von einer Leiche, die er dann tatsächlich findet; in den Augen der Polizei kann nur er der Mörder sein. Vic macht Ferien in Florida, wo er eine verschrobene alte Frau kennenlernt; eine Bekanntschaft, die in einem Horrorstrudel endet. Das sind nur drei von zwölf neuen Storys, die Stephen King in Ihr wollt es dunkler versammelt – viele Genres umspannende Geschichten über das gegenwärtige Amerika, über finstere Mächte und existenzielle Fragen. Seine Erzählsammlungen – zuletzt Zwischen Nacht und Dunkel, Basar der bösen Träume und Blutige Nachrichten – stehen regelmäßig weltweit auf den Bestsellerlisten.', '29.10.2025', 'Heyne', ARRAY['Deutsch']::text[], 734, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['Multiple POV']::text[], '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
