insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c2b29a0e-e3ce-5219-ae47-ad8762dd2c42', 'Nightmares & Dreamscapes', NULL, NULL, 'The Stephen King Amusement Park - an unnerving experience, with rides every which way to hell . . . and a few to glory. A solitary finger pokes out of a drain. Novelty teeth turn predatory. The Nevada desert swallows a Cadillac. Meanwhile, the legend of Castle Rock returns . . . and grows on you. What does it all mean? What else could it mean? Stephen King is here with a powerful collection of stories - a vast, many-chambered cave of a volume. The long reach of Stephen King''s imagination will take you on a roller coaster to places you''ve never been before. You will lose sleep. But Stephen King, writing to beat the devil, will do your dreaming for you.', '2006', NULL, ARRAY['Englisch']::text[], 1072, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Paranormal']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
