insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('092d363a-139d-573f-ae6b-16d52c352708', 'Seelen - Glaube, Kämpfe, Liebe', 'The Host', '9783551581907', 'Planet Erde, irgendwann in der Zukunft. Sogenannte Seelen haben sich in den Körpern der Menschen eingenistet und ihre Kontrolle übernommen. Als die Rebellin Melanie von der Seele Wanda in Besitz genommen wird, setzt sie alles daran, nicht aus ihrem Körper verdrängt zu werden. Denn Melanie hat ein Ziel: Sie will ihren Geliebten Jared wieder­finden. Melanies Gefühle sind so stark, dass Wanda immer mehr in ihren Bann gerät und sich aufmacht einen Mann zu suchen, den sie nicht kennt. Und den sie dennoch zu lieben scheint, mit Körper, Geist und Seele …', '14.08.2008', 'Carlsen', ARRAY['Deutsch']::text[], 912, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Wanda','Melanie']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
