insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4e9064e9-10a6-5c03-9a42-1fa95a5bc297', 'Biss zum ersten Sonnenstrahl - Das kurze zweite Leben der Bree Tanner', 'Bree Tanner – The Short Second Life of Bree Tanner', '9783551582003', 'An ihr erstes Leben kann Bree sich kaum erinnern. Was jetzt zählt, sind ihre übermenschlichen Kräfte und der unstillbare Durst nach Blut – denn Bree ist ein Vampir. Und sie hält sich an die Regeln: Sei wachsam, bleib im Hintergrund, kehre immer vor Sonnenaufgang zurück ins Dunkel. Doch dann erfährt Bree, dass ihr neues Leben auf einer Lüge beruht. Dass sie Teil eines Spiels ist, dessen Dimensionen sie nicht mal ahnen kann. Und dass sie niemandem trauen kann. Außer – vielleicht – Diego.', '12.06.2010', 'Carlsen', ARRAY['Deutsch']::text[], 208, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Seattle', '{}', ARRAY['Bree Tanner']::text[], '{}', '{}', NULL, NULL, ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
