insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b1366f85-129c-5c13-abb9-853c5c36ebad', 'Biss zum Morgengrauen', 'Twilight', '9783551356901', 'Als die 17-jährige Bella Swan aus dem sonnigen Phoenix ins regnerische Forks zieht, erwartet sie wenig von der beschaulichen Kleinstadt. Doch dann trifft sie Edward Cullen, einen Mitschüler mit faszinierend blassen Augen und einer Aura, die Bella sofort in ihren Bann zieht. Edward ist geheimnisvoll, zurückhaltend, unglaublich attraktiv – und ein Vampir! Bella kann nicht anders: Sie fühlt sich trotz – oder vielleicht gerade wegen – seiner dunklen Geheimnisse zu ihm hingezogen. Doch was bedeutet es, als Mensch einen Vampir zu lieben?', '24.01.2008', 'Carlsen', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Forks', '{}', ARRAY['Bella Swan','Edward Cullen','Jacob Black']::text[], '{}', '{}', '75cada6f-d36b-523c-9037-09c3fd861b62', '1', '{}', 'sheet', :'owner') on conflict do nothing;
