insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5817e035-76ac-5017-b5a8-f4ff2ee12a16', 'Midnight Sun', NULL, '9780349003634', 'This unforgettable tale as told through Edward''s eyes takes on a new and decidedly dark twist. Meeting Bella is both the most unnerving and intriguing event he has experienced in all his years as a vampire. As we learn more fascinating details about Edward''s past and the complexity of his inner thoughts, we understand why this is the defining struggle of his life. How can he justify following his heart if it means leading Bella into danger?', '04.08.2020', 'Little, Brown Books', ARRAY['Englisch']::text[], 756, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Forks', '{}', ARRAY['Edward Cullen','Bella Swan']::text[], '{}', '{}', NULL, NULL, ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
