insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0af398c7-bf92-5337-b745-7bd986631d2c', 'Biss zur Mittagsstunde', 'New Moon', '9783551357823', 'Für immer mit Edward zusammen zu sein – Bellas Traum scheint wahr geworden! Doch nach einem kleinen, aber blutigen Zwischenfall findet er ein jähes Ende. Edward muss sie verlassen. Für immer. Bella zerbricht beinahe daran, nur die Freundschaft zu Jacob gibt ihr Kraft. Da erfährt Bella, dass Edward in höchster Gefahr schwebt. Sie muss zu ihm, rechtzeitig, bis zur Mittagsstunde.', '13.02.2009', 'Carlsen', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Forks', '{}', ARRAY['Bella Swan','Edward Cullen','Jacob Black']::text[], '{}', '{}', '75cada6f-d36b-523c-9037-09c3fd861b62', '2', '{}', 'sheet', :'owner') on conflict do nothing;
