insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dad03d71-ff77-5242-ace4-e20893bf5d81', 'Biss zum Abendrot', 'Eclipse', '9783551581662', 'Bellas Leben ist in Gefahr. Ein offensichtlich blutrünstiger Vampir sinnt auf Rache. Und seine Spuren führen zu Bella. Aber damit nicht genug: Nachdem sie wieder mit Edward zusammen ist, muss sie sich zwischen ihrer Liebe zu ihm und ihrer Freundschaft mit Jacob entscheiden – doch damit könnte sie den uralten Kampf zwischen Vampiren und Werwölfen neu entfachen.', '22.02.2008', 'Carlsen', ARRAY['Deutsch']::text[], 640, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Forks', '{}', ARRAY['Bella Swan','Edward Cullen','Jacob Black']::text[], '{}', '{}', '75cada6f-d36b-523c-9037-09c3fd861b62', '3', '{}', 'sheet', :'owner') on conflict do nothing;
