insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a0a9cad1-198d-5786-b112-8a46cf970a23', 'Biss zum Ende der Nacht', 'Breaking Dawn', '9783551581990', 'Ein Jahr voller Glück, aber auch voller Schmerz liegt hinter Bella. Ein Jahr, in dem sie fast zerbrochen wäre, weil ihre Leidenschaft für Edward und ihre innige Freundschaft zu Jacob einfach unvereinbar sind. Aber nun ist ihre Entscheidung gefallen. Unwiderruflich. Auch wenn sie für alle verheerende Folgen haben könnte.', '17.02.2009', 'Carlsen', ARRAY['Deutsch']::text[], 800, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Forks', '{}', ARRAY['Bella Swan','Edward Cullen','Jacob Black']::text[], '{}', '{}', '75cada6f-d36b-523c-9037-09c3fd861b62', '4', '{}', 'sheet', :'owner') on conflict do nothing;
