insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d2ddfda4-af69-5818-942e-abf4ceb918a6', 'Als die Sonne im Meer verschwand', 'The Blue Between Sky and Water', '9783453291706', 'In einem malerischen Dorf in Palästina wachsen die Geschwister der Familie Baraka auf. Doch an einem Tag im Jahr 1948 geht ihre Kindheit jäh zu Ende. Israelische Soldaten stecken ihr Haus in Brand und zwingen sie gewaltsam zur Flucht. Nazmiyya versucht, dem Leid der Flüchtlingslager zu trotzen, Mamduh zieht bis ans andere Ende der Welt. Sie verlieren ihre Familie, ihre Heimat und einander – nie aber die Hoffnung. Und Hoffnung ist es auch, die sechzig Jahre später Mamduhs Enkelin aus Amerika nach Gaza führt …', '18.05.2015', 'Penguin Random House', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Historische Romane', ARRAY['Drama']::text[], 'Adult'::audience_kind, NULL, 'Gaza', '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
