insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('57caba31-62d7-51dd-a97d-018090942fd7', 'The Romance Rivalry', NULL, '9783736325081', 'Irene Park liebt Romance-Bücher - so sehr, dass sie sie zu ihrem Beruf machen will. Sie studiert nicht nur Literaturwissenschaft am Brighton College, sondern begeistert als erfolgreiche Buchbloggerin online Hunderttausende Follower:innen. Doch während sie täglich über große Gefühle schreibt, bleibt ihr eigenes Liebesleben auf der Strecke. Also beschließt Irene, die Sache endlich selbst in die Hand zu nehmen und die wahre Liebe mithilfe dessen zu finden, was sie am besten kennt: Romance Book Tropes. Immerhin ist ihr Kandidat fürs Fake Dating mit Aiden Jeon, ihrem stärksten Rivalen - am Campus und unter den Buchblogger:innen -, schnell gefunden. Was für Irene jedoch als lästiges Abhaken ihres unbeliebtesten Tropes beginnt, fühlt sich bald schon verdächtig nach einem Happy End an ...', '27.04.2026', 'LYX', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, 'Brighton College', '{}', ARRAY['Irene Park','Aiden Jeon']::text[], ARRAY['Fake Dating','Universicy/College','Rivals to Lovers']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
