insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fc4776b8-a532-57a8-9066-90005a06d6f0', 'Seoulmates - Always have and always will', 'Seoulmates', '9783736321205', 'Hannah Cho kann sich wirklich Schöneres vorstellen, als ihre Sommerferien mit Jacob Kim zu verbringen. Seitdem ihr ehemals bester Freund vor drei Jahren von seinem Besuch in Südkorea einfach nicht mehr zurückkam und dort der größte K-Drama-Star der Welt wurde, haben die beiden kein Wort mehr gewechselt. Doch jetzt ist er wieder in San Diego, um eine Pause von seinem Ruhm zu bekommen. Hannah will mit alldem und vor allem Korea nichts zu tun haben. Aber sie kann auch das verräterische Flattern ihres Herzens nicht leugnen, das plötzlich so stark wie nie zuvor ist, seitdem der gut aussehende Schauspieler ihr nicht mehr von der Seite weicht ...', '24.11.2023', 'LYX', ARRAY['Deutsch']::text[], 362, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Hannah Cho','Jacob Kim']::text[], '{}', '{}', '4b0f7334-b894-5d23-a9b5-6f55d6f4d458', '1', '{}', 'sheet', :'owner') on conflict do nothing;
