insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a81efa84-761a-5dd2-b584-ed68540a8692', :'owner', '5dfdda22-28fd-5a84-a5bc-4bb0fb68292e', 'gelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 1799, true, false, '{}', '{}', NULL, NULL, false, 'buddy'::company_kind, 'love'::verdict_kind, 4.0, 'erfuellt'::expectation_kind, 0, 'no'::burn_kind, 'Überraschenderweise haben mich ganz andere Stellen berührt als ich erwartet habe, aber es war wirklich schlimm zuzuschauen, wie Haymitch nach und nach alles verliert was er liebt und was ihn ausmacht. Einfach nur grausam.') on conflict do nothing;
