insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('abaa91f7-05b9-50f5-b3a0-bd2f4bf58945', 'Die Tribute von Panem - Tödliche Spiele', 'The Hunger Games', '9783789132186', 'In den Schatten der dystopischen Welt Panem, wo die Trümmer eines einst blühenden Nordamerikas liegen, wird die sechzehnjährige Katniss Everdeen vor die ultimative Herausforderung gestellt. Als ihre jüngere Schwester Prim für die grausamen Hungerspiele ausgewählt wird, ein brutaler Wettkampf auf Leben und Tod, der jährlich vom tyrannischen Kapitol organisiert wird, tritt Katniss ohne zu zögern an Prims Stelle. Zusammen mit Peeta Mellark, dem männlichen Tribute ihres Distrikts, wird sie in die Arena geworfen, wo die beiden gegen Tributes aus den anderen Distrikten antreten müssen, in einem Kampf, der nur einen Sieger kennt. Katniss und Peeta, gefangen in einem Netz aus Lügen, Liebe und politischen Intrigen, müssen schnell lernen, dass es in den Hungerspielen um weit mehr geht als ums bloße Überleben. Ihre unerwartete Allianz und die aufkeimenden Gefühle füreinander stellen alles in Frage, was sie über Freundschaft, Treue und Liebe zu wissen glaubten. Während sie sich durch die tödlichen Herausforderungen der Arena kämpfen, wird Katniss klar, dass sie nicht nur um ihr eigenes Leben kämpft, sondern auch um die Hoffnung und das Schicksal aller Distrikte Panems.', '01.08.2009', 'Oetinger', ARRAY['Deutsch']::text[], 415, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Panem', '{}', ARRAY['Katniss Everdeen']::text[], '{}', '{}', '336a82eb-821c-5b66-af8a-b6e3739e5738', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('0df3f8a7-70f1-5929-b3ac-1dbd3a769614', 'abaa91f7-05b9-50f5-b3a0-bd2f4bf58945', 'Film') on conflict do nothing;
