insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('71400a89-f95e-533a-943c-abc5caa2f244', 'Die Tribute von Panem - Flammender Zorn', 'Catching Fire', '9783789132209', 'In "Die Tribute von Panem 2. Gefährliche Liebe" von Suzanne Collins setzt sich die fesselnde Geschichte von Katniss Everdeen fort. Nachdem Katniss und Peeta die grausamen Hungerspiele überlebt haben, kehren sie zurück in ihr Heimatdistrikt 12, nur um festzustellen, dass der Schein trügt. Ihr vermeintlicher Sieg entfacht eine Welle des Widerstands gegen das tyrannische Kapitol, und schnell werden sie zu Symbolfiguren der Rebellion. Unter dem Druck des Kapitols müssen sie die Welt davon überzeugen, dass ihre Liebe echt ist, um ihre Familien und Freunde vor grausamen Konsequenzen zu schützen. Doch die Entscheidung zwischen Freiheit und Sicherheit, Leben und Tod, wird Katniss immer schwerer gemacht. Als die 75. Hungerspiele, ein grausames Jubiläum, angekündigt werden, bei dem frühere Gewinner gegeneinander antreten müssen, sieht sich Katniss erneut in der Arena. Diesmal ist der Kampf ums Überleben noch erbitterter, denn es steht mehr auf dem Spiel als jemals zuvor. Collins schafft es erneut, den Leser mit einer Mischung aus Spannung, Emotionen und tiefgründigen Charakteren in ihren Bann zu ziehen, in einer Welt, in der die Grenzen zwischen Gut und Böse verschwimmen.', '20.01.2011', 'Oetinger', ARRAY['Deutsch']::text[], 428, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Panem', '{}', ARRAY['Katniss Everdeen']::text[], '{}', '{}', '336a82eb-821c-5b66-af8a-b6e3739e5738', '2', '{}', 'sheet', :'owner') on conflict do nothing;
insert into adaptations (id, book_id, kind) values ('b5e4d40c-2b93-53b0-b2bb-aaf7374b8925', '71400a89-f95e-533a-943c-abc5caa2f244', 'Film') on conflict do nothing;
