insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3b2dc70b-502d-56f1-b110-6214a2984e09', 'Die Tribute von Panem - Gefährliche Liebe', 'Mockingjay', '9783789132193', 'In "Die Tribute von Panem 3. Flammender Zorn" erreicht Suzanne Collins'' dystopische Trilogie ihren dramatischen Höhepunkt. Nachdem Katniss Everdeen die Hungerspiele zum zweiten Mal überlebt hat, findet sie sich in Distrikt 13 wieder, dem Herzen des Widerstands gegen das tyrannische Kapitol. Während das Kapitol nach Rache dürstet, werden die Auseinandersetzungen blutiger, und Katniss muss erkennen, dass auch die Rebellen sie nur als Figur in ihrem Kampf sehen. Zwischen persönlichen Verlusten, inneren Konflikten und der schweren Last als Symbolfigur des Aufstands, dem Spotttölpel, zu dienen, muss Katniss entscheiden, wie weit sie gehen will, um zu kämpfen. Collins webt eine Geschichte von Macht, Verrat und der Suche nach Gerechtigkeit, die nicht nur die dunklen Seiten des Krieges beleuchtet, sondern auch tiefe menschliche Emotionen erforscht.', '19.05.2010', 'Oetinger', ARRAY['Deutsch']::text[], 431, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, 'Panem', '{}', ARRAY['Katniss Everdeen']::text[], '{}', '{}', '336a82eb-821c-5b66-af8a-b6e3739e5738', '3', '{}', 'sheet', :'owner') on conflict do nothing;
