insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a249af5b-21a9-5f18-b05c-125c217a6003', 'Heartbeat, again', NULL, '9782889510047', 'Nara lebt für seinen Beruf als Oberstufenlehrer. Die eigenen Gefühle aus dem Unterricht herauszuhalten und professionelle Distanz zu wahren, ist für ihn selbstverständlich. Davon, dass er schwul ist, wissen noch nicht einmal seine engsten Kollegen, und das soll auch so bleiben. Zu oft wurde er deswegen schon verletzt. Doch dann gesteht ihm einer seiner Schüler auf einem Prüfungsbogen seine Liebe. Als Nara begreift, dass der achtzehnjährige Ikuta aufrichtige Gefühle für ihn hegt, gerät er innerlich ins Wanken …', '03.12.2020', 'Kaze Manga', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Nara','Ikuta']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
