insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('22483d8d-a4e6-5de6-866b-e8de4285bd80', 'Changers - Oryon', NULL, '9783440148570', 'Bei ihrer zweiten Veränderung wacht die 15-jährige Drew als Junge auf. Drew ist jetzt Oryon, ein cooler afro-amerikanischer Skatertyp. Gerade, als sie sich an ihre weibliche Identität gewöhnt hatte! Doch so ist das Leben für einen Changer, eine alte Menschenart, deren Angehörige jedes Highschooljahr als eine andere Person existieren müssen. Bis zum nächsten Sommer wird Oryon lernen, wie sehr die Welt um ihn herum versucht, ihn in das zu verändern, was sie in ihm sieht – und dass er nur er selbst sein kann, wenn er sich dem widersetzt.', '08.09.2015', 'Kosmos', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Oryon','Audrey']::text[], '{}', '{}', 'b9ccedfb-921a-52cb-b582-8f405f700c37', '2', '{}', 'sheet', :'owner') on conflict do nothing;
