insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('afd5868b-adf1-5933-ab80-824043c1cf1e', 'Changers - Kim', NULL, '9783440152140', 'Ein neues Schuljahr bringt Oryon eine neue, diesmal wieder weibliche Identität: Er verwandelt sich in Kim, ein 16-jahriges asiatisches Mädchen. Mit ihrem Übergewicht und ihrem burschikosen Auftreten ist Kim in der Schule eine Außenseiterin. Vergeblich versucht sie, Audreys Aufmerksamkeit zu gewinnen. In einer einsamen, betrunkenen Nacht schreibt Kim an Audrey einen Brief, in dem sie ihr alles über die Changers und ihre verschiedenen Identitäten – Drew, Oryon, Kim – erzählt. Sie will den Brief nicht abschicken, doch Benedict, der Anführer der RaChas, hat andere Pläne...', '14.09.2016', 'Kosmos', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Kim','Audrey']::text[], '{}', '{}', 'b9ccedfb-921a-52cb-b582-8f405f700c37', '3', '{}', 'sheet', :'owner') on conflict do nothing;
