insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('e3882e40-0a21-594a-bd18-03fcb69d0caa', '9b37fd05-bb1d-5bc7-a39f-3f77b18cfd22', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0ebfd032-6e67-502b-9e17-ce02c45d286c', 'Changers - Drew', NULL, '9783440143629', 'Am ersten Highschooltag erwacht der 14-jährige Ethan plötzlich als junges blondes Mädchen. Seine Eltern erklären ihm, dass er ein „Changer“ ist. Wie sein Vater gehört er einer Gruppe von Menschen an, die sich während ihrer Schulzeit viermal in eine andere Person – Junge oder Mädchen – verwandeln, bevor sie eine feste Identität wählen. Seine erste Identität als „Drew“ ist für Ethan nicht leicht: Sie muss sich mit den Regeln der Changers vertraut machen, verliebt sich und muss für diese Liebe kämpfen. Was werden die Gegner der Changers unternehmen? Und ist die Organisation, die sie unterstützt, wirklich so gut? Die wichtigste Frage aber lautet: Wer wird „Drew“ am Ende sein?', '05.02.2015', 'Kosmos', ARRAY['Deutsch']::text[], 352, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', '{}', 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Drew','Audrey']::text[], '{}', '{}', 'b9ccedfb-921a-52cb-b582-8f405f700c37', '1', '{}', 'sheet', :'owner') on conflict do nothing;
