insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e6fe3760-e48c-55ee-9d99-3887e3a29326', 'Ich fürchte mich nicht', 'Shatter Me', '9783641080549', '„Du darfst mich nicht anfassen“, flüstere ich. Bitte fass mich an, möchte ich in Wahrheit sagen. Aber wenn man mich anfasst, geschieht Seltsames. Schlimmes. Ihr Leben lang war Juliette einsam, eine Ausgestoßene – ein Monster. Ihre Berührung ist tödlich, man fürchtet sie, hat sie weggesperrt. Bis die Machthaber einer fast zerstörten Welt sich ihrer als Waffe bedienen möchten. Doch Juliette beschließt zu kämpfen – gegen die, die sie gefangen halten, gegen sich selbst, das Dunkel in ihr. Für ihre Liebe. Und für den Zauber der Berührung ...', '23.07.2012', 'Goldmann', ARRAY['Deutsch']::text[], 336, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
