insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aa955f61-5aab-5ca3-9a4a-13a068c1049c', 'Rette mich vor dir', 'Unravel Me', '9783641093068', 'Die Schlacht gegen das Reestablishment ist verloren, der Zufluchtsort der Rebellen zerstört, Juliettes Freunde sind in alle Winde zerstreut. Über das Schicksal ihrer großen Liebe Adam ist Juliette im Ungewissen –– ebenso wie über ihre Gefühle für ihn. Die einzige Gewissheit, die sie noch hat: Sie muss das grausame Regime unbedingt besiegen! Doch dazu bleibt ihr nichts anderes übrig, als sich Warner anzuvertrauen, dem einen Menschen, den sie auf ewig zu hassen schwor. Und der ihr das Leben rettete. Jetzt verspricht er, an ihrer Seite zu kämpfen. Doch kann Juliette ihm vertrauen? Und was will er wirklich von ihr?', '30.09.2013', 'Goldmann', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
