insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('06995e4e-8b0b-5c32-bb6c-b34e13ae6c38', 'Vernichte mich', 'Fracture Me', NULL, 'Das Mädchen, das mit nur einer Berührung töten kann, hält nun die Welt in ihrer Hand. Juliette Ferrars dachte, sie hätte gewonnen. Sie hat die Macht in Sektor 45 übernommen und ist zur Obersten Befehlshaberin ernannt worden – und all das mit Warner an ihrer Seite. Doch als das Schicksal sie einholt, muss sie sich der Dunkelheit stellen, die in ihr wütet.', '25.08.2014', 'Goldmann', ARRAY['Deutsch']::text[], 72, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '4', ARRAY['Interquel','Novella']::text[], 'sheet', :'owner') on conflict do nothing;
