insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('18d81d36-a06c-547a-9263-aedf9d2cac93', 'Ich brenne für dich', 'Ignite Me', '9783641120184', 'Juliette Ferrars ist nicht, wer sie bisher glaubte zu sein und nichts ist, wie es scheint. Sie dachte, sie hätte das Reestablishment geschlagen. Sie dachte, sie hätte endlich die Kontrolle über ihr Leben, ihre Macht, ihren Schmerz. Doch als all die Lügen ans Licht kommen, die sie ihr Leben lang geglaubt hat, ändert das alles..Stärker, mutiger und widerstandsfähiger als je zuvor muss Juliette erneut für ihr Leben und ihre Liebe kämpfen. Doch zuerst muss sie sich erinnern, wer sie ist.', '29.09.2014', 'Goldmann', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '5', '{}', 'sheet', :'owner') on conflict do nothing;
