insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7facfa96-6358-51f4-a1ce-c7d233fa032d', 'Imagine Me', NULL, '9781405297042', 'Juliette Ferrars. Ella Sommers. Which is the truth and which is the lie? Now that Ella knows who Juliette is and what she was created for, things have only become more complicated. As she struggles to understand the past that haunts her and looks to a future more uncertain than ever, the lines between right and wrong—between Ella and Juliette—blur. And with old enemies looming, her destiny may not be her own to control.', '31.03.2020', 'HarperCollins', ARRAY['Englisch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '10', '{}', 'sheet', :'owner') on conflict do nothing;
