insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9035cbaf-27ca-5f7f-8be6-555f9ea50978', 'Restore Me', NULL, '9781405291781', 'The girl with the power to kill with a single touch now has the world in the palm of her hand. Juliette Ferrars thought she''d won. She took over Sector 45, was named Supreme Commander, and now has Warner by her side. But when tragedy strikes, she must confront the darkness that dwells both around and inside her.', '06.03.2018', 'HarperCollins', ARRAY['Englisch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Paranormal Romance']::text[], 'YA'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juliette Ferrar','Warner']::text[], '{}', '{}', '05832616-37d0-5b72-b79c-0abc773ee53f', '6', '{}', 'sheet', :'owner') on conflict do nothing;
