insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ba2d0c34-3205-53a2-915d-26005bfe15e9', 'Feenrache', NULL, NULL, 'Jana ist genervt. Die irische Austauschschülerin Cayla soll ein halbes Jahr in ihrer Familie wohnen. Doch wider Erwarten ist Cayla echt nett. Nach und nach gewinnt sie Janas Vertrauen. Dann werden üble Gerüchte über Jana laut, ihre Eltern misstrauen ihr, die Clique wendet sich von ihr ab. Bald fühlt sich Jana vollkommen alleingelassen. Wer treibt hier ein falsches Spiel mit ihr? Und warum?', '01.03.2016', 'Arena', ARRAY['Deutsch']::text[], 280, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jana']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
