insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a0939b71-cea1-5d03-8d3e-9cf8b07dd409', 'Nachtglanz', NULL, '9783453266421', 'Als Adam im Jahr 1889 in einer verlassenen Pariser Gasse erwacht, hat er alle Erinnerung an sein früheres Leben verloren. Nur eines spürt er mit aller Macht: Ein Dämon hat von ihm Besitz ergriffen und unterwirft ihn einem einzigen dunklen Verlangen. Unberechenbar und zerrissen irrt Adam durch die Zeiten – bis die geheimnisvolle junge Esther auftaucht. Die leidenschaftliche Liebe zu ihr gibt Adam seine Menschlichkeit zurück. Doch der Dämon hat eigene Pläne, und diesen steht Esther im Weg. Paris 1889: Seit Adam in einer dunklen Gasse wieder zu sich gekommen ist, weiß er nicht mehr, wer er ist – oder jemals war. Dafür spürt er einen Dämon in sich, der nur ein einziges düsteres Verlangen kennt: Ihn dürstet nach Blut. Vergeblich kämpft Adam gegen den Eindringling, schließlich lässt er sich willenlos von ihm treiben. Bis er plötzlich, mitten im 20. Jahrhundert, Esther begegnet und alles sich verändert. Er entbrennt in leidenschaftlicher Liebe zu der jungen und zerbrechlichen Frau. Doch Esther, die von einer tragischen Vergangenheit gezeichnet ist, erwidert seine Gefühle nur zaghaft: Sie ahnt die dunkle Gefahr, die in Adam lauert. Denn der Dämon sieht in Esther lediglich Beute. Verzweifelt versucht Adam gegen den Dämon und für seine Liebe zu kämpfen. Ein tödliches Ringen um Esther beginnt ...', '13.09.2010', 'Heyne', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Paris', '{}', ARRAY['Adam']::text[], '{}', '{}', 'bc977cd8-593e-5f59-9b9f-9258de4505db', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ffe69e3c-2bf8-5d5c-afed-3f6496bf0eeb', :'owner', 'a0939b71-cea1-5d03-8d3e-9cf8b07dd409', 'ungelesen'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Hardcover']::text[], NULL, '{}', 1799, true, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aeb2b6a3-32cd-5133-b51c-d0618c9b7d41', 'Traumsplitter', NULL, '9783453266124', 'In flirrend heißen Sommernächten beginnt die junge Ella von Gabriel zu träumen. Vom ersten Moment an fühlte sie sich von dem umwerfend charmanten Mann, der plötzlich vor ihrer Tür stand, wie magisch angezogen. Doch dann entdeckt Ella, dass Gabriel tatsächlich den Weg in ihre Träume kennt. Eine gefährliche Gabe mit einem hohen Preis, der sie beide in den Abgrund stürzen könnte. So hatte sich die junge Ella Johansen ihre Rückkehr ins Hafenstädtchen Sandfern nicht vorgestellt: die ehemals prächtige Villa der verstorbenen Tante ist heruntergekommen, der traumhafte Garten verwildert. Zudem nistet sich ihr Neffe Kimi bei ihr ein, der ganz und gar nicht mehr so süß und schüchtern wie in ihrer Erinnerung ist. Aber Ella ist fest entschlossen, zu bleiben und als Fotografin Fuß zu fassen. Der Sommer ihres Lebens beginnt in dem Moment, als ein rätselhafter Untermieter in die Villa zieht: Gabriel ist umwerfend schön und charmant; Ella fühlt sich trotz seiner Geheimnisse sofort zu ihm hingezogen. In den flirrend heißen Sommernächten beginnt sie, von ihm zu träumen. Doch dann findet sie heraus, dass Gabriel tatsächlich den Weg in ihre Träume kennt – und einen hohen Preis für seine gefährliche Gabe zahlen muss. Mit jedem Besuch in ihren Träumen riskiert er mehr, sich selbst auf der anderen Seite der Nacht zu verlieren. Plötzlich verwandelt sich der Boden unter Ellas Füßen in brüchiges Glas, und sie droht mit Gabriel in einen Abgrund zu stürzen.', '17.10.2011', 'Heyne', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Sandfern', '{}', ARRAY['Ella Johansen','Gabriel']::text[], '{}', '{}', 'bc977cd8-593e-5f59-9b9f-9258de4505db', '4', '{}', 'sheet', :'owner') on conflict do nothing;
