insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d2751ac6-fb52-5a0d-9943-47c8d1d12425', 'The Seven Husbands of Evelyn Hugo', NULL, '9781398515697', 'Aging and reclusive Hollywood movie icon Evelyn Hugo is finally ready to tell the truth about her glamorous and scandalous life. But when she chooses unknown magazine reporter Monique Grant for the job, no one is more astounded than Monique herself. Why her? Why now? Monique is not exactly on top of the world. Her husband has left her, and her professional life is going nowhere. Regardless of why Evelyn has selected her to write her biography, Monique is determined to use this opportunity to jumpstart her career.Summoned to Evelyn’s luxurious apartment, Monique listens in fascination as the actress tells her story. From making her way to Los Angeles in the 1950s to her decision to leave show business in the ''80s, and, of course, the seven husbands along the way, Evelyn unspools a tale of ruthless ambition, unexpected friendship, and a great forbidden love. Monique begins to feel a very real connection to the legendary star, but as Evelyn’s story near its conclusion, it becomes clear that her life intersects with Monique’s own in tragic and irreversible ways.', '14.10.2021', 'Simon & Schuster', ARRAY['Englisch']::text[], 385, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Evelyn Hugo']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('24950d1e-1133-5280-ae17-1e2789b9a77a', :'owner', 'd2751ac6-fb52-5a0d-9943-47c8d1d12425', 'tbr'::reading_status, true, true, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 798, NULL, NULL, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f6570837-53cd-5b95-98a6-5fc51cccf1d9', 'Gelöscht', 'Slated', NULL, 'Kylas Gedächtnis wurde gelöscht, ihre Persönlichkeit ausradiert, ihre Erinnerungen sind für immer verloren. Kyla wurde »geslated«. Aber die Stimmen aus der Vergangenheit lassen die Sechzehnjährige nicht los – hat sie wirklich unschuldige Kinder bei einem Bombenanschlag getötet? Zählte sie zu einer Gruppe von gefährlichen Terroristen? Und warum steht ein Bild von ihr auf einer geheimen Webseite mit vermissten Kindern? Kyla wird immer wieder von Flashbacks aus ihrem früheren Leben eingeholt und merkt allmählich, dass ihre wahre Identität ein großes Geheimnis birgt. Gemeinsam mit Ben, einem anderen Slater, in den sie sich verliebt, begibt sie sich auf die Suche nach der Wahrheit – doch wem kann sie überhaupt noch vertrauen?', '01.06.2013', 'Coppenrath', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Kyla']::text[], '{}', '{}', '20ea91c9-cb91-58ec-851d-bab4246f1a9a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
