insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('12067b0e-a098-5cda-b00e-be6834564b83', 'Mind Games', NULL, NULL, 'Die Welt, in der du lebst, existiert nur in deinem Kopf – doch was, wenn jemand mit deinen Gedanken spielt? In Lunas Leben ist jeder online: virtueller Unterricht, Dates und Sport als Avatar, sogar das Parlament tagt digital. Nur Luna bleibt offline. Sie ist eine Verweigerin, seit ihre Mutter vor Jahren in einem Online-Spiel starb. Umso überraschter ist Luna, als sie von der mächtigen Firma PareCo zu einem Einstufungstest eingeladen wird – und einen der begehrten Programmierer-Jobs erhält. Warum hat die Firma so ein großes Interesse an ihr? Als Luna den begabten Hacker Gecko kennenlernt, beginnt sie die von PareCo erschaffene Welt immer mehr zu hinterfragen. Doch dann ist Gecko auf einmal verschwunden, und Luna kann sich nicht mehr an ihn erinnern …', '01.06.2015', 'Coppenrath', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Luna']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
