insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d1c3ef5-6644-5c4e-86b5-c5fe7ab35f79', 'Zersplittert', 'Fractured', NULL, 'Kylas Gedächtnis wurde gelöscht, ihre Persönlichkeit ausradiert, ihre Erinnerungen sind für immer verloren. Denkt sie. Doch als Kyla angegriffen wird, tauchen schlagartig Erinnerungsfetzen auf. Trotzdem bleibt für die Sechzehnjährige vieles rätselhaft: Wer ist das Mädchen, das in ihren Albträumen auftaucht? Und welche Rolle hat sie bei der Untergrundorganisation Free UK gespielt? Als Free UK erneut an sie herantritt, wird Kyla immer mehr zum Spielball zwischen Terroristen und Überwachungsstaat …', '01.01.2014', 'Coppenrath', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Kyla']::text[], '{}', '{}', '20ea91c9-cb91-58ec-851d-bab4246f1a9a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
