insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b32366b0-231b-5e34-a985-ddcbcd70dcb2', 'Bezwungen', 'Shattered', NULL, 'Kylas Gedächtnis wurde gelöscht, ihre Persönlichkeit ausradiert, ihre Erinnerungen sind für immer verloren. Denn sie hat ein Verbrechen begangen. Denkt sie. Als Kyla einem hinterhältigen Anschlag nur knapp entkommt, weiß sie, dass sie nirgends mehr in Sicherheit ist. Es bleibt ihr nichts anderes übrig, als sich eine neue Identität zuzulegen und unterzutauchen. Doch die ungeklärten Fragen über ihre Vergangenheit lassen sie nicht los. Als Kyla endlich ihre Mutter kennenlernt, erfährt sie, wer sie als Kind wirklich war und kommt hinter das dunkelste Geheimnis ihrer Familiengeschichte ...', '01.09.2014', 'Coppenrath', ARRAY['Deutsch']::text[], 376, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, NULL, NULL, '{}', ARRAY['Kyla']::text[], '{}', '{}', '20ea91c9-cb91-58ec-851d-bab4246f1a9a', '3', '{}', 'sheet', :'owner') on conflict do nothing;
