insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('65e00847-1d4c-5a71-b095-7329d5a00500', 'In Case We Trust', 'In Case We Lie', '9783736320499', 'Nach dem Jurastudium will sich Gracie endlich als Anwältin bei Gold, Bright & Partners, einer der erfolgreichsten Kanzleien Bostons, beweisen. Aber der Konkurrenzkampf unter den jungen Anwält:innen ist härter als gedacht. Ihr größter Rivale in der Gruppe von ehrgeizigen Anfänger:innen ist der attraktive Ira, der zu allem Überfluss auch noch auf denselben Fall angesetzt wird. Trotz ihres schlechten Starts kommen sich die beiden bei spätabendlichen Recherchearbeiten schon bald immer näher. Doch Gracie verbirgt ein Geheimnis, das ihre Karriere gefährden könnte - und Ira als ihr größter Konkurrent auf keinen Fall erfahren darf ...', '22.12.2023', 'LYX', ARRAY['Deutsch']::text[], 491, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Boston, Kanzlei "Gold, Bright & Partners"', '{}', ARRAY['Gracie','Ira']::text[], '{}', '{}', '3220eb81-72ec-5fd7-8331-e1478d399db6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
