insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1d165c27-d5bc-556e-8c31-92c9a89b9997', 'In Case We Dare', 'In Case we Trust', '9783736321311', 'Für ihren Neustart in Boston will Laurel ihre Vergangenheit hinter sich lassen und sich ganz auf ihre Karriere konzentrieren. Voller Elan stürzt sie sich in die Arbeit als Anwältin bei »Gold, Bright & Partners«. Als ihr ein neuer Mentor zugewiesen wird, gerät dieser Vorsatz plötzlich ins Wanken. Aaron Bates ist das Wunderkind der Kanzlei, jüngster Juniorpartner und zudem unbestreitbar attraktiv. Zunächst hält Laurel ihn für das Klischee des arroganten Anwalts, aber als sie einen Blick hinter seine Fassade wirft, entdeckt sie so viel mehr - und bisher ungeahnte Gefühle. Doch Aaron ist ihr Boss und eine Beziehung mit ihm strengstens verboten ...', '25.10.2024', 'LYX', ARRAY['Deutsch']::text[], 524, 35, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Boston, Kanzlei "Gold, Bright & Partners"', '{}', ARRAY['Laurel','Aaron Bates']::text[], '{}', '{}', '3220eb81-72ec-5fd7-8331-e1478d399db6', '2', ARRAY['Sequel']::text[], 'sheet', :'owner') on conflict do nothing;
