insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b9edff6c-05f3-54c3-82eb-b24f09d672e1', 'The Hurricane Wars', NULL, '9783736322516', 'Talasyn ist ein Findelkind und kannte bisher nur den alles verzehrenden Krieg gegen das Nachtimperium. Als einzige noch lebende Lichtweberin kämpft sie mit ihrer Magie an vorderster Front. Eines Tages kreuzt sich ihre Klinge mit der von Alaric, dem Kronprinzen des Nachtimperiums. Obwohl sie erbitterte Feinde sind, springt ein Funke zwischen ihnen über und beide schrecken vor dem letzten tödlichen Schlag zurück. Bald wird klar, dass Talasyns Schicksal mit dem von Alaric verwoben ist. Nur, wenn sie ihre magischen Kräfte vereinen, können sie eine nie da gewesene Bedrohung abwenden. Doch wie kann sie sich mit dem Mann verbünden, der ihr so viel Leid gebracht hat - ganz gleich, welche unerwarteten Gefühle er auch in ihr auslöst?', '31.05.2024', 'LYX', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Nachtimperium', '{}', ARRAY['Talasyn','Alaric']::text[], '{}', '{}', '5d8fd823-ef00-5d19-ac09-9313c194a702', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('a71b6eb5-56ef-5c07-b06f-a715236f677a', :'owner', 'b9edff6c-05f3-54c3-82eb-b24f09d672e1', 'tbr'::reading_status, true, false, ARRAY['Digital','Print']::text[], ARRAY['eBook','Hardcover']::text[], 'Normal', '{}', 2400, true, false, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2e1cddd5-55a1-5dd2-9acc-8e2762d25553', 'A Monsoon Rising', NULL, '9783736324527', 'Die Heirat zwischen Talasyn und Alaric sollte den Krieg beenden, der ihr Leben geprägt hat. Doch friedlich ist nichts zwischen ihnen. Denn während Talasyn ihre Rolle als neue Kaiserin von Kesath spielt, planen ihre Verbündeten den Sturz von Alarics Herrschaft. Aber auch wenn sie weiß, dass das Nachtimperium noch immer eine Gefahr darstellt - je mehr Zeit Talasyn mit Alaric verbringt, desto schwerer fällt es ihr, die Gefühle zurückzudrängen, die zwischen ihnen brodeln. Ohne Alaric kann sie den Kataklymus nicht abwenden, der ihrer beider Reiche zerstören würde. Ihm zu vertrauen hieße jedoch, das Schicksal all der Menschen, an deren Seite sie jahrelang gekämpft hat, in seine Hände zu legen.', '27.06.2025', 'LYX', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Nachtimperium', '{}', ARRAY['Talasyn','Alaric']::text[], '{}', '{}', '5d8fd823-ef00-5d19-ac09-9313c194a702', '2', '{}', 'sheet', :'owner') on conflict do nothing;
