insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a0a77483-42b9-5f30-bda5-20134f591810', 'Prinzessin der tausend Diebe - Chosen', NULL, '9783757701918', 'Schreckliches ist geschehen und ganz Korea wird von finsteren Kreaturen in Schutt und Asche gelegt. Jia ist außer sich vor Wut und Trauer. In den Archiven des Hong-Clans findet sie einen Hinweis, wie sie Soras Schicksal rückgängig machen kann. Die dämonenartigen Monster sind ein scheinbar lebendig gewordenes Kunstwerk des Malers Sin Yun-Bok. Um ihre Schwester zu retten, muss Jia ins 18. Jahrhundert reisen, das Gemälde zerstören und danach den Künstler töten. Scheitert sie, ist ganz Korea und ihre Familie dem Untergang geweiht. Zu ihrem Entsetzen muss Jia jedoch feststellen, dass sie zu früh in der Vergangenheit gelandet ist. Aber ein geheimnisvoller Reisender hilft ihr bei ihrem Plan ...', '02.03.2026', 'Lübbe', ARRAY['Deutsch']::text[], 442, 37, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Busan', '{}', ARRAY['Jia','Sora']::text[], ARRAY['The Chosen One','Time Travel','Soul Mates']::text[], ARRAY['Ableismus','Body Horror','Folter','Krankheit','Mord','SVV','Suizidalität','Tod']::text[], 'adfb8bff-0e00-544a-a57f-97afa1d41dcb', '2', '{}', 'sheet', :'owner') on conflict do nothing;
