insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('61992d3b-7ff8-500a-ab30-8316c5168652', 'Prinzessin der tausend Diebe - Betrayed', NULL, '9783751784108', 'Sora ist die rechtmäßige Erbin eines koreanischen Firmenimperiums, das einer Familie gehört, die seit Jahrhunderten über magische Kräfte verfügt und damit zu Reichtum und Macht gelangte: dem Clan der Diebe. Aber sie ist für ihre Familie eine große Enttäuschung, denn sie ist offenbar magielos. Daher lebt sie fernab der glitzernden Metropole Busan auf der Insel Jeju, wo sie ein kleines Café führt und sich um ihre kranke Mutter kümmert. Bis sie eines Tages einen versiegelten Brief mit einer Einladung erhält, der ihr gesamtes Leben auf den Kopf stellt. Sie trifft auf Menschen, die sie nie wiedersehen wollte, und auf einen attraktiven gefangenen Gott, der ihre Hilfe so sehr braucht wie sie seine.', '26.09.2025', 'Lübbe', ARRAY['Deutsch']::text[], 430, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Urban Fantasy']::text[], 'NA'::audience_kind, 'Vergangenheit'::time_period, 'Jeju', '{}', ARRAY['Sora']::text[], ARRAY['The Chosen One','Time Travel','Soul Mates','Forbidden Love']::text[], '{}', 'adfb8bff-0e00-544a-a57f-97afa1d41dcb', '1', '{}', 'sheet', :'owner') on conflict do nothing;
