insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4c8e2be2-9ae0-5cf1-a44a-dabb6f685e07', 'Was bedeutet das alles?', NULL, NULL, 'Thomas Nagels ebenso kurze wie genaue und umfassende Einführung in die Philosophie findet in verständlicher Form Antworten auf die großen Fragen des Lebens: Woher wissen wir etwas? Wie hängen Körper und Geist zusammen? Was bedeuten Wörter? Gibt es Willensfreiheit wirklich? Was ist Recht und was ist Unrecht? Was ist der Tod? Und worin könnte der Sinn des Lebens bestehen?', '01.08.2008', 'Reclam', ARRAY['Deutsch']::text[], 104, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Philosophie', '{}', 'Adult'::audience_kind, 'Unbestimmt'::time_period, NULL, '{}', '{}', '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
