insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f281af19-5154-5f79-9d2c-3fb6775a2f2c', 'Echo', NULL, '9781529331790', 'Travel journalist and mountaineer Nick Grevers awakes from a coma to find that his climbing buddy, Augustin, is missing and presumed dead. Nick''s own injuries are as extensive as they are horrifying. His face wrapped in bandages and unable to speak, Nick claims amnesia - but he remembers everything. He remembers how he and Augustin were mysteriously drawn to the Maudit, a remote and scarcely documented peak in the Swiss Alps. He remembers an ominous sense that they were not alone. He remembers something waiting for them. . . Sam Avery wants to be glad that Nick is alive and coming home, but the accident has stirred up memories that Sam thought were long buried. Soon he realizes that it isn''t just the trauma of the accident that haunts Nick. Something has awakened inside of him, something that endangers the lives of everyone around him . . .', '13.10.2022', 'Hodderscrabe', ARRAY['Englisch']::text[], 417, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Horror', ARRAY['Thriller (K)']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Maudit, Switzerland', '{}', ARRAY['Nick Grevers','Sam Avery']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
