insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6c7a7b89-1cdc-5758-8c20-9f0e253502c2', 'Reptilia', NULL, NULL, 'Als der junge Genforscher David Astbury gebeten wird, an einer Expedition in den Kongo teilzunehmen, ahnt er nicht, dass er in das Abenteuer seines Lebens gerät. Ausgerüstet mit modernster Technik, reist ein Forscherteam zu einem sagenumwobenen See mitten im Dschungel, um dort ein Wesen zu bezwingen, das unbesiegbar scheint. Doch als Preis winkt der Schlüssel zur Unsterblichkeit…', '01.02.2007', 'Knaur', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Kongo', '{}', ARRAY['David Astbury']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
