insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('51ed8096-bc02-5e50-8bed-a1cf5e0b821a', 'Magma', NULL, NULL, 'Ein verschwundener Forscher, mysteriöse Gebilde aus Stein, ein Zeichen am Himmel – die Geologin Ella Jordan steht vor einem Rätsel. Als sie sich zum tiefsten Punkt der Erde hinunterwagt, scheinen die zusammenhanglosen Ereignisse einen schrecklichen Sinn zu ergeben. Aus dem Marianengraben dringen Signale an die Oberfläche, die viel zu regelmäßig sind, um natürlichen Ursprungs zu sein. Mit einem U-Boot tauchen Ella und der Wissenschaftler Konrad Martin zum untersten Bereich des Grabens, der Challenger Tiefe, die die Quelle der Störung zu sein scheint. Dort entdecken sie eine riesige Steinkugel, hart wie Diamant, widerstandsfähig gegenüber allen Messmethoden. Plötzlich werden neue Signale empfangen: zuerst aus der Region des Nordkaps, dann aus Australien bis hinunter zur Antarktis. Ella und Konrad reisen um die ganze Welt und stoßen überall auf dieselben rätselhaften Gebilde aus Stein. Mit einem Mal beginnen sich die Signale aller Kugeln zu synchronisieren, ihre seismischen Wellen erzeugen auf der ganzen Welt Erdbeben und Vulkanausbrüche – Ella arbeitet wie besessen an einer Lösung, doch der Countdown läuft …', '01.04.2008', 'Knaur', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Marianengraben', '{}', ARRAY['Ella Jordan']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
