insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f8ab8002-329a-50c0-b35d-579ffca19d3b', 'Das verbotene Eden - Logan und Gwen', NULL, NULL, 'Seit Juna aus dem Land der Frauen geflohen ist – mit einem Mann –, fühlt sich die junge Heilerin Gwen einsam und nichtswürdig. Sie schließt sich einem Spähtrupp an, der durch verlassene U-Bahn-Schächte in die Stadt der Männer vordringen soll. Doch der Einsatz scheitert grausam, und Gwen fällt in die Hände des jungen Kämpfers Logan, der sie als Sklavin verkaufen will. Logan aber hat die Rechnung ohne seine Gefühle gemacht – und setzt damit Ereignisse in Gang, die das Ende beider Welten bedeuten könnten …', '03.09.2012', 'Pan', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Logan','Gwen']::text[], '{}', '{}', '410fbd47-a152-55ab-92ad-f1a65b59ad4f', '2', '{}', 'sheet', :'owner') on conflict do nothing;
