insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('76a55f26-323b-5ce2-8f8e-f231f0a38085', 'Das verbotene Eden - Magda und Ben', NULL, NULL, 'Der Kampf der Geschlechter steuert seinem Höhepunkt entgegen. Als die Frauenarmee immer tiefer ins Herz der Männerstadt vorrückt, treffen ein alter Mann und eine alte Frau aufeinander - und machen eine unglaubliche Entdeckung: Magda, die oberste Heilerin, und Benedikt, der Prior der Abtei, waren vor fünfundsechzig Jahren ein junges Paar, das durch den Virus auseinandergerissen wurde. Inzwischen trennen sie Welten. Ob sie nach all den Jahren noch immer etwas füreinander empfinden? Kann es gelingen, die Zeit zurückzudrehen und den blutigen Konflikt beizulegen? Wenn es eine Kraft gibt, die das möglich macht, so ist es die Liebe.', '01.08.2013', 'Pan', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Magda','Ben']::text[], '{}', '{}', '410fbd47-a152-55ab-92ad-f1a65b59ad4f', '3', '{}', 'sheet', :'owner') on conflict do nothing;
