insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('02b43dbb-7efc-5661-81a7-280ccf968959', 'Valhalla', NULL, NULL, '2015. Spitzbergen – der nördlichste Siedlungspunkt der Menschheit. Eine Welt aus Eis und Schnee, überschattet von vier Monaten Polarnacht. Dort plant Archäologin Hannah Peters, geheimnisvolle Strukturen unter dem arktischen Eis zu untersuchen: Das Abschmelzen der Gletscher hat mutmaßlich Fundamente eines mythischen Nordreiches zutage gefördert. Doch Hannah ist nicht die Erste, die diese Ruinen erkundet ... 1944. Im annektierten Norwegen, fernab jeder Siedlung, reift ein Projekt, das grauenvoller ist als alles, was Menschen je ersonnen haben. Eine biologische Zeitbombe, verborgen unter dem ewigen Eis. Ihr Codename: Valhalla.', '03.03.2014', 'Knaur', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'Adult'::audience_kind, 'Unbestimmt'::time_period, 'Spitzbergen, Norwegen', '{}', ARRAY['Hannah Peters']::text[], '{}', '{}', 'f3be33f3-2d11-5ca9-88ae-6daaca26b90a', '3', '{}', 'sheet', :'owner') on conflict do nothing;
