insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a2c1af7a-1888-5e57-b178-6a0742e3d248', 'Das verbotene Eden - David und Juna', NULL, '9783426283608', 'Die Menschheit steht kurz vor ihrem Ende. Seit den »dunklen Jahren« leben Männer und Frauen in erbitterter Feindschaft. Die Zivilisation ist untergegangen: Während die Männer in den Ruinen der alten Städte hausen, haben die Frauen in der wilden Natur ein neues Leben angefangen. Nichts scheint undenkbarer und gefährlicher in dieser Welt als die Liebe zwischen der 17-jährigen Kriegerin Juna und dem jungen Mönch David. Und doch ist sie der letzte Hoffnungsschimmer …', '22.08.2011', 'Pan', ARRAY['Deutsch']::text[], 464, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Juna','David']::text[], '{}', '{}', '410fbd47-a152-55ab-92ad-f1a65b59ad4f', '1', '{}', 'sheet', :'owner') on conflict do nothing;
