insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a75df38f-f2dc-5828-9cdb-d7787e8b8197', 'The Wall - Erwachen', NULL, NULL, 'Eine Felswand von gigantischen Dimensionen. Eine Gruppe von Menschen gestrandet im Nirgendwo zwischen Raum und Zeit. Wer sind sie? Wie sind sie hierhergekommen? Ist dies eine wissenschaftliche Studie oder ein militärisches Experiment? Jeder von ihnen erinnert sich bruchstückhaft an seine Vergangenheit und scheint ein dunkles Geheimnis mit sich herumzutragen. Ist ihre Anwesenheit am Ende vielleicht kein Zufall? Um das Rätsel zu lösen, müssen sie zusammenarbeiten, doch die Wand wehrt sich. Schon bald merken die Gestrandeten, dass die Umgebung gespickt ist, mit tödlichen Fallen, tückischen Rätseln und mörderischen Kreaturen.', '04.10.2014', NULL, ARRAY['Deutsch']::text[], 102, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '1', '{}', 'sheet', :'owner') on conflict do nothing;
