insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e8d2b5f3-388a-57ec-8483-fb00bdf302f4', 'The Wall - Der Angriff', NULL, NULL, 'Die Wand hat ihr erstes Opfer gefordert. Der Gruppe ist spätestens jetzt bewusst, dass es ums nackte Überleben geht. Der Mangel an Nahrung und Wasser wird allmählich zum Problem. Hinzu kommt, dass weitere Überlebende aufwachen und für Streitigkeiten innerhalb der Gruppe sorgen. Mila Radic ist eine von ihnen. Warum reagiert Conrad Bergmann so entsetzt, als er sie sieht? Auf der Suche nach Wasser teilt sich die Gruppe schließlich auf. Ein Team erkundet das riesige Höhlensystem, während Mila sich Jack Darys Team anschließt, das sich im dichten Nebel die Wand emporkämpft, auf der Suche nach dem Wasserfall. Noch ahnen beide Teams nicht, was sie vorfinden werden, und dass nicht alle lebend zurückkehren …', '19.10.2014', NULL, ARRAY['Deutsch']::text[], 76, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '2', '{}', 'sheet', :'owner') on conflict do nothing;
