insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('24375e1d-1e2e-5c07-aaad-0f53f03d68f6', 'The Wall - Unter dem Drachen', NULL, NULL, 'Frank Reznik ist kein Held, doch wie er feststellen darf, hat die Wand ihre eigenen Gesetze. Plötzlich kann er Leben retten. Oder war es das Mädchen, das Kaisa Almgren vor dem Tod bewahrte? Leben, um dann doch zu sterben. Sind sie deswegen hier? Fest steht nur: Die Gesetze der Wand fordern ihre Opfer. Mit aller Härte, wie der zusammengewürfelte Haufen erneut erfahren muss, bei der Suche nach Nahrung und bei ihrem Aufstieg zu dem Plateau, das ihnen Wasser verspricht. Wer es bis nach oben schafft, verzweifelt an der Ungewissheit, der Angst vor dem Abgrund und was im Nebelmeer darin lauert. Oder vor dem Dämon, den Kaisa zu erkennen glaubt, jetzt, da nach und nach die Masken derer fallen, die mit ihr in der Wand gefangen sind. Und sie ahnt, dass das Tor zur Hölle bereits weit offen steht.', '02.11.2014', NULL, ARRAY['Deutsch']::text[], 76, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '3', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('c3ead31e-41d3-5c27-b559-d43af3efb624', :'owner', '24375e1d-1e2e-5c07-aaad-0f53f03d68f6', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e313dc1e-0e88-572a-9cc0-10cecf4158d1', 'The Wall - Ein Licht in tiefer Nacht', NULL, NULL, 'Während der eine Teil der Gruppe versucht, die Schläfer zu bergen, brechen Jack Dary und Jonas Strokkursson unter Tyrells Leitung zu einer gefährlichen Expedition auf. Ihr Ziel: den mysteriösen Forschungskomplex ausfindig zu machen, den sie auf den Computermonitoren gesehen haben. Hier, so hoffen die Männer, werden sie endlich Antworten auf die Fragen nach dem Sinn ihres Martyriums sowie den Erbauern der Wand erhalten. Doch was sie finden, sprengt ihre wildesten Vorstellungen. Tief unterhalb des Plateaus lauert ein uraltes Wesen, das danach trachtet, sie alle zu vernichten.', '16.11.2014', NULL, ARRAY['Deutsch']::text[], 74, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '4', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('ec8476c0-f1eb-56a2-af9e-d7df692e39c1', :'owner', 'e313dc1e-0e88-572a-9cc0-10cecf4158d1', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', NULL, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a4bb70f3-36d0-59fa-b3b4-13cf25746b57', 'The Wall - Alpträume', NULL, NULL, 'Die ganze Situation in der Wand ist ein Albtraum, und jeder Einzelne der Gruppe spürt ihn auf seine Weise. Immer wieder tauchen neue Gefahren auf, Grausamkeiten und Schrecken lassen keine Zeit zum Durchatmen. Keine Gelegenheit zum Überlegen und Planen. Zu viele Menschen sind der Wand bereits zum Opfer gefallen. Doch es bleibt eine einzige Hoffnung: der Bau eines Fluggerätes, das eine Person aus der Gruppe über den unendlichen Abgrund zu dem geheimnisvollen Gebäude auf der anderen Seite bringen kann. Ob dort Abbys Schlüssel zum Einsatz kommt? Ob es gelingt, Rettung zu holen? Und wer soll derjenige sein, dem diese Verantwortung übertragen werden soll?', '30.11.2014', NULL, ARRAY['Deutsch']::text[], 76, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '5', '{}', 'sheet', :'owner') on conflict do nothing;
