insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b1bec711-5d74-54d2-9d0b-611f04370601', 'The Wall - Armageddon', NULL, NULL, 'Die Schläfer sind erwacht und greifen unerbittlich an. Roger Harding und Abby riskieren ihr Leben, um mit dem selbstgebauten Hängegleiter den vor kurzem gesichteten Turm zu erreichen. Doch auf dem Weg dorthin lauert der Tod und das blinkende Licht entpuppt sich als Tor in die Tiefe. Dorthin, wo alles begann und alles enden wird.', '12.11.2014', NULL, ARRAY['Deutsch']::text[], 76, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Adult'::audience_kind, NULL, NULL, '{}', '{}', '{}', '{}', 'c56b3c77-9f76-5df4-a0fe-aa192b931015', '6', '{}', 'sheet', :'owner') on conflict do nothing;
