insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('25e9bd80-0832-5b0a-9645-98d14db36a37', 'In these Words (Vol.1)', NULL, NULL, 'Der Psychiater Katsuya Asano wird vom Tokyo Police Department um Mitarbeit bei der Aufklärung einer Serie mysteriöser Morde gebeten. Dank eines von ihm erstellten Täterprofils kommt man dem Mörder auf die Spur. Drei Jahre und zwölf Opfer später ist Keiji Shinohara schließlich gefasst. Er ist bereit, ein umfassendes Gestädnis abzulegen, will dies aber nur gegenüber Katsuya tun. Nicht nur das selstame Verlangen des Täters, sondern auch irritierende Albträume, von denen er heimgesucht wird, stellen Katsuyas Leben von da an völlig auf den Kopf.', '24.05.2018', 'Altraverse', ARRAY['Deutsch']::text[], 208, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', '{}', ARRAY['Katsuya Asano','Keiji Shinohara']::text[], ARRAY['Queer']::text[], '{}', '3d3a53b1-0683-55d7-b0d4-20a654c09bba', '1', '{}', 'sheet', :'owner') on conflict do nothing;
