insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9a81d77b-136e-5361-a574-c371342b21a9', 'In these Words (Vol.2)', NULL, NULL, 'Shinohara ist die Flucht gelungen und er hat Katsuya in sein Versteck entführt. Er quält Katsuya immer weiter, bis dieser droht, den Verstand zu verlieren. Aber warum macht er nicht einfach kurzen Prozess mit ihm? Was will der wahnsinnige Serienkiller nur von ihm?', '24.05.2018', 'Altraverse', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Tokyo', '{}', ARRAY['Katsuya Asano','Keiji Shinohara']::text[], ARRAY['Queer']::text[], '{}', '3d3a53b1-0683-55d7-b0d4-20a654c09bba', '2', '{}', 'sheet', :'owner') on conflict do nothing;
