insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('571371f5-aa04-5dce-8ef1-5a15a44973f0', 'Hope - My inspirational life', NULL, NULL, 'More than a celebrity memoir. Hope dives deeper than other celebrity memoirs and autobiographies before, giving readers a personal look into Tom Parker’s life all the way up to his passing. Fighting until his final days to tell his story and create his legacy, Tom creates a new definition for “the meaning of life” through this inspirational book. A book about living your best life, no matter your circumstances. After being diagnosed with an incurable illness, Tom found a purpose that not only impacted his life but the lives of all those around him. Diagnosed with incurable brain cancer in 2020, Tom made it his life’s mission to campaign for brain cancer research, raise money for cancer research, and live his life to the fullest until his passing in March of 2022.', NULL, 'Blink', ARRAY['Englisch']::text[], 200, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Biografie & Autobiografie', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Tom Parker']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
