insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('334a49a3-379e-51c4-b276-a025fe6172c2', 'Ein Meer aus Tinte und Gold', 'The Reader', '9783551583529', 'Seit Sefias Vater ermordet wurde, kämpft sie mit ihrer Tante Nin ums Überleben. Aber dann wird Nin entführt und die einzige Spur zu ihr ist ein Buch: ein scheinbar nutzloser Gegenstand in einem Land, in dem fast niemand um die Existenz des geschriebenen Wortes weiß. Doch kaum berührt Sefia das makellose Papier, spürt sie eine magische Verbundenheit und lernt die Zeichen zu deuten. Das führt sie auf eine gefährliche Reise – und an die Seite eines stummen Jungen, der selbst voller Geheimnisse steckt.', '25.11.2016', 'Carlsen', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Sefia']::text[], '{}', '{}', '47182686-7f04-51f4-a9f6-10ba7ea556a4', '1', '{}', 'sheet', :'owner') on conflict do nothing;
