insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d850a303-0cee-5177-b22e-9a6d60e65ecf', 'Iron Flowers - Die Kriegerinnen', 'Queen of Ruin', NULL, 'Sie haben alles verloren. Doch sie kämpfen weiter. Denn das Schicksal aller Frauen und Mädchen liegt allein in ihrer Hand. Die Schwestern Serina und Nomi sind Gefangene: Nomi in der Gewalt eines brutalen Regenten, der alle Frauen unterdrückt. Serina auf einer Gefängnisinsel, auf die sie verschleppt wurde. Um in dem brutalen Regime zu überleben, bleibt den Schwestern nur eins: erbittert zu kämpfen – gegen die Unterdrückung und für ihre Liebe. Mit allen Mitteln und jede auf ihre Weise.', '21.12.2018', 'Fischer', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Serina','Nomi']::text[], '{}', '{}', 'df0a8484-3086-57d8-849a-a7809f1a1a54', '2', '{}', 'sheet', :'owner') on conflict do nothing;
