insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b9f2607e-3794-5ea5-ad04-4751341743d5', 'Iron Flowers - Die Rebellinnen', 'Grace and Fury', '9783737355421', 'Sie haben keine Rechte. Sie mussten ihre Träume aufgeben. Doch sie kämpfen eisern für Freiheit und Liebe. Sie sind Schwestern, könnten unterschiedlicher nicht sein und sind dennoch unzertrennlich. Nomi ist wild und unerschrocken, Serina schön und anmutig. Und sie ist fest entschlossen, vom Thronfolger zu seiner Grace auserwählt zu werden, und ihr von Armut und Unterdrückung geprägtes Leben gegen eines im prunkvollen Regentenpalast einzutauschen. Doch am Tag der Auswahl kommt alles anders: Die Schwestern werden auseinandergerissen – und ein grauenhaftes Schicksal erwartet sie, auf das sie niemand vorbereitet hat.', '25.04.2018', 'Fischer', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Serina','Nomi']::text[], '{}', '{}', 'df0a8484-3086-57d8-849a-a7809f1a1a54', '1', '{}', 'sheet', :'owner') on conflict do nothing;
