insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f5574aa3-0a68-5b1b-8cf0-6efa13e75387', 'Crave', NULL, '9781529355550', 'My whole world changed when I stepped inside the academy. Nothing is right about this place or the other students in it. Here I am, a mere mortal among gods . . . or monsters. I still can''t decide which of these warring factions I belong to, if I belong at all. I only know the one thing that unites them is their hatred of me. Then there''s Jaxon Vega. A vampire with deadly secrets who hasn''t felt anything for a hundred years. But there''s something about him that calls to me, something broken in him that somehow fits with what''s broken in me. Which could spell death for us all. Because Jaxon walled himself off for a reason. And now someone wants to wake a sleeping monster, and I''m wondering if I was brought here intentionally - as the bait.', '07.04.2020', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Katmere Academy', '{}', ARRAY['Grace']::text[], '{}', '{}', '388cbc99-78c7-5dbb-98bf-3f888c29fb34', '1', '{}', 'sheet', :'owner') on conflict do nothing;
