insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('a78cfe62-0af9-5ce7-97a0-b0492e7c08eb', 'cc1dc8f4-ef68-5b1e-ac89-562b26670180', :'owner', 1, '2022-11-14', '2022-11-21', NULL, NULL, 8, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a86afade-33cd-5c60-b440-c8ee87486030', 'Crush', NULL, '9781529355581', 'Everything feels off—especially me. I’ve returned to Katmere Academy, but I’m haunted by fragments of days I have no recollection of living and struggling to understand who, or what, I really am. Just when I start to feel safe again, Hudson is back with a vengeance. He insists there are secrets I don’t know about, threatening to drive a wedge between Jaxon and me forever. But far worse enemies are at our doorstep. The Circle is caught in a power play, and the Vampire Court is trying to drag me out of my world and into theirs. The only thing Hudson and Jaxon agree on is that leaving Katmere would mean my certain death. And not only am I fighting for my life, but now everyone else’s is at stake—unless we can defeat an unspeakable evil. All I know is that saving the people I love is going to require sacrifice. Maybe more than I’m able to give.', '29.09.2020', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 684, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Katmere Academy', '{}', ARRAY['Grace']::text[], '{}', '{}', '388cbc99-78c7-5dbb-98bf-3f888c29fb34', '2', '{}', 'sheet', :'owner') on conflict do nothing;
