insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('480558de-769f-5e9c-8ebf-c279445a43f5', 'Court', NULL, '9781649370600', 'No one survived the last battle unscathed. Flint is angry at the world, Jaxon is turning into something I don''t recognize, and Hudson has put up a wall I''m not sure I''ll ever break through. Now war is coming, and we''re not ready. We''re going to need an army to have any hope of winning. But first, there are questions about my ancestors that need answers. Answers that might just reveal who the real monster is among us. And that''s saying something in a world filled with bloodthirsty vampires, immortal gargoyles, and an ancient battle between two gods. There''s no guarantee that anyone will be left standing when the dust settles, but if we want to save this world, I have no choice. I''ll have to embrace every part of me...even the parts I fear the most.', '01.02.2022', 'Entangled', ARRAY['Englisch']::text[], 689, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Katmere Academy', '{}', ARRAY['Grace']::text[], '{}', '{}', '388cbc99-78c7-5dbb-98bf-3f888c29fb34', '4', '{}', 'sheet', :'owner') on conflict do nothing;
