insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5cb87f78-29dd-55d1-ab9d-ce535bb178ff', 'Charm', NULL, NULL, 'He''s under my skin . . . After Katmere, I shouldn''t be surprised by anything. Including the existence of a world beyond my world called the Shadow Realm. Yet here I am, stuck in a strange, dangerous place with the worst of the supernaturals, the monster that other monsters fear: Hudson Vega. He might be Jaxon''s brother and ridiculously hot, but he''s a complete bona fide pain in my ass. The question is whether we''ll find a way out before I kill him . . or run out of time.', '08.11.2022', 'Entangled', ARRAY['Englisch']::text[], 592, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Paranormal Romance']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, 'Katmere Academy', '{}', ARRAY['Grace']::text[], '{}', '{}', '388cbc99-78c7-5dbb-98bf-3f888c29fb34', '5', '{}', 'sheet', :'owner') on conflict do nothing;
