insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5275522c-ce06-53cd-9576-a4541ac6bd8d', 'Wie das Salz der See', NULL, '9782889218271', 'Fünf Jahre schon ist Ryuta heimlich in Naoki verliebt. Aber der war ja immer mit Hana zusammen. Die beiden waren die reinsten Turteltauben. Dennoch kam Ryuta wieder, Sommer für Sommer, um in Naokis Kneipe am Meer auszuhelfen. Doch jetzt ist Hana weg, hat Naoki verlassen. Soll Ryuta ihm sagen, was er für ihn empfindet? Oder verliert er so am Ende den Menschen, der ihm am wichtigsten ist?', '05.08.2020', 'Kaze Manga', ARRAY['Deutsch']::text[], 202, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Ryuta','Naoki']::text[], ARRAY['Queer']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
