insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2b6d1fc4-3275-5683-93ad-b44bba009cb1', 'Royal - Ein Leben aus Glas', NULL, NULL, 'Viterra, das Königreich unter einer Glaskuppel, ist der einzige Ort auf Erden, an dem die Menschen die atomare Katastrophe überlebt haben. Um die Bevölkerung bei Laune zu halten, findet dort alle zwei Jahrzehnte die große Fernsehshow zur Königinnenwahl statt. Aber diesmal ist alles anders. Diesmal will der Prinz ein Mädchen finden, das ihn um seiner selbst liebt. Vor den Augen des gesamten Königreichs soll die siebzehnjährige Tatyana zusammen mit den schönsten Mädchen des Landes um die Gunst von vier jungen Männern buhlen, von denen keiner weiß, wer der echte Prinz ist. Sie würde alles darum geben, nicht teilnehmen zu müssen. Aber auch sie kann sich dem Glanz eines Königslebens nur schwer entziehen …', '06.08.2015', 'Carlsen', ARRAY['Deutsch']::text[], 193, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '1', '{}', 'sheet', :'owner') on conflict do nothing;
