insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c32fa452-f0a7-584a-8245-e4f9f22a021a', 'Royal - Ein Königreich aus Seide', NULL, NULL, 'Die entscheidenden Tage des Wettbewerbs um die Gunst des unbekannten Prinzen haben begonnen. Tatyana und den anderen Mädchen wird die erste Aufgabe zugewiesen und sie erfordert nicht wenig Einfallsreichtum und Geschick. Gleichzeitig beginnen sich die vier möglichen Prinzen Abend für Abend mit jedem der Mädchen zu treffen. Die Spannung steigt. Mit wem wird wohl Tatyana ausgehen müssen? Und was, wenn er sie nicht mag? Doch dann passiert eines Nachts etwas, mit dem sie am wenigsten gerechnet hat…', '03.09.2015', 'Carlsen', ARRAY['Deutsch']::text[], 190, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '2', '{}', 'sheet', :'owner') on conflict do nothing;
