insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4d0a478c-14da-561a-8aee-e6bc288773dc', 'Royal - Ein Schloss aus Alabaster', NULL, NULL, 'Nur zwölf Mädchen sind in der prunkvollen Fernsehshow zur Wahl der Prinzessin übriggeblieben und immer noch weiß niemand, wer von den vier jungen Männern der wahre Anwärter auf den Thron ist. Tatyana ist das aber mittlerweile egal. Ihr Herz schlägt bereits für einen von ihnen und was sie auch versucht, sie kann nichts dagegen tun. Erst als ihre Erinnerung an das zurückkehrt, was wirklich in der Nacht des Meteoritenschauers passiert ist, beginnen ihre Gefühle wieder zu schwanken …', '01.10.2015', 'Carlsen', ARRAY['Deutsch']::text[], 210, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '3', '{}', 'sheet', :'owner') on conflict do nothing;
