insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d32c9d55-d7fa-5e3f-8e08-c07413316a73', 'Royal - Eine Krone aus Stahl', NULL, NULL, 'Wenige Wochen nur trennen die übriggebliebenen Kandidatinnen von der Enthüllung des echten Prinzen und seiner Wahl der Prinzessin. Alle vier jungen Männer scheinen sich bereits für ihre zukünftige Frau entschieden zu haben, nur wer Anspruch auf Tatyana erheben wird, liegt immer noch im Dunkeln. Dass sie selbst zwiegespalten ist, macht die Situation nicht unbedingt leichter. Erst eine gemeinsame Reise durch das gesamte Königreich öffnet ihr die Augen – nicht nur, was ihr Herz betrifft, sondern auch, was die wahren Pläne des Königreichs angeht…', '05.11.2015', 'Carlsen', ARRAY['Deutsch']::text[], 203, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '4', '{}', 'sheet', :'owner') on conflict do nothing;
