insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('709eedd9-a915-51b9-9742-7044e0e0d1ee', 'Royal - Eine Hochzeit aus Brokat', NULL, NULL, 'Nach zahlreichen Herausforderungen, Unterrichtsstunden in Etikette und Anstand, exorbitanten Kleidern und einem wiederholt gebrochenen Herzen hat Tatyana es endlich geschafft: Das Herz des Prinzen gehört ihr und seine letzte Entscheidung steht an. Doch die Fassade des königlichen Prinzessinnen-Wettbewerbs hat längst schon so tiefe Risse bekommen, dass sie sich nur noch seiner Liebe und nicht mehr seiner Wahl sicher sein kann. Denn es geht bereits um viel mehr als nur darum, die Gunst des Prinzen zu erwerben…', '03.12.2015', 'Carlsen', ARRAY['Deutsch']::text[], 250, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '5', '{}', 'sheet', :'owner') on conflict do nothing;
