insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('fa29e3d3-4f8a-5165-b85a-8c3fecaf7d46', 'Royal - Eine Liebe aus Samt', NULL, NULL, 'Es ist so weit. Mit dem Angriff auf das Königreich unter der Glaskuppel haben extravagante Ballkleider, glitzernde Juwelen und funkelnde Mädchenträume ihre Bedeutung für immer verloren. Während fremde Soldaten das Land überschwemmen, bleibt Tatyana nichts anderes übrig als zu fliehen – und kommt so zu einem Ort, von dem sie niemals gedacht hätte, ihn je betreten zu können. Nun liegt es an ihr, das Königreich zu retten, auch wenn dessen Prinz ihr das Herz gebrochen hat', '07.01.2016', 'Carlsen', ARRAY['Deutsch']::text[], 256, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Tatyana']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '6', '{}', 'sheet', :'owner') on conflict do nothing;
