insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('47166d7a-6594-54d8-a508-ccf7bb6fc27f', 'Princess - Der Tag der Entscheidung', NULL, NULL, 'Viterra, das Königreich unter einer Glaskuppel, lässt seine royalen Kinder seit Anbeginn der Zeiten im Verborgenen aufwachsen. Das gilt nicht nur für den Prinzen, der gerade eine aufwendige Prinzessinnenwahl durchlaufen musste, sondern auch für seine Schwester Evelina, deren Prinzenwahl noch bevorsteht. Nur leider ist Evelina alles andere als eine typische Prinzessin und kein Mädchen, das sich gerne versteckt hält. Und dennoch ist es ausgerechnet ein Maskenball, der ihr den Weg in die Freiheit zeigen wird...', '03.03.2016', 'Carlsen', ARRAY['Deutsch']::text[], 262, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Romantasy']::text[], 'YA'::audience_kind, 'Vergangenheit'::time_period, 'Viterra', '{}', ARRAY['Evelina']::text[], '{}', '{}', '2b8d4269-7580-5706-b69c-ba60e7bd48c1', '7', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
