insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cafadda3-629b-511a-9809-05615e8e35b7', 'Only a Monster', NULL, '9781529380101', 'Don’t forget the rule. No one can know what you are. What we are. You must never tell anyone about monsters. Joan has just learned the truth: her family are monsters, with terrifying, hidden powers. And the cute boy at work isn’t just a boy: he’s a legendary monster slayer, who will do anything to destroy her family. To save herself and her family, Joan will have to do what she fears most: embrace her own monstrousness. Because in this story…she is not the hero.', '22.02.2022', 'Hodder and Stoughton', ARRAY['Englisch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'YA'::audience_kind, NULL, NULL, '{}', ARRAY['Joan']::text[], '{}', '{}', '974b46de-1aa4-5a7a-8417-0d2a1f0498c8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
