insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ac2a18e-4af1-575a-9b4a-39de8a5f3653', 'Schlaflos in Seoul', NULL, '9783423211536', '»Ich wollte nach Korea, wo alles bunt und schnell ist, wo man mitten in der Hektik der Millionenmetropole Ruhe findet in buddhistischen Tempeln, in kunstvoll angelegten Parks und Teehäusern, wo es die absurdesten Kosmetikprodukte, die neueste Technik und die besten Jeans gibt.« Neugierig und abenteuerlustig wie sie ist, landet Vera Hohleiter in Korea. Durch Zufall wird sie für eine populäre Fernsehshow engagiert. In- und außerhalb des Studios begegnen ihr Workaholics und Nationalisten, Trunkenbolde und Missonare, egomanische Regisseure und schwermütige Expats, die sich manchmal eine Verschnaufpause im rasanten koreanischen Alltag wünschen. So schrill, chaotisch und unberechenbar Korea auch sein mag, lässt das Land Vera Hohleiter doch so schnell nicht wieder los.', '01.07.2009', 'dtv', ARRAY['Deutsch']::text[], 192, NULL, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Reisen', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, 'Korea', '{}', ARRAY['Vera Hohleiter']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
