insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5442c3a4-d6d7-594f-b7ca-7f5ff27bbbbb', 'Gebannt - Unter fremden Himmel', 'Under the Never Sky', NULL, 'Getrennt durch zwei Welten, geeint im Überlebenskampf, verbunden in unendlicher Liebe. Die siebzehnjährige Aria lebt in einer Welt, die perfekter ist als die Realität. Perry kommt aus einer Wildnis, die realer ist als jede Perfektion und in der wilde Stürme das Leben bedrohen. Als Aria in seine Welt verstoßen wird, rettet Perry ihr das Leben. Trotz ihrer Fremdheit verbindet die beiden die Verzweiflung und Sorge um die, die sie lieben. Aria will ihre verschollene Mutter wiederfinden, Perry ist auf der Suche nach seinem Neffen, an dessen Entführung er sich die Schuld gibt. Aria versucht, vor Perry zu verbergen, dass ihre Gefühle ihm gegenüber sich wandeln. Doch Perry hat dies längst schon entdeckt, aber nicht nur bei Aria, auch bei sich selbst', '01.05.2012', 'Oetinger', ARRAY['Deutsch']::text[], 432, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Aria','Perry']::text[], '{}', '{}', 'b6a4e88c-10b4-516c-956e-a8d5b8d1215b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
