insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('444838a7-7ee4-55bd-8618-45430589ad05', 'Getrieben - Durch ewige Nacht', 'Through the Ever Night', NULL, 'Arias Kampf gegen Stürme, die Leben und Liebe bedrohen. Endlich haben Aria und Perry seinen Stamm erreicht. Doch seine Leute trauen Aria nicht. Um den Anfeindungen zu entfliehen, macht sie sich gemeinsam mit Roar auf die Suche nach der Blauen Stille, dem Ort, an dem alle Ätherstürme ruhen und der auch Perrys Stamm retten kann. Während ihrer Abwesenheit taucht Kirra, die Anführerin eines befreundeten Stammes auf. Wird Perry ihren Annäherungsversuchen widerstehen? Der zweite Band der packenden Trilogie: über eine Liebe, die Missgunst und Todesgefahren ausgesetzt ist und trotzdem niemals aufgibt. Auch als', '17.05.2013', 'Oetinger', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Aria','Perry']::text[], '{}', '{}', 'b6a4e88c-10b4-516c-956e-a8d5b8d1215b', '2', '{}', 'sheet', :'owner') on conflict do nothing;
