insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f79d4fe4-c180-5e8f-9ba8-021da37e1908', 'Geborgen - In unendlicher Weite', 'Into the Still Blue', NULL, 'Wenn Liebe stärker als alles ist, was sich ihr entgegenstellen kann: Das gewaltige Finale der „Aria und Perry“-Trilogie bietet Spannung und Romantik pur. Nachdem Reverie von einem Äthersturm ausgelöscht wurde, kehrt Aria schwerverletzt zum Stamm der Tiden zurück. Hier wartet Perry auf sie, dem in Arias Abwesenheit einmal mehr bewusst wurde, wie viel er für sie empfindet. Mit ihrem Stamm wollen Perry und Aria nun zur Blauen Stille aufbrechen, um Zuflucht vor den Stürmen zu finden. Doch auch Sable, der Kriegsherrn der Hörner, und Kommandant Hess hegen ganz ähnliche Absichten. Als Perry und Aria versuchen, die Pläne ihrer Rivalen zu vereiteln, geraten sie schon bald selbst in Gefangenschaft. Nach einer blutigen Schlacht gelingt es ihnen schließlich zu entkommen, und bald scheint die Blaue Stille zum Greifen nah. Doch das Schicksal will es, dass Aria und Perry erneut voneinander getrennt werden ...', '15.05.2014', 'Oetinger', ARRAY['Deutsch']::text[], 400, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Aria','Perry']::text[], '{}', '{}', 'b6a4e88c-10b4-516c-956e-a8d5b8d1215b', '3', '{}', 'sheet', :'owner') on conflict do nothing;
