insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('2e3491ee-e334-5e6a-8ef4-28b1daa14873', '4e8dbf45-f809-5cba-95bc-011ef6965223', :'owner', 1, NULL, NULL, NULL, NULL, NULL, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('c07f5a12-c679-59e1-9b2a-f6af027b957c', 'Die Bestimmung', 'Divergent', NULL, 'Altruan – die Selbstlosen. Candor – die Freimütigen. Ken – die Wissenden. Amite – die Friedfertigen. Und schließlich Ferox – die Furchtlosen … Fünf Fraktionen, fünf völlig verschiedene Lebensformen sind es, zwischen denen Beatrice, wie alle Sechzehnjährigen ihrer Welt, wählen muss. Ihre Entscheidung wird ihr gesamtes zünftiges Leben bestimmen, denn die Fraktion, der sie sich anschließt, gilt fortan als ihre Familie. Doch der Eignungstest, der über Beatrices innere Bestimmung Auskunft geben soll, zeigt kein eindeutiges Ergebnis. Sie ist eine Unbestimmte, sie trägt mehrere widerstreitende Begabungen in sich. Damit gilt sie als Gefahr für die Gemeinschaft. Beatrice entscheidet sich, ihre bisherige Fraktion, die Altruan, zu verlassen, und schließt sich den wagemutigen Ferox an. Dort aber gerät sie ins Zentrum eines Konflikts, der nicht nur ihr Leben, sondern auch das all derer, die sie liebt, bedroht…', '19.03.2012', 'Goldmann', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tris','Four']::text[], '{}', '{}', '1ccd2f49-9678-5a6e-b156-bfcb45159248', '1', '{}', 'sheet', :'owner') on conflict do nothing;
