insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5aa6ae40-1236-526c-b852-64c2ce755046', 'Die Bestimmung - Tödliche Wahrheit', 'Insurgent', NULL, 'Drei Tage ist es her, seit die Ken mithilfe der ferngesteuerten Ferox-Soldaten unzählige Altruan umgebracht haben. Drei Tage, seit Tris'' Eltern starben. Drei Tage, seit sie selbst ihren Freund Will erschossen hat – und aus Scham und Entsetzen darüber schweigt. Mit den überlebenden Altruan haben Tris und Tobias sich zu den Amite geflüchtet – doch dort sind sie nicht sicher, denn der Krieg zwischen den Fraktionen hat gerade erst begonnen. Wieder einmal muss Tris entscheiden, wo sie hingehört – selbst wenn es bedeutet, sich gegen die zu stellen, die sie am meisten liebt. Und wieder einmal kann es nur Tris in ihrer Rolle als Unbestimmte gelingen, die Katastrophe abzuwenden...', '10.12.2012', 'cbt', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tris','Four']::text[], '{}', '{}', '1ccd2f49-9678-5a6e-b156-bfcb45159248', '2', '{}', 'sheet', :'owner') on conflict do nothing;
