insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('2b66a7e3-0f3a-5276-bb16-a2ee0218c9cc', 'Die Bestimmung - Letzte Entscheidung', 'Allegient', NULL, 'Die Fraktionen haben sich aufgelöst und Tris und Four erfahren, dass ihr ganzes Leben eine Lüge ist: Es gibt eine Welt außerhalb ihrer Stadt, außerhalb des Zauns. Für Tris und Four steht fest, dass sie diese neue Welt erkunden wollen. Gemeinsam. Doch sie müssen erkennen, dass die Lüge hinter dem Zaun größer ist, als alles, was sie sich vorstellen konnten, und die Wahrheit stellt ihr Leben völlig auf den Kopf. Als Tris dann auch noch die letzte Entscheidung treffen muss, kommt alles ganz anders als gedacht ...', '24.03.2014', 'cbt', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Sci Fi', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Zukunft'::time_period, NULL, '{}', ARRAY['Tris','Four']::text[], '{}', '{}', '1ccd2f49-9678-5a6e-b156-bfcb45159248', '3', '{}', 'sheet', :'owner') on conflict do nothing;
