insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f0fd30e9-5524-52ab-a2a7-fabe9cbbab60', 'Men of Manhatten - My Best Friend''s Sister', 'The Rules of Dating - My Best Friend''s Sister', '9783736320475', 'Holden Catalano ist ein Bad Boy, wie er im Buche steht. Der attraktive Drummer der Band After Friday liebt es, auf Tour zu sein, und genießt die Vorzüge seiner Popularität. Doch Holden hat eine Schwäche: Laney, die kleine Schwester seines verstorbenen besten Freundes. Diesem hat er versprochen, die junge Wissenschaftlerin für immer zu beschützen - und damit sind jegliche Flirtversuche absolut tabu! Das ist leichter gesagt als getan, denn Holden hat nicht damit gerechnet, dass Laney seine neue Nachbarin wird und er der unglaublichen Anziehung zwischen ihnen jeden Tag aufs Neue widerstehen muss ...', '28.03.2024', 'LYX', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Holden Catalano','Laney']::text[], '{}', '{}', '80b87341-2a5d-5990-b75b-9cf1d603ef5b', '2', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
