insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('75c6b1c9-328e-5c55-b64a-d84e23e769ee', 'Man of Manhatten - More Than One Night', 'The Rules of Dating - My One-Night Stand', '9783736321984', 'Owen kennt die Regel Nummer eins, wenn es um einen One-Night-Stand geht: verlieben verboten. Doch als er nach einer langen Dating-Durststrecke auf Devyn trifft, ändert sich alles. Sie verbringen eine leidenschaftliche Nacht miteinander, und Owen kann es nicht fassen, als er am nächsten Morgen allein aufwacht. Von Devyn gibt es keine Spur, und ohne ihre Telefonnummer scheint es unmöglich, dass er die junge Frau jemals wiedersehen wird. Bis er ihr eines Tages plötzlich erneut gegenübersteht - und das ausgerechnet als ihr Vermieter, der sie abmahnen und ihr mit Kündigung drohen muss!', '26.07.2024', 'LYX', ARRAY['Deutsch']::text[], 394, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Owen','Devyn']::text[], '{}', '{}', '80b87341-2a5d-5990-b75b-9cf1d603ef5b', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
