insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1301bf56-0d55-58bc-9536-46faa9d43ee8', 'Man of Manhatten - An Unplanned Match', 'The Rules of Dating a Younger Man', '9783736323254', 'Brayden Foster hat es nicht eilig, die Eine zu finden. Er ist völlig zufrieden mit seinem Leben als Junggeselle und mit seiner Arbeit bei einer wohltätigen Stiftung, wo er Häuser für bedürftige Menschen renoviert. Er hätte niemals gedacht, dass sich Alex, einer der freiwilligen Helfer, mit dem er bisher ausschließlich via E-Mail kommuniziert hat, als Alexandria Jones entpuppt - die schönste Frau, der Brayden je begegnet ist. Von Tag eins an verdreht sie ihm den Kopf, und auch Alexandria kann nicht lange leugnen, dass da mehr zwischen ihnen ist. Doch es gibt ein Problem: Alexandria ist älter als Brayden und hat nicht vor, einen jüngeren Mann zu daten ...', '28.02.2025', 'LYX', ARRAY['Deutsch']::text[], 368, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Brayden Foster','Alexandria Jones']::text[], '{}', '{}', '80b87341-2a5d-5990-b75b-9cf1d603ef5b', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
