insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a6bfe5d3-8b7a-5e81-a7c3-2f0a19d5785f', 'Men of Manhattan - The Rules of Dating', 'The Rules of Dating', '9783736319837', 'Nach einer schmerzhaften Trennung schwört Tattoo- Artist Billie den Männern ab. Doch ihr guter Vorsatz geht - fast! - flöten, als ihr neuer Vermieter Colby Lennon vor ihrer Tür steht. Der Geschäftsmann und Besitzer des Gebäudes, in dem sich ihr Tattoostudio befindet, ist attraktiv, charmant und daran gewöhnt, dass er immer bekommt, was er will. Und jetzt will Colby sie und lässt daran keinen Zweifel. Aber mehr als Freundschaft ist für Billie nicht drin! Aus diesem Grund stellt sie strikte Regeln für ihre sogenannten Nicht-Dates mit dem Single-Dad auf und verflucht sich bei jedem Treffen ein bisschen mehr dafür, dass sie Colby in die Friendzone verbannt hat ...', '25.08.2023', 'LYX', ARRAY['Deutsch']::text[], 430, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Contemporary YA']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Billie','Colby Lennon']::text[], '{}', '{}', '80b87341-2a5d-5990-b75b-9cf1d603ef5b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
