insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('5c802b0e-a290-5a60-b767-9ed80c53c7a9', 'Die rote Königin', 'Red Queen', '9783646927245', 'Rot oder Silber – Mares Welt wird von der Farbe des Blutes bestimmt. Sie selbst gehört zu den niederen Roten, deren Aufgabe es ist, der Silber-Elite zu dienen. Denn die – und nur die – besitzt übernatürliche Kräfte. Doch als Mare bei ihrer Arbeit in der Sommerresidenz des Königs in Gefahr gerät, geschieht das Unfassbare: Sie, eine Rote, rettet sich mit Hilfe besonderer Fähigkeiten! Um Aufruhr zu vermeiden, wird sie als verschollen geglaubte Silber-Adlige ausgegeben und mit dem jüngsten Prinzen verlobt. Dabei ist es dessen Bruder, der Thronfolger, der Mares Gefühle durcheinander bringt. Doch von jetzt an gelten die Regeln des Hofes, Mare darf sich keine Fehler erlauben. Trotzdem nutzt sie ihre Position, um die aufkeimende Rote Rebellion zu unterstützen. Sie riskiert dabei ihr Leben – und ihr Herz …', '24.04.2015', 'Carlsen', ARRAY['Deutsch']::text[], 512, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Mare','Cal']::text[], '{}', '{}', 'f61f8610-4b58-5a32-89b7-15a6aeb1b7c8', '1', '{}', 'sheet', :'owner') on conflict do nothing;
