insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('a96a38bb-9af2-57c5-a283-cc138ab0e301', 'Gläsernes Schwert', 'Glass Sword', '9783646927252', 'In letzter Sekunde wurden Mare und Prinz Cal von der Scharlachroten Garde aus der Todesarena gerettet. Die Rebellen hoffen, mit Hilfe der beiden den Kampf gegen die Silber-Herrschaft zu gewinnen. Doch Mare hat eigene Pläne. Gemeinsam mit Cal will sie diejenigen aufspüren, die sind wie sie: Rote mit besonderen Silber-Fähigkeiten. Denn auch der neue König der Silbernen, ihr einstiger Verlobter, hat es auf diese Menschen abgesehen. Aber schnell wird klar, dass er eigentlich nur eins will – und zwar um jeden Preis: Mare.', '01.07.2016', 'Carlsen', ARRAY['Deutsch']::text[], 576, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Mare','Cal']::text[], '{}', '{}', 'f61f8610-4b58-5a32-89b7-15a6aeb1b7c8', '2', '{}', 'sheet', :'owner') on conflict do nothing;
