insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('aa9539e2-f2ee-580a-9a54-9360ab546e8d', 'Goldener Käfig', 'King''s Cage', '9783646927269', 'Mare, die Rote mit den besonderen Silber-Fähigkeiten, ist zurück am königlichen Hof – doch dieses Mal nicht als falsche Prinzessin, sondern als Gefangene des Königs: Um ihre Gefährten vor dem Tod zu retten, hat sie sich ihrem schlimmsten Feind – und einstigen Freund – ergeben. Und erwartet nun ein schreckliches Schicksal an seiner Seite. Aber natürlich setzen Prinz Cal und die Rebellen der Scharlachroten Garde alles daran, um die Blitzwerferin zu befreien. Denn nur mit ihr gibt es im Kampf um die Freiheit eine Chance.', '30.06.2017', 'Carlsen', ARRAY['Deutsch']::text[], 640, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Mare','Cal']::text[], '{}', '{}', 'f61f8610-4b58-5a32-89b7-15a6aeb1b7c8', '3', '{}', 'sheet', :'owner') on conflict do nothing;
