insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ee3e889c-b75c-5e91-acf7-e711d3d22b7b', 'Wütender Sturm', 'War Storm', '9783551583819', 'Siege haben ihren Preis! Das weiß Blitzwerferin Mare nur allzu gut seit dem Verrat durch Prinz Cal. Umso klarer ist ihr Ziel: Sie wird das Königreich umstürzen und den versklavten Roten und verfolgten Neublütern ein Leben in Freiheit sichern. Mavens Thron wird fallen! Doch der König tut alles, um Mare zurückzubekommen, auch wenn er dadurch sein Land zerstört. Mare braucht die Hilfe der Rebellen – und Cals Silber-Freunde. Um den zu besiegen, der fast ihren Willen gebrochen hätte, muss sie sich mit dem verbünden, der ihr das Herz brach.', '12.10.2018', 'Carlsen', ARRAY['Deutsch']::text[], 784, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Dystopie']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Mare','Cal']::text[], '{}', '{}', 'f61f8610-4b58-5a32-89b7-15a6aeb1b7c8', '4', '{}', 'sheet', :'owner') on conflict do nothing;
