insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4f6195a4-2921-5c20-bdf1-9af111c7318f', 'Das verlorene Kätzchen', NULL, '9783855812455', 'Eine Maus und eine Elster befreien ein verwirrtes junges Kätzchen. Die drei ungleichen Tiere werden Freunde und merken, daß das Kätzchen zu einem bedrohlich großen und starken Kater heranwächst. Ob die Freundschaft wohl stärker ist...?', '01.01.1992', 'Bohem Press', ARRAY['Deutsch']::text[], 32, NULL, 'Kinderbuch'::book_kind, ARRAY['Fiction']::book_category[], 'Märchen & Sagen', '{}', 'Child'::audience_kind, 'Unbestimmt'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Maus','Elster','Kätzchen']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
