insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('cf4606f2-96ae-511c-95de-449b8c563b45', 'Die Rosenschlacht', 'The War of the Roses', '9783751785150', 'Jonathan und Barbara Rose sind das perfekte Paar. Sie leben in einem wunderschönen Haus voller wertvoller Antiquitäten, haben zwei wohlgeratene Kinder und in der Garage einen teuren Ferrari. Was wünscht man sich mehr? Doch als Jonathan plötzlich einen Herzinfarkt erleidet (oder zumindest glaubt, er habe einen), wird Barbara klar, dass sie mehr vom Leben möchte - ohne ihn. Es gibt nur ein Problem: Beide wollen das Haus. Und nun beginnt ein Krieg, in dessen Verlauf alles zerstört wird, was ihnen kurz zuvor noch ach so wichtig gewesen ist ...', '1981', 'Lübbe', ARRAY['Deutsch']::text[], 275, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Comedy']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Jonathan Rose','Barbara Rose']::text[], ARRAY['Family Drama']::text[], '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
