insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ce12a105-dcd9-59ba-aa6f-e19ec4dc3447', 'The Rise of Silas Lapham', NULL, NULL, 'oin Silas Lapham on his unforgettable journey of struggle and success in William Dean Howells'' classic novel ''The Rise of Silas Lapham.'' Follow Silas as he rises from humble beginnings to become a successful paint manufacturer, but must navigate the complexities of social class and morality to maintain his newfound status.', '1885', NULL, ARRAY['Englisch']::text[], 534, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Drama']::text[], 'Adult'::audience_kind, 'Vergangenheit'::time_period, NULL, '{}', ARRAY['Silas Lapham']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
