insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f823ef76-750a-5b26-8a74-69b7861669ff', 'I Hear the Sunspot', 'Hidamari ga Kikoeru', NULL, '»Warum ist deine Stimme die einzige, die ich klar hören kann?« Student Taichi braucht dringend einen gut bezahlten Nebenjob! Er trifft Kohei, der im Gegensatz zu ihm anscheinend alles hat. Doch eines hat Kohei nicht – den leichten Zugang zu seinen Mitmenschen! Seit der Mittelschule leidet er an Schwerhörigkeit, die ihn immer mehr isoliert. Kann ihn der quirlige Taichi aus seinem Schneckenhaus herauslocken?', '02.10.2018', 'Carlsen', ARRAY['Deutsch']::text[], 194, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'YA'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Kohei','Taichi']::text[], ARRAY['Queer']::text[], '{}', '3964d9ba-a3ef-5e7f-85ed-33914e6d00e2', '1', '{}', 'sheet', :'owner') on conflict do nothing;
