insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9b64dae2-6277-5566-9b0f-069a78853849', 'Black Butler I', 'Kuroshitjuji', '9783551753038', 'London im 19. Jahrhundert: Sebastian Michaelis ist ein teuflisch guter Butler – und teuflisch ist hier wörtlich zu nehmen! Denn Sebastian ist wirklich ein Dämon, der durch einen Pakt an den jungen Earl Ciel Phantomhive gebunden ist. Gemeinsam tauchen sie in die finsteren Ecken Londons ein, lösen gefährliche Aufgaben für Königin Victoria und verteidigen das Erbe der Phantomhives gegen tödliche Feinde. Mit einer Mischung aus düsterem Humor, packender Action und einem Hauch von Boys Love, hat Yana Toboso eine atmosphärische Gothic-Horror-Serie geschaffen, die nicht nur Manga-Fans begeistern wird.', '27.05.2010', 'Carlsen', ARRAY['Deutsch']::text[], 194, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '1', '{}', 'sheet', :'owner') on conflict do nothing;
