insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1a14708a-2dfd-5978-9855-79e6918c6a58', 'Black Butler XI', 'Kuroshitjuji', '9783551753458', 'Ein Geheimbund namens »Aurora-Gesellschaft« rühmt sich, Tote zum Leben erwecken zu können. Um herauszufinden, was es mit dieser Gesellschaft auf sich hat, schmuggeln Ciel und sein Butler Sebastian sich auf eine Präsentation des Geheimbundes, die auf einem Luxusdampfer stattfindet. Und während die unterschiedlichsten Menschen sich die geheime Losung »Phönixe« zurufen, beginnt das weite Meer unter ihnen zu tosen... und wie es tost!', '22.04.2012', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '11', '{}', 'sheet', :'owner') on conflict do nothing;
