insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('db6458b8-ed08-5b49-84d7-c5ca44c1b7c0', 'Black Butler XVI', 'Kuroshitjuji', '9783551753502', 'Um an einer der »Mitternächtlichen Teepartys« des Direktors des Weston College teilnehmen zu können, bleibt Ciel nur ein einziger Weg: Er muss vom Direktor persönlich als »herausragender Spieler« des traditionellen Cricket-Turniers dazu eingeladen werden. Kurz darauf sieht man ihn auch schon mit den anderen auserwählten und vor Jugend nur so strotzenden Schülern über den hellgrünen Rasen laufen.', '18.03.2014', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '16', '{}', 'sheet', :'owner') on conflict do nothing;
