insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('d953e41b-7157-5f74-8f98-2f816c6580e1', 'Black Butler XVII', 'Kuroshitjuji', '9783551753533', 'Eine neue Serie mysteriöser Überfälle erschüttert London und zwingt den jungen Herrn Ciel und seinen Butler Sebastian, den gemütlichen Landsitz der Phantomhives zu verlassen. Bei ihren Ermittlungen treffen sie auf einen jungen indischen Prinzen und dessen Diener. Angesichts dieses tadellosen indischen Butlers beginnen Sebastians makellos weißen Handschuhe zu wirbeln. Und wie sie wirbeln!', '26.08.2014', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '17', '{}', 'sheet', :'owner') on conflict do nothing;
