insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e8472378-cee9-56a0-8854-8b84459f54e7', 'Black Butler XVIII', 'Kuroshitjuji', '9783551753540', 'Ciel hat herausgefunden, was mit den verschwundenen Schüler passiert ist. Ein kleiner Vorfall zwischen Schülern weitet sich aus zu einer riesigen Bedrohung, die selbst den Teufel verblüfft... Und so kommt es zum Streit zwischen zwei Bestien, die ihr Spiel mit den Leben der Menschen treiben.', '23.12.2014', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '18', '{}', 'sheet', :'owner') on conflict do nothing;
