insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('7e86f918-7cb8-59f0-8521-8895f8758ffb', 'Black Butler XIX', 'Kuroshitjuji', '9783551753557', 'Ciel und sein Butler haben den Auftrag, einer rätselhaften Legende über Werwölfe nachzugehen, die Menschen durch ihren bloßen Anblick in den Tod treiben. Dazu müssen sie England verlassen und sich auf den Weg nach Deutschland machen. Im »Werwolf-Wald« treffen sie auf die Nachfahrin eines Hexen-Clans, die über den Wald herrscht. Und schon trüben sich die immergrünen Augen – und wie sie sich trüben!', '30.06.2015', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '19', '{}', 'sheet', :'owner') on conflict do nothing;
