insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('29fcc57a-2fbf-5955-90c2-7de1de2e9f1e', 'Black Butler XX', 'Kuroshitjuji', '9783551753564', 'In Deutschlands dunklen Wäldern versteckt, umgeben von gefährlichen Werwölfen und Dorfbewohnern, die ihnen am liebsten ans Leder wollen, verzweifeln die Diener des Hauses Phantomhive: ihr Herr Ciel ist nicht in der Lage, am normalen Leben teilzunehmen und hat immer noch seine lähmenden Panikattacken! Doch als die Gefahr für Ciels Dienerschaft zu groß wird, konfrontiert Sebastian seinen Herrn. Denn dessen Panik und Zögern bedeutet, dass der Pakt zwischen ihnen am brechen ist...', '22.03.2016', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '20', '{}', 'sheet', :'owner') on conflict do nothing;
