insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('f41fd052-8f95-5784-9905-e6886e4d695f', 'Black Butler XXI', 'Kuroshitjuji', '9783551753571', 'Butler Sebastian hat das Geheimnis um die unheimlichen Werwölfe gelöst und sein junger Herr stellt die Grüne Hexe vor eine Wahl: Hier bleiben und sterben, oder mit ihm den Wald zu verlassen und ihr Wissenschaftsgenie in den Dienste der Menschheit zu stellen. Die Wächter der Grünen Hexe Sullivan sind davon natürlich alles andere als begeistert und tun ihr Bestes, die Flucht von Ciel und seinen Kompagnons zu verhindern…', '28.06.2016', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '21', '{}', 'sheet', :'owner') on conflict do nothing;
