insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('18130f01-25a2-5d92-ad7a-f495a54531d1', 'Black Butler XXII', 'Kuroshitjuji', '9783551753588', 'Knapp konnten Earl Ciel Phantomhive, sein wendiger Butler Sebastian und der Rest der Dienerschaft mit der Grünen Hexe den falschen Werwolfsfängen aus der Wolfsschlucht entkommen. Sie retten sich auf das Anwesen eines alten Familienfreundes – Diederich, der ein Freund und Vertrauter des verstorbenen Vincent Phantomhives war. Während sie planen, sich heimlich wieder nach England abzusetzen, erfahren sie von dem seltsamen Benehmen, dass der Undertaker an den Tag legte. Was könnte den sonst so gut gelaunten Sensenmann nur so erschüttert haben, dass sich seine grünen Augen mit Tränen füllten…', '20.12.2016', 'Carlsen', ARRAY['Deutsch']::text[], 178, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Mystery']::text[], 'Teen'::audience_kind, 'Vergangenheit'::time_period, 'London', ARRAY['3P Objective']::text[], ARRAY['Sebastian Michaelis','Ciel Phantomhive']::text[], ARRAY['Amateur Detektiv','Anti-Hero','Dark Secrets','Disguised Identity','Mentor & Protegee','Political Intrigue','Revenge Plot','Secred Identity']::text[], '{}', '07043e24-22f1-5463-a2dc-547bc4ce8d5b', '22', '{}', 'sheet', :'owner') on conflict do nothing;
