insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('4a3479a6-bffc-5a49-ae12-221944ba4caf', 'Schiffbruch mit Tiger', 'Life of Pi', NULL, 'Pi Patel, der Sohn eines indischen Zoobesitzers und praktizierender Hindu, Christ und Muslim erleidet mit einer Hyäne, einem Orang-Utan, einem verletzten Zebra und einem 450 Pfund schweren bengalischen Tiger namens Richard Parker Schiffbruch. Bald hat der Tiger alle erledigt - alle, außer Pi. Alleine treiben sie in einem Rettungsboot auf dem Ozean. Eine wundersame, abenteuerliche Odyssee beginnt.', '17.08.2010', 'Fischer', ARRAY['Deutsch']::text[], 384, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Roman', ARRAY['Adventure']::text[], 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Pi Patel']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
