insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('0130117b-0a9f-5679-bd1f-7f24b7fc0f22', 'Emotional Female', NULL, '9783759600219', 'Yumiko Kadota war der Traum aller asiatischen Eltern: Musterschülerin, Medizinstudentin, immer die Beste. Sie ordnete alles der ersehnten Karriere unter. Doch die Realität im öffentlichen Gesundheitswesen brach sie. Überarbeitung, Sexismus, Mobbing und Belästigung. Man nannte sie »emotional«, »zu selbstbewusst«. Irgendwann war es zu viel, Yumiko kündigte. Als sie ihren Blog mit den Worten begann: »Ich hätte nie gedacht, dass ich das einmal sagen würde, aber ich gebe auf. Ich gebe meinen Traum auf, Chirurgin zu werden«, ging ihre Geschichte viral. Seither ist Yumiko Kadota die Stimme ihrer Generation, wenn es um Burnout geht und darum, nach einem Zusammenbruch wieder auf die Beine zu kommen.', '27.06.2025', 'pola', ARRAY['Deutsch']::text[], 448, 39, 'Buch'::book_kind, ARRAY['Non-Fiction']::book_category[], 'Biografie & Autobiografie', '{}', 'Adult'::audience_kind, 'Gegenwart'::time_period, NULL, '{}', ARRAY['Yumiko Kadota']::text[], '{}', '{}', NULL, NULL, '{}', 'sheet', :'owner') on conflict do nothing;
