insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('1ee713f2-d9df-57af-84da-190e35706838', 'Loveless (Vol.1)', NULL, '9782849466841', 'In der Welt von Loveless sind die Katzen ohren ein Zeichen von Unschuld. Verliert man diese, verschwinden auch die niedlichen Horcher. Doch Yun Kougas Manga bietet weit mehr als unschuldige Samt pfötchen: Ohrenträger Ritsuka umgibt ein dunkles Geheimnis und zusammen mit seiner „Waffe“ Soubi muss er sich Mächten stellen, die finsterer sind als die Nacht ...', '24.01.2007', 'Egmont Manga', ARRAY['Deutsch']::text[], 192, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Ritsuka','Soubi']::text[], ARRAY['Queer']::text[], '{}', '79804942-5f97-5636-b1bf-37106d47a39c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
