insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('e477eb47-82c2-5d55-a090-fcfb9615d85d', 'Love Nest (Vol. 1)', NULL, '9783770426942', 'Masato Hozumi ist auf der Suche nach einer neuen Wohnung und landet in der Eigentumswohnung des Besitzers seiner Stammkneipe. Allerdings wohnt dort überraschenderweise bereits jemand: Asahi. Dieser ist mit seiner schluderigen und schroffen Art das genaue Gegenteil von Masato und bringt ihn damit sofort auf die Palme. Doch was noch viel schlimmer ist: In Asahis Gegenwart kommen bei Masato unerwartet immer wieder Erinnerungen an seinen Ex-Freund hoch.', '02.04.2020', 'Egmont Manga', ARRAY['Deutsch']::text[], 226, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Masato','Asahi']::text[], ARRAY['Queer']::text[], '{}', '2a3eacf8-4ecc-5d1d-a7fe-6abb31afd12c', '1', '{}', 'sheet', :'owner') on conflict do nothing;
