insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('dfcca385-c596-5428-af23-7f8c4bae0c14', 'Love Nest (Vol. 2)', NULL, '9783770426959', 'Masato ist klar geworden, dass er in Asahi verliebt ist. Nach seinem emotionalen Geständnis verbringen die beiden eine heiße Nacht miteinander. Doch eine Antwort von Asahi hat er noch nicht bekommen. Ganz im Gegenteil – von außen betrachtet hat sich nichts am Verhältnis der beiden verändert. Als dann auch noch Asahis jüngerer Bruder Kosei auftaucht, wird Masato unerwartet von seiner eigenen Vergangenheit eingeholt.', '04.06.2020', 'Egmont Manga', ARRAY['Deutsch']::text[], 250, NULL, 'Manga'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Yaoi']::text[], 'Teen'::audience_kind, 'Gegenwart'::time_period, NULL, ARRAY['3P Objective']::text[], ARRAY['Masato','Asahi']::text[], ARRAY['Queer']::text[], '{}', '2a3eacf8-4ecc-5d1d-a7fe-6abb31afd12c', '2', '{}', 'sheet', :'owner') on conflict do nothing;
