insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('089611f5-3e17-5e64-9955-1e84c6f52d63', 'A Song Unnamed', NULL, '9783736320628', 'Als Hazel Birds erfährt, dass sie eine Sirene ist, liegen ihre Träume und Hoffnungen plötzlich in Scherben. Denn sie wirkt dadurch nicht nur besonders faszinierend auf andere Menschen - eine Eigenschaft, die die Schauspielstudentin bisher auf ihr Talent zurückgeführt hat -, sondern es lastet auch ein Fluch auf ihr: Wenn sie wahrhaftig liebt, wird sie sterben. Das bedeutet, dass Hazel sich nun von Taro Takahashi fernhalten muss. Dem Mann, in dessen Nähe ihr Herz schon seit Jahren gefährlich schnell schlägt. Um mehr über ihre Kräfte und den Fluch zu erfahren, schreibt sie sich am M.U.S.E. ein, einem College für arkane Wesen. Doch trotz der Distanz, die nun zwischen ihnen liegt, können Hazel und Taro nicht gegen die Gefühle ankämpfen, die sie schon so lange empfinden, auch wenn sie dadurch Hazels Leben in Gefahr bringen ...', '28.03.2024', 'LYX', ARRAY['Deutsch']::text[], 480, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, NULL, 'M.U.S.E.', '{}', ARRAY['Hazel Birds','Taro Takahashi']::text[], '{}', '{}', 'af8e8235-82fa-5d66-95a5-4a9fc8def07a', '3', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('61c119b6-ddb7-5744-a01d-24d0fc778f79', :'owner', '089611f5-3e17-5e64-9955-1e84c6f52d63', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('9d84a475-df67-506e-841f-98f95f81f428', 'A Soul Untamed', NULL, '9783736321458', 'Als die wundervollste Nacht ihres Lebens, voller Küsse und zärtlicher Berührungen, Hazel Birds in Lebensgefahr bringt, hat sie nur einen Wunsch: den Fluch der Sirenen zu brechen, damit sie endlich mit Taro Takahashi zusammen sein kann. Vor lauter Verzweiflung vergräbt sie sich im M.U.S.E. Institute in Nachforschungen über den Ursprung ihres Fluches. Dabei stößt sie auf eine uralte Verschwörung, die alle arkanen Wesen bedroht. Und der geheime Orden, der die Fäden in der Hand hält, ist auf sie aufmerksam geworden. Nur gemeinsam haben Hazel und Taro eine Chance, die magische Gemeinschaft zu retten. Doch dafür müssen sie ihr Leben und ihre Liebe riskieren ...', '30.08.2024', 'LYX', ARRAY['Deutsch']::text[], 403, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, NULL, 'M.U.S.E.', '{}', ARRAY['Hazel Birds','Taro Takahashi']::text[], '{}', '{}', 'af8e8235-82fa-5d66-95a5-4a9fc8def07a', '4', ARRAY['Spin Off']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('20e0a2ed-3e5b-5ed6-81f9-5d64476191d5', :'owner', '9d84a475-df67-506e-841f-98f95f81f428', 'ungelesen'::reading_status, true, false, ARRAY['Digital']::text[], ARRAY['eBook']::text[], 'Normal', '{}', 999, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('b96f39b6-8578-5370-8a5f-f928743895e7', 'A Curse Unbroken', NULL, '9783736319844', 'Gemma Stone ist eine moderne Hexe, die in den sozialen Medien zeigt, wie man die Kräfte der Magie im Alltag nutzen kann. Eines Tages trifft sie den attraktiven und mysteriösen Darren, der dringend ihre Hilfe braucht: Er will endlich den Blutfluch brechen, der ihn daran hindert, gewisse brisante Informationen ans Licht zu bringen. Schon bei Gemmas und Darrens erster Begegnung fühlen sie eine beinahe magische Anziehungskraft, und je mehr Zeit sie miteinander verbringen, desto tiefer wird ihre Verbindung. Doch Darren hat ihr nicht die ganze Wahrheit über sich gesagt, und während Gemma versucht, den Fluch zu brechen, stößt sie auf seine dunklen Geheimnisse - Geheimnisse, die ihre Welt in Flammen aufgehen lassen könnten ...', '28.04.2023', 'LYX', ARRAY['Deutsch']::text[], 528, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Gemma Stone']::text[], '{}', '{}', 'af8e8235-82fa-5d66-95a5-4a9fc8def07a', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('575a9534-8c0f-5dd2-9cc2-9a3101eaf277', :'owner', 'b96f39b6-8578-5370-8a5f-f928743895e7', 'ungelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Paperback']::text[], 'Normal', '{}', 1600, true, true, '{}', '{}', NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ae1adeb8-d90f-5194-8e8b-21d7371fbfe6', 'A Spell Unbroken', NULL, '9783736319851', 'Niemals hätte die junge Hexe Gemma Stone geahnt, in welche Gefahr sie geraten würde, als sie Darren Hunter versprach, den Blutfluch zu brechen, mit dem er belegt wurde. Denn die Geheimnisse des schwarzmagischen Zirkels, auf die sie dabei stieß, trafen sie vollkommen unerwartet - genau wie die Gefühle, die Darren in ihr auslöst. Doch als sie der Anziehung nachgeben, merken sie bald, dass ihre Verbindung etwas ganz Besonderes ist. Sie sind bereit, für ihre Zukunft zu kämpfen, und spüren, dass sie nur gemeinsam einen Weg finden werden, das dunkle Unheil, das sie bedroht, noch abzuwenden - auch wenn die Schatten bereits Gemmas Namen flüstern ...', '29.09.2023', 'LYX', ARRAY['Deutsch']::text[], 488, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', ARRAY['Adventure']::text[], 'NA'::audience_kind, NULL, NULL, '{}', ARRAY['Gemma Stone']::text[], '{}', '{}', 'af8e8235-82fa-5d66-95a5-4a9fc8def07a', '2', '{}', 'sheet', :'owner') on conflict do nothing;
