insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('3b934790-72c8-5b2b-8455-43ac8070a250', 'Rosen & Champagner (Vol.1)', '장미와 샴페인', '9783989500051', 'Yiwon lebt in Russland, wo er sich als Anwalt sein Brot verdient. Bei der Arbeit an einem neuen Fall stellt sich heraus, dass die Mafia im Hintergrund ihre Finger im Spiel hat. So kommt es zu einem schicksalshaften Treffen mit Caesar, einem Mafiaboss, der von seinen Untergebenen auch „Zar“ genannt wird. Doch wider Erwarten lässt sich Yiwon von ihm nicht einschüchtern und geht direkt auf Konfrontation … was Caesars Interesse an dem schönen Ausländer weckt.', '15.07.2024', 'Papertoons', ARRAY['Deutsch']::text[], 280, NULL, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Russland', ARRAY['3P Objective']::text[], ARRAY['Yiwon','Caesar']::text[], ARRAY['Queer']::text[], '{}', '699bf959-0952-540e-bb9e-5001f170b5d6', '1', '{}', 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('44f189d7-f557-5d8d-90f1-1d3161b31cb3', :'owner', '3b934790-72c8-5b2b-8455-43ac8070a250', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1600, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'middle'::verdict_kind, 3.0, 'erfuellt'::expectation_kind, NULL, NULL, 'Ja, also mich nervt diese dauerhafte Antihaltung von Yiwon. Aber auch wie Caeasar einfach macht was er will.') on conflict do nothing;
insert into readings (id, user_book_id, user_id, read_number, started_on, finished_on, started_text, finished_text, days, abandoned, mode) values ('11b09466-3898-5946-b27d-45e095784fb7', '44f189d7-f557-5d8d-90f1-1d3161b31cb3', :'owner', 1, '2026-05-07', '2026-05-09', NULL, NULL, 3, false, NULL) on conflict do nothing;
insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('6a6aa398-0656-58f0-92e7-d3d80af9a1b7', 'Rosen & Champagner - Side Story (Vol.1)', '장미와 샴페인 - 외전', '9783989501348', 'Niemand bring Yiwon so sehr um den Verstand wie Caesar. Der Mafiaboss spricht zwar davon, sein Leben mit Yiwon verbringen zu wollen, und träumt sogar von Heirat – doch von Alltag kann kaum die Rede sein. Caesar ist ständig heiß auf Yiwon, so dass dieser nicht einmal mehr zum Arbeiten kommt. So geht es nicht weiter!\nVielleicht hilft es, aus dem Alltag auszubrechen. Ein Survival Game in der Wildnis und eine Prise tödliche Gefahr wären da doch genau das Richtige …', '14.04.2025', 'Papertoons', ARRAY['Deutsch']::text[], 256, 11, 'Manhwa'::book_kind, ARRAY['Fiction']::book_category[], 'Romance', ARRAY['Boys Love']::text[], 'NA'::audience_kind, 'Gegenwart'::time_period, 'Russland', ARRAY['3P Objective']::text[], ARRAY['Yiwon','Caesar']::text[], ARRAY['Queer']::text[], ARRAY['Dub-Con/Non-Con']::text[], '407442e2-757f-5f9c-8edf-2fd56b74ab3a', '1', ARRAY['Prequel']::text[], 'sheet', :'owner') on conflict do nothing;
insert into user_books (id, user_id, book_id, status, owned, bought, medium, format, edition, specials, price_cents, series_following, series_complete_owned, audio_platforms, narrators, duration_min, audio_verdict, adaptation_seen, company, verdict, rating, expectation, spice, burn, notes) values ('7ba3e8e0-70f4-567d-8954-9f69b0ba8cc9', :'owner', '6a6aa398-0656-58f0-92e7-d3d80af9a1b7', 'gelesen'::reading_status, true, false, ARRAY['Print']::text[], ARRAY['Taschenbuch']::text[], 'Normal', '{}', 1600, false, false, '{}', '{}', NULL, NULL, false, 'solo'::company_kind, 'middle'::verdict_kind, 2.5, 'untertroffen'::expectation_kind, 5, 'fast'::burn_kind, 'Ich verstehe einfach nicht warum Yiwon bei Ceasar bleibt, wenn er so offensichtlich ein Problem mit ihm hat. Oder warum er nicht zugibt, dass er ihn mag und dann Grenzen setzt. Klar... er hat Angst weil Ceacar ein Mafiaboss ist, aber das ist doch keine Grundlage. Leider nicht so meins. Das Ende war ganz cute, aber es hat mich gestört, dass diese Story eigentlich eine einzige Vergewaltigung war UND das Yiwon seine Gedanken NIE ausgesprochen hat.') on conflict do nothing;
