insert into books (id, title, original_title, isbn13, blurb, first_published, publisher, language, pages, chapters, kind, category, genre, subgenres, audience, period, setting, pov, main_characters, tropes, trigger_warnings, series_id, series_number, series_roles, metadata_source, created_by) values ('ec466887-a1b2-599d-884e-853746f7ba31', 'Der letzte Engel', NULL, '9783570154595', 'Motte ist sechzehn Jahre alt, als der Tod an seinem Fenster kratzt. An einem harmlosen Wochenende kurz nach Mitternacht bekommt er eine anonyme E-Mail: sorry für die schlechte Nachricht, aber wenn du aufwachst, wirst du tot sein. Wir wollten nur, dass du das weißt. Mieser Scherz, denkt Motte, wird aber dennoch ein wenig nervös und beschließt, die Nacht durchzumachen. Natürlich schläft er ein und natürlich wacht er auf - und fühlt sich wie immer. Bis darauf, dass sein Herz nicht mehr schlägt. Und dann sind da noch diese zwei Flügel auf seinem Rücken ...', '01.10.2012', 'cbj', ARRAY['Deutsch']::text[], 448, NULL, 'Buch'::book_kind, ARRAY['Fiction']::book_category[], 'Fantasy', '{}', 'Adult'::audience_kind, NULL, NULL, '{}', ARRAY['Motte']::text[], '{}', '{}', '84d6861b-7018-511b-8954-bfbf83ec526d', '1', '{}', 'sheet', :'owner') on conflict do nothing;
